// Renders the guide for the chosen type (or hides it when nothing is selected).
// Builds the explainer but does NOT show it. It is reference material — read
// once when you meet a type, then permanently in the way. It opens from the (i)
// beside the type picker instead, and the button hides itself for a type that
// has nothing to say.
function renderTypeGuide(type) {
  const box = document.getElementById('typeGuide');
  const btn = document.getElementById('typeGuideBtn');
  if (!box) return;
  const g = TYPE_GUIDE[type];
  closeTypeGuide();
  if (btn) btn.style.display = g ? '' : 'none';
  if (!g) { box.innerHTML = ''; return; }
  const chips = g.wcag.map(([num, name]) =>
    `<a class="wcag-link" target="_blank" rel="noopener"
        href="https://www.w3.org/WAI/WCAG22/Understanding/${encodeURIComponent(name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''))}.html"
        title="Open the WCAG explanation for ${escapeHtml(name)}">WCAG ${escapeHtml(num)} ${escapeHtml(name)}</a>`).join('');
  const apg = g.apg
    ? `<a class="wcag-link apg" target="_blank" rel="noopener"
         href="https://www.w3.org/WAI/ARIA/apg/patterns/${g.apg}/"
         title="The official W3C keyboard/ARIA pattern for this component">📖 ARIA pattern</a>` : '';
  box.style.display = 'block';
  const variants = (g.variants || []).map(([kind, note]) =>
    `<li><span class="tg-v-kind">${escapeHtml(kind)}</span><span class="tg-v-note">${escapeHtml(note)}</span></li>`).join('');
  box.innerHTML =
    `<div class="tg-what">${escapeHtml(g.what)}</div>` +
    `<div class="tg-keys"><strong>Keyboard:</strong> ${escapeHtml(g.keys)}</div>` +
    (variants ? `<details class="tg-variants"><summary>Which kind is it? (${g.variants.length})</summary><ul>${variants}</ul></details>` : '') +
    `<div class="tg-links">${chips}${apg}</div>`;
}

function closeTypeGuide() {
  const box = document.getElementById('typeGuide');
  const btn = document.getElementById('typeGuideBtn');
  if (box) box.style.display = 'none';
  if (btn) btn.setAttribute('aria-expanded', 'false');
}

document.getElementById('typeGuideBtn')?.addEventListener('click', (e) => {
  e.preventDefault();
  const box = document.getElementById('typeGuide');
  const btn = document.getElementById('typeGuideBtn');
  if (!box || !box.innerHTML) return;
  const open = box.style.display !== 'none';
  box.style.display = open ? 'none' : 'block';
  btn.setAttribute('aria-expanded', String(!open));
});

// Click-away and Escape. A panel this narrow cannot afford a popover that needs
// hunting for its own close button.
document.addEventListener('click', (e) => {
  if (e.target.closest('#typeGuide') || e.target.closest('#typeGuideBtn')) return;
  closeTypeGuide();
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') closeTypeGuide();
});

// Currently built template (set by Generate, consumed by Apply / Add to Mapping)
let currentTemplate = null;
let mappingsFilter = 'onpage'; // 'onpage' | 'all' | 'review' — MAPPINGS list filter toggle
// Set from outside the toolbar too: the end of an autonomous AI run lands on
// the "To review" view, since going over what it built is the next thing.
let setMappingsFilter = (mode) => { mappingsFilter = mode; };
(function wireMappingsFilter() {
  const btns = {
    onpage: document.getElementById('filterOnPage'),
    all: document.getElementById('filterAll'),
    review: document.getElementById('filterToReview'),
  };
  if (!btns.onpage || !btns.all) return;
  const set = (mode) => {
    mappingsFilter = mode;
    for (const [k, b] of Object.entries(btns)) {
      if (!b) continue;
      b.classList.toggle('active', k === mode); b.setAttribute('aria-selected', String(k === mode));
    }
    loadMappingsList();
  };
  for (const [k, b] of Object.entries(btns)) if (b) b.addEventListener('click', () => set(k));
  setMappingsFilter = set;
})();
// When editing an existing mapping, its key — so "Add to Mapping" replaces it.
let editingMappingKey = null;

$componentType.addEventListener('change', () => {
  const type = $componentType.value;
  renderTypeGuide(type); // explain the component + its WCAG criteria straight away
  if (!type) {
    $subSelSection.style.display = 'none';
    $previewSection.style.display = 'none';
    return;
  }
  renderSubSelectorInputs(type);
});

// Plain-language guidance for the TOP "CSS Selector" field, per component. The
// terse doc wording ("the container") isn't enough on its own, so each entry
// explains what element to point at and gives a concrete example selector that
// also becomes the input placeholder.
const PRIMARY_HELP = {
  'hide-element': { help:'The element to take out of the tab order and the accessibility tree. Every match is handled; mouse clicks keep working.', ex:'.navbar-brand' },
  'focus-order':  { help:'The container whose tab order is wrong. Then list the elements inside it, in the right order, in the field below.', ex:'.hero' },
  button:     { help:'The clickable button element itself (the thing that has the click event).', ex:'.test-btn' },
  link:       { help:'The element that behaves like a link (has the click/navigation event).', ex:'.accessibility-link' },
  menu:       { help:'The outermost <ul>/<nav> that wraps the whole menu (not a single item).', ex:'#main-menu' },
  accordion:  { help:'The clickable section header/button that expands & collapses the panel.', ex:'.accordion-btn' },
  carousel:   { help:'Each slide element (U1 waits for a slide to appear). The wrapper goes in "carouselContainer".', ex:'.slide' },
  datepicker: { help:'The calendar popup that holds the days grid and the prev/next buttons — NOT the input or the 📅 icon (that is the "trigger").', ex:'.datepicker-container' },
  dialog:     { help:'The modal/pop-up box that opens up (the panel that appears). The button that opens it goes in "trigger".', ex:'#login-modal' },
  listbox:    { help:'The options list container — the <ul> that holds the options (this gets role="listbox"). The button that opens it goes in "trigger".', ex:'#listbox-list' },
  combobox:   { help:'The wrapper around the input. If there is none, use the input itself.', ex:'.combobox-container' },
  checkbox:   { help:'The checkbox element that carries the click event.', ex:'.checkbox' },
  radio:      { help:'The container that wraps the whole radio group.', ex:'.radio-group' },
  tabs:       { help:'The <ul>/row that holds the tab buttons (the tab list).', ex:'.tabs-list' },
  form:       { help:'The <form> (or the element wrapping all the fields & the submit button).', ex:'.form-container' },
  table:      { help:'The table container (the element wrapping all rows & cells).', ex:'.data-table' },
  grid:       { help:'The interactive grid container (wrapping all rows & cells).', ex:'.grid-table' },
  pagination: { help:'The container that wraps the results AND the page buttons.', ex:'.pagination-container' },
  loading:    { help:'The loading indicator element — when it appears, the loading state is announced.', ex:'.loading' },
  tooltip:    { help:'The tooltip text/content element that appears.', ex:'.tooltip' },
};

// The selector key that carries the PRIMARY placeholder (i.e. the main CSS
// selector the user types at the top). Used to show its doc hint on that input.
function primaryKeyOf(schema) {
  for (const k of Object.keys(schema.selectors)) {
    if (schema.selectors[k] === 'PRIMARY') return k;
  }
  return null;
}

// Renders the selector rows for a component type.
//
// `into` lets an AI mapping card host its own copy of the exact same form, so
// the two modes cannot drift apart: same markup, same hints, same required
// markers, same 🔍 testers, same strength badges. With `append` the container's
// existing content is kept (the card puts its primary row in first), and the
// shared primary label/hint at the top of the tab is left alone.
function renderSubSelectorInputs(type, into, opts) {
  const schema = COMPONENT_SCHEMAS[type];
  if (!schema) return;
  const $subSelArea = into || document.getElementById('subSelectorsArea');
  const scoped = !!into;
  if (!(opts && opts.append)) $subSelArea.innerHTML = '';

  const req = schema.req || [];
  const desc = schema.desc || {};
  const labels = schema.labels || {};
  const labelOf = (k) => labels[k] || k;

  // Primary selector hint: show the doc description for the PRIMARY key, plus
  // whether the main selector is required.
  const pKey = primaryKeyOf(schema);

  // Rename the top label to the actual selector this field maps to, so it's
  // obvious the CSS Selector is e.g. the "listbox" (the <ul>), not the trigger.
  // Scoped renders (an AI card) own no shared header, so they skip all of this.
  const primaryLabel = scoped ? null : document.getElementById('primaryLabel');
  if (primaryLabel) {
    primaryLabel.textContent = pKey ? `CSS Selector — ${labelOf(pKey)}` : 'CSS Selector';
  }

  // Friendly, plain-language help + example for the primary field.
  const helpInfo = PRIMARY_HELP[type];
  if (!scoped && helpInfo && helpInfo.ex && $primarySelectorInput) {
    $primarySelectorInput.placeholder = 'e.g. ' + helpInfo.ex;
  }

  const primaryHint = scoped ? null : document.getElementById('primaryHint');
  if (primaryHint) {
    // Prefer the plain-language explanation; fall back to the terse doc text.
    const howPrimary = pKey ? (FIELD_HOW[type] || {})[pKey] : '';
    const body = ((helpInfo && helpInfo.help) || (pKey && desc[pKey]) || '') +
                 (howPrimary ? '\n' + howPrimary : '');
    if (body) {
      const reqTag = (pKey && req.includes(pKey)) ? '★ required — ' : '';
      const exTag = (helpInfo && helpInfo.ex) ? `\nExample: ${helpInfo.ex}` : '';
      primaryHint.textContent = reqTag + body + exTag;
      primaryHint.style.whiteSpace = 'pre-line';
      primaryHint.style.display = '';
    } else {
      primaryHint.textContent = '';
      primaryHint.style.display = 'none';
    }
  }

  // Manual fields — each with a required marker and an on-focus description bubble.
  const howFor = FIELD_HOW[type] || {};
  for (const f of schema.fields) {
    const isReq = req.includes(f);
    const hint = desc[f] || '';
    // Two different questions, so two lines: `desc` is what the field IS, in
    // U1's words; `how` is which element on this page it is, in ours. The
    // second is the one that was missing, and the one mappings go wrong for
    // want of.
    const how = howFor[f] || '';
    const row = document.createElement('div');
    row.className = 'sub-sel-row';
    row.innerHTML = `
      <div class="key">${escapeHtml(labelOf(f))}${isReq ? ' <span class="req-star" title="required">*</span>' : ''}</div>
      <span class="sel-strength-wrap">
        <input type="text" data-field="${escapeHtml(f)}" placeholder="${isReq ? 'required' : 'optional'}">
        <span class="sel-strength" data-level="empty" aria-hidden="true"></span>
      </span>
      <button class="btn-ghost btn-xs sel-test" title="Test selector on page">🔍</button>
      ${hint ? `<div class="input-hint">${escapeHtml(hint)}</div>` : ''}
      ${how ? `<div class="input-hint how-hint">${escapeHtml(how)}</div>` : ''}
    `;
    $subSelArea.appendChild(row);
  }

  // Root fields (options)
  if (schema.rootFields) {
    for (const [k, schemaDefault] of Object.entries(schema.rootFields)) {
      // A default that is a sentence spoken to the visitor has to be in the
      // visitor's language, and only the site knows which that is.
      let defaultVal = schemaDefault;
      if (type === 'link-list' && (k === 'fileWord' || k === 'newTabWord')) {
        const w = linkNoteWords();
        defaultVal = k === 'fileWord' ? w.file : w.tab;
      }
      const hint = desc[k] || '';
      if (typeof defaultVal === 'boolean') {
        const row = document.createElement('label');
        row.className = 'root-toggle';
        row.innerHTML = `
          <input type="checkbox" data-root="${escapeHtml(k)}" ${defaultVal ? 'checked' : ''}>
          <span><strong>${escapeHtml(labelOf(k))}</strong> (option)</span>
          ${hint ? `<div class="input-hint">${escapeHtml(hint)}</div>` : ''}
        `;
        $subSelArea.appendChild(row);
      } else {
        const row = document.createElement('div');
        const isSelRoot = (schema.selectorRoots || []).includes(k);
        const choices = (schema.options && schema.options[k]) || null;
        // A selector needs the whole width — it holds things like
        // 'input[type="checkbox"].toggle' and a 110px label column plus a
        // strength badge leaves a box too small to read what you typed.
        // Dropdowns stack too: their option text is a sentence, and a <select>
        // clips rather than wraps, so a narrow column hides the choice you made.
        row.className = (isSelRoot || choices) ? 'root-text root-wide' : 'root-text';
        const ph = (schema.placeholders && schema.placeholders[k]) || '';
        // A closed set of valid values is a dropdown. Typed free-text here only
        // ever produced silent typos — "checkbox " or "Checkbox" fell through to
        // the fallback role with nothing to say it had.
        const inputHtml = choices
          ? `<select data-root="${escapeHtml(k)}">` + choices.map(c => {
              const val = typeof c === 'string' ? c : c.value;
              const txt = typeof c === 'string' ? c : c.text;
              return `<option value="${escapeHtml(val)}"${val === String(defaultVal || '') ? ' selected' : ''}>${escapeHtml(txt)}</option>`;
            }).join('') + `</select>`
          : `<input type="text" data-root="${escapeHtml(k)}" value="${escapeHtml(String(defaultVal || ''))}"` +
            (ph ? ` placeholder="${escapeHtml(ph)}"` : '') + `>`;
        // A root field the schema requires (aria-label's heading) is not an
        // option, and saying "(option)" on it was read as exactly that.
        const rootTag = req.includes(k) ? '★ required' : '(option)';
        row.innerHTML = `
          <label>${escapeHtml(labelOf(k))} <span class="root-tag">${rootTag}</span></label>
          ${isSelRoot
            ? `<div class="selector-test-row"><span class="sel-strength-wrap">${inputHtml}<span class="sel-strength" data-level="empty" aria-hidden="true"></span></span><button class="btn-ghost btn-xs sel-test" title="Test selector on page">🔍</button></div>`
            : inputHtml}
          ${hint ? `<div class="input-hint">${escapeHtml(hint)}</div>` : ''}
        `;
        $subSelArea.appendChild(row);
      }
    }
  }

  if (scoped) return;   // an AI card manages its own visibility and grading
  $subSelSection.style.display = 'block';
  $previewSection.style.display = 'none';
  refreshStrength();
  // The heading is required and the page knows which one it is.
  if (type === 'aria-label') autofillAriaLabelHeading();
}

/**
 * Fill aria-label's heading field from the page.
 *
 * The field is required, and it was arriving empty on a picked "Learn more"
 * link — the one case where the answer is fully determined: the target is
 * known, its card is right there, and cardHeadingFor finds the heading the
 * same way the AI route does. Typing it by hand meant opening devtools to
 * read a selector the tool had already computed for the AI card.
 *
 * Runs when the type becomes aria-label and when the element selector
 * changes. A value already typed is left alone unless `force`.
 */
let ariaHeadingFillTimer = null;
async function autofillAriaLabelHeading(force) {
  if ($componentType.value !== 'aria-label') return;
  const primary = ($primarySelectorInput.value || '').trim();
  const inp = $subSelArea.querySelector('[data-root="headingSelector"]');
  if (!inp || !primary) return;
  if (inp.value.trim() && !force) return;
  const hint = inp.closest('.root-text')?.querySelector('.input-hint');
  const say = (text, bad) => {
    if (!hint) return;
    let line = hint.querySelector('.autofill-note');
    if (!line) { line = document.createElement('div'); line.className = 'autofill-note'; hint.appendChild(line); }
    line.textContent = text;
    line.style.color = bad ? 'var(--u1-warn, #d97706)' : 'var(--u1-success, #22c55e)';
  };
  try {
    const tab = await getTab();
    if (!isInjectable(tab)) return;
    const r = await inPage(tab.id, (s) => {
      const S = window.__u1SelectorIntel;
      return S && S.cardHeadingFor ? S.cardHeadingFor(s) : null;
    }, [primary]);
    if (!r) return;
    if (r.heading) {
      inp.value = r.heading;
      inp.dispatchEvent(new Event('input', { bubbles: true }));
      say(`Filled from the page — the heading beside ${r.cards === 1 ? 'this element' : `each of the ${r.cards} matches`}` +
          (r.example ? `, e.g. “${r.example}”` : '') + '. Change it if it is the wrong one.');
      refreshStrength();
    } else if (r.found) {
      say(`Found a heading beside ${r.found} of ${r.cards}, but no single selector reaches all of them — point at it by hand.`, true);
    } else {
      say('No heading found near this element on the page — point at the card\'s heading by hand.', true);
    }
  } catch { /* the page went away; the field stays as it is */ }
}

// The element selector changed under an aria-label form: the heading belongs
// to THAT element, so it is looked up again. Debounced — typing a selector
// character by character must not ask the page on every keystroke.
$primarySelectorInput.addEventListener('input', () => {
  if ($componentType.value !== 'aria-label') return;
  clearTimeout(ariaHeadingFillTimer);
  ariaHeadingFillTimer = setTimeout(() => autofillAriaLabelHeading(true), 500);
});

// ─────────────────────────────────────────────────────────────────────────────
//  Selector strength meter
//  Every selector input carries a live Weak / Medium / Strong badge so a fragile
//  mapping (bare tag, utility class, generated id, 0 or many matches) is obvious
//  while it is being typed — not after it breaks in production.
// ─────────────────────────────────────────────────────────────────────────────

// Some components are built ONLY when the widget opens (the datepicker popup,
// the dialog body), so 0 matches on those inner selectors is expected, not a
// fault. Keyed by type → the selector keys that MUST match even while closed.
const DYNAMIC_OPEN = {
  datepicker: ['trigger'],
  dialog: ['trigger'],
  combobox: ['trigger', 'input'],
  'keyboard-grid': [], // container + cell are created only when the widget opens
};

// The SHAPE each component has to have, checked against the live page.
//
// Match counts prove every field found something; they cannot prove the fields
// found the right things. A listbox mapped with the trigger button as its
// `listbox` passes every count check and is nonsense — and one did: it was
// generated, previewed, approved and saved without a single step objecting,
// because nothing anywhere asked whether the options were inside the list.
//
// `inside: true`  — the child elements must live within the parent, because
//                   that is where U1 looks for them.
// `inside: false` — they must NOT, because nesting them breaks the widget.
// Types where a child selector reaching outside its parent is FATAL rather than
// partial. These are the ones u1-patch wraps with a context resolver: to reach
// one part it widens the context, widening picks up the strays, and the
// component is refused outright. Everywhere else the extra matches are simply
// ignored, which is the "partial" the message used to promise for everyone.
const FATAL_IF_WIDE = ['tabs'];

const STRUCTURE_RULES = {
  // The listbox is the thing that OPENS. The trigger is outside it — a button
  // that contained the list it opens would disappear along with it.
  listbox:  [{ parent: 'listbox', child: 'options', inside: true },
             { parent: 'listbox', child: 'trigger', inside: false }],
  combobox: [{ parent: 'listbox', child: 'options', inside: true }],
  menu:     [{ parent: 'menu',    child: 'items',   inside: true }],
  // A tab strip holds the tabs; the panels sit outside it. Pointing both at one
  // element makes U1 hide the tabs along with the content they control.
  tabs:     [{ parent: 'tabList', child: 'tab',       inside: true },
             { parent: 'tabList', child: 'tabPanel',  inside: false }],
  table:    [{ parent: 'table',   child: 'row',     inside: true },
             { parent: 'table',   child: 'cell',    inside: true }],
  grid:     [{ parent: 'grid',    child: 'row',     inside: true },
             { parent: 'grid',    child: 'cell',    inside: true }],
  accordion:[{ parent: 'headerSelector', child: 'contentSelector', inside: false }],
  // A radioButton selector reaching outside its group is the same fault as a
  // tab reaching outside its list, and radio had no rule at all — so nothing
  // reported it and nothing narrowed it.
  radio:    [{ parent: 'radioGroup', child: 'radioButton', inside: true }],
};

/**
 * Narrow a child selector so it only matches inside its parent.
 *
 * STRUCTURE_RULES has always known which fields must live inside which — it
 * just reported it. For `tabs` that reporting was worse than useless: a `tab`
 * selector matching outside the tabList makes P.contextRoot.tabs refuse the
 * strip, u1.fix.tabs is never called at all, and the panel said "U1 will only
 * decorate the ones inside it", which is the opposite of what happens.
 *
 * So: fix the selector instead of describing the problem. `.tab-bar__btn`
 * matching eleven elements, six of them in #dealTabs, becomes
 * `#dealTabs>.tab-bar__btn`.
 *
 * A DESCENDANT combinator would be the obvious move and it is not available:
 * isU1ValidSelector splits on [>+~] and rejects a compound containing a space,
 * so `#dealTabs .tab-bar__btn` is invalid to U1 while `#dealTabs>.tab-bar__btn`
 * is fine. Every candidate is therefore checked against that validator before
 * it is written, and a field with no valid narrowing is left alone and
 * reported rather than quietly mangled.
 *
 * Returns [{ field, from, to, was, now }] — empty when nothing needed it.
 */
async function narrowContained(tpl) {
  const rules = STRUCTURE_RULES[tpl && tpl.type] || [];
  const sels = (tpl && tpl.config && tpl.config.selectors) || {};
  const jobs = rules
    .filter((r) => r.inside && sels[r.parent] && sels[r.child])
    .map((r) => ({ field: r.child, parentSel: sels[r.parent], childSel: sels[r.child] }));
  if (!jobs.length) return [];

  const tab = await getTab();
  if (!isInjectable(tab)) return [];

  let found;
  try {
    found = await inPage(tab.id, (list) => {
      const out = [];
      for (const job of list) {
        let parent = null, kids = [];
        try {
          parent = document.querySelector(job.parentSel);
          kids = Array.from(document.querySelectorAll(job.childSel));
        } catch { continue; }
        if (!parent || !kids.length) continue;
        const inside = kids.filter((el) => parent.contains(el) && el !== parent);
        // Nothing outside, or nothing inside — neither is this function's job.
        // "None inside" is a wrong selector, not a wide one, and narrowing it
        // would turn a loud error into a silent no-match.
        if (inside.length === kids.length || !inside.length) continue;
        const scoped = window.__u1SelectorIntel.commonSelectorFor(parent, inside, job.parentSel);
        out.push({
          field: job.field,
          was: job.childSel,
          outside: kids.length - inside.length,
          total: kids.length,
          now: scoped && scoped.selector ? scoped.selector : null,
        });
      }
      return out;
    }, [jobs]);
  } catch { return []; }

  const done = [];
  for (const f of found || []) {
    if (!f.now || f.now === f.was) continue;
    if (!isU1ValidSelector(f.now)) continue;   // rather leave it than mangle it
    setDeep(tpl.config.selectors, f.field, f.now);
    done.push(f);
  }
  if (done.length) tpl.code = mappingToCode(tpl);
  return done;
}

// Which build is actually running.
//
// "I loaded the new version" and "the browser is running the new version" are
// different claims, and for several rounds of this project there was no way to
// tell them apart from inside the panel — a fix would ship, the symptom would
// persist, and both of us would be reasoning about code that was not there.
// The manifest version rarely changes; the commit does.
async function showBuildStamp() {
  const el = document.getElementById('buildStamp');
  if (!el) return;
  try {
    const mf = chrome.runtime.getManifest();
    const stamp = (mf.version_name || mf.version || '').trim();
    el.textContent = 'v' + stamp;
    // A trailing + means the package was built from a tree with uncommitted
    // changes, so the commit named is the last one COMMITTED and not
    // necessarily what is running. Worth spelling out: the stamp exists to
    // answer "which build is this", and a reader who cannot decode it is back
    // where they started.
    el.title = `Extension ${stamp}.` +
      (/\+\)?$/.test(stamp) ? ' The + means it was built from a tree with uncommitted changes, so the commit shown is the last one committed rather than exactly what is running.' : '') +
      ` If a fix looks missing, check this first: chrome://extensions → Remove → Load unpacked. ` +
      `The Errors panel there keeps old entries until you press Clear all, so an error listed ` +
      `is not proof of an error happening.`;
  } catch {}
}
showBuildStamp();

// ─────────────────────────────────────────────────────────────────────────────
//  Saying what things are, screen by screen
// ─────────────────────────────────────────────────────────────────────────────
//
// The run stops on each section with every candidate numbered on the page,
// and you say what they are. Two things make this worth the interruption.
//
// It is FREE. buildTemplate → saveMappingEntry → applyMappingsBatch is already
// a local pipeline; the only thing the model contributes is the sub-field
// selectors, and describeComponent measures those instead. Name everything on a
// section and that section costs nothing.
//
// And it accepts a GROUP. The collector sees six .tab-bar__btn as six buttons —
// which is correct, they are buttons — and the component is the strip they
// form. There is no single candidate to label, so labelling one at a time could
// never have described it. That strip is the one the model failed to identify.
//
// `on` is no longer a setting. Naming a component costs no model call and no
// money, and a section named in full is never charged for — there was no
// version of "off" worth offering, and the checkbox was one more thing to have
// forgotten to tick before paying for a scan.
const sweepLabel = { on: false, resolve: null, marks: new Set(), busy: false, skip: false };

/**
 * The candidates a section's naming pause is working with, by section number.
 *
 * Deliberately NOT on the stop. A stop is persisted to chrome.storage and
 * pushed to the server, and hanging a list of up to 250 candidates off it made
 * a twenty-one section survey 771KB against a 99KB limit — the scan finished
 * and then failed to upload. This is scratch for a pause that is open now.
 */
const sweepCands = new Map();

/**
 * A signal that the element is ALREADY a real control.
 *
 * clickSignals reports everything it can see, and the list mixes two very
 * different findings: `<button>` and `role=link` mean the browser already gives
 * this thing focus and a name, while `onclick`, `cursor:pointer` and
 * `tabindex=-1` mean somebody hung behaviour on a <div>. Only the second group
 * is work. Telling them apart is what turns 121 rows of mostly ordinary links
 * into the handful that actually fail a keyboard.
 */
const NATIVE_SIGNAL =
  /^<(button|a href|input|select|textarea|summary)>$|^role=(button|link|menuitem|menuitemcheckbox|menuitemradio|tab|checkbox|switch|option)$/;

/**
 * Hold the run after each section, so its components can be built before the
 * next one is read.
 *
 * Ticking all twenty-three sections used to mean thirty-five minutes and $14
 * before the components view was reached even once — the loop only set
 * phase='components' after it had finished every section. The components from
 * section 1 were sitting in aiSweep.stops four minutes in and there was no way
 * to get at them short of stopping the run.
 *
 * `resolve` non-null IS the paused state: it is what the continue button calls,
 * what the stop button has to call so the run does not sit waiting for a
 * decision nobody is going to make, and what lets the make-accessible button
 * through its `aiSweep.running` guard.
 */
// Owner decision (2026-09-02): the run does NOT stop by default — one
// section or nine, the flow is "make it accessible and hand me mappings".
// Stop-at-each-section stays one tick away for a supervised run.
const sweepPause = { on: false, resolve: null };

/**
 * Stop after a section, show what it found, and wait to be told to carry on.
 *
 * Resolves { stopped:boolean }. The components view is the existing one —
 * nothing here duplicates it, because the whole point is that the fixes are
 * built by the same button, with the same ticks and the same review, as they
 * are when the run has ended.
 */
function pauseForFixes(stop, left) {
  const host = document.getElementById('sweepResume');
  if (!host) return Promise.resolve({ stopped: false });

  clearSweepBusy();          // the run is not working, it is waiting for you
  aiSweep.phase = 'components';
  renderSweepPicks();        // draws the ticks; this banner sits above them

  const k = stop.found.filter((f) => !f.done).length;
  host.style.display = '';
  host.innerHTML = `
    <div class="sweep-resume-head">Section ${stop.n} found ${k} component${k === 1 ? '' : 's'}.</div>
    <div class="sweep-resume-sub">Build the fixes for them now, then continue —
      ${left} section${left === 1 ? '' : 's'} still to read. Nothing is charged while this waits.</div>
    <div class="sweep-resume-btns">
      <button class="btn-primary btn-sm" id="sweepResumeGo">Build these ${k} and continue →</button>
      <button class="btn-outline btn-sm" id="sweepResumeSkip">Skip — carry on without building</button>
      <button class="btn-ghost btn-sm" id="sweepResumeStop">Stop the run here</button>
      <label class="sweep-resume-auto"><input type="checkbox" id="sweepResumeAuto">
        Do not stop again — read the rest straight through</label>
    </div>`;

  return new Promise((resolve) => {
    const finish = (out) => {
      sweepPause.resolve = null;
      host.onclick = null;
      host.style.display = 'none';
      host.innerHTML = '';
      resolve(out);
    };
    // Held here so the stop button can end the wait too. Without it, pressing
    // Stop set aiSweep.abort and then span for sixty seconds waiting on a
    // aiSweep.running that only this promise could clear.
    sweepPause.resolve = finish;
    host.onclick = async (e) => {
      if (e.target.closest('#sweepResumeAuto')) { sweepPause.on = !e.target.checked; return; }
      if (e.target.closest('#sweepResumeStop')) { aiSweep.abort = true; finish({ stopped: true }); return; }
      if (e.target.closest('#sweepResumeSkip')) { finish({ stopped: false }); return; }
      // The primary action BUILDS, then carries on. It used to only carry on,
      // with building left to a separate button in the list — so the obvious
      // press moved the run forward and made nothing, and the drawer ended up
      // reading "8 components found" beside "No mappings yet".
      const go = e.target.closest('#sweepResumeGo');
      if (go) {
        const label = go.textContent;
        go.disabled = true;
        go.textContent = 'Building…';
        try { await buildPickedComponents(); }
        catch (err) { showNotice(document.getElementById('sweepPicksStatus'),
          'Could not build them: ' + err.message, 'error', 9000); }
        finally { go.disabled = false; go.textContent = label; }
        finish({ stopped: false });
      }
    };
  });
}

/**
 * Every component a person named, in the corpus's own shape.
 *
 * Local and private (`__`), because it is evidence rather than site
 * configuration: it belongs to whoever is building the detector, not to the
 * client's site, and it must never travel in a project export.
 */
const LABELS_KEY = (U1Store.PRIVATE_PREFIX || '__') + 'labels';

async function rememberLabel(entry) {
  try {
    const got = await U1Store.get([LABELS_KEY]);
    const list = got[LABELS_KEY] || [];
    // One per root per type — naming the same thing twice is a correction, not
    // a second example.
    const at = list.findIndex((x) => x.root === entry.root && x.type === entry.type);
    if (at >= 0) list[at] = { ...list[at], ...entry, at: Date.now() };
    else list.push({ ...entry, at: Date.now() });
    await U1Store.set({ [LABELS_KEY]: list.slice(-500) });
  } catch {}
}

// Pulling this out of chrome.storage is a developer action, not a client
// deliverable — it never belonged on the Whole-page results screen next to
// what a client actually presses. Reachable from this panel's own DevTools
// console (right-click the panel → Inspect, or "service worker" → panel's
// document) by calling exportNamedLabels() there, rather than a button that
// sat on screen for everyone else.
async function exportNamedLabels() {
  const got = await U1Store.get([LABELS_KEY]);
  const list = got[LABELS_KEY] || [];
  if (!list.length) {
    console.log('Nothing named yet. Turn on "let me say what things are" and name something.');
    return;
  }
  // The shape verify-detect reads, field for field.
  const doc = {
    url: list[0].url || currentHostname,
    note: [
      'Written by naming components in the panel while looking at the page —',
      'not by running the tool and blessing what it found. That distinction is',
      'the whole value of this file: a corpus built from the tool\'s own output',
      'can only ever score 100%.',
    ],
    components: list.map((l) => {
      const c = { type: l.type, root: l.root, why: l.why };
      if (l.fields && Object.keys(l.fields).length) c.fields = l.fields;
      if (l.matches > 1) c.matches = l.matches;
      return c;
    }),
  };
  const blob = new Blob([JSON.stringify(doc, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${currentHostname || 'site'}.labels.json`;
  a.click();
  console.log(`${list.length} named component${list.length === 1 ? '' : 's'} exported. ` +
    'Drop it in fixtures/ and verify-detect will score against it from then on.');
}
window.exportNamedLabels = exportNamedLabels;

/** Types worth offering. Everything the builder can actually create. */
const LABEL_TYPES = () => Object.keys(COMPONENT_SCHEMAS);

/**
 * A picture of ONE element, cut out of the section screenshot already in hand.
 *
 * The sections list answers "which part of the page is this" with a photograph,
 * and that is the only thing in the tool that makes a row and a place on the
 * page the same object in your head. A row in the labelling list had no such
 * thing — hovering it drew an outline on the real page, which means looking
 * away from the panel, and scrolled that page to do it.
 *
 * Nothing is captured here. `shot` was taken for the model a moment ago, `box`
 * came back with the candidate, and the only work is a crop — so a preview
 * costs nothing and cannot fail on a page that has since moved.
 */
function elementCrop(shot, viewport, box, img) {
  if (!shot || !viewport || !box || !box.w || !box.h || !img || !img.naturalWidth) return '';
  // `box` is in CSS pixels; the shot was captured at the device ratio and then
  // scaled to a fixed width. One factor relates them.
  const k = img.naturalWidth / viewport.w;
  // A crop tight to the element is unreadable out of context — a bare button on
  // a bare background. A margin of its own size, clamped, puts it back on the
  // page it lives on.
  const pad = Math.max(24, Math.min(90, Math.round(box.h * 0.8)));
  const x = Math.max(0, Math.round((box.x - pad) * k));
  const y = Math.max(0, Math.round((box.y - pad) * k));
  const w = Math.min(img.naturalWidth - x, Math.round((box.w + pad * 2) * k));
  const h = Math.min(img.naturalHeight - y, Math.round((box.h + pad * 2) * k));
  if (w <= 0 || h <= 0) return '';
  const cv = document.createElement('canvas');
  cv.width = w; cv.height = h;
  const cx = cv.getContext('2d');
  cx.drawImage(img, x, y, w, h, 0, 0, w, h);
  // The element itself, ringed in the same pink the on-page marks use — the
  // crop alone does not say WHICH of the six things in it you are pointing at.
  cx.strokeStyle = '#ff2d95';
  cx.lineWidth = Math.max(2, Math.round(2 * k));
  cx.strokeRect(
    Math.round((box.x * k) - x), Math.round((box.y * k) - y),
    Math.round(box.w * k), Math.round(box.h * k));
  try { return cv.toDataURL('image/jpeg', 0.8); } catch { return ''; }
}

/**
 * Stop, show what is on this section, and wait.
 * Resolves { labelled:[], done:boolean, stopped:boolean }.
 */
function labelScreen(stop, collected, tab) {
  // The list drops out of the section's own row, not out of a panel above it.
  //
  // A section and the components on it are one thing at two levels, and putting
  // the second in a separate box at the top of the tab broke that: you were
  // reading about "Section 1" in a panel that had no visual connection to the
  // Section 1 row a few inches below, still sitting in the list with its own
  // thumbnail. Now the row opens and the components are inside it.
  //
  // The standalone host stays as the fallback for the case where the row is not
  // on screen — a restored survey, or a phase that is not showing the list.
  const fallback = document.getElementById('sweepLabel');
  const screenRow = document.querySelector(`#sweepPicksList .sweep-screen[data-screen="${stop.n}"]`);
  let host = fallback;
  let drop = null;
  if (screenRow) {
    drop = document.createElement('div');
    drop.className = 'lbl-drop';
    screenRow.insertAdjacentElement('afterend', drop);
    screenRow.classList.add('is-open');
    host = drop;
    host.style.display = '';
    // The row can be anywhere in a list of twenty-three, and the run just
    // scrolled the PAGE to it — the panel has no idea. Bring it into view.
    try { screenRow.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch {}

    // Everything else folds away while this one is open.
    //
    // The section being worked on is a few hundred pixels of list, and the
    // twenty-two sections queued behind it are several thousand more — so the
    // components you are deciding about, and the button that builds them, sat
    // in a thin band with the rest of the run scrolling past underneath. They
    // are not gone: the fold says how many and opens on a click.
    const list = document.getElementById('sweepPicksList');
    const others = list
      ? [...list.querySelectorAll('.sweep-screen')].filter((x) => x !== screenRow).length
      : 0;
    if (list && others) {
      list.classList.add('lbl-focus');
      const bar = document.createElement('details');
      bar.className = 'sweep-others';
      bar.innerHTML = `<summary>${others} other section${others === 1 ? '' : 's'} — ` +
        `hidden while this one is open</summary>`;
      bar.addEventListener('toggle', () => list.classList.toggle('lbl-focus', !bar.open));
      // At the BOTTOM. Above the list it sat between you and the section you
      // are working on, and read as a header for it.
      list.appendChild(bar);
    }
  }
  if (!host) return Promise.resolve({ labelled: [], done: false });

  sweepLabel.marks = new Set();
  const made = [];
  const cands = collected.candidates || [];
  // Held in memory, keyed by section — NOT on the stop.
  //
  // Putting it on the stop threaded it straight into everything the stop is
  // part of: chrome.storage, and the survey body pushed to the server. A
  // candidate is ~376 bytes and a section can hold 250 of them, so a
  // twenty-one section run turned a 52KB body into three quarters of a
  // megabyte and the upload came back 413 — "saved on this machine but did not
  // reach the server", on a scan that had just worked perfectly.
  //
  // It is scratch for the pause that is open right now. It has no business
  // outliving the session, let alone travelling.
  sweepCands.set(stop.n, cands);
  // Worth asking about: anything the collector has a guess for, or that showed
  // a click signal. The rest are links, buttons and text — real elements, but
  // not a question. They stay one fold away, because sometimes the noise IS the
  // component: six plain buttons that are a tab strip.
  //
  // `nested` is the collector's own word for "this is a PART of a component of
  // the same kind that is already listed above it" — seven <li>s and seven
  // triggers inside one mega menu. Seventeen rows all reading "menu?" for one
  // menu is not seventeen questions; it is one question asked seventeen times,
  // and it pushed the rest of the section off the end of the list. They fold
  // away with the plain elements, where they are still reachable, because
  // occasionally the part IS the thing you mean to name.
  // Grouped by what there is to DO with each, which is the only distinction
  // that matters when you are working through a section:
  //
  //   components — a menu, a carousel, a tab strip. These are the answer.
  //   bare       — it takes a click and it is not a button or a link. This is
  //                the one that fails a keyboard user, and it is one press to
  //                fix: give it the role it should have had.
  //   native     — a real <a href> or <button>. Nothing to do, and a list that
  //                shows them is a list you have to read past to find the two
  //                groups above.
  //
  // It used to be one flat list of everything with a click signal — 121 rows
  // out of 224 on this page, nearly all of them ordinary links.
  const isNative = (c) => (c.signals || []).some((s) => NATIVE_SIGNAL.test(s));
  const components = cands.filter((c) => !c.nested && c.component);
  const rest = cands.filter((c) => components.indexOf(c) === -1);
  // !c.nested: an element folded into a typed component (a segmented
  // control's options, a carousel's dots) is that component's PART — elal's
  // four trip-type links were the radio's options and were offered again
  // here as four loose buttons-to-be.
  const bare = rest.filter((c) => (c.signals || []).length && !isNative(c) && c.selector && !c.nested);
  const plain = rest.filter((c) => bare.indexOf(c) === -1);
  const interesting = components;   // what the head count is about

  // The picture goes where the pink number was. A number is a lookup you have to
  // perform against the page; a thumbnail of the element IS the answer, and it
  // is the same thing the sections list does one level up. Hovering enlarges it,
  // exactly as a section thumbnail does.
  const thumb = (c) => `
    <span class="lbl-thumb" data-mark="${c.mark}">
      <img class="lbl-img" alt="">
      <img class="lbl-zoom" alt="">
      <span class="lbl-n">${c.mark}</span>
    </span>`;

  // A component row states what it IS, in a control you can correct, and starts
  // ticked. The question being asked is "is this right?", and a row that starts
  // empty asks "what is this?" instead — which is the question the tool is
  // supposed to have answered already.
  const typeSel = (c) => `
    <select class="lbl-row-type" aria-label="What ${escapeHtml(c.selector || 'it')} is">
      ${LABEL_TYPES().map((t) =>
        `<option value="${t}"${t === c.component ? ' selected' : ''}>${t}</option>`).join('')}
    </select>`;

  // Deliberately the same shape as a section row in the picker: tick, picture,
  // a bold name, a quieter line of detail under it. A component and a section
  // are the same kind of object at two scales — one is a piece of the page you
  // are deciding about — and giving them two different layouts made the second
  // list read as a different tool.
  const compRow = (c) => `
    <label class="ai-approved-row ai-bulk-row lbl-row is-comp" data-mark="${c.mark}">
      <input type="checkbox" class="lbl-tick" value="${c.mark}" ${c.inShadow ? '' : 'checked'}
             aria-label="Build ${escapeHtml(c.component)} on ${escapeHtml(c.selector || 'this')}">
      ${thumb(c)}
      <span class="lbl-body">
        <!-- Both controls are dark boxes on a dark ground, one above the
             other, and neither said which was which — a dropdown of component
             types and a free-text selector field read as two identical empty
             bars. The captions are what tell them apart at a glance. -->
        <span class="lbl-field">
          <span class="lbl-cap">What it is</span>
          <span class="lbl-title">${typeSel(c)}</span>
        </span>
        <!-- The selector is editable. What the collector works out is a good
             guess and not a decision — it may be too wide (fourteen matches
             where one is meant), too narrow, or rooted one level off. Correcting
             it here is the difference between a mapping you can use and one you
             have to rebuild by hand in Mappings afterwards. -->
        <span class="lbl-field">
          <span class="lbl-cap">Selector</span>
          <input class="lbl-sel-edit" type="text" spellcheck="false"
                 value="${escapeHtml(c.selector || '')}"
                 placeholder="${c.inShadow
                   ? 'inside a shadow root — u1.fix cannot reach it, no selector exists'
                   : c.selector ? 'CSS selector for this component'
                   : 'this element has no stable name — ask the client to add a class'}"
                 aria-label="Selector to build the ${escapeHtml(c.component)} on">
        </span>
        <span class="lbl-meta lbl-meta-2">${escapeHtml(c.tag)}${
          c.maybe ? ' · guessed from its class name' : ' · stated by the markup'}${
          c.matches > 1 ? ` · selector hits ${c.matches} elements` : ''}${
          c.inShadow ? ` · INSIDE A SHADOW ROOT${c.shadowHost ? ` (host: ${escapeHtml(c.shadowHost)})` : ''} — not mappable, unticked` : ''}</span>
      </span>
      <!-- Not this, and never ask again. Unticking says "not this time";
           .pageWrapper guessed as a form is wrong every time, and without a
           way to say so it comes back on every scan of every page. Dismissals
           are per-project and shared, and the cost dialog is where they can
           be cleared. -->
      <button type="button" class="lbl-dismiss" data-dismiss="${c.mark}"
              title="Not a component — remove it and stop suggesting it on this site">✕</button>
    </label>`;

  const row = (c) => `
    <label class="lbl-row" data-mark="${c.mark}">
      <input type="checkbox" class="lbl-tick" value="${c.mark}">
      ${thumb(c)}
      <span class="lbl-tag">${escapeHtml(c.tag)}</span>
      <span class="lbl-sel">${escapeHtml(c.selector || '(no selector)')}</span>
      ${c.component ? `<span class="lbl-guess">${escapeHtml(c.component)}${c.maybe ? '?' : ''}</span>` : ''}
      ${c.closed ? '<span class="lbl-flag">closed</span>' : ''}
      ${c.matches > 1 ? `<span class="lbl-flag">${c.matches} matches</span>` : ''}
    </label>`;

  host.style.display = '';
  host.innerHTML = `
    <div class="lbl-box">
      <div class="lbl-head">
        <strong>Section ${stop.n}</strong>
        <span class="lbl-sub">${components.length
          ? `These are the ${components.length} component${components.length === 1 ? '' : 's'} found here. ` +
            `Check them, correct anything wrong, then carry on — naming them costs nothing.`
          : `Nothing here reads as a component. Everything on this section is ordinary links and text, ` +
            `or the model has not been asked yet.`}</span>
        <!-- The one honest answer to "it is right there in the picture and not
             in the list". Everything already mapped is filtered out before
             this screen — correct, and completely invisible, so a component
             you built an hour ago reads as one the tool has stopped finding. -->
        ${collected.skipped ? `<span class="lbl-sub lbl-skipped">${collected.skipped} element${
          collected.skipped === 1 ? ' on this section is' : 's on this section are'} not listed:
          already mapped, or found on an earlier section. They are in the picture; they are not work any more.</span>` : ''}
      </div>

      <div class="lbl-list">${components.map(compRow).join('')}</div>

      ${bare.length ? `<div class="lbl-bare">
        <div class="lbl-bare-head">${bare.length} thing${bare.length === 1 ? '' : 's'} here take${bare.length === 1 ? 's' : ''} a click without being a button or a link</div>
        <p class="lbl-sub">A keyboard cannot reach ${bare.length === 1 ? 'it' : 'them'} and a screen reader says nothing.
        Ticked below, ${bare.length === 1 ? 'it gets' : 'they get'} the role ${bare.length === 1 ? 'it' : 'they'} should have had.</p>
        <div class="lbl-list">${bare.map(row).join('')}</div>
        <div class="lbl-act">
          <button class="btn-outline btn-sm" id="lblRoleBtn" disabled>Make the ticked ones accessible</button>
        </div>
      </div>` : ''}

      <!-- Everything else, and the way to correct a miss. Shut, because on a
           good section there is nothing to do here — but it is the only answer
           to "it did not find my tab strip", so it says so on the tin rather
           than being a bare count of rows. -->
      <details class="lbl-plain">
        <summary>Missed something? ${plain.length} more element${plain.length === 1 ? '' : 's'} to choose from</summary>
        <p class="lbl-sub">Real links and buttons, text, and the parts of the components above — nothing
        here needs doing on its own. But if a component was missed, this is where it is:
        tick the elements that form it, say what it is, and add it. Six buttons that are a tab strip
        appear here as six buttons.</p>
        <div class="lbl-list">${plain.map(row).join('')}</div>
        <div class="lbl-act">
          <select id="lblType" aria-label="What the ticked elements are">
            ${LABEL_TYPES().map((t) => `<option value="${t}">${t}</option>`).join('')}
          </select>
          <button class="btn-outline btn-sm" id="lblAdd" disabled>Add the ticked ones as this</button>
        </div>
      </details>

      <div class="lbl-made" id="lblMade"></div>

      <!-- One button. "Ask Claude about this section as well" and a second Stop
           both went: the run already has "Stop after this section" above it, and
           the model is what the sections you have not confirmed are for. Two
           more ways out of one screen is what made this area unreadable.
           "Do not ask me again" moved up to the box that decides what gets
           read, beside the other two switches that govern the run. -->
      <div class="lbl-go">
        <button class="btn-ghost btn-sm" id="lblSkip" hidden>Skip the rest — keep what is done</button>
        <button class="btn-primary btn-sm" id="lblFree">${components.length
          ? 'These are right — build them and go on'
          : 'Nothing here — next section'}</button>
      </div>
      <div class="map-mode-hint" id="lblStatus"></div>
    </div>`;

  const status = document.getElementById('lblStatus');
  const addBtn = document.getElementById('lblAdd');
  const roleBtns = ['lblRoleBtn'].map((id) => document.getElementById(id));
  const sync = () => {
    sweepLabel.marks = new Set([...host.querySelectorAll('.lbl-tick:checked')].map((t) => Number(t.value)));
    addBtn.disabled = sweepLabel.marks.size === 0 || sweepLabel.busy;
    // These act on the bare group only, so they are armed by what is ticked
    // INSIDE it — ticking a menu up in the components list must not offer to
    // turn it into a button.
    const bareTicked = [...host.querySelectorAll('.lbl-bare .lbl-tick:checked')].length;
    for (const b of roleBtns) if (b) b.disabled = !bareTicked || sweepLabel.busy;
  };

  return new Promise((resolve) => {
    const finish = (out) => {
      sweepLabel.resolve = null;
      host.onchange = host.onclick = host.onmouseover = host.onmouseout = null;
      host.innerHTML = '';
      // A drop belongs to one pause and is built fresh for the next; the
      // standalone fallback is a fixture and is only hidden.
      if (drop) {
        drop.remove();
        if (screenRow) screenRow.classList.remove('is-open');
        // Rebuilt from state rather than unpicked by hand — the fold, the
        // hidden rows and the marks this pause set are all undone by one
        // redraw, and the redraw was blocked only while the pause was open.
        if (aiSweep.phase === 'screens') renderSweepScreens();
      } else host.style.display = 'none';
      resolve(out);
    };
    // Declared on sweepLabel since this pause was written and never assigned,
    // so "is the run holding to be told what things are" had no answer outside
    // this function. sweepPreviewScreen needs it: a held run is not moving the
    // page, so hovering a section may still preview it.
    sweepLabel.resolve = finish;

    host.onchange = sync;

    // Hover a row and see the element — as a picture, in the panel, the way the
    // sections list shows a section. Cut from the screenshot already taken for
    // this section, so it costs nothing and does not touch the page.
    //
    // The outline on the real page is still drawn, because "where is it on the
    // actual site" is a different question from "which one is it" and both get
    // asked. What it no longer does is scroll the page out from under you.
    const shotImg = new Image();
    const crops = new Map();
    const byMark = new Map(cands.map((c) => [c.mark, c]));
    const cropFor = (n) => {
      if (!crops.has(n)) {
        const c = byMark.get(n);
        crops.set(n, c ? elementCrop(collected.shot, collected.viewport, c.box, shotImg) : '');
      }
      return crops.get(n);
    };
    // Drawn into the rows as soon as the shot decodes. Doing it on hover meant
    // the list was a wall of numbers until you touched it — and the number was
    // never the thing you wanted to see.
    shotImg.onload = () => {
      for (const holder of host.querySelectorAll('.lbl-thumb')) {
        const n = Number(holder.dataset.mark);
        const src = cropFor(n);
        if (!src) { holder.classList.add('is-blank'); continue; }
        holder.querySelector('.lbl-img').src = src;
        holder.querySelector('.lbl-zoom').src = src;
        holder.classList.add('has-shot');
      }
    };
    if (collected.shot) shotImg.src = collected.shot;

    host.onmouseover = (e) => {
      const r = e.target.closest('.lbl-row');
      if (!r) return;
      const n = Number(r.dataset.mark);
      const c = byMark.get(n);
      if (!tab) return;
      // Hovering marks it ON THE PAGE — by SELECTOR, not by mark number.
      //
      // showMark looks up [data-u1-mark="n"], and the first line of
      // collectCandidates is clearMarks(). Anything that re-reads the page —
      // hovering a row in the sections list, a preview, a re-collect — wipes
      // every mark, and from then on the highlight silently found nothing.
      // That is why this "did not work": not the drawing, the lookup.
      //
      // A selector is not destroyed by anything, and the row already carries
      // one. noScroll because the page is parked on this section deliberately;
      // yanking it elsewhere on a mouse-over is what the preview is for.
      const sel = c && c.selector;
      if (sel) {
        inPage(tab.id, (x) => window.__u1SelectorIntel.highlightSelector(x, { noScroll: true }), [sel])
          .catch(() => {});
      } else {
        inPage(tab.id, (m) => window.__u1SelectorIntel.showMark(m), [n]).catch(() => {});
      }
    };
    host.onmouseout = (e) => {
      // Leaving the list takes the highlight down; moving between rows does not,
      // or every gap between two rows would flash the page.
      if (!host.contains(e.relatedTarget) && tab) {
        inPage(tab.id, () => window.__u1SelectorIntel.clearHilite()).catch(() => {});
      }
    };

    host.onclick = async (e) => {
      // The one control that must work WHILE a build is running.
      if (e.target.closest('#lblSkip')) {
        sweepLabel.skip = true;
        e.target.closest('#lblSkip').textContent = 'Stopping after this one…';
        return;
      }
      if (sweepLabel.busy) return;

      // ✕ on a component row: this is not a component at all — a wrapper div
      // guessed as a form, a cookie bar guessed as a dialog. Off THIS list,
      // and nothing more: it used to also go onto a shared per-site dismissed
      // list that silently gated every later scan, which is how a ✕ pressed
      // once ate the molina sign-in listbox for weeks. Owner decision
      // (2026-09-01): every scan starts fresh. Inside a <label>, so the
      // default (toggling the row's checkbox) has to be suppressed before the
      // row is removed.
      const dis = e.target.closest('[data-dismiss]');
      if (dis) {
        e.preventDefault();
        e.stopPropagation();
        const rowEl = dis.closest('.lbl-row');
        rowEl?.remove();
        showNotice(status, 'Removed from this list. The next scan starts fresh, so it will be suggested again.', 'success', 7000);
        return;
      }

      // The one press this screen exists for: yes, these are what they say
      // they are — build them and carry on. Each row is built as the type ITS
      // OWN control says, so correcting one is changing that row's dropdown and
      // nothing else. It used to be one dropdown at the bottom governing every
      // ticked row at once, which is unusable the moment two rows differ and
      // unreadable even when they do not.
      if (e.target.closest('#lblFree')) {
        const ticked = [...host.querySelectorAll('.lbl-list .lbl-row.is-comp')]
          .filter((r) => r.querySelector('.lbl-tick')?.checked)
          .map((r) => ({
            mark: Number(r.dataset.mark),
            type: r.querySelector('.lbl-row-type').value,
            // Empty, or unchanged, means "use what was measured".
            sel: (r.querySelector('.lbl-sel-edit')?.value || '').trim(),
          }));
        if (ticked.length) {
          sweepLabel.busy = true;
          sync();
          const btn = document.getElementById('lblFree');
          const label = btn.textContent;
          let ok = 0;
          const failed = [];
          // One component can sit for a minute or two on a model call, and a
          // build of six is six of those. A way out that does not throw away
          // the ones already saved — they are in Mappings and applied — is the
          // difference between waiting and being stuck.
          sweepLabel.skip = false;
          const skipBtn = document.getElementById('lblSkip');
          if (skipBtn) skipBtn.hidden = false;
          try {
            for (let k = 0; k < ticked.length; k++) {
              if (sweepLabel.skip) {
                failed.push(`${ticked.length - k} skipped at your request`);
                break;
              }
              btn.textContent = `Building ${k + 1} of ${ticked.length}…`;
              const rowEl = host.querySelector(`.lbl-row.is-comp[data-mark="${ticked[k].mark}"]`);
              const res = await confirmedToMapping(ticked[k], stop, tab);
              // The outcome goes ON THE ROW. Pressing build and getting silence
              // — no mapping in the drawer, no error anywhere you would look —
              // is indistinguishable from the button doing nothing, and that is
              // what a one-line hint at the bottom of a long panel amounts to.
              if (res.err) {
                failed.push(`${ticked[k].type}: ${res.err}`);
                if (rowEl) {
                  rowEl.classList.add('is-failed');
                  rowEl.insertAdjacentHTML('beforeend',
                    `<span class="lbl-why">✗ ${escapeHtml(res.err)}</span>`);
                }
                continue;
              }
              ok++;
              made.push(res.found);
              if (res.warn) showNotice(status, res.warn, 'warn', 12000);
              if (rowEl) {
                rowEl.classList.add('is-used');
                rowEl.insertAdjacentHTML('beforeend',
                  `<span class="lbl-why">✓ saved to Mappings</span>`);
              }
            }
          } finally {
            sweepLabel.busy = false;
            btn.textContent = label;
            sweepLabel.skip = false;
            if (skipBtn) skipBtn.hidden = true;
          }
          // And a sentence about the whole press, because "6 ticked, 5 saved"
          // must never again be something you notice by counting rows.
          if (failed.length) {
            showNotice(status,
              `${ok} of ${ticked.length} saved to Mappings. ${failed.length} could not be built: ` +
              failed.join(' · '), 'warn', 16000);
            // Stay on the section. A failure you cannot see and cannot retry is
            // the same as no failure report at all.
            return;
          }
          // Everything the site has, not only the ones just built. u1 decorates
          // an element once per page load, so a mapping made two sections ago
          // may never have met what this section re-rendered — and the whole
          // point of confirming a section is to look at the page afterwards.
          let put = null;
          try { put = await applyAllMappings({ silent: true, tab: await sweepTab() }); } catch (e) {}
          showNotice(status,
            `${ok} saved to Mappings` +
            (put ? ` · ${put.applied} of ${put.applied + put.failed} now applied on the page` : '') + '.',
            'success', 6000);
        }
        // "and everything after this one, without asking" — the same switch the
        // hold offers, set from the place the decision is actually made.
        finish({ labelled: made, done: true, auto: !sweepLabel.on || !sweepPause.on });
        return;
      }

      // The safety net. Not a component and not a judgement: this element takes
      // a click, it is not a button or a link, and u1.fix.button/link is
      // exactly the correction for that. One press per group rather than one
      // trip through the type dropdown per element.
      const roleBtn = e.target.closest('#lblRoleBtn');
      if (roleBtn) {
        const marks = [...host.querySelectorAll('.lbl-bare .lbl-tick:checked')].map((t) => Number(t.value));
        if (!marks.length) return;
        sweepLabel.busy = true;
        sync();
        try {
          // One at a time: these are separate controls that happen to share a
          // problem, not one component with several parts. Button or link is
          // not the person's question any more (owner: "just make it
          // accessible") — an element that reads as navigation (an <a>, a
          // role=link, an href of its own) becomes a link; everything else
          // acts, so it becomes a button.
          for (const m of marks) {
            let asType = 'button';
            try {
              const cand = cands.find((x) => x.mark === m);
              const el = cand && cand.selector ? await inPage(tab.id, (x) => {
                const n = document.querySelector(x);
                if (!n) return null;
                return { tag: n.tagName.toLowerCase(), href: n.getAttribute('href') || '',
                         role: n.getAttribute('role') || '' };
              }, [cand.selector]) : null;
              if (el && (el.role === 'link' ||
                  (el.tag === 'a' && el.href && el.href !== '#' && !/^javascript:/i.test(el.href)))) {
                asType = 'link';
              }
            } catch {}
            const res = await labelToMapping(asType, [m], stop, tab);
            if (res.err) { showNotice(status, res.err, 'error', 9000); continue; }
            made.push(res.found);
            document.getElementById('lblMade').insertAdjacentHTML('beforeend',
              `<div class="lbl-done">✓ ${escapeHtml(asType)} on <code>${escapeHtml(res.found.sel)}</code></div>`);
            const tick = host.querySelector(`.lbl-bare .lbl-tick[value="${m}"]`);
            if (tick) { tick.checked = false; tick.closest('.lbl-row').classList.add('is-used'); }
          }
        } finally { sweepLabel.busy = false; sync(); }
        return;
      }

      if (!e.target.closest('#lblAdd')) return;
      const marks = [...sweepLabel.marks];
      if (!marks.length) return;
      const type = document.getElementById('lblType').value;
      sweepLabel.busy = true;
      addBtn.disabled = true;
      try {
        const res = await labelToMapping(type, marks, stop, tab);
        if (res.err) { showNotice(status, res.err, 'error', 9000); }
        else {
          made.push(res.found);
          document.getElementById('lblMade').insertAdjacentHTML('beforeend',
            `<div class="lbl-done">✓ ${escapeHtml(res.found.type)} on <code>${escapeHtml(res.found.sel)}</code>` +
            `<span class="lbl-sub"> — ${escapeHtml(res.found.why)}</span></div>`);
          host.querySelectorAll('.lbl-tick:checked').forEach((t) => {
            t.checked = false;
            t.closest('.lbl-row').classList.add('is-used');
          });
        }
      } finally {
        sweepLabel.busy = false;
        sync();
      }
    };
    sync();
  });
}

/**
 * A confirmed row becomes a mapping — through the engine that reads the
 * container's markup, not the one that measures it from the outside.
 *
 * These produced mappings whose every sub-selector was the ROOT selector again:
 *
 *   fix.tabs('.finder__tabs', { selectors: { tabList: '.finder__tabs' } })
 *   fix.menu('.mega-nav', { selectors: { horizontalMenu: '.mega-nav',
 *                                        menu: '.mega-nav' } })
 *
 * which is not a mapping — u1.fix.tabs needs tabList, tab and tabPanel to be
 * three DIFFERENT things. describeComponent measures a component from a set of
 * ticked marks, and when the tick is the container itself there is nothing to
 * measure the parts from, so every field collapses onto the root.
 *
 * rowFromParts → prepareOne is the path the per-component route has always
 * used: it extracts the container's actual HTML and asks the model to name the
 * parts inside it. That is the one that works, and it is the one the estimate's
 * "Build" row has always been quoting for — a call per component.
 */
async function confirmedToMapping(pick, stop, tab, extra) {
  const cand = (sweepCands.get(stop && stop.n) || []).find((c) => c.mark === pick.mark);
  let sel = pick.sel || (cand && cand.selector) || '';
  if (!sel) return { err: 'That row has no selector to build on.' };

  // A dialog, listbox, datepicker or tooltip is rooted on the thing that
  // APPEARS, and the row holds the control that summons it. Same two sources of
  // the other half, best evidence first, as the bulk path uses.
  let container = '';
  let openWhy = '';
  // triggerRequired ONLY — a dialog's sel is the dialog itself and its
  // trigger is optional; hunting a "panel" for it filed some unrelated
  // popup as its trigger. See the bulk path for the molina incident.
  if (triggerRequired(pick.type)) {
    const seen = (stop.probed || []).find((p) =>
      p.parts && (p.parts.trigger === sel || p.root === sel) && p.parts.panel);
    container = (seen && seen.parts.panel) || '';
    // The row does not always hold the control. A menu row retyped by
    // menuIsReallyListbox is rooted on the LIST itself, and this hunt then
    // asked "what does the list open" and pressed a hidden <ul> — so the
    // molina Sign-In, correctly surveyed and correctly retyped, was refused
    // at the last step with "open it on the page", addressed to nobody. The
    // shape reader answers from markup alone for every spelling — the list,
    // the wrapper or the button (climbing to the parent for the first) — so
    // for a listbox it goes before anything that guesses or presses.
    if (!container && pick.type === 'listbox') {
      const lb = await inPage(tab.id, (x) => {
        const S = window.__u1SelectorIntel;
        let sh = S.listboxShape(x);
        if (!sh) {
          try {
            const el = document.querySelector(x);
            if (el && el.parentElement) {
              const up = S.robustSelector(el.parentElement);
              if (up && S.isU1Valid(up)) sh = S.listboxShape(up);
            }
          } catch (e) {}
        }
        return sh || null;
      }, [sel]);
      if (lb && lb.listbox && lb.trigger) { container = lb.listbox; sel = lb.trigger; }
    }
    if (!container) {
      container =
        (await inPage(tab.id, (x) => window.__u1SelectorIntel.openedBy(x), [sel])) || '';
    }
    // Neither the sweep nor the markup knows the other half: press the trigger
    // and read what appears, the same way the card route does.
    if (!container) {
      const cap = await autoOpenCapture(tab, sel, pick.type);
      if (cap && cap.shape && cap.shape.listbox) {
        container = cap.shape.listbox;
        if (cap.shape.trigger) sel = cap.shape.trigger;
      } else {
        container = (cap && (cap.root || cap.stated)) || '';
        if (container && cap && cap.pressed) sel = cap.pressed;
      }
      if (!container && cap) {
        openWhy = cap.err ||
          (!cap.opened ? `pressed ${cap.pressed || 'it'}, but nothing new appeared on the page` : '');
      }
    }
  }
  const built = rowFromParts({
    type: pick.type, found: sel, container, label: sel, compIndex: undefined,
    why: pick.why || (cand && cand.why) || '',
  });
  if (built.err) {
    return { err: built.err + (openWhy ? ` (Tried to open it myself: ${openWhy}.)` : '') };
  }
  built.row.needsWork = true;
  const prepared = await prepareOne(built.row, tab);
  if (prepared.err) return { err: prepared.err };

  // ── And SAVE it. ─────────────────────────────────────────────────────────
  // prepareOne only prepares: it works out the selectors and puts a card on
  // the approval track. The bulk route saves by pressing the approve button
  // afterwards, and this route had no such press — so six components were
  // built, reported as done, and Mappings stayed empty.
  //
  // Saved one at a time on purpose. saveMappingEntry reads the stored list,
  // mutates it and writes it back with no locking, so concurrent saves clobber
  // each other. It also means each component appears in the drawer the moment
  // it is finished, rather than all six arriving at the end — which is what
  // makes a six-minute build watchable.
  const tpl = aiCardTemplate(prepared.idx);
  if (!tpl) return { err: 'The prepared mapping could not be read back.' };
  // Fields the CALLER knows and the pipeline cannot — e.g. the interior scan
  // stamping which dialog this mapping was found inside, so the drawer can
  // nest it under that dialog's row.
  if (extra && typeof extra === 'object') Object.assign(tpl, extra);
  let saved;
  let warn = '';
  try { saved = await saveMappingEntry(tpl, { refreshUi: false }); }
  catch (e) {
    // The store distinguishes "not written" from "written here, not shared".
    // A server that refuses the push — 413 on a site with a lot of mappings —
    // used to be reported as a failed build on a mapping that was already
    // safely in chrome.storage, so the count read "0 of 1 saved" when it was
    // in fact 1 of 1.
    if (!e.localOnly) return { err: 'Could not save it: ' + e.message };
    warn = e.message;
  }
  if (saved && saved.cancelled) return { err: 'Not saved — the role question was declined.' };
  try {
    await applyMappingsBatch([{
      type: tpl.type, primary: tpl.primary, firstArg: tpl.firstArg,
      config: tpl.config, overwriteRole: tpl.overwriteRole,
    }]);
  } catch (e) { /* saved is the durable half; the panel re-applies on open */ }

  // Take the approval card down.
  //
  // prepareOne renders one, because on the manual route the card IS the
  // approval step. Here the approval already happened — you ticked the row and
  // pressed build — so leaving it up asks the same question twice. Worse, a
  // card without data-done is what holds the whole "cards" stage open
  // (stageHasContent), so one left behind sat over the panel until it was
  // dismissed by hand, in a mode whose entire promise is that nothing will ask.
  //
  // Removed only after aiCardTemplate has read it: the template lives in the
  // card's own form.
  document.querySelector(`#aiSlideTrack .ai-map-card[data-card="${prepared.idx}"]`)?.remove();
  if (!document.querySelectorAll('#aiSlideTrack .ai-map-card:not([data-done])').length) {
    setStage(mapMode === 'sweep' ? (aiSweep.phase === 'components' ? 'components' : 'screens') : 'none');
  }

  await loadMappingsList();
  refreshExportInfo();
  return {
    warn,
    // mappingKey is what "undo this section" deletes on. Recorded here, at the
    // moment of saving, because it is the only place that knows which stored
    // row this component became — matching on the selector later would be a
    // guess, and a wrong guess deletes a neighbouring section's work.
    found: { id: `s${stop.n}m${pick.mark}`, label: sel, type: pick.type, sel, done: true,
             mappingKey: mappingKey({ type: tpl.type, primary: tpl.primary, firstArg: tpl.firstArg }) },
  };
}

/**
 * A type and some marks become a saved, applied mapping — with no model call.
 *
 * describeComponent measures the sub-fields; buildTemplate, saveMappingEntry and
 * applyMappingsBatch are the same three the manual route has always used, so
 * this mapping is indistinguishable from a hand-built one and carries the same
 * narrowing, role question and export.
 */
async function labelToMapping(type, marks, stop, tab, rootOverride) {
  let desc;
  try {
    desc = await inPage(tab.id,
      (t, m, f) => window.__u1SelectorIntel.describeComponent(t, m, f),
      [type, marks, rootOverride || '']);
  } catch (e) { return { err: 'Could not read the page: ' + e.message }; }
  if (!desc) return { err: 'Could not read the page.' };
  if (desc.err) return { err: desc.err };

  // A selector typed in the row wins over the measured one. What the collector
  // works out is a guess: it can be too wide, too narrow, or rooted a level off,
  // and correcting it here is the difference between a usable mapping and one
  // rebuilt by hand in Mappings afterwards. The measured sub-fields are kept —
  // they are relative to the root and are still the best description of it.
  let root = desc.root;
  if (rootOverride && rootOverride !== desc.root) {
    const hits = await inPage(tab.id, (x) => {
      try { return document.querySelectorAll(x).length; } catch (e) { return -1; }
    }, [rootOverride]);
    if (hits === -1) return { err: `That selector is not valid CSS: ${rootOverride}` };
    if (!hits) return { err: `That selector matches nothing on this page: ${rootOverride}` };
    root = rootOverride;
  }
  const tpl = buildTemplate(type, root, desc.fields || {}, {});
  if (!tpl) return { err: `Could not build a ${type} mapping from that.` };

  let saved;
  try { saved = await saveMappingEntry(tpl, { refreshUi: false }); }
  catch (e) { return { err: 'Could not save it: ' + e.message }; }
  if (saved && saved.cancelled) return { err: 'Not saved — the role question was declined.' };

  const res = await applyMappingsBatch([{
    type: tpl.type, primary: tpl.primary, firstArg: tpl.firstArg,
    config: tpl.config, overwriteRole: tpl.overwriteRole,
  }]);
  const verdict = describeApply(res, tpl);
  loadMappingsList();

  // Keep it as ground truth too.
  //
  // fixtures/step.labels.json is the corpus verify-detect scores against, and
  // its own header insists it be written by reading the markup rather than by
  // running the tool and blessing the output — "a corpus built from the tool's
  // own output can only ever score 100%". A label you typed is exactly that
  // kind of source: you looked at the page and said what it is.
  //
  // Kept locally and exported on request; nothing writes the fixture directly.
  rememberLabel({
    type,
    root,
    fields: desc.fields || {},
    matches: (desc.counts && desc.counts[Object.keys(desc.fields || {})[0]]) || undefined,
    why: desc.why || 'named by hand during a scan',
    url: (stop && stop.url) || currentHostname,
  });

  return {
    found: {
      id: `s${stop.n}L${marks.join('_')}`,
      label: `${type} — you named it`,
      type,
      sel: desc.root,
      why: (desc.why || 'measured from what you ticked') + (verdict.ok ? '' : ' · ' + verdict.msg),
      needsWork: true,
      done: true,          // already saved and applied; not work for a later stage
    },
  };
}

// ─────────────────────────────────────────────────────────────────────────────
//  What is on screen — one stage at a time
// ─────────────────────────────────────────────────────────────────────────────
//
// The two AI routes share every result panel, and until now every one of them
// showed and hid itself: roughly twenty-five `style.display` writes over six
// containers, with no single place deciding. Nothing enforced exclusion, so the
// Whole-page route ended up stacking the sections list, a pending review card
// and a session-wide "approved and applied" list all at once — not by design,
// but because no line of code was responsible for the question.
//
// setStage is that line. It is the ONLY writer of `display` for these six, and
// a test in verify-sweep.mjs fails the build if anything else writes one, which
// is what stops the stack coming back.
const STAGE_PANELS = {
  screens:    ['sweepPicks'],      // Whole page · which sections to search
  components: ['sweepPicks'],      // Whole page · which components to build
  found:      ['aiResults'],       // Automatic · what is on this section
  cards:      ['aiMappings'],      // either · one card at a time
  review:     ['aiBulkReview'],    // either · approve a batch
  applied:    ['aiApproved'],      // either · what this batch did
  none:       [],
};
const STAGE_IDS = ['aiResults', 'aiMappings', 'aiBulkReview', 'sweepPicks', 'aiApproved'];

// The trail, per route. Manual has no stages; Automatic and Whole page each
// have their own three, and the words differ because the work differs — you
// search SCREENS on one and read one section on the other.
// Numbered, and named after what you DO at each one rather than what lives
// there. "SCREENS › COMPONENTS › APPLIED" are three nouns of equal weight, and
// which of the three you are standing on was carried entirely by an underline —
// reported as not knowing what stage you are at. A number is not decoration
// here: it is the answer to "how far through this am I", which three nouns
// cannot give however they are styled.
const STAGE_TRAIL = {
  sweep: [['screens', 'Pick sections'], ['components', 'Choose fixes'], ['applied', 'Applied']],
  auto:  [['found', 'Found'], ['cards', 'Review'], ['applied', 'Applied']],
};
// Stages that are a moment inside another stage rather than one of their own.
const STAGE_STANDS_FOR = { review: 'cards' };

let currentStage = 'none';

function setStage(stage) {
  if (!STAGE_PANELS[stage]) stage = 'none';
  currentStage = stage;
  const show = STAGE_PANELS[stage];
  for (const id of STAGE_IDS) {
    const el = document.getElementById(id);
    if (el) el.style.display = show.includes(id) ? 'block' : 'none';
  }
  renderStageTrail();
}

/**
 * Where you are and how to get back.
 *
 * This replaces the numbered captions, which were `::before` content on shared
 * containers — so the Whole-page route was labelled "1 · Found on this section"
 * over a list of twenty-six sections it had not read yet.
 */
function renderStageTrail() {
  const host = document.getElementById('stageTrail');
  if (!host) return;
  // The whole-page route says only the stage it is ON — "Pick sections", then
  // "Choose fixes" — as a heading under its two controls, not a three-step
  // strip above them. Asked for: the other two steps were noise on a screen
  // that only ever shows one of them. The heading lives inside #sweepPicks
  // (#sweepStageNow); the shared strip above is left empty in this route.
  const now = document.getElementById('sweepStageNow');
  const clear = () => {
    host.style.display = 'none';
    host.innerHTML = '';
    if (now) { now.style.display = 'none'; now.innerHTML = ''; }
  };
  // Once every section has been read, "Pick sections" is not a stage you
  // are moving through any more — it is finished, and the Completed row
  // beside it already says so. A trail claiming a three-step journey next
  // to a row that says the journey is over reads as the two contradicting
  // each other.
  if (mapMode === 'sweep' && currentStage === 'screens' && aiSweep.stops.length > 0 &&
      aiSweep.stops.every((s) => !s.count || s.scanned)) {
    clear();
    return;
  }
  const trail = STAGE_TRAIL[mapMode === 'sweep' ? 'sweep' : 'auto'];
  const at = STAGE_STANDS_FOR[currentStage] || currentStage;
  const idx = trail.findIndex(([k]) => k === at);
  if (mapMode === 'manual' || idx < 0) { clear(); return; }
  if (mapMode === 'sweep' && now) {
    host.style.display = 'none';
    host.innerHTML = '';
    // The one stage, with a way back to the one before it when that one
    // still has something in it — the only use the three-step strip had.
    const prev = idx > 0 && stageHasContent(trail[idx - 1][0]) ? trail[idx - 1] : null;
    now.style.display = '';
    now.innerHTML =
      `<h3 class="stage-now">` +
        `<span class="stage-now-n" aria-hidden="true">${idx + 1}</span>` +
        `<span class="stage-now-label">${escapeHtml(trail[idx][1])}</span>` +
        `<span class="stage-now-of">step ${idx + 1} of ${trail.length}</span>` +
        (prev ? `<button type="button" class="stage-now-back" data-stage="${prev[0]}">‹ ${escapeHtml(prev[1])}</button>` : '') +
      `</h3>`;
    return;
  }
  if (now) { now.style.display = 'none'; now.innerHTML = ''; }
  host.style.display = '';
  host.innerHTML = trail.map(([key, label], i) => {
    // Reachable if it HAS something, not if it happens to be behind you.
    //
    // The first rule was "only a stage you have already been through", which
    // reads sensibly and is wrong the moment you use it: go back to Screens and
    // Components is suddenly ahead of you and dead, even though the components
    // are sitting right there. Reported as "I clicked one and then I cannot
    // click the rest". Direction is not what makes a stage available — content
    // is, and the current stage is the only one that is never a control.
    const state = i === idx ? 'at' : stageHasContent(key) ? 'open' : 'empty';
    const tag = state === 'open' ? 'button' : 'span';
    const attrs = state === 'open' ? ` type="button" data-stage="${key}"` : '';
    // The step number is part of the label, not an ornament beside it, so it
    // survives being read aloud and being read at a glance. "Step 2 of 3,
    // current" is what the stage actually is.
    const where = i === idx ? ` aria-current="step"` : '';
    return `<${tag} class="crumb is-${state}"${attrs}${where}>` +
           `<span class="crumb-n" aria-hidden="true">${i + 1}</span>` +
           `<span class="crumb-label">${escapeHtml(label)}</span></${tag}>` +
           (i < trail.length - 1 ? '<span class="crumb-sep" aria-hidden="true">›</span>' : '');
  }).join('');
}

/** Is there anything in that stage to go to? */
function stageHasContent(key) {
  const stops = (typeof aiSweep !== 'undefined' && aiSweep.stops) || [];
  if (key === 'screens') return stops.length > 0;
  if (key === 'components') {
    return stops.some((x) => (x.found || []).some((f) => !f.done));
  }
  if (key === 'found') return document.querySelectorAll('#aiCompTrack .ai-comp:not([data-done])').length > 0;
  if (key === 'cards') return document.querySelectorAll('#aiSlideTrack .ai-map-card:not([data-done])').length > 0;
  if (key === 'applied') return document.querySelectorAll('#aiApprovedList .ai-approved-row').length > 0;
  return false;
}

document.addEventListener('click', (e) => {
  const back = e.target.closest('#stageTrail [data-stage], #sweepStageNow [data-stage]');
  if (!back) return;
  const to = back.dataset.stage;
  if (to === 'screens') { aiSweep.phase = 'screens'; renderSweepScreens(); return; }
  if (to === 'components') { aiSweep.phase = 'components'; renderSweepPicks(); return; }
  if (to === 'found') { setStage('found'); return; }
  if (to === 'cards') { setStage('cards'); return; }
  setStage(to);
});

/**
 * What a link's file type and its new tab are CALLED, per language.
 *
 * These go into aria-label, so they are spoken to the visitor — an Israeli
 * site announcing "opens in a new tab" in English is a worse answer than
 * saying nothing at all. The Config tab already knows the site's language, so
 * the builder prefills from it rather than making every implementer translate
 * two strings by hand and get it wrong on the sites where they forget.
 *
 * %s is the file type, already uppercase (PDF, JPG, Word).
 */
const LINK_NOTE_WORDS = {
  en: { file: '%s file',        tab: 'opens in a new tab' },
  he: { file: 'קובץ %s',        tab: 'נפתח בלשונית חדשה' },
  ar: { file: 'ملف %s',         tab: 'يفتح في علامة تبويب جديدة' },
  fr: { file: 'fichier %s',     tab: 'ouvre un nouvel onglet' },
  es: { file: 'archivo %s',     tab: 'se abre en una pestaña nueva' },
  de: { file: '%s-Datei',       tab: 'wird in einem neuen Tab geöffnet' },
  ru: { file: 'файл %s',        tab: 'откроется в новой вкладке' },
  it: { file: 'file %s',        tab: 'si apre in una nuova scheda' },
  pt: { file: 'ficheiro %s',    tab: 'abre num novo separador' },
  zh: { file: '%s 文件',         tab: '在新标签页中打开' },
};

// The site's configured language, or English. Read at the moment the form is
// built, so changing the language in Config and coming back gets the right
// wording without a reload.
function linkNoteWords() {
  // Straight off the Config tab's own control, which is the single source of
  // truth for the site's language and is already populated from storage by
  // the time any builder form is opened.
  let lang = 'en';
  try { lang = (document.getElementById('langSelect') || {}).value || 'en'; } catch (e) {}
  return LINK_NOTE_WORDS[lang] || LINK_NOTE_WORDS.en;
}

// Fields that point at exactly ONE element. u1.fix.* resolves a selector rather
// than looping, and applies to the LAST match — so several matches here is a
// real defect, not a style note. (Plural fields like `items` are meant to match
// many, and must not be penalised for it.)
const SINGULAR_FIELDS = new Set([
  'element', 'container', 'menu', 'horizontalMenu', 'listbox', 'combobox', 'trigger',
  'input', 'dialog', 'closeBtn', 'heading', 'form', 'table', 'grid', 'carouselContainer',
  'headerSelector', 'contentSelector', 'loading', 'tooltip', 'paginationContainer',
]);

// Batched match counts — ONE executeScript for every visible selector input, so
// typing does not fire a round-trip per field per keystroke.
async function countSelectors(sels) {
  const tab = await getTab();
  if (!isInjectable(tab)) return sels.map(() => null);
  try {
    const res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: (list) => list.map(s => {
        if (!s) return null;
        try { return document.querySelectorAll(s).length; } catch { return -1; }
      }),
      args: [sels],
    });
    return (res && res[0] && res[0].result) || sels.map(() => null);
  } catch { return sels.map(() => null); }
}

function strengthOf(sel, opts) {
  const intel = globalThis.__u1SelectorIntel;
  if (!intel) return { level: 'empty', label: '', reasons: [] };
  return intel.selectorStrength(sel, opts);
}

// Paint one badge and fold its reasons into the row's on-focus hint bubble.
function paintStrength(badge, s) {
  if (!badge) return;
  badge.dataset.level = s.level;
  badge.textContent = s.label || '';
  badge.title = (s.reasons || []).join('\n');
  const row = badge.closest('.sub-sel-row, .root-text, .field-group');
  const hint = row && row.querySelector('.input-hint');
  if (!hint) return;
  let why = hint.querySelector('.strength-why');
  if (s.level === 'empty') { if (why) why.remove(); return; }
  if (!why) {
    why = document.createElement('div');
    why.className = 'strength-why';
    hint.appendChild(why);
  }
  why.dataset.level = s.level;
  why.textContent = (s.label ? s.label + ' selector — ' : '') + (s.reasons || []).join(' ');
}

let strengthTimer = null;

// Re-grade every selector input on the builder form. Debounced by its callers.
async function refreshStrength() {
  const type = $componentType.value;
  const schema = COMPONENT_SCHEMAS[type];
  const pKey = schema ? primaryKeyOf(schema) : null;
  const alwaysPresent = DYNAMIC_OPEN[type];

  // Collect every (input, badge, field-key) triple currently on screen.
  const rows = [];
  if ($primarySelectorInput) {
    const badge = $primarySelectorInput.parentElement?.querySelector('.sel-strength');
    if (badge) rows.push({ input: $primarySelectorInput, badge, key: pKey || 'element',
                           unique: !(schema && schema.primaryMany) });
  }
  $subSelArea.querySelectorAll('.sel-strength-wrap').forEach(wrap => {
    const input = wrap.querySelector('input[type="text"]');
    const badge = wrap.querySelector('.sel-strength');
    if (!input || !badge) return;
    const key = input.dataset.field || input.dataset.root || '';
    rows.push({ input, badge, key, unique: SINGULAR_FIELDS.has(key) });
  });
  if (!rows.length) return;

  // Grade statically first so the badge responds instantly, then refine with
  // live match counts when the page answers.
  const opts = rows.map(r => ({
    allowZero: !!(alwaysPresent && !alwaysPresent.includes(r.key)),
    unique: r.unique,
  }));
  rows.forEach((r, i) => paintStrength(r.badge, strengthOf(r.input.value.trim(), opts[i])));

  const sels = rows.map(r => r.input.value.trim());
  if (!sels.some(Boolean)) return;
  const counts = await countSelectors(sels);
  rows.forEach((r, i) => {
    if (r.input.value.trim() !== sels[i]) return; // typed on since — skip stale paint
    const o = opts[i];
    if (typeof counts[i] === 'number') o.count = counts[i];
    paintStrength(r.badge, strengthOf(sels[i], o));
  });
}

function scheduleStrength() {
  clearTimeout(strengthTimer);
  strengthTimer = setTimeout(refreshStrength, 400);
}

// One delegated listener covers the primary input and every generated sub-row.
document.getElementById('tab-picker')?.addEventListener('input', (e) => {
  if (e.target.matches('input[type="text"]')) scheduleStrength();
});

// ─────────────────────────────────────────────────────────────────────────────
//  AUTO MAPPING MODE
//  Manual mode is unchanged. In Auto mode the specialist supplies only the
//  PARENT selector; the analyzer reads that element on the page and proposes
//  each sub-selector as a plain-English question. Nothing is written into the
//  form until the suggestions are confirmed.
// ─────────────────────────────────────────────────────────────────────────────

// Plain-English questions, keyed `type.field`. Deliberately short and free of
// U1 jargon — the schema's `desc` text is the doc wording and reads as a spec,
// which is not what you want to be answering one question at a time.
const AUTO_QUESTIONS = {
  'menu.items': 'Which things should the arrow keys move between?',
  'menu.triggers': 'Which items open a drop-down when clicked?',
  'menu.submenus': 'Which boxes open up when you click a top-level item?',
  'menu.horizontalMenu': 'Do the top-level items sit side by side (left/right arrows)?',
  'menu.menubar': 'Is this a bar of commands, or site navigation with drop-downs?',
  'menu.openByMouseenter': 'Does just hovering over an item open its drop-down?',
  'menu.openByMouseover': 'Does just hovering over an item open its drop-down?',
  'listbox.options': 'Which rows are the options you pick from?',
  'listbox.trigger': 'Which button opens this list?',
  'dialog.trigger': 'Which button opens this pop-up?',
  'dialog.closeBtn': 'Which button closes it? (Esc will do the same)',
  'dialog.heading': 'Which text is the title of the pop-up?',
  'accordion.contentSelector': 'Which panel opens and closes underneath?',
  'tabs.tab': 'Which elements are the tabs themselves?',
  'table.row': 'Which elements are the rows?',
  'table.cell': 'Which elements are the cells?',
  'grid.row': 'Which elements are the rows?',
  'grid.cell': 'Which elements are the cells the arrows move between?',
  'carousel.carouselContainer': 'Which element wraps all the slides?',
};

// The last analysis, so Apply can read the specialist's choices back.
let autoResult = null;

const $modeManualBtn = document.getElementById('modeManualBtn');
const $modeAutoBtn = document.getElementById('modeAutoBtn');
const $modeSweepBtn = document.getElementById('modeSweepBtn');

let mapMode = 'manual';

// 'manual' | 'auto' | 'sweep'. The two AI routes share every result panel below
// — the inventory cards, the mapping carousel, the approval screen — and differ
// only in what starts them, so `isAi` rather than `isAuto` is what most of this
// function is asking about.
function setMapMode(mode) {
  mapMode = mode;
  const isAuto = mode === 'auto';
  const isSweep = mode === 'sweep';
  const isAi = isAuto || isSweep;
  // The route, on the body, so CSS can hide what belongs to another route
  // without a display write per element — the "Element." caption over the
  // Whole-page controls is Manual's, and only CSS knows where it sits.
  document.body.dataset.mapMode = mode;
  if (isSweep && typeof syncSweepStartBtn === 'function') syncSweepStartBtn();
  for (const [btn, on] of [[$modeManualBtn, mode === 'manual'],
                           [$modeAutoBtn, isAuto],
                           [$modeSweepBtn, isSweep]]) {
    btn?.classList.toggle('active', on);
    btn?.setAttribute('aria-selected', String(on));
  }
  // Show one route at a time. In Automatic mode the type picker, the CSS
  // Selector field, the sub-selector form and the preview are all things you
  // never touch — the AI cards carry their own copies — so hiding them is what
  // actually makes this tab readable, rather than shrinking everything.
  const manualOnly = document.getElementById('manualOnly');
  if (manualOnly) manualOnly.style.display = isAi ? 'none' : '';
  // The sub-selector form and the preview are manual-route panels too, but they
  // sit OUTSIDE #manualOnly in the markup — so hiding that block left them on
  // screen. Open a type in Manual, switch to Automatic, and its Selectors form
  // and Generate Template button stayed under the AI cards. Their display is
  // stashed on the way out and restored on the way back, because which of them
  // was open depends on how far the manual flow had got.
  for (const el of [document.getElementById('subSelectorsSection'),
                    document.getElementById('previewSection')]) {
    if (!el) continue;
    if (isAi) {
      if (el.dataset.manualDisplay === undefined) el.dataset.manualDisplay = el.style.display || '';
      el.style.display = 'none';
    } else if (el.dataset.manualDisplay !== undefined) {
      el.style.display = el.dataset.manualDisplay;
      delete el.dataset.manualDisplay;
    }
  }
  // Each AI route has its own starting line — one scans a container, the other
  // scans everything — and only one of them belongs on screen at a time.
  const runRow = document.getElementById('aiRunRow');
  if (runRow) runRow.style.display = isAuto ? '' : 'none';
  const sweepRow = document.getElementById('sweepOnly');
  if (sweepRow) sweepRow.style.display = isSweep ? '' : 'none';
  // The assistant is a dialog now — it is opened on demand, not shown by
  // display, and leaving the AI routes must dismiss it rather than strand it.
  // Show a results panel only when it holds actual results. #aiResults has a
  // fixed shell (summary, list, buttons), so testing its own innerHTML would
  // always be truthy and leave an empty box with a dead button sitting there.
  // Count the CARDS, not the container. Both panels now hold a static carousel
  // shell, so testing the wrapper's children is always truthy and would leave
  // an empty carousel with dead arrows on screen.
  // ONE stage on screen. Restoring both — which is what happened when each had
  // content and they were toggled independently — puts the found list and the
  // mapping cards up together: two carousels with two positions again.
  // Whichever stage still has work to do is the one that comes back — and only
  // that one. setStage decides; nothing here writes display itself.
  if (!isAi) {
    setStage('none');
  } else if (isSweep && aiSweep.stops.length) {
    // Re-drawn rather than merely un-hidden. Testing for a pending row alone
    // missed the case where every screen read is already done: the survey is
    // still there, the completed drawer and the unread sections are still worth
    // seeing, and the panel came back empty.
    if (aiSweep.phase === 'components') renderSweepPicks(); else renderSweepScreens();
  } else {
    setStage(resumeStage());
  }
  // Leaving the sweep running while its own controls are hidden means a page
  // scrolling by itself with no way to stop it. Switching route stops it.
  if (!isSweep && aiSweep.running) aiSweep.abort = true;
}

/** Which stage still has work in it, for coming back to a route. */
function resumeStage() {
  if (document.querySelectorAll('#aiSlideTrack .ai-map-card:not([data-done])').length) return 'cards';
  if (document.querySelectorAll('#aiCompTrack .ai-comp:not([data-done])').length) return 'found';
  // Count the ROWS. The section is a <details> with a summary and a list in
  // the markup, so it always has children — which made it show itself even
  // when it had nothing to report.
  if (document.querySelectorAll('#aiApprovedList .ai-approved-row').length) return 'applied';
  return 'none';
}

// The key settings buttons in both AI modes used to open a modal. There is no
// modal any more — the key is a section in Setup — so they go there, the same
// way a locked mode pill does. One destination, however you arrive at it.
for (const id of ['aiSettingsBtn', 'sweepSettingsBtn']) {
  document.getElementById(id)?.addEventListener('click', () => {
    document.querySelector('.tab-btn[data-tab="setup"]')?.click();
    document.getElementById('aiKeySection')?.scrollIntoView({ block: 'center', behavior: 'smooth' });
  });
}

$modeManualBtn?.addEventListener('click', () => setMapMode('manual'));
// ── The two modes that cost money need a key before they mean anything ──────
//
// Both AI modes were freely selectable without one. Pressing either put you in
// front of the whole flow — the estimate, the tick list, the button — and the
// key was asked for at the LAST step, by a dialog, after all the choosing was
// done. "Paste your Anthropic API key first" is a fine sentence in the wrong
// place: it arrives once you have already decided what to spend.
//
// So the gate moves to the door. A locked mode says it is locked, says what
// unlocks it, and pressing it takes you to the place that unlocks it rather
// than simply refusing.
//
// `aiUnlocked` is declared with the rest of the module state at the top of the
// file, NOT here beside the function that owns it. Boot calls this at line
// ~2300 and this is line ~4590: a `let` is not hoisted-initialised, so the
// write below landed in the temporal dead zone, threw, and threw AGAIN out of
// the catch that was supposed to handle it. See the note up there.
async function refreshAiLocks() {
  try { aiUnlocked = !!(await U1AI.getKey()); } catch { aiUnlocked = false; }
  // The key section is a set-once field. Open while there is nothing in it —
  // it is the thing standing between you and two of the three Picker modes —
  // and folded away once there is, where it says only that it is saved.
  const det = document.getElementById('aiKeyDetails');
  if (det) det.open = !aiUnlocked;
  const flag = document.getElementById('aiKeyFlag');
  if (flag) {
    flag.textContent = aiUnlocked ? 'saved' : 'needed';
    flag.className = 'section-flag ' + (aiUnlocked ? 'is-ok' : 'is-needed');
  }
  for (const btn of [$modeAutoBtn, $modeSweepBtn]) {
    if (!btn) continue;
    btn.classList.toggle('is-locked', !aiUnlocked);
    // Not `disabled`. A disabled button is skipped by the keyboard and says
    // nothing about why — and this one has something to say and somewhere to
    // send you, which is the entire point of it.
    btn.setAttribute('aria-disabled', String(!aiUnlocked));
    // Unlocked, the title reverts to what the mode itself does (data-tip
    // carries the same text) rather than going empty — this button still
    // has an explanation, just not a lock notice any more.
    btn.title = aiUnlocked ? (btn.dataset.tip || '') : 'Needs an Anthropic API key — press to go and add one';
  }
}

/**
 * True when the mode may be entered. Otherwise: go to where it is unlocked,
 * and say so.
 *
 * Re-reads the key rather than trusting `aiUnlocked`. That flag is written by
 * refreshAiLocks, which is one step in a long boot sequence — and a flag that
 * says "locked" because the step that would have said otherwise did not run is
 * indistinguishable, at the point of the click, from a genuine no. Reported as:
 * clicking the AI tabs sends me to Setup now. Reading storage is one await and
 * removes the entire class of that.
 *
 * It also repaints the buttons, so a wrong answer corrects itself the first
 * time it is pressed instead of persisting for the life of the panel.
 */
async function aiModeAllowed() {
  await refreshAiLocks();
  if (aiUnlocked) return true;
  // Refusing silently is the worst of the three options. The panel simply
  // changed tab, and "why did it do that" is left to be worked out from a
  // section highlight two scrolls away.
  showNotice($aiKeyStatus,
    'That mode calls Claude, so it needs an Anthropic API key. Paste one here and it unlocks.',
    'warn', 8000);
  document.querySelector('.tab-btn[data-tab="setup"]')?.click();
  const box = document.getElementById('aiKeySection');
  const det = document.getElementById('aiKeyDetails');
  if (det) det.open = true;   // being sent to a folded heading explains nothing
  if (box) {
    // Guarded: a throw here would abandon this function before it returns
    // false, and the caller would get a rejected promise instead of "no".
    // Scrolling is the least important thing this does.
    try { box.scrollIntoView?.({ block: 'center', behavior: 'smooth' }); } catch {}
    // A tab change and a scroll is a lot of movement with no stated cause, so
    // the thing you were sent to says, briefly, that it is the thing.
    box.classList.add('is-calling');
    setTimeout(() => box.classList.remove('is-calling'), 2200);
  }
  return false;
}

$modeAutoBtn?.addEventListener('click', async () => { if (await aiModeAllowed()) setMapMode('auto'); });
$modeSweepBtn?.addEventListener('click', async () => { if (await aiModeAllowed()) setMapMode('sweep'); });



// ─────────────────────────────────────────────────────────────────────────────
//  AI MODE — two stages, and the specialist decides at both.
//
//  Stage 1  "Find what's on this page": screenshot with a number drawn on
//           every candidate element + the matching element list → an inventory
//           of components. Each row's TYPE and CONTAINER are editable inputs,
//           because a wrong guess must be correctable before it costs anything.
//  Stage 2  "Make these accessible": for each ticked row, the container's real
//           markup and its click-handler data go to Claude, which decides which
//           selector belongs in which field. The answer is rendered in THE SAME
//           form Manual mode uses — the AI replaces the typing, not the review.
//
//  Nothing is written to the mappings list until Save is pressed on a card, and
//  every selector still goes through the same U1 validation and strength meter.
// ─────────────────────────────────────────────────────────────────────────────

const $aiResults = document.getElementById('aiResults');
const $aiStatus = document.getElementById('aiStatus');
// The key now lives in Setup, and its notices have to appear THERE — $aiStatus
// is the Picker's own status line and is on a tab you are not looking at.
const $aiKeyStatus = document.getElementById('aiKeyStatus');
const $aiKeyRow = document.getElementById('aiKeyRow');
const $aiKeyInput = document.getElementById('aiKeyInput');

let aiFound = null;     // stage 1 result + the element context it was based on
let aiMapped = [];      // stage 2 cards, index-aligned with the DOM cards
// The site the results on screen belong to. Everything in this workspace is
// selectors from ONE page; carrying it to another site is how one client's
// mappings end up filed under another client's hostname.
let aiWorkspaceHost = null;

/**
 * Throws away every AI result on screen and in memory.
 *
 * Called whenever the panel changes site. The panel outlives the tab: switch
 * from one client to the next and the previous scan stayed on screen, still
 * actionable — and "Make all of these accessible" would have saved a whole
 * page of one client's selectors into the other client's mappings file, then
 * auto-applied them there on every panel open.
 */
/**
 * True when the results on screen were scanned on the site now being looked at.
 *
 * The last line of defence before anything is written. A stale workspace is not
 * a cosmetic problem: these selectors would be saved under whatever hostname is
 * current, which is a different client's file.
 */
function aiWorkspaceMatchesSite() {
  return !aiWorkspaceHost || aiWorkspaceHost === currentHostname;
}

function warnWrongSite(statusEl) {
  showNotice(statusEl,
    `These results were scanned on ${aiWorkspaceHost}, and you are now on ${currentHostname}. ` +
    `Saving them here would file one site's components under the other. Scan this page instead.`,
    'error', 10000);
  resetAiWorkspace();
}

// One parked workspace — the site it belongs to, its state, and where it was
// standing when its tab lost focus. null means the slot is empty.
let parkedAi = null;

// A single-element (Automatic) scan in flight, and the tab it was started on.
// The sweep has aiSweep.running for this; the Automatic route had nothing, so
// a tab change during the model call re-pointed the panel, cleared the
// workspace under it, and the answer landed nowhere.
let aiScanHold = null;

/**
 * Glancing at another tab must not destroy work in progress.
 *
 * Scan results, half-approved cards and a finished survey used to be RESET the
 * moment a tab on another site came to the front. The reason given was
 * cross-site safety, but every write path already refuses to save across
 * sites (aiWorkspaceHost is checked and warnWrongSite fires). So the whole
 * workspace is parked — state kept, view down — and coming back to its own
 * site puts it back up where it stood. One slot: parking a second site's work
 * replaces the first, which is still strictly better than the zero slots
 * there were.
 */
function parkAiWorkspace() {
  if (!aiWorkspaceHost) return;
  parkedAi = {
    host: aiWorkspaceHost, stage: currentStage, mode: mapMode,
    sweep: aiSweep, found: aiFound, mapped: aiMapped,
  };
  // The live slots are handed to the next site EMPTY — its own stored survey
  // must be able to restore, which restoreSweep refuses to do over non-empty
  // stops. Views down; state safe in the slot above.
  aiSweep = { running: false, abort: false, phase: 'screens', stops: [] };
  aiFound = null;
  aiMapped = [];
  aiWorkspaceHost = null;
  setStage('none');
}

function unparkAiWorkspaceFor(host) {
  if (!parkedAi || parkedAi.host !== host) return false;
  const p = parkedAi;
  parkedAi = null;
  aiSweep = p.sweep;
  aiFound = p.found;
  aiMapped = p.mapped;
  aiWorkspaceHost = p.host;
  if (p.mode && p.mode !== mapMode) setMapMode(p.mode);
  // Rebuilt from STATE, never by re-showing whatever DOM happened to survive:
  // scanning the other site while this one was parked would have overwritten
  // the card track, and setStage would then have proudly revealed the other
  // site's components under this site's name.
  if ((aiSweep.stops || []).length) {
    // A sweep redraws its own phase — its renderers know which of the two
    // views the stops belong in.
    if (aiSweep.phase === 'components') renderSweepPicks();
    else renderSweepScreens();
  } else if (aiFound) {
    renderAiComponents(aiFound);
  } else {
    setStage(p.stage);
  }
  return true;
}

function resetAiWorkspace() {
  aiFound = null;
  aiMapped = [];
  aiBulk = { running: false, abort: false, failed: [], armed: false };
  // A sweep in flight is scrolling the page, so clearing the workspace under it
  // has to stop it too — and its stops index into the aiMapped that just went.
  aiSweep.abort = true;
  aiSweep = { running: false, abort: false, phase: 'screens', stops: [] };
  aiWorkspaceHost = null;
  const hide = (id) => { const el = document.getElementById(id); if (el) el.style.display = 'none'; };
  const empty = (id) => { const el = document.getElementById(id); if (el) el.innerHTML = ''; };
  hide('aiResults'); hide('aiMappings'); hide('aiApproved'); hide('aiBulkReview');
  hide('sweepLog'); hide('sweepPicks');
  empty('aiCompTrack'); empty('aiSlideTrack'); empty('aiApproved');
  empty('aiBulkList'); empty('aiBulkSummary'); empty('aiSummary'); empty('sweepLog');
  empty('sweepPicksList'); empty('sweepPicksSummary');
}
let aiCost = 0;         // running spend for this panel session, in USD
let aiRowTimer = null;
let aiCardTimer = null;

// Nothing may reach a mapping that we did not observe on the page. A selector
// we produced is accepted outright; anything else only if every one of its
// simple tokens (.class / #id / [attr] / tag) came from one we produced. That
// allows the legitimate case — regrouping known classes into a comma group —
// while an invented name has nowhere to have come from and is rejected.
function checkAiSelector(value, context) {
  const intel = globalThis.__u1SelectorIntel;
  const norm = intel ? intel.normalize(value) : String(value || '').trim();
  if (!norm) return { ok: false, why: 'empty' };
  if (intel && !intel.isU1Valid(norm)) return { ok: false, why: 'U1 cannot use this selector (spaces or a pseudo-class)' };

  const known = new Set((context.candidates || []).map(c => c.selector).filter(Boolean));
  const TOKEN = /#[\w-]+|\.[\w-]+|\[[^\]]+\]|[a-z][\w-]*/gi;
  const knownTokens = new Set();
  // The names the page actually carries, straight off the elements. Without
  // these the set is only what robustSelector chose to EMIT — and it prefers
  // #id, so for <div class="tab-bar" id="faqTabs"> the class `.tab-bar` was in
  // no produced selector and was reported as invented while sitting on the
  // page. That is the tool refusing to map something it can see.
  for (const t of (context.tokens || [])) knownTokens.add(t);
  for (const s of known) for (const t of (s.match(TOKEN) || [])) knownTokens.add(t);

  const invented = [];
  for (const branch of norm.split(',')) {
    if (known.has(branch)) continue;
    for (const t of (branch.match(TOKEN) || [])) if (!knownTokens.has(t)) invented.push(t);
  }
  if (invented.length) {
    const list = [...new Set(invented)];
    // The set that proves it wrong is the set that can put it right, and
    // "handle this one by hand" is the tool declining to use what it holds.
    const near = list.map((t) => nearestToken(t, knownTokens)).filter(Boolean);
    return {
      ok: false,
      why: `invented — ${list.join(', ')} is on no element we found on the page` +
           (near.length ? ` — did you mean ${[...new Set(near)].join(', ')}?` : ''),
      suggest: [...new Set(near)],
    };
  }
  return { ok: true, value: norm };
}

/**
 * The known token closest to one that is not known, or '' when nothing is near.
 *
 * Ordinary edit distance, capped: `.tab-bar` against a page holding
 * `.tab-bar__btn` should offer it, while `.completely-different` should offer
 * nothing rather than the least-bad of a hundred unrelated names.
 */
function nearestToken(bad, knownTokens) {
  const a = String(bad || '');
  if (!a) return '';
  let best = '', bestD = Infinity;
  for (const t of knownTokens) {
    // Only compare like with like — a class is never the answer for an id.
    if (t[0] !== a[0]) continue;
    const d = editDistance(a, t);
    if (d < bestD) { bestD = d; best = t; }
  }
  // Half the length, so short names need a close match and long ones may differ
  // by a suffix — which is what BEM does.
  return bestD <= Math.max(2, Math.floor(a.length / 2)) ? best : '';
}

function editDistance(a, b) {
  if (a === b) return 0;
  const prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let last = prev[0];
    prev[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = prev[j];
      prev[j] = Math.min(prev[j] + 1, prev[j - 1] + 1, last + (a[i - 1] === b[j - 1] ? 0 : 1));
      last = tmp;
    }
  }
  return prev[b.length];
}

// The dialog is only ever about the key, so the row is always there and this
// button does the one thing you actually want beside a password field: let you
// read back what you pasted before committing to it.
document.getElementById('aiKeyToggle')?.addEventListener('click', (e) => {
  if (!$aiKeyInput) return;
  const hidden = $aiKeyInput.type === 'password';
  $aiKeyInput.type = hidden ? 'text' : 'password';
  e.currentTarget.textContent = hidden ? 'Hide' : 'Show';
  $aiKeyInput.focus();
});

// Reflect whether a key is saved, without ever rendering the key back.
async function markKeyState() {
  if (!$aiKeyInput || !globalThis.U1AI) return false;
  const saved = await U1AI.getKey();
  $aiKeyInput.placeholder = saved ? '•••••••• saved — type to replace' : 'sk-ant-…';
  const settings = document.getElementById('aiSettingsBtn');
  if (settings) settings.title = saved ? 'Change the API key' : 'No API key yet — click to add one';
  return !!saved;
}

// Open the key field on first use rather than hiding it behind an icon: with it
// collapsed, the instruction box is the only thing that looks like an input,
// which is exactly how a key ends up pasted into the prompt.
// Runs at panel load, so it must not take the rest of panel.js down with it if
// ai-advisor.js is missing — Manual mode does not depend on the AI layer.
(async () => {
  try {
    if (!$aiKeyRow || !globalThis.U1AI) return;
    const hasKey = await markKeyState();
    if (!hasKey) $aiKeyRow.style.display = '';
    // A first run needs the key, so ask for it up front. After that the dialog
    // is behind ⚙ and the screen belongs to the results.
    if (!hasKey && mapMode === 'auto') await aiModeAllowed();   // sends you to Setup
  } catch {}
})();

// An API key pasted into the instruction box would be sent to Claude as prompt
// text — a real leak, and an easy mistake to make when both fields sit in the
// same panel. Catch it on the way in: move it to the key field and say so,
// rather than letting it sit there looking accepted.
const LOOKS_LIKE_KEY = /\bsk-ant-[A-Za-z0-9_-]{10,}/;

// A key pasted into the wrong field should still end up saved rather than sent
// somewhere it does not belong. The instruction box is gone, so this now only
// guards the key field: strip anything around the key and keep the key.
$aiKeyInput?.addEventListener('input', () => {
  const val = $aiKeyInput.value;
  if (!LOOKS_LIKE_KEY.test(val) || LOOKS_LIKE_KEY.exec(val)[0] === val.trim()) return;
  $aiKeyInput.value = (val.match(LOOKS_LIKE_KEY) || [])[0];
});

document.getElementById('aiKeySave')?.addEventListener('click', async () => {
  const val = ($aiKeyInput.value || '').trim();
  if (!val) { showNotice($aiKeyStatus, 'Paste a key first.', 'error', 3000); return; }
  await U1AI.setKey(val);
  $aiKeyInput.value = '';
  $aiKeyInput.placeholder = '•••••••• (saved — type to replace)';
  $aiKeyRow.style.display = 'none';
  showNotice($aiKeyStatus, 'Key saved on this machine.', 'success', 3000);
  // The two locked modes unlock on this press, not on the next panel open.
  await refreshAiLocks();
});

// Run selector-intel in the page (injecting it first, idempotently).
async function inPage(tabId, fn, args) {
  await chrome.scripting.executeScript({ target: { tabId }, files: ['selector-intel.js'] });
  const res = await chrome.scripting.executeScript({ target: { tabId }, func: fn, args: args || [] });
  return res && res[0] ? res[0].result : null;
}

// Screenshot the visible tab and scale it down. The long edge is capped at
// 1568px: Claude accepts up to 2576px, but a full-resolution image costs up to
// ~3x the image tokens and this review does not need that fidelity.
function scaleShot(dataUrl, maxEdge) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const long = Math.max(img.width, img.height);
      const scale = long > maxEdge ? maxEdge / long : 1;
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(img.width * scale));
      canvas.height = Math.max(1, Math.round(img.height * scale));
      canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
      resolve(canvas.toDataURL('image/jpeg', 0.85));
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
  });
}

// ── Stage 1: discover what is on the screen ─────────────────────────────────
// Scan after a countdown, so a dialog or menu can be opened and LEFT open.
// Pressing anything in this panel moves focus off the page, and a great many
// widgets close on focus-out — which is why "just open it first" does not work
// on its own. The countdown hands the page back to you before the capture.
// A fixed 5-second count then one shot at collectRegion meant a dialog that
// took six seconds to find on the page — or a user who needed a moment
// longer — landed on "Nothing reviewable inside X, check the selector, and
// open it if it is a dialog," which reads as a wrong selector even when the
// selector was always right. Collection itself is free (no model call, see
// collectRegion above), so there is nothing to lose by polling for it
// instead of guessing one delay for every dialog on every site. Capped, and
// cancellable, so it does not poll forever if the dialog never opens.
let aiDelayedPollActive = false;
document.getElementById('aiDelayedBtn')?.addEventListener('click', async (e) => {
  const btn = e.currentTarget;
  const original = btn.textContent;

  if (aiDelayedPollActive) { aiDelayedPollActive = false; return; } // second click cancels

  aiDelayedPollActive = true;
  btn.classList.add('is-polling');
  const MAX_MS = 60000, TICK_MS = 1200;
  let started = Date.now();
  try {
    const tab = await getTab();
    if (!isInjectable(tab)) { showNotice($aiStatus, 'Cannot read this page.', 'error', 4000); return; }
    const scopeSel = (document.getElementById('aiScopeInput')?.value || '').trim();
    const handled = await alreadyHandled();

    let idleSince = null;
    while (aiDelayedPollActive && Date.now() - started < MAX_MS) {
      // Collection captures a screenshot, and a screenshot of a background
      // tab blocks inside captureScreen until the tab is visible again — for
      // up to ten minutes, breakable only by a sweep's abort flag this flow
      // never sets. So the tick is skipped while the tab is hidden, and the
      // sixty-second clock stops with it: time spent on another tab is not
      // time the dialog failed to open.
      if (!(await pinnedTabIsVisible(tab))) {
        if (idleSince == null) idleSince = Date.now();
        btn.textContent = '⏱ Paused — come back to the page’s tab (click to cancel)';
        await new Promise(r => setTimeout(r, TICK_MS));
        continue;
      }
      if (idleSince != null) { started += Date.now() - idleSince; idleSince = null; }
      const elapsed = Math.round((Date.now() - started) / 1000);
      btn.textContent = `⏱ Looking… open it now (${elapsed}s, click to cancel)`;
      const collected = await collectRegion(tab, scopeSel, handled);
      if (aiDelayedPollActive && collected && !collected.err && collected.candidates && collected.candidates.length) {
        document.getElementById('aiDiscoverBtn')?.click();
        return;
      }
      await new Promise(r => setTimeout(r, TICK_MS));
    }
    if (aiDelayedPollActive) {
      showNotice($aiStatus, `Still nothing after ${Math.round(MAX_MS / 1000)}s — check the selector, or press this again once the dialog is open.`, 'error', 8000);
    }
  } finally {
    aiDelayedPollActive = false;
    btn.classList.remove('is-polling');
    btn.textContent = original;
  }
});

document.getElementById('aiDiscoverBtn')?.addEventListener('click', async () => {
  const btn = document.getElementById('aiDiscoverBtn');
  const tab = await getTab();
  if (!isInjectable(tab)) { showNotice($aiStatus, 'Cannot read this page.', 'error', 4000); return; }
  if (!(await U1AI.getKey())) {
    $aiKeyRow.style.display = '';
    showNotice($aiStatus, 'Paste your Anthropic API key first.', 'error', 4000);
    return;
  }

  const original = btn.textContent;
  btn.disabled = true;
  // A scan in flight owns the panel, exactly as a sweep does. Without this,
  // glancing at another tab while the model was answering re-pointed the
  // panel, cleared the workspace under the call, and the answer landed
  // nowhere — reported as "it started scanning, I changed tab, and that was
  // that". Pinned to the tab it was started on, so the answer can only ever
  // be filed against the page it was asked about.
  aiScanHold = { tabId: tab.id, host: currentHostname };
  try {
    const scopeSel = (document.getElementById('aiScopeInput')?.value || '').trim();
    // The same truth machinery the walk has: the ring, the clock, the stop,
    // and a log line per stage — 'I scanned one element and it got stuck'
    // was unanswerable because this flow reported nothing on the way.
    sweepLog(0, `scoped scan${scopeSel ? ' ' + scopeSel : ''}: reading the page`, 'info');
    showSweepBusy('Scoped scan — reading', scopeSel ? `Looking inside ${scopeSel}.` : 'Looking at what is on screen.', null);
    showAiBusy('Reading…', scopeSel ? `Looking inside ${scopeSel}.` : 'Looking at what is on screen.');
    btn.textContent = 'Reading…';

    // Drop what this site has already settled. The same page gets scanned again
    // and again to reach things that only exist while open, and re-listing what
    // was skipped or already mapped is how that becomes tedious. Filtering here
    // rather than after the answer also means no tokens are spent on them.
    const handled = await alreadyHandled();

    // ONE region, ONE call. Sixty candidates is the collector's cap, so a whole
    // page either summarises the widget you actually care about away or costs a
    // call per section — and one answer covering everything is harder to check
    // than five answers covering one region each. Point at a container instead.
    const collected = await collectRegion(tab, scopeSel, handled);
    if (collected.err) {
      sweepLog(0, `scoped scan: could not read the page — ${collected.err}`, 'err');
      showNotice($aiStatus, collected.err, 'error', 5000);
      return;
    }
    if (!collected.candidates.length) {
      sweepLog(0, `scoped scan: nothing reviewable${scopeSel ? ` inside ${scopeSel}` : ''}`, 'skip');
      showNotice($aiStatus, scopeSel
        ? `Nothing reviewable inside ${scopeSel} — check the selector, and open it if it is a dialog.`
        : 'Nothing reviewable on screen that has not already been mapped or skipped. Scroll to the part you want, or name a container above.',
        'success', 7000);
      return;
    }

    sweepLog(0, `scoped scan: asking Claude about ${collected.candidates.length} element${collected.candidates.length === 1 ? '' : 's'}`, 'info');
    showSweepBusy('Scoped scan — asking Claude', `${collected.candidates.length} elements — usually 10–30 seconds.`, null);
    showAiBusy('Claude is looking…', 'Usually 10–30 seconds.');
    btn.textContent = 'Looking…';
    $aiStatus.textContent = 'Usually 10–30 seconds.';
    $aiStatus.className = 'map-mode-hint';
    $aiStatus.style.display = '';

    const part = await U1AI.discover({
      screenshot: collected.shot,
      // These were being dropped, so every prompt said "Page: (untitled)", an
      // empty URL, and — worse — the literal "The page has NO headings at all."
      // even on pages full of them. The heading-order rule was being fed a lie.
      context: {
        candidates: collected.candidates,
        headings: collected.headings,
        title: collected.title,
        url: collected.url,
      },
      scope: scopeSel || undefined,
    });
    if (!part || part.err) {
      sweepLog(0, `scoped scan: no answer — ${part?.err || 'the model returned nothing'}`, 'err');
      showNotice($aiStatus, part?.err || 'No answer from the model.', 'error', 8000);
      return;
    }

    aiCost += U1AI.estimateCost(part.usage) || 0;
    const mergedContext = { candidates: collected.candidates, tokens: collected.tokens || [] };
    let found = part.components || [];

    // You pointed at ONE element. Handle that element.
    //
    // Typing `.signin` and pressing Scan it came back with three components,
    // because everything inside a container is, technically, inside it — the
    // dropdown, the Register link, the wrapper. All true, none of them what was
    // asked. The scoped box is a way of saying "this one", and answering with an
    // inventory means picking your component out of a list you did not want.
    //
    // The others are counted and named, not silently dropped: the scan saw them
    // and that is worth knowing. They are simply not the answer.
    let alsoInside = [];
    if (scopeSel && found.length > 1) {
      const ranked = await inPage(tab.id, (scope, sels) => {
        const el = (s) => { try { return document.querySelector(s); } catch { return null; } };
        const target = el(scope);
        if (!target) return null;
        return sels.map((s) => {
          const node = el(s);
          if (!node) return 2;
          if (node === target) return 0;              // it IS what was asked for
          // Otherwise the outermost thing inside it is the best reading of
          // "this one" — a wrapper's single real widget, rather than its parts.
          return target.contains(node) ? 1 : 2;
        });
      }, [scopeSel, found.map((c) => c.containerSelector)]);

      if (ranked) {
        const best = Math.min(...ranked);
        const keep = [], rest = [];
        found.forEach((c, i) => (ranked[i] === best ? keep : rest).push(c));
        // Several equally-good candidates means the scope really is a wrapper
        // round separate widgets, and listing them all is the honest answer.
        if (keep.length === 1) { found = keep; alsoInside = rest; }
      }
    }

    // You named an element; the card must be about THAT element.
    //
    // Pointing at `#state-select-modal-find-doctor` came back as a card whose
    // Element was `#state-select-modal-find-doctor>div.modal-dialog` — a
    // generic inner wrapper of the thing asked about, which is the exact
    // mistake the dialog advisor already warns against ("point it at the
    // outer modal container with a unique id, not a generic inner wrapper").
    // A typed selector is a decision, not a hint, so it is what the card is
    // rooted on; the model's deeper pick is kept in view rather than dropped,
    // because on a wrapper round a real widget it is sometimes the better
    // answer and the field stays editable.
    if (scopeSel && found.length === 1) {
      const inner = found[0].containerSelector || '';
      const isDescendant = inner && inner !== scopeSel && await inPage(tab.id, (scope, s) => {
        const el = (x) => { try { return document.querySelector(x); } catch { return null; } };
        const target = el(scope), node = el(s);
        return !!(target && node && node !== target && target.contains(node));
      }, [scopeSel, inner]);
      if (isDescendant) {
        found = [{ ...found[0], containerSelector: scopeSel,
          why: `${found[0].why || ''} (You pointed at ${scopeSel}, so that is what this is ` +
               `rooted on. The scan would have picked ${inner} — use that instead if the ` +
               `component really is only that inner part.)`.trim() }];
      }
    }

    const out = { components: found, usage: part.usage,
                  skipped: collected.skipped, scope: scopeSel || '',
                  alsoInside: alsoInside.map((c) => c.label || c.containerSelector) };
    if (!out.components.length) {
      sweepLog(0, `scoped scan: the model found nothing worth mapping${scopeSel ? ` inside ${scopeSel}` : ''}`, 'skip');
      showNotice($aiStatus, scopeSel
        ? `Nothing worth mapping inside ${scopeSel}.`
        : 'Nothing worth mapping on screen right now.', 'success', 7000);
      return;
    }
    const context = mergedContext;

    // Deliberately NOT re-marking here. The 👁 buttons work off each row's
    // container selector, so they need nothing on the page — and re-marking
    // left data-u1-mark attributes scattered across the site's DOM, which both
    // pollutes what the specialist is inspecting and lands in any markup they
    // copy out of DevTools.
    const audit = await auditSurveyComponents(out.components, tab);
    out.components = audit.comps;
    aiFound = { ...out, context, audit: { dropped: audit.dropped, retyped: audit.retyped } };
    // Stamp the site these selectors came from. onTabChanged clears the
    // workspace on a switch, but the panel can also be looking at a tab that
    // changed under it — so the act of saving checks this again.
    aiWorkspaceHost = currentHostname;
    sweepLog(0, `scoped scan: ${out.components.length} component${out.components.length === 1 ? '' : 's'} found`, 'info');
    renderAiComponents(aiFound);
    $aiStatus.style.display = 'none';
  } catch (err) {
    sweepLog(0, 'scoped scan failed: ' + err.message, 'err');
    showNotice($aiStatus, 'Failed: ' + err.message, 'error', 6000);
  } finally {
    clearSweepBusy();
    // The tab that was SCANNED, read before the hold comes down — the front
    // tab is not it if the user wandered off mid-call, and clearing marks on
    // the front tab left them standing on the scanned one.
    const heldTabId = aiScanHold && aiScanHold.tabId;
    aiScanHold = null;
    clearSweepHoldsPanel();
    clearAiBusy();
    btn.disabled = false;
    btn.textContent = original;
    // Belt and braces: never leave our own attributes on the site's DOM, even
    // if something threw between stamping and the capture's own cleanup.
    try {
      const t = heldTabId != null
        ? await chrome.tabs.get(heldTabId).catch(() => null)
        : await getTab();
      if (t && isInjectable(t)) await inPage(t.id, () => window.__u1SelectorIntel.clearMarks());
    } catch {}
    // The panel was held on the scanned site while the call ran; whatever tab
    // is in front now decides what it shows next.
    const front = await getTab();
    if (front) await onTabChanged(front);
  }
});

/**
 * Collect one region for the model: the candidates inside `scopeSel`, or what is
 * on screen when no container is given, plus the numbered screenshot of it.
 *
 * One region, one call. The collector caps at sixty candidates, so pointing at a
 * container is not a limitation to work around — it is what keeps the widget you
 * care about from being summarised away, and it keeps each answer small enough
 * to actually check.
 *
 * `opts.drop(candidate)` is an extra filter applied before anything is captured
 * or sent, so what it rejects costs nothing. The sweep uses it to leave out the
 * sticky header it already dealt with on the first section.
 *
 * `opts.thumb` also takes a picture WITHOUT the pink numbers on it. That one is
 * never sent anywhere — it is what the approval screen shows beside "screen 4"
 * so a row can be placed on the page without scrolling back to find it.
 *
 * `opts.surveyOnly` stops before the part that costs anything: the candidates
 * are collected (that is in-page code, free and instant) and the plain picture
 * is taken, but the numbers are never drawn and the big screenshot for the model
 * is never made. It is what lets the sweep photograph fifteen sections in
 * twenty seconds so you can choose which of them is worth paying to read.
 */
async function collectRegion(tab, scopeSel, handled, opts) {
  // COLLECTION is free — it is in-page code and nothing leaves the browser —
  // so both the survey and the read collect the whole section. The token budget
  // belongs to the model call, and it is applied there, in batches, so that a
  // section bigger than one batch costs another call instead of losing its tail.
  //
  // It used to be applied here, as a blind head-cut at sixty in DOM order. A
  // 97-element section was surveyed as "6 menus · form · dialog? · carousel?"
  // and then read as its first sixty elements: the whole sticky header and the
  // top of the mega menu, stopping before the form and the carousel ever came
  // into view. They were not mis-detected and not filtered — they were never
  // collected. The survey had seen them, the estimate had charged for them, and
  // nothing anywhere said that thirty-seven elements had been dropped.
  const limit = SWEEP_COLLECT_MAX;
  const context = await inPage(tab.id,
    (n, within) => window.__u1SelectorIntel.collectCandidates(n, within), [limit, scopeSel || null]);
  if (!context) return { err: 'Could not read the page.' };
  if (!context.candidates || !context.candidates.length) {
    return { candidates: [], headings: [], skipped: 0 };
  }

  const drop = (opts && opts.drop) || null;
  const before = context.candidates.length;
  const candidates = context.candidates.filter((c) => {
    if (c.selector && handled.has(c.selector)) return false;
    return !(drop && drop(c));
  });
  const skipped = before - candidates.length;
  if (!candidates.length) return { candidates: [], headings: [], skipped };

  // The survey's own picture, with a labelled box round each component that was
  // recognised. It is what the sections list is chosen from, so it shows the
  // finding rather than describing it — and it costs nothing, because drawing
  // and capturing never involve the model.
  let thumb = null;
  // captureVisibleTab photographs the tab in FRONT of the window, whatever id
  // it is handed. A survey keeps running while you work in another tab, so
  // taking the picture anyway would file a photograph of a different page
  // against this section. No picture is honest; the wrong one is not.
  // With the background camera attached the picture is always of THIS tab, so
  // there is nothing to guard against. Without it, a thumbnail of whatever the
  // user happens to be looking at is worse than no thumbnail.
  if (opts && opts.thumb && !sweepCam.attached && !(await pinnedTabIsVisible(tab))) {
    opts = { ...opts, thumb: false };
  }
  if (opts && opts.thumb) {
    try {
      // Including what the PROBE found. The boxes were drawn from the read
      // candidates alone, so a component discovered by pressing it was named in
      // the text and drawn nowhere — on a page where reading finds nothing,
      // that is every box on the picture.
      const drawn = candidates.concat((opts.observed || []).map((c) => ({
        mark: null, selector: c.root, component: c.type, maybe: false, observed: true,
      })));
      await inPage(tab.id, (list) => window.__u1SelectorIntel.drawComponentMarks(list), [drawn]);
      await new Promise(r => setTimeout(r, 200));   // let the overlay paint
      const shot = await captureScreen(tab, 72);
      // Wide enough for the labels to be readable in the 340px hover preview and
      // the full-size view. A sweep holds one per section for the session.
      thumb = await scaleShot(shot, 760);
    } catch { thumb = null; }   // a missing picture must not stop the survey
    finally { await inPage(tab.id, () => window.__u1SelectorIntel.clearMarks()); }
  }

  if (opts && opts.surveyOnly) {
    // Everything below this line exists to build the model's input. A survey
    // never calls the model, so it stops here — and leaves the page untouched,
    // since the numbers were never drawn.
    return {
      shot: null, thumb, candidates, skipped, truncated: !!context.truncated,
      headings: context.headings || [], title: context.title || '', url: context.url || '',
      tokens: context.tokens || [],
    };
  }

  // Draw the numbers, capture, then clear them again immediately so the page is
  // left as it was even if the request fails.
  await inPage(tab.id, () => window.__u1SelectorIntel.drawMarks());
  await new Promise(r => setTimeout(r, 250)); // let the overlay paint
  let shot = null;
  // The picture IS the request, so it has to be a picture of THIS page. Wait
  // for the page to be in front rather than photographing whatever is, and
  // rather than dying — which is what happened before.
  try {
    const raw = await captureScreen(tab, 85, () => showSweepBusy(
      'Waiting for the page',
      'Without the background camera the scan needs its own tab in front. Switch back and it carries on from here — nothing is lost.'));
    // 1568 is the size Anthropic recommends for maximum image fidelity, and this
    // task does not need it: the model is reading two-digit pink numbers, not
    // fine detail. 1280 keeps them legible and costs about a third fewer tokens.
    shot = raw ? await scaleShot(raw, 1280) : null;
  } catch (err) {
    // One section that could not be photographed is one section lost. The
    // loop above knows how to skip a screen and carry on; a throw from here
    // reached the run's outer catch and ended everything.
    shot = null;
  } finally {
    // `keepMarks` leaves the numbers on the page. They are the only binding
    // between a row in the panel and an element in the page — clearMarks strips
    // the attribute — so anything that wants to ask "which element is number 7"
    // after the capture has to hold onto them. The caller that does is the
    // labelling pause; everyone else still gets the page left as it was found.
    if (!(opts && opts.keepMarks)) {
      await inPage(tab.id, () => window.__u1SelectorIntel.clearMarks());
    }
  }
  if (!shot) return { err: 'Could not capture the page.' };

  return {
    shot, thumb, candidates, skipped,
    headings: context.headings || [],
    title: context.title || '',
    url: context.url || '',
    // Carried so a candidate's `box` — which is in CSS pixels — can be turned
    // into a crop rectangle on `shot`, which is a scaled capture. Without the
    // width it was taken at, the two coordinate systems cannot be related.
    viewport: context.viewport || null,
    // Every id, class and tag actually on the page. checkAiSelector needs them
    // to tell a real name from an invented one, and the selector fields need
    // them to offer anything at all — dropping them here is why `.tab-bar` was
    // refused while sitting on the page.
    tokens: context.tokens || [],
  };
}


// Something to look at while it works. A panel that sits still for thirty
// seconds reads as broken, and the two slow steps here are a screenshot and a
// model call — neither of which can report progress, so the least we can do is
// say which one is running.
// `pct` turns the indeterminate sweep bar into a real progress bar. A scan that
// visits twenty sections needs to say how far along it is, or it reads as a
// page scrolling by itself forever.
function showAiBusy(title, sub, pct) {
  const results = document.getElementById('aiResults');
  const track = document.getElementById('aiCompTrack');
  if (!results || !track) return;
  results.style.display = 'block';
  const head = track.previousElementSibling;
  if (head) head.style.display = 'none';
  document.getElementById('aiSummary').innerHTML = '';
  const determinate = typeof pct === 'number' && isFinite(pct);
  const clamped = determinate ? Math.max(0, Math.min(100, Math.round(pct))) : 0;
  track.innerHTML = `
    <div class="ai-busy">
      <div class="ai-busy-bar${determinate ? ' determinate' : ''}">
        <span${determinate ? ` style="width:${clamped}%"` : ''}></span>
      </div>
      <div class="ai-busy-title">${escapeHtml(title)}${determinate ? ` — ${clamped}%` : ''}</div>
      <div class="ai-busy-sub">${escapeHtml(sub || '')}</div>
      ${[0, 1, 2].map(() => '<div class="ai-skel"></div>').join('')}
    </div>`;
}

/**
 * Take the spinner down.
 *
 * showAiBusy writes itself into the results track, and the success path
 * overwrites it by rendering the components. Every OTHER path did not: "nothing
 * reviewable inside .click-nav", "nothing worth mapping", a failed call — each
 * returned early and left the spinner turning over an empty panel with the real
 * message somewhere below it. Pressing Scan it and watching nothing happen was
 * the tool working correctly and saying so underneath a spinner.
 *
 * Only clears if the busy markup is still what is in the track, so calling it
 * after a successful render cannot wipe the results.
 */
function clearAiBusy() {
  const track = document.getElementById('aiCompTrack');
  if (!track || !track.querySelector('.ai-busy')) return;
  track.innerHTML = '';
  const results = document.getElementById('aiResults');
  if (results && !document.querySelector('#aiCompTrack .ai-comp')) {
    results.style.display = 'none';
  }
}

function showMapBusy(label, n, total) {
  const track = document.getElementById('aiSlideTrack');
  if (!track) return;
  // It used to bail whenever a card was already in the track, which meant the
  // FIRST component showed progress and every one after it left the panel
  // standing empty — an outlined box with a heading and nothing in it. The
  // placeholder is its own element, so it can sit alongside finished cards.
  clearMapBusy();
  const holder = document.createElement('div');
  holder.id = 'aiMapBusyHost';
  track.appendChild(holder);
  holder.innerHTML = `
    <div class="ai-busy" id="aiMapBusy">
      <div class="ai-busy-bar"><span></span></div>
      <div class="ai-busy-title">Working out ${escapeHtml(label)} (${n} of ${total})</div>
      <div class="ai-busy-sub">Reading its markup and its click handlers.</div>
      ${[0, 1, 2, 3].map(() => '<div class="ai-skel"></div>').join('')}
    </div>`;
  // Existing cards are hidden while this runs, or the placeholder appears below
  // a card and nobody scrolls to it.
  track.querySelectorAll('.ai-map-card').forEach(c => { c.style.display = 'none'; });
}

function clearMapBusy() {
  document.getElementById('aiMapBusyHost')?.remove();
  document.getElementById('aiMapBusy')?.remove();
}

// The sweep's progress, in its own panel rather than Automatic mode's.
//
// It used to call showAiBusy, which draws into #aiCompTrack — inside #aiResults,
// which also holds "✨ Make all of these accessible" and "Clear". A running
// sweep therefore showed two buttons from the other route, both of which would
// have acted on an empty inventory. Same look, its own container.
// A clock on the current step.
//
// "It has been five minutes on the last screen — how do I know what state it is
// in?" A percentage answers how far along the RUN is and says nothing about
// whether this step is alive. Under a line reading "usually 10-30 seconds", an
// elapsed count of 4:37 is the whole answer, and it needs no interpretation.
let sweepBusyTimer = null;

// The stop lives ON the progress card ('loved it — just needs a cancel').
// One delegated listener; the card is re-rendered on every step. It stops
// whichever run is going — the walk, the bulk build, or both — after the
// step in flight, and says so where the title was.
document.addEventListener('click', (e) => {
  const btn = e.target.closest('.ai-busy-stop');
  if (!btn) return;
  aiSweep.abort = true;
  if (typeof aiBulk === 'object' && aiBulk) aiBulk.abort = true;
  const title = btn.closest('.ai-busy')?.querySelector('.ai-busy-title');
  if (title) title.textContent = 'Stopping after the current step…';
  btn.disabled = true;
});

/**
 * The pinned progress banner.
 *
 * `sub` is one short line — this is position:fixed over the panel, so its
 * height is the amount of the panel it hides, and a three-line message covered
 * the list it was reporting on. `long` is the full sentence, on the tooltip:
 * worth saying, not worth three lines of a fixed header on every section of a
 * thirty-section run.
 */
/**
 * Light the element being mapped, on the page, while the ring works — the
 * build stops being an abstract counter when the purple ring lands on the
 * thing it is talking about. Falls back to the trigger when the primary has
 * no box (a closed dropdown's list), exactly like the drawer's hover.
 */
async function spotlightBuild(tab, sel, alt) {
  if (!sel || !tab || !isInjectable(tab)) return;
  try {
    await inPage(tab.id, (x, a) => {
      const S = window.__u1SelectorIntel;
      const shown = (q) => {
        try { const el = document.querySelector(q); if (!el) return false;
          const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0; } catch { return false; }
      };
      if (!shown(x) && a && shown(a)) return S.highlightSelector(a);
      return S.highlightSelector(x);
    }, [sel, alt || '']);
  } catch {}
}

async function spotlightOff(tab) {
  if (!tab || !isInjectable(tab)) return;
  try { await inPage(tab.id, () => window.__u1SelectorIntel.clearHilite()); } catch {}
}

function showSweepBusy(title, sub, pct, long) {
  const host = document.getElementById('sweepBusy');
  if (!host) return;
  // Pinned for the duration, because the picks list below it is long enough
  // that the progress bar sits off-screen for the whole run.
  host.classList.add('pinned');
  const determinate = typeof pct === 'number' && isFinite(pct);
  const clamped = determinate ? Math.max(0, Math.min(100, Math.round(pct))) : 0;
  // A RING, centred in the panel (owner: the panel cannot be touched while
  // a run works anyway, so the middle of it is free real estate). r=52 →
  // circumference ≈ 326.7; determinate progress is the dashoffset.
  const C = 326.7;
  host.innerHTML = `
    <div class="ai-busy${determinate ? '' : ' is-indeterminate'}">
      <div class="ai-busy-ring">
        <svg viewBox="0 0 120 120" aria-hidden="true">
          <circle class="ring-track" cx="60" cy="60" r="52"></circle>
          <circle class="ring-fill" cx="60" cy="60" r="52"
            stroke-dasharray="${C}" stroke-dashoffset="${determinate ? (C * (1 - clamped / 100)).toFixed(1) : C * 0.75}"></circle>
        </svg>
        <div class="ai-busy-pct">${determinate ? `${clamped}<span>%</span>` : '…'}</div>
      </div>
      <div class="ai-busy-title">${escapeHtml(title)}</div>
      <div class="ai-busy-sub" title="${escapeHtml(long || sub || '')}">${escapeHtml(sub || '')} <span class="ai-busy-clock" id="sweepBusyClock">0:00</span></div>
      <button type="button" class="ai-busy-stop" title="Stop after the current step — everything already saved stays saved">■ Stop</button>
    </div>`;

  // Restarted per step, because the number that matters is how long THIS step
  // has taken — a total would keep rising through a run that is behaving.
  clearInterval(sweepBusyTimer);
  const startedAt = Date.now();
  const paint = () => {
    const el = document.getElementById('sweepBusyClock');
    if (!el) { clearInterval(sweepBusyTimer); return; }
    const secs = Math.round((Date.now() - startedAt) / 1000);
    el.textContent = `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}`;
    el.classList.toggle('is-long', secs > 60);
    // A long step with a silent card reads as STUCK ('I switched tabs and it
    // froze' — at 2:11 on a busy section the run was alive and streaming).
    // Say what the silence means, once, in place.
    if (secs > 90) {
      const card = document.querySelector('#sweepBusy .ai-busy');
      if (card && !card.querySelector('.ai-busy-patience')) {
        card.querySelector('.ai-busy-sub')?.insertAdjacentHTML('afterend',
          '<div class="ai-busy-patience">Still working — a very busy section can take several minutes. ' +
          'The run watches its own line and gives up by itself if the answer goes quiet, ' +
          'so a climbing clock means it is alive.</div>');
      }
    }
  };
  sweepBusyTimer = setInterval(paint, 1000);
  paint();
}

/**
 * Move the bar and reword the line WITHOUT restarting the step.
 *
 * showSweepBusy rebuilds the banner and resets the clock, which is right when
 * a new step begins and wrong many times a second while one is running: the
 * elapsed time would sit at 0:00 for the whole call, which is the one number
 * that was telling the truth before any of this.
 */
function updateSweepBusy(pct, sub) {
  const host = document.getElementById('sweepBusy');
  if (!host) return;
  const clamped = Math.max(0, Math.min(100, Math.round(pct)));
  const ring = host.querySelector('.ring-fill');
  if (ring) {
    host.querySelector('.ai-busy')?.classList.remove('is-indeterminate');
    ring.style.strokeDashoffset = (326.7 * (1 - clamped / 100)).toFixed(1);
  }
  const pctEl = host.querySelector('.ai-busy-pct');
  if (pctEl) pctEl.innerHTML = `${clamped}<span>%</span>`;
  // The percent lives in the ring's middle now — the title stays words.
  // The clock is a child of the sub line and is repainted by its own interval,
  // so the text is replaced around it rather than through innerHTML.
  const subEl = host.querySelector('.ai-busy-sub');
  if (subEl && typeof sub === 'string') {
    const clock = subEl.querySelector('.ai-busy-clock');
    subEl.textContent = sub + ' ';
    if (clock) subEl.appendChild(clock);
  }
}

function clearSweepBusy() {
  clearInterval(sweepBusyTimer);
  sweepBusyTimer = null;
  const host = document.getElementById('sweepBusy');
  if (host) { host.innerHTML = ''; host.classList.remove('pinned'); }
  markScreenReading(null);
}

/**
 * Which section is being read, marked in the list itself.
 *
 * The percentage says how far along a run is; this says where it is. On a list
 * of twenty-six that is the difference between "something is happening" and
 * "that one, the one I am looking at".
 */
/**
 * A section that has just been read, marked in the list as it happens.
 *
 * Nothing updated the list during a run: it stayed exactly as it was ticked, so
 * ten sections in, the ten already paid for still looked like work to do — and
 * pressing Read again read them a second time. Reported as "if it already read
 * this, why does it need to again", which is the right question.
 *
 * In place rather than a re-render: twenty-six rows carry twenty-six
 * screenshots, and rebuilding them mid-run would throw away the scroll position
 * of the list you are watching.
 */
function markScreenRead(stop) {
  stop.failed = null;
  const row = document.querySelector(`#sweepPicksList .sweep-screen[data-screen="${stop.n}"]`);
  if (row) {
    row.classList.remove('is-failed');
    row.querySelector('.sweep-fail-flag')?.remove();
    row.querySelector('.sweep-retry')?.remove();
    row.querySelector('.sweep-outcome')?.remove();
    row.classList.add('is-done');
    const tick = row.querySelector('.sweep-screen-tick');
    if (tick) tick.checked = false;
    const label = row.querySelector('.ai-approved-label');
    if (label && !label.querySelector('.sweep-read-flag')) {
      label.insertAdjacentHTML('beforeend', ' <span class="sweep-read-flag">completed</span>');
    }
    // And what it gave. A completed section with no result on it answers "is it
    // done" and not "was it worth it", and the second is the one you need when
    // deciding whether to carry on.
    const body = row.querySelector('.ai-bulk-body');
    if (body && stop.outcome && !body.querySelector('.sweep-outcome')) {
      body.insertAdjacentHTML('beforeend',
        `<div class="sweep-outcome">${escapeHtml(stop.outcome)}</div>`);
    }
  }
  // …and moves into the completed area, now, rather than staying where it was
  // until the run ends. Screen 1 finished and was still sitting under "still to
  // search" while the drawer below said COMPLETED · 3 — so the drawer was
  // answering for the previous run and this one was invisible in it.
  //
  // The node is moved rather than the list redrawn: twenty-six rows carry
  // twenty-six screenshots, and rebuilding them would throw away the scroll
  // position of the list being watched. The one case that needs a redraw is the
  // first completion, when the two areas do not exist yet.
  const done = document.querySelector('#sweepPicksList .sweep-part-done');
  const stops = aiSweep.stops || [];
  // The run finishing is not just another completion: the ticking controls
  // above give way to the two summary buttons, and the stage trail hides —
  // both of which only a full render produces. Patching the drawer in place
  // was fine for every completion before this one, where nothing else on
  // screen needs to change.
  const sweepDone = stops.length > 0 && stops.every((s) => !s.count || s.scanned);
  if (row && done && !sweepDone) {
    done.appendChild(row);
    const left = document.querySelector('#sweepPicksList .sweep-part > h4');
    if (left) left.textContent = `Still to search · ${stops.filter(x => x.count && !x.scanned).length}`;
    const head = done.querySelector('summary');
    if (head) {
      const readNow = stops.filter(x => x.scanned);
      const found = readNow.reduce((a, x) => a + ((x.found || []).filter(f => !f.done).length), 0);
      head.innerHTML = `Completed · ${readNow.length}` + (found
        ? ` · ${found} component${found === 1 ? '' : 's'} found` +
          `<button class="btn-outline btn-xs" data-build-found>Stop and build these</button>`
        : '') +
        `<button class="btn-outline btn-xs" data-sweep-clear>Clear</button>`;
    }
  } else if (row) {
    renderSweepScreens();
  }

  // The estimate under the list is what the NEXT press will cost, so it has to
  // come down as the run goes.
  syncSweepMakeBtn();
  // And persist it before the next section begins — awaited, not debounced, so
  // stopping after any section leaves that section recorded.
  return saveSweepNow();
}

let sweepReadingNow = null;

// The finished-run summary, folded behind the "What was read" button — cached
// here because it no longer sits in the DOM once collapsed.
let sweepReadSummaryHtml = '';

/**
 * A screen the run tried and could not finish.
 *
 * It keeps its tick and its place in "still to search", because it really was
 * not searched and pressing again should pick it up. What it gains is the
 * reason — otherwise the only evidence that anything happened to it is a gap in
 * the numbering of the completed drawer.
 */
function markScreenFailed(stop, why) {
  stop.failed = why || 'could not be read';
  const row = document.querySelector(`#sweepPicksList .sweep-screen[data-screen="${stop.n}"]`);
  if (row) {
    row.classList.add('is-failed');
    const label = row.querySelector('.ai-approved-label');
    if (label && !label.querySelector('.sweep-fail-flag')) {
      label.insertAdjacentHTML('beforeend', ' <span class="sweep-fail-flag">⚠ Failed</span>');
    }
    // The way out sits on the card. It is the same press as ▶ — one section,
    // one call, same cost dialog — so it carries the same data attribute and
    // the same delegate handles it.
    if (label && !row.querySelector('.sweep-retry')) {
      label.insertAdjacentHTML('afterend',
        `<button type="button" class="btn-outline btn-xs sweep-retry" data-play-screen="${stop.n}" ` +
        `title="Read this section again — one call">Retry</button>`);
    }
    const body = row.querySelector('.ai-bulk-body');
    if (body && !body.querySelector('.sweep-outcome')) {
      body.insertAdjacentHTML('beforeend',
        `<div class="sweep-outcome">${escapeHtml(stop.failed)} — not read, nothing charged. Still ticked; press Retry.</div>`);
    }
  }
  return saveSweepNow();
}

function markScreenReading(n) {
  // Remembered, because the list is redrawn during a run — switching route and
  // back, a restore, the regroup at the end — and a mark that only lives in the
  // DOM comes back attached to whichever row happened to hold it last. That is
  // how the bar could say "section 1" while a row far down the list was lit.
  sweepReadingNow = n;
  document.querySelectorAll('.sweep-screen.is-reading')
    .forEach((r) => r.classList.remove('is-reading'));
  if (n == null) return;
  const row = document.querySelector(`#sweepPicksList .sweep-screen[data-screen="${n}"]`);
  if (!row) return;
  row.classList.add('is-reading');
  try { row.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch {}
}

// The inventory. Every row's component type and container selector are inputs,
// not labels — a wrong guess is corrected here rather than worked around later.
/**
 * What the survey answered, checked against the page before anyone sees it.
 *
 * Two corrections, both mechanical, both of things the prompt has asked the
 * model for in plain words and not got:
 *
 *   1. A native <a href> or <button> with a name is ALREADY a link or a button.
 *      u1.fix.link on one re-announces an element that announces itself — the
 *      double-fixing a specialist would never do by hand. The prompt has said
 *      so for a long time and link/button rows are still the commonest thing on
 *      the list, which is the signature of a question that should be measured.
 *
 *   2. `role="menu"` on a button-and-a-flat-list is a listbox. u1 draws that
 *      line by behaviour, not by the word in the markup, and fix.menu on that
 *      shape decorates nothing.
 *
 * Returns { comps, dropped, retyped } — the caller reports the counts, because
 * a row silently disappearing is its own kind of wrong.
 */
/**
 * Stage 3.1: what the probe OBSERVED becomes proposed rows, beside the
 * model's — source:'observed', so every later surface can say which voice
 * said what. Stage 3.3: merged by root selector; agreement folds into one
 * dual-source row, disagreement keeps BOTH rows flagged mismatch — no voice
 * wins silently.
 */
function observedRowsFor(stop) {
  return ((stop && stop.probed) || [])
    .filter((c) => c && c.root && c.type)
    .map((c) => ({
      label: `${c.type} (observed): ${c.root}`,
      u1Type: c.type,
      containerSelector: c.root,
      triggerSelector: (c.parts && c.parts.trigger) || '',
      needsWork: true,
      source: 'observed',
      why: 'Pressed and watched: ' + (c.why || ''),
    }));
}

// Stage 6: one confidence number per discovery row, from the voices that
// agreed. A role/tag hint is worth 1.0 and a class hint 0.4; pressing and
// watching adds 0.5; the model's word adds 0.3; a shape reader that later
// confirms the anatomy adds 0.4 (see prepareOne). Probe silence adds
// nothing — it is silence, not testimony. Published at ≥0.6; shown as sure
// only at ≥0.9.
function confidenceOf(row, hintRows) {
  let s = 0;
  const hint = (hintRows || []).find((h) =>
    h && h.component && h.selector && h.selector === row.containerSelector);
  if (hint) s += hint.maybe ? 0.4 : 1.0;
  const src = row.source || 'model';
  if (/observed/.test(src)) s += 0.5;
  if (/model/.test(src)) s += 0.3;
  // The shape reader's +0.4 is NOT here: it lands in prepareOne, directly
  // on detConf, because at merge time no shape has been read yet. A
  // shapeConfirmed parameter lived here dead for a day — R6 removed it.
  return Math.min(1, Math.round(s * 10) / 10);
}

function mergeObservedRows(modelRows, obsRows, hintRows) {
  const out = (modelRows || []).map((r) => ({ ...r, source: r.source || 'model' }));
  for (const obs of obsRows || []) {
    const same = out.find((r) => r.containerSelector === obs.containerSelector);
    if (!same) { out.push(obs); continue; }
    if (same.u1Type === obs.u1Type) {
      same.source = 'model+observed';
      same.why = (same.why ? same.why + ' ' : '') + '(Confirmed by pressing.)';
      if (!same.triggerSelector && obs.triggerSelector) same.triggerSelector = obs.triggerSelector;
      continue;
    }
    // Two voices, two answers: both rows stay, both say so. Silence is how
    // the probe's verdicts were thrown away for a year.
    same.mismatch = true;
    same.why = (same.why ? same.why + ' ' : '') +
      `⚠ Pressing said ${obs.u1Type}, the reading says ${same.u1Type} — decide.`;
    obs.mismatch = true;
    obs.why += ` ⚠ The reading says ${same.u1Type} — decide.`;
    out.push(obs);
  }
  // Every row leaves with its score; a mismatch pair carries one score EACH,
  // so the person deciding sees which voice has more behind it.
  for (const r of out) {
    r.detConf = confidenceOf(r, hintRows);
    if (r.mismatch) r.why += ` (confidence ${r.detConf})`;
  }
  return out;
}

async function auditSurveyComponents(comps, tab) {
  const list = (comps || []).filter((c) => c && c.containerSelector);
  if (!list.length || !isInjectable(tab)) return { comps: list, dropped: [], retyped: [] };

  let verdicts = null;
  try {
    verdicts = await inPage(tab.id, (rows) => rows.map(([sel, type]) => {
      const S = window.__u1SelectorIntel;
      const out = { native: null, listbox: null, junk: null };
      try { if (type === 'link' || type === 'button') out.native = S.alreadyNative(sel); } catch (e) {}
      // fix.link on a CONTAINER makes the whole region one link. The survey
      // filed molina's entire <footer> — forty links of site navigation — as
      // a single LINK row (2026-09-02), and nothing downstream questions a
      // link's element the way listbox/dialog shapes are questioned.
      try {
        if ((type === 'link' || type === 'button') && !out.native) {
          const el = document.querySelector(sel);
          if (el && !el.matches('a,button,input,[role="link"],[role="button"]')) {
            const inner = el.querySelectorAll('a[href],button').length;
            if (inner >= 2) out.junk = { tag: el.tagName.toLowerCase(), inner };
          }
        }
      } catch (e) {}
      try { if (type === 'menu') out.listbox = S.menuIsReallyListbox(sel); } catch (e) {}
      return out;
    }), [list.map((c) => [c.containerSelector, c.u1Type])]);
  } catch (e) { verdicts = null; }
  if (!verdicts || verdicts.length !== list.length) return { comps: list, dropped: [], retyped: [] };

  const dropped = [], retyped = [], kept = [];
  list.forEach((c, i) => {
    const v = verdicts[i] || {};
    if (v.native) {
      dropped.push({ label: c.label || c.containerSelector, tag: v.native.tag, name: v.native.name });
      return;
    }
    if (v.junk) {
      dropped.push({ label: c.label || c.containerSelector, tag: v.junk.tag,
        name: `holds ${v.junk.inner} links/buttons of its own — ${c.u1Type} on a container would fuse them into one` });
      return;
    }
    if (v.listbox) {
      retyped.push({ label: c.label || c.containerSelector, from: c.u1Type });
      c.u1Type = 'listbox';
      c.containerSelector = v.listbox.listbox;
      c.triggerSelector = v.listbox.trigger;
      c.why = (c.why ? c.why + ' ' : '') + v.listbox.why;
    }
    kept.push(c);
  });
  return { comps: kept, dropped, retyped };
}

function renderAiComponents(found) {
  const list = document.getElementById('aiComponentList');
  const comps = found.components || [];
  // The model's prose description of the page told the specialist what they were
  // already looking at. Only the count and what it cost are worth the space.
  document.getElementById('aiSummary').innerHTML =
    `<div class="ai-meta">${comps.length} component${comps.length === 1 ? '' : 's'} found` +
    ` · ${escapeHtml(found.model || '')} · ~$${aiCost.toFixed(3)} this session</div>` +
    // Folded away. It is the same paragraph on every scan, it is read once, and
    // sitting above the results it is only something to scroll past. How many
    // rows were left out earns a place on the summary; the explanation does not.
    // Named, not silently dropped. The scan saw them and that is worth knowing;
    // they are simply not what was pointed at.
    ((found.alsoInside || []).length
      ? `<div class="ai-meta">Also inside ${escapeHtml(found.scope)}, not mapped: ` +
        found.alsoInside.map((n) => escapeHtml(n)).join(', ') +
        ` — scan ${found.alsoInside.length === 1 ? 'it' : 'one of them'} directly to handle ` +
        `${found.alsoInside.length === 1 ? 'it' : 'them'}.</div>`
      : '') +
    `<details class="ai-hint-fold"><summary>What wasn't scanned` +
    (found.skipped ? ` · ${found.skipped} left out` : '') + `</summary>` +
    `<div class="ai-hint-line">Only ${found.scope ? `<code>${escapeHtml(found.scope)}</code>` : 'what was on screen'}` +
    ` was scanned. A dialog, dropdown or datepicker that is closed does not exist in the page
      yet — open one and use <strong>⏱ Scan in 5s</strong>, or name it in the container box.` +
    (found.skipped ? ` <strong>${found.skipped}</strong> already mapped on this site were left out —
      delete a mapping to see its element again.` : '') +
    // A row vanishing without a word is its own kind of wrong, even when the
    // reason is good. These two say what was decided and why, so the reading
    // can be argued with rather than just trusted.
    (((found.audit && found.audit.dropped) || []).length
      ? `<div class="ai-hint-line"><strong>${found.audit.dropped.length}</strong> left out for needing no fix:
         ${found.audit.dropped.map((d) => `<code>&lt;${escapeHtml(d.tag)}&gt;</code> “${escapeHtml(d.name)}”`).join(', ')}.
         The browser already gives a named &lt;a href&gt; and &lt;button&gt; their role and their tab stop —
         mapping one announces it twice.</div>`
      : '') +
    (((found.audit && found.audit.retyped) || []).length
      ? `<div class="ai-hint-line">${found.audit.retyped.map((r) =>
           `<strong>${escapeHtml(r.label)}</strong> reads as ${escapeHtml(r.from)} in the markup and is mapped as a listbox`).join('; ')} —
         one control opening one flat list is a listbox whatever the role attribute says.</div>`
      : '') +
    `</div></details>`;

  const typeOptions = (sel) => U1AI.U1_TYPES
    .map(t => `<option value="${t}"${t === sel ? ' selected' : ''}>${t}</option>`).join('');

  const track = document.getElementById('aiCompTrack');

  track.innerHTML = comps.map((c, i) => {
    const chk = checkAiSelector(c.containerSelector, found.context);
    const bad = !chk.ok ? `<div class="ai-sel-bad">⛔ ${escapeHtml(chk.why)} — put another selector above, or handle this one by hand.</div>` : '';
    return `
      <div class="ai-comp" data-i="${i}">
        <div class="ai-comp-head">
          <span class="ai-comp-label">${escapeHtml(c.label || '')}</span>
          ${c.needsWork ? '<span class="ai-sev" data-need="1">needs work</span>'
                        : '<span class="ai-sev" data-need="0">looks ok</span>'}
        </div>

        <!-- The element is the thing being decided about, so it leads the card
             at full width — and stays editable, because a wrong container is
             the most common thing to correct. -->
        <label class="ai-comp-eltag" for="aiCompSel${i}">Element</label>
        <div class="ai-comp-elrow">
          <span class="sel-strength-wrap">
            <input type="text" class="ai-comp-sel" id="aiCompSel${i}"
                   value="${escapeHtml(c.containerSelector || '')}" spellcheck="false">
            <span class="sel-strength" data-level="empty" aria-hidden="true"></span>
          </span>
          <button class="btn-ghost auto-eye ai-comp-eye" title="Show it on the page">👁</button>
        </div>
        <div class="ai-comp-hit" id="aiCompHit${i}"></div>
        ${bad}

        <div class="ai-comp-why">${escapeHtml(c.why || '')}</div>

        <div class="ai-comp-fields">
          <label for="aiCompType${i}">Component type</label>
          <select class="ai-comp-type" id="aiCompType${i}">${typeOptions(c.u1Type)}</select>
        </div>

        <!-- Switch a found element to a type whose first argument is a TRIGGER
             and the element stops being the component: the help button IS the
             thing you click, but the thing to map is the panel it opens. So ask
             for that panel, and file the found element as the trigger. Without
             this the only way through was to give up on the card and start
             again by hand. -->
        <div class="ai-comp-trigger" id="aiCompTrig${i}" style="display:none;">
          <label class="ai-comp-cont-label" for="aiCompCont${i}"></label>
          <div class="ai-comp-cont-line">
            <input type="text" class="ai-comp-cont" id="aiCompCont${i}" placeholder="#help-panel, .modal…"
                   value="${escapeHtml(triggerRequired(c.u1Type) ? '' : (c.triggerSelector || ''))}">
            <button class="btn-ghost btn-sm ai-comp-conteye" title="Show it on the page">👁</button>
          </div>
          <div class="input-hint ai-comp-cont-hint" style="display:block;"></div>
          <div class="ai-comp-hit" id="aiCompContHit${i}"></div>
        </div>

        <!-- One element, one action. A global tick plus a batch button counted
             selections across the whole list, so pressing it from the card in
             front of you started work on a different component entirely. -->
        <div class="ai-comp-actions">
          <button class="btn-primary" data-mapone="${i}" ${chk.ok ? '' : 'disabled'}>✨ Make this accessible</button>
          <button class="btn-ghost btn-sm" data-skipcomp="${i}" title="Not needed — take it off the list">Skip</button>
        </div>
      </div>`;
  }).join('') || '<div class="advisor-note ok">✅ Nothing found that needs a mapping.</div>';

  setStage('found');
  // Clear the CARDS, not the container: the carousel head and track are static
  // markup now, and wiping innerHTML took them out with the cards.
  document.getElementById('aiSlideTrack').innerHTML = '';
  clearApproved();
  syncAllTriggerFields();
  showCompSlide(0);
  paintAiRowStrength();

  // The inventory is not the page. A dialog scanned while open through the
  // container box carries classes no collected candidate has — so the
  // invented check, which only knows the inventory, refused
  // `.modal.state-select-modal.show` on the same card whose own 👁 reported
  // "1 match — highlighted on the page". The page outranks the inventory:
  // every refused-as-invented selector is retried against the live DOM, and
  // one the page resolves is reprieved. A U1-INVALID refusal (spaces, a
  // pseudo-class) is never reprieved — the page resolving it does not make
  // the engine able to.
  (async () => {
    const cards = [...track.querySelectorAll('.ai-comp')]
      .filter((c) => (c.querySelector('.ai-sel-bad')?.textContent || '').includes('invented'));
    if (!cards.length) return;
    const sels = cards.map((c) => c.querySelector('.ai-comp-sel').value.trim());
    const counts = await countSelectors(sels);
    cards.forEach((card, i) => {
      if (!(typeof counts[i] === 'number' && counts[i] >= 1)) return;
      // The field may have been edited while the count ran.
      if (card.querySelector('.ai-comp-sel').value.trim() !== sels[i]) return;
      card.querySelector('.ai-sel-bad')?.remove();
      const go = card.querySelector('[data-mapone]');
      if (go) go.disabled = false;
    });
  })();
}

const showCompSlide = (i) => slideTo('aiComp', i, '.ai-comp', () => paintAiRowStrength());

/**
 * Every mapping for this site, gone. For clearing the board between runs.
 *
 * Destructive and SHARED — these are on the server too, so this is not just
 * this machine's copy — so it says what it will take before it takes it, and
 * offers the export first. A debugging convenience that quietly deletes a
 * colleague's afternoon is not a convenience.
 *
 * Deliberately per-site: `currentHostname` only. Deleting every mapping for
 * every client from a debug button is not a thing anyone should be one press
 * away from.
 */
document.getElementById('deleteAllBtn')?.addEventListener('click', async () => {
  const key = storageKey('mappings', currentHostname);
  const list = (await U1Store.get([key]))[key] || [];
  const status = document.getElementById('applyAllStatus');
  if (!list.length) { showNotice(status, 'There are none to delete.', 'info', 4000); return; }

  const dlg = document.getElementById('deleteAllDialog');
  const byType = {};
  for (const m of list) byType[m.custom || m.type || '?'] = (byType[m.custom || m.type || '?'] || 0) + 1;
  document.getElementById('deleteAllBody').innerHTML =
    `<strong>${list.length} mapping${list.length === 1 ? '' : 's'} on ${escapeHtml(currentHostname)}</strong> — ` +
    escapeHtml(Object.entries(byType).map(([t, n]) => `${n} ${t}`).join(', ')) + '.<br><br>' +
    'Everything goes: the mappings, the set-aside offers and the dismissed list — from this ' +
    'computer and from the server, so your colleagues lose them too. The page reloads afterwards, ' +
    'so what U1 already wrote into it goes with them and the next scan sees the site as it really is.<br><br>' +
    'Export from the Export tab first if you might want any of it back.';

  const go = await new Promise((resolve) => {
    const done = (v) => {
      dlg.close();
      document.getElementById('deleteAllGo').onclick = null;
      document.getElementById('deleteAllCancel').onclick = null;
      resolve(v);
    };
    document.getElementById('deleteAllGo').onclick = () => done(true);
    document.getElementById('deleteAllCancel').onclick = () => done(false);
    dlg.showModal();
  });
  if (!go) return;

  try {
    // Through set(), not setLocalOnly: the server has to be told, or the next
    // pull brings every one of them straight back.
    await U1Store.set({ [key]: [] });
    // Deleted means deleted EVERYWHERE. These were OUR fixes: what the page
    // still runs of them is this machine's leftover, remembered locally so
    // it is never mistaken for the site's own deployment — and any standing
    // decline of the same fixes is lifted, not deepened. The old behaviour
    // here declined every deleted mapping, permanently and for the whole
    // team, which is how a week of map-apply-delete experiments became "17
    // fixes set aside" that nobody remembered refusing.
    const goneKeys = list.filter((m) => m && typeof m === 'object').map(mappingKey);
    await rememberSelfApplied(goneKeys);
    await forgetDeclinedFixes(goneKeys);
    // "Total" means total: the set-aside offers and the dismissed selectors
    // are decisions about work that no longer exists, and keeping them is how
    // a clean slate stayed haunted — a scan on an emptied site still refused
    // to look at things nobody remembered refusing. Through set(), so the
    // server hears it too.
    await U1Store.set({
      [storageKey('declined', currentHostname)]: [],
      [storageKey('dismissed', currentHostname)]: [],
    });
    // And the page itself: U1 keeps whatever it already wrote until a
    // reload, and those leftovers are exactly what later scans misread —
    // ARIA nobody's markup contains, fixes "the site runs". A wipe that
    // leaves them standing is half a wipe.
    try {
      const tab = await getTab();
      if (isInjectable(tab) && getHostname(tab) === currentHostname) {
        await chrome.tabs.reload(tab.id);
      }
    } catch {}
    showNotice(status, `${list.length} mapping${list.length === 1 ? '' : 's'} deleted, ` +
      `the set-aside and dismissed lists cleared, and the page reloaded clean.`, 'success', 8000);
  } catch (err) {
    // Local went; the server did not. Say which, because "deleted" and
    // "deleted here" are different states and the next pull tells them apart.
    showNotice(status, err.localOnly
      ? `Deleted on this computer. The server still has them (${err.message}) — they will ` +
        `come back on the next pull unless this succeeds.`
      : 'Could not delete them: ' + err.message, 'error', 12000);
  }
  await loadMappingsList();
  refreshExportInfo();
});

// Remove a conflicting older mapping, on request, from the approved list.
document.getElementById('aiApproved')?.addEventListener('click', async (e) => {
  const btn = e.target.closest('[data-dropkey]');
  if (!btn) return;
  const key = storageKey('mappings', currentHostname);
  const list = (await U1Store.get([key]))[key] || [];
  const next = list.filter(m => mappingKey(m) !== btn.dataset.dropkey);
  if (next.length === list.length) { btn.textContent = 'Already gone'; btn.disabled = true; return; }
  await U1Store.set({ [key]: next });
  loadMappingsList();
  refreshExportInfo();
  btn.textContent = 'Removed ✓';
  btn.disabled = true;
  // Settled is settled: once the conflicting mapping is gone, the sentence
  // describing the conflict and the button that resolved it are a solved
  // problem still being reported. The ✓ gets a beat to be seen, then both
  // come off — anything still wrong with the row (a failure of its own)
  // stays, because removing the clash did not fix that.
  const rowEl = btn.closest('.ai-approved-row');
  setTimeout(() => {
    const wrap = btn.closest('.ai-approved-why');
    btn.remove();
    if (wrap && !wrap.querySelector('[data-dropkey]')) wrap.remove();
    const why = rowEl && rowEl.querySelector('.ai-approved-why');
    if (why) {
      // [\s\S]*?, not [^.]* — the clash names selectors like `.mainNav`,
      // whose dot would stop a period-excluding match halfway through.
      why.textContent = why.textContent
        .replace(/\s*Also mapped by [\s\S]*?two on the same elements fight, and the second wins\./, '');
    }
  }, 1200);
});

// Keep the "Make these accessible" button honest about how many are ticked —
// with one card on screen at a time, the count is the only way to know.
async function paintAiRowStrength() {
  const rows = [...document.querySelectorAll('#aiComponentList .ai-comp')];
  if (!rows.length) return;
  const sels = rows.map(r => r.querySelector('.ai-comp-sel').value.trim());
  rows.forEach((r, i) => paintStrength(r.querySelector('.sel-strength'), strengthOf(sels[i], { unique: true })));
  const counts = await countSelectors(sels);
  rows.forEach((r, i) => {
    if (r.querySelector('.ai-comp-sel').value.trim() !== sels[i]) return;
    const o = { unique: true };
    if (typeof counts[i] === 'number') o.count = counts[i];
    paintStrength(r.querySelector('.sel-strength'), strengthOf(sels[i], o));
  });
}

// 👁 — highlight the container on the page and say how many it matches. The
// handler for this was lost when the tick counter was removed, so the button
// rendered and did nothing; and its result used to go to the shared test panel
// in the manual area, which is not on screen in this mode.
document.getElementById('aiCompTrack')?.addEventListener('click', async (e) => {
  const eye = e.target.closest('.ai-comp-eye');
  if (!eye) return;
  const comp = eye.closest('.ai-comp');
  const sel = comp.querySelector('.ai-comp-sel').value.trim();
  const hit = document.getElementById('aiCompHit' + comp.dataset.i);
  if (!sel) return;
  eye.disabled = true;
  try {
    const res = await testSelector(sel);
    if (hit) {
      const n = res && typeof res.count === 'number' ? res.count : null;
      hit.className = 'ai-comp-hit ' + (n === 1 ? 'ok' : n ? 'warn' : 'bad');
      hit.textContent = res && res.err ? res.err
        : n === null ? ''
        : n === 0 ? 'Matches nothing on this page.'
        : n === 1 ? '1 match — highlighted on the page.'
        : `${n} matches — highlighted. u1.fix decorates only one of them.`;
    }
    if (res && res.count) {
      await highlightMatch(sel, 0, true);
      setTimeout(() => highlightMatch(sel, 0, false), 2500);
    }
  } finally {
    eye.disabled = false;
  }
});

// Re-grade a container selector as it is edited — the badge is the fastest way
// to see that a hand-typed selector matches nothing.
document.getElementById('aiComponentList')?.addEventListener('input', (e) => {
  if (!e.target.classList.contains('ai-comp-sel')) return;
  clearTimeout(aiRowTimer);
  aiRowTimer = setTimeout(paintAiRowStrength, 400);
});

// Types whose fix() first argument is a TRIGGER rather than the component: the
// element you click is not the element that gets decorated. Read from the
// schemas so a new type cannot be forgotten here.
const triggerFirstType = (type) => {
  const sc = COMPONENT_SCHEMAS[type];
  return !!sc && sc.firstArgFrom === 'trigger' && (sc.fields || []).includes('trigger');
};

// Every type whose schema declares a trigger at all — not just the three that
// swap it into first position. tooltip and keyboard-grid take one too, and the
// card used to offer no way to give it, so the only route was to abandon the
// card and rebuild it by hand in Manual.
const acceptsTrigger = (type) => {
  const sc = COMPONENT_SCHEMAS[type];
  return !!sc && (sc.fields || []).includes('trigger');
};

// Required is the schema's own req list, not "has a trigger". dialog declares a
// trigger but does not require one — a dialog with no opener is a real mapping,
// and the card used to refuse it.
const triggerRequired = (type) => {
  const sc = COMPONENT_SCHEMAS[type];
  return !!sc && (sc.req || []).includes('trigger');
};

/**
 * Reads one discovery card into the row shape the mapping step expects, and
 * says why if it cannot. Shared by the per-card button and the bulk run so the
 * two can never disagree about what a trigger-first type means.
 */
function rowFromCompCard(comp) {
  return rowFromParts({
    type: comp.querySelector('.ai-comp-type').value,
    found: comp.querySelector('.ai-comp-sel').value.trim(),
    container: (comp.querySelector('.ai-comp-cont')?.value || '').trim(),
    label: comp.querySelector('.ai-comp-label').textContent,
    compIndex: comp.dataset.i,
    why: (comp.querySelector('.ai-comp-why')?.textContent || '').trim(),
  });
}

/**
 * The same rules, without a card to read them off.
 *
 * The whole-page sweep never draws the inventory cards — it goes straight from
 * the model's answer to preparing each component — so the trigger swap and the
 * required-field check had to stop living inside the DOM reader.
 */
function rowFromParts({ type, found, container, label, compIndex, why }) {
  // For a type whose trigger is REQUIRED the found element is the TRIGGER, and
  // the mapping is rooted on what it opens. Everything downstream expects
  // `sel` to be that root, so swap them here rather than teaching each step
  // about the exception. Any other type that accepts a trigger keeps the found
  // element as the component and files what was entered as the trigger.
  //
  // Keyed on triggerRequired, NOT triggerFirstType. `firstArgFrom:'trigger'`
  // says only which selector becomes fix()'s first argument — "the element to
  // wait for" — and buildTemplate already handles that on its own. Reading it
  // as "the found element is the trigger" inverted every dialog: pointing at
  // the modal and naming its opener produced
  //   fix.dialog({ dialog: "#HealthCareProfessionals>a", trigger: "#state-select-modal-find-doctor" })
  // — the link filed as the dialog and the modal filed as the link that opens
  // it, exactly backwards. datepicker and listbox require a trigger and do
  // mean the found element is one; dialog's is optional and does not.
  const swap = triggerRequired(type) && !!container;
  const row = {
    type,
    sel: swap ? container : found,
    trigger: swap ? found : (acceptsTrigger(type) && container ? container : undefined),
    label,
    compIndex,
    // The scan's diagnosis rides along. Every finding names the defect and
    // usually the remedy — "missing aria-expanded", "should be an h3" — and
    // dropping it here was why the mapping step kept re-deriving (or
    // faithfully copying) what the finding had already answered.
    why: (why || '').trim() || undefined,
  };
  // Block only on what the schema actually requires. dialog declares a trigger
  // but does not require one, and this used to refuse it anyway.
  if (triggerRequired(type) && !container) {
    return { err: `A ${type} needs the element it opens. Open it on the page, then paste its selector.`, focusTrigger: true };
  }
  if (!row.sel || !COMPONENT_SCHEMAS[row.type]) {
    return { err: 'Give this one a container selector and a component type first.' };
  }
  return { row };
}

// Show the container field only when the chosen type needs one. Driven off the
// <select>'s own value rather than the type the scan proposed, because the two
// can differ: a type the AI returns that is not in U1_TYPES leaves the dropdown
// showing its first option instead.
function syncTriggerField(comp) {
  const sel = comp?.querySelector('.ai-comp-type');
  const trig = comp?.querySelector('.ai-comp-trigger');
  if (!sel || !trig) return;
  const type = sel.value;
  trig.style.display = acceptsTrigger(type) ? '' : 'none';
  if (!acceptsTrigger(type)) return;

  // The wording comes from the schema because the relationship is not the same
  // in both directions: for a listbox the entered selector is what the found
  // element OPENS, while for a tooltip it is the element that opens the found
  // one. A single hand-written label was wrong for half of them.
  const sc = COMPONENT_SCHEMAS[type] || {};
  const required = triggerRequired(type);
  const label = trig.querySelector('.ai-comp-cont-label');
  if (label) {
    label.textContent = (sc.desc && sc.desc.trigger) || 'Selector of the trigger element';
    if (required) label.insertAdjacentHTML('beforeend', ' <span class="req-star">*</span>');
  }
  const hint = trig.querySelector('.ai-comp-cont-hint');
  if (hint) {
    // Same test rowFromParts swaps on, or the hint promises one arrangement
    // and the mapping is built with the other.
    hint.textContent = required
      ? 'The element above becomes the trigger. Open it on the page first — a closed panel is not there to point at.'
      : 'The element above stays the component; this is what drives it.';
  }
}

// Every card needs this on first paint, not only after someone touches the
// dropdown. When the scan already classified a component as a trigger-first
// type — a listbox, a modal — no change event ever fired, so the field stayed
// hidden and "Make this accessible" failed on a selector the card gave you no
// way to enter. The error even focused the hidden input.
function syncAllTriggerFields() {
  document.querySelectorAll('#aiCompTrack .ai-comp').forEach(syncTriggerField);
}

// Re-check on every change — the type is a dropdown the specialist is expected
// to correct.
document.getElementById('aiCompTrack')?.addEventListener('change', (e) => {
  const sel = e.target.closest('.ai-comp-type');
  if (!sel) return;
  syncTriggerField(sel.closest('.ai-comp'));
});

// 👁 for the container field.
document.getElementById('aiCompTrack')?.addEventListener('click', async (e) => {
  const eye = e.target.closest('.ai-comp-conteye');
  if (!eye) return;
  const comp = eye.closest('.ai-comp');
  const sel = (comp.querySelector('.ai-comp-cont').value || '').trim();
  const hit = comp.querySelector('[id^="aiCompContHit"]');
  if (!sel || !hit) return;
  eye.disabled = true;
  try {
    const res = await testSelector(sel);
    const n = res && typeof res.count === 'number' ? res.count : null;
    hit.className = 'ai-comp-hit ' + (n === 1 ? 'ok' : n ? 'warn' : 'bad');
    hit.textContent = res && res.err ? res.err
      : n === 0 ? 'Matches nothing — if it only exists while open, open it first.'
      : n === 1 ? '1 match — highlighted on the page.'
      : `${n} matches — highlighted. u1.fix decorates only one of them.`;
    if (n) { await highlightMatch(sel, 0, true); setTimeout(() => highlightMatch(sel, 0, false), 2500); }
  } finally { eye.disabled = false; }
});

// Everything already settled on this site — which means MAPPED, and nothing
// else. There used to be a second, persistent reason: a ✕ pressed on a survey
// row wrote that selector to a shared per-site "dismissed" list that every
// later scan silently filtered out, forever, on every machine. On molina that
// standing judgement ate the sign-in listbox run after run, and from the
// outside it read as "the AI keeps missing it". Owner decision (2026-09-01):
// a scan starts fresh every time — ✕ takes a row off the CURRENT list only,
// and nothing a person skipped once is held against the next run.
/** The saved mappings as `{ type, sel }` pairs — every selector each one owns. */
async function mappedSelectors() {
  const out = [];
  try {
    const key = storageKey('mappings', currentHostname);
    for (const m of (await U1Store.get([key]))[key] || []) {
      if (!m || typeof m !== 'object' || !m.type) continue;
      for (const sel of new Set([m.primary, m.firstArg].filter(Boolean))) out.push({ type: m.type, sel });
    }
  } catch {}
  return out;
}

/**
 * Which of these selectors land on something a saved mapping already owns —
 * the same element, inside it, or around it. That is the test the build step
 * applies before it saves anything (overlappingMappings), so what it says
 * here is exactly what would come back "Skipped — already mapped" later.
 *
 * Asked of the PAGE, not of the strings: alreadyHandled() drops a candidate
 * only when its selector is byte-for-byte a saved one, and the survey names
 * elements its own way, so `.mainNav` in the drawer and `#header>nav>ul` in
 * the survey were the same menu counted as new work every time.
 *
 * Returns `{ selector: 'menu' }` — the type of the mapping it overlaps — or
 * null when the page could not be asked.
 */
async function mappedOverlapOnPage(tab, sels, mapped) {
  if (!isInjectable(tab) || !sels.length || !mapped.length) return {};
  try {
    const res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: (list, owned) => {
        const q = (s) => { try { return Array.from(document.querySelectorAll(s)); } catch { return []; } };
        const own = owned.map(o => ({ type: o.type, els: q(o.sel) })).filter(o => o.els.length);
        const out = {};
        for (const s of list) {
          const mine = q(s);
          if (!mine.length) continue;
          const hit = own.find(o => o.els.some(el => mine.some(x => x === el || x.contains(el) || el.contains(x))));
          if (hit) out[s] = hit.type;
        }
        return out;
      },
      args: [sels, mapped],
    });
    return (res && res[0] && res[0].result) || {};
  } catch { return null; }
}

async function alreadyHandled() {
  const out = new Set();
  try {
    const key = storageKey('mappings', currentHostname);
    for (const m of (await U1Store.get([key]))[key] || []) {
      if (m && m.primary) out.add(m.primary);
      if (m && m.firstArg) out.add(m.firstArg);
    }
  } catch {}
  return out;
}

// Scan just one part of the page, and reset the skipped list.
// This button was in the markup from the start and wired to nothing — pressing
// it did exactly nothing, with no feedback to say so.
document.getElementById('aiDismissBtn')?.addEventListener('click', () => {
  resetAiWorkspace();
  showNotice($aiStatus, 'Cleared.', 'success', 2500);
});

document.getElementById('aiScopeBtn')?.addEventListener('click', () => {
  document.getElementById('aiDiscoverBtn')?.click();
});

// 🔍 — same purpose as the 👁 eye button elsewhere (testSelector): show
// what the typed container selector actually resolves to, BEFORE spending a
// scan (and a model call) on it. Typing `.signin` with no way to check it
// first meant finding out it matched the wrong element only after "Nothing
// reviewable inside .signin" came back.
document.getElementById('aiScopeFindBtn')?.addEventListener('click', async () => {
  const btn = document.getElementById('aiScopeFindBtn');
  const input = document.getElementById('aiScopeInput');
  const preview = document.getElementById('aiScopePreview');
  const sel = (input?.value || '').trim();
  if (!sel) { showNotice($aiStatus, 'Type a container selector first.', 'error', 3000); return; }
  btn.disabled = true;
  try {
    const res = await testSelector(sel);
    if (res.err || res.error) { showNotice($aiStatus, res.err || res.error, 'error', 5000); return; }
    showNotice($aiStatus,
      res.count === 0 ? `Matches nothing on this page — check the selector, and open it first if it is a dialog.`
      : res.count === 1 ? `1 match — outlined on the page.`
      : `${res.count} matches — all outlined. Scan uses whichever this selector resolves to.`,
      res.count ? 'success' : 'error', 4000);
    // The picture, under the input. The outline is drawn on the PAGE — behind
    // the panel, and often scrolled somewhere else — so "1 match" was a claim
    // that still had to be verified by going and looking. The crop shows the
    // matched element right where the question was asked.
    if (preview) {
      if (res.count) {
        preview.style.display = '';
        preview.innerHTML = '<span class="ai-scope-preview-note">taking its picture…</span>';
        const shot = await captureElementScreenshot(sel);
        // The input may have been edited while the capture ran; a picture of
        // the previous selector under the new text would be a lie.
        if ((input?.value || '').trim() !== sel) return;
        preview.innerHTML = shot
          ? `<img src="${shot}" alt="The element ${escapeHtml(sel)} matches on the page">` +
            `<span class="ai-scope-preview-note">this is what ${escapeHtml(sel)} points at${
              res.count > 1 ? ` (first of ${res.count})` : ''}</span>`
          : '';
        if (!shot) preview.style.display = 'none';
      } else {
        preview.style.display = 'none';
        preview.innerHTML = '';
      }
    }
  } finally {
    btn.disabled = false;
  }
});
document.getElementById('aiScopeInput')?.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); document.getElementById('aiDiscoverBtn')?.click(); }
});
// A picture of the OLD selector under a NEW one reads as an answer to the
// wrong question — edit the field and the preview stands down until 🔍 is
// pressed again.
document.getElementById('aiScopeInput')?.addEventListener('input', () => {
  const preview = document.getElementById('aiScopePreview');
  if (preview) { preview.style.display = 'none'; preview.innerHTML = ''; }
});

// Map ONE component, on demand, from its own card. No ticking, no batch: the
// button you press is about the element you are looking at.
document.getElementById('aiCompTrack')?.addEventListener('click', async (e) => {
  // Skip: take this component off the list without mapping it. The scan is a
  // suggestion, and a specialist who can see it is not needed should be able to
  // say so in one click rather than working around it.
  const skipBtn = e.target.closest('[data-skipcomp]');
  if (skipBtn) {
    const comp = skipBtn.closest('.ai-comp');
    comp.dataset.done = '1';
    // For this list only — a skip is not remembered, so the next scan offers
    // the row again. Every scan starts fresh (owner decision, 2026-09-01).
    const left = document.querySelectorAll('#aiCompTrack .ai-comp:not([data-done])').length;
    if (left) showCompSlide(Math.min(carouselAt.aiComp || 0, left - 1));
    else {
      setStage('none');
      showNotice(document.getElementById('aiStatus'),
        'Nothing left on the list. Scan again, or switch to Manual.', 'success', 5000);
    }
    return;
  }

  const btn = e.target.closest('[data-mapone]');
  if (!btn) return;
  const status = document.getElementById('aiMapStatus');
  if (isReadonly()) {
    showNotice(status, 'Licence expired — existing mappings still work and export, but new ones are paused.', 'error', 6000);
    return;
  }

  if (!aiWorkspaceMatchesSite()) { warnWrongSite(status); return; }

  const comp = btn.closest('.ai-comp');
  let built = rowFromCompCard(comp);
  if (built.err && built.focusTrigger) {
    // The missing half is missing because the thing is CLOSED. Before sending
    // the specialist off to open it by hand, press the trigger from inside the
    // page and read what appears — the machine's version of the hint text.
    const openTab = await getTab();
    if (isInjectable(openTab)) {
      showNotice(status, 'Opening it on the page to find the other half…', 'warn', 4000);
      const found = (comp.querySelector('.ai-comp-sel')?.value || '').trim();
      const type = comp.querySelector('.ai-comp-type')?.value || '';
      const cap = found ? await autoOpenCapture(openTab, found, type) : null;
      const got = (cap && (cap.root || cap.stated)) || '';
      if (got) {
        // Written into the card, not smuggled past it — the specialist sees
        // the selector, can correct it, and Approve shows what will be saved.
        const contInput = comp.querySelector('.ai-comp-cont');
        if (contInput) contInput.value = got;
        built = rowFromCompCard(comp);
      }
    }
  }
  if (built.err) {
    showNotice(status, built.err, 'error', built.focusTrigger ? 6000 : 4000);
    if (built.focusTrigger) comp.querySelector('.ai-comp-cont')?.focus();
    return;
  }
  const row = built.row;

  const tab = await getTab();
  if (!isInjectable(tab)) { showNotice(status, 'Cannot read this page.', 'error', 4000); return; }

  // Ask about the site's own role HERE — on the card where the container and
  // the trigger are chosen — rather than two steps later at Approve & apply.
  //
  // This is the moment the decision is actually about something: you are
  // looking at the element, you have just named it, and the answer changes
  // whether a mapping is worth building at all. Answering it after the mapping
  // card has been generated means generating one that cannot work. The answer
  // rides on the row, so Approve & apply does not ask again.
  const roleAsk = { type: row.type, primary: row.sel };
  if (!(await confirmRoleOverwrite(roleAsk))) {
    showNotice(status, 'Left as it is — no mapping was built.', 'info', 5000);
    return;
  }
  if (roleAsk.overwriteRole) row.overwriteRole = roleAsk.overwriteRole;

  const host = document.getElementById('aiMappings');
  const track = document.getElementById('aiSlideTrack');
  host.style.display = 'block';
  setStage('cards');

  btn.disabled = true;
  const original = btn.textContent;
  btn.textContent = 'Working…';
  comp.classList.add('is-working');
  showMapBusy(row.label, 1, 1);

  try {
    const prepared = await prepareOne(row, tab);
    clearMapBusy();
    if (prepared.err) {
      track.insertAdjacentHTML('beforeend', aiMapCardError(row, prepared.err));
      showSlide(0);
      return;
    }
    showSlide(slideIndex('aiSlide'));
    document.querySelector(`#aiSlideTrack .ai-map-card[data-card="${prepared.idx}"]`)
      ?.scrollIntoView({ block: 'start', behavior: 'smooth' });
  } catch (err) {
    clearMapBusy();
    showNotice(status, 'Failed: ' + err.message, 'error', 6000);
  } finally {
    btn.disabled = false;
    btn.textContent = original;
    comp.classList.remove('is-working');
  }
});

/**
 * Press a widget's trigger ON THE PAGE, read what the mapping needs off the
 * OPEN state, and put the page back — the machine doing what the hint text
 * used to ask of the specialist: "Open it on the page first — a closed panel
 * is not there to point at."
 *
 * Pressing from the panel is what makes this work at all: a click in the
 * panel's own UI moves focus off the page and closes exactly the widgets this
 * is trying to catch, but probe.js clicks from inside the page, under its own
 * safety net (no navigation, no submit, no network), and restores afterwards.
 *
 * What comes back is already selectors and serialisable facts — the elements
 * themselves never cross the executeScript boundary:
 *   { root, shape, markup, stated, opened, overlay, stateClass, restored }
 * for an open/close widget, { toggle: { checkedClass, uncheckedClass, … } }
 * for a checkbox/radio/switch, or { err } when nothing could be pressed.
 */
// probe.js's "net" (armNet in probe.js) cancels navigation/submission from the
// isolated world it runs in — which stops a plain link or form, but not a
// click handler that calls fetch/location.assign/window.open etc. directly in
// script, because that script's globals are a different copy from probe.js's.
// probe-net.js is the MAIN-world half that patches the real ones; the two
// coordinate over a shared DOM attribute (see the comment in probe.js's
// armNet). Injected once per tab per page load, alongside probe.js itself,
// everywhere probe.js is — the file guards against a second injection, so
// calling this more than once for the same load is free.
async function ensureProbeNet(tabId) {
  try {
    await chrome.scripting.executeScript({ target: { tabId }, world: 'MAIN', files: ['probe-net.js'] });
  } catch (e) { /* probe.js's own click/submit/beforeunload net still holds */ }
}

async function autoOpenCapture(tab, triggerSel, type) {
  // The net cancels link defaults, submits, window.open and location.assign,
  // but `location.href = …` is a host setter nothing can stub — a handler
  // that navigates in script still gets through. So the URL is noted here
  // and put back below, the same recovery the sweep uses.
  const urlBefore = ((await chrome.tabs.get(tab.id).catch(() => null))?.url || '').split('#')[0];
  try {
    await ensureProbeNet(tab.id);
    await chrome.scripting.executeScript({
      target: { tabId: tab.id }, files: ['selector-intel.js', 'probe.js'] });
  } catch (e) { return { err: e.message }; }
  let res = null;
  try {
    res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: async (trigSel, u1Type) => {
        const S = window.__u1SelectorIntel, P = window.__u1Probe;
        if (!S || !P) return { err: 'The page helpers did not load.' };
        let trigger = null;
        try { trigger = document.querySelector(trigSel); }
        catch (e) { return { err: 'Bad trigger selector: ' + e.message }; }
        if (!trigger) return { err: 'The trigger is not on the page right now.' };

        // A survey names the COMPONENT, which for a sign-in dropdown is the
        // wrapper holding the button and the closed list together. Clicking
        // the wrapper fires no handler — the listener lives on the button —
        // so descend to the pressable thing inside before pressing. The
        // named element is kept: the markup's own statements live anywhere
        // inside it, not only on what ends up being pressed.
        const namedEl = trigger;
        if (!trigger.matches('button,a[href],[role="button"],[aria-haspopup],[tabindex],input,summary')) {
          const inner = trigger.querySelector(
            'button,[role="button"],a[href],[aria-haspopup],summary,[tabindex]');
          if (inner) trigger = inner;
          else {
            // A bare <div class="clicker"> with a JS handler gives none of the
            // hints that list can read. The cursor is the one honest signal
            // left — and pressing the right element matters twice over: the
            // wrapper's own text face bundles the options in ("Sign In…
            // Register"), and 'register' reads as an action the safety layer
            // rightly refuses to press. The button's own face is just
            // "Sign In", which it allows. First pointer-cursor descendant in
            // document order wins: the button precedes the closed list.
            const kids = trigger.querySelectorAll('*');
            for (let i = 0; i < kids.length && i < 60; i++) {
              try {
                if (getComputedStyle(kids[i]).cursor === 'pointer') { trigger = kids[i]; break; }
              } catch (e) { /* keep looking */ }
            }
          }
        }

        // What the markup already states (aria-controls, a data-* id, a role
        // in the neighbourhood) — costs nothing and needs no restore. Asked
        // about the named element AND about what it holds: the survey names
        // the WRAPPER, and the aria-controls that answers everything sits on
        // the button inside it — asking only the wrapper missed a component
        // whose own description said "aria-controls links them".
        let stated = S.openedBy(trigSel) || null;
        if (!stated) {
          try {
            const carriers = [namedEl, trigger]
              .filter((el, i, a) => el && a.indexOf(el) === i)
              .filter((el) => el.matches('[aria-controls],[aria-owns]'))
              .concat(Array.prototype.slice.call(
                namedEl.querySelectorAll('[aria-controls],[aria-owns]')));
            for (const c of carriers) {
              const id = c.getAttribute('aria-controls') || c.getAttribute('aria-owns');
              const el = id && document.getElementById(id);
              if (!el || el === namedEl || el.contains(namedEl)) continue;
              const sel = S.robustSelector(el);
              if (sel && S.isU1Valid(sel)) { stated = sel; break; }
            }
          } catch (e) {}
        }

        // The wrapper that BUNDLES trigger and options — the survey's own
        // words: "no separate list element exposed, only the wrapper". The
        // list is right there, closed, INSIDE the named element, and closed
        // is fine: structure reads do not care about display. This also
        // covers the widget nothing synthetic can open — a menu that opens
        // on CSS :hover alone ignores clicks and dispatched hover events
        // both, and the only way in is to read it shut.
        if (!stated) {
          try {
            const OPT = 'li,[role="option"],[role="menuitem"],a[href],button';
            const queue = Array.prototype.slice.call(namedEl.children);
            let seen = 0;
            while (queue.length && seen++ < 200) {
              const node = queue.shift();
              const kids = Array.prototype.slice.call(node.children);
              // A node HOLDING the trigger is not the list — but the list may
              // sit beside the trigger inside it, so its children still get
              // their turn. Skipping the whole subtree missed exactly the
              // <ul> next to the button one level down.
              if (node === trigger || node.contains(trigger)) {
                for (const k of kids) queue.push(k);
                continue;
              }
              let hits = 0;
              for (const k of kids) {
                if (k.matches && k.matches(OPT)) hits++;
              }
              if (hits >= 2) {
                const sel = S.robustSelector(node);
                if (sel && S.isU1Valid(sel)) { stated = sel; break; }
              }
              for (const k of Array.prototype.slice.call(node.children)) queue.push(k);
            }
          } catch (e) {}
        }

        // A toggle has no panel to open; its two states are read off one
        // press, and probeToggle presses back so the box ends as it started.
        if (u1Type === 'checkbox' || u1Type === 'radio' || u1Type === 'switch') {
          const net = P.armNet();
          try {
            const t = await P.probeToggle(trigger);
            if (!t || t.skipped) return { err: (t && t.why) || 'This one could not be pressed.' };
            return { toggle: {
              checkedClass: t.checkedClass || null,
              uncheckedClass: t.uncheckedClass || null,
              saysOffByAbsence: !!t.saysOffByAbsence,
              hiddenInput: t.hiddenInput ? S.robustSelector(t.hiddenInput) : null,
              toggled: !!t.toggled,
              restored: !!t.restored,
            } };
          } finally { net.disarm(); }
        }

        // Read everything the mapping needs off one open target. Shared by
        // the click path — called while the widget is genuinely open — and
        // the hover path, which reads just after the close: the elements
        // persist, and structure reads do not care about visibility.
        const readOpen = (target) => {
          if (!target) return null;
          const rootSel = S.robustSelector(target);
          if (!rootSel) return null;
          const cap = { root: rootSel, shape: null, markup: null };

          // The smallest element holding both the trigger and what it
          // opened — the natural container for a combobox, and the scope
          // the listbox reader expects.
          let wrap = trigger.parentElement;
          while (wrap && wrap !== document.body && !wrap.contains(target)) {
            wrap = wrap.parentElement;
          }
          if (wrap === document.body) wrap = null;

          try {
            if (u1Type === 'dialog') {
              cap.shape = S.dialogShape(rootSel);
            } else if (u1Type === 'combobox') {
              cap.shape = S.comboboxShape(rootSel) ||
                          (wrap ? S.comboboxShape(S.robustSelector(wrap)) : null);
            } else if (u1Type === 'listbox' && wrap) {
              cap.shape = S.listboxShape(S.robustSelector(wrap));
            }
            if ((u1Type === 'listbox' || u1Type === 'combobox') && !cap.shape) {
              // A <select> swapped for a div has no text input, so the
              // combobox reader refuses it — but OPEN, it is a list with
              // rows, and the visible toggle stands where the textbox
              // would. Read the list off what actually appeared. The
              // trigger is named by what was actually PRESSED — the
              // descended-to button, not the wrapper it was found in.
              const rows = Array.prototype.slice.call(target.children)
                .filter((c) => c.nodeType === 1);
              const optSel = rows.length >= 2
                ? S.commonSelectorFor(target, rows, rootSel) : null;
              const pressedSel = S.robustSelector(trigger) || trigSel;
              cap.shape = {
                combobox: wrap ? S.robustSelector(wrap) : rootSel,
                listbox: rootSel,
                trigger: pressedSel,
                textbox: pressedSel,
                options: (optSel && optSel.selector) || '',
              };
            }
          } catch (e) { /* the markup below still comes back */ }
          try { cap.markup = S.extractComponent(cap.root); } catch (e) {}
          return cap;
        };

        const net = P.armNet();
        let r = null;
        try {
          // trust: this call opens ONE named component the mapping already
          // calls a disclosure widget, under the armed net — so a label like
          // "Register" or an href on the trigger is a misread, not a reason.
          r = await P.probeOne(trigger, {
            trust: true,
            whileOpen: (panel) => {
              let target = panel;
              if (!target && stated) {
                try { target = document.querySelector(stated); } catch (e) {}
              }
              return target ? readOpen(target) : null;
            },
          });
        } finally { net.disarm(); }

        // The click gave nothing — refused, or pressed with nothing new
        // appearing. The commonest honest reason is that the widget opens on
        // HOVER or focus: tooltips, and nav drop-downs that ignore clicks
        // entirely. Hovering is harmless, so it is always the next try, and
        // it also learns WHICH event opens — an answer the mapping records.
        if (!r || r.skipped || !(r.held && r.held.root)) {
          let hov = null;
          try { hov = await P.probeHover(trigger, {}); } catch (e) {}
          if (hov && hov.revealed && hov.revealed.length) {
            const cap = readOpen(hov.revealed[0]) || {};
            return {
              stated,
              root: cap.root || stated || null,
              shape: cap.shape || null,
              markup: cap.markup || null,
              opensOn: hov.opensOn,
              opened: hov.revealed.length,
              overlay: false,
              focusEntered: null,
              stateClass: null,
              restored: !!hov.restored,
            };
          }
        }

        if (!r || r.skipped) {
          return { err: (r && r.why) || 'This one could not be pressed.', stated };
        }
        const held = r.held || null;
        return {
          stated,
          pressed: S.robustSelector(trigger) || trigSel,
          root: (held && held.root) || stated || null,
          shape: (held && held.shape) || null,
          markup: (held && held.markup) || null,
          opened: (r.opened || []).length,
          overlay: !!r.overlay,
          focusEntered: r.focusEntered,
          stateClass: r.stateClass || null,
          restored: !!r.restored,
        };
      },
      args: [triggerSel, type],
    });
  } catch (e) { return { err: e.message }; }
  const out = (res && res[0] && res[0].result) || { err: 'The page gave no answer.' };
  // Pressed, and the page LEFT despite the net — put it back before anything
  // else runs against the wrong page. What was captured before the jump is
  // still good: the selectors were read while the right page was up.
  const nowTab = await chrome.tabs.get(tab.id).catch(() => null);
  const urlAfter = ((nowTab && nowTab.url) || '').split('#')[0];
  if (urlBefore && urlAfter && urlAfter !== urlBefore) {
    try {
      await chrome.tabs.update(tab.id, { url: urlBefore });
      await new Promise((r) => setTimeout(r, 1500));
      out.navigatedBack = true;
    } catch { /* the tab may be gone; the caller's next read will say so */ }
  }
  return out;
}

/**
 * Turns one discovery row into a mapping card: reads the element's markup, asks
 * the model to fill the component's fields, and renders the card.
 *
 * This is the paid step — one network round trip per component — and it is
 * shared by the per-card button and the bulk run so both spend the same way and
 * produce identical cards. The card must land in the DOM: aiCardTemplate reads
 * its values back out of #aiMapForm<idx>, and every per-card affordance (edit a
 * selector, Ask AI, Open in builder) works off it.
 *
 * Returns { idx } or { err }; it never throws for an expected failure, so a
 * bulk loop can record one bad selector and keep going.
 */
async function prepareOne(row, tab) {
  const track = document.getElementById('aiSlideTrack');
  // A menu's root has to be the DIRECT PARENT of the items — u1.fix.menu reads
  // the root's own children. <nav> is the element with the aria-label on it and
  // the one that looks like the answer, so it gets chosen constantly, and its
  // children are a logo, a search box and one <ul>: a menu of one item. Descend
  // to the list. Returns null when there is nothing better, and then we keep
  // what the specialist or the model chose.
  if (row.type === 'menu') {
    const better = await inPage(tab.id, (s) => window.__u1SelectorIntel.menuItemsRoot(s), [row.sel]);
    if (better && better !== row.sel) row.sel = better;
  }
  // A listbox is not a judgement call, so it is not asked as one.
  //
  // Inside the container: the clickable thing is the trigger, because it has the
  // event; the thing that CONTAINS several things is the listbox, because that
  // is the shape. The model has been asked three times and answered wrong three
  // times in three different arrangements — the button as the listbox, the
  // wrapper as the listbox, and the two swapped outright — each with a fluent
  // explanation, each with every field resolving. That is the signature of a
  // question that should be measured instead of asked.
  //
  // Measured here, and it OVERRIDES the answer below rather than filling a gap.
  let lbShape = null;
  if (row.type === 'listbox') {
    lbShape = await inPage(tab.id, (s) => window.__u1SelectorIntel.listboxShape(s), [row.sel]);
    // Read from the container that was pointed at; if that was already the list
    // itself, ask its parent, which is where the trigger lives.
    if (!lbShape) {
      lbShape = await inPage(tab.id, (s) => {
        const el = document.querySelector(s);
        const up = el && el.parentElement;
        return up ? window.__u1SelectorIntel.listboxShape(
          window.__u1SelectorIntel.robustSelector(up)) : null;
      }, [row.sel]);
    }
    // Still no shape, and the reason is almost always that the list is CLOSED
    // — a closed list has no rows to read. So open it: press the trigger from
    // inside the page, read the shape off the open state, press it shut.
    if (!lbShape && (row.trigger || row.sel)) {
      const cap = await autoOpenCapture(tab, row.trigger || row.sel, 'listbox');
      if (cap && cap.shape && cap.shape.listbox) lbShape = cap.shape;
    }
    if (lbShape) { row.sel = lbShape.listbox; row.trigger = lbShape.trigger; }
  }

  // The same move for a form, and for the same reason. u1.fix.form will not run
  // without submitButton, inputField and invalidField, and a model reading a
  // screenshot cannot supply any of the three: which control submits is a type
  // attribute, and what marks a bad field is a CSS rule. Asked anyway, it
  // returned three empty strings on a search box with a Go button in the
  // markup, and the save guard refused the whole component.
  //
  // Read, not overridden: whatever the model did answer is kept if it resolves.
  // invalidField is exempt from that test on purpose — it is SUPPOSED to match
  // nothing until a field goes bad.
  let fmShape = null;
  if (row.type === 'form') {
    fmShape = await inPage(tab.id, (s) => window.__u1SelectorIntel.formShape(s), [row.sel]);
  }

  // An accordion is rooted on its HEADER BUTTON — headerSelector is the PRIMARY
  // — and contentSelector is required. Detection points at the container,
  // because that is the element carrying the `accordion` class, so the mapping
  // came out as fix.accordion('#faqPanel', { headerSelector: '#faqPanel' }):
  // the container in the button's place, and the required content missing.
  // That is why mapping one did nothing at all.
  //
  // Measured, not asked. The heading level and the collapse behaviour are facts
  // about the markup — the wrapping <h3>, and whether one panel is open or
  // several — and a model that guesses them is guessing at something readable.
  let accShape = null;
  if (row.type === 'accordion') {
    accShape = await inPage(tab.id, (s) => window.__u1SelectorIntel.accordionShape(s), [row.sel]);
    if (accShape) row.sel = accShape.headerSelector;
  }

  // A radio group, measured the same way. The survey only ever names the
  // group; radioButton and checkedState are readable off the markup — the
  // pressable children and the state class exactly one of them carries
  // (elal's trip-type strip, refused at build until this existed).
  // A menu's drop-down wiring, measured. menu+items are all u1 REQUIRES, so
  // auto-built menus shipped without triggers/submenus — and those are what
  // give a drop-down its focus handling and arrow-key navigation ("the
  // top-level mapping is right, but focus never enters the submenu").
  let mnShape = null;
  if (row.type === 'menu') {
    mnShape = await inPage(tab.id, (s) => window.__u1SelectorIntel.menuShape(s), [row.sel]);
  }

  // Table/grid, carousel and pagination: their REQUIRED halves (row/cell,
  // slide, pageButtons) had no reader at all — the model either guessed or
  // the build refused. Measured now, filled only where the field is empty
  // or resolves to nothing.
  let tblShape = null, carShape = null, pgShape = null;
  if (row.type === 'table' || row.type === 'grid') {
    tblShape = await inPage(tab.id, (x) => window.__u1SelectorIntel.tableShape(x), [row.sel]);
  }
  if (row.type === 'carousel') {
    carShape = await inPage(tab.id, (x) => window.__u1SelectorIntel.carouselShape(x), [row.sel]);
  }
  if (row.type === 'pagination') {
    pgShape = await inPage(tab.id, (x) => window.__u1SelectorIntel.paginationShape(x), [row.sel]);
  }

  let rgShape = null;
  if (row.type === 'radio') {
    rgShape = await inPage(tab.id, (s) => window.__u1SelectorIntel.radioShape(s), [row.sel]);
    if (rgShape) row.sel = rgShape.radioGroup;
  }

  // An autocomplete, measured the same way. Nothing detects one — no class
  // pattern matches it, no role path finds it on a site that never wrote the
  // roles, and the probe can only ever answer tabs/menu/accordion/dialog — so
  // all four of its selectors had to be typed by hand. It has a SHAPE though:
  // a text input with a list of options beside it under a common parent, and
  // that is true whether or not the page says so.
  let cbShape = null;
  if (row.type === 'combobox') {
    cbShape = await inPage(tab.id, (s) => window.__u1SelectorIntel.comboboxShape(s), [row.sel]);
    // No shape while closed is the ordinary case, not a dead end — the list
    // half of a combobox only exists open, and a native <select> swapped for a
    // styled div has no text input for the reader to find at all. Open it and
    // read what actually appears; the visible toggle stands in for the
    // textbox when there is no real one.
    if (!cbShape) {
      const cap = await autoOpenCapture(tab, row.trigger || row.sel, 'combobox');
      if (cap && cap.shape && cap.shape.listbox) {
        cbShape = Object.assign({ combobox: row.sel }, cap.shape);
      }
    }
    if (cbShape) row.sel = cbShape.combobox;
  }

  // A dialog's close control, read off the markup. closeBtn is optional in the
  // schema, so the model treats it as optional in fact and the standing
  // instruction "leave a field out rather than guess" makes omitting it the
  // safe-looking answer every time — so dialog after dialog shipped with
  // nothing bound to close it, which is the one thing a keyboard user most
  // needs from a modal. An ✕, a Close/Cancel button, [aria-label*="close"] and
  // .modal-close are all readable, so they are read, not asked about.
  let dlgShape = null;
  if (row.type === 'dialog') {
    dlgShape = await inPage(tab.id, (s) => window.__u1SelectorIntel.dialogShape(s), [row.sel]);
  }

  // A checkbox mapping needs checkedState and uncheckedState — the class the
  // page adds when it goes on and the one it drops — and until now the only
  // way to get them was devtools, a press, and comparing two class attributes
  // by eye. Getting it backwards is silent and specific: the control announces
  // the opposite of what it is, every time. So it is pressed HERE, both
  // states read off the one press, and pressed back.
  let tgShape = null;
  if (row.type === 'checkbox') {
    const cap = await autoOpenCapture(tab, row.sel, 'checkbox');
    if (cap && cap.toggle && cap.toggle.toggled) tgShape = cap.toggle;
  }

  // Stage 6: a shape reader that resolved the anatomy is testimony — +0.4 on
  // the row's confidence, once, whichever reader answered.
  if ((lbShape || fmShape || accShape || cbShape || dlgShape || tgShape) && row.detConf != null) {
    row.detConf = Math.min(1, Math.round((row.detConf + 0.4) * 10) / 10);
  }

  // A link whose whole text is "Learn more" is a real link and a useless name
  // — in a screen reader's links list every card on the page reads
  // identically. u1.fix.link cannot rename anything; the aria-label custom
  // mapping exists precisely for this and had no way of being proposed. When
  // the card's own heading is there to read, the component IS that mapping.
  if (row.type === 'link') {
    const amb = await inPage(tab.id,
      (s) => window.__u1SelectorIntel.ambiguousLink(s), [row.sel]);
    if (amb && amb.headingSelector) {
      row.type = 'aria-label';
      row.ambiguousLink = amb;
    }
  }
  let markup = await inPage(tab.id, (s) => window.__u1SelectorIntel.extractComponent(s), [row.sel]);
  // Not on the page, but its opener is: a component built on demand — a modal
  // assembled at click time, a menu rendered on first open. Press the trigger,
  // read the markup while the thing exists, put the page back.
  if ((!markup || markup.error || markup.notFound) && row.trigger) {
    const cap = await autoOpenCapture(tab, row.trigger, row.type);
    if (cap && cap.markup && !cap.markup.error && !cap.markup.notFound) {
      if (cap.root) row.sel = cap.root;
      markup = cap.markup;
      if (row.type === 'dialog' && cap.shape && !dlgShape) dlgShape = cap.shape;
    }
  }
  if (!markup || markup.error || markup.notFound) {
    // Almost always the same cause: the scan was taken on one section and the
    // page has since moved on — another tab, a closed dialog, a re-render.
    // Saying "matches nothing" invites a hunt for a typo in a selector that
    // was correct when it was written.
    return { err: markup?.error ||
      `${row.sel} is not on the page right now. Scan results go stale as soon as you switch tab or section, or close what you had open — go back to that view, or scan this section again.` };
  }

  const schema = COMPONENT_SCHEMAS[row.type];

  // ── Nothing to ask ────────────────────────────────────────────────────────
  //
  // A link is `selectors: { element: PRIMARY }`. There is no second selector to
  // work out, no state to name, no shape to read — the mapping is entirely
  // determined by the selector already in hand. Same for a heading, whose only
  // extra is a level, and that is the tag. Same for a loading bar.
  //
  // Every one of these was still going to the model with a page of markup and
  // waiting on the answer. On the shop page that is sixteen of the twenty-four
  // mappings — nine links, four buttons, three headings — sixteen calls whose
  // reply the code could have written itself, each one a wait and a charge.
  //
  // A button's only field is `focusTo`, and it is optional: a scroll-to target
  // nobody has asked for. Not worth a call either; it stays editable on the
  // card like every other field.
  if (!needsModelToMap(row.type)) {
    const primaryKey = primaryKeyOf(schema);
    const fields = [];
    // The converted ambiguous link: every field measured, none asked for.
    if (row.type === 'aria-label' && row.ambiguousLink) {
      fields.push(
        { key: 'middleText', value: 'about',
          why: 'Joins the link\'s own words to the heading\'s.' },
        { key: 'headingSelector', value: row.ambiguousLink.headingSelector,
          why: `The card's own heading — "${row.ambiguousLink.headingText}" — so "${row.ambiguousLink.text}" finally says what it is about.` });
    }
    // The one measurable extra — and the one place the diagnosis used to be
    // thrown away at the moment it mattered. u1.fix.heading needs a level,
    // and this read it off the element's own tag: for a heading mapped
    // BECAUSE its level is wrong ("h6 where the outline calls for h3"), that
    // faithfully copied the defect into the fix. The outline already knows
    // what the sequence calls for; ask it, and fall back to the tag only for
    // a heading whose level was never the problem.
    if (row.type === 'heading') {
      const lvl = await inPage(tab.id, (sel) => {
        let el = null;
        try { el = document.querySelector(sel); } catch (e) { return null; }
        if (!el) return null;
        const own = Number((el.tagName.match(/^H(\d)$/) || [])[1]) ||
                    Number(el.getAttribute('aria-level')) || 0;
        const S = window.__u1SelectorIntel;
        try {
          for (const r of (S && S.headingOutline ? S.headingOutline() : [])) {
            let m = null;
            try { m = document.querySelector(r.selector); } catch (e) {}
            if (m === el) return { own, should: r.should || null, problem: r.problem || null };
          }
        } catch (e) {}
        return { own, should: null, problem: null };
      }, [row.sel]);
      if (lvl && lvl.should && lvl.should !== lvl.own) {
        fields.push({ key: 'level', value: String(lvl.should),
          why: `What the page's own outline calls for — the sequence ${lvl.problem === 'no level' ? 'gives this no level' : `skips to h${lvl.own}`}, and h${lvl.should} is the step it lands on. Copying the tag's h${lvl.own} would have written the defect into the fix.` });
      } else if (lvl && lvl.own) {
        fields.push({ key: 'level', value: String(lvl.own), why: 'From the element\'s own tag — the outline finds no fault with it.' });
      }
    }
    const local = {
      primary: row.sel,
      fields,
      options: [],
      confidence: 'high',
      notes: [`${row.type} needs only the element itself — worked out here, with no model call.`],
      usage: null,
    };
    const idx0 = aiMapped.length;
    aiMapped.push({ row, result: local, markup });
    track.insertAdjacentHTML('beforeend', renderAiMapCard(idx0, row, local, markup.recorderActive));
    fillAiMapCard(idx0, row, local);
    return { idx: idx0 };
  }

  const out = await U1AI.mapComponent({
    u1Type: row.type,
    containerSel: row.sel,
    markup,
    // The finding is the brief. The discovery stage already named the defect
    // — "missing aria-expanded on Members", "no role on the replacement div"
    // — and the mapping model used to be handed the markup with none of it,
    // so it mapped the component in general instead of mapping AT the fault.
    instruction: [
      row.trigger
        ? `The specialist identified "${row.trigger}" as the element that opens this ${row.type}. Use it for the trigger field and do not look for another.`
        : '',
      row.why
        ? `The scan's finding about this component: "${row.why}". Fill the fields so the mapping corrects exactly that.`
        : '',
    ].filter(Boolean).join('\n') || undefined,
    fields: schema.fields || [],
    fieldDocs: schema.desc || {},
    options: Object.keys(schema.rootFields || {}),
  });
  aiCost += U1AI.estimateCost(out.usage) || 0;
  if (out.err) return { err: out.err };

  // The specialist already told us which element opens this, and that is
  // better evidence than a guess from markup — so it wins over whatever the
  // model put in `trigger`.
  if (row.trigger) {
    out.fields = (out.fields || []).filter(f => f.key !== 'trigger');
    out.fields.unshift({ key: 'trigger', value: row.trigger,
                         why: 'The element you started from — you identified it as what opens this.' });
  }

  // A tabs mapping without a tabPanel is a tab strip that controls nothing:
  // U1 writes no aria-controls, the arrows move between the tabs, and the
  // content never follows. The schema requires it and the model leaves it out
  // anyway, so it is worked out from the page instead of asked for again —
  // mechanical, free, and it does not depend on the markup saying "tabpanel".
  if (row.type === 'tabs') {
    // Owner rule, same as menus: the LIST is the first parent of the first
    // tab, whatever its tag — the survey may name the whole section
    // (fix.tabs('#deals', {tabList:'#deals'}) shipped self-scoped and dead).
    // And the engine scopes fix.tabs: it waits for the tabList to appear
    // INSIDE the first argument (jQuery's $(selector, context) searches
    // descendants only), so the primary must be an ANCESTOR of the list.
    const tabField = (out.fields || []).find(f => f.key === 'tab');
    const tabSel = (tabField && tabField.value) || '[role="tab"]';
    const panelField = (out.fields || []).find(f => f.key === 'tabPanel' && String(f.value || '').trim());
    let panelValue = panelField ? String(panelField.value).trim() : '';
    const shape = await inPage(tab.id, (rowSel, tSel, pSel) => {
      const S = window.__u1SelectorIntel;
      const out2 = {};
      let tabs = [];
      try { tabs = [...document.querySelectorAll(tSel)]; } catch {}
      let scopeEl = null;
      try { scopeEl = document.querySelector(rowSel); } catch {}
      if (scopeEl && tabs.some((t) => scopeEl.contains(t))) tabs = tabs.filter((t) => scopeEl.contains(t));
      // No tab field and no role=tab on the page (the common case): the tabs
      // are the named element's own pressable children — the approval card
      // was showing tab/tabPanel as empty REQUIRED fields.
      if (tabs.length < 2 && scopeEl) {
        tabs = [...scopeEl.children].filter((k) => {
          try { return k.matches('button,a,[role="tab"],[tabindex]'); } catch { return false; }
        });
        if (tabs.length >= 2) out2.tabFromChildren = true;
      }
      if (tabs.length < 2) return null;
      const list = tabs[0].parentElement;
      if (!list || !tabs.every((t) => t.parentElement === list)) {
        out2.list = S.robustSelector(S.commonAncestor(tabs));
      } else {
        out2.list = S.robustSelector(list);
      }
      if (!out2.list || !S.isU1Valid(out2.list)) return null;
      if (out2.tabFromChildren) {
        const listEl0 = document.querySelector(out2.list);
        const tsel = listEl0 && S.commonSelectorFor(listEl0, tabs, out2.list);
        if (tsel && tsel.selector && S.isU1Valid(tsel.selector)) out2.tab = tsel.selector;
      }
      let panelEl = null;
      try { panelEl = pSel ? document.querySelector(pSel) : null; } catch {}
      out2.panelResolves = !!panelEl;
      const listEl = document.querySelector(out2.list);
      let anc = panelEl && listEl ? S.commonAncestor([listEl, panelEl]) : (listEl && listEl.parentElement);
      if (!anc || anc === listEl) anc = listEl && listEl.parentElement;
      if (anc && anc !== document.documentElement && anc !== document.body) {
        const rSel = S.robustSelector(anc);
        if (rSel && S.isU1Valid(rSel) && rSel !== out2.list) out2.root = rSel;
      }
      return out2;
    }, [row.sel, tabSel, panelValue]);

    if (shape && shape.list) {
      out.fields = (out.fields || []).filter(f => f.key !== 'tabList');
      out.fields.push({ key: 'tabList', value: shape.list,
        why: 'The first parent of the first tab — the strip itself. The mapping is rooted one level up because the engine waits for this to appear inside the first argument.' });
      if (shape.tab && !(tabField && String(tabField.value || '').trim())) {
        out.fields = (out.fields || []).filter(f => f.key !== 'tab');
        out.fields.push({ key: 'tab', value: shape.tab,
          why: 'The strip\u2019s own pressable children — measured, because the page never says role=tab.' });
      }
      if (!shape.panelResolves) {
        const panels = await inPage(tab.id,
          (listSel, tSel) => window.__u1SelectorIntel.tabPanelsFor(listSel, tSel),
          [shape.list, tabSel]);
        if (panels) {
          out.fields = (out.fields || []).filter(f => f.key !== 'tabPanel');
          out.fields.push({ key: 'tabPanel', value: panels,
            why: (panelValue ? `'${panelValue}' matches nothing on this page — replaced with the measured answer. ` : '') +
              'Worked out from the page — the panels these tabs switch between. Required: without it the tabs control nothing.' });
          panelValue = panels;
        }
      }
      // The root may improve now that the panel is real.
      if (shape.root) out.primary = shape.root;
      else {
        const root2 = await inPage(tab.id, (listSel, pSel) => {
          const S = window.__u1SelectorIntel;
          let list = null, panel = null;
          try { list = document.querySelector(listSel); } catch { return null; }
          try { panel = pSel ? document.querySelector(pSel) : null; } catch {}
          if (!list) return null;
          let anc = panel ? S.commonAncestor([list, panel]) : list.parentElement;
          if (!anc || anc === list) anc = list.parentElement;
          if (!anc || anc === document.documentElement) return null;
          const sel2 = S.robustSelector(anc);
          return sel2 && S.isU1Valid(sel2) && sel2 !== listSel ? sel2 : null;
        }, [shape.list, panelValue]);
        if (root2) out.primary = root2;
      }
    }
  }

  // The measured shape wins. Not a preference: the three fields below are
  // determined by the markup, and an answer that disagrees with the markup is
  // wrong however confidently it is phrased.
  if (lbShape) {
    out.fields = (out.fields || []).filter(
      (f) => f.key !== 'trigger' && f.key !== 'options');
    out.fields.unshift(
      { key: 'trigger', value: lbShape.trigger,
        why: 'The clickable element in this container — it carries the event that opens the list.' },
      { key: 'options', value: lbShape.options,
        why: 'The list\'s own items.' });
    out.primary = lbShape.listbox;
  }

  // Fill, don't override. The model may well have named the right submit
  // button from the picture; what it cannot do is invent one when it could not
  // see one, and that is the case this covers. A field it answered is replaced
  // only when the answer resolves to nothing on the page — except invalidField,
  // which is meant to.
  if (fmShape) {
    const already = new Map((out.fields || []).map((f) => [f.key, f]));
    for (const key of ['inputField', 'submitButton', 'invalidField', 'errorMsg', 'requiredField']) {
      const got = fmShape[key];
      if (!got || !got.selector) continue;
      const had = already.get(key);
      const hadValue = had && String(had.value || '').trim();
      if (hadValue && key === 'invalidField') continue;
      if (hadValue) {
        const n = await inPage(tab.id, (sel) => {
          try { return document.querySelectorAll(sel).length; } catch (e) { return -1; }
        }, [had.value]);
        if (n > 0) continue;
      }
      out.fields = (out.fields || []).filter((f) => f.key !== key);
      out.fields.push({ key, value: got.selector, why: 'Read off the page. ' + got.why });
    }
  }

  // Same rule for the accordion, and for the same reason: which element is the
  // header, which region it opens, and what level the heading is, are all
  // readable off the page. The model's answer here was a container in the
  // header's place and no content at all.
  if (mnShape) {
    // The MEASURED shape wins, as it does for a listbox: the model handed
    // STEP's mega nav items:"#megaNav>li:nth-child(1)>button" — one item of
    // seven — and fill-only-empty politely kept it. Owner rule: the menu
    // root is the first parent of the first item, whatever its tag, and the
    // parts are what the markup shows.
    out.fields = (out.fields || []).filter(
      (f) => !['items', 'triggers', 'submenus'].includes(f.key));
    out.fields.unshift({ key: 'items', value: mnShape.items,
      why: 'The menu\u2019s own top-level interactive children — read from the markup, covering every one.' });
    // Only ever together: submenus without a trigger cover makes U1 throw
    // ("Submenu must have a trigger element").
    if (mnShape.triggers && mnShape.submenus) {
      out.fields.push(
        { key: 'triggers', value: mnShape.triggers,
          why: 'The items that hold a drop-down — this is what wires focus into the submenus.' },
        { key: 'submenus', value: mnShape.submenus,
          why: 'The drop-down lists themselves — arrow keys navigate inside once both halves are named.' });
    }
    if (mnShape.menu) out.primary = mnShape.menu;
  }

  {
    const fillMeasured = (pairs, note) => {
      for (const [key, value] of pairs) {
        if (!value) continue;
        const had = (out.fields || []).find((f) => f.key === key && String(f.value || '').trim());
        if (had) continue;
        out.fields = (out.fields || []).filter((f) => f.key !== key);
        out.fields.push({ key, value, why: note });
      }
    };
    if (tblShape) {
      fillMeasured([['row', tblShape.row], ['cell', tblShape.cell]],
        'Measured off the table itself.');
      out.primary = tblShape.table;
    }
    if (carShape) {
      fillMeasured([['slide', carShape.slide], ['prevButton', carShape.prevButton], ['nextButton', carShape.nextButton]],
        'Measured — the densest run of same-shaped siblings is the slides.');
    }
    if (pgShape) {
      fillMeasured([['pageButtons', pgShape.pageButtons], ['prevButton', pgShape.prevButton], ['nextButton', pgShape.nextButton]],
        'Measured — the pressables whose faces are running numbers.');
    }
  }

  if (rgShape) {
    out.fields = (out.fields || []).filter(
      (f) => !['radioButton', 'checkedState', 'uncheckedState'].includes(f.key));
    out.fields.unshift(
      { key: 'radioButton', value: rgShape.radioButton,
        why: 'The group\u2019s own pressable children — read from the markup.' },
      { key: 'checkedState', value: rgShape.checkedState,
        why: 'The class exactly one option carries — the checked one.' });
    if (rgShape.uncheckedState) out.fields.push(
      { key: 'uncheckedState', value: rgShape.uncheckedState,
        why: 'Every option that does not carry the checked class.' });
    out.primary = rgShape.radioGroup;
  }

  if (accShape) {
    out.fields = (out.fields || []).filter(
      (f) => f.key !== 'contentSelector' && f.key !== 'headingLevel' && f.key !== 'collapsesOthers');
    out.fields.unshift(
      { key: 'contentSelector', value: accShape.contentSelector,
        why: 'The region each header opens — read from what the header controls.' },
      { key: 'headingLevel', value: accShape.headingLevel,
        why: 'From the heading wrapping the header button, not guessed.' },
      { key: 'collapsesOthers', value: accShape.collapsesOthers,
        why: accShape.collapsesOthers
          ? 'Only one panel is open on the page, so opening one closes the rest.'
          : 'Several panels can be open at once.' });
    out.primary = accShape.headerSelector;
  }

  if (cbShape) {
    out.fields = (out.fields || []).filter(
      (f) => !['textbox', 'listbox', 'options', 'label'].includes(f.key));
    out.fields.unshift(
      { key: 'textbox', value: cbShape.textbox, why: 'The field you type into.' },
      { key: 'listbox', value: cbShape.listbox, why: 'The list the suggestions appear in.' },
      { key: 'options', value: cbShape.options, why: 'The suggestions themselves — what a person picks.' });
    if (cbShape.label) {
      out.fields.push({ key: 'label', value: cbShape.label, why: 'The field\'s own label.' });
    }
    out.primary = cbShape.combobox;
  }

  // Measured beats omitted. Only fills what the model LEFT EMPTY — unlike the
  // shapes above it does not overrule a real answer, because a close control
  // the model found in the markup is the same kind of evidence this is.
  if (dlgShape) {
    for (const key of ['closeBtn', 'heading', 'trigger']) {
      if (!dlgShape[key]) continue;
      const had = (out.fields || []).find((f) => f.key === key && String(f.value || '').trim());
      if (had) continue;
      out.fields = (out.fields || []);
      out.fields.push({ key, value: dlgShape[key],
        why: key === 'closeBtn'
          ? 'The dialog\'s own close control, read off the markup. Without it there is nothing for U1 to bind closing to.'
          : key === 'trigger'
          ? 'The control whose exact-id reference (aria-controls / data-target / href) names this dialog. Without it focus never moves in on open.'
          : 'The dialog\'s heading — this is what a screen reader announces it as.' });
    }
  }

  // Measured beats read-by-eye. The state classes came off an actual press,
  // which is stronger evidence than a model reading a closed markup — so they
  // replace the model's answer the way the listbox shape does. Appending the
  // class to the element's own selector keeps it pointing at the same element
  // in the same words: `.opt` becomes `.opt.opt--on`. A comma-selector cannot
  // take that suffix as one string, so it is left to the model's answer.
  if (tgShape && !/,/.test(row.sel)) {
    const put = (key, cls, why) => {
      if (!cls) return;
      out.fields = (out.fields || []).filter((f) => f.key !== key);
      out.fields.push({ key, value: row.sel + '.' + cls, why });
    };
    put('checkedState', tgShape.checkedClass,
      'Pressed once and watched: this is the class the page adds when it goes on.');
    put('uncheckedState', tgShape.uncheckedClass,
      'The class the page drops when it goes on — how it says "off".');
    if (tgShape.saysOffByAbsence) {
      out.notes = (out.notes || []).concat(
        'This page says "off" by the ABSENCE of a class, and there is no U1-valid selector for an absence — the off state needs a class of its own from the site\'s developers.');
    }
    if (tgShape.hiddenInput) {
      const had = (out.fields || []).find((f) => f.key === 'exclude' && String(f.value || '').trim());
      if (!had) {
        out.fields.push({ key: 'exclude', value: tgShape.hiddenInput,
          why: 'The real <input> hiding inside the styled box, found while pressing — excluded so it does not take focus beside the thing standing in for it.' });
      }
    }
  }

  // The description is announced. It should be what the PAGE calls the thing.
  //
  // `menuDescription: "Sign in options"` was composed by a model looking at a
  // picture, and it is read out to a screen reader user as the name of the
  // component. The button next to it says "Sign In". The page has already
  // named this, in its own words, and those are the words the user will hear
  // spoken elsewhere on the site — so they are the ones to use. Composed prose
  // is kept only where the page offers nothing.
  {
    const descKey = Object.keys((COMPONENT_SCHEMAS[row.type] || {}).rootFields || {})
      .find((k) => /description$/i.test(k));
    if (descKey) {
      const words = await inPage(tab.id,
        (c, t) => window.__u1SelectorIntel.componentWording(c, t),
        [out.primary || row.sel, row.trigger || '']);
      if (words) {
        out.fields = (out.fields || []).filter((f) => f.key !== descKey);
        out.fields.push({ key: descKey, value: words,
          why: 'What the page itself calls this — the same words a person sees, so a screen reader says the same thing.' });
      }
    }
  }

  // Rename anything U1 cannot resolve, here, before the card is drawn.
  //
  // The save gate repairs this too, and has to — it is the one place every
  // route passes through. But by the time the save gate runs, the specialist
  // has already been shown the code, ticked it, and pressed Approve, and what
  // they were shown said `heading: "#siteLeavingAlert h3"` while a red banner
  // above the card explained that U1 refuses a descendant space. The card
  // should never have been able to show a name the engine cannot use.
  {
    const cand = [];
    if (out.primary && !isU1ValidSelector(out.primary)) cand.push(['', out.primary]);
    for (const f of (out.fields || [])) {
      if (typeof f.value === 'string' && f.value.trim() && !isU1ValidSelector(f.value)) {
        cand.push([f.key, f.value]);
      }
    }
    if (cand.length) {
      let fixed = null;
      try {
        fixed = await inPage(tab.id, (list) => list.map(([k, v]) => {
          try { return [k, v, window.__u1SelectorIntel.repairForU1(v) || '']; }
          catch (e) { return [k, v, '']; }
        }), [cand]);
      } catch (e) { fixed = null; }
      for (const [k, was, now] of fixed || []) {
        if (!now || !isU1ValidSelector(now)) continue;
        if (!k) { out.primary = now; continue; }
        const f = (out.fields || []).find((x) => x.key === k && x.value === was);
        if (f) {
          f.value = now;
          f.why = (f.why ? f.why + ' ' : '') +
            `Renamed from "${was}" — U1 resolves selectors through jQuery, which refuses a descendant space and a pseudo-class silently. Same element, name it can use.`;
        }
      }
    }
  }

  const idx = aiMapped.length;
  aiMapped.push({ row, result: out, markup });
  track.insertAdjacentHTML('beforeend', renderAiMapCard(idx, row, out, markup.recorderActive));
  fillAiMapCard(idx, row, out);
  return { idx };
}

// ─────────────────────────────────────────────────────────────────────────────
//  Make all of these accessible
//
//  Prepare every found component, then ONE approval screen, then one press that
//  saves and applies the lot. The per-card path is untouched and both coexist —
//  this is not the old global tick counter, which was removed because it counted
//  selections across a list while showing you a single card. Every row here is
//  named, previewed and individually un-tickable.
// ─────────────────────────────────────────────────────────────────────────────

let aiBulk = { running: false, abort: false, failed: [], armed: false, tabId: null, host: '' };

// The bulk run's own tab, the way sweepTab() is the sweep's. A run of model
// calls is pinned to the tab it started on; which tab happens to be in FRONT
// while it runs is not information about it.
async function bulkTab() {
  if (aiBulk.tabId == null) return null;
  try {
    const t = await chrome.tabs.get(aiBulk.tabId);
    return isInjectable(t) ? t : null;
  } catch { return null; }   // closed or navigated away
}

const chunksOf = (arr, n) => {
  const out = [];
  for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
  return out;
};

function setBulkStatus(msg, kind = 'info', ms = 0) {
  showNotice(document.getElementById('aiBulkStatus'), msg, kind, ms);
}

/**
 * The status line belonging to the stage that is actually on screen.
 *
 * Each AI stage carries its own, and setStage shows exactly one stage — so a
 * message written to another stage's line is painted into a display:none
 * container and is never seen. That is not a cosmetic problem: it is how
 * "Approve & apply does nothing" happened. The save was refused, correctly and
 * with a good sentence explaining why, into a hidden element.
 */
function stageStatusEl() {
  const byStage = {
    found: 'aiMapStatus',
    cards: 'aiCardStatus',
    review: 'aiBulkStatus',
    screens: 'sweepPicksStatus',
    components: 'sweepPicksStatus',
  };
  return document.getElementById(byStage[currentStage] || 'aiMapStatus') ||
         document.getElementById('aiMapStatus');
}

document.getElementById('aiMapAllBtn')?.addEventListener('click', async () => {
  const btn = document.getElementById('aiMapAllBtn');
  const stopBtn = document.getElementById('aiMapAllStopBtn');
  const status = document.getElementById('aiMapStatus');
  if (aiBulk.running) return;
  if (isReadonly()) {
    showNotice(status, 'Licence expired — existing mappings still work and export, but new ones are paused.', 'error', 6000);
    return;
  }

  if (!aiWorkspaceMatchesSite()) { warnWrongSite(status); return; }

  const cards = [...document.querySelectorAll('#aiCompTrack .ai-comp:not([data-done])')];
  const rows = [];
  const blocked = [];
  // Only on the run that was paid for. The first press exists to show a cost
  // estimate, and pressing widgets open all over the page during it would be a
  // side effect nobody asked for; on the armed press it is the work itself.
  let openTab = null;
  for (const comp of cards) {
    let built = rowFromCompCard(comp);
    if (built.err && built.focusTrigger && aiBulk.armed) {
      if (openTab === null) {
        const t = await getTab();
        openTab = isInjectable(t) ? t : undefined;
      }
      const found = (comp.querySelector('.ai-comp-sel')?.value || '').trim();
      const type = comp.querySelector('.ai-comp-type')?.value || '';
      const cap = (openTab && found) ? await autoOpenCapture(openTab, found, type) : null;
      const got = (cap && (cap.root || cap.stated)) || '';
      if (got) {
        const contInput = comp.querySelector('.ai-comp-cont');
        if (contInput) contInput.value = got;
        built = rowFromCompCard(comp);
      }
    }
    if (built.err) blocked.push({ comp, err: built.err });
    else rows.push({ comp, row: built.row });
  }
  if (!rows.length) {
    showNotice(status, blocked.length
      ? `None of these can be prepared automatically — ${blocked.length} still need a selector or a trigger. Handle them one at a time.`
      : 'Nothing left to prepare.', 'error', 6000);
    return;
  }

  // Spend nothing on the first press. One call per component is the whole cost
  // of this feature, and it should be a number the specialist saw before it was
  // charged, not one they find on a bill.
  if (!aiBulk.armed) {
    aiBulk.armed = true;
    const per = aiCost > 0 ? aiCost / Math.max(1, aiMapped.length) : 0;
    const estimate = per ? ` Roughly $${(per * rows.length).toFixed(2)} more, on top of $${aiCost.toFixed(3)} this session.` : '';
    btn.textContent = `Yes — prepare all ${rows.length}`;
    showNotice(status,
      `${rows.length} component${rows.length === 1 ? '' : 's'} means ${rows.length} model call${rows.length === 1 ? '' : 's'}.${estimate} Press again to start.` +
      (blocked.length ? ` (${blocked.length} will be left for you to do by hand.)` : ''),
      'warn', 12000);
    setTimeout(() => {
      if (!aiBulk.running) { aiBulk.armed = false; btn.textContent = '✨ Make all of these accessible'; }
    }, 12000);
    return;
  }

  const tab = await getTab();
  if (!isInjectable(tab)) { showNotice(status, 'Cannot read this page.', 'error', 4000); return; }

  clearApproved();   // this list is the batch, not the session
  aiBulk = { running: true, abort: false, failed: [], armed: false,
             tabId: tab.id, host: getHostname(tab) };
  btn.disabled = true;
  stopBtn.style.display = '';
  setStage('cards');

  try {
    for (let i = 0; i < rows.length; i++) {
      if (aiBulk.abort) break;
      const { comp, row } = rows[i];
      btn.textContent = `Preparing ${i + 1} of ${rows.length}…`;
      showMapBusy(row.label, i + 1, rows.length);
      comp.classList.add('is-working');
      try {
        const prepared = await prepareOne(row, tab);
        // One dead selector must not cost the other eleven their turn.
        if (prepared.err) aiBulk.failed.push({ label: row.label, err: prepared.err });
      } catch (err) {
        aiBulk.failed.push({ label: row.label, err: err.message });
      } finally {
        comp.classList.remove('is-working');
      }
    }
  } finally {
    await spotlightOff(tab);
    clearMapBusy();
    aiBulk.running = false;
    btn.disabled = false;
    btn.textContent = '✨ Make all of these accessible';
    stopBtn.style.display = 'none';
    stopBtn.disabled = false;
    stopBtn.textContent = '■ Stop';
  }

  renderBulkReview();

  // "Make all of these accessible" means MAKE them accessible — not "prepare
  // a list and wait to be asked a third time". The second press of the button
  // was the authorisation (the first showed the cost), and the sweep's build
  // route has auto-approved through this same button since it existed. The
  // review list still renders first, so what proceeds is exactly what it
  // shows: rows the model called low-confidence stay unticked and wait for a
  // person, and a pressed Stop withdraws the authorisation entirely.
  if (!aiBulk.abort && aiMapped.length) {
    document.getElementById('aiBulkApproveBtn')?.click();
  }
});

document.getElementById('aiMapAllStopBtn')?.addEventListener('click', () => {
  aiBulk.abort = true;
  const b = document.getElementById('aiMapAllStopBtn');
  b.disabled = true;
  b.textContent = 'Stopping…';
});

// Everything prepared and not yet approved, as one list to say yes to.
function renderBulkReview() {
  const wrap = document.getElementById('aiBulkReview');
  const list = document.getElementById('aiBulkList');
  const summary = document.getElementById('aiBulkSummary');
  if (!wrap || !list) return;

  const pending = aiMapped
    .map((entry, idx) => ({ entry, idx }))
    .filter(({ idx }) => !document.querySelector(`#aiSlideTrack .ai-map-card[data-card="${idx}"]`)?.dataset.done);

  if (!pending.length && !aiBulk.failed.length) { setStage(resumeStage()); return; }

  setStage('review');

  // Say how many are being held back, or they read as missing rather than as
  // waiting for a decision.
  const weak = pending.filter(({ entry }) => entry.result.confidence === 'low').length;
  summary.innerHTML =
    `<div class="ai-meta">${pending.length - weak} ready to apply` +
    (weak ? ` · <strong>${weak} left unticked — the model called ${weak === 1 ? 'it' : 'them'} low confidence</strong>` : '') +
    (aiBulk.failed.length ? ` · ${aiBulk.failed.length} could not be prepared` : '') +
    ` · ~$${aiCost.toFixed(3)} spent preparing these</div>`;

  const fails = aiBulk.failed.map(f => `
      <div class="ai-approved-row ai-bulk-row">
        <span class="ai-approved-tick warn">!</span>
        <div class="ai-bulk-body">
          <span class="ai-approved-label">${escapeHtml(f.label)}</span>
          <div class="ai-approved-why">${escapeHtml(f.err)}</div>
        </div>
      </div>`).join('');

  // A sweep produces one flat list of everything on a twelve-screen page, which
  // is a list with no sense of where anything is. Grouped by the section it
  // came from — with that section's own picture and its own share of the cost
  // — it can be read, and a whole screen can be dropped in one click.
  const groups = aiSweep.stops.filter(s => s.indexes.length);
  list.innerHTML = groups.length ? sweepGroupsHtml(groups, pending) + fails
                                 : pending.map(p => bulkRowHtml(p)).join('') + fails;
}

function bulkRowHtml({ entry, idx }) {
  const conf = ['high', 'medium', 'low'].includes(entry.result.confidence) ? entry.result.confidence : 'medium';
  // Low confidence is not ticked. Everything was, and the approve-all that
  // follows applied it — so a guess the model itself flagged as weak ("no h1
  // anywhere, I set level=2 as a guess, a specialist should verify") went onto
  // the page beside the work that was actually asked for.
  //
  // It stays in the list, with its warning and its reasoning, one tick away.
  // The judgement it needs is a person's, and ticked-by-default is the one
  // arrangement that guarantees it does not get one.
  const weak = conf === 'low';
  // Read the template fresh so the row shows what would actually be applied,
  // including any edit made in the carousel after this section was opened.
  const tpl = aiCardTemplate(idx);
  return `
      <div class="ai-approved-row ai-bulk-row" data-bulk-idx="${idx}">
        <input type="checkbox" class="ai-bulk-tick"${weak ? '' : ' checked'} aria-label="Apply ${escapeHtml(entry.row.label)}">
        <div class="ai-bulk-body">
          <span class="ai-approved-label">${escapeHtml(entry.row.label)}</span>
          <code>u1.fix.${escapeHtml(entry.row.type)}</code>
          <span class="ai-conf" data-c="${conf}">${conf}</span>
          ${weak ? '<span class="ai-sev" data-need="1">not ticked — read it first</span>' : ''}
          ${entry.row.needsWork === false
            ? '<span class="ai-sev" data-need="0">already looks correct</span>' : ''}
          <button class="btn-ghost btn-xs" data-bulk-edit="${idx}">Edit</button>
          <div class="ai-approved-why">${escapeHtml(tpl?.primary || entry.row.sel || '')}</div>
          ${tpl ? `<details class="ai-approved-code"><summary>Show the code</summary><div class="code-preview">${escapeHtml(tpl.code)}</div></details>` : ''}
        </div>
      </div>`;
}

function sweepGroupsHtml(groups, pending) {
  const byIdx = new Map(pending.map(p => [p.idx, p]));
  return groups.map((stop, i) => {
    const mine = stop.indexes.map(idx => byIdx.get(idx)).filter(Boolean);
    if (!mine.length) return '';   // every row in it has already been approved
    const img = safeImg(stop.thumb);
    const n = mine.length;
    return `
      <details class="sweep-group" data-stop="${stop.n}"${i === 0 ? ' open' : ''}>
        <summary>
          <input type="checkbox" class="sweep-group-tick" checked
                 aria-label="Apply everything found on screen ${stop.n}">
          ${img ? `<span class="mh-thumb" data-shot="${stop.n}">
                     <img class="mh-img" src="${img}" alt="Section ${stop.n}">
                     <img class="mh-preview" src="${img}" alt="">
                   </span>` : ''}
          <span class="sweep-group-name">Section ${stop.n}</span>
          <span class="sweep-group-meta">${n} component${n === 1 ? '' : 's'} · $${(stop.cost || 0).toFixed(3)}</span>
        </summary>
        <div class="sweep-group-body">${mine.map(p => bulkRowHtml(p)).join('')}</div>
      </details>`;
  }).join('');
}

// Ticking a whole section at a time is wired for both lists by
// wireGroupTicks, alongside the picks list it was written for.

document.getElementById('aiBulkBackBtn')?.addEventListener('click', () => {
  setStage('cards');
  showSlide(slideIndex('aiSlide'));
});

document.getElementById('aiBulkList')?.addEventListener('click', (e) => {
  const edit = e.target.closest('[data-bulk-edit]');
  if (!edit) return;
  const idx = Number(edit.dataset.bulkEdit);
  setStage('cards');
  showSlide(slideIndex('aiSlide'));
  document.querySelector(`#aiSlideTrack .ai-map-card[data-card="${idx}"]`)
    ?.scrollIntoView({ block: 'start', behavior: 'smooth' });
});

document.getElementById('aiBulkApproveBtn')?.addEventListener('click', async () => {
  const btn = document.getElementById('aiBulkApproveBtn');
  if (isReadonly()) {
    setBulkStatus('Licence expired — existing mappings still work and export, but new ones are paused.', 'error', 6000);
    return;
  }
  if (!aiWorkspaceMatchesSite()) { warnWrongSite(document.getElementById('aiBulkStatus')); return; }
  const ticked = [...document.querySelectorAll('#aiBulkList .ai-bulk-row[data-bulk-idx]')]
    .filter(r => r.querySelector('.ai-bulk-tick')?.checked)
    .map(r => Number(r.dataset.bulkIdx));
  const items = ticked.map(i => ({ i, tpl: aiCardTemplate(i) })).filter(x => x.tpl);
  if (!items.length) { setBulkStatus('Nothing is ticked.', 'error', 4000); return; }

  btn.disabled = true;
  const original = btn.textContent;

  // The approve is part of the run: saving and applying take real seconds,
  // and a tab switch in the middle used to re-point the panel — park the
  // workspace mid-save, move currentHostname, and file the tail of the batch
  // under the site in front. The same hold that protects the prepare loop
  // holds here; the tabId pinned by that loop is still in aiBulk.
  const wasRunning = aiBulk.running;
  aiBulk.running = true;

  try {
    // ── Phase A: save, strictly one at a time ────────────────────────────────
    // saveMappingEntry reads the list, mutates it and writes it back with no
    // locking, so running these concurrently would have each write clobber the
    // others and silently drop mappings. This loop is load-bearing, not style.
    //
    // `committed` starts as whatever is already saved for this host, and grows
    // as this batch saves — so item 8 in a sweep's "approve all" is checked
    // against item 3 from the SAME batch, not just against mappings that
    // predate this run. Without that, a whole-page sweep whose sections
    // overlap (a header visible in more than one section, say) would save two
    // different u1.fix.* calls on the same element and apply BOTH — this used
    // to be caught only after the fact, in Phase C below, by which point the
    // clash had already been written to the page. Checking here stops the
    // second mapping from ever being saved or applied in the first place.
    const bulkMapKey = storageKey('mappings', currentHostname);
    const committed = (await U1Store.get([bulkMapKey]))[bulkMapKey] || [];
    const saved = [];
    for (let n = 0; n < items.length; n++) {
      const it = items[n];
      btn.textContent = `Saving ${n + 1} of ${items.length}…`;
      setBulkStatus(`Saving ${n + 1} of ${items.length} — ${it.tpl.primary}`, 'info', 0);
      const clashes = await overlappingMappings(it.tpl.primary, committed);
      if (clashes.length) {
        // Visible in the SAME "applied in this batch" list everything else
        // lands in — not just tallied into aiBulk.failed, which belongs to
        // the pre-approval review screen this run has already moved past.
        // Reuses addApproved's existing clash-button UI (`data-dropkey`) so
        // resolving it — keep the earlier mapping, or drop it and re-run this
        // one — is one click, the same offer a post-hoc clash already gave.
        addApproved(aiMapped[it.i].row, {
          ok: false,
          msg: `Skipped — already mapped by ${clashes.map(c => `u1.fix.${c.type} on ${c.sel}`).join(', ')}. Two mappings on the same element fight; the earlier one stays.`,
          clashes,
        }, it.tpl.code);
        continue;
      }
      try {
        const r = await saveMappingEntry(it.tpl, { refreshUi: false });
        // Declining the role question is an answer, not a failure — it must not
        // land in the failed list beside real errors.
        if (r && r.cancelled) continue;
        saved.push(it);
        committed.push({ type: it.tpl.type, firstArg: it.tpl.firstArg, primary: it.tpl.primary });
      } catch (err) {
        aiBulk.failed.push({ label: it.tpl.primary, err: err.message });
      }
    }
    loadMappingsList();
    refreshExportInfo();

    // ── Phase B: apply, in chunks ────────────────────────────────────────────
    // applyMappingsBatch already takes an array and loops in-page, but each item
    // polls for up to 4s before concluding no-effect, so one big call would sit
    // silent for a minute. Five at a time keeps progress visible.
    const details = [];
    for (const chunk of chunksOf(saved, 5)) {
      const from = details.length + 1;
      const to = details.length + chunk.length;
      btn.textContent = `Applying ${from}–${to} of ${saved.length}…`;
      setBulkStatus(`Applying ${from}–${to} of ${saved.length}…`, 'info', 0);
      // overwriteRole travels with them. It was dropped here — so a mapping
      // whose role clash had been answered "replace it" was applied WITHOUT
      // the site's role being lifted, U1 refused to write over it, and the
      // element came back undecorated. The single-apply path threaded it and
      // this one did not, which is why it only ever went wrong in bulk: the
      // whole-page route saves and applies exclusively through here.
      const res = await applyMappingsBatch(chunk.map(x => ({
        type: x.tpl.type, primary: x.tpl.primary, firstArg: x.tpl.firstArg,
        config: x.tpl.config, overwriteRole: x.tpl.overwriteRole,
      })), (await bulkTab()) || undefined);
      chunk.forEach((x, j) => details.push({ x, verdict: describeApply(res, x.tpl, j) }));
      // Saving succeeded even when applying could not run, and the panel
      // re-applies everything on open — so this is not work to do again.
      if (!res.ok && res.u1Missing) {
        setBulkStatus('Saved. U1 is not loaded on this page so nothing was applied — it will apply next time the panel opens on a page that has U1.', 'error', 12000);
      }
    }

    // ── Phase C: report into the same approved list the single flow uses ─────
    // Clashes are no longer detected here — Phase A already refused to save
    // (let alone apply) anything that overlapped with a mapping already
    // committed in this same batch, so nothing that reaches `details` can
    // clash with anything else in it.
    for (const { x, verdict } of details) {
      const entry = aiMapped[x.i];
      const card = document.querySelector(`#aiSlideTrack .ai-map-card[data-card="${x.i}"]`);
      if (card) card.dataset.done = '1';
      if (entry?.row?.compIndex != null) {
        const comp = document.querySelector(`#aiCompTrack .ai-comp[data-i="${CSS.escape(entry.row.compIndex)}"]`);
        if (comp) comp.dataset.done = '1';
      }
      addApproved(entry.row, verdict, x.tpl.code);
    }

    setStage(resumeStage());
    const bad = details.filter(d => !d.verdict.ok).length;
    // AFTER setStage, and addressed to whichever stage it just chose —
    // resumeStage can land on cards or applied, and #aiMapStatus is hidden in
    // both.
    showNotice(stageStatusEl(),
      `${details.length} mapping${details.length === 1 ? '' : 's'} saved and applied` +
      (bad ? `, ${bad} with something to look at — see the list below.` : '.'),
      bad ? 'error' : 'success', 9000);
  } catch (err) {
    setBulkStatus('Failed: ' + err.message, 'error', 8000);
  } finally {
    aiBulk.running = wasRunning;
    btn.disabled = false;
    btn.textContent = original;
    // The hold is over; whatever tab is in front now decides what the panel
    // shows next — the same hand-back the single-scan flow does.
    if (!aiBulk.running) {
      const front = await getTab().catch(() => null);
      if (front) await onTabChanged(front);
    }
  }
});

// ─────────────────────────────────────────────────────────────────────────────
//  Whole page — the same two stages, run over every section by itself.
//
//  Automatic mode does one section per press. A real page is eight to twenty
//  of them, so the actual workflow was: scroll, press, wait, scroll, press —
//  twenty times. Every step of that already exists here; all that was missing
//  was doing them in a row.
//
//  Nothing reaches the site during the sweep. It prepares, and the one approval
//  screen at the end is still the only thing that writes.
// ─────────────────────────────────────────────────────────────────────────────

// 15% back, so a component sitting across the fold is whole in one of the two
// shots rather than cut in half in both.
const SWEEP_OVERLAP = 0.85;
// A page that grows as you scroll never ends. This is the backstop against
// following an infinite feed forever.
//
// It used to be 15, from when every section cost a model call — it was a
// spending guard wearing a loop guard's clothes. The survey costs nothing now,
// so a page taller than fifteen sections was simply being cut off with most of it
// unseen. The real end condition is a scroll position that stops moving; this
// only has to be higher than any page a person would actually scan. Sixty
// sections is about a minute and a half, and still free.
const SWEEP_MAX_STOPS = 60;
// Scrolling starts lazy images and whole sections loading. Capturing straight
// away photographs the skeleton.
const SWEEP_SETTLE_MS = 700;

/**
 * How much of a section is collected, and how much goes into one model call.
 *
 * These were a single number, and conflating them is what lost the tail of
 * every busy section. Collecting is free; asking is not. So collect everything
 * the survey counted, and spend the budget in batches — a 97-element section is
 * two calls, not sixty elements and silence about the other thirty-seven.
 */
const SWEEP_COLLECT_MAX = 250;
const SWEEP_ASK_BATCH = 60;

// phase: 'screens' once the free survey is done and you are choosing which
// sections to pay to read; 'components' once those have been read and you are
// choosing what to fix.
let aiSweep = { running: false, abort: false, phase: 'screens', stops: [], tabId: null };

const $sweepStatus = () => document.getElementById('sweepStatus');

// ─────────────────────────────────────────────────────────────────────────────
//  A sweep outlives the panel
//
//  It was memory only, so closing the browser — or the side panel, which the
//  browser closes for you — threw away a survey that had cost real money to
//  produce, with no way back except paying for it again. A sweep is per SITE
//  and it is durable: it is kept under the hostname, restored the next time
//  that site is in front of you, and only forgotten when you press Clear.
//
//  The `__` prefix marks it private, which keeps it out of exported backups.
//  It is a cache of one machine's scan, not the client's project data — it
//  should not travel to a colleague in a handover file.
// ─────────────────────────────────────────────────────────────────────────────
const sweepStoreKey = (host) => U1Store.PRIVATE_PREFIX + 'sweep_' + (host || currentHostname);

let sweepSaveTimer = null;

/**
 * Persist the survey. Debounced: the render functions call it, and a run
 * re-renders on every section.
 *
 * The thumbnails travel with it — they are the whole reason the list is worth
 * looking at, and "unlimitedStorage" is already granted for exactly this kind
 * of payload. `running`, `abort` and `tabId` are deliberately dropped: a
 * restored sweep is finished, and its tab is gone.
 */
// The debounce is right for typing and ticking, and wrong for a section
// boundary. "Finish one, save it, move to the next" has to mean the write
// actually happened before the next one starts — otherwise a run of quick
// sections coalesces into one save that has not landed yet when the panel is
// closed. saveSweepNow is the same write, awaited, with the pending debounce
// cancelled so it cannot fire again behind it.
function saveSweepNow() {
  clearTimeout(sweepSaveTimer);
  return sweepWrite();
}

function saveSweep() {
  clearTimeout(sweepSaveTimer);
  sweepSaveTimer = setTimeout(sweepWrite, 400);
}

function sweepWrite() {
  return (async () => {
    try {
      if (!aiSweep.stops.length) return;
      // The survey's own site, not the panel's. They are the same except when
      // something has moved the panel, and that is exactly when writing to the
      // panel's key files a scan under the wrong client.
      const host = aiSweep.host || currentHostname;
      await U1Store.set({
        [sweepStoreKey(host)]: {
          v: 1,
          savedAt: Date.now(),
          host,
          url: aiSweep.url || '',
          phase: aiSweep.phase,
          cost: aiCost,
          stops: aiSweep.stops,
        },
      });
      // And to the server, so a colleague on another machine opens this site
      // and sees the same survey — the same sections, the same pictures, the
      // same progress — instead of being asked to pay for it again.
      //
      // The sweep key is private (`__`), so U1Store.set's own sync hook does
      // not fire for it: a survey is not one of the site-scoped prefixes and
      // has its own shape, its own pictures and its own endpoint.
      if (await U1Auth.isLoggedIn()) {
        try {
          await U1Sync.pushSweep(host, {
            url: aiSweep.url, phase: aiSweep.phase, cost: aiCost, stops: aiSweep.stops,
          });
        } catch (err) {
          showNotice(document.getElementById('sweepPicksStatus'),
            'The scan is saved on this machine but did not reach the server, so your ' +
            'colleagues will not see it: ' + err.message, 'error', 12000);
        }
      }
    } catch (err) {
      // Storage being full must not take the run down with it — the results are
      // still on screen and still usable, they just will not survive the panel.
      showNotice(document.getElementById('sweepPicksStatus'),
        'The scan is on screen but could not be saved: ' + err.message, 'warn', 8000);
    }
  })();
}

/** Throw the stored survey away. Only Clear does this — never a tab change. */
async function forgetSweep(host) {
  try { await U1Store.remove([sweepStoreKey(host)]); } catch {}
}

/**
 * Put back the survey for the site now in front of us, if there is one.
 *
 * Nothing here costs anything or touches the page: it is the free half of the
 * work being handed back. The tab it ran on is not restored — that tab is
 * gone, and sweepTab() falls back to the one in front, which is the right
 * answer for a survey being reopened rather than continued.
 */
async function restoreSweep() {
  if (aiSweep.running || aiSweep.stops.length) return false;
  let saved;
  try { saved = (await U1Store.get([sweepStoreKey()]))[sweepStoreKey()]; } catch { return false; }
  if (!saved || !Array.isArray(saved.stops) || !saved.stops.length) return false;

  aiSweep = {
    running: false, abort: false,
    phase: saved.phase === 'components' ? 'components' : 'screens',
    stops: saved.stops, tabId: null, url: saved.url || '',
    // Filed under the site it was saved for, so continuing it later saves it
    // back to the same place.
    host: saved.host || currentHostname,
  };
  aiCost = saved.cost || 0;
  aiWorkspaceHost = currentHostname;
  if (aiSweep.phase === 'components') renderSweepPicks();
  else renderSweepScreens();

  // How old it is, said plainly. A scan from last week describes a page that
  // may have been redeployed twice since, and a stale survey that looks fresh
  // is worse than no survey — it spends money reading sections that moved.
  const summary = document.getElementById('sweepPicksSummary');
  if (summary) {
    summary.insertAdjacentHTML('beforeend',
      `<div class="sweep-restored">Restored from your last scan of this site, ` +
      `${describeAge(saved.savedAt)}. Nothing was charged to bring it back — ` +
      `scan again if the page has changed since.</div>`);
  }
  return true;
}

function describeAge(ts) {
  if (!ts) return 'earlier';
  // Not `const mins` — verify-sweep.mjs lifts the panel's own `const mins =`
  // helper out of this file by regex, and a second declaration of that name
  // anywhere above it is the one the regex finds.
  const ageMins = Math.round((Date.now() - ts) / 60000);
  if (ageMins < 2) return 'just now';
  if (ageMins < 60) return `${ageMins} minutes ago`;
  const ageHours = Math.round(ageMins / 60);
  if (ageHours < 24) return `${ageHours} hour${ageHours === 1 ? '' : 's'} ago`;
  const ageDays = Math.round(ageHours / 24);
  return `${ageDays} day${ageDays === 1 ? '' : 's'} ago`;
}

/**
 * One line in the scan log.
 *
 * A tall page produces two or three lines per section, and thirty sections
 * of that filled the panel and pushed the thing you actually came for — the
 * list of sections to pick from — off the bottom. So the log is an accordion:
 * shut by default, one nested section per section, and the summary line of
 * each carries that screen's result so the detail is there without being in
 * the way. Progress still shows while a sweep runs, because the outer summary
 * mirrors the latest line even while everything is closed.
 */
function sweepLog(n, what, kind, cost) {
  const box = document.getElementById('sweepLog');
  if (!box) return;
  box.style.display = '';

  let wrap = box.querySelector('.sweep-log-wrap');
  if (!wrap) {
    wrap = document.createElement('details');
    wrap.className = 'sweep-log-wrap';
    wrap.innerHTML =
      '<summary><span class="sweep-log-title">Scan log</span>' +
      '<span class="sweep-log-live"></span>' +
      // Reading a long run back means scrolling a small box and photographing
      // it a screenful at a time. One press hands the whole thing over as
      // text — every section's rows, whether or not its fold is open.
      '<button type="button" class="btn-ghost btn-xs sweep-log-copy">Copy</button></summary>' +
      '<div class="sweep-log-body"></div>';
    box.appendChild(wrap);
    const copyBtn = wrap.querySelector('.sweep-log-copy');
    copyBtn.addEventListener('click', async (e) => {
      // Inside a <summary>: without this the press also toggles the drawer.
      e.preventDefault();
      e.stopPropagation();
      const lines = [];
      wrap.querySelectorAll('.sweep-log-body .sweep-log-row, .sweep-log-body summary').forEach((el) => {
        const t = (el.innerText || '').replace(/\s+/g, ' ').trim();
        if (t) lines.push(el.tagName === 'SUMMARY' ? '## ' + t : t);
      });
      try {
        await navigator.clipboard.writeText(lines.join('\n'));
        copyBtn.textContent = 'Copied';
        setTimeout(() => { copyBtn.textContent = 'Copy'; }, 2000);
      } catch {
        copyBtn.textContent = 'Could not copy';
        setTimeout(() => { copyBtn.textContent = 'Copy'; }, 2500);
      }
    });
  }
  const body = wrap.querySelector('.sweep-log-body');

  const row = document.createElement('div');
  row.className = 'sweep-log-row';
  if (kind) row.dataset.kind = kind;
  row.innerHTML =
    `<span class="what">${escapeHtml(what)}</span>` +
    `<span class="cost">${typeof cost === 'number' ? '$' + cost.toFixed(3) : ''}</span>`;

  if (!n) {
    // Not about one section — the end of the page, a limit, a failure. These
    // are the lines worth seeing without opening anything, so they sit loose at
    // the bottom rather than inside a section.
    row.classList.add('sweep-log-note');
    body.appendChild(row);
  } else {
    let sec = body.querySelector(`.sweep-log-screen[data-n="${n}"]`);
    if (!sec) {
      sec = document.createElement('details');
      sec.className = 'sweep-log-screen';
      sec.dataset.n = String(n);
      sec.innerHTML = `<summary><span class="n">Section ${n}</span>` +
        '<span class="sum"></span></summary>';
      body.appendChild(sec);
    }
    sec.appendChild(row);
    // The last line that says something — "pressed 12, nothing opened" is
    // process, "form · tabs? — 51 elements" is the answer.
    if (kind !== 'skip' || !sec.querySelector('.sum').textContent) {
      sec.querySelector('.sum').textContent = what;
    }
  }

  const live = wrap.querySelector('.sweep-log-live');
  if (live) live.textContent = n ? `Section ${n} · ${what}` : what;
  if (wrap.open) body.scrollTop = body.scrollHeight;
}

/** How tall the page is in sections — the basis for the estimate. */
async function sweepMeasure(tab) {
  return inPage(tab.id, () => ({
    height: Math.max(document.documentElement.scrollHeight, document.body ? document.body.scrollHeight : 0),
    view: window.innerHeight,
    y: window.scrollY,
  }));
}

document.getElementById('sweepStopBtn')?.addEventListener('click', () => {
  aiSweep.abort = true;
  const b = document.getElementById('sweepStopBtn');
  if (b) { b.disabled = true; b.textContent = 'Stopping after this section…'; }
});

document.getElementById('sweepStartBtn')?.addEventListener('click', async () => {
  const btn = document.getElementById('sweepStartBtn');
  const status = $sweepStatus();
  if (aiSweep.running) return;

  if (isReadonly()) {
    showNotice(status, 'Licence expired — existing mappings still work and export, but new ones are paused.', 'error', 6000);
    return;
  }
  const tab = await getTab();
  if (!isInjectable(tab)) { showNotice(status, 'Cannot read this page.', 'error', 4000); return; }

  // A modal is open, and this route is about to scroll the page — which is
  // what closes one. The survey would then read the page BEHIND it and report,
  // truthfully and uselessly, that it found no dialog. Reported as: I opened a
  // dialog so it would scan it, and it did not.
  //
  // Nothing can make this route scan an open modal; scrolling is what it does.
  // But the conflict is visible before anything is spent, so it is said here
  // and the route that CAN do it is named.
  try {
    await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['selector-intel.js'] });
    const open = await inPage(tab.id, () => window.__u1SelectorIntel.openModalNow());
    if (open) {
      showNotice(status,
        `A dialog is open (${open}). This route scrolls the page from the top, which will close it — ` +
        `so it would survey the page behind it and find no dialog. Use Automatic (AI) instead: ` +
        `paste ${open} into its container box and press Scan it. That route does not scroll.`,
        'error', 16000);
      return;
    }
  } catch {}

  // No API key check and no "are you sure" here any more. This press only
  // photographs the page and counts what is on it, in the panel — it makes no
  // request and costs nothing, so asking permission for it was friction in
  // front of the free half. The confirmation belongs on the next press, which
  // is where the first call is made, and that is where it now lives.
  await runSweep(tab);
});

async function runSweep(tab) {
  const btn = document.getElementById('sweepStartBtn');
  const stopBtn = document.getElementById('sweepStopBtn');
  const status = $sweepStatus();
  const log = document.getElementById('sweepLog');

  // Pinned to the tab this ran on. Hovering a section scrolls the page and
  // draws on it, and `getTab()` answers with whatever tab is in FRONT — so
  // switching browser tabs and moving the mouse over the list scrolled and
  // marked up a completely different page. The results belong to the page they
  // came from, and so does everything that acts on them.
  // The site this survey is ABOUT, carried on the survey itself. sweepStoreKey
  // defaults to currentHostname, which is a property of whatever tab is in
  // front — so anything that re-points the panel mid-run also re-points where
  // the run is filed, silently, one save at a time. The panel is held during a
  // run now; this is so that a future path that moves currentHostname cannot
  // file a scan of one client's site under another client's name.
  aiSweep = { running: true, abort: false, phase: 'screens', stops: [],
              tabId: tab.id, url: tab.url || '', host: getHostname(tab) };
  aiBulk.failed = [];
  // "There is nothing there" and "I cannot see in there" used to produce the
  // same output. A page built on closed shadow roots surveys as empty —
  // honestly, but silently. One line at the top of the run says which page
  // this is, and it is the only thing shadowReport's answer can honestly buy.
  try {
    const shadow = await inPage(tab.id, () =>
      window.__u1SelectorIntel.shadowReport && window.__u1SelectorIntel.shadowReport());
    if (shadow && shadow.closedHosts) {
      sweepLog(0, `${shadow.closedHosts} closed shadow host${shadow.closedHosts === 1 ? '' : 's'} on this page — ` +
        `their contents cannot be scanned or mapped from outside`, 'err');
    }
  } catch { /* the survey itself is unaffected */ }
  // F-lite + D for the real walk, exactly as measured in verify-browser: one
  // snapshot decides press membership (live-rect membership was a coin flip —
  // the hero advances on its own clock), and the hint layer's strips are
  // seeded so a strip the markup announces always gets its presses.
  try {
    await ensureProbeNet(tab.id);
    await chrome.scripting.executeScript({
      target: { tabId: tab.id }, files: ['selector-intel.js', 'probe.js'] });
    await inPage(tab.id, () => {
      const P = window.__u1Probe;
      if (!P || !P.planRun) return 0;
      P.resetRun();
      const seeds = [];
      try {
        for (const rootEl of document.querySelectorAll(
          '[role="tablist"],[class*="tab" i],[class*="menu" i],[class*="nav" i]')) {
          if (seeds.length >= 60) break;
          const kids = [...rootEl.children].map((k) => {
            try {
              return k.matches('button,[role="button"],[role="tab"],summary') ? k
                : k.querySelector('button,[role="button"],[role="tab"],summary');
            } catch (e) { return null; }
          }).filter(Boolean);
          if (kids.length >= 2) for (const k of kids) { if (seeds.length < 60) seeds.push(k); }
        }
      } catch (e) {}
      window.scrollTo(0, 0);
      return P.planRun(document.body, { seeds });
    });
  } catch { /* the walk still runs, on live rects */ }
  if (log) { log.innerHTML = ''; log.style.display = 'none'; }
  btn.disabled = true;
  stopBtn.style.display = '';
  stopBtn.disabled = false;
  stopBtn.textContent = '■ Stop after this section';
  setStage('none');

  // Stamp the site these selectors come from, the same way a single scan does.
  aiWorkspaceHost = currentHostname;

  // Where the page was before we started moving it. A sweep ends fourteen
  // sections down, and leaving it there means the approval screen names
  // components nowhere near what is on the page behind it.
  const startedAt = (await sweepMeasure(tab))?.y || 0;

  // Selectors already dealt with — saved mappings — plus, as the
  // sweep goes, everything it has already found. Without the second half the
  // sticky header is discovered again at every scroll position.
  const handled = await alreadyHandled();
  // The same mappings, for the by-element test each section runs.
  const mapped = await mappedSelectors();

  // The camera that does not need the tab in front. It was written, documented
  // at length, and never once called — so every section still went through
  // captureVisibleTab, and captureVisibleTab photographs whatever is IN FRONT.
  // The entire apparatus for carrying on in the background existed and was
  // unreachable: switch tabs and the survey stood still until you came back.
  await announceCamera(tab);

  let n = 0;
  try {
    await inPage(tab.id, () => window.scrollTo(0, 0));
    await new Promise(r => setTimeout(r, SWEEP_SETTLE_MS));

    while (n < SWEEP_MAX_STOPS && !aiSweep.abort) {
      n++;
      const stop = {
        n, scrollY: 0, thumb: null, cost: 0,
        count: 0, components: '', inventory: '', truncated: false, sticky: 0, probed: [],
        compSels: [], continuedFrom: 0, continuesOnto: 0, positional: 0,
        mapped: 0, mappedKinds: '', mappedSels: [],
        scanned: false, found: [], indexes: [],
      };
      aiSweep.stops.push(stop);

      const pos = await sweepMeasure(tab);
      stop.scrollY = pos ? pos.y : 0;
      showSweepBusy(`Section ${n}`, 'Photographing this section.',
        pos && pos.height ? Math.min(100, ((pos.y + pos.view) / pos.height) * 100) : undefined);
      btn.textContent = `Section ${n}…`;

      // Survey only: collect what is here and photograph it. No numbers drawn,
      // no big screenshot, no model call — so a fifteen-screen page is looked
      // at in about twenty seconds and costs nothing.
      //
      // A sticky header travels with the viewport and would be counted again at
      // every stop, which is why it is dropped from the second section on.
      // Pressed BEFORE the picture is taken, so what the probe finds can be
      // drawn on it. The probe needs no screenshot of its own.
      let observed = [];
      // Always. It was a checkbox and turning it off only produced worse
      // answers — the scan reads what a component is CALLED, and opening it is
      // how it learns what the component does.
      {
        showSweepBusy(`Section ${n}`, 'Opening each component to see what it is.',
          pos && pos.height ? Math.min(100, ((pos.y + pos.view) / pos.height) * 100) : undefined);
        // F-lite: this section presses whoever the run's snapshot put in its
        // band; to:null means "to the end of the page" across the arg channel.
        const bandStep = pos && pos.view ? Math.round(pos.view * SWEEP_OVERLAP) : 0;
        const band = pos ? {
          from: pos.y,
          to: (!bandStep || pos.y + bandStep >= (pos.height || 0)) ? null : pos.y + bandStep,
        } : null;
        const probed = await probeScreen(tab, band);
        // Pressing things can still take the page somewhere, however careful
        // the probe is: it cancels link clicks and form submits, but a site
        // whose own handler does `location.href = '/search'` navigates as its
        // own work rather than as the click's default action, and nothing in
        // the page can cancel that. Reported from elal.com — the survey pressed
        // something, landed on עמוד חיפוש, and carried on measuring a page that
        // was no longer the one being surveyed.
        //
        // So it is checked rather than assumed, and the way back is the way it
        // came: back to the surveyed URL, and back to the scroll position this
        // section was read at.
        if (!(await sweepBackIfNavigated(tab, n))) {
          sweepLog(n, 'the page navigated away and would not come back — stopping here so the rest of the survey is not about another page', 'err');
          break;
        }
        await inPage(tab.id, (y) => window.scrollTo({ top: y, left: 0, behavior: 'instant' }), [stop.scrollY]);
        if (!probed) sweepLog(n, 'the probe could not run on this page', 'err');
        if (probed && probed.blocked && probed.blocked.length) {
          // "This page tried to navigate seven times" — finally said.
          sweepLog(n, `the page tried to navigate ${probed.blocked.length} time${probed.blocked.length === 1 ? '' : 's'} ` +
            `while being pressed — blocked (${probed.blocked[0].split(' ')[0]}…)`, 'err');
        }
        if (!probed) { /* handled above */ }
        else if (!probed.pressed) {
          sweepLog(n, 'nothing here could be pressed' +
            (probed.skipped ? ` — ${probed.skipped} were refused as unsafe` : ''), 'skip');
        } else if (!probed.components.length) {
          sweepLog(n, `pressed ${probed.pressed}, nothing opened`, 'skip');
        } else {
          observed = probed.components;
          stop.probed = probed.components;
          sweepLog(n, `pressed ${probed.pressed} · found ` +
            probed.components.map((c) => c.type).join(', '));
          if (!probed.restored) {
            sweepLog(n, 'a component would not close again — the page may look different', 'err');
          }
        }
      }

      const collected = await collectRegion(tab, '', handled, {
        thumb: true,
        surveyOnly: true,
        observed,
        drop: (c) => c.sticky && n > 1,
      });
      if (collected.err) { sweepLog(n, collected.err, 'err'); break; }
      stop.thumb = collected.thumb || null;

      // What here is ALREADY MAPPED — by the element, not the selector string
      // (see mappedOverlapOnPage). Counted on its own and taken out of the
      // component line, so a section reads "form · already mapped: menu,
      // listbox" instead of listing the site's mapped header as new work on
      // every section. The read step skips them too (stop.mappedSels), so
      // nothing is paid to have the model look at them again.
      {
        const compSel = (c) => c.component && c.selector ? c.selector : '';
        const probeSel = (o) => (o && o.root) || '';
        const ask = Array.from(new Set([
          ...collected.candidates.map(compSel), ...observed.map(probeSel)].filter(Boolean)));
        const hits = await mappedOverlapOnPage(tab, ask, mapped);
        const isMapped = (sel) => !!(hits && sel && hits[sel]);
        const kinds = new Map();
        for (const sel of ask) if (isMapped(sel)) kinds.set(hits[sel], (kinds.get(hits[sel]) || 0) + 1);
        stop.mappedSels = ask.filter(isMapped);
        stop.mapped = stop.mappedSels.length;
        stop.mappedKinds = [...kinds.entries()].map(([k, v]) => (v > 1 ? `${v} ${k}s` : k)).join(', ');
        collected.candidates = collected.candidates.filter(c => !isMapped(compSel(c)));
        observed = observed.filter(o => !isMapped(probeSel(o)));
      }

      stop.count = collected.candidates.length;
      stop.truncated = !!collected.truncated;
      stop.inventory = screenInventory(collected.candidates);

      // Read as well. The probe above covers what it could press; the reading
      // covers what announces itself, and neither is a superset of the other.
      stop.components = mergeComponents(screenComponents(collected.candidates), observed);
      // Which components are on this section, by selector. The same selector
      // appearing on two consecutive stops is the same element straddling the
      // fold — a table taller than the window — and saying so is what stops you
      // ticking the second section alone and mapping its bottom half.
      stop.compSels = collected.candidates
        .filter(c => c.component && c.selector)
        .map(c => c.selector);
      const prev = aiSweep.stops[aiSweep.stops.length - 2];
      if (prev && prev.compSels) {
        const shared = stop.compSels.filter(s => prev.compSels.includes(s));
        if (shared.length) {
          stop.continuedFrom = prev.n;
          prev.continuesOnto = n;
        }
      }
      // Which section the sticky header landed on. It is counted once, on the
      // first section that sees it — so that section has to say so, or
      // ticking only the middle of a page would silently leave out the site's
      // main navigation.
      stop.sticky = collected.candidates.filter(c => c.sticky).length;
      // Components whose only possible selector counts siblings. Worth knowing
      // BEFORE paying to read the section: the mapping will work and will be
      // fragile, and the better move may be to ask the client for a class.
      stop.positional = collected.candidates
        .filter(c => c.component && /:nth-|:first-child|:last-child|:only-child/.test(c.selector || '')).length;
      sweepLog(n,
        (stop.count
          ? (stop.components ? stop.components + ' — ' : 'no complex components — ') +
            `${stop.count}${stop.truncated ? '+' : ''} elements` +
            (stop.truncated ? ' · truncated' : '')
          : 'nothing on this section') +
        (stop.mapped ? ` · already mapped: ${stop.mappedKinds}` : ''),
        stop.count ? '' : 'skip');

      if (aiSweep.abort) break;

      // Down one section, less the overlap.
      //
      // behavior:'instant' is load-bearing. A page carrying the very ordinary
      // `html { scroll-behavior: smooth }` animates scrollTo, so window.scrollY
      // on the next line still holds the OLD value — and reading it there to
      // decide whether the page moved concluded "bottom reached" after the
      // first section, every time, on every site that has that one line of
      // CSS. The check has to happen after the scroll has actually landed, so
      // it is a second call after the settle rather than a return value here.
      const y0 = (await sweepMeasure(tab))?.y ?? 0;
      await inPage(tab.id, (frac) => {
        window.scrollTo({ top: window.scrollY + window.innerHeight * frac, left: 0, behavior: 'instant' });
      }, [SWEEP_OVERLAP]);
      await new Promise(r => setTimeout(r, SWEEP_SETTLE_MS));
      const y1 = (await sweepMeasure(tab))?.y ?? 0;
      // The page itself decides when this ends: a scroll position that will not
      // move is the bottom, whatever the height said before lazy content
      // changed it.
      if (y1 <= y0) {
        // Two very different things end a sweep here, and they look identical
        // from the outside: the page really is at its end, or it refused to
        // scroll at all. Saying which turns "it stopped after one section" into
        // something answerable.
        const atEnd = pos && (y1 + pos.view) >= pos.height - 4;
        sweepLog(0, atEnd
          ? `reached the bottom of the page (${Math.round(y1)}px)`
          : `the page would not scroll past ${Math.round(y1)}px of ${Math.round(pos ? pos.height : 0)} — stopping`,
          'skip');
        break;
      }
    }
    if (n >= SWEEP_MAX_STOPS && !aiSweep.abort) {
      sweepLog(0, `stopped at the ${SWEEP_MAX_STOPS}-section limit`, 'skip');
    }
  } catch (err) {
    sweepLog(0, 'Failed: ' + err.message, 'err');
  } finally {
    // Detach before anything else: Chrome's "is debugging this browser" banner
    // stays up for exactly as long as we are attached, and leaving it there
    // after the survey has ended is its own small lie about what is happening.
    await endBackgroundCapture();
    clearSweepBusy();
    aiSweep.running = false;
    btn.disabled = false;
    syncSweepStartBtn();
    stopBtn.style.display = 'none';
    // Our own numbers must never be left on the site's DOM, and the page goes
    // back where it was — the specialist did not scroll it here.
    try { await inPage(tab.id, () => window.__u1SelectorIntel.clearMarks()); } catch {}
    try { await inPage(tab.id, (y) => window.scrollTo(0, y), [startedAt]); } catch {}
    // Regroup: the rows were marked one by one while the run went, and now the
    // list can settle into "still to read" and "already read".
    if (aiSweep.phase === 'screens') renderSweepScreens();
    // Whatever the outcome. A run that found nothing still read those sections
    // and still paid for them, and that has to survive a panel reload — it did
    // not, because the only save on this path hung off a render that an empty
    // run never reached.
    saveSweep();
    // ── And put it on the page ────────────────────────────────────────────
    //
    // Applying was a button in the drawer that you had to remember. It is part
    // of the job, not a step after it: a mapping that is saved and not applied
    // is a page nobody has made accessible yet, and the run has just spent
    // twenty minutes deciding what to do to it.
    //
    // Everything the site has, not only what this run built — u1 decorates an
    // element once per page load, so a mapping made early in a run may never
    // have met the elements a later section re-rendered.
    //
    // The run-level pass (3.5): one classify over the whole walk's ledger,
    // with the sibling climb. Its answer REPLACES the per-section fragments
    // in stop.probed, so every later consumer — the typing merge, the
    // panel-recovery lookups — reads whole components instead of shards.
    try {
      const finalObs = await inPage(tab.id, () => {
        const P = window.__u1Probe, S = window.__u1SelectorIntel;
        if (!P || !P.classifyRun || !S) return null;
        const sy = window.scrollY || 0;
        return P.classifyRun().map((c) => {
          const parts = {};
          for (const k of Object.keys(c.parts || {})) {
            const sels = (c.parts[k] || []).map((e) => {
              try { return S.robustSelector(e); } catch (e2) { return ''; }
            }).filter(Boolean);
            if (sels.length) parts[k] = sels.length === 1 ? sels[0] : sels.join(',');
          }
          let rootSel = '', docY = 0;
          try { rootSel = S.robustSelector(c.root) || ''; } catch (e) {}
          try { docY = c.root.getBoundingClientRect().top + sy; } catch (e) {}
          return { type: c.type, root: rootSel, why: c.why, parts, docY };
        }).filter((c) => c.root);
      });
      if (finalObs && finalObs.length) {
        aiSweep.finalObserved = finalObs;
        const byY = [...aiSweep.stops].sort((a, b) => (a.scrollY || 0) - (b.scrollY || 0));
        for (let si = 0; si < byY.length; si++) {
          const from = byY[si].scrollY || 0;
          const to = si + 1 < byY.length ? (byY[si + 1].scrollY || 0) : Infinity;
          const mine = finalObs.filter((c) => c.docY >= from && c.docY < to);
          if (mine.length) byY[si].probed = mine;
        }
        sweepLog(0, `run-level pass: ${finalObs.length} whole component${finalObs.length === 1 ? '' : 's'} from the presses, fragments replaced`, '');
        // 4.2: a reveal that matched no pattern is said out loud in the log —
        // an existing row, never a new discovery card and never a guess.
        const unclassed = finalObs.filter((c) => !c.type);
        if (unclassed.length) {
          sweepLog(0, `observed, unclassified: ${unclassed.slice(0, 6).map((c) => c.root).join(' · ')}` +
            (unclassed.length > 6 ? ` · +${unclassed.length - 6} more` : '') +
            ' — something opened, no pattern matched; left for a person', 'skip');
        }
      }
    } catch { /* per-section observations stand */ }

    // The "Read more" cards, saved by the run itself. The mapping existed and
    // the headings-review button that proposes it lives three tabs away, so
    // it was never made — while a run that promises "make everything
    // accessible on its own" walked right past twelve identical links. Every
    // field is measured (cardDescriptions only reports the repeated kind and
    // validates the heading selector across every card), no model is
    // involved, and the guard below keeps a re-run from saving it twice.
    // Only in the do-not-stop mode: "show me, let me build" means exactly
    // that, and it still has the headings-review button.
    if (!sweepPause.on) {
      try {
        const named = await saveCardDescriptionMappings(tab);
        if (named) sweepLog(0, `${named} kind${named === 1 ? '' : 's'} of "read more" links named after their card headings`, '');
      } catch (err) {
        sweepLog(0, 'card descriptions: ' + err.message, 'err');
      }
    }

    // Silent: the run reports its own outcome below, and two verdicts about
    // one press is how neither gets read.
    try {
      const put = await applyAllMappings({ silent: true, tab: await sweepTab() });
      if (put && (put.applied || put.failed)) {
        sweepLog(0, `applied to the page — ${put.applied} of ${put.applied + put.failed}` +
          (put.failed ? `, ${put.failed} could not be` : ''), put.failed ? 'err' : '');
      }
    } catch (err) {
      sweepLog(0, 'saved, but could not be applied to the page: ' + err.message, 'err');
    }

    // If you said "I have moved on to another site" while this held the panel,
    // this is where it lets go.
    await followPendingSiteSwitch();
  }

  const total = aiSweep.stops.reduce((s, x) => s + x.count, 0);
  if (!total) {
    showNotice(status, 'Nothing on this page that is not already mapped.', 'success', 0);
    return;
  }
  status.style.display = 'none';
  aiSweep.phase = 'screens';
  renderSweepScreens();
}

/**
 * The COMPONENTS on this section, as the page itself declares them.
 *
 * This is the line worth reading. "22 links, 19 buttons" tells you how busy a
 * section is; "a nav, a carousel and a tab strip" tells you whether it is
 * worth paying to read — and that is the choice the list exists to support.
 *
 * Free, because none of it is judgement: role="tablist" IS a tab strip and
 * <form> IS a form. What the model is paid for is the part that IS judgement —
 * deciding that seven links and six drop-downs are one menu, and which element
 * is its root. Anything guessed from a class name is marked with a "?" so the
 * two are never confused.
 */
function screenComponents(candidates) {
  const sure = new Map();
  const maybe = new Map();
  for (const c of candidates || []) {
    if (!c.component || c.nested) continue;
    const into = c.maybe ? maybe : sure;
    into.set(c.component, (into.get(c.component) || 0) + 1);
  }
  // A guess is not worth repeating when the same component is already known to
  // be there — a `.hero-carousel` class beside role="region" says one thing.
  for (const k of sure.keys()) maybe.delete(k);
  const say = (m, q) => [...m.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([k, v]) => `${v > 1 ? v + ' ' : ''}${v > 1 ? k + (k.endsWith('s') ? '' : 's') : k}${q}`);
  return [...say(sure, ''), ...say(maybe, '?')].slice(0, 5).join(' · ');
}

/**
 * Operate this section's components and report what they turned out to be.
 *
 * Reading a page cannot see a widget built from bare <div>s with its handlers
 * hung in JavaScript. That is measured rather than assumed: the same page scores
 * 100% with its roles and class names and 0% with them stripped. Pressing it
 * works on both, because it never looked at either.
 *
 * Costs no model call and no money. What it costs is pressing things on someone
 * else's page, so it sits behind a switch and inside probe.js's own safety net.
 */
/**
 * One line describing the section, from what was read and what was observed.
 *
 * An observation outranks a guess about the same kind of thing: if pressing the
 * strip proved it is a tab strip, "tabs?" from a class name adds nothing and its
 * question mark is now simply wrong. Guesses about kinds nobody probed are kept
 * — the probe presses at most a dozen things per section, so its silence is
 * not evidence of absence.
 */
function mergeComponents(readLine, observed) {
  if (!observed || !observed.length) return readLine;
  const counts = new Map();
  for (const c of observed) counts.set(c.type, (counts.get(c.type) || 0) + 1);
  const proven = [...counts.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([k, v]) => (v > 1 ? `${v} ${k}${k.endsWith('s') ? '' : 's'}` : k));

  const kinds = new Set(counts.keys());
  const leftover = (readLine || '').split(' · ')
    .filter(Boolean)
    .filter(part => ![...kinds].some(k => part.includes(k)));

  return [...proven, ...leftover].slice(0, 5).join(' · ');
}

/**
 * Did pressing things take the page somewhere? Then go back.
 *
 * The probe cancels link clicks, form submits, beforeunload, window.open, and
 * (since the same report) location.assign/replace and history.pushState. What
 * it cannot cancel is `location.href = '/search'`: that is a setter on a host
 * object, it runs as the page's OWN handler rather than as the click's default
 * action, and there is no hook that sees it.
 *
 * So navigation is treated as something that will occasionally happen and is
 * recovered from, rather than something the net is trusted to have prevented.
 * The way back is the way it came: the surveyed URL, then the scroll position
 * the section was being read at — restored by the caller, which knows it.
 *
 * Returns true when the page is (still, or again) the one being surveyed.
 */
async function sweepBackIfNavigated(tab, n) {
  const from = aiSweep.url;
  if (!from) return true;
  // Compared without the hash: an in-page anchor is a move, not a navigation,
  // and the scroll restore below already puts that right.
  const bare = (u) => String(u || '').split('#')[0];
  const now = await chrome.tabs.get(tab.id).then((t) => t && t.url).catch(() => null);
  if (!now || bare(now) === bare(from)) return true;

  sweepLog(n, `the page went to ${bare(now)} — waiting to be back on the surveyed page`, 'err');
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const there = async () => {
    const t = await chrome.tabs.get(tab.id).catch(() => null);
    return !!(t && t.status === 'complete' && bare(t.url) === bare(from));
  };
  // The same three steps the dynamic scan takes, gentlest first — Back in the
  // history, then WAIT for the person to come back to the surveyed page (a
  // long, live countdown; Stop still works), and only then a hard
  // re-navigation. The survey continues from where it stopped, on the page it
  // was reading, never on the one a press happened to open.
  showSweepBusy(`Section ${n}`, 'Something navigated the page. Going back to where the survey was.');
  let back = false;
  try { await chrome.tabs.goBack(tab.id); } catch {}
  for (let i = 0; i < 16 && !back && !aiSweep.abort; i++) { await sleep(250); back = await there(); }
  if (!back && !aiSweep.abort) {
    try { await chrome.tabs.update(tab.id, { url: from }); } catch { return false; }
    for (let i = 0; i < 60 && !back; i++) { await sleep(250); back = await there(); }
  }
  if (!back) return false;
  // The page is new, so anything the run injected into the old one is gone.
  try {
    await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['selector-intel.js'] });
  } catch {}
  // And let the site's own scripts (and U1) settle before pressing anything.
  await sleep(600);
  return true;
}

async function probeScreen(tab, band) {
  try {
    await ensureProbeNet(tab.id);
    await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['probe.js'] });
  } catch { return null; }
  try {
    return await inPage(tab.id, async (sectionBand) => {
      const P = window.__u1Probe, S = window.__u1SelectorIntel;
      if (!P || !S) return null;
      // `idle` buys the two findings a press cannot make: a gallery you swipe,
      // which has no control to press and announces itself no other way, and a
      // thing that moves on its own and cannot be stopped, which is a WCAG
      // 2.2.2 failure nobody reports because nothing looks broken.
      //
      // It costs its own window per section, on top of the pressing, and a
      // sweep visits a lot of sections — so it is stated here rather than
      // defaulted into silently. Two seconds is under the shortest auto-advance
      // worth calling one (a slide nobody could read faster than that), and the
      // watch samples inside the window rather than only at its ends.
      // Infinity does not survive the executeScript argument channel, so an
      // open-ended band arrives as to:null and is widened back here.
      const sectionY = sectionBand
        ? { from: sectionBand.from || 0,
            to: sectionBand.to == null ? Infinity : sectionBand.to }
        : undefined;
      const out = await P.probeAll(document.body,
        { inViewport: true, settle: 80, max: 12, limit: 2500, idle: 2000, sectionY });
      // Selectors are worked out HERE, where the elements are. The panel never
      // handles a node — only a selector produced by the same code that
      // produces every other selector in the tool.
      const nameFor = (root, els) => {
        if (!els || !els.length) return '';
        if (els.length === 1) return S.robustSelector(els[0]);
        const common = root && S.commonSelectorFor ? S.commonSelectorFor(root, els) : null;
        return (common && common.selector) || els.map((e) => S.robustSelector(e)).join(',');
      };
      return {
        restored: out.restored, pressed: out.pressed, skipped: out.skipped,
        // Script navigations the net stopped during the presses — the report
        // the armNet comment promised and nothing ever surfaced.
        blocked: (out.blocked || []).slice(0, 20),
        components: out.components.map((c) => {
          const parts = {};
          for (const k of Object.keys(c.parts)) parts[k] = nameFor(c.root, c.parts[k]);
          const out = { type: c.type, root: c.root ? S.robustSelector(c.root) : '', why: c.why, parts };
          // Both of these were being dropped on the floor here, which is the
          // quietest way to lose a finding: observed correctly, reported
          // correctly, and then not carried across the boundary.
          if (c.autoAdvances) out.autoAdvances = true;      // WCAG 2.2.2
          if (c.stateClass) out.stateClass = c.stateClass;  // how the page says "open"
          // Whether focus followed what opened. A finding, not a condition —
          // a panel that covers the page is a dialog either way, and the ones
          // that get this wrong are the ones worth mapping.
          if (c.focusEntered != null) out.focusEntered = c.focusEntered;
          return out;
        }),
      };
    }, [band || null]);
  } catch { return null; }
}

/**
 * What kind of thing is on this section, counted in the panel from data the
 * page already handed back. No model, no network, no wait — which is the whole
 * reason the survey can afford to look at every section.
 */
function screenInventory(candidates) {
  const KIND = {
    a: 'links', button: 'buttons', input: 'inputs', select: 'inputs',
    textarea: 'inputs', form: 'forms', nav: 'navs', table: 'tables',
    img: 'images', iframe: 'iframes', video: 'media', audio: 'media',
  };
  // A role is the better answer where there is one — a <div role="tab"> is a
  // tab, not a div, and that is what you are choosing sections by.
  // A container and the things inside it are two different answers. Counting a
  // tablist among its own tabs reported the five-tab finder as six tabs — a
  // number that is wrong in the one place you are using numbers to choose.
  const ROLE = {
    tab: 'tabs', tablist: 'tab strips',
    menu: 'menus', menubar: 'menus',
    dialog: 'dialogs', alertdialog: 'dialogs',
    listbox: 'lists', option: 'options',
    combobox: 'comboboxes', grid: 'grids', table: 'tables', row: 'rows',
    checkbox: 'checkboxes', radio: 'radios', button: 'buttons', link: 'links',
  };
  const tally = new Map();
  for (const c of candidates || []) {
    const kind = ROLE[(c.role || '').toLowerCase()] || KIND[(c.tag || '').toLowerCase()] || 'other';
    tally.set(kind, (tally.get(kind) || 0) + 1);
  }
  // "other" is every div the collector picked up on a class hint. It is real,
  // but naming it adds nothing to a choice, so it sorts last and is dropped
  // once there is anything better to say.
  const rows = [...tally.entries()].sort((a, b) =>
    (a[0] === 'other') - (b[0] === 'other') || b[1] - a[1]);
  const named = rows.filter(([k]) => k !== 'other');
  return (named.length ? named : rows).slice(0, 4)
    .map(([k, v]) => `${v} ${v === 1 ? SINGULAR[k] || k : k}`).join(', ');
}

// Written out rather than stripped with a regex. Chopping /e?s$/ turns "tables"
// into "tabl" and "images" into "imag" — which is where the "1 tabl" in a real
// run came from. English is not regular enough to guess at in a label somebody
// is reading to make a decision.
const SINGULAR = {
  links: 'link', buttons: 'button', inputs: 'input', forms: 'form',
  navs: 'nav', tables: 'table', images: 'image', iframes: 'iframe',
  media: 'media', tabs: 'tab', 'tab strips': 'tab strip', menus: 'menu',
  dialogs: 'dialog', lists: 'list', options: 'option', comboboxes: 'combobox',
  grids: 'grid', rows: 'row', checkboxes: 'checkbox', radios: 'radio',
  other: 'other',
};

// ── The sections, to choose from ─────────────────────────────────────────────
// The survey above cost nothing. Reading a section costs a model call, so the
// choice sits here, in front of the first thing that is charged for — and it is
// made from the photographs, which is the one form in which fifteen sections
// can actually be judged at a glance.

// What a call costs and how long it takes. The money is measured from this
// session as soon as there is anything to measure; the times are not measured
// at all and are labelled as estimates wherever they are shown.
// scanSecs was a flat 15 seconds per section, used by all three places that
// quote a time: the estimate box, the cost dialog, and the "Left" line of a
// running scan. Nothing ever measured it. The COST tightens after the first
// call — sweepAvgCall does that — while the note underneath said "Times are
// estimates" as though that were a property of time rather than of nobody
// having looked.
//
// A 94-element section took 1:34. All three quoted 15 seconds, and the clock
// beside the quote ran past it six times over. That is not a slightly-off
// estimate; it is a number with nothing behind it.
//
// How long a section takes is mostly how much is on it, so the fallback
// scales with the element count, and a measured rate replaces it as soon as one
// section has actually been read.
const SWEEP_EST = {
  scanBase: 10, scanPerElement: 0.85,
  fixSecs: 15, fixPerElements: 6, fallbackCall: 0.13, fixCall: 0.10,
};

/**
 * How long reading a section of `elements` should take, in seconds.
 *
 * Measured seconds-per-element from the sections this session has already
 * read, applied to the one being quoted for — so a run over a long page gets
 * more honest with every screen, in time as well as in money.
 */
function sweepSecsFor(elements) {
  const n = elements || 0;
  const done = (aiSweep.stops || []).filter((s) => s.scanned && s.secs > 0 && s.count > 0);
  if (done.length) {
    const perEl = done.reduce((a, s) => a + s.secs / s.count, 0) / done.length;
    return Math.max(SWEEP_EST.scanBase, Math.round(perEl * n));
  }
  return Math.round(SWEEP_EST.scanBase + n * SWEEP_EST.scanPerElement);
}

/** True once a real duration has been recorded, so the note can stop hedging. */
const sweepTimesMeasured = () =>
  (aiSweep.stops || []).some((s) => s.scanned && s.secs > 0 && s.count > 0);

const sweepAvgCall = () =>
  (aiCost > 0 && aiMapped.length ? aiCost / aiMapped.length : SWEEP_EST.fallbackCall);

const mins = (secs) => secs < 90 ? `~${Math.round(secs)}s`
  : `~${Math.round(secs / 60)}–${Math.round(secs / 60) + 2} min`;

function renderSweepScreens() {
  const wrap = document.getElementById('sweepPicks');
  const list = document.getElementById('sweepPicksList');
  const summary = document.getElementById('sweepPicksSummary');
  if (!wrap || !list) return;
  // The naming pause now renders INSIDE this list, dropped out of its section's
  // row. Redrawing the list throws that away — host, handlers and all — and the
  // promise it is waiting on can then never resolve: the run hangs with no
  // panel and no way out. Toggling a switch in the summary above was enough to
  // do it, because that handler asks for a redraw.
  //
  // A pause owns the list while it is open. Everything a redraw would have
  // shown is still true when it closes, and the run redraws then.
  if (sweepLabel.resolve) return;

  const stops = aiSweep.stops;
  const elements = stops.reduce((s, x) => s + x.count, 0);
  const pickable = stops.filter(s => s.count).length;
  const todo = stops.filter(s => s.count && !s.scanned).length;
  // Once every section has been read, "what to read" and "how it should run"
  // are questions about a run that is over — they used to stay expanded
  // forever, standing between the completed run and the one thing left worth
  // doing: going back to scan again (Scan the whole page, above this).
  const sweepDone = stops.length > 0 && stops.every(s => !s.count || s.scanned);
  // Two decisions and a price used to sit in one unbroken block, so the eye
  // read them as one thing and the price looked like part of the choosing. They
  // are separate questions — what to read, then what that costs — and each now
  // says which it is.
  // One row, collapsed: what will be read and how the run behaves, stated as
  // answers ("Read: 2 unread sections · Mode: Don't stop"), with the controls
  // behind an edit toggle. Two open boxes of settings sat between the list
  // and the button that reads it, on a screen whose one job is to press that
  // button; the answers are what you need to see, the controls only when you
  // mean to change one.
  const summaryBody =
    `<details class="sweep-settings" id="sweepSettings">` +
      `<summary class="sweep-settings-row">` +
        `<span class="sweep-settings-item"><span class="sweep-settings-k">Read</span> ` +
          `<span id="sweepReadNow">${todo} unread section${todo === 1 ? '' : 's'}</span></span>` +
        `<span class="sweep-settings-item"><span class="sweep-settings-k">Mode</span> ` +
          `<span id="sweepModeNow"></span></span>` +
        `<span class="sweep-settings-edit" aria-hidden="true">settings</span>` +
      `</summary>` +
      `<div class="sweep-settings-body">` +
        `<div class="ai-meta">${stops.length} section${stops.length === 1 ? '' : 's'} · ` +
        `${elements} element${elements === 1 ? '' : 's'} · nothing spent yet</div>` +
        // Twenty-one sections is twenty-one clicks to clear, and "only the ones
        // with a carousel" starts from none rather than from all. "All" means
        // all the UNREAD ones — the read ones are paid for and are not part of
        // what the next press will charge for.
        // Nothing left to read: a ticked box offering to include zero sections
        // is a form for a decision that no longer exists. Say what happened.
        (todo === 0 && pickable > 0
          ? `<div class="ai-meta">All ${pickable} section${pickable === 1 ? '' : 's'} read — nothing left to include.</div>`
          : `<label class="sweep-all"><input type="checkbox" id="sweepAllTick"${todo ? ' checked' : ''}>` +
            `Include <span id="sweepUnreadCount">${todo}</span> unread section${todo === 1 ? '' : 's'}` +
            // The dash state. A half-ticked box is the commonest thing on this
            // screen — you untick a couple of sections — and nothing said so, which
            // made it read as broken rather than as "some".
            (pickable > todo
              ? ` <span class="sweep-all-sub">(${pickable - todo} already read — not ticked, cost nothing)</span>`
              : '') + `</label>`) +
        // ── How the run should behave, as one either/or ──────────────────
        // Two answers to one question, not two independent switches: either the
        // run stops at each section and waits for you, or it does not stop at
        // all. Both ticked is a state the run cannot honour, and both empty is
        // no answer — so they are radios, and the mutual exclusion is in the
        // markup rather than in a handler that has to remember to enforce it.
        `<div class="sweep-mode"><span class="sweep-mode-head">How it should run</span>` +
        `<label class="sweep-all sweep-radio"><input type="radio" name="sweepMode" id="sweepPauseTick"${
          sweepLabel.on || sweepPause.on ? ' checked' : ''}>` +
        `<span id="sweepModeStopLbl"></span></label>` +
        `<label class="sweep-all sweep-radio"><input type="radio" name="sweepMode" id="sweepSilentTick"${
          !sweepLabel.on && !sweepPause.on ? ' checked' : ''}>` +
        `<span id="sweepModeGoLbl"></span></label></div>` +
      `</div>` +
    `</details>`;

  // While the run is still live, these choices are still choices — shown
  // plain, the way they always were. Once nothing is left to read, they
  // become a record of a decision already acted on, so they fold away with
  // the rest of the finished run — a summary you can reopen, not a form you
  // have to look past.
  // Once the run is done this is a record, not a form — folded behind a
  // button rather than a standing accordion, the same way the cost breakdown
  // is. The content it opens is cached, since it no longer lives in the DOM
  // until the dialog is opened.
  sweepReadSummaryHtml = summaryBody;
  // Done: the resting screen shows nothing here. The two record buttons
  // (what it cost / what was read) belong to the finished run, so they live
  // inside its Completed drawer below, not standing on the main screen.
  summary.innerHTML = sweepDone ? '' : summaryBody;
  // typeof-guarded: verify-sweep lifts this function out and runs it alone.
  if (typeof updateSweepModeWording === 'function') updateSweepModeWording();

  // Two areas, because a half-finished run is the ordinary state — you start
  // one, you stop it, you come back tomorrow. "Which of these have I paid for
  // and which are still owed" is the only question the list has to answer then,
  // and a flat list of twenty-six rows with a small tag on some of them does
  // not answer it at a glance.
  const left = stops.filter(x => !x.scanned);
  const read = stops.filter(x => x.scanned);
  // What the completed sections are actually WORTH. A drawer that only counts
  // sections answers "how far have I got" and not "is there anything in there
  // for me yet" — and the second is what decides whether the rest of the run
  // has to finish before any of it can be used.
  const foundSoFar = read.reduce((a, x) => a + ((x.found || []).filter(f => !f.done).length), 0);
  const listHtml = read.length
    ? // Left empty rather than saying so: a done run already says so through
      // the two buttons that replace this whole area once nothing is ticked.
      (left.length
        ? `<div class="sweep-part"><h4>Still to search · ${left.filter(x => x.count).length}</h4>` +
          left.map(sweepScreenRowHtml).join('') + `</div>`
        : '') +
      // Open while there is still a "still to search" list above it, for the
      // same reason a receipt stays visible mid-purchase. Once that list is
      // gone, this is the only thing left on screen — leaving it expanded
      // then is a scroll of finished rows between you and scanning again.
      // Clear lives on this row now — the one place on the finished screen
      // that is about the survey as a whole, rather than about one section
      // or one press of Read.
      `<details class="sweep-part sweep-part-done"${sweepDone ? '' : ' open'}><summary>Completed · ${read.length}` +
      (foundSoFar
        ? ` · ${foundSoFar} component${foundSoFar === 1 ? '' : 's'} found` +
          `<button class="btn-outline btn-xs" data-build-found>${aiSweep.running
            ? 'Stop and build these' : 'Build fixes for these'}</button>`
        : '') +
      `<button class="btn-outline btn-xs" data-sweep-clear>Clear</button>` +
      `</summary>` +
      // The finished run's record, inside its own drawer: open Completed and
      // the cost and the read summary are the first things in it. On the
      // resting screen itself they are gone — that screen belongs to the
      // scan button.
      (sweepDone
        ? `<div class="btn-row sweep-done-info">` +
            // States the answer, not the question: what this run spent.
            `<button type="button" class="btn-outline btn-sm" id="sweepEstBtn">💰 Spent $${
              read.reduce((a, x) => a + (x.cost || 0), 0).toFixed(2)} · details</button>` +
            `<button type="button" class="btn-outline btn-sm" id="sweepReadBtn">⚙️ What was read · ${stops.length} section${stops.length === 1 ? '' : 's'} · ${elements} element${elements === 1 ? '' : 's'}</button>` +
          `</div>`
        : '') +
      read.map(sweepScreenRowHtml).join('') + `</details>`
    : stops.map(sweepScreenRowHtml).join('');
  list.innerHTML = listHtml;
  // The one-section fold belongs to an open pause. Redrawing the list removes
  // the bar that toggles it but not the class that hides everything, so the
  // other twenty-two stayed hidden with no way to bring them back.
  list.classList.remove('lbl-focus');
  // Re-apply the "reading now" mark the redraw just threw away.
  if (aiSweep.running && sweepReadingNow != null) markScreenReading(sweepReadingNow);

  // On a finished run the list (what was found) matters more than the two
  // buttons above it (a record of what was read and what it cost) — so it
  // moves ahead of them instead of sitting stranded below.
  wrap.classList.toggle('is-sweep-done', sweepDone);

  setStage(mapMode === 'sweep' ? 'screens' : 'none');
  syncSweepMakeBtn();
  if (typeof syncSweepStartBtn === 'function') syncSweepStartBtn();
  saveSweep();
}

/**
 * One filled button per state. Before a survey the scan button is the only
 * thing to do, so it is the primary. Once there are sections, the primary is
 * the button that reads them, and this one steps back to a small ghost
 * "Rescan" — it never leaves (the resting screen after a finished run is
 * still its screen), it just stops competing.
 */
function syncSweepStartBtn() {
  const btn = document.getElementById('sweepStartBtn');
  if (!btn) return;
  const surveyed = !!(aiSweep.stops && aiSweep.stops.length);
  if (aiSweep.running) return;                 // the run owns the label while it goes
  btn.classList.toggle('btn-primary', !surveyed);
  btn.classList.toggle('btn-outline', false);
  btn.classList.toggle('btn-ghost', surveyed);
  btn.classList.toggle('btn-sm', surveyed);
  btn.textContent = surveyed ? '↻ Rescan' : '🪄 Scan the whole page';
  btn.title = surveyed ? 'Survey the page again from the top — free, no model call' : '';
}

/**
 * One section, as a row you can tick to pay to read it.
 *
 * Pulled out of renderSweepScreens so the same row can be shown again AFTER a
 * read, under "not read yet" — reading the first screen used to replace the
 * whole list with its results, and the other seventeen sections simply
 * disappeared with no way back to them short of scanning the page again.
 */
function sweepScreenRowHtml(stop) {
    // The survey's component line, split into what it is sure of and what it
    // guessed. screenComponents() writes a guess with a trailing "?" ("2
    // buttons?"); that is data the scan log also carries, so the string is
    // left alone and only PARTED here — the sure part is shown as text, the
    // guesses are counted into one explicit chip. Inner, not a sibling
    // function: verify-sweep lifts this function out by name and runs it on
    // its own, so everything it needs has to travel with it.
    const splitSweepGuess = (components) => {
      const sure = [], maybe = [];
      let uncertain = 0;
      for (const part of String(components || '').split(' · ').filter(Boolean)) {
        if (part.endsWith('?')) {
          const m = /^(\d+)\s/.exec(part);
          uncertain += m ? Number(m[1]) : 1;
          maybe.push(part.slice(0, -1));
        } else sure.push(part);
      }
      return { sure: sure.join(' · '), maybe: maybe.join(' · '), uncertain };
    };
    const img = safeImg(stop.thumb);
    const empty = !stop.count;
    // A section that has already been read starts UNTICKED. It was ticked, so
    // pressing Read a second time — to pick up the ones that failed, or the
    // ones a longer page added — quietly paid for all of them again. Still
    // tickable by hand: re-reading one deliberately is a real thing to want,
    // and it should cost a deliberate click.
    const done = !!stop.scanned;
    const failed = !done && !!stop.failed;
    const guess = splitSweepGuess(stop.components);
    const chip = (text, cls, title) =>
      `<span class="sw-chip${cls ? ' ' + cls : ''}"${title ? ` title="${escapeHtml(title)}"` : ''}>${text}</span>`;
    // The metadata, as chips rather than one long sentence. Each fact is a
    // thing you scan for — "how many links", "does it continue" — and a
    // sentence makes you read past the ones you do not want.
    const chips = [
      chip(`${stop.count}${stop.truncated ? '+' : ''} element${stop.count === 1 ? '' : 's'}`),
      ...String(stop.inventory || '').split(', ').filter(Boolean).map(x => chip(escapeHtml(x))),
      // A sticky header is counted once, on the section that first sees it.
      // Ticking only the middle of a page would otherwise leave out the site's
      // main navigation with nothing to say it had.
      stop.sticky ? chip(`includes the sticky header (${stop.sticky})`, '', 'Counted here once, so ticking only the middle of the page does not leave the site navigation out') : '',
      // Something here runs past the edge of the picture and carries on in the
      // next section. Tick one without the other and you map half of it.
      stop.continuedFrom ? chip(`↤ continued from section ${stop.continuedFrom}`, 'sw-chip-link', 'A component here starts in the previous section — tick both to map all of it') : '',
      stop.continuesOnto ? chip(`continues onto section ${stop.continuesOnto} ↦`, 'sw-chip-link', 'A component here carries on into the next section — tick both to map all of it') : '',
      // An observation is worth marking as one: these were not read off the
      // markup, they were opened and watched.
      (stop.probed || []).length ? chip(`${stop.probed.length} confirmed by opening ${stop.probed.length === 1 ? 'it' : 'them'}`, 'sw-chip-ok') : '',
      // Guesses from a class name rather than a role, said as what they are.
      guess.uncertain ? chip(`${guess.uncertain} uncertain`, 'sw-chip-uncertain', `Guessed from a class name, not a role: ${guess.maybe}`) : '',
      // What this section cost — a fact once it has been read, and worth
      // stating on the card that was charged rather than in a total elsewhere.
      done ? chip(stop.cost ? `charged $${Number(stop.cost).toFixed(2)}` : 'read · nothing charged', 'sw-chip-cost') : '',
      failed ? chip('nothing charged', 'sw-chip-cost') : '',
    ].filter(Boolean).join('');
    // Everything guessed and nothing confirmed, after a paid read, is a result
    // — and an empty card is what it used to look like.
    const allUncertain = done && !(stop.found || []).length && !guess.sure && guess.uncertain > 0 && !stop.outcome;
    // typeof-guarded: verify-sweep lifts this function out and runs it alone.
    const open = typeof sweepOpenRows !== 'undefined' && sweepOpenRows.has(stop.n);
    return `
      <div class="ai-approved-row ai-bulk-row sweep-screen${empty ? ' is-empty' : ''}${done ? ' is-done' : ''}${failed ? ' is-failed' : ''}${open ? ' is-open' : ''}" data-screen="${stop.n}">
        <input type="checkbox" class="sweep-screen-tick" ${empty ? 'disabled' : (done ? '' : 'checked')}
               aria-label="Search section ${stop.n}${done ? ' again' : ''}">
        ${// One screen, on its own, now.
          //
          // Ticking and pressing the button at the bottom is the right shape
          // for "read these nine" and the wrong shape for "just this one" —
          // which is what a page actually gets worked through as: read one,
          // build its fixes, apply them, look at the page, read the next. That
          // took three actions (untick all, tick one, scroll to the button)
          // where it should take one, and every one of them is a chance to pay
          // for a screen you did not mean.
          //
          // Same run, same guard, same cost dialog — it is the ticking that is
          // skipped, not the confirmation.
          empty ? '' :
          `<button class="btn-icon sweep-play" data-play-screen="${stop.n}"${aiSweep.running ? ' disabled' : ''}
                   title="Run this section only — one call"
                   aria-label="Run section ${stop.n} only — one call">▶</button>`}
        ${img ? `<span class="mh-thumb" data-shot="${stop.n}">
                   <img class="mh-img" src="${img}" alt="Section ${stop.n}">
                 </span>` : ''}
        <div class="ai-bulk-body">
          <span class="ai-approved-label">Section ${stop.n}${done ? ' <span class="sweep-read-flag">completed</span>' : ''}${
            // Failed is a state with a way out, not a tag. The card stays in
            // the list, says so, and carries the retry itself.
            failed ? ` <span class="sweep-fail-flag">⚠ Failed</span>` : ''}</span>
          ${failed ? `<button type="button" class="btn-outline btn-xs sweep-retry" data-play-screen="${stop.n}"${aiSweep.running ? ' disabled' : ''}
                   title="Read this section again — one call">Retry</button>` : ''}
          ${// The components come first and in the panel's own text colour.
            // "22 links, 19 buttons" says how busy a section is; the components
            // say whether it is worth paying to read, which is the actual choice.
            //
            // A section with none says so out loud. Left blank, an unmarked
            // picture reads as "the tool missed it" rather than "there is
            // nothing here but links and text" — which is a real answer, and
            // usually a reason not to spend a call on it.
            //
            // "no COMPLEX components", not "no components": a section of
            // links, buttons and inputs is full of components, they are just
            // the simple kind that needs no mapping. The shorter wording read
            // as "nothing here", which is wrong and reads as a failure.
            // ── Once it has been searched, the guess is no longer the answer ──
            //
            // The survey line is a free guess read off the markup: "6 menus ·
            // form · dialog? · carousel?". The search then returned two
            // components — and the row went on displaying the guess, so the
            // panel showed one set of things in the survey and a different set
            // in the results with nothing in between. Asked, exactly: where is
            // this and where is that.
            //
            // Both are true, and they answer different questions. The guess
            // counts what is ON the section. The search reports what is LEFT to
            // map — and most of the difference is that the rest is already
            // mapped, or was found in an earlier section. That sentence already
            // existed, as stop.outcome, written into the scan log: collapsed,
            // and two panels away from the row that raised the question.
            //
            // So a searched section leads with what the search concluded, and
            // keeps the guess under it, named as the guess it was.
            done && stop.outcome
            ? `<span class="sweep-components">${escapeHtml(stop.outcome)}</span>` +
              (guess.sure
                ? `<span class="sweep-guess">first pass had guessed: ${escapeHtml(guess.sure)}</span>`
                : '')
            : allUncertain
            ? `<span class="sweep-components sweep-none">Read — nothing confirmed. ${guess.uncertain} guess${guess.uncertain === 1 ? '' : 'es'} only, none held up.</span>`
            : guess.sure
            ? `<span class="sweep-components">${escapeHtml(guess.sure)}</span>`
            : stop.count && !guess.uncertain
            ? `<span class="sweep-components sweep-none">no complex components — simple elements only</span>`
            : stop.count
            ? `<span class="sweep-components sweep-none">nothing certain — see the uncertain chip</span>`
            : ''}
          ${stop.truncated ? '<span class="ai-sev" data-need="1" title="This section holds more than 250 elements; only the first 250 were counted, so the numbers here are a floor">only the first 250 counted</span>' : ''}
          ${stop.positional ? '<span class="ai-sev" data-need="1" title="Some elements here have no id, class or role to point at — they can only be reached by their position in the page, which breaks the moment the page changes">positional</span>' : ''}
          ${stop.mapped ? `<span class="ai-sev" data-need="0" title="Already mapped on this site: ${escapeHtml(stop.mappedKinds)}. Not counted above, not read again, not built again.">${stop.mapped} already mapped</span>` : ''}
          ${// The card folds. Closed, it is the section number and what the
            // survey found — the two things the choice is made from. The
            // counts, the chips and the positional note sit under a caret:
            // there when asked for, not twelve lines between one section and
            // the next.
            empty ? '' :
            `<button type="button" class="sweep-more-btn" data-more="${stop.n}" aria-expanded="${open ? 'true' : 'false'}"
                     title="${open ? 'Hide' : 'Show'} details" aria-label="${open ? 'Hide' : 'Show'} details for section ${stop.n}">▾</button>`}
          <div class="sweep-more"${open ? '' : ' hidden'}>
            <div class="ai-approved-why sw-chips">${chips}</div>
            ${stop.mapped
              ? `<div class="sw-warn" role="note" style="opacity:.8">✓ already mapped here: ${escapeHtml(stop.mappedKinds)}` +
                `<span class="sw-warn-sub">found on this section but a saved mapping already owns the element — left out of the counts, and not read or built again</span></div>`
              : ''}
            ${// Pulled out of the sentence and onto a row of its own: this is
              // the one thing on the card the client has to act on, and it was
              // buried as the fifth clause of a line about link counts.
              stop.positional
              ? `<div class="sw-warn" role="note">⚠ ${stop.positional} positional — needs a class` +
                `<span class="sw-warn-sub">these can only be reached by position; ask the client for a class or id</span></div>`
              : ''}
          </div>
        </div>
      </div>`;
}

// Which section cards are unfolded — kept across redraws, since the list is
// redrawn on every tick and a card you just opened must not snap shut.
const sweepOpenRows = new Set();
document.getElementById('sweepPicksList')?.addEventListener('click', (e) => {
  const btn = e.target.closest('.sweep-more-btn');
  if (!btn) return;
  // The row underneath is a ticking surface; the caret is not a tick.
  e.preventDefault();
  e.stopPropagation();
  const n = Number(btn.dataset.more);
  const row = btn.closest('.sweep-screen');
  const more = row && row.querySelector('.sweep-more');
  if (!more) return;
  const open = more.hidden;
  more.hidden = !open;
  btn.setAttribute('aria-expanded', String(open));
  btn.title = open ? 'Hide details' : 'Show details';
  btn.setAttribute('aria-label', `${open ? 'Hide' : 'Show'} details for section ${n}`);
  row.classList.toggle('is-open', open);
  if (open) sweepOpenRows.add(n); else sweepOpenRows.delete(n);
});

/**
 * The estimate under the sections list.
 *
 * Two rows, because they are two different promises. "Scan" is what pressing
 * the button now will cost. "Fix" is what would follow IF every component found
 * were then ticked — a ceiling, not a forecast, and said so on the line itself.
 * Rolling them into one number would quote a bill nobody has agreed to yet.
 */
/**
 * The same box, for a run in progress: what it has done and spent, and what is
 * left of THIS run — not what a press that is not going to happen would cost.
 */
/**
 * The mode labels follow how many sections are ticked. "Stop at EACH
 * section" over a single ticked section reads as a different feature —
 * the owner picked it with one section and got a mid-scan approval screen
 * he never wanted. One section is one stop: the same two behaviours,
 * said in that shape's own words.
 */
function updateSweepModeWording() {
  const stopL = document.getElementById('sweepModeStopLbl');
  const goL = document.getElementById('sweepModeGoLbl');
  if (!stopL || !goL) return;
  const n = sweepPickedScreens().length;
  // A short bold title and a quiet second line — no italics. The old label
  // was one italic sentence that wrapped to three lines and had to be read to
  // the end before it could be told apart from the other one.
  const opt = (title, sub) =>
    `<strong class="sweep-radio-title">${title}</strong>` +
    `<span class="sweep-radio-sub">${sub}</span>`;
  const one = n === 1;
  const stopTitle = one ? 'Approve at the end' : 'Stop at each section';
  const goTitle = one ? 'Start to finish' : "Don't stop";
  stopL.innerHTML = opt(stopTitle, one
    ? 'scan this section, then show what it found for approval'
    : 'review before continuing');
  goL.innerHTML = opt(goTitle, one
    ? 'scan this section and make everything on it accessible'
    : 'run everything automatically');
  // The collapsed row states the answer.
  const now = document.getElementById('sweepModeNow');
  if (now) now.textContent = (sweepLabel.on || sweepPause.on) ? stopTitle : goTitle;
  const readNow = document.getElementById('sweepReadNow');
  const unread = document.getElementById('sweepUnreadCount');
  if (readNow || unread) {
    const stops = (typeof aiSweep !== 'undefined' && aiSweep.stops) || [];
    const picked = sweepPickedScreens();
    const todo = stops.filter(s => s.count && !s.scanned).length;
    const pickedUnread = stops.filter(s => s.count && !s.scanned && picked.includes(s.n)).length;
    if (unread) unread.textContent = String(todo);
    const readAll = stops.filter(s => s.count && s.scanned).length;
    if (readNow) readNow.textContent = todo === 0 && readAll
      ? `all ${readAll} section${readAll === 1 ? '' : 's'} read`
      : `${pickedUnread} of ${todo} unread section${todo === 1 ? '' : 's'}`;
  }
}

function sweepRunningHtml() {
  const p = aiSweep.progress || { at: 0, of: 0, screen: 0 };
  const stops = aiSweep.stops || [];
  const spent = stops.reduce((a, x) => a + (x.cost || 0), 0);
  const left = Math.max(0, p.of - p.at);
  const call = sweepAvgCall();
  // What is left is the elements on the sections not yet read, not a count of
  // sections times a constant — the remaining ones may be nothing like the
  // ones already done.
  const leftEls = stops.filter((s) => !s.scanned && s.count).reduce((a, s) => a + s.count, 0);
  const found = stops.reduce((a, x) => a + ((x.found || []).filter(f => !f.done).length), 0);
  return `
    <div class="sweep-est">
      <div class="sweep-est-head">Searching · section ${p.screen} · ${p.at} of ${p.of}</div>
      <div class="sweep-est-row">
        <span>Done</span><span>${p.at - 1} section${p.at - 1 === 1 ? '' : 's'}</span>
        <span>$${spent.toFixed(2)}</span>
      </div>
      <div class="sweep-est-row">
        <span>Left</span><span>${mins(sweepSecsFor(leftEls))}</span>
        <span>~$${(left * call).toFixed(2)}</span>
      </div>
      <div class="sweep-est-note">${found
        ? `${found} component${found === 1 ? '' : 's'} found so far — you can stop and build them from the drawer above.`
        : 'Nothing found yet. You can stop at any section; what is done stays done.'}</div>
      ${sweepSettledHtml()}
    </div>`;
}

/**
 * What each finished section actually settled, as it goes.
 *
 * A silent run — "do not ask me anything" — reports its progress as a section
 * number and a clock, and the only record of what it DECIDED is the scan log,
 * which is an accordion that starts shut. So twenty minutes in the honest
 * answer to "what has it done?" was "look in a collapsed panel, line by line".
 *
 * Newest first, because the interesting one is the one that just finished.
 */
function sweepSettledHtml() {
  const done = (aiSweep.stops || []).filter((s) => s.scanned && s.outcome);
  if (!done.length) return '';
  const rows = done.slice(-6).reverse().map((s) => {
    const k = (s.found || []).length;
    const built = (s.found || []).filter((f) => f.done).length;
    return `
      <div class="sweep-settled-row">
        <span class="sweep-settled-n">Section ${s.n}</span>
        <span class="sweep-settled-what">${escapeHtml(s.outcome)}</span>
        ${k ? `<span class="sweep-settled-k">${built}/${k} built</span>` : ''}
      </div>`;
  }).join('');
  return `
    <details class="sweep-settled" open>
      <summary>${done.length} section${done.length === 1 ? '' : 's'} settled${
        done.length > 6 ? ' — last 6' : ''}</summary>
      ${rows}
    </details>`;
}

/**
 * How many model calls a set of sections actually costs.
 *
 * Not one per section. A section is asked about in batches of SWEEP_ASK_BATCH,
 * so a 97-element section is two calls — and quoting it as one was the other
 * half of the same bug that lost its tail: the number under the button was
 * right only because the elements past sixty were being silently dropped.
 */
function sweepCallsFor(numbers) {
  const list = (aiSweep.stops || []).filter((s) => numbers.includes(s.n));
  return list.reduce((a, s) => a + Math.max(1, Math.ceil((s.count || 0) / SWEEP_ASK_BATCH)), 0);
}

function sweepEstimateHtml(sections, elements, calls) {
  const call = sweepAvgCall();
  if (calls == null) calls = sections;
  const comps = Math.max(1, Math.round(elements / SWEEP_EST.fixPerElements));
  const measured = aiCost > 0 && aiMapped.length;
  // "26 screens" read as twenty-six pages. They are twenty-six SECTIONS of one
  // page — the sections a scroll passes through. A sweep is pinned to a
  // single tab and a single URL, so the screen count is one by construction,
  // and saying so is what makes the section count mean anything.
  return `
    <div class="sweep-est">
      <div class="block-title">What it costs</div>
      <div class="sweep-est-head">Ticked: ${sections} section${sections === 1 ? '' : 's'} on 1 page · ${elements} element${elements === 1 ? '' : 's'}</div>
      <!-- Three stages, each saying whether it costs anything. The survey is
           already done and was free, and leaving it off the list made the two
           paid rows look like the whole of the work — so "what have I spent so
           far" had no answer on the one panel where it is decided. -->
      <div class="sweep-est-row is-free">
        <span>Survey</span><span>done</span><span>free</span>
      </div>
      <div class="sweep-est-row">
        <span>Find</span><span>${mins(sweepSecsFor(elements))}</span>
        <span>~$${(calls * call).toFixed(2)}</span>
        ${calls > sections ? `<em>${calls} calls for ${sections} section${sections === 1 ? '' : 's'} — the busy ones are asked about in more than one</em>` : ''}
      </div>
      <div class="sweep-est-row">
        <span>Build</span><span>${mins(comps * SWEEP_EST.fixSecs)}</span>
        <span>~$${(comps * SWEEP_EST.fixCall).toFixed(2)}</span>
        <em>costs only for the components you then tick — all ~${comps} of them here</em>
      </div>
      <div class="sweep-est-note">${measured || sweepTimesMeasured()
        ? `From this session's own sections — ${measured ? 'prices' : ''}` +
          `${measured && sweepTimesMeasured() ? ' and ' : ''}${sweepTimesMeasured() ? 'times' : ''} ` +
          `measured, not guessed.`
        : `Estimates, and the time scales with how busy a section is. ` +
          `Both tighten once the first section has been read.`}</div>
    </div>`;
}

// What a finished run actually spent — the same three-line shape as the
// forecast above it, but reporting what happened rather than what would.
// Shown once nothing is left ticked, when the forecast has nothing left to
// price.
function sweepSpentHtml() {
  const read = (aiSweep.stops || []).filter(s => s.scanned);
  const spent = read.reduce((a, x) => a + (x.cost || 0), 0);
  const elements = read.reduce((a, x) => a + (x.count || 0), 0);
  const found = read.reduce((a, x) => a + (x.found || []).length, 0);
  const built = read.reduce((a, x) => a + (x.found || []).filter(f => f.done).length, 0);
  return `
    <div class="sweep-est">
      <div class="block-title">What this cost</div>
      <div class="sweep-est-head">Read: ${read.length} section${read.length === 1 ? '' : 's'} on 1 page · ${elements} element${elements === 1 ? '' : 's'}</div>
      <div class="sweep-est-row">
        <span>Find</span><span>done</span><span>$${spent.toFixed(2)}</span>
      </div>
      ${found ? `<div class="sweep-est-row"><span>Build</span><span>${built}/${found} built</span><span></span></div>` : ''}
      <div class="sweep-est-note">What this run actually spent — a record, not a forecast.</div>
    </div>`;
}

// The cost breakdown, folded behind a button instead of sitting open on
// screen. Pulled out to a named function so it is one thing to call, both
// from the click below and from a test. Forecasts what is ticked while
// there is still something ticked to read; once a run is done and nothing
// is left ticked, reports what it actually spent instead.
function openSweepEstDialog() {
  const picked = sweepPickedScreens();
  const elements = aiSweep.stops.filter(s => picked.includes(s.n)).reduce((a, s) => a + s.count, 0);
  const body = document.getElementById('sweepEstBody');
  const dlg = document.getElementById('sweepEstDialog');
  if (body) {
    body.innerHTML = picked.length
      ? sweepEstimateHtml(picked.length, elements, sweepCallsFor(picked))
      : sweepSpentHtml();
  }
  if (dlg && typeof dlg.showModal === 'function') dlg.showModal();
}

// Same treatment for the finished run's summary.
function openSweepReadDialog() {
  const body = document.getElementById('sweepReadBody');
  const dlg = document.getElementById('sweepReadDialog');
  if (body) body.innerHTML = sweepReadSummaryHtml;
  // The cached HTML carries the radio labels and the "Read / Mode" answers
  // as EMPTY spans — they are filled by updateSweepModeWording, which ran
  // against the live summary at render time and never against this copy.
  // So the dialog opened with two blank radios and "Read 0 unread sections".
  if (typeof updateSweepModeWording === 'function') updateSweepModeWording();
  // A finished run is a record, not a form: the settings row stays open so
  // the record is readable without a second click.
  const det = body && body.querySelector('#sweepSettings');
  if (det) det.open = true;
  if (dlg && typeof dlg.showModal === 'function') dlg.showModal();
}

document.addEventListener('click', (e) => {
  if (e.target.closest('#sweepEstBtn')) return openSweepEstDialog();
  if (e.target.closest('#sweepEstCloseBtn')) return document.getElementById('sweepEstDialog')?.close();
  if (e.target.closest('#sweepReadBtn')) return openSweepReadDialog();
  if (e.target.closest('#sweepReadCloseBtn')) return document.getElementById('sweepReadDialog')?.close();
});

// ── What it found, to choose from ───────────────────────────────────────────
// The sweep stops here on purpose. Everything above cost one call per SCREEN;
// working out the selectors for a component costs a call per COMPONENT. Putting
// the choice between the two is what makes "just the first screen" cheap
// instead of merely tidier — nothing below this list is paid for until it is
// ticked and the button is pressed.
function renderSweepPicks() {
  const wrap = document.getElementById('sweepPicks');
  const list = document.getElementById('sweepPicksList');
  const summary = document.getElementById('sweepPicksSummary');
  if (!wrap || !list) return;

  const read = aiSweep.stops.filter(s => s.found.length);
  // A section whose components have all been made accessible is finished, and
  // it is not a choice any more. It used to stay in the list with everything
  // ticked, so the next press offered to do the same work again; and hiding the
  // whole panel after applying took the rest of the page with it. Done sections
  // move to their own drawer, shut, where they can still be looked at.
  // A component that could not be mapped is not done, so its section stays in
  // the pending list carrying the reason. "Six found, five saved" must never
  // again be something you notice by counting.
  const stops = read.filter(s => !s.found.every(f => f.done));
  const finished = read.filter(s => s.found.length && s.found.every(f => f.done));
  const total = stops.reduce((s, x) => s + x.found.length, 0);
  const doneCount = finished.reduce((s, x) => s + x.found.length, 0);
  const barrenCount = read.filter(s => s.scanned && !s.found.length).length;
  if (!total && !doneCount && !barrenCount) { setStage('none'); return; }
  // Nothing left to choose — everything found is built (or there was nothing
  // to find). "Choose fixes" with zero components across zero sections is a
  // stage with no decision in it; the finished run's own view (Completed, and
  // the two record buttons) is the honest answer, so go there instead of
  // rendering an empty chooser.
  if (!total) {
    aiSweep.phase = 'screens';
    renderSweepScreens();
    return;
  }

  // The way back. Stopping a run to build what it had found left you in the
  // components view with no route to the sections that were never searched —
  // the survey was still there, and unreachable, so the only apparent way on
  // was to start the whole page again.
  const unsearched = aiSweep.stops.filter(x => x.count && !x.scanned).length;
  summary.innerHTML = `<div class="ai-meta">${total} component${total === 1 ? '' : 's'} across ` +
    `${stops.length} section${stops.length === 1 ? '' : 's'} · $${aiCost.toFixed(3)} to find them` +
    (unsearched
      ? ` · <button class="btn-outline btn-xs" data-back-to-sections>← ${unsearched} section${unsearched === 1 ? '' : 's'} still to search</button>`
      : '') + `</div>`;

  list.innerHTML = stops.map((stop, i) => {
    const img = safeImg(stop.thumb);
    const heldN = stop.found.filter(f => f.held).length;
    const k = stop.found.length - heldN;
    return `
      <details class="sweep-group" data-stop="${stop.n}"${i === 0 ? ' open' : ''}>
        <summary>
          <input type="checkbox" class="sweep-group-tick" checked
                 aria-label="Choose everything found on screen ${stop.n}">
          ${img ? `<span class="mh-thumb" data-shot="${stop.n}">
                     <img class="mh-img" src="${img}" alt="Section ${stop.n}">
                     <img class="mh-preview" src="${img}" alt="">
                   </span>` : ''}
          <span class="sweep-group-name">Section ${stop.n}</span>
          <span class="sweep-group-meta">${k} component${k === 1 ? '' : 's'}${heldN ? ` · ${heldN} need${heldN === 1 ? 's' : ''} review` : ''} · $${(stop.cost || 0).toFixed(3)}</span>
        </summary>
        <div class="sweep-group-body">${stop.found.map(f => `
          <div class="ai-approved-row ai-bulk-row" data-pick="${f.id}">
            <input type="checkbox" class="ai-bulk-tick" ${f.held ? '' : 'checked'} aria-label="Make ${escapeHtml(f.label)} accessible">
            <div class="ai-bulk-body">
              <span class="ai-approved-label">${escapeHtml(f.label)}</span>
              <code>u1.fix.${escapeHtml(f.type)}</code>
              ${f.held ? `<span class="ai-sev" data-need="1">low confidence${f.detConf != null ? ' ' + f.detConf : ''} — not ticked for you</span>` : ''}
              ${!f.held && f.needsWork ? '<span class="ai-sev" data-need="1">needs work</span>' : ''}
              ${!f.held && !f.needsWork ? '<span class="ai-sev" data-need="0">already looks correct</span>' : ''}
              ${f.failed ? '<span class="ai-sev" data-need="1">could not be mapped</span>' : ''}
              <div class="ai-approved-why">${escapeHtml(f.why || f.sel)}</div>
              ${f.failed ? `<div class="ai-approved-why sweep-failed">${escapeHtml(f.failed)}</div>` : ''}
            </div>
          </div>`).join('')}</div>
      </details>`;
  }).join('');

  // Done, and out of the way. Named, so "which sections have I finished" is
  // answerable at a glance rather than by remembering.
  if (finished.length) {
    const doneBox = document.createElement('details');
    doneBox.className = 'sweep-done';
    doneBox.innerHTML =
      `<summary><span class="sweep-done-name">✓ ${finished.length} section${finished.length === 1 ? '' : 's'} completed</span>` +
      `<span class="sweep-done-meta">${doneCount} component${doneCount === 1 ? '' : 's'} made accessible</span></summary>` +
      `<div class="sweep-done-body">${finished.map(stop => `
        <div class="sweep-done-row" data-screen="${stop.n}">
          ${safeImg(stop.thumb) ? `<span class="mh-thumb"><img class="mh-img" src="${safeImg(stop.thumb)}" alt="Section ${stop.n}"></span>` : ''}
          <div class="ai-bulk-body">
            <span class="ai-approved-label">Section ${stop.n}</span>
            <div class="ai-approved-why">${stop.found.map(f => escapeHtml(f.label)).join(' · ')}</div>
          </div>
          <!-- "Completed" was a one-way door: a section built by mistake, or
               one you decided against after seeing it on the page, could only
               be undone by finding each of its mappings in the list below and
               deleting them one at a time. This takes the section's own
               mappings back and returns it to the choosing list. -->
          <button type="button" class="btn-outline btn-xs" data-undo-section="${stop.n}"
                  title="Delete the mappings this section produced and put it back on the list">↶ Undo this section</button>
        </div>`).join('')}</div>`;
    list.appendChild(doneBox);
  }

  // The sections you did NOT pay to read. Reading one used to replace the
  // list with its results, and the rest of the page went with it — "I ticked
  // screen 1 and made it accessible, where is everything else". They are still
  // surveyed, still free, and still tickable; shut by default because the
  // components just found are what this step is about.
  // Read, and it produced nothing. Not a choice any more and not a failure —
  // but it must be SAYABLE, because two sections ticked and one section of
  // results is otherwise indistinguishable from the run having stopped early.
  const barren = read.filter(s => s.scanned && !s.found.length);
  if (barren.length) {
    const box = document.createElement('div');
    box.className = 'sweep-barren';
    box.innerHTML = barren.map(stop => `
      <div class="sweep-barren-row" data-screen="${stop.n}">
        <span class="sweep-barren-n">Section ${stop.n}</span>
        <span class="sweep-barren-why">${escapeHtml(stop.outcome || 'read, nothing found')}</span>
      </div>`).join('');
    list.appendChild(box);
  }

  const unread = aiSweep.stops.filter(s => !s.scanned && s.count);
  if (unread.length) {
    const rest = document.createElement('details');
    rest.className = 'sweep-rest';
    rest.innerHTML =
      `<summary><span class="sweep-rest-name">${unread.length} section${unread.length === 1 ? '' : 's'} not read yet</span>` +
      `<span class="sweep-rest-meta">already surveyed · free until you read ${unread.length === 1 ? 'it' : 'them'}</span></summary>` +
      `<div class="sweep-rest-body">${unread.map(sweepScreenRowHtml).join('')}` +
      `<button type="button" class="u1-btn u1-btn-secondary" id="sweepReadMoreBtn">Read the ticked sections</button></div>`;
    list.appendChild(rest);
    rest.querySelectorAll('.sweep-screen-tick').forEach(t => { t.checked = false; });
    rest.querySelector('#sweepReadMoreBtn').addEventListener('click', async () => {
      const picks = [...rest.querySelectorAll('.sweep-screen')]
        .filter(r => r.querySelector('.sweep-screen-tick')?.checked)
        .map(r => Number(r.dataset.screen));
      if (!picks.length) {
        showNotice(document.getElementById('sweepPicksStatus'),
          'Tick the sections you want read first.', 'warn', 4000);
        return;
      }
      await scanPickedScreens(picks);
    });
  }

  // The sweep's results belong to the Whole page route. Restoring a survey on
  // panel open, or adopting a colleague's, calls this whatever route is on
  // screen — which put "2 sections completed" and a Make-accessible button
  // underneath the single-element scanner, acting on nothing you were looking at.
  // One stage at a time: the components list IS this stage, and the review
  // that produced it belongs to the one before. Both on screen together, each
  // with its own apply button, is the stack this replaced.
  setStage(mapMode === 'sweep' ? 'components' : 'none');
  syncSweepMakeBtn();
  saveSweep();
}

/** Arm or disarm every per-row ▶ at once. */
function setPlayButtons(on) {
  document.querySelectorAll('#sweepPicksList .sweep-play')
    .forEach((b) => { b.disabled = !on; });
}

const sweepPicked = () => [...document.querySelectorAll('#sweepPicksList .ai-bulk-row[data-pick]')]
  .filter(r => r.querySelector('.ai-bulk-tick')?.checked)
  .map(r => r.dataset.pick);

const sweepPickedScreens = () => [...document.querySelectorAll('#sweepPicksList .sweep-screen')]
  .filter(r => r.querySelector('.sweep-screen-tick')?.checked)
  .map(r => Number(r.dataset.screen));

// Whether the Cost drawer is open — kept across the redraw every tick causes.
let sweepCostOpen = false;

// One button, two jobs, because the list under it changes and the button is
// always "do the next thing to what is ticked". The count is on it in both
// cases: it is the number of calls that will be charged.
function syncSweepMakeBtn() {
  // The mode labels follow the picked count, and THIS function provably runs
  // on every tick (the button's own count updates) — the separate change
  // listener did not reword reliably, so the rewording rides here.
  try { updateSweepModeWording(); } catch {}
  const btn = document.getElementById('sweepMakeBtn');
  const est = document.getElementById('sweepEstimate');
  if (!btn) return;

  if (aiSweep.phase === 'screens') {
    const picked = sweepPickedScreens();
    // Keep the master tick honest about what is under it. An empty section is
    // disabled and never counts either way, or "select all" could never reach
    // a fully-ticked state on a page that has one.
    const all = document.getElementById('sweepAllTick');
    const ticks = [...document.querySelectorAll('#sweepPicksList .sweep-screen-tick:not(:disabled)')];
    if (all && ticks.length) {
      all.checked = picked.length > 0;
      all.indeterminate = picked.length > 0 && picked.length < ticks.length;
    }
    const elements = aiSweep.stops.filter(s => picked.includes(s.n)).reduce((a, s) => a + s.count, 0);
    // The estimate keeps updating during a run — that is the point of marking
    // each section read as it goes. The BUTTON does not: a run owns it, and it
    // is saying which section it is on. This function used to overwrite that
    // with "Read 25 sections" after every section and re-enable it, so the
    // label flickered between two answers and the button invited a second run
    // on top of the one already going.
    if (!aiSweep.running) {
      // Once nothing is left to read, "No sections ticked" is not an offer
      // any more — there is nothing to tick. The two buttons above already
      // say the run is over; a disabled button repeating that is clutter,
      // not information.
      const sweepDone = aiSweep.stops.length > 0 && aiSweep.stops.every(s => !s.count || s.scanned);
      if (!picked.length && sweepDone) {
        btn.style.display = 'none';
      } else {
        btn.style.display = '';
        btn.disabled = !picked.length;
        // The count AND the size, on the button: it is the number of calls
        // that will be charged, and how much page they cover.
        btn.textContent = picked.length
          ? `🔎 Find components · ${picked.length} section${picked.length === 1 ? '' : 's'} · ~${elements} element${elements === 1 ? '' : 's'}`
          : '🔎 No sections ticked';
      }
    }
    // The box under the button described the NEXT press while the button
    // described the current run — two different moments, stacked. While a run
    // is going the box is about the run.
    // The cost is folded into the line under the button, stated as the answer
    // — "Est. cost: ~$0.26" — with the breakdown one press away in a dialog.
    // It used to be a button asking a question ("What it costs") that you had
    // to press to learn the number; a second filled control on a screen that
    // should have one.
    if (est) {
      const calls = sweepCallsFor(picked);
      const cost = calls * sweepAvgCall();
      // Same shape as the Settings control beside it, and it stays put when
      // nothing is ticked — "$0.00 · nothing ticked" is an answer; a control
      // that vanishes when the number reaches zero reads as a fault.
      // A drop-down like Settings beside it — same shape, same size, opens
      // underneath. The breakdown is written into the body only when the
      // drawer is opened, so a closed Cost box carries the answer and not
      // fifteen lines of forecast behind it.
      // typeof-guarded: verify-sweep lifts this function out and runs it alone.
      const costOpen = typeof sweepCostOpen !== 'undefined' && sweepCostOpen;
      est.innerHTML = aiSweep.running
        ? sweepRunningHtml()
        : `<details class="sweep-settings sweep-cost"${costOpen ? ' open' : ''}>` +
            `<summary class="sweep-settings-row" title="Time and cost, stage by stage">` +
              `<span class="sweep-settings-item"><span class="sweep-settings-k">Est. cost</span> ` +
              `<strong>${picked.length ? '~' : ''}$${cost.toFixed(2)}</strong>` +
              `<span class="sweep-ctl-sub">${picked.length ? mins(sweepSecsFor(elements)) : 'nothing ticked'}</span></span>` +
              `<span class="sweep-settings-edit" aria-hidden="true">cost</span>` +
            `</summary>` +
            `<div class="sweep-settings-body sweep-cost-body"></div>` +
          `</details>`;
      const costBox = est.querySelector('.sweep-cost');
      if (costBox) {
        const fill = () => {
          const body = costBox.querySelector('.sweep-cost-body');
          if (!body) return;
          body.innerHTML = picked.length
            ? sweepEstimateHtml(picked.length, elements, calls)
            : sweepSpentHtml();
        };
        if (costOpen) fill();
        costBox.addEventListener('toggle', () => {
          try { sweepCostOpen = costBox.open; } catch {}
          if (costBox.open) fill();
          else { const b = costBox.querySelector('.sweep-cost-body'); if (b) b.innerHTML = ''; }
        });
      }
    }
    return;
  }

  const k = sweepPicked().length;
  btn.disabled = !k;
  btn.textContent = k ? `✨ Build fixes for ${k} component${k === 1 ? '' : 's'} — ${k} more call${k === 1 ? '' : 's'}`
                      : '✨ Nothing ticked';
  if (est) est.innerHTML = '';
}

// One tick for a whole section, in both lists. Same behaviour, so they are
// wired the same way.
function wireGroupTicks(rootId, after) {
  document.getElementById(rootId)?.addEventListener('change', (e) => {
    // A sections-phase row has no group around it — it IS the unit — so it falls
    // straight through to `after`, which recomputes the estimate.
    const group = e.target.closest('.sweep-group');
    if (group) {
      if (e.target.classList.contains('sweep-group-tick')) {
        group.querySelectorAll('.ai-bulk-tick').forEach(t => { t.checked = e.target.checked; });
      } else if (e.target.classList.contains('ai-bulk-tick')) {
        const ticks = [...group.querySelectorAll('.ai-bulk-tick')];
        const head = group.querySelector('.sweep-group-tick');
        if (head) {
          head.checked = ticks.some(t => t.checked);
          head.indeterminate = head.checked && ticks.some(t => !t.checked);
        }
      }
      group.dataset.off = [...group.querySelectorAll('.ai-bulk-tick')].some(t => t.checked) ? '' : '1';
    }
    if (after) after();
  });
  // Clicking the thumbnail opens it full size — the hover preview settles
  // "which screen is this", not "is that the right button".
  document.getElementById(rootId)?.addEventListener('click', (e) => {
    const thumb = e.target.closest('.sweep-group .mh-thumb');
    if (!thumb) return;
    e.preventDefault();          // the summary would otherwise toggle the group
    const stop = aiSweep.stops.find(s => String(s.n) === thumb.dataset.shot);
    if (stop?.thumb) openImageDialog(stop.thumb);
  });
}
wireGroupTicks('sweepPicksList', syncSweepMakeBtn);
wireGroupTicks('aiBulkList');

// ── Hovering a section shows it on the real page ──────────────────────────
//
// A 340px picture of a section answers "roughly where am I". Scrolling the
// actual page there and outlining the components on it answers "is THAT the nav
// I mean" — which is the question you are actually holding while you decide
// whether a section is worth paying to read.
//
// The marks are drawn from a fresh collection at that scroll position rather
// than from what the survey stored: it is local code, it costs nothing, and it
// means the outlines are of the page as it is now, not as it was.
let sweepHover = { n: 0, timer: null, restoreY: null, busy: false };

/**
 * The tab a sweep's results belong to — not whichever tab is in front now.
 *
 * Everything that acts on those results scrolls a page and draws on it, so
 * pointing any of it at the wrong tab is worse than doing nothing. Returns null
 * once that tab is gone, and the caller simply does not act.
 */
async function sweepTab() {
  if (aiSweep.tabId != null) {
    try {
      const t = await chrome.tabs.get(aiSweep.tabId);
      return isInjectable(t) ? t : null;
    } catch { return null; }   // closed or navigated away
  }
  const t = await getTab();
  return isInjectable(t) ? t : null;
}

/**
 * True when there is sweep work — running or finished — tied to a tab that is
 * still open.
 *
 * Switching browser tab changes the panel's hostname, and the panel clears the
 * AI workspace on every hostname change. That is right for a scan of "whatever
 * is in front of me" and wrong for a sweep, which is pinned to one tab: looking
 * at another tab and coming back threw the whole survey away and started it
 * over. The results are still that tab's results, so they stay.
 */
async function sweepIsPinnedAndAlive() {
  if (aiSweep.tabId == null) return false;
  if (!aiSweep.running && !(aiSweep.stops && aiSweep.stops.length)) return false;
  return !!(await sweepTab());
}

/**
 * True when the pinned tab is the one actually on screen.
 *
 * captureVisibleTab photographs whichever tab is in FRONT of the window, not
 * the tab id you pass — pass a backgrounded tab and it hands back a picture of
 * a different page, with no error. A sweep that keeps running while you work in
 * another tab must therefore skip its thumbnails rather than store wrong ones.
 */
/**
 * Block until the sweep's own page is at the front again.
 *
 * captureVisibleTab photographs whatever is in front and throws outright when
 * the window is minimised — and that throw used to escape collectRegion (its
 * try had a finally and no catch), reach the run's outer catch and end a
 * twenty-six section scan on the spot. Switching tabs mid-run is ordinary; it
 * must cost nothing but the wait.
 *
 * Resolves IMMEDIATELY when the tab is already in front, so a run that is never
 * interrupted pays nothing for this. The poll is 120ms, which is below what
 * anyone perceives as a delay on coming back.
 */
// ── Photographing a page that is not in front ───────────────────────────────
//
// captureVisibleTab photographs whatever tab is in FRONT, whatever id it is
// handed, and throws when the window is minimised. Everything the sweep does is
// built on a photograph, so with that as the only camera "leave it running and
// carry on working" is not something the tool can offer — it can only wait, and
// waiting is what it did.
//
// The debugger protocol has a camera that does not care: Page.captureScreenshot
// photographs the tab it is attached to, in the background, unfocused. That is
// the whole difference between pausing and running.
//
// It is attached for the length of a run and detached the moment it ends —
// Chrome shows its own banner on the page for as long as it is attached, which
// is right: the browser saying out loud that something is driving this tab.
//
// It can fail to attach for one ordinary reason: DevTools is already open on
// that tab, and Chrome allows one debugger at a time. That is not an error to
// hide — it changes what the run can do — so it is reported and the run falls
// back to the focus-bound camera.
//
// And one way it fails that is not ordinary at all, which is the whole reason
// the timeout below exists:
//
//   Page.captureScreenshot defaults to fromSurface:true — it photographs the
//   BROWSER'S composited surface. A backgrounded tab does not produce frames,
//   so on a hidden tab that call does not fail, does not return an empty
//   picture, and does not throw. It never settles. `await` on it waits for the
//   rest of the session.
//
// Which is exactly the case the camera was attached for. Every debugger call
// therefore races a clock, and a timeout is not a shrug: it retries once with
// fromSurface:false — the renderer-side path, which does not need frames —
// and if that will not answer either the camera is demoted for the rest of the
// run and the focus-bound one takes over, saying so.
const sweepCam = { tabId: null, attached: false, why: '' };

// A screenshot of a big page is not instant, and killing a slow-but-working
// camera would be its own bug. Eight seconds is far outside a normal capture
// and far inside "why has this section taken two minutes".
const CDP_TIMEOUT_MS = 8000;

/** One debugger command, with a clock on it. Rejects rather than hanging. */
function cdp(tabId, method, params, ms = CDP_TIMEOUT_MS) {
  return new Promise((resolve, reject) => {
    let done = false;
    const timer = setTimeout(() => {
      if (done) return;
      done = true;
      reject(new Error(`${method} did not answer within ${Math.round(ms / 1000)}s`));
    }, ms);
    chrome.debugger.sendCommand({ tabId }, method, params || {}).then(
      (res) => { if (!done) { done = true; clearTimeout(timer); resolve(res); } },
      (err) => { if (!done) { done = true; clearTimeout(timer); reject(err); } });
  });
}

async function beginBackgroundCapture(tab) {
  sweepCam.tabId = tab.id;
  sweepCam.attached = false;
  sweepCam.why = '';
  if (!chrome.debugger) { sweepCam.why = 'this browser has no debugger API'; return false; }
  try {
    await chrome.debugger.attach({ tabId: tab.id }, '1.3');
    // Page.captureScreenshot happens to work on some builds without its domain
    // enabled and returns an empty result on others, which reads as "the camera
    // is attached and produces nothing" — the worst of the three outcomes.
    try { await cdp(tab.id, 'Page.enable', {}, 3000); } catch {}
    sweepCam.attached = true;
    return true;
  } catch (e) {
    const msg = String((e && e.message) || e);
    sweepCam.why = /already attached/i.test(msg)
      ? 'DevTools is open on that tab, and Chrome allows one debugger at a time'
      : msg;
    return false;
  }
}

/**
 * Attach the background camera, and say in the log which camera this run has.
 *
 * Whether you can switch tabs and carry on working is the single most visible
 * difference between the two, so it is not something to discover by trying it.
 * It is one line at the top of the scan log, before the first section.
 */
async function announceCamera(tab) {
  const ok = await beginBackgroundCapture(tab);
  sweepLog(0, ok
    ? 'background camera on — switch tabs and work as usual, this keeps going'
    : `no background camera (${sweepCam.why}) — this run needs its own tab in front, and pauses when you leave it`,
    ok ? '' : 'skip');
  return ok;
}

async function endBackgroundCapture() {
  if (!sweepCam.attached || sweepCam.tabId == null) { sweepCam.attached = false; return; }
  try { await chrome.debugger.detach({ tabId: sweepCam.tabId }); } catch {}
  sweepCam.attached = false;
}

/**
 * One section, as a data URL.
 *
 * `onWait` is only ever called on the fallback path — the background camera
 * never waits, so a run using it must not print "waiting for the page".
 */
async function captureScreen(tab, quality, onWait) {
  if (sweepCam.attached && sweepCam.tabId === tab.id) {
    // fromSurface:true is the default and photographs the browser's composited
    // surface, which a hidden tab does not produce — so on the very tab this
    // camera exists to photograph, the call can simply never settle. It gets a
    // clock, and a timeout is retried on the renderer-side path, which needs no
    // frames.
    for (const surface of [true, false]) {
      try {
        const res = await cdp(tab.id, 'Page.captureScreenshot',
          { format: 'jpeg', quality, fromSurface: surface });
        if (res && res.data) return 'data:image/jpeg;base64,' + res.data;
        // Attached, no error, no picture. Left as it was, every section would
        // pay the round trip and then fall through anyway.
        sweepCam.why = 'it returned an empty picture';
      } catch (e) {
        // A detach mid-run (the tab navigated, DevTools opened) or a call that
        // would not answer. Either way this is the last word on that path.
        sweepCam.why = String((e && e.message) || e);
      }
    }
    // Both paths tried. Demoted for the rest of the run — retrying a camera
    // that has already cost sixteen seconds of silence on every remaining
    // section is how one slow screen becomes a run nobody can sit through.
    sweepCam.attached = false;
    sweepLog(0, `background camera stopped working (${sweepCam.why}) — ` +
      `from here this run needs its own tab in front`, 'err');
  }
  if (!(await awaitTabVisible(tab, onWait))) return null;
  try {
    return await chrome.tabs.captureVisibleTab(tab.windowId, { format: 'jpeg', quality });
  } catch { return null; }
}

async function awaitTabVisible(tab, onWait) {
  if (await pinnedTabIsVisible(tab)) return true;
  let told = false;
  for (let waited = 0; waited < 10 * 60 * 1000; waited += 120) {
    if (aiSweep.abort) return false;
    if (!told && onWait) { told = true; onWait(); }
    await new Promise((r) => setTimeout(r, 120));
    if (await pinnedTabIsVisible(tab)) return true;
  }
  return false;
}

async function pinnedTabIsVisible(tab) {
  try {
    const t = await chrome.tabs.get(tab.id);
    if (!t.active) return false;
    const w = await chrome.windows.get(t.windowId);
    return !!w.focused || w.state !== 'minimized';
  } catch { return false; }
}

async function sweepPreviewScreen(n) {
  const stop = aiSweep.stops.find(s => s.n === n);
  // A run owns the page's scroll position, so previewing during one would move
  // the page out from under the section being read. But a run that is HOLDING —
  // for fixes, or for you to name what is on a section — is not moving
  // anything, and that is exactly when this list is being looked at. Blocking
  // both on one flag is why the preview "stopped working": it was disabled at
  // the only moment it was wanted.
  // …but NOT while the naming pause is open. That pause is built on the marks
  // drawn on the page, and this function re-collects — whose first line is
  // clearMarks(). Hovering the sections list wiped every mark, and the next
  // press of "build them" failed with "None of those marks are on the page any
  // more" on a component that was still plainly there.
  //
  // The hold-for-fixes banner does not depend on marks, so previewing is still
  // allowed there.
  const held = !!sweepPause.resolve;
  if (!stop || sweepHover.busy || sweepLabel.resolve || (aiSweep.running && !held)) return;
  const tab = await sweepTab();
  if (!tab) return;
  sweepHover.busy = true;
  try {
    // Where the page was before any of this, so it can be put back.
    if (sweepHover.restoreY === null) sweepHover.restoreY = (await sweepMeasure(tab))?.y ?? 0;
    await inPage(tab.id, (y) => window.scrollTo({ top: y, left: 0, behavior: 'instant' }), [stop.scrollY]);
    // For a screen already read, the components ARE known — mark those, by the
    // selectors that were paid for, rather than re-guessing from the markup.
    // For one not read yet, a fresh local collection is all there is, and it is
    // free.
    const known = (stop.found || []).map(f => ({
      mark: null, selector: f.sel, component: f.type, maybe: false, observed: true,
    }));
    await inPage(tab.id, (known) => {
      const got = window.__u1SelectorIntel.collectCandidates(200, null);
      window.__u1SelectorIntel.drawComponentMarks(known.length ? known : got.candidates);
    }, [known]);
  } catch { /* the page may have navigated away mid-hover */ }
  finally { sweepHover.busy = false; }
}

async function sweepPreviewEnd() {
  const tab = await sweepTab();
  if (!tab) return;
  try {
    await inPage(tab.id, () => window.__u1SelectorIntel.clearMarks());
    if (sweepHover.restoreY !== null) {
      await inPage(tab.id, (y) => window.scrollTo({ top: y, left: 0, behavior: 'instant' }), [sweepHover.restoreY]);
      sweepHover.restoreY = null;
    }
  } catch {}
}

/**
 * Take a completed section back.
 *
 * "Completed" was a one-way door. A section built by mistake — or one you
 * decided against once you saw what it did to the page — could only be undone
 * by hunting each of its mappings down in the list below and deleting them one
 * at a time, with nothing saying which of the twenty belonged to it.
 *
 * The section knows what it produced (`stop.found`), so it can hand exactly
 * those back and return itself to the choosing list. The survey is not thrown
 * away: it stays read and paid for, so putting the section back costs nothing
 * and re-reading it is not required.
 */
document.addEventListener('click', async (e) => {
  const btn = e.target.closest('[data-undo-section]');
  if (!btn) return;
  e.preventDefault();
  e.stopPropagation();                 // it lives inside a <details> row
  const n = Number(btn.dataset.undoSection);
  const stop = (aiSweep.stops || []).find((s) => s.n === n);
  if (!stop) return;

  const built = (stop.found || []).filter((f) => f.done);
  btn.disabled = true;
  btn.textContent = 'Undoing…';
  const key = storageKey('mappings', currentHostname);
  let removed = 0;
  try {
    const list = (await U1Store.get([key]))[key] || [];
    // Matched on the mapping key the build recorded, not on the selector: two
    // sections can legitimately produce mappings on related selectors, and
    // deleting a neighbour's work would be far worse than leaving this one.
    const drop = new Set(built.map((f) => f.mappingKey).filter(Boolean));
    const next = drop.size ? list.filter((m) => !drop.has(mappingKey(m))) : list;
    removed = list.length - next.length;
    if (removed) await U1Store.set({ [key]: next });
  } catch (err) {
    showNotice(document.getElementById('sweepPicksStatus'),
      'Could not remove them: ' + err.message, 'error', 8000);
    btn.disabled = false;
    btn.textContent = '↶ Undo this section';
    return;
  }
  // Back on the list, still read: the survey and the search are paid for and
  // stay that way, so putting it back costs nothing.
  stop.found = (stop.found || []).map((f) => ({ ...f, done: false }));
  await loadMappingsList();
  refreshExportInfo();
  saveSweep();
  renderSweepPicks();
  showNotice(document.getElementById('sweepPicksStatus'),
    removed
      ? `Section ${n} undone — ${removed} mapping${removed === 1 ? '' : 's'} removed and the section is back on the list. ` +
        `Reload the page to see it without them.`
      : `Section ${n} is back on the list. Nothing was in Mappings to remove.`,
    'success', 10000);
});

document.getElementById('sweepPicksList')?.addEventListener('mouseover', (e) => {
  // Gated on the phase, this stopped working the moment one section had been
  // read — which is exactly when the rest of the list is most worth looking at,
  // and when the "not read yet" rows appear. A row that names a section can
  // preview that section whatever phase the panel is in. Both shapes qualify:
  // an unread screen row, and a group of components found on one.
  const row = e.target.closest('.sweep-screen, .sweep-group, .sweep-done-row');
  if (!row) return;
  const n = Number(row.dataset.screen || row.dataset.stop);
  if (!n || n === sweepHover.n) return;
  sweepHover.n = n;
  document.querySelectorAll('#sweepPicksList .is-previewing')
    .forEach(x => x.classList.remove('is-previewing'));
  row.classList.add('is-previewing');
  // Debounced: sweeping the mouse down twenty-one rows must not fire twenty-one
  // scrolls, and the page jumping about under the cursor is the whole failure
  // mode this guards against.
  clearTimeout(sweepHover.timer);
  sweepHover.timer = setTimeout(() => sweepPreviewScreen(sweepHover.n), 160);
});

document.getElementById('sweepPicksList')?.addEventListener('mouseleave', () => {
  clearTimeout(sweepHover.timer);
  sweepHover.n = 0;
  document.querySelectorAll('#sweepPicksList .is-previewing')
    .forEach(x => x.classList.remove('is-previewing'));
  // Leaving the list puts the page back where it was. A tool that scrolls
  // somebody's page and walks away has moved their work, not shown them theirs.
  sweepPreviewEnd();
});

// Any tick anywhere changes how many sections are picked, and the mode
// labels follow that count — the per-row ticks live in the LIST, not the
// summary, which is why a summary-scoped listener never saw them flip.
document.getElementById('sweepPicksList')?.addEventListener('change', (e) => {
  if (e.target.classList && e.target.classList.contains('sweep-screen-tick')) updateSweepModeWording();
});

// Select all / none. It lives in the summary, which is rebuilt on every render,
// so it is delegated rather than bound to the element.
document.getElementById('sweepPicksSummary')?.addEventListener('change', (e) => {
  // Sits in the same rebuilt summary, so it is delegated from the same place.
  // One question, two answers. Stopping means both halves — being shown what a
  // section holds, and being given the chance to build it — because a run that
  // shows you a section and then moves on regardless is not a stop.
  if (e.target.id === 'sweepPauseTick' || e.target.id === 'sweepSilentTick') {
    const stopping = e.target.id === 'sweepPauseTick';
    sweepLabel.on = stopping;
    sweepPause.on = stopping;
    saveSweep();
    return;
  }
  if (e.target.id !== 'sweepAllTick') return;
  const on = e.target.checked;
  document.querySelectorAll('#sweepPicksList .sweep-screen-tick:not(:disabled)')
    .forEach(t => { t.checked = on;   updateSweepModeWording();
});
  syncSweepMakeBtn();
});

// Stop a build between components. Everything already saved stays saved.
document.getElementById('buildStopBtn')?.addEventListener('click', (e) => {
  aiBulk.abort = true;
  const b = e.currentTarget;
  b.disabled = true;
  b.textContent = 'Finishing this one…';
});

// Lives on the Completed row now (data-sweep-clear), redrawn into the list
// on every render — so, like the Build-fixes button beside it, it is found
// by delegation rather than a fixed id, and stops the click reaching the
// <summary> it sits inside so it does not also toggle the drawer.
document.addEventListener('click', async (e) => {
  const btn = e.target.closest('[data-sweep-clear]');
  if (!btn) return;
  e.preventDefault();
  e.stopPropagation();
  // Clear is the ONLY thing that forgets a stored survey. Switching site or
  // closing the panel must not, or the durability is theatre.
  //
  // It used to ask only when a section had been paid for. But the survey itself
  // is not nothing: it scrolled the whole page, photographed every section
  // and is shared with everyone on the project — and one press of a small grey
  // word took all of it with no question at all. Always ask.
  if (!(await confirmSweepClear())) return;
  clearTimeout(sweepSaveTimer);
  aiSweep.stops = [];
  await forgetSweep();
  // Shared work, so Clear clears it for everyone — leaving the server copy
  // would mean it silently reappeared the next time the panel was opened.
  if (await U1Auth.isLoggedIn()) {
    try { await U1Sync.deleteSweep(currentHostname); } catch {}
  }
  setStage('none');
  document.getElementById('sweepPicksList').innerHTML = '';
  document.getElementById('sweepLog').style.display = 'none';
  document.getElementById('sweepLog').innerHTML = '';
  document.getElementById('sweepPicks')?.classList.remove('is-sweep-done');
});

// ── The paid half ───────────────────────────────────────────────────────────
// Work out the selectors for the ticked components, then save and apply them.
// The choice was already made on the list above, so this does not ask a second
// time — it hands the prepared cards to the approval flow and presses its
// button, which is the one path that saves, applies and reports. Duplicating
// that here is how the two would drift.
// ── The first paid step: read the ticked sections ────────────────────────────
// One model call per ticked screen. The photograph the choice was made from is
// the small one; the model needs the numbered 1280px version, and that has to be
// taken at the right scroll position — so this scrolls back to each screen it
// was asked about. ~1.5s of scrolling against 10–30s of call is noise, and
// collecting afresh means the picture and the element list always agree.
async function scanPickedScreens(numbers) {
  const btn = document.getElementById('sweepMakeBtn');
  const status = document.getElementById('sweepPicksStatus');
  // The page the survey walked, not the one in front now — this scrolls back to
  // each section, and doing that to the wrong tab would both waste the calls
  // and move somebody's work.
  const tab = await sweepTab();
  if (!tab) {
    showNotice(status, 'The page these results came from is no longer open.', 'error', 6000);
    return;
  }
  if (!(await U1AI.getKey())) {
    await aiModeAllowed();   // no key: Setup is where that is fixed
    showNotice(status, 'Paste your Anthropic API key first.', 'error', 4000);
    return;
  }
  // This one is paid for, and the picture IS the request — so it has to be a
  // picture of THIS page. The background camera guarantees that without moving
  // anything, and is tried first.
  //
  // Only if it will not attach do we fall back to yanking the tab in front,
  // which is the rude version: it takes the window away from whatever you were
  // doing. That yank used to happen on every run, camera or no camera.
  // A survey restored from storage comes back with tabId null — the tab it
  // originally ran on is gone, and sweepTab() falls back to the one in front.
  // That is the right answer for reopening a survey and the wrong one for
  // continuing it: sweepIsPinnedAndAlive() requires a tabId, so without this a
  // restored survey is not "pinned", the hold in onTabChanged does not apply to
  // it, and pressing ▶ on it and then switching tabs resets it — which is
  // precisely the run that was reported as never having scanned.
  //
  // Reading a section pins the survey to the tab being read, whatever it was
  // pinned to before.
  aiSweep.tabId = tab.id;
  if (!aiSweep.url) aiSweep.url = tab.url || '';
  // A restored survey has no host of its own until it is continued.
  if (!aiSweep.host) aiSweep.host = getHostname(tab) || currentHostname;
  const cam = await announceCamera(tab);
  if (!cam && !(await pinnedTabIsVisible(tab))) {
    try {
      await chrome.tabs.update(tab.id, { active: true });
      await chrome.windows.update(tab.windowId, { focused: true });
      await new Promise(r => setTimeout(r, 250));
    } catch {}
  }

  const stops = aiSweep.stops.filter(s => numbers.includes(s.n));
  const handled = await alreadyHandled();
  // What the survey found to be already mapped — by element, under whatever
  // name the survey gave it — is not read again either.
  for (const st of stops) for (const sel of st.mappedSels || []) handled.add(sel);
  // Low-confidence rows published unticked, keyed by selector so a later,
  // confident reading of the same element can replace its hesitant twin.
  const heldAt = new Map();
  const startedAt = (await sweepMeasure(tab))?.y || 0;
  clearApproved();   // a new run, a new answer to "what did I just do"
  aiSweep.running = true;
  aiSweep.abort = false;
  btn.disabled = true;
  // The floating "Stop after this section" button is gone. Every state this
  // run can be sitting in now carries its own way out — the naming pause and
  // the hold-for-fixes banner each have one — and a button that only appears
  // during a run, over the list you are reading, was one more thing in the way.
  // Deliberately NOT shown. The paid run holds after every section, and both
  // holds — naming and building — carry their own way out, next to the decision
  // being made. A button floating over the list you are reading, for the whole
  // length of a thirty-five minute run, was one more thing in the way.
  { const b = document.getElementById('sweepStopBtn'); if (b) b.style.display = 'none'; }
  // The rows are not redrawn during a run, so the ▶s that were live a moment
  // ago have to be disarmed where they stand. The finally redraws the list and
  // brings them back.
  setPlayButtons(false);

  try {
    for (let i = 0; i < stops.length; i++) {
      if (aiSweep.abort) break;
      const stop = stops[i];
      const before = aiCost;
      // Beside the cost, because they answer the same question about the same
      // section and only one of them was ever recorded.
      const beganAt = Date.now();
      // "Searching section 2 of 23" was read as screen 2 — which was already
      // completed and sitting in the drawer below. The counter is the position
      // in THIS run; the sections have numbers of their own. Two numbering
      // systems shown with one word, so the word is no longer alone.
      btn.textContent = `Searching section ${stop.n} — ${i + 1} of ${stops.length}…`;
      aiSweep.progress = { at: i + 1, of: stops.length, screen: stop.n };
      // Word for word what the button says, because they are read together
      // and a difference between them reads as a difference in meaning.
      // The step, not the section. A section is four steps — scroll, read,
      // photograph, ask — and one label covering all four is how "the model has
      // been thinking for ninety seconds" and "this has hung" look identical
      // from outside. Each step now names itself as it starts.
      showSweepBusy(`Section ${stop.n} — ${i + 1} of ${stops.length}`,
        `Reading what is on this section — a few seconds, no charge.`,
        ((i + 0.05) / stops.length) * 100);
      markScreenReading(stop.n);

      // The paid read scrolls back to each section and photographs it. If the
      // page has moved on since the survey — the probe pressed something that
      // navigated, or you followed a link yourself between the two passes —
      // that photograph is of the wrong page, and it is about to be sent to
      // the model and charged for. Checked before the money is spent.
      if (!(await sweepBackIfNavigated(tab, stop.n))) {
        const why = 'the page navigated away and would not come back — nothing was charged for this section';
        sweepLog(stop.n, why, 'err');
        await markScreenFailed(stop, why);
        continue;
      }
      await inPage(tab.id, (y) => window.scrollTo({ top: y, left: 0, behavior: 'instant' }), [stop.scrollY]);
      await new Promise(r => setTimeout(r, SWEEP_SETTLE_MS));

      const collected = await collectRegion(tab, '', handled, {
        drop: (c) => c.sticky && stop.n > 1,
        // The numbers stay on the page while you label, because they are the
        // only binding between a row here and an element there.
        keepMarks: sweepLabel.on,
      });
      if (collected.err) {
        sweepLog(stop.n, collected.err, 'err');
        // Attempted and failed is not the same as never tried, and it looked
        // identical: the run moved past sections 6 and 7 and left them sitting
        // in "still to search" with their original survey line, so the only
        // visible fact was that the completed drawer had holes in it.
        //
        // It stays in "still to search" — it genuinely was not searched, and it
        // is still worth a retry — but it says what happened.
        await markScreenFailed(stop, collected.err);
        continue;
      }
      // Every candidate on this section was filtered out before the model was
      // called: either already mapped, already found on an earlier section, or
      // part of the sticky header which is counted once. Nothing was charged.
      //
      // Silently skipping made a two-screen run look like a one-screen run —
      // the second screen produced no components, so renderSweepPicks dropped
      // its row and there was nothing on screen saying it had been looked at.
      // A section that was read and yielded nothing is a RESULT, and it says
      // so on its own row.
      if (!collected.candidates.length) {
        const why = collected.skipped
          ? `nothing new — all ${collected.skipped} element${collected.skipped === 1 ? '' : 's'} here were ` +
            'already found in an earlier section or already mapped'
          : 'nothing on this section to read';
        sweepLog(stop.n, why, 'skip');
        stop.scanned = true;
        stop.outcome = why;
        await markScreenRead(stop);
        continue;
      }

      // ── You say what it is ────────────────────────────────────────────────
      // The run stops here, with the numbers still drawn on the page, and waits.
      // Everything you name is built from measurement and costs nothing; only
      // what is left over is sent to the model. Name it all and the section
      // is free.
      let labelled = [];
      if (!Array.isArray(stop.found)) stop.found = [];
      if (sweepLabel.on) {
        const answer = await labelScreen(stop, collected, tab);
        if (answer.stopped) break;
        // "Do not ask me again." Both interruptions go: no more naming pause on
        // the sections after this one, and no more holding to build what they
        // find. The run reads the rest of the page and applies what it gets.
        if (answer.auto) {
          sweepLabel.on = false;
          sweepPause.on = false;
          sweepLog(stop.n, 'carrying on without asking — the rest of the page runs on its own', 'skip');
        }
        labelled = answer.labelled || [];
        if (labelled.length) {
          for (const made of labelled) {
            stop.found.push(made);
            handled.add(made.sel);
          }
        }
        // Nothing left for the model to look at: the screen is done, unpaid.
        if (answer.done) {
          stop.scanned = true;
          stop.cost = 0;
          stop.secs = Math.round((Date.now() - beganAt) / 1000);
          const k = labelled.length;
          // Confirming used to be free — it measured the component locally. It
          // now goes through the same engine the per-component route uses,
          // which reads the container's markup and costs a call each, because
          // the free measurement produced mappings whose every sub-selector was
          // the root again. Saying "nothing charged" over a real charge is the
          // one thing this line must not do.
          stop.outcome = k
            ? `${k} component${k === 1 ? '' : 's'} you confirmed — saved to Mappings and applied`
            : 'you marked nothing here as a component — nothing charged';
          sweepLog(stop.n, stop.outcome, k ? '' : 'skip', 0);
          await markScreenRead(stop);
          continue;
        }
      }

      // The one step that is neither quick nor local, and the only one that
      // costs. "Usually 10–30 seconds" was written for a sparse section and
      // read as a promise on every section: this one is 94 elements with a
      // picture attached, it took a minute and a half, and the panel said
      // nothing except a clock ticking past its own estimate. A call is allowed
      // 150 seconds before it is given up on, and that is what it now says.
      // Everything still worth asking about — the WHOLE section, not its first
      // screenful of DOM.
      const asking = collected.candidates.filter((c) => !handled.has(c.selector));
      const busyN = asking.length;
      // One call per batch. The picture goes with every batch: the model is
      // being asked "which of these elements form a component, and where is it
      // on this section", and the second half of that question is the image.
      const batches = [];
      for (let b = 0; b < asking.length; b += SWEEP_ASK_BATCH) {
        batches.push(asking.slice(b, b + SWEEP_ASK_BATCH));
      }
      sweepLog(stop.n, `asking about ${busyN} element${busyN === 1 ? '' : 's'}` +
        (batches.length > 1 ? ` in ${batches.length} calls — too many for one` : ''), 'skip');

      const parts = [];
      let died = null;
      for (let b = 0; b < batches.length; b++) {
        // Per BATCH, not per section. `i / stops.length` alone meant a
        // two-section run sat at 0% for the whole of section 1 — a minute or
        // two of a bar that has not moved and a clock that has, which reads
        // as stuck rather than slow.
        // One timeline per run: reading is the first tenth of the section's
        // slice, the model calls the next six tenths, the build the rest —
        // so the bar climbs through every phase instead of parking at 0%.
        const pctAt = (frac) => ((i + 0.1 + 0.6 * Math.min(1, (b + frac) / batches.length)) / stops.length) * 100;
        const head = `Section ${stop.n} — ${i + 1} of ${stops.length}`;
        const part = (batches.length > 1 ? `Part ${b + 1}/${batches.length} · ` : '');
        const long =
          `Asking Claude about ${batches[b].length} element${batches[b].length === 1 ? '' : 's'} and a ` +
          `picture of this section. A busy one takes a minute or two — it only gives up if ` +
          `Claude goes quiet for a minute, so a long answer is never mistaken for a stuck one.`;
        showSweepBusy(head,
          // Short enough for a banner pinned over the panel. The reassurance
          // that a slow answer is not a stuck one is on the tooltip: it is
          // worth saying once, not worth three lines of a fixed header on
          // every section of a thirty-section run.
          part + `asking Claude about ${batches[b].length} element${batches[b].length === 1 ? '' : 's'}` +
          ` — a busy section takes a minute or two`,
          pctAt(0), long);
        const got = await U1AI.discover({
          screenshot: collected.shot,
          context: {
            candidates: batches[b],
            headings: collected.headings,
            title: collected.title,
            url: collected.url,
            // 3.2: what pressing found, in the model's brief. It may
            // disagree, with a reason — never ignore.
            observations: ((stop.probed || []).slice(0, 12)).map((c) => ({
              trigger: (c.parts && c.parts.trigger) || '',
              root: c.root, type: c.type, why: (c.why || '').slice(0, 140),
            })),
          },
          // The definitive answer to "is it stuck?": bytes of the actual
          // answer, counted as they land. Silence is what the idle clock
          // already catches; this is what makes a working call LOOK like one.
          // The share of the batch is a guess from a typical answer length —
          // it only has to move, and it is capped so it cannot claim to be
          // finished before it is.
          onProgress: (chars) => {
            if (aiSweep.abort) return;
            updateSweepBusy(pctAt(Math.min(0.9, chars / 4000)),
              part + `Claude is answering — ${chars.toLocaleString()} characters so far`);
          },
        });
        if (got && got.err && /cut off before it finished/.test(got.err) && batches[b].length > 10) {
          // 'Narrow the scope and try again' is addressed to nobody in an
          // unattended run (elal's 105-element section died exactly here).
          // Narrow it OURSELVES: split the batch, redo the first half now,
          // queue the second — down to a floor of ten, where a cut-off means
          // something else is wrong.
          sweepLog(stop.n, `the answer for ${batches[b].length} elements was cut off — splitting the batch and retrying`, 'skip');
          const half = Math.ceil(batches[b].length / 2);
          batches.splice(b + 1, 0, batches[b].slice(half));
          batches[b] = batches[b].slice(0, half);
          b--;
          continue;
        }
        if (got && got.err) { died = got.err; break; }
        aiCost += U1AI.estimateCost(got.usage) || 0;
        parts.push(got);
        if (aiSweep.abort) break;
      }
      if (died && !parts.length) {
        sweepLog(stop.n, died, 'err');
        await markScreenFailed(stop, died);
        // A rate limit or a network blip is not a reason to abandon the other
        // sections; a bad key is, and it would fail the same way on every one.
        if (/API 401/.test(died)) break;
        continue;
      }
      // Some batches answered and one did not. That is a partial result, and
      // throwing it away would be worse than keeping it — but it must not be
      // reported as a complete reading of the section.
      if (died) sweepLog(stop.n, `part of this section failed: ${died}`, 'err');
      const part = {
        components: parts.flatMap((p) => p.components || []),
        usage: null,
      };

      // needsWork is a LABEL, not a filter — which is how Automatic mode has
      // always treated it. Dropping the rows it marks false looked like a saving
      // and was actually a way to return nothing: the model is conservative with
      // that flag, so a page whose markup reads as broadly reasonable came back
      // empty even though every component on it still needed mapping.
      // 3.1 + 3.3: the probe's observations join the model's rows before the
      // audit, merged by root — so menuIsReallyListbox and alreadyNative
      // finally run on the one detector that works on hint-free pages.
      const merged = mergeObservedRows(part.components, observedRowsFor(stop), asking);
      const audit = await auditSurveyComponents(merged, tab);
      const found = audit.comps;
      for (const d of audit.dropped) {
        sweepLog(stop.n, `left out ${d.label} — a <${d.tag}> named “${d.name}” is already ` +
          `a ${d.tag === 'a' ? 'link' : 'button'}; mapping it would announce it twice`, 'info');
      }
      for (const r of audit.retyped) {
        sweepLog(stop.n, `${r.label} read as ${r.from} in the markup, mapped as a listbox — ` +
          `one control opening one flat list is a listbox whatever the role says`, 'info');
      }
      let seenAgain = 0;
      // Keep what you named. This used to be `stop.found = []`, which is right
      // when the model is the only source and wrong the moment it is not —
      // everything labelled on this section before the call would have been
      // thrown away by the call's own answer.
      stop.found = (stop.found || []).filter((f) => f.done);
      for (const c of found) {
        // Stage 6: the publication threshold. A row below 0.6 — the model's
        // word alone, with no markup voice and no behaviour behind it — is not
        // ticked for you. But it is SHOWN: hiding it in the log read as "the
        // AI missed this" when it had actually seen it and hesitated. The row
        // is published unchecked, labelled with its confidence, for a person
        // to approve or ignore.
        const held = c.detConf != null && c.detConf < 0.6;
        if (held) {
          if (handled.has(c.containerSelector) || heldAt.has(c.containerSelector)) { seenAgain++; continue; }
          sweepLog(stop.n, `held back ${c.label || c.containerSelector} (${c.u1Type}) — ` +
            `confidence ${c.detConf}: shown unticked, not applied for you`, 'skip');
        } else {
          // Never twice, whatever brought it back: a sticky bar, a repeated
          // footer, or a component straddling the overlap between two sections.
          if (handled.has(c.containerSelector)) { seenAgain++; continue; }
          handled.add(c.containerSelector);
          // A confident reading replaces an earlier hesitant one of the same
          // element, wherever that hesitation was published.
          const prior = heldAt.get(c.containerSelector);
          if (prior) {
            prior.stop.found = prior.stop.found.filter((x) => x !== prior.f);
            heldAt.delete(c.containerSelector);
          }
        }
        if (c.detConf != null && c.detConf < 0.9) {
          c.why = `Confidence ${c.detConf} — read before applying. ` + (c.why || '');
        }
        const row = {
          id: `s${stop.n}i${stop.found.length}`,
          held,
          label: c.label || c.containerSelector,
          type: c.u1Type,
          sel: c.containerSelector,
          // What the survey said opens this. For a dialog it is the ONLY way
          // the trigger ever gets filled: a dialog's trigger is optional, so
          // nothing downstream goes looking for one, and the mapping ships
          // with a modal that U1 never learns to wait for.
          trigger: c.triggerSelector || '',
          why: c.why || '',
          needsWork: c.needsWork !== false,
          detConf: c.detConf,
        };
        stop.found.push(row);
        if (held) heldAt.set(c.containerSelector, { stop, f: row });
      }
      // The missing trace (2026-09-01): everything this section ASKED about
      // that nothing answered. A candidate the hint layer flagged, sent to
      // the model, that came back in no row — not the model's, not the
      // probe's — used to vanish without a word, and "why is the listbox
      // missing" had no log line to point at. Now each one gets a line
      // saying which stage went silent.
      try {
        const coveredBy = (sel) =>
          stop.found.some((f) => f.sel === sel || f.trigger === sel) || handled.has(sel);
        for (const c of asking) {
          if (!c.component || !c.selector) continue;
          if (coveredBy(c.selector)) continue;
          const pressedIt = (stop.probed || []).find((p) => p && (p.root === c.selector ||
            (p.parts && p.parts.trigger && p.parts.trigger === c.selector)));
          sweepLog(stop.n, `asked about ${c.selector} (${c.component}${c.maybe ? '?' : ''}) — ` +
            (pressedIt && !pressedIt.type
              ? 'pressed it and something happened, but no pattern matched'
              : pressedIt
                ? `the press read it as ${pressedIt.type}, but no row was published for it`
                : 'nothing came back: not from the model, not from a press'), 'skip');
        }
        for (const p of (stop.probed || [])) {
          if (p && !p.type && p.root) {
            sweepLog(stop.n, `pressed ${p.root} — ${p.why || 'something changed, no pattern matched'}`, 'skip');
          }
        }
      } catch {}
      stop.scanned = true;
      stop.cost = aiCost - before;
      stop.secs = Math.round((Date.now() - beganAt) / 1000);
      await markScreenRead(stop);
      const k = stop.found.length;
      const named = stop.found.filter((f) => f.done).length;
      // Everything that did NOT come back, accounted for.
      //
      // seenAgain only counts things the model returned that we already had —
      // the small half. The big half is dropped BEFORE the call: every
      // candidate already mapped, or already found in an
      // earlier section is filtered out of what gets sent, and that count
      // (collected.skipped) went nowhere. So a section the survey described as
      // "6 menus · form · dialog? · carousel?" came back as "2 components" with
      // the other several silently missing, and the obvious reading is that the
      // search failed.
      //
      // It did not. They were left out on purpose, and now it says so.
      const held = (collected.skipped || 0) + seenAgain;
      stop.outcome = (found.length || named)
        ? `${k} component${k === 1 ? '' : 's'} to map` +
          (named ? ` · ${named} you named, free` : '') +
          (held ? ` · ${held} left out — already mapped, or found in an earlier section` : '')
        : held
        ? `nothing new to map — all ${held} thing${held === 1 ? '' : 's'} here are already mapped or were found in an earlier section`
        : 'read, and nothing on it needs mapping';
      sweepLog(stop.n, stop.outcome, k ? '' : 'skip', stop.cost);

      // ── "Do not stop": build them here, one at a time ─────────────────────
      // Finding is not the promise. "Read the rest of the page and make
      // everything accessible on its own" means the mappings arrive in the
      // drawer while it runs — and until now this mode found components,
      // logged them, and left every one of them to be built by hand from a
      // drawer, which is the opposite of what it says.
      if (!sweepPause.on && !sweepLabel.on) {
        const todo = (stop.found || []).filter((f) => !f.done && f.sel);
        for (let b = 0; b < todo.length && !aiSweep.abort; b++) {
          // The counter is RUN-WIDE: "Mapping 7 of 20 · 35%", not a per-
          // section fraction that resets and a percent that never moves.
          // totalKnown grows as later sections are read — the percent
          // recalculates, which is honest: the run learns its size as it goes.
          const builtAll = aiSweep.stops.reduce((a2, s2) => a2 + ((s2.found || []).filter((f2) => f2.done).length), 0);
          const knownAll = aiSweep.stops.reduce((a2, s2) => a2 + ((s2.found || []).filter((f2) => f2.sel).length), 0);
          showSweepBusy(`Mapping ${builtAll + 1} of ${knownAll} — ${todo[b].type}`,
            `${todo[b].label || todo[b].sel} · section ${stop.n}` +
            (todo[b].why ? ` — ${String(todo[b].why).slice(0, 90)}` : '') +
            `. Saved to Mappings as it finishes.`,
            ((i + 0.7 + 0.3 * (b / Math.max(1, todo.length))) / stops.length) * 100);
          await spotlightBuild(tab, todo[b].sel, todo[b].trigger);
          try {
            const made = await confirmedToMapping(
              { mark: null, type: todo[b].type, sel: todo[b].sel, why: todo[b].why }, stop, tab);
            if (made.err) { todo[b].failed = made.err; sweepLog(stop.n, `${todo[b].type}: ${made.err}`, 'err'); }
            else {
              todo[b].done = true;
              todo[b].failed = null;
              // Carried through so "undo this section" knows which stored row
              // this became — the silent run builds through the same path but
              // keeps its own object rather than the returned one.
              if (made.found && made.found.mappingKey) todo[b].mappingKey = made.found.mappingKey;
            }
          } catch (err) {
            todo[b].failed = err.message;
            sweepLog(stop.n, `${todo[b].type}: ${err.message}`, 'err');
          }
        }
        await spotlightOff(tab);
        const built = (stop.found || []).filter((f) => f.done).length;
        if (todo.length) {
          stop.outcome = `${built} of ${todo.length} made accessible — saved to Mappings`;
          sweepLog(stop.n, stop.outcome, built ? '' : 'err');
          await markScreenRead(stop);
          saveSweep();
        }
      }

      // ── Build the fixes for this section, then carry on ───────────────────
      // Only when there is something to build and something still to read.
      // Holding after the last section, or after one that found nothing, is a
      // press that asks for a decision there is nothing to decide.
      const buildable = stop.found.filter((f) => !f.done).length;
      const rest = stops.length - (i + 1);
      if (sweepPause.on && buildable && rest > 0 && !aiSweep.abort) {
        const out = await pauseForFixes(stop, rest);
        if (out.stopped) break;
        // Back to being a run: the sections list is what the busy overlay and
        // the per-section marking are drawn against, and the finally clause
        // redraws whichever phase it ends in.
        aiSweep.phase = 'screens';
        renderSweepScreens();
        setPlayButtons(false);
        btn.disabled = true;
      }
    }
  } catch (err) {
    sweepLog(0, 'Failed: ' + err.message, 'err');
  } finally {
    // Detach first. Chrome's "is debugging this browser" banner stays up for
    // exactly as long as we are attached, and leaving it there after a run has
    // ended is its own small lie about what is happening to the page.
    await endBackgroundCapture();
    clearSweepBusy();
    aiSweep.running = false;
    aiSweep.progress = null;
    btn.disabled = false;
    { const b = document.getElementById('sweepStopBtn'); if (b) b.style.display = 'none'; }
    // The labelling pause asks for the marks to be LEFT on the page, so the run
    // owns taking them down — including when it ends by Stop, by a throw, or in
    // the middle of a section.
    const lblHost = document.getElementById('sweepLabel');
    if (lblHost) { lblHost.style.display = 'none'; lblHost.innerHTML = ''; }
    try { await inPage(tab.id, () => window.__u1SelectorIntel.clearMarks()); } catch {}
    // Same for the hold-for-fixes banner: a throw inside the loop skips its own
    // finish(), and a "continue to the next section" button left on screen
    // after the run has ended is a button that does nothing.
    sweepPause.resolve = null;
    const resHost = document.getElementById('sweepResume');
    if (resHost) { resHost.style.display = 'none'; resHost.innerHTML = ''; resHost.onclick = null; }
    try { await inPage(tab.id, (y) => window.scrollTo(0, y), [startedAt]); } catch {}
    // Regroup: the rows were marked one by one while the run went, and now the
    // list can settle into "still to read" and "already read".
    if (aiSweep.phase === 'screens') renderSweepScreens();
    // Whatever the outcome. A run that found nothing still read those sections
    // and still paid for them, and that has to survive a panel reload — it did
    // not, because the only save on this path hung off a render that an empty
    // run never reached.
    saveSweep();
    // If you said "I have moved on to another site" while this held the panel,
    // this is where it lets go.
    await followPendingSiteSwitch();
  }

  // What the run actually did, per screen, in one line. Ticking two sections and
  // seeing one in the results is alarming and was unexplained: the second had
  // been read and had yielded nothing, and nothing said so.
  const ran = stops.filter(s => s.scanned);
  const empty = ran.filter(s => !s.found.length);
  const total = aiSweep.stops.reduce((s, x) => s + x.found.length, 0);
  const spent = stops.reduce((a, x) => a + (x.cost || 0), 0);

  // One line, in this order: what it did, what it cost, what it got. It used to
  // open with a wall of per-screen prose and never say the last two at all — so
  // a run that read twenty-six sections, spent real money and found nothing
  // ended in a paragraph you had to parse to discover any of that.
  const head = `Searched ${ran.length} section${ran.length === 1 ? '' : 's'}` +
    (spent > 0 ? ` · $${spent.toFixed(2)}` : '') +
    ` · ${total} component${total === 1 ? '' : 's'} to map.`;

  if (total) {
    if (empty.length) {
      showNotice(status, head + ' ' +
        empty.map(s => `Section ${s.n}: ${s.outcome || 'nothing found'}`).join('. ') + '.', 'warn', 14000);
    }
    // "Do not stop — make everything accessible on its own" also means no
    // review screen afterwards. The specialist checks the MAPPINGS, in their
    // own words — a list of triage cards after a run that already built and
    // saved everything buildable is noise standing where the result should
    // be. What remains is a sentence: how many landed, how many could not be
    // built (their reasons are already in the run log, one line each), and
    // the drawer below holding the mappings themselves. The components view
    // still exists — it is the workflow of "stop at each section", and the
    // way back in after a pressed Stop.
    if (!sweepPause.on) {
      // The autonomous run builds inline, section by section, and never goes
      // through the bulk-build button — so its dialogs' insides and the
      // page-wide finishing pass (headings, vague links) have to run HERE.
      // They only ran on the manual path, which is why an autonomous molina
      // run produced no heading or vague-link mappings at all.
      // Nothing was BUILT this run — a read that failed, an all-skip section —
      // so there is nothing for the statics to finish. Asking about them here
      // read as "I got the static dialog and nothing else happened".
      const builtNow = stops.reduce((a3, s3) => a3 + ((s3.found || []).filter((f3) => f3 && f3.done).length), 0);
      if (!builtNow) {
        sweepLog(0, 'static pass not offered — nothing was built on this run', 'skip');
      } else {
      const dlgCount0 = (aiSweep.stops || []).reduce((a2, s2) =>
        a2 + ((s2.found || []).filter((f2) => f2 && f2.done && f2.type === 'dialog' && f2.sel).length), 0);
      if (!(await confirmStaticPass(dlgCount0))) {
        sweepLog(0, 'static pass skipped at your request — headings, vague links and dialog interiors left for a later run', 'skip');
      } else {
      try {
        sweepLog(0, 'dialog interiors: starting — every dialog this run built gets its own inside scan', 'info');
        const din = await dialogInteriorScan(tab);
        if (din.dialogs) {
          sweepLog(0, `dialog interiors: looked inside ${din.dialogs} dialog${din.dialogs === 1 ? '' : 's'}, ` +
            `mapped ${din.made} component${din.made === 1 ? '' : 's'} in there`, 'info');
        }
      } catch (e) { sweepLog(0, 'dialog-interior scan failed: ' + e.message, 'err'); }
      try {
        // The requested heads-up: the run has moved from components to the
        // page-wide STATIC pass — headings and vague links.
        sweepLog(0, 'static pass: starting — reading the heading outline and the vague links', 'info');
        const viewH1 = await inPage(tab.id, () => window.innerHeight).catch(() => 900);
        const staticRanges1 = stops.map((s4) => ({ top: s4.scrollY || 0, bottom: (s4.scrollY || 0) + (viewH1 || 900) }));
        const fin = await sweepFinishingPass(tab, staticRanges1);
        const vd = fin.vagueDiag || {};
      const vaguePart = fin.links
        ? `${fin.links} vague-link group${fin.links === 1 ? '' : 's'} mapped`
        : !vd.vague ? 'no vague links (learn-more-style) on the page'
        : `${vd.vague} vague link${vd.vague === 1 ? '' : 's'} seen (${(vd.sample || []).join(', ')}) but none mapped — ` +
          [vd.noCard ? `${vd.noCard} had no heading beside them` : '',
           vd.lonely ? `${vd.lonely} were one of a kind` : '',
           vd.noSelector ? `${vd.noSelector} lost their common selector` : '']
            .filter(Boolean).join(', ');
      sweepLog(0, `finishing pass: ` + vaguePart + ` (headings are left to the manual review, by decision)`, 'info');
      } catch (e) { sweepLog(0, 'static pass failed: ' + e.message, 'err'); }
      clearSweepBusy();
      }
      }
      const done = aiSweep.stops.reduce((a, x) => a + ((x.found || []).filter(f => f.done).length), 0);
      const failedC = aiSweep.stops.reduce((a, x) => a + ((x.found || []).filter(f => !f.done && f.failed).length), 0);
      aiSweep.phase = 'screens';
      renderSweepScreens();
      showNotice(status,
        head + ` ${done} made accessible and saved to Mappings.` +
        (failedC ? ` ${failedC} could not be built — each one's reason is one line in the run log above.` : ''),
        failedC ? 'warn' : 'success', 20000);
      // The run is over; going over what it built is what comes next. So the
      // panel goes THERE — the Mappings list, filtered to what has not been
      // ticked as reviewed — rather than resting on the finished run's
      // screen with the work one tab away. Only when something was built:
      // an empty run has nothing to review.
      if (done && !aiSweep.abort) {
        setMappingsFilter('review');
        if (typeof setPickerPane === 'function') setPickerPane('mappings');
        const ms = document.getElementById('mappingsStatus');
        if (ms) showNotice(ms,
          `The AI run finished — ${done} new mapping${done === 1 ? '' : 's'}. This is the To-review view: ` +
          `open each one, check it on the page, and tick ○ review when it is right. The ticks stay in this extension only.`,
          'info', 20000);
      }
      return;
    }
    aiSweep.phase = 'components';
    renderSweepPicks();
    return;
  }

  // Nothing found at all.
  showNotice(status, head + ' ' + (empty.length
    ? 'Everything on these sections is already mapped, or was found in a section searched earlier.'
    : 'Nothing on these sections needs mapping.'), 'info', 20000);
}

// ▶ on a single row: read that one section and stop.
//
// It goes through scanPickedScreens like everything else — the function has
// always taken a list of screen numbers, so "one" needs no separate path and
// gets the same stop button, the same log, the same labelling pause and the
// same saved progress. The only thing that differs is the list it is handed.
document.getElementById('sweepPicksList')?.addEventListener('click', async (e) => {
  const btn = e.target.closest('[data-play-screen]');
  if (!btn) return;
  // The row it sits in is a ticking surface and a hover preview; neither should
  // fire because you pressed the button on top of it.
  e.preventDefault();
  e.stopPropagation();
  if (aiSweep.running) {
    showNotice(document.getElementById('sweepPicksStatus'),
      'A scan is already going. Stop it first, or wait for it to finish.', 'warn', 4000);
    return;
  }
  const n = Number(btn.dataset.playScreen);
  const stop = aiSweep.stops.find(s => s.n === n);
  if (!stop || !stop.count) return;
  // Re-reading a screen that is already paid for is a real thing to want and a
  // waste to do by accident, so it says which of the two this is.
  if (!(await confirmSweepCost(1, stop.scanned ? n : 0, stop.count, sweepCallsFor([n])))) return;
  await scanPickedScreens([n]);
});

/**
 * Build every ticked component. Shared by the button and by the hold.
 *
 * Extracted because the hold's own primary action has to do this and then
 * carry on: it used to say "Continue to the next section →" and build nothing,
 * so a section that found eight components and a person who pressed the
 * obvious button moved on with eight found and none made. The drawer then read
 * "8 COMPONENTS FOUND" beside "No mappings yet", which is exactly what it was.
 */
/**
 * Save an aria-label mapping for every repeated "Read more"-style card
 * pattern on the page — the same construction the headings-review button
 * makes by hand, minus the hand. Returns how many kinds were saved; skips
 * any target already mapped so a re-run does not double up.
 */
async function saveCardDescriptionMappings(tab) {
  let shapes = null;
  try {
    await chrome.scripting.executeScript({
      target: { tabId: tab.id }, files: ['selector-intel.js'] });
    shapes = await inPage(tab.id, () => {
      const S = window.__u1SelectorIntel;
      return S && S.cardDescriptions ? S.cardDescriptions() : null;
    });
  } catch { shapes = null; }
  if (!shapes || !shapes.length) return 0;

  const key = storageKey('mappings', currentHostname);
  const stored = (await U1Store.get([key]))[key] || [];
  let made = 0;
  for (const c of shapes) {
    if (stored.some((m) => m && typeof m === 'object' && m.primary === c.target)) continue;
    const tpl = buildTemplate('aria-label', c.target, {},
      { middleText: 'about', headingSelector: c.heading });
    await saveMappingEntry(tpl, { refreshUi: false });
    made++;
  }
  if (made) { loadMappingsList(); refreshExportInfo(); }
  return made;
}

async function buildPickedComponents() {
  const btn = document.getElementById('sweepMakeBtn');
  const status = document.getElementById('sweepPicksStatus');
  const picked = new Set(sweepPicked());
  if (!picked.size) return;
  if (isReadonly()) {
    showNotice(status, 'Licence expired — existing mappings still work and export, but new ones are paused.', 'error', 6000);
    return;
  }
  if (!aiWorkspaceMatchesSite()) { warnWrongSite(status); return; }

  // Every job below comes from aiSweep.stops, so the tab is the SWEEP's tab,
  // not whichever one is in front — asking getTab() here meant a build kicked
  // off and then a glance at another tab sent every in-page read, every
  // prepareOne and the final apply to the innocent page in front.
  const tab = (await sweepTab()) || (await getTab());
  if (!isInjectable(tab)) { showNotice(status, 'Cannot read this page.', 'error', 4000); return; }

  const jobs = [];
  for (const stop of aiSweep.stops) {
    for (const f of stop.found) if (picked.has(f.id)) jobs.push({ stop, f });
  }

  clearApproved();   // this list is the batch, not the session
  aiBulk = { running: true, abort: false, failed: [], armed: false,
             tabId: tab.id, host: getHostname(tab) };
  btn.disabled = true;
  const original = btn.textContent;
  const stopBtn = document.getElementById('buildStopBtn');
  if (stopBtn) { stopBtn.style.display = ''; stopBtn.disabled = false; stopBtn.textContent = '■ Stop building'; }
  setStage('cards');

  try {
    for (let i = 0; i < jobs.length; i++) {
      // A build is a model call per component, so twenty components is minutes.
      // Stopping keeps everything already saved — they are in Mappings and on
      // the page — and just does not start the next one.
      if (aiBulk.abort) {
        showNotice(status,
          `Stopped. ${i} of ${jobs.length} built and saved; the rest are still ticked.`,
          'warn', 8000);
        break;
      }
      const { stop, f } = jobs[i];
      btn.textContent = `Preparing ${i + 1} of ${jobs.length}…`;
      showMapBusy(f.label, i + 1, jobs.length);
      await spotlightBuild(tab, f.sel, f.trigger);
      // A listbox, a datepicker and a tooltip are rooted on the thing that
      // APPEARS, and the sweep holds only the control that summons it. Passing
      // an empty container made rowFromParts refuse every one of them — that is
      // why a page reporting six components saved five, with the reason shown
      // in a panel the auto-approve closed a moment later.
      //
      // Two ways to supply the other half, best evidence first. The probe
      // PRESSED it and watched what came out; that is not a guess. Failing
      // that, it is read off the page the same way every other selector is.
      let container = '';
      let found = f.sel;
      let openWhy = '';
      // Gate on triggerRequired ONLY. A dialog is firstArgFrom:'trigger' too,
      // but its row's sel is the DIALOG itself and its trigger is optional —
      // sending it through this hunt asked the markup read "what does this
      // dialog open", and on a page where a runtime engine had decorated a
      // dropdown with role=listbox, the answer was that dropdown: every
      // dialog on molinahealthcare.com shipped with
      // trigger:'.signin-dropdown' (2026-09-01). A dialog's trigger comes
      // from the survey, below.
      if (triggerRequired(f.type)) {
        const seen = (stop.probed || []).find(p =>
          p.parts && (p.parts.trigger === f.sel || p.root === f.sel) && p.parts.panel);
        container = (seen && seen.parts.panel) ||
          (await inPage(tab.id, (s) => window.__u1SelectorIntel.openedBy(s), [f.sel])) || '';
        // Both of those need f.sel to BE the trigger. The survey names the
        // component, which for a sign-in dropdown is the wrapper holding the
        // button and the closed list together — so both came back empty and the
        // whole component was refused with "open it on the page, then paste its
        // selector", addressed to nobody, in an unattended sweep.
        //
        // listboxShape does not care which of the three you point at. It reads
        // the wrapper, the button or the list and returns all three. It was
        // already being called one step later, in prepareOne — one step after
        // the refusal that made sure prepareOne was never reached.
        if (!container && f.type === 'listbox') {
          // Climbing to the parent as well: listboxShape reads the WRAPPER,
          // and a row rooted on the list itself (menuIsReallyListbox does
          // that) answers only from one level up.
          const lb = await inPage(tab.id, (s) => {
            const S = window.__u1SelectorIntel;
            let sh = S.listboxShape(s);
            if (!sh) {
              try {
                const el = document.querySelector(s);
                if (el && el.parentElement) {
                  const up = S.robustSelector(el.parentElement);
                  if (up && S.isU1Valid(up)) sh = S.listboxShape(up);
                }
              } catch (e) {}
            }
            return sh || null;
          }, [f.sel]);
          if (lb && lb.listbox) { container = lb.listbox; found = lb.trigger || f.sel; }
        }
        // Fourth source, for the component that defeats all three reads: it
        // is CLOSED and its markup states nothing — no aria-controls, no list
        // shape while shut, and the survey's probe never pressed it. So press
        // it now, read what appears while it is open, and put it back. This
        // is the same open-and-read every interactive path already gets.
        if (!container) {
          const cap = await autoOpenCapture(tab, found, f.type);
          if (cap && cap.shape && cap.shape.listbox) {
            container = cap.shape.listbox;
            if (cap.shape.trigger) found = cap.shape.trigger;
          } else if (cap && (cap.root || cap.stated)) {
            container = cap.root || cap.stated;
            // The mapping's trigger is the button that was actually pressed,
            // not the wrapper the survey named around it.
            if (cap.pressed) found = cap.pressed;
          } else if (cap && cap.err) {
            // The refusal below says only "open it on the page" — which reads
            // as nothing was even attempted. It was; say what stopped it, or
            // the same card comes back run after run with no way to know why.
            openWhy = cap.err;
          } else if (cap && !cap.opened) {
            openWhy = `pressed ${cap.pressed || 'it'}, but nothing new appeared on the page`;
          }
        }
      } else if (acceptsTrigger(f.type) && f.trigger) {
        // The third source, and the one that reaches the types the two above
        // never ran for. A dialog, a tooltip, a collapsible grid: their trigger
        // is OPTIONAL, so neither the probe nor openedBy was ever asked, and
        // the field stayed empty on every single one. The page declared the
        // relationship in its own markup, the survey copied it through, and
        // this is where it lands in the mapping.
        container = f.trigger;
      }
      const built = rowFromParts({
        type: f.type, found, container, label: f.label, compIndex: undefined,
        why: f.why,
      });
      if (built.err) {
        // "Open it on the page" alone reads as nothing was even attempted.
        // It was — say what stopped it, or the same card comes back run
        // after run with no way to know why.
        const why = built.err + (openWhy ? ` (Tried to open it myself: ${openWhy}.)` : '');
        aiBulk.failed.push({ label: f.label, err: why });
        f.failed = why;
        continue;
      }
      f.failed = null;
      built.row.needsWork = f.needsWork;
      try {
        const prepared = await prepareOne(built.row, tab);
        if (prepared.err) {
          aiBulk.failed.push({ label: f.label, err: prepared.err });
          f.failed = prepared.err;
        } else { stop.indexes.push(prepared.idx); f.done = true; f.failed = null; }
      } catch (err) {
        aiBulk.failed.push({ label: f.label, err: err.message });
        f.failed = err.message;
      }
    }
  } finally {
    clearMapBusy();
    aiBulk.running = false;
    btn.disabled = false;
    btn.textContent = original;
    if (stopBtn) stopBtn.style.display = 'none';
  }

  renderBulkReview();
  // Everything on that screen is what was just ticked, so approving it again
  // would be the same question twice. The code is still there to read on each
  // row afterwards, and every mapping stays editable in Mappings below.
  document.getElementById('aiBulkApproveBtn')?.click();
  // And the page you were working through comes back — with the sections just
  // finished moved into the completed drawer, and the ones never read still
  // waiting. Hiding it left the review on screen and nothing else, which reads
  // as the end of the job on a page with twenty-five sections left in it.
  renderSweepPicks();
  // Inside every dialog this batch built: a dialog is a page of its own.
  const dlgCount0 = (aiSweep.stops || []).reduce((a2, s2) =>
    a2 + ((s2.found || []).filter((f2) => f2 && f2.done && f2.type === 'dialog' && f2.sel).length), 0);
  if (!(await confirmStaticPass(dlgCount0))) {
    sweepLog(0, 'static pass skipped at your request — headings, vague links and dialog interiors left for a later run', 'skip');
  } else {
  try {
    sweepLog(0, 'dialog interiors: starting — every dialog this run built gets its own inside scan', 'info');
    const din = await dialogInteriorScan(tab);
    if (din.dialogs) {
      sweepLog(0, `dialog interiors: looked inside ${din.dialogs} dialog${din.dialogs === 1 ? '' : 's'}, ` +
        `mapped ${din.made} component${din.made === 1 ? '' : 's'} in there`, 'info');
    }
  } catch (e) { sweepLog(0, 'dialog-interior scan failed: ' + e.message, 'err'); }
  // The page-wide finishing pass: heading outline and vague links, written
  // automatically once the components of this batch are built.
  try {
    // The requested heads-up: the run has moved from components to the
    // page-wide STATIC pass — headings and vague links.
    sweepLog(0, 'static pass: starting — reading the heading outline and the vague links', 'info');
    const builtStops = [...new Set(jobs.map((jj) => jj.stop))];
    const viewH2 = await inPage(tab.id, () => window.innerHeight).catch(() => 900);
    const staticRanges2 = builtStops.map((s4) => ({ top: s4.scrollY || 0, bottom: (s4.scrollY || 0) + (viewH2 || 900) }));
    const fin = await sweepFinishingPass(tab, staticRanges2);
    const vd = fin.vagueDiag || {};
      const vaguePart = fin.links
        ? `${fin.links} vague-link group${fin.links === 1 ? '' : 's'} mapped`
        : !vd.vague ? 'no vague links (learn-more-style) on the page'
        : `${vd.vague} vague link${vd.vague === 1 ? '' : 's'} seen (${(vd.sample || []).join(', ')}) but none mapped — ` +
          [vd.noCard ? `${vd.noCard} had no heading beside them` : '',
           vd.lonely ? `${vd.lonely} were one of a kind` : '',
           vd.noSelector ? `${vd.noSelector} lost their common selector` : '']
            .filter(Boolean).join(', ');
      sweepLog(0, `finishing pass: ` + vaguePart + ` (headings are left to the manual review, by decision)`, 'info');
  } catch (e) { sweepLog(0, 'static pass failed: ' + e.message, 'err'); }
  clearSweepBusy();
  }
  return { built: (aiBulk.failed || []).length === 0, failed: (aiBulk.failed || []).length };
}

document.getElementById('sweepMakeBtn')?.addEventListener('click', async () => {
  if (aiSweep.running && !sweepPause.resolve) return;
  if (aiSweep.phase === 'screens') {
    const sections = sweepPickedScreens();
    if (!sections.length) return;
    const ticked = aiSweep.stops.filter((s) => sections.includes(s.n))
      .reduce((a, s) => a + (s.count || 0), 0);
    if (!(await confirmSweepCost(sections.length, 0, ticked, sweepCallsFor(sections)))) return;
    await scanPickedScreens(sections);
    return;
  }
  await buildPickedComponents();
});

const aiMapCardError = (row, why) => `
  <div class="ai-map-card">
    <div class="ai-map-head"><strong>${escapeHtml(row.label)}</strong>
      <span class="ai-conf" data-c="low">failed</span></div>
    <div class="ai-comp-why">${escapeHtml(why)}</div>
  </div>`;

function renderAiMapCard(idx, row, out, recorderActive) {
  const conf = ['high', 'medium', 'low'].includes(out.confidence) ? out.confidence : 'medium';
  return `
    <div class="ai-map-card" data-card="${idx}">
      <div class="ai-map-head">
        <strong>${escapeHtml(row.label)}</strong>
        <code>u1.fix.${escapeHtml(row.type)}</code>
        <span class="ai-conf" data-c="${conf}">${conf} confidence</span>
      </div>
      ${out.notes ? `<div class="ai-comp-why">⚠️ ${escapeHtml(out.notes)}</div>` : ''}

      <!-- Neither the code nor the form is what you came for: you came to
           approve this element. Both are here when you want them, folded. -->
      <details class="ai-map-code">
        <summary>Show the code</summary>
        <div class="code-preview" id="aiMapCode${idx}"></div>
      </details>

      <details class="ai-map-edit">
        <summary>✍️ Edit the selectors</summary>
        <div class="ai-comp-why">${recorderActive
          ? '✓ Triggers identified from the real click handlers recorded on this page.'
          : 'Triggers were worked out from tags and attributes. For measured handlers, switch on precise event detection and reload the page.'}</div>
        <div class="ai-map-form" id="aiMapForm${idx}"></div>
      </details>

      <div class="ai-find-actions">
        <button class="btn-primary btn-sm" data-savecard="${idx}">✓ Approve &amp; apply</button>
        <button class="btn-ghost btn-sm" data-skipcard="${idx}">Skip</button>
        <button class="btn-ghost btn-sm" data-editcard="${idx}">Open in builder</button>
        <button class="btn-ghost btn-sm" data-askwhy="${idx}">✨ Ask AI about this</button>
      </div>
      <div class="ai-why" id="aiWhy${idx}" style="display:none;"></div>
    </div>`;
}

// What to do after approving: carry on with what is left, or start a new scan.
// Rendered under the approved list and kept in step with what remains.
function renderApprovedNext() {
  const box = document.getElementById('aiApproved');
  if (!box || !document.querySelectorAll('#aiApprovedList .ai-approved-row').length) return;
  const left = document.querySelectorAll('#aiCompTrack .ai-comp:not([data-done])').length;
  const cards = document.querySelectorAll('#aiSlideTrack .ai-map-card:not([data-done])').length;

  let el = document.getElementById('aiNextRow');
  if (!el) {
    el = document.createElement('div');
    el.id = 'aiNextRow';
    el.className = 'ai-next-row';
    (document.getElementById('aiApprovedList') || box).appendChild(el);
  }
  el.innerHTML = cards
    ? `<button class="btn-primary btn-sm" data-ainext="cards">Next mapping →<span class="ai-next-count">${cards} left</span></button>`
    : left
      ? `<button class="btn-primary btn-sm" data-ainext="list">Next → back to what was found<span class="ai-next-count">${left} left</span></button>`
      : `<button class="btn-primary btn-sm" data-ainext="scan">🔎 Scan this page again</button>` +
        `<span class="ai-next-hint">Everything on this page has been handled. Open a dialog or go to another page, then scan again.</span>`;
}

document.getElementById('aiApproved')?.addEventListener('click', (e) => {
  const btn = e.target.closest('[data-ainext]');
  if (!btn) return;
  const what = btn.dataset.ainext;
  if (what === 'cards') {
    setStage('cards');
    showSlide(slideIndex('aiSlide'));
    document.querySelector('#aiSlideTrack .ai-map-card:not([data-done])')
      ?.scrollIntoView({ block: 'start', behavior: 'smooth' });
  } else if (what === 'list') {
    setStage('found');
    showCompSlide(slideIndex('aiComp'));
    document.getElementById('aiResults').scrollIntoView({ block: 'start', behavior: 'smooth' });
  } else {
    document.getElementById('aiDiscoverBtn')?.click();
  }
});

// Replace a pending row's verdict once the page has actually been measured.
function updateApproved(rowId, verdict) {
  // The verdict has arrived — stop the progress bar that stood in for it.
  document.getElementById(rowId)?.querySelector('[data-pendingbar]')?.remove();
  const row = document.getElementById(rowId);
  if (!row) return;
  const tick = row.querySelector('.ai-approved-tick');
  if (tick) { tick.className = 'ai-approved-tick ' + (verdict.ok ? 'ok' : 'warn'); tick.textContent = verdict.ok ? '✓' : '!'; }
  const why = row.querySelector('.ai-approved-why');
  if (why) why.textContent = verdict.msg;
  if (verdict.clashes && verdict.clashes.length) {
    why?.insertAdjacentHTML('afterend', `<div class="ai-approved-why">${verdict.clashes.map(c =>
      `<button class="btn-outline btn-xs" data-dropkey="${escapeHtml(c.key)}">Remove u1.fix.${escapeHtml(c.type)} on ${escapeHtml(c.sel)}</button>`).join(' ')}</div>`);
  }
}

// ── Carousels ───────────────────────────────────────────────────────────────
// One card at a time, for both stages. At side-panel width a stack of cards is
// the wall of controls that made this unreadable; a card that gets the full
// width gets read. Cards marked data-done="1" (approved, skipped) drop out.
const carouselAt = {};   // id -> current index

// `id` is the track prefix; `sel` matches the cards inside it.
function slideTo(id, i, sel, onShow) {
  const track = document.getElementById(id + 'Track');
  if (!track) return;
  const all = [...track.querySelectorAll(sel)];
  all.forEach(c => { c.style.display = 'none'; });
  const cards = all.filter(c => c.dataset.done !== '1');

  const head = track.previousElementSibling;
  if (!cards.length) {
    if (head) head.style.display = 'none';
    // The stage owns display, not the carousel inside it. An empty track is a
    // reason to move ON, and where to is a stage question.
    if (track.closest('.ai-results')) setStage(resumeStage());
    // Handling the last card must not strand you on an empty panel. If there
    // is still an inventory to work through, go back to it — skipping one
    // element is not a reason to end the run.
    if (id === 'aiSlide') {
      const left = document.querySelectorAll('#aiCompTrack .ai-comp:not([data-done])').length;
      if (left) {
        setStage('found');
        showCompSlide(carouselAt.aiComp || 0);
        document.getElementById('aiResults')?.scrollIntoView({ block: 'start', behavior: 'smooth' });
      }
    }
    return;
  }
  if (head) head.style.display = '';

  const at = Math.max(0, Math.min(i, cards.length - 1));
  carouselAt[id] = at;
  cards[at].style.display = '';

  const count = document.getElementById(id + 'Count');
  if (count) count.textContent = `${at + 1} / ${cards.length}`;
  const [prev, next] = [`[data-slide="${id}:prev"]`, `[data-slide="${id}:next"]`]
    .map(s => document.querySelector(s));
  if (prev) prev.disabled = at === 0;
  if (next) next.disabled = at >= cards.length - 1;
  if (onShow) onShow(cards[at]);
}

// Stage 2 keeps its own thin wrapper so the call sites stay readable.
const showSlide = (i) => {
  slideTo('aiSlide', i, '.ai-map-card', (card) => refreshAiCard(Number(card.dataset.card)));
  renderApprovedNext();
};
const slideIndex = (id) => carouselAt[id] || 0;

// Delegated prev/next for every carousel on the tab.
document.getElementById('tab-picker')?.addEventListener('click', (e) => {
  const btn = e.target.closest('[data-slide]');
  if (!btn) return;
  const [id, dir] = btn.dataset.slide.split(':');
  const at = carouselAt[id] || 0;
  if (id === 'aiSlide') showSlide(dir === 'next' ? at + 1 : at - 1);
  else showCompSlide(dir === 'next' ? at + 1 : at - 1);
});

// Approved mappings collect here, each carrying whether it actually took effect
// on the page — the same measured verdict the Apply button reports.
let approvedSeq = 0;

/**
 * Empty the applied list — the LIST, not the section.
 *
 * This used to be `#aiApproved.innerHTML = ''`, which took the <summary> and
 * the count badge with it. addApproved rebuilds only the inner list, so after
 * one re-scan the heading was gone for the rest of the session.
 *
 * It is called at the start of every batch, because the list answers "what did
 * I just do". Left to accumulate it answered "what has happened since the panel
 * opened" — a number that, in the whole-page route, crossed every run and every
 * route switch and read as the current batch. The permanent record is the
 * Mappings list below, which nothing here touches.
 */
function clearApproved() {
  const box = document.getElementById('aiApproved');
  if (!box) return;
  const list = box.querySelector('#aiApprovedList');
  if (list) list.innerHTML = '';
  const n = document.getElementById('aiApprovedN');
  if (n) n.textContent = '';
  if (currentStage === 'applied') setStage(resumeStage());
}

function addApproved(row, verdict, code) {
  const box = document.getElementById('aiApproved');
  if (!box) return null;
  setStage('applied');
  box.open = true;
  const cls = verdict.ok ? 'ok' : 'warn';
  // A conflicting older mapping is actionable, so offer the action rather than
  // just naming the problem — but never delete anything without being asked.
  const clashBtns = (verdict.clashes || []).map(c =>
    `<button class="btn-outline btn-xs" data-dropkey="${escapeHtml(c.key)}">Remove u1.fix.${escapeHtml(c.type)} on ${escapeHtml(c.sel)}</button>`).join(' ');

  const rowId = 'aiApproved' + (++approvedSeq);
  // Resolve these from the box, not by a global id lookup — the list lives
  // inside it, and a lookup is one more thing that can find nothing.
  let listEl = box.querySelector('#aiApprovedList');
  if (!listEl) {
    listEl = box.ownerDocument.createElement('div');
    listEl.id = 'aiApprovedList';
    box.appendChild(listEl);
  }
  const nEl = box.querySelector('#aiApprovedN');
  if (nEl) nEl.textContent = String(listEl.querySelectorAll('.ai-approved-row').length + 1);
  // Approving the last card leaves this list on screen with nothing to do
  // next, which reads as being stuck. Give the run somewhere to go.
  queueMicrotask(renderApprovedNext);
  listEl.insertAdjacentHTML('beforeend', `
    <div class="ai-approved-row" id="${rowId}">
      <span class="ai-approved-tick ${cls}">${verdict.ok ? '✓' : '!'}</span>
      <span class="ai-approved-label">${escapeHtml(row.label)}</span>
      <code>u1.fix.${escapeHtml(row.type)}</code>
      ${verdict.pending ? '<div class="ai-busy-bar" data-pendingbar><span></span></div>' : ''}
      <div class="ai-approved-why">${escapeHtml(verdict.msg)}</div>
      ${code ? `<details class="ai-approved-code"><summary>Show the code that was applied</summary><div class="code-preview">${escapeHtml(code)}</div></details>` : ''}
      ${clashBtns ? `<div class="ai-approved-why">${clashBtns}</div>` : ''}
    </div>`);
  return rowId;
}

// Renders the standard sub-selector rows into a card and fills them with the
// AI's answer. Reuses renderSubSelectorInputs by pointing it at this card's
// container, so the markup, hints, 🔍 testers and strength badges are identical
// to Manual mode — the AI only replaces the typing.
function fillAiMapCard(idx, row, out) {
  const form = document.getElementById('aiMapForm' + idx);
  if (!form) return;
  const schema = COMPONENT_SCHEMAS[row.type];
  const pKey = primaryKeyOf(schema);

  form.innerHTML =
    `<div class="sub-sel-row">
       <div class="key">${escapeHtml(pKey || 'selector')} <span class="req-star">*</span></div>
       <span class="sel-strength-wrap">
         <input type="text" data-field="__primary" value="${escapeHtml(out.primary || row.sel)}">
         <span class="sel-strength" data-level="empty" aria-hidden="true"></span>
       </span>
       <button class="btn-ghost btn-xs sel-test" title="Test selector on page">🔍</button>
     </div>`;
  renderSubSelectorInputs(row.type, form, { append: true });
  // Every selector field on this card gets the page's own names to choose from.
  // Typing a selector blind is where "invented — .tab-bar is on no element" came
  // from, and it is the whole of the work for a combobox, whose four
  // sub-selectors had no source but the keyboard.
  attachSelectorSuggestions(form, (aiFound && aiFound.context) || null);

  const byKey = {};
  for (const f of (out.fields || [])) byKey[f.key] = f;
  for (const f of (schema.fields || [])) {
    const inp = form.querySelector(`input[data-field="${CSS.escape(f)}"]`);
    if (inp && byKey[f]) {
      inp.value = byKey[f].value;
      if (byKey[f].why) {
        const hint = inp.closest('.sub-sel-row')?.querySelector('.input-hint');
        if (hint) hint.insertAdjacentHTML('beforeend', `<div class="strength-why">AI: ${escapeHtml(byKey[f].why)}</div>`);
      }
    }
  }
  for (const o of (out.options || [])) {
    const inp = form.querySelector(`[data-root="${CSS.escape(o.key)}"]`);
    if (!inp) continue;
    if (inp.type === 'checkbox') inp.checked = !/^(false|no|off|0)$/i.test(String(o.value).trim());
    else inp.value = o.value;
  }
  // A menu with submenus MUST have menubar off, or u1 throws
  // "Submenu must have a trigger element".
  if (row.type === 'menu' && byKey.submenus && !(out.options || []).some(o => o.key === 'menubar')) {
    const mb = form.querySelector('[data-root="menubar"]');
    if (mb && mb.type === 'checkbox') mb.checked = false;
  }

  refreshAiCard(idx);
}

/**
 * Offer the page's real element names on every selector input in a form.
 *
 * A <datalist> rather than a <select>: a selector is not always one element's
 * name — `.a,.b` and `#x>li` are ordinary answers — so the field has to stay
 * free text with the real names offered beside it, not replaced by them.
 *
 * The names come from the collector, which already reports every id, class and
 * tag it saw (`tokens`), plus the full selector it built for each candidate.
 * Nothing new is fetched.
 */
function attachSelectorSuggestions(form, ctx) {
  if (!form) return;
  const names = new Set();
  for (const t of (ctx && ctx.tokens) || []) names.add(t);
  for (const c of (ctx && ctx.candidates) || []) if (c && c.selector) names.add(c.selector);
  if (!names.size) return;

  // One list per form, shared by its fields — a datalist per input would be the
  // same few thousand options repeated for every row on the card.
  const id = 'seldl-' + (form.id || Math.random().toString(36).slice(2, 8));
  let dl = document.getElementById(id);
  if (!dl) {
    dl = document.createElement('datalist');
    dl.id = id;
    form.appendChild(dl);
  }
  // Shortest first: `.suggestion` before `#box>ul.list>li.suggestion`, because
  // the short one is nearly always the one meant.
  dl.innerHTML = [...names]
    .sort((a, b) => a.length - b.length || a.localeCompare(b))
    .slice(0, 1000)
    .map((n) => `<option value="${escapeHtml(n)}"></option>`).join('');

  form.querySelectorAll('input[type="text"][data-field]').forEach((inp) => {
    inp.setAttribute('list', id);
    inp.setAttribute('autocomplete', 'off');   // the browser's history is not the page
  });
}

// Build the template from one card's inputs (the card-scoped twin of
// buildTemplateFromForm), refresh its code preview and its strength badges.
function aiCardTemplate(idx) {
  const form = document.getElementById('aiMapForm' + idx);
  const entry = aiMapped[idx];
  if (!form || !entry) return null;
  const primary = form.querySelector('input[data-field="__primary"]').value.trim();
  if (!primary) return null;
  const fieldValues = {};
  form.querySelectorAll('input[type="text"][data-field]').forEach(inp => {
    if (inp.dataset.field !== '__primary') fieldValues[inp.dataset.field] = inp.value.trim();
  });
  const rootValues = {};
  form.querySelectorAll('[data-root]').forEach(inp => {
    rootValues[inp.dataset.root] = inp.type === 'checkbox' ? inp.checked : inp.value.trim();
  });
  const tpl = buildTemplate(entry.row.type, primary, fieldValues, rootValues);
  // The role question was answered on the component card, two steps back. Carry
  // it, or saveMappingEntry asks again — and the export would not strip the
  // role even though the answer was given.
  if (tpl && entry.row.overwriteRole) {
    tpl.overwriteRole = entry.row.overwriteRole;
    tpl.code = mappingToCode(tpl);
  }
  return tpl;
}

async function refreshAiCard(idx) {
  const tpl = aiCardTemplate(idx);
  const pre = document.getElementById('aiMapCode' + idx);
  if (pre) pre.textContent = tpl ? tpl.code : '';
  const form = document.getElementById('aiMapForm' + idx);
  if (!form) return;
  const wraps = [...form.querySelectorAll('.sel-strength-wrap')];
  const sels = wraps.map(w => w.querySelector('input').value.trim());
  // A type whose primary is MEANT to match many must not be graded as though
  // it were a u1.fix.* selector that resolves one element.
  const many = !!(tpl && COMPONENT_SCHEMAS[tpl.type] && COMPONENT_SCHEMAS[tpl.type].primaryMany);
  const isUnique = (key) => (key === '__primary' ? !many : SINGULAR_FIELDS.has(key));
  wraps.forEach((w, i) => {
    const key = w.querySelector('input').dataset.field || '';
    paintStrength(w.querySelector('.sel-strength'), strengthOf(sels[i], { unique: isUnique(key) }));
  });
  const counts = await countSelectors(sels);
  wraps.forEach((w, i) => {
    const inp = w.querySelector('input');
    if (inp.value.trim() !== sels[i]) return;
    const key = inp.dataset.field || '';
    const o = { unique: isUnique(key) };
    if (typeof counts[i] === 'number') o.count = counts[i];
    paintStrength(w.querySelector('.sel-strength'), strengthOf(sels[i], o));
  });
}

document.getElementById('aiMappings')?.addEventListener('input', (e) => {
  const card = e.target.closest('[data-card]');
  if (!card) return;
  clearTimeout(aiCardTimer);
  aiCardTimer = setTimeout(() => refreshAiCard(Number(card.dataset.card)), 400);
});
document.getElementById('aiMappings')?.addEventListener('change', (e) => {
  const card = e.target.closest('[data-card]');
  if (card && e.target.matches('[data-root]')) refreshAiCard(Number(card.dataset.card));
});

document.getElementById('aiMappings')?.addEventListener('click', async (e) => {
  const skip = e.target.closest('[data-skipcard]');
  if (skip) {
    skip.closest('.ai-map-card').dataset.done = '1';
    showSlide(slideIndex('aiSlide'));
    return;
  }

  const save = e.target.closest('[data-savecard]');
  if (save) {
    const idx = Number(save.dataset.savecard);
    const tpl = aiCardTemplate(idx);
    // The CARDS stage's own status line. #aiMapStatus is inside #aiResults,
    // which is display:none whenever a card is showing — so everything this
    // handler said, refusals included, went into a hidden element and the
    // button looked dead. Falls back to the old one only if the markup is
    // older than this fix.
    const status = stageStatusEl();
    if (isReadonly()) {
      showNotice(status, 'Licence expired — existing mappings still work and export, but new ones are paused.', 'error', 6000);
      return;
    }
    if (!aiWorkspaceMatchesSite()) { warnWrongSite(status); return; }
    if (!tpl) {
      // Approve & apply doing nothing but leave a small toast is exactly the
      // failure mode a low-confidence card produces most often — the AI left
      // the primary selector empty on purpose because it couldn't find one it
      // trusted, so this button silently has nothing to do. A toast that
      // fades in 3.5s next to a button that never even changed its own text
      // reads as "the click didn't register," not "there's a field to fill
      // in above." Open the form, put focus where the fix actually is, and
      // don't let it fade on its own.
      const card = save.closest('.ai-map-card');
      const editDetails = card?.querySelector('.ai-map-edit');
      if (editDetails) editDetails.open = true;
      const primaryInput = card?.querySelector('input[data-field="__primary"]');
      if (primaryInput) {
        primaryInput.focus();
        primaryInput.classList.add('input-flash-error');
        setTimeout(() => primaryInput.classList.remove('input-flash-error'), 1500);
      }
      showNotice(status, 'Nothing to save yet — no selector could be determined for this element. Fill one in above (⚠️ note explains why the AI left it blank), or use "Open in builder".', 'error', 0);
      return;
    }

    save.disabled = true; save.textContent = 'Saving…';

    try {
      const r = await saveMappingEntry(tpl);
      if (r && r.cancelled) {
        save.disabled = false; save.textContent = '✓ Approve & apply';
        showNotice(status, 'Not saved — the role the site wrote is still there. Nothing was changed.', 'info', 6000);
        return;
      }
    } catch (e) {
      save.disabled = false; save.textContent = '✓ Approve & apply';
      showNotice(status, e.message, 'error', 12000);
      return;
    }

    // Move on NOW. Verifying what U1 did means waiting for U1, and that wait
    // belongs to the report, not to you — blocking the carousel on it made
    // approving feel like it took a minute.
    const card = save.closest('.ai-map-card');
    card.dataset.done = '1';
    const row = aiMapped[idx].row;
    if (row.compIndex != null) {
      const comp = document.querySelector(`#aiCompTrack .ai-comp[data-i="${CSS.escape(row.compIndex)}"]`);
      if (comp) { comp.dataset.done = '1'; showCompSlide(slideIndex('aiComp')); }
    }
    const rowId = addApproved(row, { ok: true, msg: 'Saved. Applying…', pending: true }, tpl.code);
    showSlide(slideIndex('aiSlide'));
    const next = document.querySelector('#aiSlideTrack .ai-map-card:not([data-done])');
    if (next) next.scrollIntoView({ block: 'start', behavior: 'smooth' });
    else document.getElementById('aiApproved')?.scrollIntoView({ block: 'start', behavior: 'smooth' });

    // ── everything below runs in the background ──
    // The catch is what ends the progress bar when the measurement itself
    // fails. Without it a rejection here left the row spinning "Applying…"
    // forever, which reads as the tool still working on something it has
    // already given up on. The mapping IS saved at this point — only the
    // verdict is missing, so say exactly that.
    (async () => {
      const mkey = storageKey('mappings', currentHostname);
      const existing = (await U1Store.get([mkey]))[mkey] || [];
      const clashes = await overlappingMappings(tpl.primary, existing);

      const res = await applyMappingsBatch([{
        type: tpl.type, primary: tpl.primary, firstArg: tpl.firstArg, config: tpl.config,
        overwriteRole: tpl.overwriteRole,
      }]);
      const verdict = describeApply(res, tpl);

      if (clashes.length) {
        verdict.clashes = clashes;
        verdict.ok = false;
        verdict.msg += ` Also mapped by ${clashes.map(c => `u1.fix.${c.type} on ${c.sel}`).join(', ')} — two on the same elements fight, and the second wins.`;
      }
      updateApproved(rowId, verdict);
    })().catch((err) => {
      updateApproved(rowId, {
        ok: false,
        msg: `Saved, but applying it could not be measured: ${err?.message || err}. Reload the page and re-run Apply to check it took effect.`,
      });
    });
    return;
  }

  const ask = e.target.closest('[data-askwhy]');
  if (ask) {
    const idx = Number(ask.dataset.askwhy);
    const entry = aiMapped[idx];
    const box = document.getElementById('aiWhy' + idx);
    if (!entry || !box) return;
    box.style.display = 'block';
    const key = 'card:' + idx;
    if (!agentThreads.has(key)) {
      box.innerHTML = '<div class="ai-busy"><div class="ai-busy-bar"><span></span></div>' +
        '<div class="ai-busy-sub">Measuring what this mapping does on the page.</div></div>';
      const tpl = aiCardTemplate(idx);
      const ctx = tpl
        ? await agentContext(tpl.type, tpl.primary, tpl.firstArg, tpl.config, tpl.overwriteRole)
        : { err: 'The mapping could not be rebuilt from the form.' };
      if (ctx.err) { box.innerHTML = `<div class="ai-sel-bad">${escapeHtml(ctx.err)}</div>`; return; }
      // It already has the markup this card was built from; prefer it.
      ctx.markup = entry.markup || ctx.markup;
      agentThreads.set(key, { ctx, history: [] });
    }
    renderAgentThread(box, key);
    return;
  }

  const edit = e.target.closest('[data-editcard]');
  if (edit) {
    // Hand this card off to the Manual builder, unchanged.
    const idx = Number(edit.dataset.editcard);
    const tpl = aiCardTemplate(idx);
    if (!tpl) return;
    loadMappingIntoForm({ type: tpl.type, primary: tpl.primary, config: tpl.config });
  }
});

// ── Precise event detection ─────────────────────────────────────────────────
//
// Registered dynamically rather than in manifest.json, and — this is the part
// that matters — only for the sites this specialist actually works on.
//
// It used to be registered for <all_urls>. That put a MAIN-world patch of
// EventTarget.prototype on every page the person opened for the rest of the
// day: their mail, their bank, the CRM. Two things came of that, both visible
// on the extension's own Errors page:
//
//   1. Our wrapper is the immediate caller of the native addEventListener, so
//      any violation the PAGE commits in registering a listener is filed
//      against us. Gmail's document forbids `unload` listeners and something
//      on it registers one anyway; the error reads "Permissions policy
//      violation: unload is not allowed in this document" at
//      event-recorder.js:48, which is the line that calls the original. Not
//      our listener, not our policy, and reported as our error every time.
//   2. A MAIN-world content script is subject to the PAGE's CSP, unlike an
//      isolated-world one. On any site with a strict script-src the injection
//      is refused outright and logged — noise on a page where the recorder was
//      never going to run in the first place.
//
// Neither is a bug in the recorder. Both are the cost of being somewhere it
// has no business being, so the fix is to be there only for the client sites
// the panel has been opened on. The list is device-local and bounded.
const RECORDER_ID = 'u1-event-recorder';
// A device-local preference, not project data: the `__` prefix keeps it out of
// exported backups (U1Store.getExportable strips private keys).
const PRECISE_EVENTS_KEY = U1Store.PRIVATE_PREFIX + 'preciseEvents';
const RECORDER_HOSTS_KEY = U1Store.PRIVATE_PREFIX + 'recorderHosts';
// Enough for every client a specialist touches in a year, and still a bound —
// a match list is re-registered on every panel open and must not grow forever.
const MAX_RECORDER_HOSTS = 60;

/**
 * The two patterns that cover a hostname: the host itself and its subdomains.
 *
 * currentHostname has already had "www." stripped, so a site stored as
 * example.com must still match www.example.com — which the subdomain pattern
 * does. Both schemes, because a client's staging site is often plain http.
 */
function recorderMatchesFor(host) {
  return [`*://${host}/*`, `*://*.${host}/*`];
}

/** Hosts the recorder is registered for, newest first. */
async function loadRecorderHosts() {
  try {
    const v = (await U1Store.get([RECORDER_HOSTS_KEY]))[RECORDER_HOSTS_KEY];
    return Array.isArray(v) ? v.filter((h) => typeof h === 'string' && h && h !== 'unknown') : [];
  } catch { return []; }
}

/**
 * Make sure the recorder is registered for this site, and only for sites like
 * it.
 *
 * Called on every panel open. Re-registering the whole list each time is what
 * narrows an old <all_urls> registration left behind by a previous version —
 * there is no separate migration, because the correct match list is computed
 * from scratch anyway.
 *
 * The one real cost is unchanged and still worth saying in Setup: the recorder
 * has to be installed BEFORE the page's own script runs, so the first time the
 * panel is opened on a new client site that page needs one reload before
 * precise detection has anything to report. Every visit after that is covered,
 * because the host stays on the list.
 */
async function ensureRecorderForHost(host) {
  if (!host || host === 'unknown') return false;
  try {
    const hosts = await loadRecorderHosts();
    const known = hosts.includes(host);
    const next = known ? hosts : [host, ...hosts].slice(0, MAX_RECORDER_HOSTS);

    const matches = [];
    for (const h of next) matches.push(...recorderMatchesFor(h));

    const [existing] = await chrome.scripting.getRegisteredContentScripts({ ids: [RECORDER_ID] });
    const same = existing && existing.matches &&
                 existing.matches.length === matches.length &&
                 existing.matches.every((m, i) => m === matches[i]);
    if (!same) {
      const script = {
        id: RECORDER_ID,
        matches,
        js: ['event-recorder.js'],
        runAt: 'document_start',
        world: 'MAIN',
        allFrames: false,
      };
      if (existing) await chrome.scripting.updateContentScripts([script]);
      else await chrome.scripting.registerContentScripts([script]);
    }
    // setLocalOnly: which machine has watched which site is a fact about this
    // computer, not about the client's site, and it must not travel.
    if (!known) await U1Store.setLocalOnly({ [RECORDER_HOSTS_KEY]: next });
    await U1Store.setLocalOnly({ [PRECISE_EVENTS_KEY]: true });
    return !known;                 // true when this site was only just added
  } catch (err) {
    showNotice(document.getElementById('applyStatus'),
      'Could not set up event detection: ' + err.message, 'error', 4000);
    return false;
  }
}

/**
 * Stop recording anywhere. Not wired to a control — precise detection is not a
 * choice any more — but the registration must still be removable, or a stale
 * <all_urls> one from an older build has no way out of an install where the
 * panel is never opened on a site.
 */
async function clearRecorder() {
  try {
    const existing = await chrome.scripting.getRegisteredContentScripts({ ids: [RECORDER_ID] });
    if (existing.length) await chrome.scripting.unregisterContentScripts({ ids: [RECORDER_ID] });
    await U1Store.setLocalOnly({ [RECORDER_HOSTS_KEY]: [], [PRECISE_EVENTS_KEY]: false });
    return true;
  } catch { return false; }
}

// ─────────────────────────────────────────────────────────────────────────────
//  Smart Advisor — inspect the selected element on the live page and recommend
//  the right component type + sub-selectors, and warn about common mistakes.
// ─────────────────────────────────────────────────────────────────────────────

// Inspect the element matched by `sel` and return a serializable profile of it
// and its subtree (no DOM nodes). Child selectors are built U1-valid (single
// simple selector, joined with '>', never a descendant space).
async function analyzeElement(sel) {
  const tab = await getTab();
  if (!isInjectable(tab)) return { err: 'Cannot run on this page.' };
  try {
    // Provides window.__u1SelectorIntel.robustSelector, used below.
    await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['selector-intel.js'] });
    const res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: (selector) => {
        let el;
        try { el = document.querySelector(selector); }
        catch (e) { return { error: e.message }; }
        if (!el) return { notFound: true };

        // Robust, U1-valid, UNIQUE selector builder: identity ladder + class
        // noise filter + uniqueness gate + id-anchored '>' chain. No spaces, no
        // :nth. One implementation, in selector-intel.js — this function's
        // caller injects it first. The fallback is the degraded identity ladder,
        // so a missing module is obvious rather than a silent second opinion.
        const simple = (node) => {
          if (window.__u1SelectorIntel) return window.__u1SelectorIntel.robustSelector(node);
          if (!node || node.nodeType !== 1) return '';
          if (node.id && /^[A-Za-z][\w-]*$/.test(node.id)) return '#' + node.id;
          const cls = (node.className && typeof node.className === 'string')
            ? node.className.trim().split(/\s+/).filter(Boolean) : [];
          return cls.length ? node.tagName.toLowerCase() + '.' + cls[0] : node.tagName.toLowerCase();
        };

        const classList = (el.className && typeof el.className === 'string')
          ? el.className.trim().split(/\s+/).filter(Boolean) : [];
        const role = el.getAttribute('role') || '';
        const ariaHaspopup = el.getAttribute('aria-haspopup') || '';

        const ul = /^(ul|ol)$/i.test(el.tagName) ? el : el.querySelector('ul,ol');
        const lis = ul ? ul.querySelectorAll(':scope > li') : [];
        const links = el.querySelectorAll('a[href]');
        const checkboxes = el.querySelectorAll('input[type="checkbox"]');
        const radios = el.querySelectorAll('input[type="radio"]');
        const buttons = el.querySelectorAll('button');
        const trs = el.querySelectorAll('tr');
        const tds = el.querySelectorAll('td');
        const imgs = el.querySelectorAll('img');
        const headings = Array.from(el.querySelectorAll('h1,h2,h3,h4,h5,h6')).map(h => h.tagName.toLowerCase());

        // Close-button candidate (dialogs).
        let closeBtn = el.querySelector('[aria-label*="close" i],[title*="close" i],.close,.close-btn,.modal-close,.ssm-close-btn');
        if (!closeBtn) closeBtn = Array.from(buttons).find(b => {
          const t = (b.textContent || '').trim().toLowerCase(); return t === '×' || t === 'x';
        }) || null;

        // Trigger candidate: an opener button that sits just before the element or
        // shares its parent (common menu-button / listbox pattern).
        let triggerEl = null;
        const prev = el.previousElementSibling;
        if (prev && /^(button|a)$/i.test(prev.tagName)) triggerEl = prev;
        if (!triggerEl && el.parentElement) {
          triggerEl = el.parentElement.querySelector('[aria-haspopup],button');
          if (triggerEl === el) triggerEl = null;
        }

        // First heading inside, for dialog heading suggestion.
        const heading = el.querySelector('h1,h2,h3,h4,h5,h6');

        const isClickable = !!(el.onclick || role === 'button' ||
          el.getAttribute('tabindex') != null || el.tagName === 'BUTTON' || el.tagName === 'A');

        const ulSel = ul ? simple(ul) : '';
        return {
          tag: el.tagName.toLowerCase(),
          role, ariaHaspopup,
          id: el.id || '', classList, childCount: el.childElementCount, isClickable,
          hasUl: !!ul, ulSel,
          liCount: lis.length,
          liSel: ul ? ulSel + '>li' : '',
          linkCount: links.length,
          linkSel: ul ? ulSel + '>li>a' : (links.length ? 'a' : ''),
          checkboxCount: checkboxes.length,
          radioCount: radios.length,
          buttonCount: buttons.length,
          trCount: trs.length, tdCount: tds.length, imgCount: imgs.length,
          headings,
          headingSel: heading ? simple(heading) : '',
          closeBtnSel: closeBtn ? simple(closeBtn) : '',
          triggerSel: triggerEl ? simple(triggerEl) : '',
        };
      },
      args: [sel],
    });
    return res?.[0]?.result || { err: 'No result' };
  } catch (err) { return { err: err.message }; }
}

// Heuristic ruleset → { type, fields:{key:sel}, notes:[{level,msg}] } or null.
// `fields` are SUB-selector suggestions only (the primary stays what the user typed).
function recommendComponent(p) {
  if (!p || p.err || p.error || p.notFound) return null;
  const cls = (p.classList || []).join(' ').toLowerCase();
  const role = (p.role || '').toLowerCase();
  const hp = (p.ariaHaspopup || '').toLowerCase();
  const notes = [];

  // Dialog / modal
  if (role === 'dialog' || hp === 'dialog' || /(^|[^a-z])(modal|dialog|popup|lightbox)([^a-z]|$)/.test(cls)) {
    const fields = {};
    if (p.closeBtnSel) fields.closeBtn = p.closeBtnSel;
    if (p.headingSel) fields.heading = p.headingSel;
    if (p.triggerSel) fields.trigger = p.triggerSel;
    notes.push({ level: 'ok', msg: 'Looks like a dialog / modal. If it has a trigger button that opens it, put that in "trigger".' });
    return { type: 'dialog', fields, notes };
  }

  // ul/list-based dropdowns
  if (p.hasUl && (p.liCount > 0 || p.linkCount > 0)) {
    // A pop-up list opened by a trigger button → listbox. Per U1's code the
    // listbox closes on ESC (case ESC → closeListbox) as long as `options`
    // points at the individual <li> items (not the container). This holds even
    // when the items are navigation links. Use `menu` only for a standing nav
    // bar with NO single trigger / real nested submenus — otherwise U1 throws
    // "Submenu must have a trigger element".
    if (p.triggerSel) {
      notes.push({ level: 'ok', msg: 'A dropdown opened by a trigger → listbox. It closes on ESC once “options” points at the <li> items (below). If the items navigate to other pages that is fine — listbox still works.' });
      const fields = { options: p.liSel, trigger: p.triggerSel };
      return { type: 'listbox', fields, notes };
    }
    // No trigger button → a persistent navigation menu.
    notes.push({ level: 'ok', msg: 'A standing navigation list (no single trigger) → menu.' });
    const fields = { items: p.linkCount > 0 ? p.linkSel : p.liSel };
    return { type: 'menu', fields, notes };
  }

  if (role === 'tablist' || /(^|[^a-z])tabs?([^a-z]|$)/.test(cls)) {
    notes.push({ level: 'ok', msg: 'Tab strip detected → tabs. Point "tab" at each tab button and "tabPanel" at the content panel.' });
    return { type: 'tabs', fields: {}, notes };
  }
  if (role === 'radiogroup' || p.radioCount > 0) {
    notes.push({ level: 'ok', msg: 'Radio buttons detected → radio.' });
    return { type: 'radio', fields: {}, notes };
  }
  if (p.checkboxCount > 0 || role === 'checkbox') {
    notes.push({ level: 'ok', msg: 'Checkbox detected → checkbox. Fill checkedState / uncheckedState with the on/off selectors.' });
    return { type: 'checkbox', fields: {}, notes };
  }
  if (p.trCount > 0 && p.tdCount > 0) {
    notes.push({ level: 'ok', msg: 'Rows & cells detected → table. Use "grid" instead if cells are interactive.' });
    return { type: 'table', fields: { row: 'tr', cell: 'td' }, notes };
  }
  if (p.tag === 'a') {
    notes.push({ level: 'ok', msg: 'An <a> element → link.' });
    return { type: 'link', fields: {}, notes };
  }
  if (p.isClickable && p.imgCount > 0) {
    notes.push({ level: 'ok', msg: 'A clickable element wrapping an image → button.' });
    return { type: 'button', fields: {}, notes };
  }
  return null;
}

// Validate the current field values against the page + rules. Returns notes.
// ── In-page test engine bridge ──────────────────────────────────────────────
// Injects test-engine.js into the page (idempotent) then calls one of its
// exported functions. Runs in the isolated content-script world (shared DOM).
async function callTestEngine(fnName, args, forTab) {
  // Same rule as applyMappingsBatch: a pinned run passes its own tab, or the
  // engine ends up driving keyboard tests on whatever page is in front.
  const tab = forTab || await getTab();
  if (!isInjectable(tab)) return null;
  try {
    // selector-intel.js first: test-engine.js delegates robustSelector to it.
    await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      files: ['selector-intel.js', 'test-engine.js'],
    });
    const res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      // The engine's own throw comes back as a message, not as null: "could
      // not run" with no reason sent the person hunting in the dark.
      func: async (fn, a) => {
        try {
          if (!(window.__u1TestEngine && window.__u1TestEngine[fn])) return { __err: 'the test engine is not on this page (it could not be injected)' };
          return await window.__u1TestEngine[fn].apply(null, a);
        } catch (e) { return { __err: String((e && e.message) || e) }; }
      },
      args: [fnName, args || []],
    });
    return res && res[0] ? res[0].result : null;
  } catch (e) {
    // executeScript itself failed: the page navigated away mid-test ("Frame
    // … was removed"), the tab closed, or the page is not injectable.
    return { __err: /Frame|removed|closed|No tab/i.test(String(e && e.message)) ? `the page navigated away while this was being driven (${e.message})` : String((e && e.message) || e) };
  }
}

async function recommendSelector(type, primary) {
  return callTestEngine('recommendSelector', [type, primary]);
}

// Returns a Set of the selectors (from `sels`) that currently match ≥1 element on
// the open page — used by the "On this page" mappings filter.
// Origin + path, ignoring hash/query — the granularity mapping capture and
// "was this the same page" comparisons both use.
function cleanPageUrl(u) {
  try { const x = new URL(u); return (x.origin + x.pathname).replace(/\/+$/, ''); }
  catch { return (u || '').split('#')[0].split('?')[0].replace(/\/+$/, ''); }
}

// A mapping belongs to "this page" if, in this order:
//   1. its selector matches something VISIBLE right now, or
//   2. its selector matches something IN THE DOM right now, even if hidden —
//      a closed dropdown, a dialog waiting behind its trigger, a cookie
//      banner already dismissed. These are in the page on every load; they
//      just aren't visible until opened. A site-wide header widget (the
//      sign-in dropdown, the language switcher) is exactly this shape on
//      EVERY page of the site, which is why the URL test below alone was not
//      enough: captured once on the homepage, it read as "elsewhere" from any
//      other page even though it's right there in the header, or
//   3. it was captured on this exact URL (a widget rendered into the DOM only
//      while open, which the DOM test can't see while shut).
// `present` is what selectorsPresentOnPage returned: `{ visible, exists }`
// Sets, or null meaning "couldn't check" — treated as "don't rule it out".
function mappingOnPage(m, present, hereUrl) {
  if (!m || typeof m !== 'object') return true;
  const p = m.primary || m.firstArg || '';
  if (present && p && present.visible.has(p)) return true;       // visible right now
  if (present && p && present.exists.has(p)) return true;        // in the DOM, just not showing
  if (m.pageUrl && hereUrl && cleanPageUrl(m.pageUrl) === hereUrl) return true; // captured here
  return present ? false : true;                                  // couldn't check → don't hide
}

async function selectorsPresentOnPage(sels) {
  const tab = await getTab();
  if (!isInjectable(tab)) return null; // null = can't tell (don't filter)
  try {
    const res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      // Two answers per selector, in one round trip. `visible` is what it
      // always was — matches AND is actually showing (not display:none, not a
      // zero box, not opacity 0); header/menu duplicates, mobile variants and
      // leftover nodes are often hidden, and counting those made mappings
      // wrongly read as "on this page" after navigating. `exists` is the
      // looser question — is it in the DOM at all — which is what a closed
      // dropdown, a dialog behind its trigger or a dismissed banner answers
      // yes to on every page load. mappingOnPage ranks them.
      func: (list) => {
        const visible = [], exists = [];
        for (const s of list) {
          try {
            const el = document.querySelector(s);
            if (!el) continue;
            exists.push(s);
            if (!el.getBoundingClientRect) continue;
            const r = el.getBoundingClientRect();
            if (r.width < 1 || r.height < 1) continue;
            const cs = getComputedStyle(el);
            if (cs.visibility === 'hidden' || cs.display === 'none' || +cs.opacity === 0) continue;
            if (el.offsetParent === null && cs.position !== 'fixed') continue;
            visible.push(s);
          } catch {}
        }
        return { visible, exists };
      },
      args: [sels],
    });
    const out = (res && res[0] && res[0].result) || { visible: [], exists: [] };
    return { visible: new Set(out.visible || []), exists: new Set(out.exists || []) };
  } catch { return null; }
}

async function validateMapping(type, primary, fieldValues, rootValues) {
  const schema = COMPONENT_SCHEMAS[type];
  if (!schema) return [];
  const pKey = primaryKeyOf(schema);
  const req = schema.req || [];
  const notes = [];

  // Build key → selector map (primary + non-empty fields).
  const map = {};
  if (pKey) map[pKey] = primary;
  for (const f of schema.fields) if (fieldValues[f]) map[f] = fieldValues[f];

  // Required-field presence (no page needed).
  for (const r of req) {
    // aria-label: a typed name stands in for the heading it would otherwise borrow.
    if (r === 'headingSelector' && rootValues && String(rootValues.label || '').trim()) continue;
    const val = (r === pKey) ? primary
      : (fieldValues[r] != null && fieldValues[r] !== '') ? fieldValues[r]
      : (rootValues ? rootValues[r] : undefined);   // a required ROOT field (aria-label's heading)
    if (!val || !String(val).trim()) notes.push({ level: 'err', msg: `Required field “${labels[r] || r}” is empty.` });
  }

  // A name our own tooling writes cannot appear in a mapping.
  //
  // `u1-anchor-<token>-<n>` is stamped by the Studio when a skip link targets an
  // element by CSS selector rather than by id — background.js writes it on every
  // page load, and the token is re-randomised whenever the skip links are saved.
  // `u1st-*` is the U1 library's own. Neither is in the site's HTML, so a mapping
  // built on one depends on other tooling having run first and on a token that
  // changes under it. Generation refuses them now, but a pasted selector, an
  // edit, or a model's answer can still carry one — and it looks like the best
  // answer available.
  for (const [k, v] of Object.entries(map)) {
    const parts = String(v).match(/[#.][\w-]+/g) || [];
    const bad = parts.filter((t) => /^[#.]u1(st)?-/i.test(t));
    if (bad.length) {
      const ours = bad.some((t) => /^[#.]u1-anchor-/i.test(t));
      notes.push({ level: 'err', msg:
        `“${k}” uses ${bad.join(', ')}, which is not in the site's HTML — ` +
        (ours
          ? `the Studio writes that id onto the element at runtime because a skip ` +
            `link points at it, and the random part changes every time the skip ` +
            `links are saved. The skip link is fine and should stay — one element ` +
            `can be a skip target and a mapped component at once. It is only the ` +
            `id that must not be used here.`
          : `the U1 library adds it while it runs.`) +
        ` Use the element's own class or id instead.` });
    }
  }

  // Descendant-space check (U1 rejects spaces; only > + ~ combinators allowed).
  // Custom mappings (aria-label) run our own querySelector — descendant spaces
  // are fine there, so skip this warning.
  if (!schema.custom) {
    for (const [k, v] of Object.entries(map)) {
      if (/[\w\]\)]\s+[.#\[\w]/.test(v)) {
        notes.push({ level: 'warn', msg: `“${k}” has a descendant space — U1 only allows > + ~ combinators, so it may be rejected.` });
      }
    }
  }

  // options/items pointing at the container itself.
  if (type === 'listbox' && fieldValues.options && fieldValues.options === primary) {
    notes.push({ level: 'warn', msg: `“options” points at the container itself. Use the individual items, e.g. ${primary}>li.` });
  }
  // Radio without uncheckedState: U1 skips aria-checked entirely (it guards with
  // `checkedState && uncheckedState`), so the group is operable but its selected
  // option is never announced. Allowed, but the user must know.
  if (type === 'radio' && fieldValues.checkedState && !fieldValues.uncheckedState) {
    notes.push({ level: 'warn', msg: 'No “uncheckedState”: roles + arrow-key navigation will work, but U1 will not maintain aria-checked — a screen reader won’t announce which option is selected (WCAG 4.1.2).' });
  }
  // menubar:true together with submenus makes U1 throw "Submenu must have a
  // trigger element" and abort tagging entirely — the mapping reports as
  // applied and the DOM gains no roles at all. This is the single most costly
  // config mistake in the tool, so it is an error, not a warning.
  if (type === 'menu' && fieldValues.submenus && rootValues && rootValues.menubar === true) {
    notes.push({ level: 'err', msg: 'menubar is on AND “submenus” is set. U1 throws “Submenu must have a trigger element” for that combination and stops adding roles altogether — the mapping will look applied and do nothing. Turn menubar off for a navigation menu with drop-downs.' });
  }
  if (type === 'menu' && fieldValues.items && fieldValues.items === primary) {
    notes.push({ level: 'warn', msg: `“items” points at the container itself. Use the individual items, e.g. ${primary}>li>a.` });
  }

  // Page checks: match counts + listbox-options-are-links.
  const tab = await getTab();
  if (isInjectable(tab)) {
    try {
      const res = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: (pairs, t, rules, fatalIfWide) => {
          const out = { counts: {}, optionsAreLinks: false, structure: [] };
          for (const [k, sel] of pairs) {
            try { out.counts[k] = document.querySelectorAll(sel).length; }
            catch { out.counts[k] = -1; }
          }

          // Do the fields describe the SHAPE the component actually has?
          //
          // Counting matches says every field found something; it cannot say
          // they found the right things. A listbox mapped with the trigger
          // button as its `listbox` passes every count check and is nonsense:
          // the listbox has to be the thing that OPENS, and the options have to
          // be inside it. That mapping was generated, previewed, approved and
          // saved without one step objecting.
          const one = (sel) => { try { return document.querySelector(sel); } catch { return null; } };
          const all = (sel) => { try { return Array.prototype.slice.call(document.querySelectorAll(sel)); } catch { return []; } };
          const get = (k) => (pairs.find((pp) => pp[0] === k) || [])[1];

          for (const rule of rules) {
            const pSel = get(rule.parent), cSel = get(rule.child);
            if (!pSel || !cSel) continue;
            const parent = one(pSel), kids = all(cSel);
            if (!parent || !kids.length) continue;   // absence is the counts' job

            if (rule.inside) {
              const outside = kids.filter((el) => !parent.contains(el) || el === parent);
              if (outside.length === kids.length) {
                out.structure.push({ level: 'err', parent: rule.parent, child: rule.child, kind: 'none-inside' });
              } else if (outside.length) {
                out.structure.push({ level: 'warn', parent: rule.parent, child: rule.child,
                                     kind: 'some-outside', n: outside.length, total: kids.length,
                                     fatal: fatalIfWide.indexOf(t) >= 0 });
              }
            } else {
              // The reverse: these must NOT be nested, e.g. a tab panel living
              // inside the tab strip, or a trigger inside the thing it opens.
              const inside = kids.filter((el) => parent.contains(el));
              if (inside.length) {
                out.structure.push({ level: 'err', parent: rule.parent, child: rule.child, kind: 'wrongly-inside' });
              }
            }
          }
          if (t === 'listbox') {
            const opt = pairs.find(pp => pp[0] === 'options');
            if (opt) {
              try {
                const els = document.querySelectorAll(opt[1]);
                out.optionsAreLinks = els.length > 0 &&
                  Array.from(els).every(e => e.matches('a[href]') || e.querySelector('a[href]'));
              } catch {}
            }
          }
          return out;
        },
        args: [Object.entries(map), type, STRUCTURE_RULES[type] || [], FATAL_IF_WIDE],
      });
      const r = res?.[0]?.result;
      if (r) {
        // Components built ONLY when the widget opens: only the always-present
        // key (the trigger) must match now — see DYNAMIC_OPEN at module scope.
        const alwaysPresent = DYNAMIC_OPEN[type];
        for (const [k, c] of Object.entries(r.counts)) {
          if (c === -1) { notes.push({ level: 'err', msg: `“${k}” is not a valid CSS selector.` }); continue; }
          if (c !== 0) continue;
          if (alwaysPresent && !alwaysPresent.includes(k)) {
            notes.push({ level: 'ok', msg: `“${k}” matches 0 now — that’s fine for a ${type}: it’s created only when the widget opens. Open it, then click 🔍 to verify this selector.` });
          } else {
            notes.push({ level: 'warn', msg: `“${k}” matches 0 elements on the page right now.` });
          }
        }
        for (const f of r.structure || []) {
          if (f.kind === 'none-inside') {
            notes.push({ level: 'err', msg:
              `None of the elements “${f.child}” matches are inside “${f.parent}”. ` +
              `U1 looks for them within it, so this mapping will apply and do nothing. ` +
              (f.parent === 'listbox'
                ? `The listbox is the list that OPENS, not the control that opens it — ` +
                  `point it at the panel and put the button in “trigger”.`
                : `Check which element is really the container.`) });
          } else if (f.kind === 'some-outside') {
            // "U1 will only decorate the ones inside it" was true for most
            // types and flatly wrong for the one that matters. For a type the
            // patch wraps with a context resolver, a child selector reaching
            // outside its parent makes the resolver refuse the whole component:
            // u1.fix.* is never called and NOTHING is decorated. Saying
            // "partial" there sent people to check selectors that were fine.
            notes.push({ level: f.fatal ? 'err' : 'warn', msg:
              `${f.n} of the ${f.total} elements “${f.child}” matches are outside “${f.parent}”. ` +
              (f.fatal
                ? `For ${f.parent === 'tabList' ? 'a tab strip' : 'this component'} that is fatal, not partial: ` +
                  `the parts can no longer be reached together, so u1.fix.* is not run at all. ` +
                  `Saving narrows “${f.child}” to the ones inside “${f.parent}” automatically.`
                : `U1 will only decorate the ones inside it.`) });
          } else if (f.kind === 'wrongly-inside') {
            notes.push({ level: 'err', msg:
              `“${f.child}” is inside “${f.parent}”, and it must not be. ` +
              (f.parent === 'tabList'
                ? `A tab panel sits outside the tab strip — pointing both at the same ` +
                  `element makes U1 hide the tabs along with the content.`
                : `Check which is the container and which is the part.`) });
          }
        }
        // Note: listbox options that are links are fine — U1 still closes the
        // listbox on ESC. (No menu recommendation here; menu needs submenu
        // triggers and throws on a plain button+list dropdown.)
      }
    } catch {}
  }
  return notes;
}

function renderAdvisorNotes(notes) {
  const box = document.getElementById('advisorBox');
  if (!box) return;
  if (!notes || !notes.length) { box.style.display = 'none'; box.innerHTML = ''; return; }
  box.style.display = 'block';
  box.innerHTML = notes.map(n => {
    const lvl = n.level === 'err' ? 'err' : n.level === 'warn' ? 'warn' : 'ok';
    const icon = lvl === 'err' ? '⛔' : lvl === 'warn' ? '⚠️' : '✅';
    return `<div class="advisor-note ${lvl}">${icon} ${escapeHtml(n.msg)}</div>`;
  }).join('');
}

// Read the current builder form (type + primary + sub-selectors + options) and
// return a fresh template, or null if type/primary are missing. Shared by
// "Generate Template" and "Add to Mapping" so Add never silently no-ops on a
// stale/absent Generate.
function buildTemplateFromForm() {
  const type = $componentType.value;
  const primary = $primarySelectorInput.value.trim();
  if (!type || !primary) return null;

  const fieldValues = {};
  $subSelArea.querySelectorAll('input[type="text"][data-field]').forEach(inp => {
    fieldValues[inp.dataset.field] = inp.value.trim();
  });
  const rootValues = {};
  $subSelArea.querySelectorAll('[data-root]').forEach(inp => {
    if (inp.type === 'checkbox') rootValues[inp.dataset.root] = inp.checked;
    else rootValues[inp.dataset.root] = inp.value.trim();
  });
  return buildTemplate(type, primary, fieldValues, rootValues);
}

document.getElementById('generateBtn').addEventListener('click', async () => {
  const type = $componentType.value;
  const status = document.getElementById('applyStatus');
  if (!type) { showNotice(status, 'Pick a component type first.', 'error', 3000); return; }
  const primary = $primarySelectorInput.value.trim();
  if (!primary) {
    showNotice(status, 'Enter a CSS selector for the element first.', 'error', 3000);
    return;
  }

  const fieldValues = {};
  $subSelArea.querySelectorAll('input[type="text"][data-field]').forEach(inp => {
    fieldValues[inp.dataset.field] = inp.value.trim();
  });

  currentTemplate = buildTemplateFromForm();
  if (!currentTemplate) return;
  $templatePreview.textContent = currentTemplate.code;
  $previewSection.style.display = 'block';

  // Non-blocking advice: surface any problems with the mapping + selector
  // recommendation (is the primary selector the best element for this type?).
  try {
    // currentTemplate.config carries the resolved root options (menubar etc.),
    // which is where the fatal menubar+submenus combination lives.
    const notes = await validateMapping(type, primary, fieldValues, currentTemplate.config || {});
    const rec = await recommendSelector(type, currentTemplate.firstArg || primary);
    if (rec && Array.isArray(rec.notes)) {
      for (const n of rec.notes) {
        notes.push({ level: n.level, msg: n.msg + (n.suggestion ? ` → try: ${n.suggestion}` : '') });
      }
    }
    renderAdvisorNotes(notes);
  } catch {}
});

/**
 * Ask before writing our role over one the site's own markup already carries.
 *
 * Molina's dropdown ships `<ul class="signin-dropdown" role="menu">`. Mapped as
 * a listbox, u1 was asked to write `role="listbox"` over the author's role: the
 * trigger got decorated, the list did not, and nothing anywhere said why. Two
 * statements about what an element is, and one of them silently lost.
 *
 * Three answers, because there genuinely are three: the site is wrong, the site
 * is right, or you want to look first. Nothing is saved until one is chosen.
 *
 * Resolves true to carry on saving, false to abandon it.
 */
async function confirmRoleOverwrite(tpl) {
  const dlg = document.getElementById('roleClashDialog');
  if (!dlg || !tpl || !tpl.type || !tpl.primary) return true;
  // Already answered — on the component card, before the mapping was built.
  // Re-reading the DOM would find the same role and ask the same question a
  // second time, which teaches people to click through it without reading.
  if (tpl.overwriteRole) return true;

  const tab = await getTab();
  if (!isInjectable(tab)) return true;

  let clash = null;
  try {
    clash = await inPage(tab.id,
      (sel, type) => window.__u1SelectorIntel.authoredRoleConflict(sel, type),
      [tpl.primary, tpl.type]);
  } catch { return true; }   // cannot read the page — not a reason to block a save
  if (!clash) return true;

  // Owner decision (2026-09-02): "when a role needs overwriting, just do it."
  // This used to open a dialog with one right answer, and in an unattended
  // run the question was addressed to nobody — components died on it. The
  // decision is still RECORDED, twice: overwriteRole on the mapping (apply
  // and export lift the author's attribute before u1.fix runs — the only
  // thing that makes the word true), and a note a person can read on the row.
  tpl.overwriteRole = clash.role;
  tpl.note = (tpl.note ? tpl.note + ' · ' : '') +
    `the site's own HTML carried role="${clash.role}" here — overwritten automatically`;
  try {
    sweepLog(0, `${tpl.type} ${tpl.primary}: the site's markup carries role="${clash.role}" — overwriting it`, 'info');
  } catch {}
  return true;
}

// Loads an existing mapping back into the builder for editing. "Add to Mapping"
// will then replace the original (tracked via editingMappingKey).
function loadMappingIntoForm(m) {
  if (!m || typeof m !== 'object' || !m.type || !COMPONENT_SCHEMAS[m.type]) return;
  // Editing IS the manual builder, and the AI routes hide it — the container
  // field lives inside #manualOnly. Open a sweep result in the builder without
  // this and the form fills correctly behind a hidden panel: every sub-selector
  // on screen and no element selector anywhere, which reads as the tool having
  // lost it.
  if (mapMode !== 'manual') setMapMode('manual');
  $primarySelectorInput.value = m.primary || '';
  $componentType.value = m.type;
  renderTypeGuide(m.type);
  renderSubSelectorInputs(m.type);

  const schema = COMPONENT_SCHEMAS[m.type];
  const selectors = (m.config && m.config.selectors) || {};
  for (const f of schema.fields) {
    const val = getDeep(selectors, f);
    const inp = $subSelArea.querySelector('input[data-field="' + f + '"]');
    if (inp && typeof val === 'string') inp.value = val;
  }
  if (schema.rootFields) {
    for (const k of Object.keys(schema.rootFields)) {
      const inp = $subSelArea.querySelector('[data-root="' + k + '"]');
      if (!inp) continue;
      if (inp.type === 'checkbox') { inp.checked = !!(m.config && m.config[k]); continue; }
      const saved = (m.config && m.config[k] != null) ? String(m.config[k]) : '';
      // A <select> given a value it has no option for goes blank, which reads as
      // "nothing chosen" for a field that always has a value. Fall back to the
      // schema default — what a mapping saved before this field existed meant.
      if (inp.tagName === 'SELECT' && !Array.from(inp.options).some(o => o.value === saved)) {
        inp.value = String(schema.rootFields[k] || '');
      } else {
        inp.value = saved;
      }
    }
  }

  // Build preview + currentTemplate from the filled inputs, mark edit mode.
  refreshStrength();
  document.getElementById('generateBtn').click();
  editingMappingKey = mappingKey(m);
  const addBtn = document.getElementById('addMappingBtn');
  if (addBtn) addBtn.textContent = 'Update Mapping';

  // Bring the builder into view and switch to the Templates tab.
  document.querySelector('.tab-btn[data-tab="picker"]').click();
  // Editing happens in the Scan pane; the row that was pressed is in Mappings.
  if (typeof setPickerPane === 'function') setPickerPane('scan');
  $primarySelectorInput.scrollIntoView({ block: 'start', behavior: 'smooth' });
}

// Clears the builder so the user can start a fresh element.
function resetPicker() {
  $primarySelectorInput.value = '';
  $primarySelectorInput.placeholder = 'e.g. #login-modal';
  $componentType.value = '';
  renderTypeGuide('');
  $subSelArea.innerHTML = '';
  $subSelSection.style.display = 'none';
  $previewSection.style.display = 'none';
  $templatePreview.textContent = '';
  const primaryLabel = document.getElementById('primaryLabel');
  if (primaryLabel) primaryLabel.textContent = 'CSS Selector';
  const primaryHint = document.getElementById('primaryHint');
  if (primaryHint) { primaryHint.textContent = ''; primaryHint.style.display = 'none'; }
  const advisorBox = document.getElementById('advisorBox');
  if (advisorBox) { advisorBox.innerHTML = ''; advisorBox.style.display = 'none'; }
  currentTemplate = null;
  editingMappingKey = null;
  const addBtn = document.getElementById('addMappingBtn');
  if (addBtn) addBtn.textContent = 'Add to Mapping';
  const testBox = document.getElementById('selectorTestResult');
  if (testBox) { testBox.style.display = 'none'; testBox.innerHTML = ''; }
  const applyStatus = document.getElementById('applyStatus');
  if (applyStatus) applyStatus.style.display = 'none';
  const primaryBadge = $primarySelectorInput.parentElement?.querySelector('.sel-strength');
  if (primaryBadge) paintStrength(primaryBadge, { level: 'empty', label: '', reasons: [] });
  $primarySelectorInput.focus();
}

document.getElementById('resetPickerBtn').addEventListener('click', resetPicker);

// ─────────────────────────────────────────────────────────────────────────────
//  TAB — SCAN (static content audit: headings, descriptions, alts, labels…)
// ─────────────────────────────────────────────────────────────────────────────

let scanEnginesRan = [];   // which third-party engines actually answered
let scanResults = [];      // enriched findings [{ruleId, cat, severity, wcag, why, fix, issue, text, selector, detail}]
let scanInventory = null;  // what the page holds — the evidence beside each checklist row
let scanView = 'checklist'; // 'checklist' | 'all' — how the findings are shown
let scanActiveCat = '*';   // current category filter
let scanActiveSev = '*';   // current severity filter

// ── Rules catalog (auto-detectable subset of the WCAG issue catalog) ─────────
// Each finding the scanner emits references a ruleId here; the panel enriches it
// with the client-friendly title/explanation/fix + WCAG + severity + category.
const SEVERITY_ORDER = { Critical: 0, High: 1, Medium: 2, Low: 3 };
const SCAN_RULES = {
  'title-missing':        { title: 'Missing or unclear page title', wcag: '2.4.2', severity: 'High', category: 'Page Title', why: 'The browser tab title is missing or does not describe the page.', fix: 'Set a unique, clear page title for each page.' },
  'lang-missing':         { title: 'Missing page language', wcag: '3.1.1', severity: 'High', category: 'Screen Reader Support', why: 'Screen readers use the wrong pronunciation.', fix: 'Set the correct language on <html lang="…">.' },
  'h1-missing':           { title: 'Missing level 1 heading (H1)', wcag: '1.3.1', severity: 'High', category: 'Headings', why: 'The page lacks a main H1, making it hard to understand the primary topic and structure.', fix: 'Add a single descriptive <h1> at the top of the main content.' },
  'h1-multiple':          { title: 'Multiple H1', wcag: '1.3.1', severity: 'Medium', category: 'Headings', why: 'More than one H1 on the page.', fix: 'A web page should have only one H1.' },
  'heading-skip':         { title: 'Heading levels are skipped', wcag: '1.3.1', severity: 'Medium', category: 'Headings', why: 'Headings jump levels (e.g. H1 then H3), which confuses navigation.', fix: 'Use a logical order: H1 → H2 → H3 (avoid jumps).' },
  'heading-empty':        { title: 'Empty heading', wcag: '1.3.1', severity: 'Medium', category: 'Headings', why: 'A heading element has no text.', fix: 'Add text, or remove the heading tag.' },
  'landmarks-missing':    { title: 'No landmarks for main areas', wcag: '1.3.1', severity: 'High', category: 'Page Navigation', why: 'Screen reader users cannot jump quickly to main sections.', fix: 'Use <header>, <nav>, <main>, <footer> or ARIA landmarks.' },
  'skip-link-missing':    { title: 'No skip link', wcag: '2.4.1', severity: 'High', category: 'skip link', why: 'Keyboard users must tab through the whole menu on every page.', fix: "Add a 'Skip to main content' link at the top (visible on focus)." },
  'img-alt-missing':      { title: 'Image missing alt text', wcag: '1.1.1', severity: 'High', category: 'Images', why: 'Screen reader users do not know what the image shows.', fix: "Add meaningful alt text, or alt='' if decorative." },
  'link-empty':           { title: 'Link has no accessible text', wcag: '2.4.4', severity: 'Critical', category: 'Link and Button Labels', why: 'Screen reader users hear a link with no meaning.', fix: 'Add visible text or an aria-label that describes the destination.' },
  'link-generic':         { title: 'Link text is vague', wcag: '2.4.4', severity: 'High', category: 'Link and Button Labels', why: 'Users cannot tell where a link goes.', fix: "Use descriptive link text (avoid 'Click here')." },
  'button-noname':        { title: 'Button has no accessible name', wcag: '4.1.2', severity: 'High', category: 'Link and Button Labels', why: 'Icon-only or empty buttons are not announced clearly.', fix: 'Add visible text or an aria-label / screen-reader-only text.' },
  'input-nolabel':        { title: 'Input has no label', wcag: '3.3.2', severity: 'High', category: 'Form Labels and Instructions', why: 'Users do not know what to enter.', fix: 'Add a visible label linked to the input (label/for/id).' },
  'input-placeholder':    { title: 'Placeholder used as label', wcag: '3.3.2', severity: 'Medium', category: 'Form Labels and Instructions', why: 'The label disappears when typing.', fix: 'Use a real label; keep the placeholder for examples only.' },
  'group-nolabel':        { title: 'Option group has no group label', wcag: '1.3.1', severity: 'Medium', category: 'Form Labels and Instructions', why: 'Radio/checkbox groups are unclear without a group label.', fix: 'Use fieldset/legend or aria-labelledby for the group.' },
  'iframe-notitle':       { title: 'Iframe has no title', wcag: '4.1.2', severity: 'Medium', category: 'Iframes', why: 'Screen reader users cannot identify embedded content.', fix: "Add a clear iframe title (e.g. title='Payment form')." },
  'table-noheaders':      { title: 'Data table missing headers', wcag: '1.3.1', severity: 'High', category: 'Tables', why: 'Screen reader users cannot understand rows/columns.', fix: 'Use <th> header cells and set scope correctly.' },
  'tabindex-positive':    { title: 'Positive tabindex breaks focus order', wcag: '2.4.3', severity: 'High', category: 'Reading and Focus Order', why: 'A positive tabindex makes keyboard focus jump in a confusing order.', fix: 'Match the HTML order to the visual order; avoid positive tabindex.' },
  'aria-hidden-focusable':{ title: 'Keyboard-focusable but hidden from screen readers', wcag: '4.1.2', severity: 'Medium', category: 'Focus access', why: 'Element receives Tab focus but is ignored by screen readers (aria-hidden).', fix: "Remove aria-hidden='true', or add tabindex='-1' to take it out of the tab order." },
  'dup-ids':              { title: 'Duplicate id (note for the developers)', wcag: '4.1.1', severity: 'Low', note: true, category: 'Screen Reader Support', why: 'Not an accessibility failure on its own — nobody is blocked by it. It becomes one only when a label, aria-labelledby or aria-controls points at the id, because then the browser picks the first element and the reference can land on the wrong one.', fix: 'A note for the developers: give each element its own id. Nothing to map.' },
  'zoom-disabled':        { title: 'Zoom is disabled', wcag: '1.4.4', severity: 'High', category: 'Text Resize and Magnification', why: 'Users cannot enlarge content enough to read.', fix: 'Do not disable zoom; avoid user-scalable=no / maximum-scale.' },
  'autoplay-audio':       { title: 'Autoplay media cannot be stopped', wcag: '1.4.2', severity: 'High', category: 'Media Animation Motion', why: 'Autoplay audio interrupts users and screen readers.', fix: 'Do not autoplay, or provide pause/stop/mute controls.' },
  'carousel-nopause':     { title: 'Auto-advancing carousel has no pause control', wcag: '2.2.2', severity: 'High', category: 'Media Animation Motion', why: 'Content that moves, updates, or auto-advances for more than five seconds must be pausable — this carousel changes slides on its own with no way to stop it.', fix: 'Add a visible pause/stop control placed and styled to match the rest of the page — not something to auto-generate; where it belongs is a design decision for this specific site.' },
  'video-nocaptions':     { title: 'Video has no captions', wcag: '1.2.2', severity: 'High', category: 'Media Animation Motion', why: 'Users who cannot hear the audio miss the content.', fix: 'Add a captions track (<track kind="captions">).' },
  'switch-nostate':       { title: 'Switch has no state', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'Users cannot tell if a role="switch" is On or Off.', fix: 'Add aria-checked="true/false" to the switch.' },
  'checkbox-nostate':     { title: 'Custom checkbox has no state', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'Users cannot perceive selected / unselected / mixed.', fix: 'Add aria-checked="true/false/mixed" to role="checkbox".' },
  'slider-novalue':       { title: 'Slider has no value', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'The current value of a role="slider" is not announced.', fix: 'Add aria-valuenow / aria-valuemin / aria-valuemax.' },
  'meter-novalue':        { title: 'Meter / progressbar has no value', wcag: '1.1.1', severity: 'Medium', category: 'Semantic Mapping', why: 'A visual gauge’s value is not announced.', fix: 'Add aria-valuenow / aria-valuemin / aria-valuemax.' },
  'combobox-noexpanded':  { title: 'Combobox missing aria-expanded', wcag: '4.1.2', severity: 'Critical', category: 'Semantic Mapping', why: 'User is unaware a suggestions list has appeared.', fix: 'Add role="combobox" with aria-expanded and aria-controls.' },
  'misleading-role':      { title: 'Interactive role but not keyboard-focusable', wcag: '4.1.2', severity: 'Critical', category: 'Focus access', why: 'Element is announced as clickable but cannot receive keyboard focus.', fix: 'Use a native <button>/<a>, or add tabindex="0"; otherwise remove the role.' },
  'clickable-div':        { title: 'Clickable element not identified as interactive', wcag: '4.1.2', severity: 'High', category: 'Screen Reader Support', why: 'A div/span with a click handler lacks an interactive role, so it is not announced as activatable.', fix: 'Use <button>/<a>, or add role="button" and tabindex="0".' },
  'aria-ref-broken':      { title: 'ARIA reference points to a missing id', wcag: '1.3.1', severity: 'Medium', category: 'Screen Reader Support', why: 'aria-labelledby / describedby / controls references an element that does not exist.', fix: 'Point the reference at a real element id.' },
  'target-size-small':    { title: 'Touch target too small', wcag: '2.5.8', severity: 'Medium', category: 'Custom Components', why: 'Users miss taps and hit the wrong item.', fix: 'Increase target size (~24px) or add spacing around targets.' },

  // ── Static checks the removed IBM engine used to make, in our words ──────
  'img-alt-filename':     { title: 'Alt text is just the file name', wcag: '1.1.1', severity: 'Medium', category: 'Images', why: 'A screen reader will read “Career_HealthNews” or “banner.png” aloud — the file name says nothing about what the picture shows or why it is there.', fix: 'Write what the picture is FOR in a few words, or alt="" if it is decoration.' },
  'label-for-broken':     { title: 'Label points at a field that does not exist', wcag: '1.3.1', severity: 'High', category: 'Forms and Inputs', why: 'The <label for="…"> names an id no field has, so the field it sits next to is announced with no label at all.', fix: 'Make the label\'s for="" match the field\'s id.' },
  'link-newwindow':       { title: 'Link opens a new tab without saying so', wcag: '3.2.5', severity: 'Low', category: 'Link and Button Labels', why: 'target="_blank" moves the user to a new tab with no warning; screen reader users lose their place and the Back button stops working.', fix: 'Say it in the name — “Careers (opens in a new tab)” — with an aria-label mapping, or drop the target.' },
  'media-nocontrols':     { title: 'Video or audio has no controls', wcag: '2.1.1', severity: 'Medium', category: 'Media Animation Motion', why: 'Without the controls attribute or a custom control bar there is no keyboard way to play, pause or change the volume.', fix: 'Add the controls attribute, or make sure the custom controls are real buttons.' },
  'title-weak':           { title: 'Page title looks like a file name', wcag: '2.4.2', severity: 'Low', category: 'Page Structure', why: 'The tab title is a file name, a URL or “Untitled” — it does not tell a user which page they are on.', fix: 'Set a <title> that names the page and the site: “Members – Molina Healthcare”.' },
  'list-stray-br':        { title: 'Line break or spacer sitting directly inside a list', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: 'A <br> or an empty spacer between the items is counted as one — the screen reader says “list, 7 items” for 5 links.', fix: 'Hide the stray nodes from screen readers (aria-hidden="true"). The list stays exactly as it looks.' },
  'list-structure':       { title: 'List holds things that are not list items', wcag: '1.3.1', severity: 'Medium', category: 'Page Structure', why: 'A <ul>/<ol> contains elements other than <li> and carries no roles of its own, so the count and the items a screen reader announces are wrong.', fix: 'Put only <li> directly inside the list, or map it as the component it really is (a menu, a tab strip) so it gets the right roles.' },
  'landmark-noname':      { title: 'Several form/region landmarks with no name (note)', wcag: '1.3.1', severity: 'Low', note: true, category: 'Page Structure', why: 'Not a failure: an unnamed role="form" or role="region" is simply not listed as a landmark, and one of them costs nobody anything. Two or more without names is the case worth a note — a screen reader\'s landmark list then reads “form, form”, and the person cannot tell which is which. A form that is a U1 mapping is already the treatment and is not counted here.', fix: 'Optional: give each a name (“Search”, “Newsletter”) — Fix all takes it from the field\'s own label or the heading inside.' },
};

// ── Equivalent findings across engines ───────────────────────────────────────
//
// axe and our own rules both flag a missing lang attribute, and they call it
// html-has-lang and lang-missing. Shown as two rows that is one fault reported
// twice, and the list stops being countable — which is what a client is
// actually doing with it.
//
// So known equivalents collapse onto a shared concept. A hand-kept table rather
// than fuzzy text matching, because a wrong merge HIDES a finding: two genuinely
// different faults on one element would become one, and the one that disappears
// is the one nobody knows to look for. Anything not in the table keeps its own
// identity, which is the safe direction to be wrong in.
//
// Our own rules map here; axe's map through AXE_RULES below (`as` names the
// hand-written rule an axe rule IS, `concept` names the question it answers).
const SCAN_CONCEPTS = {
  'list-stray-br': 'list-structure',
  'lang-missing': 'lang',
  'title-missing': 'doc-title', 'title-weak': 'doc-title',
  'img-alt-missing': 'img-alt',
  'button-noname': 'button-name',
  'link-empty': 'link-name',
  'input-nolabel': 'input-label',
  'dup-ids': 'dup-id',
  'heading-skip': 'heading-order',
  'heading-empty': 'heading-empty',
  'iframe-notitle': 'frame-title',
  'zoom-disabled': 'zoom',
  'landmarks-missing': 'landmarks',
  'skip-link-missing': 'skip-link',
  'table-noheaders': 'table-headers',
  'tabindex-positive': 'tabindex',
};

// ── Every axe rule, in our words ─────────────────────────────────────────────
//
// axe runs under the hood (scan-engines.js) because colour contrast and the
// ARIA grammar need a rendered page and a mature algorithm nobody should
// rewrite. What the reader sees is never axe's message: each rule is either
// the SAME fault a hand-written rule already describes (`as`), or gets its own
// plain title / why / fix here, and is filed under a checklist question via
// its `concept`. A rule missing from this table would surface with axe's own
// wording under "Other findings" — verify-scan-engines.mjs fails the build on
// that, so the table stays complete as axe versions move.
//
// Severity is ours, not axe's impact: axe calls a missing <h1> "moderate" and a
// wrong ARIA attribute "critical", which is the grammar's view, not the user's.
const AXE_RULES = {
  // ── The same faults our rules find ────────────────────────────────────────
  'document-title': { as: 'title-missing' },
  'html-has-lang': { as: 'lang-missing' },
  'image-alt': { as: 'img-alt-missing' }, 'input-image-alt': { as: 'img-alt-missing' },
  'button-name': { as: 'button-noname' }, 'input-button-name': { as: 'button-noname' },
  'link-name': { as: 'link-empty' },
  'label': { as: 'input-nolabel' },
  'duplicate-id': { as: 'dup-ids' }, 'duplicate-id-active': { as: 'dup-ids' }, 'duplicate-id-aria': { as: 'dup-ids' },
  'heading-order': { as: 'heading-skip' }, 'empty-heading': { as: 'heading-empty' },
  'page-has-heading-one': { as: 'h1-missing' },
  'frame-title': { as: 'iframe-notitle' },
  'meta-viewport': { as: 'zoom-disabled' },
  'region': { as: 'landmarks-missing' },
  'bypass': { as: 'skip-link-missing' },
  'th-has-data-cells': { as: 'table-noheaders' }, 'td-has-header': { as: 'table-noheaders' },
  'tabindex': { as: 'tabindex-positive' },
  'aria-hidden-focus': { as: 'aria-hidden-focusable' },
  'no-autoplay-audio': { as: 'autoplay-audio' },
  'video-caption': { as: 'video-nocaptions' },
  'target-size': { as: 'target-size-small' },
  'focus-order-semantics': { as: 'clickable-div' },
  'image-redundant-alt': { as: 'img-alt-filename' },

  // ── Colour ────────────────────────────────────────────────────────────────
  'color-contrast': { concept: 'contrast', title: 'Text is too faint against its background', wcag: '1.4.3', severity: 'High', category: 'Colour and Contrast', why: 'The text and its background are too close in colour (under 4.5:1, or 3:1 for large text). People with low vision, and anyone in sunlight, cannot read it.', fix: 'Darken the text or lighten the background until the ratio is 4.5:1 — a CSS change on the site; U1 does not restyle text.' },
  'link-in-text-block': { concept: 'link-color-only', title: 'Link in a paragraph is told apart by colour alone', wcag: '1.4.1', severity: 'Medium', category: 'Colour and Contrast', why: 'Inside running text the link differs from the words around it only by colour, so a colour-blind reader cannot see there is a link.', fix: 'Underline links inside paragraphs, or make the link colour differ from the text by at least 3:1 — a CSS change on the site.' },

  // ── Language ──────────────────────────────────────────────────────────────
  'html-lang-valid': { concept: 'lang', title: 'Page language code is not valid', wcag: '3.1.1', severity: 'High', category: 'Page Structure', why: 'The <html lang> value is not a real language code, so the screen reader falls back to its default voice.', fix: 'Use a real code: lang="en", lang="he", lang="es".' },
  'valid-lang': { concept: 'lang', title: 'A lang attribute inside the page is not valid', wcag: '3.1.2', severity: 'Medium', category: 'Page Structure', why: 'An element switches language with a code that is not real, so that passage is read in the wrong voice.', fix: 'Use a real code on the element (lang="fr"), or remove the attribute.' },
  'html-xml-lang-mismatch': { concept: 'lang', title: 'lang and xml:lang disagree', wcag: '3.1.1', severity: 'Low', category: 'Page Structure', why: 'The page declares two different languages; screen readers may pick either.', fix: 'Make lang and xml:lang the same, or drop xml:lang.' },

  // ── Headings and text structure ───────────────────────────────────────────
  'p-as-heading': { concept: 'fake-heading', title: 'Bold paragraph used as a heading', wcag: '1.3.1', severity: 'Medium', category: 'Headings', why: 'It looks like a heading but is a styled <p>, so it is missing from the heading list a screen reader user navigates by.', fix: 'Map it as a heading at the right level — the finding tells you which.' },
  'list': { concept: 'list-structure', title: 'List holds things that are not list items (axe wording, unused)', wcag: '1.3.1', severity: 'Medium', category: 'Page Structure', why: 'A <ul>/<ol> contains elements other than <li>, so the screen reader miscounts the items or announces stray content.', fix: 'Put only <li> directly inside the list; move the rest out or wrap it in an item.' },
  'listitem': { concept: 'list-structure', title: 'List item outside a list', wcag: '1.3.1', severity: 'Medium', category: 'Page Structure', why: 'An <li> is not inside a <ul>/<ol>, so it is announced with no list context and no count.', fix: 'Wrap the items in a <ul> or <ol>, or use a different element.' },
  'definition-list': { concept: 'list-structure', title: 'Definition list is not structured correctly', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: 'A <dl> must alternate terms (<dt>) and definitions (<dd>); anything else breaks how it is read.', fix: 'Keep only <dt>/<dd> pairs (optionally wrapped in <div>) inside the <dl>.' },
  'dlitem': { concept: 'list-structure', title: '<dt> or <dd> outside a <dl>', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: 'A term or definition with no list around it loses its meaning to a screen reader.', fix: 'Wrap them in a <dl>, or use ordinary elements.' },

  // ── Images ────────────────────────────────────────────────────────────────
  'role-img-alt': { concept: 'img-alt', title: 'Element marked as an image has no alt text', wcag: '1.1.1', severity: 'High', category: 'Images', why: 'role="img" tells the screen reader “this is a picture” and then gives it nothing to say.', fix: 'Add an aria-label saying what it shows, or remove the role if it is decoration.' },
  'svg-img-alt': { concept: 'img-alt', title: 'SVG icon has no name', wcag: '1.1.1', severity: 'High', category: 'Images', why: 'An inline <svg> with role="img" and no <title> or aria-label is announced as “image” with nothing more.', fix: 'Add a <title> inside the svg or an aria-label — or aria-hidden="true" if it is decoration.' },
  'object-alt': { concept: 'img-alt', title: 'Embedded object has no text alternative', wcag: '1.1.1', severity: 'Medium', category: 'Images', why: 'An <object> (PDF, Flash-era media) with no fallback text is a hole in the page for a screen reader.', fix: 'Put fallback text inside the <object>, or an aria-label on it.' },
  'area-alt': { concept: 'img-alt', title: 'Image-map area has no alt text', wcag: '2.4.4', severity: 'High', category: 'Images', why: 'Each clickable <area> of an image map is a link; without alt it is a link with no name.', fix: 'Add alt="" text naming where each area goes.' },
  'server-side-image-map': { concept: 'image-map', title: 'Server-side image map', wcag: '2.1.1', severity: 'High', category: 'Images', why: 'An <img ismap> sends click coordinates to the server — there is nothing a keyboard can activate.', fix: 'Replace it with a client-side map (<map>/<area>) or plain links.' },

  // ── Names for controls ────────────────────────────────────────────────────
  'aria-command-name': { concept: 'button-name', title: 'Custom button, link or menu item has no name', wcag: '4.1.2', severity: 'Critical', category: 'Link and Button Labels', why: 'role="button"/"link"/"menuitem" with no text, aria-label or labelled-by is announced as just “button”.', fix: 'Give it a name with an aria-label mapping, or visible text.' },
  'summary-name': { concept: 'button-name', title: 'Expandable section (<summary>) has no name', wcag: '4.1.2', severity: 'High', category: 'Link and Button Labels', why: 'The <summary> is the button that opens the <details>; empty, it is “button, collapsed” with no subject.', fix: 'Put text in the <summary>, or give it an aria-label.' },
  'aria-toggle-field-name': { concept: 'button-name', title: 'Custom checkbox, switch or radio has no name', wcag: '4.1.2', severity: 'Critical', category: 'Forms and Inputs', why: 'A role="checkbox"/"switch"/"radio" with no name is announced as “checkbox, not checked” — checkbox for what?', fix: 'Name it with an aria-label mapping or aria-labelledby.' },
  'aria-input-field-name': { concept: 'input-label', title: 'Custom text field, combobox or listbox has no name', wcag: '4.1.2', severity: 'Critical', category: 'Forms and Inputs', why: 'A role="textbox"/"combobox"/"listbox"/"spinbutton" with no name is announced with no purpose.', fix: 'Name it with an aria-label mapping or a visible label tied by aria-labelledby.' },
  'select-name': { concept: 'input-label', title: 'Dropdown (<select>) has no label', wcag: '4.1.2', severity: 'Critical', category: 'Forms and Inputs', why: 'The dropdown is announced as “combobox” with no idea what is being chosen.', fix: 'Add a <label for>, or an aria-label mapping.' },
  'form-field-multiple-labels': { concept: 'input-label', title: 'Field has more than one label', wcag: '3.3.2', severity: 'Low', category: 'Forms and Inputs', why: 'Two <label for> point at one field; screen readers read one, the other, or both joined.', fix: 'Keep one <label>; make the rest plain text or aria-describedby.' },
  'label-title-only': { concept: 'label-hidden', title: 'Field is labelled only by a tooltip', wcag: '3.3.2', severity: 'Medium', category: 'Forms and Inputs', why: 'The only name comes from title= or aria-describedby — nothing is visible, and sighted keyboard users get no label.', fix: 'Add a visible label, or at least an aria-label.' },
  'label-content-name-mismatch': { concept: 'label-mismatch', title: 'Spoken name differs from the visible text', wcag: '2.5.3', severity: 'High', category: 'Link and Button Labels', why: 'The button shows one word and its aria-label says another, so a voice-control user saying the visible word cannot activate it.', fix: 'Start the aria-label with the visible text, or remove it and let the text be the name.' },
  'autocomplete-valid': { concept: 'autocomplete', title: 'autocomplete value is not valid', wcag: '1.3.5', severity: 'Medium', category: 'Forms and Inputs', why: 'The autocomplete token is not a real one, so the browser and assistive tools cannot fill the field for the user.', fix: 'Use a real token: autocomplete="email", "given-name", "tel", "postal-code".' },

  // ── Widgets ───────────────────────────────────────────────────────────────
  'aria-meter-name': { concept: 'meter-name', title: 'Meter has no name', wcag: '1.1.1', severity: 'High', category: 'Semantic Mapping', why: 'A role="meter" announces a value with nothing saying what it measures.', fix: 'Add an aria-label naming what it measures.' },
  'aria-progressbar-name': { concept: 'meter-name', title: 'Progress bar has no name', wcag: '1.1.1', severity: 'High', category: 'Semantic Mapping', why: 'A role="progressbar" announces “50%” with nothing saying 50% of what.', fix: 'Add an aria-label naming the task.' },
  'aria-dialog-name': { concept: 'dialog-name', title: 'Dialog has no name', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'A role="dialog" opens and the screen reader says only “dialog” — the title inside it is not tied to it.', fix: 'Map it as a dialog and point it at its heading (aria-labelledby).' },
  'aria-tooltip-name': { concept: 'tooltip-name', title: 'Tooltip has no text', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'A role="tooltip" with no content is announced as nothing.', fix: 'Put the tooltip text inside it, or remove the role.' },
  'aria-treeitem-name': { concept: 'treeitem-name', title: 'Tree item has no name', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'A role="treeitem" with no text is an unnamed branch in the tree.', fix: 'Give each tree item text or an aria-label.' },

  // ── ARIA used correctly ───────────────────────────────────────────────────
  'aria-roles': { concept: 'aria-grammar', title: 'role= value is not a real role', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'The role is misspelt or invented, so the browser ignores it and the element is announced as plain.', fix: 'Use a real role (button, dialog, tablist…), or remove it.' },
  'aria-allowed-role': { concept: 'aria-grammar', title: 'Role does not fit this element', wcag: '4.1.2', severity: 'Low', category: 'Semantic Mapping', why: 'A role this element may not carry (e.g. role="button" on an <a href>, role="heading" on a <li>) confuses what is announced.', fix: 'Use an element that fits the role, or a role that fits the element.' },
  'aria-deprecated-role': { concept: 'aria-grammar', title: 'Deprecated ARIA role', wcag: '4.1.2', severity: 'Low', category: 'Semantic Mapping', why: 'The role was dropped from the ARIA spec and newer screen readers may ignore it.', fix: 'Replace it with its current equivalent.' },
  'aria-valid-attr': { concept: 'aria-grammar', title: 'aria-* attribute does not exist', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'The attribute is misspelt (aria-lable, aria-labeledby) so it does nothing — usually a name that was meant to be there is missing.', fix: 'Fix the spelling.' },
  'aria-valid-attr-value': { concept: 'aria-grammar', title: 'aria-* attribute has an invalid value', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'aria-expanded="yes", aria-controls pointing at no id, aria-live="on" — the value is not one the attribute accepts, so it is ignored.', fix: 'Use the allowed values (true/false, a real id, polite/assertive).' },
  'aria-allowed-attr': { concept: 'aria-grammar', title: 'ARIA attribute not allowed on this role', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'The attribute means nothing for this role (aria-checked on a link, aria-expanded on a heading) and is either ignored or mis-announced.', fix: 'Remove it, or change the role to one that supports it.' },
  'aria-prohibited-attr': { concept: 'aria-grammar', title: 'aria-label on an element that cannot carry a name', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'Plain <div>, <span>, <p> and the like have no role, so their aria-label is ignored by most screen readers — the name the author wanted is silently lost.', fix: 'Give the element a role that takes a name, or put the text where it is read as content.' },
  'aria-conditional-attr': { concept: 'aria-grammar', title: 'ARIA attribute used where the role forbids it', wcag: '4.1.2', severity: 'Medium', category: 'Semantic Mapping', why: 'The attribute is only valid under certain conditions for this role (e.g. aria-checked on a native checkbox) and here it conflicts with the element itself.', fix: 'Remove the attribute; the native element already conveys the state.' },
  'aria-required-attr': { concept: 'aria-grammar', title: 'Role is missing an attribute it needs', wcag: '4.1.2', severity: 'High', category: 'Semantic Mapping', why: 'Some roles are meaningless without a state: a checkbox without aria-checked, a slider without aria-valuenow, a combobox without aria-expanded.', fix: 'Add the missing attribute — mapping the element as that component does it for you.' },
  'aria-required-children': { concept: 'aria-structure', title: 'Composite role is missing its parts', wcag: '1.3.1', severity: 'High', category: 'Semantic Mapping', why: 'A tablist with no tabs, a list with no listitems, a menu with no menuitems — the screen reader announces the container and then finds nothing inside.', fix: 'Give the children the matching roles — mapping the component as tabs / menu / listbox does exactly this.' },
  'aria-required-parent': { concept: 'aria-structure', title: 'Role used outside the container it belongs in', wcag: '1.3.1', severity: 'High', category: 'Semantic Mapping', why: 'A tab outside a tablist, an option outside a listbox, a menuitem outside a menu — the role is announced but its position (“2 of 5”) is lost.', fix: 'Map the whole component, container included, rather than the item alone.' },
  'aria-roledescription': { concept: 'aria-grammar', title: 'aria-roledescription on an element with no role', wcag: '4.1.2', severity: 'Low', category: 'Semantic Mapping', why: 'A custom role description only applies when there is a role to describe; here it is ignored.', fix: 'Add a role, or remove the description.' },
  'aria-text': { concept: 'aria-grammar', title: 'role="text" hides focusable content', wcag: '4.1.2', severity: 'Medium', category: 'Semantic Mapping', why: 'role="text" flattens everything inside to plain text, so links or buttons within it stop being announced as such.', fix: 'Remove the role, or move the controls outside it.' },
  'aria-braille-equivalent': { concept: 'aria-grammar', title: 'Braille label with no spoken equivalent', wcag: '4.1.2', severity: 'Low', category: 'Semantic Mapping', why: 'aria-braillelabel is set but there is no aria-label or text for speech users.', fix: 'Add the ordinary name as well.' },
  'aria-hidden-body': { concept: 'aria-grammar', title: 'The whole page is hidden from screen readers', wcag: '4.1.2', severity: 'Critical', category: 'Screen Reader Support', why: 'aria-hidden="true" on <body> removes every element from assistive technology — the page is blank to a screen reader.', fix: 'Remove aria-hidden from <body>. Usually a modal script that forgot to undo it.' },
  'presentation-role-conflict': { concept: 'aria-grammar', title: 'Element is “presentational” but also interactive or labelled', wcag: '4.1.2', severity: 'Low', category: 'Semantic Mapping', why: 'role="none"/"presentation" says “ignore me”, while a tabindex or aria-label on the same element says the opposite; screen readers disagree on which wins.', fix: 'Pick one: remove the role, or remove the tabindex / aria attributes.' },
  'nested-interactive': { concept: 'nested-controls', title: 'Control inside a control', wcag: '4.1.2', severity: 'High', category: 'Focus access', why: 'A button inside a link, or a link inside a role="button" — screen readers announce only the outer one and keyboard focus can get stuck.', fix: 'Flatten it: one interactive element per action, side by side.' },

  // ── Keyboard reach ────────────────────────────────────────────────────────
  'scrollable-region-focusable': { concept: 'scroll-keyboard', title: 'Scrolling area cannot be reached by keyboard', wcag: '2.1.1', severity: 'High', category: 'Focus access', why: 'A box with its own scrollbar has nothing focusable inside and no tabindex, so keyboard users cannot scroll it and never see the rest of its content.', fix: 'Give the scrolling element tabindex="0" (a static fix), and a name with aria-label.' },
  'frame-focusable-content': { concept: 'frame-tabindex', title: 'Iframe with controls is taken out of the tab order', wcag: '2.1.1', severity: 'High', category: 'Focus access', why: 'tabindex="-1" on an <iframe> that contains links or fields makes everything inside unreachable by keyboard.', fix: 'Remove the tabindex from the iframe.' },
  'skip-link': { concept: 'skip-link', title: 'Skip link points at nothing', wcag: '2.4.1', severity: 'Medium', category: 'Page Structure', why: 'The “skip to content” link\'s href names an id that is not on the page, or a target that cannot take focus — pressing it goes nowhere.', fix: 'Point it at the main content\'s id, and make sure that element can take focus (tabindex="-1").' },
  'accesskeys': { concept: 'accesskey-dup', title: 'Same accesskey on more than one element', wcag: '4.1.2', severity: 'Low', category: 'Focus access', why: 'Two elements share a keyboard shortcut, so pressing it activates only one and the other can never be reached that way.', fix: 'Give each accesskey a different letter, or drop them.' },

  // ── Landmarks ─────────────────────────────────────────────────────────────
  'landmark-one-main': { concept: 'landmarks', title: 'Page has no main landmark', wcag: '1.3.1', severity: 'Medium', category: 'Page Structure', why: 'Without <main> a screen reader user cannot jump straight to the content past the header.', fix: 'Map the content area as the main landmark — Config does this.' },
  'landmark-no-duplicate-main': { concept: 'landmark-structure', title: 'More than one main landmark', wcag: '1.3.1', severity: 'Medium', category: 'Page Structure', why: 'Two <main> elements: “jump to main content” becomes a guess.', fix: 'Keep one <main>; the rest become <section> or plain <div>.' },
  'landmark-no-duplicate-banner': { concept: 'landmark-structure', title: 'More than one page header (banner) landmark', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: 'Two top-level <header>/role="banner": the landmark list shows two page headers.', fix: 'Keep one page header; give inner <header>s a section around them or no role.' },
  'landmark-no-duplicate-contentinfo': { concept: 'landmark-structure', title: 'More than one page footer (contentinfo) landmark', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: 'Two top-level <footer>/role="contentinfo": the landmark list shows two page footers.', fix: 'Keep one page footer.' },
  'landmark-main-is-top-level': { concept: 'landmark-structure', title: 'Main landmark is nested inside another landmark', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: '<main> inside <nav>, <header> or <aside> is announced as part of that region, not as the page content.', fix: 'Move <main> out so it sits directly under <body>.' },
  'landmark-banner-is-top-level': { concept: 'landmark-structure', title: 'Page header landmark is nested inside another landmark', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: 'A banner inside main or nav is not the page header any more; the landmark list gets confusing.', fix: 'Move the <header> to the top level, or remove role="banner".' },
  'landmark-contentinfo-is-top-level': { concept: 'landmark-structure', title: 'Page footer landmark is nested inside another landmark', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: 'A footer inside main is announced as part of the content, not as the page footer.', fix: 'Move the <footer> to the top level, or remove role="contentinfo".' },
  'landmark-complementary-is-top-level': { concept: 'landmark-structure', title: 'Sidebar (aside) is nested inside another landmark', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: 'An <aside> inside <main> is announced as part of the content, not as a sidebar.', fix: 'Move it out, or drop the aside for a plain <div>.' },
  'landmark-unique': { concept: 'landmark-structure', title: 'Several landmarks of the same kind with the same (or no) name', wcag: '1.3.1', severity: 'Low', category: 'Page Structure', why: 'Three <nav>s with no names are listed as “navigation, navigation, navigation” — the user cannot tell the menu from the footer links.', fix: 'Give each one an aria-label (“Main menu”, “Footer links”).' },

  // ── Iframes and tables ────────────────────────────────────────────────────
  'frame-title-unique': { concept: 'frame-title-dup', title: 'Two iframes share the same title', wcag: '4.1.2', severity: 'Low', category: 'Iframes', why: 'The frame list reads the same name twice, so the user cannot tell them apart.', fix: 'Give each iframe its own title (“Map”, “Chat”).' },
  'td-headers-attr': { concept: 'table-structure', title: 'Cell headers= points at cells that do not exist', wcag: '1.3.1', severity: 'Medium', category: 'Tables', why: 'A <td headers="…"> names ids that are not header cells in this table, so the header is not announced.', fix: 'Point headers= at the ids of real <th> cells in the same table.' },
  'scope-attr-valid': { concept: 'table-structure', title: 'Header cell scope= is wrong', wcag: '1.3.1', severity: 'Low', category: 'Tables', why: 'scope must be row/col/rowgroup/colgroup and belongs on <th>; anything else is ignored.', fix: 'Use scope="col" on column headers and scope="row" on row headers.' },
  'table-fake-caption': { concept: 'table-structure', title: 'Table title is a cell, not a caption', wcag: '1.3.1', severity: 'Low', category: 'Tables', why: 'The first row holds the table\'s title as a merged cell, so it is read as data and never as the table\'s name.', fix: 'Move the title into a <caption>.' },
  'table-duplicate-name': { concept: 'table-structure', title: 'Table caption repeats its summary', wcag: '1.3.1', severity: 'Low', category: 'Tables', why: 'The same text is announced twice when the table is reached.', fix: 'Keep the <caption>; drop or change the summary.' },
  'empty-table-header': { concept: 'table-structure', title: 'Header cell is empty', wcag: '1.3.1', severity: 'Low', category: 'Tables', why: 'A <th> with no text gives the column no name; each cell under it is announced with a blank header.', fix: 'Put the column\'s name in the <th>, or make it a <td>.' },

  // ── Zoom, motion, time ────────────────────────────────────────────────────
  'meta-viewport-large': { concept: 'zoom', title: 'Zoom is capped below 500%', wcag: '1.4.4', severity: 'Low', category: 'Text Resize and Magnification', why: 'maximum-scale stops the page short of the zoom some low-vision users need.', fix: 'Remove maximum-scale, or set it to 5 or more.' },
  'css-orientation-lock': { concept: 'orientation', title: 'Page is locked to one screen orientation', wcag: '1.3.4', severity: 'Medium', category: 'Text Resize and Magnification', why: 'A CSS rotate forces portrait or landscape; a user whose device is mounted one way cannot use the page.', fix: 'Remove the orientation lock in CSS.' },
  'avoid-inline-spacing': { concept: 'text-spacing', title: 'Text spacing is forced with !important', wcag: '1.4.12', severity: 'Medium', category: 'Text Resize and Magnification', why: 'Inline line-height / letter-spacing / word-spacing with !important cannot be overridden by a reader\'s own spacing stylesheet.', fix: 'Drop the !important from the inline spacing styles.' },
  'blink': { concept: 'blinking', title: 'Blinking text', wcag: '2.2.2', severity: 'High', category: 'Media Animation Motion', why: 'A <blink> element flashes for ever with no way to stop it.', fix: 'Remove the <blink> element.' },
  'marquee': { concept: 'blinking', title: 'Scrolling marquee text', wcag: '2.2.2', severity: 'High', category: 'Media Animation Motion', why: 'A <marquee> moves for ever with no pause, and is unreadable to many users.', fix: 'Remove the <marquee>; show the text still.' },
  'meta-refresh': { concept: 'auto-refresh', title: 'Page reloads or redirects itself on a timer', wcag: '2.2.1', severity: 'High', category: 'Media Animation Motion', why: 'A <meta http-equiv="refresh"> with a delay moves the user without warning — mid-form, mid-read.', fix: 'Remove the timed refresh; redirect immediately (delay 0) or on a button.' },
  'audio-caption': { concept: 'audio-transcript', title: 'Audio has no captions or transcript', wcag: '1.2.1', severity: 'High', category: 'Media Animation Motion', why: 'A deaf user gets nothing from an <audio> element with no text version.', fix: 'Add a <track kind="captions"> or a transcript beside it.' },
};

/** axe rules deliberately not shown, and why. Kept so the coverage account is honest. */
const AXE_SKIP = {
  // Lists are ours: axe fails a <ul> for a stray <br> the same as for real
  // junk, and fails a list that carries proper roles (a menu built on <ul>).
  // Our check tells the two apart and offers the right fix for each.
  'list': 'ours instead — a stray <br> gets aria-hidden, a list with roles passes',
  'listitem': 'ours instead — see list',
  'frame-tested': 'about axe itself (did it run inside every iframe), not about the page',
  'hidden-content': 'informational — "there is hidden content", which every page has',
  'color-contrast-enhanced': 'WCAG AAA (7:1) — beyond the AA target',
  'identical-links-same-purpose': 'WCAG AAA — and it guesses at intent',
  'meta-refresh-no-exceptions': 'WCAG AAA — the AA rule (meta-refresh) is shown',
};

/** The catalog entry an axe finding is shown as, or null when it is skipped. */
function axeCatalog(ruleId) {
  const id = String(ruleId || '').replace(/^axe\./, '');
  if (AXE_SKIP[id]) return null;
  const t = AXE_RULES[id];
  if (!t) return undefined; // not translated — verify-scan-engines.mjs keeps this from shipping
  if (t.as) return { ...SCAN_RULES[t.as], ruleId: t.as, concept: SCAN_CONCEPTS[t.as] || t.as };
  return { ...t, ruleId: 'axe.' + id, concept: t.concept };
}

/** The checklist question a rule answers — ours by table, axe's by translation. */
function conceptOfRule(ruleId) {
  if (SCAN_CONCEPTS[ruleId]) return SCAN_CONCEPTS[ruleId];
  if (/^axe\./.test(ruleId || '')) { const c = axeCatalog(ruleId); if (c && c.concept) return c.concept; }
  return ruleId;
}

const SEVERITY_RANK = { Critical: 0, High: 1, Medium: 2, Low: 3 };

// Kept on each finding for the record (and the report), no longer shown as a
// chip: every row reads in our words now, wherever the fault was found.
const ENGINE_LABEL = { u1: 'U1', axe: 'axe' };

/**
 * One row per real fault, carrying the engines that found it.
 *
 * Agreement between independent engines is worth showing: it is the difference
 * between "axe has an opinion" and "three rulesets say this is broken", and it
 * is the first thing a specialist uses to decide what to fix first.
 *
 * Our own finding wins the visible text where there is one, because it is
 * written for this audience — axe's failureSummary is written for the person
 * who wrote the HTML.
 */
function mergeScanFindings(findings) {
  const byKey = new Map();
  for (const f of findings) {
    if (!f || !f.ruleId) continue;
    const concept = conceptOfRule(f.ruleId);
    // Same element, same concept — the selector AND its index matter, or every
    // missing alt on the page would fold into one row (`img` names them all).
    const key = concept + '\u0000' + (f.selector || '') + '\u0000' + (f.idx ?? '');
    const seen = byKey.get(key);
    if (!seen) {
      byKey.set(key, { ...f, engines: [f.engine || 'u1'] });
      continue;
    }
    if (seen.engines.indexOf(f.engine || 'u1') === -1) seen.engines.push(f.engine || 'u1');
    // The most severe verdict wins: engines disagree about impact, and quietly
    // taking the milder one is how a critical fault gets sorted to the bottom.
    if ((SEVERITY_RANK[f.severity] ?? 9) < (SEVERITY_RANK[seen.severity] ?? 9)) seen.severity = f.severity;
    // Prefer a rule that carries a WCAG reference over one that does not.
    if (!seen.wcag && f.wcag) seen.wcag = f.wcag;
    // Our own wording is written for whoever reads the report.
    if ((f.engine || 'u1') === 'u1') {
      seen.issue = f.issue || seen.issue;
      seen.why = f.why || seen.why;
      seen.fix = f.fix || seen.fix;
      seen.cat = f.cat || seen.cat;
    }
  }
  return [...byKey.values()];
}

/**
 * Run the third-party engines in the page and hand back normalised findings.
 *
 * Injected as files, into the ISOLATED world: full DOM access, and out of reach
 * of the client site's Content-Security-Policy — which matters, because the
 * sites most in need of a scan are the ones most likely to forbid a script.
 *
 * A failure here never fails the scan. Our own rules are the part that always
 * works, and losing them because a 540KB bundle would not load on one page is a
 * bad trade — but the caller is told which engines answered, so a half-run is
 * never presented as a clean page.
 */
async function runScanEngines(tabId) {
  try {
    await chrome.scripting.executeScript({
      target: { tabId },
      files: ['vendor/axe.min.js', 'scan-engines.js'],
    });
    const [res] = await chrome.scripting.executeScript({
      target: { tabId },
      func: () => (window.__u1ScanEngines ? window.__u1ScanEngines() : { findings: [], ran: [] }),
    });
    return (res && res.result) || { findings: [], ran: [] };
  } catch (e) {
    console.warn('[U1 Studio] scan engines could not run:', e);
    return { findings: [], ran: [], err: String((e && e.message) || e) };
  }
}

async function scanPageStatic() {
  const tab = await getTab();
  if (!isInjectable(tab)) return { err: 'Cannot scan this page.' };
  try {
    const res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: () => {
        const identOk = (s) => /^[A-Za-z][\w-]*$/.test(s);
        const selOf = (el) => {
          if (!el || el.nodeType !== 1) return '';
          if (el.id && identOk(el.id)) return '#' + el.id;
          const cls = (el.className && typeof el.className === 'string')
            ? el.className.trim().split(/\s+/).filter(identOk) : [];
          if (cls.length) return el.tagName.toLowerCase() + '.' + cls.slice(0, 2).join('.');
          return el.tagName.toLowerCase();
        };
        const txt = (el) => (el.textContent || '').trim().replace(/\s+/g, ' ');
        const accName = (el) => {
          const al = el.getAttribute('aria-label'); if (al && al.trim()) return al.trim();
          const lb = el.getAttribute('aria-labelledby');
          if (lb) { const t = lb.split(/\s+/).map(id => { const e = document.getElementById(id); return e ? txt(e) : ''; }).join(' ').trim(); if (t) return t; }
          const t = txt(el); if (t) return t;
          // Accessible-name roll-up: an icon/image inside the control lends its
          // name to it — <a><img alt="Home"></a> IS named "Home", and a logo link
          // <a><img alt="ACME"></a> is named "ACME". textContent misses this, so
          // gather a descendant's alt / aria-label / <svg><title>. (alt="" is
          // decorative and contributes nothing, so a truly nameless link still flags.)
          for (const d of el.querySelectorAll('[aria-label],img[alt],svg')) {
            const n = (d.getAttribute('aria-label') || d.getAttribute('alt') || '').trim()
              || (d.tagName.toLowerCase() === 'svg' ? ((d.querySelector('title') && d.querySelector('title').textContent) || '').trim() : '');
            if (n) return n;
          }
          return (el.getAttribute('title') || el.value || '').trim();
        };
        // "Really visible": rendered, non-zero box, not display:none/visibility:hidden/
        // opacity:0, not inside a display:none subtree (offsetParent null unless fixed).
        const visible = (el) => {
          if (!el || !el.getBoundingClientRect) return false;
          // Deliberately taken out of reach — by us, or by the site. Reporting
          // it would be the tool flagging its own fix, and `inert` is a
          // statement that this subtree is not part of the page's interface.
          try { if (el.closest('[inert]')) return false; } catch (e) {}
          const r = el.getBoundingClientRect();
          if (r.width < 1 || r.height < 1) return false;
          const s = getComputedStyle(el);
          if (s.visibility === 'hidden' || s.display === 'none' || +s.opacity === 0) return false;
          if (el.offsetParent === null && s.position !== 'fixed') return false;
          return true;
        };
        const nativelyFocusable = (el) => /^(A|BUTTON|INPUT|SELECT|TEXTAREA|SUMMARY)$/.test(el.tagName) && !el.disabled;
        const out = [];
        const seen = new Set(); // avoid duplicate (ruleId+selector) spam
        // Element-based findings are only relevant if the element is actually
        // visible on the page — skip hidden dropdowns, closed modals, templates.
        // `force:true` keeps document-level or intentionally-hidden checks.
        // The selector is short on purpose (`h4`, `a.externalLink`) and can
        // match more than one element; the index among its matches is what
        // makes it THIS one — for the highlight, and for folding an axe finding
        // on the same element into the same row.
        const idxOf = (el, sel) => { try { return Math.max(0, Array.prototype.indexOf.call(document.querySelectorAll(sel), el)); } catch (e) { return 0; } };
        const add = (ruleId, el, text, detail, force) => {
          if (el && !force && !visible(el)) return;
          const selector = el ? selOf(el) : '';
          const idx = el ? idxOf(el, selector) : 0;
          const key = ruleId + '|' + selector + '|' + idx + '|' + (text || '').slice(0, 30);
          if (seen.has(key)) return; seen.add(key);
          out.push({ ruleId, selector, idx, text: (text || '').slice(0, 120), detail: detail || '' });
        };

        // ── Page title / language ──────────────────────────────────────
        const docTitle = (document.title || '').trim();
        if (!docTitle) add('title-missing', null, '(no <title>)');
        else if (/^(untitled|home|index|default|document|new page)$/i.test(docTitle) || /\.(html?|aspx?|php|jsp)$/i.test(docTitle) || /^https?:\/\//i.test(docTitle))
          add('title-weak', null, docTitle);
        if (!document.documentElement.getAttribute('lang')) add('lang-missing', null, '<html> has no lang');

        // ── Headings ───────────────────────────────────────────────────
        const heads = Array.from(document.querySelectorAll('h1,h2,h3,h4,h5,h6,[role=heading][aria-level]'));
        let prev = 0, h1count = 0;
        heads.forEach(h => {
          const lvl = h.getAttribute('aria-level') ? +h.getAttribute('aria-level') : +h.tagName.charAt(1);
          if (lvl === 1) h1count++;
          const t = txt(h);
          if (!t) add('heading-empty', h, '(empty ' + (h.tagName.toLowerCase()) + ')', 'H' + lvl);
          else if (prev && lvl > prev + 1) add('heading-skip', h, t, `H${prev} → H${lvl}`);
          prev = lvl;
        });
        if (h1count === 0) add('h1-missing', null, 'Page has no H1');
        else if (h1count > 1) add('h1-multiple', null, `${h1count} H1 elements on the page`);

        // ── Landmarks / skip link ──────────────────────────────────────
        if (!document.querySelector('main,[role=main]') && !document.querySelector('nav,[role=navigation]'))
          add('landmarks-missing', null, 'No <main>/<nav> landmarks found');
        const firstLinks = Array.from(document.querySelectorAll('a[href^="#"]')).slice(0, 5);
        const hasSkip = firstLinks.some(a => /skip|main|content|navigation/i.test(txt(a) + ' ' + (a.getAttribute('href') || '')));
        if (!hasSkip) add('skip-link-missing', null, 'No “skip to content” link at the top');

        // ── Images ─────────────────────────────────────────────────────
        Array.from(document.querySelectorAll('img')).slice(0, 200).forEach(el => {
          const decorative = el.getAttribute('role') === 'presentation' || el.getAttribute('aria-hidden') === 'true' || el.getAttribute('alt') === '';
          const file = (el.getAttribute('src') || '').split('/').pop().split('?')[0];
          if (el.getAttribute('alt') === null && !decorative)
            add('img-alt-missing', el, file || '(image)');
          else if (!decorative) {
            // "Career_HealthNews.jpg → Career_HealthNews": the alt is the file
            // name, or a file name outright. Says nothing about the picture.
            const alt = (el.getAttribute('alt') || '').trim();
            const stem = file.replace(/\.[a-z0-9]+$/i, '');
            const norm = (x) => x.toLowerCase().replace(/[\s_\-]+/g, '');
            // "View Personal Health Record" beside ViewPersonalHealthRecord.png
            // is a real alt that happens to match the file — words with spaces
            // pass. A token with no spaces that equals the file's stem, or any
            // alt that ends in an image extension, does not.
            if (alt && (/\.(png|jpe?g|gif|svg|webp|bmp|avif)$/i.test(alt) || (stem.length > 3 && !/\s/.test(alt) && norm(alt) === norm(stem))))
              add('img-alt-filename', el, `${file} → “${alt}”`);
          }
        });

        // ── Links ──────────────────────────────────────────────────────
        const generic = /^(click here|read more|here|link|more|learn more|details|›|»|>)$/i;
        Array.from(document.querySelectorAll('a[href]')).slice(0, 300).forEach(el => {
          if (!visible(el)) return;
          const name = accName(el);
          if (!name) add('link-empty', el, (el.getAttribute('href') || '').slice(0, 50));
          else if (generic.test(name)) add('link-generic', el, name, (el.getAttribute('href') || '').slice(0, 40));
          // Opens elsewhere without saying so — in the name, the title, or an
          // icon's alt. Low severity: an advisory, not a blocker.
          if (el.getAttribute('target') === '_blank') {
            const said = name + ' ' + (el.getAttribute('title') || '');
            if (!/new (tab|window)|opens? in|external|חלון חדש|לשונית חדשה|כרטיסייה חדשה/i.test(said))
              add('link-newwindow', el, name, (el.getAttribute('href') || '').slice(0, 40));
          }
        });

        // ── Buttons ────────────────────────────────────────────────────
        Array.from(document.querySelectorAll('button,[role=button],input[type=submit],input[type=button]')).slice(0, 300).forEach(el => {
          if (!visible(el)) return;
          if (!accName(el)) add('button-noname', el, '(unnamed button)');
        });

        // ── Form fields ────────────────────────────────────────────────
        Array.from(document.querySelectorAll('input:not([type=hidden]):not([type=submit]):not([type=button]):not([type=radio]):not([type=checkbox]),select,textarea')).slice(0, 200).forEach(el => {
          let label = '';
          if (el.id) { try { const l = document.querySelector(`label[for="${CSS.escape(el.id)}"]`); if (l) label = txt(l); } catch {} }
          if (!label && el.closest('label')) label = txt(el.closest('label'));
          if (!label) label = el.getAttribute('aria-label') || (el.getAttribute('aria-labelledby') ? 'x' : '');
          const ph = el.getAttribute('placeholder') || '';
          if (!label && ph) add('input-placeholder', el, ph, el.getAttribute('type') || el.tagName.toLowerCase());
          else if (!label) add('input-nolabel', el, '(unlabelled ' + el.tagName.toLowerCase() + ')', el.getAttribute('type') || '');
        });

        // ── <label for> pointing at nothing ────────────────────────────
        Array.from(document.querySelectorAll('label[for]')).slice(0, 200).forEach(el => {
          const id = el.getAttribute('for');
          if (id && !document.getElementById(id)) add('label-for-broken', el, txt(el).slice(0, 60) || '(label)', `for="${id}"`);
        });

        // ── Named landmarks that have no name ──────────────────────────
        // A landmark is not named by its contents — only by aria-label,
        // aria-labelledby or title. A hidden <label> inside a role="form" does
        // not name the form.
        const landmarkName = (el) => {
          const al = (el.getAttribute('aria-label') || '').trim(); if (al) return al;
          const lb = el.getAttribute('aria-labelledby');
          if (lb) { const t = lb.split(/\s+/).map(id => { const e = document.getElementById(id); return e ? txt(e) : ''; }).join(' ').trim(); if (t) return t; }
          return (el.getAttribute('title') || '').trim();
        };
        // Not a failure on its own: an unnamed role=form/region is just not a
        // landmark, and a form that is a U1 mapping (it carries the engine's
        // marker) IS the treatment — every other mapped form on the page
        // passes for the same reason, and this one must not read differently.
        // The one case worth a NOTE is two or more unnamed ones: the landmark
        // list then says “form, form” and nobody can tell them apart.
        const unnamedLandmarks = Array.from(document.querySelectorAll('[role=form],[role=region]')).slice(0, 50)
          .filter(el => !landmarkName(el) && !el.hasAttribute('u1st-avoid-change-detection'));
        if (unnamedLandmarks.length >= 2) unnamedLandmarks.forEach(el => {
          const f = el.querySelector('input:not([type=hidden]),select,textarea');
          let about = '';
          if (f) { const lab = f.id ? document.querySelector(`label[for="${CSS.escape(f.id)}"]`) : null; about = (lab && txt(lab)) || f.getAttribute('aria-label') || f.getAttribute('placeholder') || f.getAttribute('name') || ''; }
          if (!about) { const h = el.querySelector('h1,h2,h3,h4,h5,h6'); about = h ? txt(h) : txt(el).slice(0, 40); }
          add('landmark-noname', el, `the ${el.getAttribute('role')} around “${about.slice(0, 40)}” — one of ${unnamedLandmarks.length} without a name`, '', true);
        });

        // ── Radio/checkbox groups without a group label ────────────────
        const groups = {};
        Array.from(document.querySelectorAll('input[type=radio][name],input[type=checkbox][name]')).forEach(el => {
          (groups[el.name] = groups[el.name] || []).push(el);
        });
        Object.keys(groups).forEach(name => {
          const els = groups[name];
          if (els.length < 2) return;
          const grouped = els[0].closest('fieldset') || els[0].closest('[role=group],[role=radiogroup]');
          const labelled = grouped && (grouped.querySelector('legend') || grouped.getAttribute('aria-label') || grouped.getAttribute('aria-labelledby'));
          if (!labelled) add('group-nolabel', els[0], `Group "${name}" (${els.length} options)`);
        });

        // ── Lists: what sits directly inside a <ul>/<ol> ───────────────
        // A list that carries roles of its own (a menu, a tab strip, a
        // listbox, or role=list with role=listitem children) is judged by
        // those roles, not by its tags — it passes here. A stray <br> or an
        // empty spacer is one finding with one fix (hide it); real non-item
        // content is the other.
        Array.from(document.querySelectorAll('ul, ol')).slice(0, 150).forEach(list => {
          const role = (list.getAttribute('role') || '').toLowerCase();
          if (role && role !== 'list') return;                     // a component — its own roles decide
          const kids = Array.from(list.children);
          const offenders = kids.filter(k => !/^(LI|SCRIPT|TEMPLATE)$/.test(k.tagName));
          if (!offenders.length) return;
          if (offenders.every(k => (k.getAttribute('role') || '').toLowerCase() === 'listitem' || k.getAttribute('aria-hidden') === 'true')) return;
          const stray = offenders.filter(k => /^(BR|HR)$/.test(k.tagName) || (!(k.textContent || '').trim() && !k.querySelector('img,svg,a,button,input,li')));
          if (stray.length === offenders.length) add('list-stray-br', list, `${stray.length} stray <${stray[0].tagName.toLowerCase()}> in a list of ${kids.length - stray.length}`, '', true);
          else add('list-structure', list, txt(list).slice(0, 60), offenders.map(k => '<' + k.tagName.toLowerCase() + '>').slice(0, 4).join(' '));
        });

        // ── Iframes ────────────────────────────────────────────────────
        Array.from(document.querySelectorAll('iframe')).slice(0, 40).forEach(el => {
          if (!el.getAttribute('title') && !el.getAttribute('aria-label')) add('iframe-notitle', el, (el.getAttribute('src') || '(iframe)').slice(0, 50));
        });

        // ── Tables without headers ─────────────────────────────────────
        Array.from(document.querySelectorAll('table')).slice(0, 40).forEach(el => {
          if (el.getAttribute('role') === 'presentation' || el.getAttribute('role') === 'none') return;
          const rows = el.querySelectorAll('tr').length;
          if (rows >= 2 && !el.querySelector('th')) add('table-noheaders', el, `Table with ${rows} rows and no <th>`);
        });

        // ── Positive tabindex ──────────────────────────────────────────
        Array.from(document.querySelectorAll('[tabindex]')).slice(0, 200).forEach(el => {
          const ti = parseInt(el.getAttribute('tabindex'), 10);
          if (ti > 0) add('tabindex-positive', el, `${el.tagName.toLowerCase()} tabindex="${ti}"`);
        });

        // ── aria-hidden on focusable ───────────────────────────────────
        Array.from(document.querySelectorAll('[aria-hidden="true"]')).slice(0, 100).forEach(el => {
          const foc = (nativelyFocusable(el) && el.tagName !== 'A') || (el.tagName === 'A' && el.hasAttribute('href')) || (el.getAttribute('tabindex') && +el.getAttribute('tabindex') >= 0)
            || el.querySelector('a[href],button,input,select,textarea,[tabindex]:not([tabindex="-1"])');
          if (foc) add('aria-hidden-focusable', el, '(focusable content inside aria-hidden)');
        });

        // ── Duplicate ids ──────────────────────────────────────────────
        const idMap = {};
        Array.from(document.querySelectorAll('[id]')).forEach(el => { const id = el.id; if (id) (idMap[id] = idMap[id] || []).push(el); });
        Object.keys(idMap).forEach(id => {
          if (idMap[id].length < 2) return;
          // Which ones actually break something: a label or ARIA reference
          // pointing at this id lands on the first element only.
          let referenced = false;
          try { referenced = !!document.querySelector(`label[for="${CSS.escape(id)}"],[aria-labelledby~="${CSS.escape(id)}"],[aria-describedby~="${CSS.escape(id)}"],[aria-controls~="${CSS.escape(id)}"]`); } catch (e) {}
          add('dup-ids', idMap[id][0], `id="${id}" used ${idMap[id].length}×${referenced ? ' — and a label/ARIA reference points at it' : ''}`, '', true);
        });

        // ── Zoom disabled ──────────────────────────────────────────────
        const vp = document.querySelector('meta[name=viewport]');
        if (vp && /user-scalable\s*=\s*(no|0)|maximum-scale\s*=\s*1(\.0)?\b/i.test(vp.getAttribute('content') || '')) add('zoom-disabled', null, vp.getAttribute('content') || '');

        // ── Autoplay media / captions ──────────────────────────────────
        Array.from(document.querySelectorAll('audio[autoplay],video[autoplay]')).forEach(el => {
          if (!el.muted && !el.controls) add('autoplay-audio', el, el.tagName.toLowerCase() + ' autoplay');
        });
        // Media with sound and no way to drive it. A muted, looping background
        // video is decoration and is left alone.
        Array.from(document.querySelectorAll('audio,video')).slice(0, 20).forEach(el => {
          if (el.hasAttribute('controls') || ((el.muted || el.hasAttribute('muted')) && el.hasAttribute('loop'))) return;
          const custom = el.parentElement && el.parentElement.querySelector('button,[role=button]');
          if (!custom) add('media-nocontrols', el, el.tagName.toLowerCase() + (el.getAttribute('src') ? ' ' + el.getAttribute('src').split('/').pop().slice(0, 40) : ''));
        });

        // ── Carousel with no pause control (WCAG 2.2.2) ─────────────────
        // Recommendation only — U1 does not inject a button for this (see
        // u1-patch.js's carousel region for why). Same "does it actually
        // move" guard the patch used to use: a static carousel gaining a
        // flagged issue that doesn't apply to it would be its own false
        // positive. A real pause/stop control anywhere in the carousel
        // (however the site built it) means this is already handled.
        //
        // The control is wherever the site put it. Molina's is
        // <a title="Pause" class="pausebtn">Play/Pause</a> in a sibling <div>
        // BEFORE the carousel, not inside it — so the search covers the
        // carousel, then each ancestor up to three levels (the banner wrapper),
        // and reads title, aria-label, class, id, text and an icon's alt, not
        // aria-label alone. Missing a real button is the false positive that
        // costs the most: the client checks, finds the button, and stops
        // trusting the list.
        const PAUSE_WORDS = /\b(pause|stop|play\/pause|autoplay|עצור|עצירה|השהה|הפסק)\b/i;
        const looksLikePause = (c) => {
          const attrs = [c.getAttribute('aria-label'), c.getAttribute('title'), c.className && String(c.className), c.id,
            (c.textContent || '').trim().slice(0, 60)];
          const img = c.querySelector('img[alt],svg title,[aria-label]');
          if (img) attrs.push(img.getAttribute('alt') || img.getAttribute('aria-label') || img.textContent);
          return attrs.some(a => a && PAUSE_WORDS.test(String(a).replace(/[-_]/g, ' ')));
        };
        const findPauseControl = (root) => {
          let scope = root;
          for (let up = 0; scope && scope !== document.body && up <= 3; up++, scope = scope.parentElement) {
            const found = Array.from(scope.querySelectorAll('button,a,[role=button],input[type=button],[onclick]')).find(looksLikePause);
            if (found) return found;
          }
          return null;
        };
        const carousels = new Set(Array.from(document.querySelectorAll(
          '[role="group"][aria-roledescription="carousel"],.u1st-carousel,[data-u1-carousel],' +
          // Frameworks whose markup SAYS it auto-advances:
          '.carousel[data-ride="carousel"],.carousel[data-bs-ride="carousel"],[data-autoplay]:not([data-autoplay="false"]),[data-swiper-autoplay],.slick-slider[data-slick*="autoplay"]')));
        carousels.forEach(el => {
          // One finding per carousel: a decorated inner track inside a framework
          // wrapper is the same carousel.
          if (Array.from(carousels).some(o => o !== el && o.contains(el))) return;
          const declared = /data-(bs-)?ride|data-autoplay|data-swiper-autoplay|autoplay/i.test(el.outerHTML.slice(0, 400));
          const moves = declared || !!el.querySelector('[aria-hidden="true"],[hidden]');
          if (!moves) return;
          if (!findPauseControl(el)) add('carousel-nopause', el, '(auto-advancing carousel)');
        });
        Array.from(document.querySelectorAll('video')).slice(0, 20).forEach(el => {
          if (!el.querySelector('track[kind=captions],track[kind=subtitles]')) add('video-nocaptions', el, '(video without captions track)');
        });

        // ── Custom widget roles missing required state/value ───────────
        Array.from(document.querySelectorAll('[role=switch]')).forEach(el => { if (el.getAttribute('aria-checked') == null) add('switch-nostate', el, accName(el) || '(switch)'); });
        Array.from(document.querySelectorAll('[role=checkbox]')).forEach(el => { if (el.getAttribute('aria-checked') == null) add('checkbox-nostate', el, accName(el) || '(checkbox)'); });
        Array.from(document.querySelectorAll('[role=slider]')).forEach(el => { if (el.getAttribute('aria-valuenow') == null) add('slider-novalue', el, accName(el) || '(slider)'); });
        Array.from(document.querySelectorAll('[role=meter],[role=progressbar]')).forEach(el => { if (el.getAttribute('aria-valuenow') == null) add('meter-novalue', el, accName(el) || '(meter)'); });
        Array.from(document.querySelectorAll('[role=combobox]')).forEach(el => { if (el.getAttribute('aria-expanded') == null) add('combobox-noexpanded', el, accName(el) || '(combobox)'); });

        // ── Misleading role but not focusable ──────────────────────────
        Array.from(document.querySelectorAll('[role=button],[role=link],[role=menuitem],[role=tab]')).slice(0, 200).forEach(el => {
          if (nativelyFocusable(el)) return;
          const ti = el.getAttribute('tabindex');
          if (ti == null || +ti < 0) add('misleading-role', el, `${el.tagName.toLowerCase()} role="${el.getAttribute('role')}"`);
        });

        // ── Clickable div/span with no interactive role ────────────────
        Array.from(document.querySelectorAll('div[onclick],span[onclick]')).slice(0, 100).forEach(el => {
          const role = el.getAttribute('role');
          if (!role || !/button|link|menuitem|tab|checkbox|switch/.test(role)) add('clickable-div', el, txt(el).slice(0, 60) || '(clickable ' + el.tagName.toLowerCase() + ')');
        });

        // ── Broken ARIA references ─────────────────────────────────────
        ['aria-labelledby', 'aria-describedby', 'aria-controls'].forEach(attr => {
          Array.from(document.querySelectorAll('[' + attr + ']')).slice(0, 200).forEach(el => {
            const ids = (el.getAttribute(attr) || '').split(/\s+/).filter(Boolean);
            const missing = ids.filter(id => !document.getElementById(id));
            if (missing.length) add('aria-ref-broken', el, `${attr}="${missing.join(' ')}" → not found`);
          });
        });

        // ── Touch target too small ─────────────────────────────────────
        let smallCount = 0;
        Array.from(document.querySelectorAll('a[href],button,[role=button],input:not([type=hidden])')).forEach(el => {
          if (smallCount >= 20 || !visible(el)) return;
          const r = el.getBoundingClientRect();
          if (r.width < 24 && r.height < 24) { add('target-size-small', el, `${Math.round(r.width)}×${Math.round(r.height)}px`); smallCount++; }
        });

        // What the page HOLDS, so the checklist can say "passed" with the
        // evidence beside it, and "nothing to check" when there is nothing —
        // a title that exists can still be wrong, and only a person can say.
        const q = (s) => Array.from(document.querySelectorAll(s));
        // selOf can answer a bare `img` for a picture with no id or class; the
        // index among that selector's matches (idxOf, above) is what makes it
        // THIS picture.
        const inventory = {
          title: (document.title || '').trim(),
          lang: (document.documentElement.getAttribute('lang') || '').trim(),
          headings: q('h1,h2,h3,h4,h5,h6,[role=heading][aria-level]').filter(visible).slice(0, 80).map(h => ({
            // aria-level wins over the tag — that is how a mapping re-levels
            // a real <h4>, and what a screen reader announces.
            level: (+h.getAttribute('aria-level') || (/^H[1-6]$/.test(h.tagName) ? +h.tagName[1] : 2)),
            text: txt(h).slice(0, 90), selector: selOf(h), idx: idxOf(h, selOf(h)),
          })),
          images: q('img').filter(visible).slice(0, 60).map(img => ({
            selector: selOf(img), idx: idxOf(img, selOf(img)), alt: img.hasAttribute('alt') ? img.getAttribute('alt') : null,
            src: (img.currentSrc || img.src || '').split('/').pop().split('?')[0].slice(0, 40),
            decorative: img.getAttribute('alt') === '' || img.getAttribute('role') === 'presentation',
          })),
          imagesTotal: q('img').filter(visible).length,
          links: q('a[href]').filter(visible).length,
          buttons: q('button,[role=button],input[type=submit],input[type=button]').filter(visible).length,
          inputs: q('input:not([type=hidden]),select,textarea').filter(visible).length,
          iframes: q('iframe').map(f => ({ selector: selOf(f), idx: idxOf(f, selOf(f)), title: (f.getAttribute('title') || '').trim(), src: (f.src || '').slice(0, 60) })),
          tables: q('table').filter(visible).length,
          media: q('video,audio').length,
          landmarks: {
            main: q('main,[role=main]').length, nav: q('nav,[role=navigation]').length,
            header: q('header,[role=banner]').length, footer: q('footer,[role=contentinfo]').length,
            // A search that carries no role=search is still a search — the
            // field says so (type, name, label or placeholder). Counted, and
            // marked so the evidence can say "there, but not marked".
            // role=search, OR a NAMED form around a search field — the shape
            // a U1 `form` mapping leaves (role="form" it re-writes on every
            // tick, so the name is the fix there, not the role).
            search: (() => {
              const SEARCHQ = 'input[type=search],input[name*="search" i],input[id*="search" i],input[placeholder*="search" i],input[aria-label*="search" i],input[placeholder*="חיפוש"],input[aria-label*="חיפוש"]';
              // A named form around the search field, or one that is a U1
              // form mapping (the engine's marker), is the search landmark as
              // far as this page is concerned.
              const named = q('[role=form][aria-label],[role=form][aria-labelledby],form[aria-label],form[aria-labelledby],[role=form][u1st-avoid-change-detection]').filter(f => f.querySelector(SEARCHQ));
              return q('[role=search]').length + named.length;
            })(),
            searchUnmarked: (() => {
              const SEARCHQ = 'input[type=search],input[name*="search" i],input[id*="search" i],input[placeholder*="search" i],input[aria-label*="search" i],input[placeholder*="חיפוש"],input[aria-label*="חיפוש"]';
              const fields = q(SEARCHQ).filter(visible);
              return fields.filter(f => !f.closest('[role=search],[role=form][aria-label],[role=form][aria-labelledby],form[aria-label],form[aria-labelledby],[role=form][u1st-avoid-change-detection]')).length;
            })(),
          },
          skipLink: (() => {
            const a = q('a[href^="#"]').find(x => /skip|דלג|main|content|תוכן/i.test(txt(x) + ' ' + (x.getAttribute('aria-label') || '')));
            return a ? txt(a) || (a.getAttribute('aria-label') || '') : '';
          })(),
          // Every skip link on the page — the engine's, the config's, the
          // site's own — and whether each one lands on something.
          skipLinks: q('a[href^="#"]').filter(x => x.classList.contains('u1st-skip-link') || /skip|דלג/i.test(txt(x) + ' ' + (x.getAttribute('aria-label') || ''))).slice(0, 12).map(x => {
            const id = (x.getAttribute('href') || '').slice(1);
            let t = null; try { t = id && document.getElementById(id); } catch (e) {}
            return { text: txt(x) || (x.getAttribute('aria-label') || ''), href: x.getAttribute('href') || '', lands: !!t, target: t ? selOf(t) : '' };
          }),
          positiveTabindex: q('[tabindex]').filter(x => +x.getAttribute('tabindex') > 0).length,
        };
        return { results: out, total: out.length, inventory };
      },
    });
    return res?.[0]?.result || { err: 'No result' };
  } catch (err) {
    return { err: err.message };
  }
}

// ── "This alt is right" ──────────────────────────────────────────────────────
//
// The scan can only ask whether an alt says what the picture is for; a person
// answers. An approved image (by file name + alt) stops being a finding and
// shows a tick in the evidence list, on every scan of this site, until the
// alt changes. Local, private, never exported.
const altOkKey = (host) => (U1Store.PRIVATE_PREFIX || '__') + 'altOk_' + (host || currentHostname);
let scanAltOk = new Set();
const altOkId = (src, alt) => `${(src || '').split('/').pop().split('?')[0]}|${(alt || '').trim()}`;
async function loadAltOk() {
  try { const k = altOkKey(); const v = (await U1Store.get([k]))[k]; scanAltOk = new Set(Array.isArray(v) ? v : []); }
  catch { scanAltOk = new Set(); }
  return scanAltOk;
}
async function setAltOk(ids, on) {
  for (const id of ids || []) { if (on) scanAltOk.add(id); else scanAltOk.delete(id); }
  try { await U1Store.setLocalOnly({ [altOkKey()]: [...scanAltOk].slice(-1500) }); } catch {}
}
// The image finding's text is `file → “alt”`; approval is keyed the same way.
const altOkIdOfFinding = (r) => {
  const m = /^(.*?) → “(.*)”$/.exec(r.text || '');
  return m ? altOkId(m[1], m[2]) : '';
};
function dropApprovedAlts(list) {
  return list.filter(r => !(r.ruleId === 'img-alt-filename' && scanAltOk.has(altOkIdOfFinding(r))));
}

// ── "Ignore this one" ────────────────────────────────────────────────────────
//
// A finding the person has looked at and decided is not theirs to fix — a
// third-party widget, a false alarm, a thing the client accepted. Ignored
// per site (private key, never exported), by rule + element, so it stays
// ignored on the next scan of this page and comes back the moment the
// element or the rule changes. Never silently: the row count says how many
// are ignored, and one click shows them again.
const ignoredKey = (host) => (U1Store.PRIVATE_PREFIX || '__') + 'scanIgnored_' + (host || currentHostname);
let scanIgnored = new Map(); // id → { at, title, text }
let scanShowIgnored = false;
const ignoreIdOf = (r) => `${r.ruleId}|${r.selector || ''}|${r.idx || 0}|${(r.text || '').slice(0, 60)}`;
async function loadIgnored() {
  try { const k = ignoredKey(); const v = (await U1Store.get([k]))[k]; scanIgnored = new Map(Object.entries(v && typeof v === 'object' ? v : {})); }
  catch { scanIgnored = new Map(); }
  return scanIgnored;
}
async function setIgnored(r, on) {
  const id = ignoreIdOf(r);
  if (on) scanIgnored.set(id, { at: Date.now(), title: r.issue || r.ruleId, text: r.text || '' }); else scanIgnored.delete(id);
  const obj = {}; for (const [k, v] of [...scanIgnored.entries()].slice(-1000)) obj[k] = v;
  try { await U1Store.setLocalOnly({ [ignoredKey()]: obj }); } catch {}
}
const isIgnored = (r) => scanIgnored.has(ignoreIdOf(r));

/** Our raw in-page findings, dressed with their catalog rule. */
function enrichOurFindings(results) {
  return (results || []).map(f => {
    const rule = SCAN_RULES[f.ruleId] || {};
    return {
      engine: 'u1',
      ruleId: f.ruleId, selector: f.selector, text: f.text, detail: f.detail,
      issue: rule.title || f.ruleId, why: rule.why || '', fix: rule.fix || '',
      severity: rule.severity || 'Medium', wcag: rule.wcag || '', cat: rule.category || 'Other',
      note: !!rule.note, idx: f.idx || 0,
    };
  });
}

/**
 * Re-read the page after a mapping was applied from the scan, so the list
 * moves in real time: the outline shows the new level, the count drops, and
 * the row that was mapped stays — marked resolved — instead of vanishing.
 *
 * Only OUR checks are re-run (they take milliseconds); the engine's findings
 * from the last full scan are kept as they were. A row mapped here whose
 * fault is gone from the fresh read is kept as `resolved` so the person sees
 * what they did land; a mapped row whose fault is STILL there keeps its
 * "mapped" mark and stays counted — the mapping did not take, and hiding
 * that is worse than showing it.
 */
async function refreshScanAfterMapping(focusRule) {
  // U1 and the patch apply on their own tick; read after they have.
  await new Promise(r => setTimeout(r, 700));
  const res = await scanPageStatic();
  if (!res || res.err) { renderScanResults(); return; }
  const prev = scanResults;
  const keyOf = (r) => r.ruleId + '|' + (r.selector || '') + '|' + (r.idx || 0) + '|' + (r.text || '');
  const theirs = prev.filter(r => !r.resolved && !(r.engines || ['u1']).includes('u1'))
    .map(r => ({ ...r, engine: 'axe', engines: undefined, mapped: undefined }));
  const next = mergeScanFindings([...dropApprovedAlts(enrichOurFindings(res.results)), ...theirs])
    .sort((a, b) => (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9));
  const byKey = new Map(next.map(n => [keyOf(n), n]));
  for (const r of prev) {
    if (!r.mapped && !r.resolved) continue;
    const hit = byKey.get(keyOf(r));
    if (hit) { hit.mapped = true; continue; }
    if (!r.resolved) r.resolved = true;
    next.push(r);
  }
  // Rows that were on the list for the rule just fixed and are gone from the
  // fresh read are FIXED — kept, marked, so the person sees each one land.
  if (focusRule) {
    for (const r of prev) {
      if (r.ruleId !== focusRule || r.resolved || r.note) continue;
      const still = byKey.get(keyOf(r));
      if (still) { still.stillAfterFix = true; continue; }
      next.push({ ...r, resolved: true, fixedBy: focusRule });
    }
  }
  scanResults = next;
  scanInventory = res.inventory || scanInventory;
  await loadScanMappingStatus();
  // Say, row by row, what the fix did: "44 fixed · 2 still there: …".
  if (focusRule) {
    const was = prev.filter(r => r.ruleId === focusRule && !r.resolved && !r.note);
    const still = next.filter(r => r.ruleId === focusRule && !r.resolved && !r.note);
    const fixed = was.length - still.length;
    const rule = SCAN_RULES[focusRule] || {};
    const tail = still.length ? ` Still there: ${still.slice(0, 6).map(r => `“${(r.text || r.selector || '').slice(0, 40)}”`).join(', ')}${still.length > 6 ? ` +${still.length - 6} more` : ''} — those need a look by hand.` : '';
    showNotice(document.getElementById('scanStatus'),
      `${rule.title || focusRule}: ${fixed} of ${was.length} fixed on the page.${tail}`, still.length ? 'warn' : 'success', 12000);
  }
  const crit = scanResults.filter(r => !r.resolved && r.severity === 'Critical').length;
  const high = scanResults.filter(r => !r.resolved && r.severity === 'High').length;
  const live = scanResults.filter(r => !r.resolved && !r.note).length;
  const cnt = document.getElementById('scanCount');
  if (cnt) cnt.textContent = live ? `${computeScanScore(scanResults)}% · ${live} issues${crit ? ` · ${crit} critical` : ''}${high ? ` · ${high} high` : ''}` : '100%';
  // The history row for this page moves with it.
  getTab().then(t => saveScanToHistory(t, scanResults, scanEnginesRan, scanInventory)).catch(() => {});
  renderScanFilters();
  renderScanResults();
}

// Which findings pass the active severity + category filters.
function scanFiltered() {
  return scanResults.filter(r =>
    (scanActiveSev === '*' || r.severity === scanActiveSev) &&
    (scanActiveCat === '*' || r.cat === scanActiveCat));
}

function renderScanFilters() {
  const el = document.getElementById('scanFilters');
  if (!el) return;
  // Severity row (ordered Critical→Low) + category row.
  const sevCounts = {};
  for (const r of scanResults) { if (!r.resolved && !isIgnored(r)) sevCounts[r.severity] = (sevCounts[r.severity] || 0) + 1; }
  const sevChip = (s, label) => {
    const n = s === '*' ? scanResults.length : (sevCounts[s] || 0);
    if (s !== '*' && !n) return '';
    return `<button class="scan-chip sev-${(s || '').toLowerCase()} ${scanActiveSev === s ? 'active' : ''}" data-scan-sev="${escapeHtml(s)}">${escapeHtml(label)} <span class="n">${n}</span></button>`;
  };
  const catCounts = {};
  for (const r of scanResults) catCounts[r.cat] = (catCounts[r.cat] || 0) + 1;
  const cats = Object.keys(catCounts).sort();
  const catChip = (c, label, n) =>
    `<button class="scan-chip ${scanActiveCat === c ? 'active' : ''}" data-scan-cat="${escapeHtml(c)}">${escapeHtml(label)} <span class="n">${n}</span></button>`;
  el.innerHTML =
    `<div class="scan-filter-row">${sevChip('*', 'All')}${['Critical', 'High', 'Medium', 'Low'].map(s => sevChip(s, s)).join('')}</div>` +
    `<div class="scan-filter-row">${catChip('*', 'All categories', scanResults.length)}${cats.map(c => catChip(c, c, catCounts[c])).join('')}</div>`;
}

/**
 * The scan rules a static fix can actually resolve, and what to call it.
 *
 * Deliberately short. A rule belongs here only when the answer is the same for
 * every element it flags and needs nothing written by a person — otherwise
 * "fix all forty" is forty wrong decisions taken at once, which is worse than
 * forty right ones taken slowly.
 *
 * Everything absent stays read-only, and says why: `img-alt-missing` and
 * `button-noname` need words nobody but you can write; `clickable-div` and the
 * `*-nostate` rules are components, and mapping them as a component is the fix.
 */
const STATIC_FIXABLE = {
  'tabindex-positive':   { does: 'Put every positive tabindex back to 0, so focus follows the page again.' },
  'aria-ref-broken':     { does: 'Drop the aria-labelledby/describedby ids that point at nothing, so the element gets its own name back.' },
  'input-placeholder':   { does: 'Promote each placeholder to a real label. The text is already written — nothing to author.' },
  'table-noheaders':     { does: 'Turn the first row of each data table into <th scope="col">.' },
  'zoom-disabled':       { does: 'Let the page be enlarged: remove user-scalable=no and raise maximum-scale.' },
  'autoplay-audio':      { does: 'Remove the autostart and make sure there is a control. The media stays.' },
  'landmark-noname':     { does: 'Name each unnamed form/region from what is inside it: a search box becomes role="search" named after its field; others take their heading or first field label as the name.' },
  'link-newwindow':      { does: 'Add “(opens in a new tab)” — in the page’s language — to the name of every link that opens one and does not say so. The visible text is untouched; the name a screen reader hears is extended.' },
  'list-stray-br':       { does: 'Hide every <br> and empty spacer sitting directly inside a list from screen readers (aria-hidden="true"), so the item count is right. Nothing visible changes.' },
  'lang-missing':        { does: 'Set the page language, so a screen reader reads it in the right voice.', needsLang: true },
};

/**
 * Filter-and-results: a field that narrows a list already on the page.
 *
 * Not in STATIC_FIXABLE because no scan rule finds it — it is not a fault in
 * the markup, it is a pattern with a missing status message, and the only way
 * to see it is by shape. Offered from the Scan tab beside the exclude control,
 * measured by filterListShape and applied as a static fix.
 */
async function offerFilterResults() {
  const tab = await getTab();
  if (!isInjectable(tab)) return null;
  return inPage(tab.id, () => {
    const S = window.__u1SelectorIntel;
    if (!S || !S.filterListShape) return null;
    // Any text or search input on the page is a candidate for the pattern; the
    // shape says whether it really is one.
    for (const f of document.querySelectorAll('input[type="search"],input[type="text"],input:not([type])')) {
      const shape = S.filterListShape(S.robustSelector(f));
      if (shape) return shape;
    }
    return null;
  });
}

/** Why a rule offers no bulk fix — shown instead of a button, never as silence. */
const STATIC_WHY_NOT = {
  'img-alt-missing': 'needs alt text only you can write',
  'link-empty': 'needs the link\'s text', 'link-generic': 'needs better link text',
  'button-noname': 'needs the button\'s name', 'input-nolabel': 'needs the field\'s label',
  'iframe-notitle': 'needs a title for the frame', 'title-missing': 'needs a page title',
  'group-nolabel': 'needs a name for the group',
  'clickable-div': 'map it as a component instead — that is the fix',
  'misleading-role': 'map it as a component instead — that is the fix',
  'switch-nostate': 'map it as a switch', 'checkbox-nostate': 'map it as a checkbox',
  'slider-novalue': 'map it as a slider', 'meter-novalue': 'map it as a meter',
  'combobox-noexpanded': 'map it as an autocomplete', 'video-nocaptions': 'needs caption files',
  'target-size-small': 'a CSS change — the exported bundle carries no stylesheet',
  'carousel-nopause': 'a visible control the client places — U1 does not add UI to the page',
  'dup-ids': 'a note for the developers, not a failure — renaming an id breaks whatever queries it',
  'img-alt-filename': 'needs alt text only you can write',
  'label-for-broken': 'the for="" must be corrected in the page',
  'media-nocontrols': 'add the controls attribute in the page',
  'title-weak': 'needs a page title',
  'list-structure': 'map it as the component it is (menu, tabs), or fix the markup',
  'axe.color-contrast': 'colours are the site\'s to set — a shade that passes is suggested beside each colour pair',
  'axe.link-in-text-block': 'an underline is a CSS change on the site',
  'heading-skip': 'map the heading and give it the right level',
  'h1-missing': 'decide which element is the page heading', 'h1-multiple': 'decide which one is the page heading',
  'heading-empty': 'decide whether it is a heading at all',
  'landmarks-missing': 'map the landmarks — Config does this',
  'skip-link-missing': 'Config adds skip links',
  'aria-hidden-focusable': 'use "must not be reachable" on it, or un-hide it',
};

/**
 * Show the results of the scan that was just run, and only those.
 *
 * The Scan tab holds two: the page's own faults, and whether the mappings
 * still work. They are different questions with different answers, and having
 * both on screen made the second look like part of the first — a report saying
 * "36 links have no accessible text" directly above "45 tested · 5 failing"
 * reads as one finding about one thing.
 *
 * Hidden, not cleared: the other run's results are still there and come back
 * when it is run again.
 */
// Which of the two Scan-tab cards (Page Content / Saved Mappings) is showing.
// Same shape as the Picker's Scan/Mappings split (setPickerPane) — one card
// visible at a time instead of both stacked, so pressing a scan's own button
// is always pressing something you're already looking at.
function setScanChoicePane(name) {
  const pane = name === 'mappings' ? 'mappings' : 'content';
  document.querySelectorAll('.scan-choice-tab').forEach((b) => {
    const on = b.dataset.scanpane === pane;
    b.classList.toggle('active', on);
    b.setAttribute('aria-selected', String(on));
  });
  const content = document.getElementById('scanPaneContent');
  const mappings = document.getElementById('scanPaneMappings');
  if (content) content.hidden = pane !== 'content';
  if (mappings) mappings.hidden = pane !== 'mappings';
  // Each pane's results belong to it. They used to sit below BOTH panes, so
  // the Static pane showed the last mapping run under its own card.
  const s = document.getElementById('scanResultsSection');
  const m = document.getElementById('elemScanSection');
  if (s) s.style.display = pane === 'content' && scanResults.length ? 'block' : 'none';
  if (m) m.style.display = pane === 'mappings' && elemScanResults.length ? 'block' : 'none';
  // The Dynamic pane opens on its last run, not empty: it was kept.
  if (pane === 'mappings' && !elemScanResults.length && !elemScanRunning) {
    loadElemLastRun().then(async (run) => {
      if (!run || !run.results || !run.results.length || elemScanResults.length) return;
      elemScanResults = run.results;
      elemScanActiveStatus = '*';
      elemScanPageFilter = 'here';
      const t = await getTab().catch(() => null); elemScanHereUrl = (t && t.url) || '';
      document.getElementById('elemScanCount').textContent = elemRunCountText(run.results) + ` (saved ${new Date(run.at).toLocaleString()})`;
      renderElemScanFilters(); renderElemScanResults();
      document.getElementById('elemScanClearBtn').style.display = '';
      document.getElementById('elemScanReportRow').style.display = '';
      if (m && document.querySelector('.scan-choice-tab.active')?.dataset.scanpane === 'mappings') m.style.display = 'block';
    }).catch(() => {});
  }
}
function elemRunCountText(results) {
  const tested = results.filter(r => ['pass', 'warn', 'fail'].includes(r.status)).length;
  const failed = results.filter(r => r.status === 'fail').length;
  return `${tested} tested · ${failed} failing`;
}
document.querySelectorAll('.scan-choice-tab').forEach((b) => {
  b.addEventListener('click', () => setScanChoicePane(b.dataset.scanpane));
});
// The sticky switcher sits exactly under the top bar, whatever height the bar
// has right now (it changes with the licence line and the tab card).
{
  const topbar = document.querySelector('.topbar');
  if (topbar) {
    const setH = () => document.documentElement.style.setProperty('--u1-topbar-h', topbar.offsetHeight + 'px');
    setH();
    try { new ResizeObserver(setH).observe(topbar); } catch { window.addEventListener('resize', setH); }
  }
}

function showOnlyScan(which) {
  setScanChoicePane(which === 'mappings' ? 'mappings' : 'content');
  const m = document.getElementById('elemScanSection');
  if (m && which === 'mappings') m.style.display = 'block';
  // And say which of the two the results below belong to. With only one on
  // screen there is nothing else to tell you which question was asked.
  const cards = document.querySelectorAll('#tab-scan .scan-choice-card');
  cards.forEach((c, i) => c.classList.toggle('is-showing',
    (which === 'static' && i === 0) || (which === 'mappings' && i === 1)));
}

// ─────────────────────────────────────────────────────────────────────────────
//  The checklist — the fixed list of questions a page is asked
//
//  Three engines, forty rule names, two severities per rule and a chip for each
//  engine that agreed: the "all findings" view is complete and it is
//  unreadable at a glance — "I cannot understand what the faults are", verbatim.
//  A monitoring report asks a fixed set of plain questions and answers each one
//  PASS or FAIL. This is that: one row per question, in a fixed order, with the
//  evidence beside it — the page title itself, the heading outline, every
//  image's alt — because a title that exists can still be the wrong title, and
//  only a person looking at it can say. Engine findings still count: each one
//  is filed under the question it answers (via SCAN_CONCEPTS), and whatever
//  matches no question goes in one last row, folded.
// ─────────────────────────────────────────────────────────────────────────────
const SCAN_CHECKS = [
  { id: 'title', title: 'Page title', ask: 'Does the tab title say what this page is?',
    rules: ['doc-title'], evidence: 'title' },
  { id: 'lang', title: 'Page language', ask: 'Is the language declared and valid, so screen readers use the right voice?',
    rules: ['lang'], evidence: 'lang' },
  { id: 'headings', title: 'Heading structure', ask: 'One H1, levels in order, none empty, nothing bold pretending — does the outline read like a table of contents?',
    rules: ['h1-missing', 'h1-multiple', 'heading-order', 'heading-empty', 'fake-heading'], evidence: 'headings', needs: 'headings' },
  { id: 'images', title: 'Images', ask: 'Does every meaningful image, icon and SVG have alt text, and is the alt text right?',
    rules: ['img-alt', 'img-alt-filename', 'image-map'], evidence: 'images', needs: 'imagesTotal' },
  { id: 'links', title: 'Link text', ask: 'Does every link say where it goes, on its own — and warn when it opens a new tab?',
    rules: ['link-name', 'link-generic', 'link-newwindow', 'label-mismatch'], needs: 'links' },
  { id: 'buttons', title: 'Button names', ask: 'Does every button, including icon-only and custom ones, have a name?',
    rules: ['button-name'], needs: 'buttons' },
  { id: 'forms', title: 'Form fields', ask: 'Is every field labelled — visibly, once, correctly — and every option group named?',
    rules: ['input-label', 'input-placeholder', 'group-nolabel', 'label-for-broken', 'label-hidden', 'autocomplete'], needs: 'inputs' },
  { id: 'contrast', title: 'Colour contrast', ask: 'Is text readable against its background, and are links told apart by more than colour?',
    rules: ['contrast', 'link-color-only'], engine: 'axe' },
  { id: 'landmarks', title: 'Landmarks', ask: 'Can a screen reader jump to main, navigation, header, footer? (Several unnamed forms/regions are listed as a note.)',
    rules: ['landmarks', 'landmark-structure', 'landmark-noname'], evidence: 'landmarks' },
  { id: 'skip', title: 'Skip link', ask: 'Can the keyboard skip the menu and land on the content?',
    rules: ['skip-link'], evidence: 'skipLink' },
  { id: 'focus', title: 'Keyboard reach and focus order', ask: 'Can everything clickable be reached in a sensible order, with nothing hidden from screen readers while focusable?',
    rules: ['tabindex', 'misleading-role', 'clickable-div', 'aria-hidden-focusable', 'nested-controls', 'scroll-keyboard', 'frame-tabindex', 'accesskey-dup'] },
  { id: 'aria', title: 'ARIA used correctly', ask: 'Are roles and aria-* attributes real, allowed, complete, and in the right container?',
    rules: ['aria-grammar', 'aria-structure'], engine: 'axe' },
  { id: 'structure', title: 'Lists and text structure', ask: 'Are lists real lists, so items are counted and announced?',
    rules: ['list-structure'], engine: 'axe' },
  { id: 'iframes', title: 'Iframes', ask: 'Is every embedded frame titled, each differently?',
    rules: ['frame-title', 'frame-title-dup'], evidence: 'iframes', needs: 'iframes' },
  { id: 'tables', title: 'Data tables', ask: 'Do data tables have header cells, tied to the right columns and rows?',
    rules: ['table-headers', 'table-structure'], needs: 'tables' },
  { id: 'zoom', title: 'Zoom and text spacing', ask: 'Can the page be enlarged, respaced, and turned sideways?',
    rules: ['zoom', 'orientation', 'text-spacing'] },
  { id: 'media', title: 'Media and motion', ask: 'Nothing autoplays, blinks or reloads without a stop; carousels can be paused; video and audio have captions and controls?',
    rules: ['autoplay-audio', 'carousel-nopause', 'video-nocaptions', 'audio-transcript', 'media-nocontrols', 'blinking', 'auto-refresh'] },
  { id: 'widgets', title: 'Custom widgets', ask: 'Do switches, checkboxes, sliders, meters, dialogs and comboboxes announce their state and name?',
    rules: ['switch-nostate', 'checkbox-nostate', 'slider-novalue', 'meter-novalue', 'combobox-noexpanded', 'meter-name', 'dialog-name', 'tooltip-name', 'treeitem-name'] },
  { id: 'ids', title: 'IDs and ARIA references', ask: 'Do ARIA references point at something? (Duplicate ids are listed as a note.)',
    rules: ['dup-id', 'aria-ref-broken'] },
  { id: 'targets', title: 'Touch targets', ask: 'Are tap targets big enough?',
    rules: ['target-size-small'] },
];

const scanConceptOf = (r) => conceptOfRule(r.ruleId);
// Which checklist rows the person has opened. Everything starts folded — a
// page with twelve failing questions used to open all twelve at once, which
// is a wall, not a list — and a row stays open across re-renders (a fix, an
// approval) once it was opened, so the list does not fold under the hand.
const scanOpenChecks = new Set();
document.getElementById('scanResults')?.addEventListener('toggle', (e) => {
  const d = e.target;
  if (!d || !d.matches || !d.matches('details.sc-row[data-check]')) return;
  if (d.open) scanOpenChecks.add(d.dataset.check); else scanOpenChecks.delete(d.dataset.check);
}, true);

// ── What has already been done about each question, on this page ────────────
//
// A passed "Button names" says nothing about WHY it passed. Opened, the row
// now lists the mappings on this page that answer that question — the
// aria-label that named the icon button, the heading that fixed the level —
// each with whether it is on the element right now. The work is documented
// where the question is asked, not only in the drawer.
const SCAN_CHECK_MAPPINGS = {
  headings: { types: ['heading'] },
  links: { types: ['aria-label', 'link', 'link-list'], statics: ['link-newwindow'] },
  buttons: { types: ['aria-label', 'button', 'keyboard-clickable', 'link'] },
  forms: { types: ['form', 'combobox', 'checkbox', 'radio', 'datepicker'], statics: ['input-placeholder'] },
  landmarks: { types: ['breadcrumb'], statics: ['landmark-noname'] },
  focus: { types: ['keyboard-clickable', 'focus-order', 'hide-element', 'keyboard-tabs', 'keyboard-grid'], statics: ['tabindex-positive', 'exclude'] },
  aria: { types: ['menu', 'tabs', 'accordion', 'dialog', 'listbox', 'combobox', 'tooltip', 'carousel', 'pagination', 'grid', 'table', 'loading'] },
  structure: { statics: ['list-stray-br'] },
  tables: { types: ['table', 'grid'], statics: ['table-noheaders'] },
  zoom: { statics: ['zoom-disabled'] },
  media: { types: ['carousel'], statics: ['autoplay-audio'] },
  widgets: { types: ['checkbox', 'radio', 'listbox', 'combobox', 'tooltip', 'loading', 'datepicker'] },
  ids: { statics: ['aria-ref-broken'] },
  contrast: { statics: ['contrast'] },
  lang: { statics: ['lang-missing'] },
};
let scanMappingStatus = []; // [{ key, id, fixNo, type, primary, custom, label, state }] for this page
async function loadScanMappingStatus() {
  scanMappingStatus = [];
  try {
    const tab = await getTab();
    if (!isInjectable(tab)) return;
    const key = storageKey('mappings', currentHostname);
    const list = ((await U1Store.get([key]))[key] || []).filter(m => m && typeof m === 'object' && (m.type || m.custom));
    if (!list.length) return;
    const present = await selectorsPresentOnPage(list.map(m => m.primary || m.firstArg || ''));
    const hereUrl = cleanPageUrl(tab.url);
    const here = list.filter(m => m.custom === 'staticFix' || mappingOnPage(m, present, hereUrl));
    if (!here.length) return;
    const probe = here.map(m => ({ key: mappingKey(m), primary: m.primary || m.firstArg || '', type: m.type || '', custom: m.custom || '', label: (m.config && m.config.label) || '' }));
    const [res] = await chrome.scripting.executeScript({
      target: { tabId: tab.id }, world: 'MAIN',
      func: (items) => items.map(it => {
        if (it.custom === 'staticFix') return { key: it.key, state: (window.__u1Statics && window.__u1Statics[it.primary]) ? 'applied' : 'saved' };
        let el = null; try { el = document.querySelector(it.primary); } catch (e) {}
        if (!el) return { key: it.key, state: 'missing' };
        const says = (el.getAttribute('aria-label') || el.getAttribute('alt') || el.getAttribute('title') || (el.textContent || '')).replace(/\s+/g, ' ').trim().slice(0, 50);
        const tag = el.tagName.toLowerCase();
        const level = el.getAttribute('aria-level') || (/^h[1-6]$/.test(tag) ? tag.slice(1) : '');
        const base = { key: it.key, says, tag, level };
        if (it.custom === 'ariaLabel') return { ...base, state: el.getAttribute('aria-label') ? 'applied' : 'saved' };
        if (it.type === 'heading') return { ...base, state: (el.getAttribute('aria-level') || el.getAttribute('role') === 'heading') ? 'applied' : 'saved' };
        const touched = Array.from(el.attributes).some(a => /^(role|tabindex)$|^aria-|^u1st-/.test(a.name)) || !!el.querySelector('[role],[u1st-avoid-change-detection]');
        return { ...base, state: touched ? 'applied' : 'saved' };
      }),
      args: [probe],
    });
    const states = new Map(((res && res.result) || []).map(x => [x.key, x]));
    scanMappingStatus = here.map(m => {
      const st = states.get(mappingKey(m)) || {};
      return {
        key: mappingKey(m), id: m.id || '', fixNo: m.fixNo, type: m.custom === 'staticFix' ? 'static fix' : (m.type || m.custom || ''),
        primary: m.custom === 'staticFix' ? ((SCAN_RULES[m.primary] || {}).title || m.primary) : (m.primary || m.firstArg || ''),
        custom: m.custom || '', staticRule: m.custom === 'staticFix' ? m.primary : '', rawType: m.type || '',
        label: (m.config && m.config.label) || '', level: (m.config && m.config.level) || '',
        says: st.says || '', tag: st.tag || '', nowLevel: st.level || '', state: st.state || 'saved',
      };
    });
  } catch { scanMappingStatus = []; }
}
function scanCheckMappingsHtml(check) {
  const spec = SCAN_CHECK_MAPPINGS[check.id];
  if (!spec || !scanMappingStatus.length) return '';
  const mine = scanMappingStatus.filter(m => (spec.types || []).includes(m.rawType) || (m.staticRule && (spec.statics || []).includes(m.staticRule)) || (check.id === 'links' && m.custom === 'ariaLabel') || (check.id === 'buttons' && m.custom === 'ariaLabel'));
  if (!mine.length) return '';
  const st = (m) => m.state === 'applied' ? '<span class="sc-lm">✓ on the page</span>' : m.state === 'missing' ? '<strong class="sc-bad">element not on the page</strong>' : '<span class="sc-lm sc-warnish">saved, not seen on the element</span>';
  // In words: what the element SAYS and what was done to it. The selector is
  // the tooltip, not the line.
  const line = (m) => {
    if (m.custom === 'staticFix') return `Rule: <strong>${escapeHtml(m.primary)}</strong> — on every matching element`;
    const what = m.says ? `“${escapeHtml(m.says)}”` : `<code>${escapeHtml(m.primary)}</code>`;
    if (m.custom === 'ariaLabel') return `${m.tag === 'a' ? 'Link' : m.tag === 'button' ? 'Button' : 'Element'} named ${what}`;
    if (m.rawType === 'heading') return `Heading ${what} → level ${escapeHtml(String(m.level || m.nowLevel || '?'))}`;
    return `${escapeHtml(m.type.charAt(0).toUpperCase() + m.type.slice(1))} ${what}`;
  };
  return `<details class="sc-evidence sc-fixed"><summary><span class="sc-ev-k">Already handled here — ${mine.length} mapping${mine.length === 1 ? '' : 's'}</span> <span class="sc-ev-note">— other elements on this page, fixed earlier. The findings above are what is still open.</span></summary>` +
    `<ul class="sc-imgs">${mine.map(m => `<li${m.custom !== 'staticFix' ? ` data-hl-sel="${escapeHtml(m.primary)}" data-hl-idx="0" title="${escapeHtml(m.primary)} — hover to see it on the page"` : ''}>` +
      `${line(m)} ${st(m)}${m.id ? ` <span class="mh-id">${escapeHtml(m.id)}</span>` : ''}</li>`).join('')}</ul></details>`;
}

/** Findings filed under each check, plus the ones no check claims. */
function scanChecklistBuckets() {
  const byCheck = new Map(SCAN_CHECKS.map(c => [c.id, []]));
  const rest = [];
  for (const r of scanResults) {
    const concept = scanConceptOf(r);
    const c = SCAN_CHECKS.find(ch => ch.rules.includes(concept) || ch.rules.includes(r.ruleId));
    if (c) byCheck.get(c.id).push(r); else rest.push(r);
  }
  return { byCheck, rest };
}

/** The evidence block for a check that PASSED — what a person confirms. */
function scanEvidenceHtml(check, inv) {
  if (!inv || !check.evidence) return '';
  const esc = escapeHtml;
  switch (check.evidence) {
    case 'title':
      return inv.title ? `<div class="sc-evidence"><span class="sc-ev-k">Title</span> <strong>${esc(inv.title)}</strong> <span class="sc-ev-note">— confirm it names THIS page, not just the site.</span></div>` : '';
    case 'lang':
      return inv.lang ? `<div class="sc-evidence"><span class="sc-ev-k">lang</span> <code>${esc(inv.lang)}</code> <span class="sc-ev-note">— confirm it matches the language of the text.</span></div>` : '';
    case 'headings': {
      if (!inv.headings || !inv.headings.length) return '';
      return `<div class="sc-evidence"><span class="sc-ev-k">Outline</span> <span class="sc-ev-note">— read it top to bottom: does it describe the page?</span>` +
        `<ol class="sc-outline">${inv.headings.map(h =>
          `<li style="--lvl:${h.level}" data-hl-sel="${esc(h.selector || '')}" data-hl-idx="${h.idx || 0}" title="Hover to see it on the page"><span class="sc-h-lvl">H${h.level}</span> <span class="sc-h-txt">${esc(h.text || '(empty)')}</span></li>`).join('')}</ol></div>`;
    }
    case 'images': {
      if (!inv.images || !inv.images.length) return '';
      const named = inv.images.filter(i => i.alt && !i.decorative);
      const deco = inv.images.filter(i => i.decorative);
      const okId = (i) => altOkId(i.src, i.alt);
      const pending = named.filter(i => !scanAltOk.has(okId(i)));
      return `<div class="sc-evidence"><span class="sc-ev-k">${inv.imagesTotal} image${inv.imagesTotal === 1 ? '' : 's'}</span> ` +
        `<span class="sc-ev-note">— ${named.length} with alt text, ${deco.length} marked decorative. Read each alt: does it say what the picture is FOR? Tick the ones that do${pending.length ? ` (${pending.length} unticked)` : ''}.</span>` +
        (pending.length > 1 ? ` <button type="button" class="btn-outline btn-xs scan-alt-ok-all" data-alt-ids="${esc(pending.map(okId).join('\n'))}">✓ All ${pending.length} are right</button>` : '') +
        `<ul class="sc-imgs">${inv.images.map(i => {
          const approved = !i.decorative && i.alt && scanAltOk.has(okId(i));
          const tick = i.decorative || !i.alt ? '' : approved
            ? `<button type="button" class="scan-alt-ok on" data-alt-id="${esc(okId(i))}" title="Approved — click to take it back">✓ approved</button>`
            : `<button type="button" class="scan-alt-ok" data-alt-id="${esc(okId(i))}" title="This alt says what the picture is for">approve</button>`;
          return `<li${approved ? ' class="is-ok"' : ''} data-hl-sel="${esc(i.selector || '')}" data-hl-idx="${i.idx || 0}" title="Hover to see it on the page"><span class="sc-img-line"><code>${esc(i.src || i.selector)}</code> → ${i.decorative ? '<em>decorative (alt="")</em>' : i.alt ? `“${esc(i.alt)}”` : '<strong class="sc-bad">no alt</strong>'}</span>${tick}</li>`;
        }).join('')}</ul></div>`;
    }
    case 'landmarks': {
      const L = inv.landmarks || {};
      const parts = [['main', L.main], ['nav', L.nav], ['header', L.header], ['footer', L.footer], ['search', L.search]]
        .map(([k, n]) => k === 'search' && !n && L.searchUnmarked
          ? `<span class="sc-lm sc-warnish" title="A search field is on the page but nothing carries role=search — name it with an aria-label mapping or add the role">search: found, not marked</span>`
          : `<span class="sc-lm${n ? '' : ' sc-bad'}">${k}: ${n || 0}</span>`).join(' ');
      return `<div class="sc-evidence"><span class="sc-ev-k">Landmarks</span> ${parts}</div>`;
    }
    case 'skipLink': {
      const list = inv.skipLinks && inv.skipLinks.length ? inv.skipLinks : (inv.skipLink ? [{ text: inv.skipLink, href: '', lands: true }] : []);
      if (!list.length) return '';
      return `<div class="sc-evidence"><span class="sc-ev-k">${list.length} skip link${list.length === 1 ? '' : 's'}</span> <span class="sc-ev-note">— Tab once on a fresh load: do they appear, and does each land where it says?</span>` +
        `<ul class="sc-imgs">${list.map(l => `<li${l.target ? ` data-hl-sel="${esc(l.target)}" data-hl-idx="0" title="Hover to see where it lands"` : ''}>“${esc(l.text)}” → <code>${esc(l.href)}</code> ${l.lands ? '<span class="sc-lm">lands</span>' : '<strong class="sc-bad">target missing</strong>'}</li>`).join('')}</ul></div>`;
    }
    case 'iframes':
      return (inv.iframes && inv.iframes.length) ? `<div class="sc-evidence"><span class="sc-ev-k">${inv.iframes.length} iframe${inv.iframes.length === 1 ? '' : 's'}</span>` +
        `<ul class="sc-imgs">${inv.iframes.map(f => `<li data-hl-sel="${esc(f.selector)}" data-hl-idx="${f.idx || 0}" title="Hover to see it on the page"><code>${esc(f.selector)}</code> → ${f.title ? `“${esc(f.title)}”` : '<strong class="sc-bad">no title</strong>'}</li>`).join('')}</ul></div>` : '';
  }
  return '';
}

function renderScanChecklist(wrap) {
  const inv = scanInventory;
  const { byCheck, rest } = scanChecklistBuckets();
  const hasInv = !!inv;
  const item = scanItemHtml;
  const rows = SCAN_CHECKS.map(c => {
    const allRows = byCheck.get(c.id) || [];
    const ignoredHere = allRows.filter(isIgnored);
    const rows = scanShowIgnored ? allRows : allRows.filter(r => !isIgnored(r));
    const faults = rows.filter(r => !r.note && !r.resolved && !isIgnored(r));
    const n = faults.length;
    // "Nothing to check": the page holds none of the thing this asks about.
    const none = hasInv && c.needs && !(Array.isArray(inv[c.needs]) ? inv[c.needs].length : inv[c.needs]);
    // A question only the engine answers, on a scan where it did not run, is
    // unanswered — not passed.
    const unanswered = !n && c.engine && !scanEnginesRan.includes(c.engine);
    // Notes (duplicate ids) are listed, not failed: nobody is blocked by them.
    const state = n ? 'fail' : rows.some(r => r.note) ? 'note' : none ? 'none' : unanswered ? 'unknown' : 'pass';
    const worst = faults.reduce((w, r) => (SEVERITY_RANK[r.severity] ?? 9) < (SEVERITY_RANK[w] ?? 9) ? r.severity : w, 'Low');
    const badge = state === 'fail' ? `<span class="sc-state fail">✕ ${n} to fix</span>`
                : state === 'note' ? `<span class="sc-state note">ⓘ ${rows.length} note${rows.length === 1 ? '' : 's'}</span>`
                : state === 'none' ? `<span class="sc-state none">— none on page</span>`
                : state === 'unknown' ? `<span class="sc-state none">? not checked</span>`
                : `<span class="sc-state pass">✓ passed</span>`;
    // Fix-all where a rule offers it, per rule present.
    // Only what is still open: a "Fix all 39" under a row that reads
    // "All 39 fixed" is the button that asks to be pressed again.
    const ruleIds = [...new Set(faults.map(r => r.ruleId))];
    const actions = (c.id === 'contrast' ? scanContrastActionsHtml(rows) : '') +
      ruleIds.map(rid => scanRuleActionHtml(rid, faults.filter(r => r.ruleId === rid))).filter(Boolean).join('') +
      scanMapAllHtml(rows);
    const evidence = state !== 'none' ? scanEvidenceHtml(c, inv) : '';
    const handled = scanCheckMappingsHtml(c);
    const wcag = [...new Set(rows.map(r => r.wcag).filter(Boolean))];
    return `
      <details class="sc-row ${state}${state === 'fail' ? ' sev-' + worst.toLowerCase() : ''}" data-check="${c.id}"${scanOpenChecks.has(c.id) ? ' open' : ''}>
        <summary>
          ${badge}
          <span class="sc-title">${escapeHtml(c.title)}</span>
          <span class="sc-ask">${escapeHtml(c.ask)}</span>
          ${wcag.length ? `<span class="wcag-chip">WCAG ${escapeHtml(wcag.join(', '))}</span>` : ''}
        </summary>
        ${evidence}
        ${actions}
        ${rows.length ? scanRowsHtml(rows) : ''}
        ${ignoredHere.length ? `<div class="scan-ignored-note"><button type="button" class="btn-ghost btn-xs scan-show-ignored">${scanShowIgnored ? 'Hide' : 'Show'} ${ignoredHere.length} ignored</button></div>` : ''}
        ${handled}
      </details>`;
  });
  const restHtml = rest.length ? `
      <details class="sc-row other" data-check="other">
        <summary>
          <span class="sc-state other">${rest.length} more</span>
          <span class="sc-title">Other findings</span>
          <span class="sc-ask">Outside the questions above — look when the list above is clean.</span>
        </summary>
        ${rest.map(item).join('')}
      </details>` : '';
  const faultsIn = (c) => (byCheck.get(c.id) || []).filter(r => !r.note && !r.resolved && !isIgnored(r)).length;
  const passed = SCAN_CHECKS.filter(c => !faultsIn(c) && !(hasInv && c.needs && !(Array.isArray(inv[c.needs]) ? inv[c.needs].length : inv[c.needs])) && !(c.engine && !scanEnginesRan.includes(c.engine))).length;
  const failed = SCAN_CHECKS.filter(c => faultsIn(c)).length;
  wrap.innerHTML =
    `<div class="sc-summary"><strong>${passed}</strong> passed · <strong>${failed}</strong> need work` +
    (hasInv ? '' : ' · <span class="sc-ev-note">evidence (title, outline, alts) appears after a fresh scan</span>') + `</div>` +
    rows.join('') + restHtml;
}

// Rules whose findings are one decision taken many times — forty new-tab
// links, a dozen duplicate ids. One row, the elements listed inside it, one
// fix for all of them. A row each was forty rows saying the same sentence.
const SCAN_GROUPED = new Set(['link-newwindow', 'dup-ids', 'list-stray-br']);
function scanRowsHtml(rows) {
  const out = [];
  const grouped = new Map();
  for (const r of rows) {
    if (SCAN_GROUPED.has(r.ruleId)) { if (!grouped.has(r.ruleId)) grouped.set(r.ruleId, []); grouped.get(r.ruleId).push(r); }
    else out.push(scanItemHtml(r));
  }
  for (const [ruleId, list] of grouped) out.unshift(scanGroupedItemHtml(ruleId, list));
  return out.join('');
}
function scanGroupedItemHtml(ruleId, rows) {
  const live = rows.filter(r => !r.resolved && !isIgnored(r));
  const r0 = rows[0];
  const sev = (r0.note ? 'Note' : (r0.severity || '')).toLowerCase();
  const li = (r) => {
    const t = scanTargetOf(r);
    const where = r.href || r.detail || '';
    return `<li class="scan-el${r.resolved ? ' is-fixed' : ''}${r.stillAfterFix ? ' is-still' : ''}"${t.sel ? ` data-hl-sel="${escapeHtml(t.sel)}" data-hl-idx="${t.idx}" title="Hover to see it on the page"` : ''}>` +
      `<span class="scan-el-state">${r.resolved ? '✓ fixed' : r.stillAfterFix ? '! still' : '•'}</span> ` +
      `<span class="scan-el-text">${escapeHtml(r.text || r.selector || '(no text)')}</span>` +
      (where ? ` <code class="scan-el-where">${escapeHtml(String(where).slice(0, 70))}</code>` : '') + `</li>`;
  };
  return `
    <div class="scan-item scan-item-group sev-${escapeHtml(sev)}${r0.note ? ' is-note' : ''}${!live.length ? ' is-resolved' : ''}" data-scan-idx="${scanResults.indexOf(r0)}">
      <div class="scan-item-main">
        <span class="scan-sev-badge sev-${escapeHtml(sev)}">${escapeHtml(!live.length ? 'Fixed' : r0.note ? 'Note' : (r0.severity || ''))}</span>
        <span class="scan-issue-title">${escapeHtml(r0.issue || '')} <span class="scan-group-n">${live.length}${live.length !== rows.length ? ` / ${rows.length}` : ''}</span></span>
        ${r0.wcag ? `<span class="wcag-chip">WCAG ${escapeHtml(r0.wcag)}</span>` : ''}
      </div>
      <details class="scan-why" open>
        <summary>${live.length ? `The ${live.length} element${live.length === 1 ? '' : 's'} — hover one to see it` : `All ${rows.length} fixed`}</summary>
        <ul class="scan-els">${rows.map(li).join('')}</ul>
        <div class="scan-why-body">
          <div class="scan-why-line"><strong>Why:</strong> ${escapeHtml(r0.why || '')}</div>
          <div class="scan-why-line"><strong>Fix:</strong> ${escapeHtml(r0.fix || '')}</div>
        </div>
      </details>
    </div>`;
}

/** One finding row — shared by both views so the highlight click keeps working. */
// The precise handle for THIS element on the page: axe's unique path when the
// finding came with one, otherwise our short selector plus its index.
function scanTargetOf(r) {
  return r.target ? { sel: r.target, idx: 0 } : { sel: r.selector || '', idx: r.idx || 0 };
}
function scanItemHtml(r) {
  const gi = scanResults.indexOf(r);
  const t = scanTargetOf(r);
  const hover = t.sel ? ` data-hl-sel="${escapeHtml(t.sel)}" data-hl-idx="${t.idx}" title="Hover to see it on the page"` : '';
  const ignored = isIgnored(r);
  return `
    <div class="scan-item sev-${(r.severity || '').toLowerCase()}${r.note ? ' is-note' : ''}${r.resolved ? ' is-resolved' : ''}${ignored ? ' is-ignored' : ''}" data-scan-idx="${gi}"${hover}>
      <div class="scan-item-main">
        <span class="scan-sev-badge sev-${(r.severity || '').toLowerCase()}">${escapeHtml(ignored ? 'Ignored' : r.resolved ? 'Fixed' : r.note ? 'Note' : (r.severity || ''))}</span>
        <span class="scan-issue-title">${escapeHtml(r.issue || '')}${t.sel ? ` <button class="scan-hl" title="Show it on the page" aria-label="Show it on the page">🔍</button>` : ''}</span>
        ${r.wcag ? `<span class="wcag-chip">WCAG ${escapeHtml(r.wcag)}</span>` : ''}
        <button class="btn-ghost btn-xs scan-ignore" title="${ignored ? 'Ignored on this site — click to bring it back' : 'Not mine to fix / a false alarm — hide it on this site'}">${ignored ? '↺ un-ignore' : '✕ ignore'}</button>
      </div>
      ${ignored ? '' : `<div class="scan-item-actions">${scanMapButtonHtml(r)}</div>`}
      <div class="scan-context">${escapeHtml(r.cat)}${r.text ? ` · ${r.tag ? `${({ select: 'dropdown', a: 'link', button: 'button', input: 'field', img: 'image', h1: 'heading', h2: 'heading', h3: 'heading', h4: 'heading', h5: 'heading', h6: 'heading' })[r.tag] || '<' + escapeHtml(r.tag) + '>'} ` : ''}“${escapeHtml(r.text)}”` : ''}${r.detail ? ` <span class="scan-detail">(${escapeHtml(r.detail)})</span>` : ''}${r.href && !r.detail ? ` <span class="scan-detail">(${escapeHtml(String(r.href).slice(0, 70))})</span>` : ''}${r.data && r.data.fgColor ? ` <span class="scan-detail">— ${escapeHtml(r.data.fgColor)} on ${escapeHtml(r.data.bgColor || '?')}, ${escapeHtml(String(r.data.contrastRatio || '?'))}:1 (needs ${escapeHtml(String(r.data.expectedContrastRatio || '4.5:1').replace(/:1$/, ''))}:1)</span>` : ''}</div>
      <details class="scan-why">
        <summary>Why &amp; how to fix</summary>
        <div class="scan-why-body">
          <div class="scan-why-line"><strong>Why:</strong> ${escapeHtml(r.why || '')}</div>
          <div class="scan-why-line"><strong>Fix:</strong> ${escapeHtml(r.fix || '')}</div>
          ${r.selector ? `<div class="scan-why-line scan-sel"><strong>Selector:</strong> <code>${escapeHtml(r.selector)}</code></div>` : ''}
          ${r.engineDetail ? `<div class="scan-why-line scan-sel"><strong>Markup:</strong> <code>${escapeHtml(r.engineDetail.slice(0, 200))}</code></div>` : ''}
        </div>
      </details>
    </div>`;
}

// ── From a finding to its mapping, in one press ──────────────────────────────
//
// "No bulk fix — map the heading and give it the right level" is true and it
// is a chore: read the selector, open the builder, pick heading, type the
// level, save. The finding already knows all four. So the two findings that
// ARE one mapping away get a button that makes it: a skipped heading level
// becomes a heading mapping at the level the outline needs; a vague link
// becomes the same aria-label mapping the AI route builds, its card heading
// looked up the same way. Everything else still needs a person's words.
function scanWantedLevel(r) {
  const m = /H(\d)\s*→\s*H(\d)/.exec(r.detail || '');
  return m ? Math.min(6, +m[1] + 1) : 0;
}
// Findings whose whole fix is a name: an aria-label mapping settles them.
const SCAN_NAMEABLE = new Set(['select-name', 'input-nolabel', 'aria-input-field-name', 'button-noname']);
function scanMapButtonHtml(r) {
  if (!r.selector) return '';
  if (r.resolved) return `<span class="scan-mapped">✓ mapped — gone from the page</span>`;
  if (r.mapped) return `<span class="scan-mapped is-still">✓ mapped — still reads as a fault, check the mapping</span>`;
  if (r.ruleId === 'heading-skip' && scanWantedLevel(r)) {
    return `<button class="btn-primary btn-xs scan-map" data-map="heading" title="Save a heading mapping at H${scanWantedLevel(r)} and apply it">Map it → H${scanWantedLevel(r)}</button>`;
  }
  if (r.ruleId === 'link-generic') {
    // Two ways to name it, because a mapping already exists for most of
    // these: a card of "Learn More" links is usually one aria-label mapping
    // per card, naming each link from ITS card's own heading selector — not
    // literal text typed per link. That mapping is what "Map it -> name from
    // card" saves (headingSelector, the same route the AI route and the
    // "Read more" batch fix use). The free-text box beside it is for the one
    // that has no card heading to borrow, where a person types the name
    // directly. Neither is guessed at silently; both save a mapping and
    // apply on the page.
    return `<span class="scan-name-box">` +
      `<button class="btn-primary btn-xs scan-map" data-map="aria-label" title="Name it after its card's heading -- the same mapping the AI route and the Read-more batch fix build">Map it → name from card</button>` +
      `<span class="scan-name-or">or</span>` +
      `<input type="text" class="scan-name-input" placeholder="Type what “${escapeHtml((r.text || 'this link').slice(0, 20))}” is about" spellcheck="false" title="No card heading to borrow -- type the name directly">` +
      `<button class="btn-outline btn-xs scan-map" data-map="label">Save as mapping</button></span>`;
  }
  // A field, dropdown or button with no name: the same typed-name route the
  // vague link has. The scan shows the element; the person says what it is
  // for ("Language"), and that becomes an aria-label mapping — saved, applied
  // now, re-applied on every load, exported. It had no button before, so the
  // only way to fix it was to leave the scan and find it again in the Picker.
  if (SCAN_NAMEABLE.has(r.ruleId)) {
    return `<span class="scan-name-box">` +
      `<input type="text" class="scan-name-input" placeholder="Type what this ${r.ruleId === 'button-noname' ? 'button does' : 'field is for'}" spellcheck="false" title="Becomes the element's aria-label">` +
      `<button class="btn-primary btn-xs scan-map" data-map="label">Map it → name</button></span>`;
  }
  if (r.ruleId === 'img-alt-filename' && altOkIdOfFinding(r)) {
    return `<button class="btn-outline btn-xs scan-alt-ok" data-alt-id="${escapeHtml(altOkIdOfFinding(r))}" title="The alt does say what the picture is for — drop this finding">✓ alt is right</button>`;
  }
  return '';
}

// Approving alts: the finding goes at once, the evidence list ticks, and the
// question turns green the moment the last one is approved.
document.getElementById('scanResults')?.addEventListener('click', async (e) => {
  const one = e.target.closest('.scan-alt-ok');
  const all = e.target.closest('.scan-alt-ok-all');
  if (!one && !all) return;
  e.preventDefault(); e.stopPropagation();
  const ids = one ? [one.dataset.altId] : (all.dataset.altIds || '').split('\n').filter(Boolean);
  const on = one ? !one.classList.contains('on') : true;
  await setAltOk(ids, on);
  if (on) scanResults = dropApprovedAlts(scanResults);
  else await refreshScanAfterMapping();
  renderScanFilters();
  renderScanResults();
}, true);

/** "Map all N headings" — the same button, once, for every skipped level in the outline. */
function scanMapAllHtml(rows) {
  const todo = rows.filter(r => r.ruleId === 'heading-skip' && r.selector && !r.mapped && scanWantedLevel(r));
  if (todo.length < 2) return '';
  return `<div class="scan-group-fix"><button class="btn-primary btn-xs scan-map-all" data-map-all="heading">Map all ${todo.length} headings</button>` +
    `<span class="scan-group-does">Save a heading mapping for each skipped level (${todo.map(r => 'H' + scanWantedLevel(r)).join(', ')}) and apply them — one press, then tick them in Mappings.</span></div>`;
}

/**
 * Build and save the one mapping a finding is away from. Returns the template,
 * or null when the user cancelled the save. Throws with a sentence for the
 * notice when the element cannot be pinned down.
 */
async function scanMapCore(r, kind, tabId, opts) {
  // The scan's selector is short on purpose (`h4`, `a.externalLink`) and can
  // match more than this one element. Resolve THIS one — by its index, then by
  // its text — and name it with the builder every other mapping's selector
  // comes from.
  const primary = await inPage(tabId, (sel, idx, text) => {
    const S = window.__u1SelectorIntel;
    let els = [];
    try { els = Array.from(document.querySelectorAll(sel)); } catch (e) { return ''; }
    if (!els.length) return '';
    const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();
    const el = (text && els[idx] && norm(els[idx].textContent) === norm(text) ? els[idx] : null)
      || els.find(e => norm(e.textContent) === norm(text)) || els[idx] || (els.length === 1 ? els[0] : null);
    if (!el) return '';
    const out = S.robustSelector(el);
    return (out && S.isU1Valid(out)) ? out : '';
  }, [r.selector, r.idx || 0, r.text || '']);
  if (!primary) throw new Error(`Could not pin down "${r.text || r.selector}" on the page — map it from the Picker.`);

  let tpl;
  if (kind === 'heading') {
    tpl = buildTemplate('heading', primary, {}, { level: scanWantedLevel(r) });
  } else if (kind === 'label') {
    const label = String((opts && opts.label) || '').trim();
    if (!label) throw new Error('Type the name first — that text becomes its aria-label.');
    tpl = buildTemplate('aria-label', primary, {}, { label });
  } else {
    const card = await inPage(tabId, (s) => {
      const S = window.__u1SelectorIntel;
      return S && S.cardHeadingFor ? S.cardHeadingFor(s) : null;
    }, [primary]);
    if (!card || !card.heading) throw new Error(`No heading found beside "${r.text}" — name this link by hand from the Picker (aria-label).`);
    tpl = buildTemplate('aria-label', primary, {}, { middleText: 'about', headingSelector: card.heading });
  }
  const saved = await saveMappingEntry(tpl, { refreshUi: false });
  if (saved && saved.cancelled) return null;
  try {
    const res = tpl.custom
      ? await applyOne(tpl.type, tpl.firstArg || tpl.primary, tpl.config, tpl.custom, tpl)
      : await applyMappingsBatch([{ type: tpl.type, primary: tpl.primary, firstArg: tpl.firstArg, config: tpl.config, overwriteRole: tpl.overwriteRole }]);
    tpl.__applied = !!(res && (res.ok || (res.results && res.results.some(x => x && x.ok))));
  } catch { tpl.__applied = false; }
  // A heading level is two attributes; whatever the engine's gate did, they
  // are on the element when this returns. Same rule the patch applies.
  if (kind === 'heading') {
    try {
      await chrome.scripting.executeScript({
        target: { tabId }, world: 'MAIN',
        func: (sel, n) => {
          document.querySelectorAll(sel).forEach((el) => {
            if (/^H[1-6]$/.test(el.tagName)) { if (+el.tagName.charAt(1) === n) el.removeAttribute('aria-level'); else el.setAttribute('aria-level', String(n)); }
            else { el.setAttribute('role', 'heading'); el.setAttribute('aria-level', String(n)); }
          });
        },
        args: [primary, scanWantedLevel(r)],
      });
      tpl.__applied = true;
    } catch {}
  }
  r.mapped = true;
  return tpl;
}

async function scanMapFinding(r, btn) {
  const status = document.getElementById('scanStatus');
  const tab = await getTab();
  if (!isInjectable(tab)) { showNotice(status, 'Cannot run on this page.', 'error', 4000); return; }
  btn.disabled = true; btn.textContent = 'Mapping…';
  try {
    const input = btn.parentElement && btn.parentElement.querySelector('.scan-name-input');
    const tpl = await scanMapCore(r, btn.dataset.map, tab.id, input ? { label: input.value } : undefined);
    if (!tpl) { btn.disabled = false; btn.textContent = 'Map it'; return; }
    loadMappingsList(); refreshExportInfo();
    await refreshScanAfterMapping();
    showNotice(status, `Saved ${tpl.type} ${tpl.primary}${tpl.__applied ? ' and applied on the page' : ''}. It is in Mappings now — tick it there once you have checked it.`, 'success', 8000);
  } catch (e) {
    btn.disabled = false; btn.textContent = 'Map it';
    showNotice(status, e.message, 'error', 9000);
  }
}

async function scanMapAll(btn) {
  const status = document.getElementById('scanStatus');
  const tab = await getTab();
  if (!isInjectable(tab)) { showNotice(status, 'Cannot run on this page.', 'error', 4000); return; }
  const todo = scanResults.filter(r => r.ruleId === 'heading-skip' && r.selector && !r.mapped && scanWantedLevel(r));
  btn.disabled = true;
  let done = 0; const failed = [];
  for (const r of todo) {
    btn.textContent = `Mapping ${done + 1}/${todo.length}…`;
    try {
      const tpl = await scanMapCore(r, 'heading', tab.id);
      if (!tpl) break; // cancelled — stop, keep what was saved
      done++;
    } catch (e) { failed.push(`"${r.text || r.selector}"`); }
  }
  loadMappingsList(); refreshExportInfo();
  await refreshScanAfterMapping();
  const tail = failed.length ? ` Could not pin down ${failed.join(', ')} — map those from the Picker.` : '';
  showNotice(status, `${done} heading mapping${done === 1 ? '' : 's'} saved and applied.${tail} Tick them in Mappings once you have checked them.`, failed.length ? 'warn' : 'success', 9000);
}

// ── Contrast: one darker shade per colour pair, for every element in it ────
//
// axe reports the pair behind each faint text; twelve "here"s on white are
// one pair. The darkening keeps the hue and drops lightness until the pair
// meets its required ratio; the person approves it once per pair and the
// bundle ships it as a stylesheet rule on those exact elements.
function hexToRgb(h) { const m = /^#?([0-9a-f]{6})$/i.exec(String(h || '').trim()); if (!m) return null; const n = parseInt(m[1], 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function rgbToHex([r, g, b]) { return '#' + [r, g, b].map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join(''); }
function relLum([r, g, b]) { const f = v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }; return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b); }
function contrastOf(a, b) { const x = relLum(a), y = relLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
function darkenToContrast(fgHex, bgHex, need) {
  const fg = hexToRgb(fgHex), bg = hexToRgb(bgHex || '#ffffff');
  if (!fg || !bg) return null;
  const towardsDark = relLum(bg) > 0.4;
  let c = fg.slice();
  for (let i = 0; i < 40 && contrastOf(c, bg) < need; i++) c = c.map(v => towardsDark ? v * 0.92 : v + (255 - v) * 0.12);
  return contrastOf(c, bg) >= need ? rgbToHex(c) : (towardsDark ? '#000000' : '#ffffff');
}
function scanContrastPairs(rows) {
  const pairs = new Map();
  for (const r of rows) {
    if (!r.data || !r.data.fgColor || r.resolved) continue;
    const k = `${r.data.fgColor}|${r.data.bgColor || ''}|${r.data.expectedContrastRatio || '4.5:1'}`;
    if (!pairs.has(k)) pairs.set(k, { fg: r.data.fgColor, bg: r.data.bgColor || '#ffffff', need: parseFloat(String(r.data.expectedContrastRatio || '4.5')) || 4.5, rows: [] });
    pairs.get(k).rows.push(r);
  }
  return [...pairs.values()];
}
function scanContrastActionsHtml(rows) {
  // Colours are the site's to set. What the scan gives is the shade that
  // would pass — same hue, darker — beside each colour pair, and the CSS to
  // hand the developers. Nothing is applied.
  const pairs = scanContrastPairs(rows.filter(r => conceptOfRule(r.ruleId) === 'contrast'));
  if (!pairs.length) return '';
  return pairs.map(p => {
    const to = darkenToContrast(p.fg, p.bg, p.need);
    const css = `/* ${p.rows.length} element${p.rows.length === 1 ? '' : 's'}: ${p.fg} on ${p.bg} is ${p.rows[0].data.contrastRatio || '?'}:1, needs ${p.need}:1 */\ncolor: ${to};`;
    return `<div class="scan-group-fix is-manual scan-contrast-suggest">
      <span class="scan-group-does"><span class="scan-swatch" style="background:${escapeHtml(p.fg)}"></span>${escapeHtml(p.fg)} on <span class="scan-swatch" style="background:${escapeHtml(p.bg)}"></span>${escapeHtml(p.bg)} — ${escapeHtml(String(p.rows[0].data.contrastRatio || '?'))}:1, needs ${p.need}:1 (${p.rows.length} element${p.rows.length === 1 ? '' : 's'}). <strong>Suggested:</strong> <span class="scan-swatch" style="background:${escapeHtml(to || '#000')}"></span><code>${escapeHtml(to || '')}</code> — same hue, passes. For the site's stylesheet; nothing is changed here.</span>
      <button type="button" class="btn-ghost btn-xs scan-copy" data-copy="${escapeHtml(css)}" title="Copy the CSS for the developers">Copy CSS</button>
    </div>`;
  }).join('');
}
document.getElementById('scanResults')?.addEventListener('click', (e) => {
  const b = e.target.closest('.scan-copy');
  if (!b) return;
  e.preventDefault(); e.stopPropagation();
  navigator.clipboard.writeText(b.dataset.copy || '').then(() => { const t = b.textContent; b.textContent = 'Copied'; setTimeout(() => { b.textContent = t; }, 1500); }).catch(() => {});
}, true);

/** The "Fix all N" control for a rule, or the reason there is none. */
function scanRuleActionHtml(ruleId, rows) {
  if (!rows.length) return '';
  const fixable = STATIC_FIXABLE[ruleId];
  const why = STATIC_WHY_NOT[ruleId];
  if (fixable) {
    return `<div class="scan-group-fix">
           ${fixable.needsLang ? `<select class="scan-lang" aria-label="Page language">
              ${['he', 'en', 'ar', 'ru', 'fr', 'es'].map((c) =>
                `<option value="${c}"${c === (document.documentElement.lang || 'he') ? ' selected' : ''}>${c}</option>`).join('')}
             </select>` : ''}
           <button class="btn-primary btn-xs scan-fix-all" data-fix-rule="${escapeHtml(ruleId)}">
             Fix all ${rows.length}
           </button>
           <span class="scan-group-does">${escapeHtml(fixable.does)}</span>
         </div>`;
  }
  return why ? `<div class="scan-group-fix is-manual"><span class="scan-group-does">No bulk fix — ${escapeHtml(why)}.</span></div>` : '';
}

function renderScanResults() {
  const wrap = document.getElementById('scanResults');
  if (!wrap) return;
  // The view switch sits with the filters; the checklist ignores them (it IS
  // the filter) and says so by hiding them.
  const filters = document.getElementById('scanFilters');
  let sw = document.getElementById('scanViewSwitch');
  if (!sw && filters) {
    sw = document.createElement('div');
    sw.id = 'scanViewSwitch';
    sw.className = 'seg scan-view-switch';
    sw.setAttribute('role', 'tablist');
    filters.parentElement.insertBefore(sw, filters);
  }
  if (sw) {
    sw.innerHTML = ['checklist', 'all'].map(v =>
      `<button type="button" class="seg-btn${scanView === v ? ' active' : ''}" data-scan-view="${v}" role="tab" aria-selected="${scanView === v}">${v === 'checklist' ? '✓ Checklist' : `All findings (${scanResults.length})`}</button>`).join('');
  }
  if (filters) filters.style.display = scanView === 'checklist' ? 'none' : '';
  if (scanView === 'checklist') { renderScanChecklist(wrap); return; }

  const list = scanFiltered();
  if (!list.length) { wrap.innerHTML = '<div class="empty-state">No issues match this filter. 🎉</div>'; return; }

  // Grouped by RULE. Forty positive tabindex values are one decision taken
  // forty times, and the report used to present them as forty — each with its
  // own "why & how to fix" fold saying the same sentence.
  const groups = new Map();
  for (const r of list) {
    if (!groups.has(r.ruleId)) groups.set(r.ruleId, []);
    groups.get(r.ruleId).push(r);
  }
  const item = scanItemHtml;

  wrap.innerHTML = [...groups.entries()].map(([ruleId, rows]) => {
    const r0 = rows[0];
    const fixable = STATIC_FIXABLE[ruleId];
    const why = STATIC_WHY_NOT[ruleId];
    const open = rows.filter(r => !r.resolved && !isIgnored(r));
    const action = (fixable && !open.length) ? '' : fixable
      ? `<div class="scan-group-fix">
           ${fixable.needsLang ? `<select class="scan-lang" aria-label="Page language">
              ${['he', 'en', 'ar', 'ru', 'fr', 'es'].map((c) =>
                `<option value="${c}"${c === (document.documentElement.lang || 'he') ? ' selected' : ''}>${c}</option>`).join('')}
             </select>` : ''}
           <button class="btn-primary btn-xs scan-fix-all" data-fix-rule="${escapeHtml(ruleId)}">
             Fix all ${open.length}
           </button>
           <span class="scan-group-does">${escapeHtml(fixable.does)}</span>
         </div>`
      : why
        ? `<div class="scan-group-fix is-manual"><span class="scan-group-does">No bulk fix — ${escapeHtml(why)}.</span></div>`
        : '';
    return `
      <details class="scan-group" data-rule="${escapeHtml(ruleId)}" open>
        <summary>
          <span class="scan-sev-badge sev-${(r0.severity || '').toLowerCase()}">${escapeHtml(r0.severity || '')}</span>
          <span class="scan-issue-title">${escapeHtml(r0.issue || ruleId)}</span>
          <span class="scan-group-n">${rows.length}</span>
          ${r0.wcag ? `<span class="wcag-chip">WCAG ${escapeHtml(r0.wcag)}</span>` : ''}
        </summary>
        ${action}
        <div class="scan-why-body">
          <div class="scan-why-line"><strong>Why:</strong> ${escapeHtml(r0.why || '')}</div>
          <div class="scan-why-line"><strong>Fix:</strong> ${escapeHtml(r0.fix || '')}</div>
        </div>
        ${scanRowsHtml(rows)}
      </details>`;
  }).join('');
}

/**
 * One press, one rule, every element it flags.
 *
 * The fix is stored as an ordinary mapping (`custom: 'staticFix'`), so it gets
 * storage, sync, export, the drawer, the monitoring hook and the report for
 * nothing — the same route ariaLabel and keyboardClickable already take. What
 * it emits is a DECLARATION; the corrector that reads it lives in the patch's
 * `statics` region and covers every match, including elements the page adds
 * later. That is the difference between fixing forty and fixing forty-and-
 * whatever-comes-next.
 */
document.getElementById('scanResults')?.addEventListener('click', async (e) => {
  const btn = e.target.closest('.scan-fix-all');
  if (!btn) return;
  e.preventDefault();
  const rule = btn.dataset.fixRule;
  const spec = STATIC_FIXABLE[rule];
  const status = document.getElementById('scanStatus');
  if (!spec) return;
  if (isReadonly()) {
    showNotice(status, 'Licence expired — existing work still applies and exports, but new fixes are paused.', 'error', 6000);
    return;
  }

  const config = {};
  if (spec.needsLang) {
    const sel = btn.closest('.scan-group-fix')?.querySelector('.scan-lang');
    config.lang = (sel && sel.value) || 'en';
  }

  const label = btn.textContent.trim();
  btn.disabled = true;
  btn.textContent = 'Applying…';
  try {
    // An unnamed form the ENGINE manages (a saved `form` mapping wrote its
    // role="form") is named the engine's way: the mapping's own
    // formLabelAbsolute, which U1 turns into aria-labelledby on every tick.
    // An attribute we write there is an attribute the engine overwrites, and
    // that is why "Fix all" on the search box looked like it did nothing. So
    // the mapping is completed first; the static rule below covers the rest.
    if (rule === 'landmark-noname') {
      const tab = await getTab();
      const key = storageKey('mappings', currentHostname);
      const list = (await U1Store.get([key]))[key] || [];
      const forms = list.filter(m => m && m.type === 'form' && m.primary && !((m.config || {}).selectors || {}).formLabelAbsolute);
      if (forms.length && isInjectable(tab)) {
        const found = await inPage(tab.id, (prims) => {
          const S = window.__u1SelectorIntel;
          return prims.map(p => {
            let el = null; try { el = document.querySelector(p); } catch (e) {}
            if (!el || el.getAttribute('aria-label') || el.getAttribute('aria-labelledby')) return null;
            const f = el.querySelector('input:not([type=hidden]),select,textarea');
            let lab = f && f.id ? document.querySelector(`label[for="${CSS.escape(f.id)}"]`) : null;
            if (!lab) lab = el.querySelector('label,legend,h1,h2,h3,h4,h5,h6');
            if (!lab || !(lab.textContent || '').trim()) return null;
            const sel = S && S.robustSelector ? S.robustSelector(lab) : (lab.id ? '#' + lab.id : (f && f.id ? `label[for="${f.id}"]` : ''));
            return sel ? { primary: p, label: sel, text: (lab.textContent || '').trim().slice(0, 40) } : null;
          });
        }, [forms.map(m => m.primary)]).catch(() => null);
        const named = [];
        (found || []).forEach((hit, i) => {
          if (!hit) return;
          const m = forms[i];
          m.config = m.config || {}; m.config.selectors = m.config.selectors || {};
          m.config.selectors.formLabelAbsolute = hit.label;
          if (m.code && typeof buildTemplate === 'function') { try { const t = buildTemplate('form', m.primary, m.config.selectors, m.config); if (t && t.code) m.code = t.code; } catch {} }
          named.push({ m, text: hit.text });
        });
        if (named.length) {
          await U1Store.set({ [key]: list });
          try { await applyMappingsBatch(named.map(({ m }) => ({ type: m.type, primary: m.primary, firstArg: m.firstArg, config: m.config, overwriteRole: m.overwriteRole }))); } catch {}
          // The engine will not re-run a fixer on a container it already
          // processed this page load (u1st-avoid-change-detection), so the
          // new formLabelAbsolute takes effect on the NEXT load. The name
          // has to be on the element NOW as well — written directly, the
          // same aria-labelledby the engine would write.
          try {
            await chrome.scripting.executeScript({
              target: { tabId: tab.id }, world: 'MAIN',
              func: (pairs) => pairs.forEach(([p, labelSel]) => {
                let el = null, lab = null;
                try { el = document.querySelector(p); lab = document.querySelector(labelSel); } catch (e) {}
                if (!el || !lab) return;
                if (!lab.id) lab.id = 'u1-lbl-' + Math.random().toString(36).slice(2, 8);
                el.setAttribute('aria-labelledby', lab.id);
              }),
              args: [named.map(({ m }) => [m.primary, m.config.selectors.formLabelAbsolute])],
            });
          } catch {}
          showNotice(status, `${named.map(n => `form mapping ${n.m.id || n.m.primary} now named “${n.text}”`).join('; ')} — named on the page now, and by the engine on every load from here (formLabelAbsolute).`, 'success', 9000);
        }
      }
    }
    // primary IS the rule name: one mapping per rule, so pressing twice
    // corrects the same entry rather than stacking duplicates.
    const tpl = { type: null, custom: 'staticFix', primary: rule, config, needsWork: true };
    const saved = await saveMappingEntry(tpl, { refreshUi: false });
    if (saved && saved.cancelled) { showNotice(status, 'Not saved.', 'warn', 4000); return; }
    await applyStaticFixesToPage();
    await loadMappingsList();
    refreshExportInfo();
    // Landmarks: name them NOW, directly, whatever the mapping path above and
    // the corrector did — and then look again a second later, because the
    // engine strips attributes it did not write on some containers. The
    // notice says, per landmark, what was written and whether it held. Four
    // presses of this button with nothing to show for them is what happens
    // when the outcome is not read back.
    let landmarkReport = '';
    if (rule === 'landmark-noname') {
      const tab = await getTab();
      if (isInjectable(tab)) {
        const nameNow = (probeOnly) => chrome.scripting.executeScript({
          target: { tabId: tab.id }, world: 'MAIN',
          func: (probe) => {
            const SEARCHY = /search|חיפוש|بحث|поиск|buscar|recherche|suche/i;
            const txt = (e) => (e && e.textContent || '').replace(/\s+/g, ' ').trim();
            const out = [];
            document.querySelectorAll('[role="form"],[role="region"]').forEach((el) => {
              const named = () => el.getAttribute('aria-label') || (el.getAttribute('aria-labelledby') && document.getElementById(el.getAttribute('aria-labelledby').split(/\s+/)[0]));
              const field = el.querySelector('input:not([type=hidden]),select,textarea');
              const lab = field && field.id ? document.querySelector(`label[for="${CSS.escape(field.id)}"]`) : null;
              const heading = el.querySelector('h1,h2,h3,h4,h5,h6,legend');
              const name = (lab && txt(lab)) || (field && (field.getAttribute('aria-label') || field.getAttribute('placeholder'))) || (heading && txt(heading)) || '';
              const engineOwned = el.hasAttribute('u1st-avoid-change-detection');
              const rec = { about: name || txt(el).slice(0, 30), role: el.getAttribute('role'), engineOwned, wrote: '', now: '' };
              if (!probe && !named() && name) {
                const src = lab || heading;
                if (src) { if (!src.id) src.id = 'u1-lbl-' + Math.random().toString(36).slice(2, 8); el.setAttribute('aria-labelledby', src.id); rec.wrote = `aria-labelledby → “${name}”`; }
                else { el.setAttribute('aria-label', name); rec.wrote = `aria-label “${name}”`; }
                const searchy = field && (field.type === 'search' || SEARCHY.test(field.name || '') || SEARCHY.test(field.id || '') || SEARCHY.test(name));
                if (searchy && el.getAttribute('role') === 'form' && !engineOwned) { el.setAttribute('role', 'search'); rec.wrote += ', role=search'; }
              }
              rec.now = named() ? (el.getAttribute('aria-label') ? `aria-label “${el.getAttribute('aria-label')}”` : `aria-labelledby → “${txt(document.getElementById(el.getAttribute('aria-labelledby').split(/\s+/)[0]))}”`) : 'no name';
              out.push(rec);
            });
            return out;
          },
          args: [!!probeOnly],
        }).then(r => (r && r[0] && r[0].result) || []).catch(() => []);
        const wrote = await nameNow(false);
        await new Promise(r => setTimeout(r, 1200));
        const after = await nameNow(true);
        landmarkReport = wrote.map((w, i) => {
          const a = after[i] || {};
          const held = a.now && a.now !== 'no name';
          return `${w.role} around “${w.about}”: ${w.wrote || 'already named'} → after 1s: ${held ? a.now + ' ✓' : 'STRIPPED — the engine removed it'}${w.engineOwned ? ' (engine-managed container)' : ''}`;
        }).join(' · ');
      }
    }
    showNotice(status,
      landmarkReport
        ? `Landmarks: ${landmarkReport}. ${/STRIPPED/.test(landmarkReport) ? 'A stripped name can only come from the form mapping itself (formLabelAbsolute) — it is set; reload the page and the engine names it on load.' : ''}`
        : `${rule} — fixed for every element on the page, and for any the page adds later. It is in Mappings and it exports.`,
      /STRIPPED/.test(landmarkReport) ? 'warn' : 'success', landmarkReport ? 15000 : 8000);
    // Re-read the page so the rows go at once, and say which did. A fix you
    // cannot see land is a fix you will press again.
    await refreshScanAfterMapping(rule);
  } catch (err) {
    showNotice(status, 'Could not apply it: ' + err.message, 'error', 8000);
  } finally {
    btn.disabled = false;
    btn.textContent = label;
  }
});

/**
 * Run the saved static fixes against the page in front, now.
 *
 * The exported bundle gets them through the patch; the panel has to apply them
 * itself so that pressing "Fix all" changes the page you are looking at rather
 * than only a file you have not pasted yet.
 */
async function applyStaticFixesToPage() {
  const tab = await getTab();
  if (!isInjectable(tab)) return;
  const key = storageKey('mappings', currentHostname);
  const list = (await U1Store.get([key]))[key] || [];
  const on = {};
  for (const m of list) {
    if (m && m.custom === 'staticFix' && m.primary) on[m.primary] = m.config || {};
  }
  if (!Object.keys(on).length) return;
  try {
    await chrome.scripting.executeScript({ target: { tabId: tab.id }, world: 'MAIN', files: ['u1-patch.js'] });
  } catch {}
  // MAIN world, and nothing else: the patch reads window.__u1Statics from the
  // page's own window. This used to go through inPage — the ISOLATED world —
  // so the declaration landed on a window the patch never sees, and every
  // "Fix all" from the panel changed nothing on the page in front.
  try {
    await chrome.scripting.executeScript({
      target: { tabId: tab.id }, world: 'MAIN',
      func: (decl) => {
        window.__u1Statics = decl;
        // The correctors are registered; this is what makes them run now
        // rather than at the next mutation.
        if (window.__u1Patch && window.__u1Patch.schedule) window.__u1Patch.schedule();
      },
      args: [on],
    });
  } catch {}
}

// The filter-and-results pattern: find it, then make it announce itself.
let filterShape = null;

/* ── Static fixes: the headings review, and the "Read more" cards ──────────
 *
 * Neither is a scan finding, because nothing about either is malformed: the
 * markup is correct and the result is unusable anyway. They sit together
 * because they are the two things on a page that only a person can settle.
 *
 * The headings box is a REVIEW and approving writes NOTHING. That is not a
 * detail of the interface, it is the rule: a page's own author knows things
 * about their structure that reading order cannot show, and the rules have
 * always said not to renumber a page's headings to make them tidy. A level is
 * rewritten only where somebody asks for one.
 */
/**
 * The finishing pass (owner decision, 2026-09-01): after a sweep builds its
 * components, the page-wide judgement calls are made automatically instead of
 * waiting in their manual tools. Two things run:
 *   1. Heading outline — every heading whose outline IMPLIES a concrete other
 *      level (h.should) gets a heading mapping at that level. A heading that
 *      merely looks odd, with no implied level, is still left alone.
 *   2. Vague links — the repeated "Learn more" pattern beside card headings
 *      gets the aria-label mapping ("<says> about <heading>") that the manual
 *      "Name them after their headings" button writes.
 * Both dedupe against alreadyHandled(), so re-running a sweep on the same page
 * writes nothing twice. The manual review screens stay, for overrides.
 */
/**
 * Inside every dialog this run detected (owner decision, 2026-09-01): a dialog
 * is a page of its own — a state selector, a search form, a close-listbox live
 * in there, and a sweep that maps the dialog and walks past its insides has
 * done half the job. For each dialog built this run, collect INSIDE it (a
 * named scope admits closed/hidden descendants — the page-wide walk never
 * sees them), ask the model about that one region, audit the answer the same
 * way a survey row is audited, and build what comes back through
 * confirmedToMapping — the exact path the autonomous sweep already trusts.
 * One model call per dialog, each one logged with what it cost to skip.
 */
/**
 * The static pass asks before it writes. It maps headings, vague links and
 * dialog interiors automatically — and doing that unannounced read as
 * "mappings suddenly appear and I have no idea when this happens". One
 * question covers the whole phase; Skip leaves the components built and the
 * statics for a later run.
 */
async function confirmStaticPass(dialogCount) {
  const dlg = document.getElementById('staticPassDialog');
  if (!dlg) return true;
  document.getElementById('staticPassBody').textContent =
    'The components are built. Next comes the automatic static work: vague "learn more" links' +
    (dialogCount ? `, and a look inside ${dialogCount} dialog${dialogCount === 1 ? '' : 's'} (one model call each)` : '') +
    ' — written straight to Mappings. (Headings are left to the manual review, by decision.)';
  return await new Promise((resolve) => {
    const go = document.getElementById('staticPassGo');
    const skip = document.getElementById('staticPassSkip');
    const done = (a) => { dlg.close();
      go.removeEventListener('click', onGo); skip.removeEventListener('click', onSkip); resolve(a); };
    const onGo = () => done(true);
    const onSkip = () => done(false);
    go.addEventListener('click', onGo);
    skip.addEventListener('click', onSkip);
    dlg.showModal();
  });
}

async function dialogInteriorScan(tab) {
  const out = { dialogs: 0, made: 0 };
  if (isReadonly()) return out;
  const sels = [];
  for (const s of (aiSweep.stops || [])) {
    for (const f of (s.found || [])) {
      if (f && f.done && f.type === 'dialog' && f.sel && !sels.includes(f.sel)) sels.push(f.sel);
    }
  }
  out.dialogs = sels.length;
  if (!sels.length) return out;
  if (!(await U1AI.getKey())) return out;
  const handled = await alreadyHandled();
  let di = 0;
  for (const dSel of sels) {
    if (aiSweep.abort) break;
    di++;
    // Watched, not discovered afterwards: mappings appearing with no visible
    // work running read as "they suddenly show up out of nowhere".
    try {
      showSweepBusy('Static pass — inside the dialogs',
        `Looking inside ${dSel} — ${di} of ${sels.length} (one model call each). New mappings land in the drawer as they are built.`,
        ((di - 1) / sels.length) * 100);
    } catch {}
    let collected = null;
    try { collected = await collectRegion(tab, dSel, handled); } catch (e) {}
    if (!collected || collected.err || !(collected.candidates || []).length) {
      sweepLog(0, `inside ${dSel}: nothing new to map` +
        (collected && collected.err ? ` (${collected.err})` : ''), 'skip');
      continue;
    }
    let part = null;
    try {
      part = await U1AI.discover({
        screenshot: collected.shot,
        context: { candidates: collected.candidates, headings: collected.headings,
                   title: collected.title, url: collected.url },
        scope: dSel,
      });
    } catch (e) { part = { err: e.message }; }
    if (!part || part.err) {
      sweepLog(0, `inside ${dSel}: the model gave no answer` +
        (part && part.err ? ` (${part.err})` : ''), 'err');
      continue;
    }
    aiCost += U1AI.estimateCost(part.usage) || 0;
    // The dialog itself is already mapped — this pass is about what it holds.
    let comps = (part.components || []).filter((c) =>
      c && c.containerSelector && c.containerSelector !== dSel &&
      c.u1Type !== 'dialog' && !handled.has(c.containerSelector));
    try { const audit = await auditSurveyComponents(comps, tab); comps = audit.comps; } catch (e) {}
    if (!comps.length) {
      sweepLog(0, `inside ${dSel}: nothing worth mapping beyond the dialog itself`, 'skip');
      continue;
    }
    for (const c of comps) {
      if (aiSweep.abort) break;
      try {
        const res = await confirmedToMapping(
          { mark: null, type: c.u1Type, sel: c.containerSelector,
            why: c.why || `found inside the dialog ${dSel}` },
          { n: 0, probed: [] }, tab, { parent: dSel });
        if (res && res.err) {
          sweepLog(0, `inside ${dSel}: ${c.u1Type} ${c.containerSelector} could not be built — ${res.err}`, 'err');
        } else {
          out.made++;
          handled.add(c.containerSelector);
          sweepLog(0, `inside ${dSel}: mapped ${c.u1Type} ${c.containerSelector}`, 'info');
        }
      } catch (err) {
        sweepLog(0, `inside ${dSel}: ${c.u1Type} ${c.containerSelector} — ${err.message}`, 'err');
      }
    }
  }
  return out;
}

async function sweepFinishingPass(tab, ranges) {
  // Owner decision (2026-09-02): headings are OUT of the static pass — a
  // heading fix landing inside another mapping's area fought it ("two on the
  // same elements fight, and the second wins", the #deals tabs vs the
  // section title). The manual headings review remains for deliberate use.
  const made = { headings: 0, links: 0, read: 0, off: 0, already: 0 };
  if (isReadonly()) return made;
  const handled = await alreadyHandled();
  try {
    await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['selector-intel.js'] });
  } catch { return made; }
  try { showSweepBusy('Static pass — vague links', 'Looking for repeated \u201cLearn more\u201d links beside headings\u2026', null); } catch {}
  try {
    const got2 = await inPage(tab.id, (rgs) => {
      const S = window.__u1SelectorIntel;
      const diag = {};
      let rows = S && S.cardDescriptions ? S.cardDescriptions(diag) : [];
      if (rgs && rgs.length) {
        rows = rows.filter((c) => {
          let el = null;
          try { el = document.querySelector(c.target); } catch { return false; }
          if (!el) return false;
          const y = el.getBoundingClientRect().top + window.scrollY;
          return rgs.some((r) => y >= r.top - 60 && y <= r.bottom + 60);
        });
      }
      return { rows, diag };
    }, [ranges || null]);
    const shapes = (got2 && got2.rows) || [];
    made.vagueDiag = (got2 && got2.diag) || null;
    for (const c of shapes || []) {
      if (!c.target || handled.has(c.target)) continue;
      try {
        await saveMappingEntry(buildTemplate('aria-label', c.target, {},
          { middleText: 'about', headingSelector: c.heading }), { refreshUi: false });
        handled.add(c.target);
        made.links++;
      } catch {}
    }
  } catch {}
  if (made.headings || made.links) {
    try { await applyAllMappings({ silent: true }); } catch {}
    await loadMappingsList();
    refreshExportInfo();
  }
  return made;
}

async function readHeadingOutline() {
  const tab = await getTab();
  if (!isInjectable(tab)) return null;
  try {
    await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['selector-intel.js'] });
    return await inPage(tab.id, () => {
      const S = window.__u1SelectorIntel;
      if (!S || !S.headingOutline) return null;
      const list = S.headingOutline();
      return { rows: list.slice(), noH1: !!list.noH1 };
    });
  } catch { return null; }
}

function headingRowHtml(h, i) {
  const lvl = h.level ? 'H' + h.level : 'no level';
  const note = h.problem
    ? `<span class="head-problem">${escapeHtml(h.problem)}</span>` : '';
  // The suggestion is offered, never pre-selected. A row nobody touches leaves
  // the page exactly as it is.
  const choices = [1, 2, 3, 4, 5, 6].map((n) =>
    `<option value="${n}"${n === h.level ? ' selected' : ''}>H${n}</option>`).join('');
  return `<div class="head-row" data-i="${i}">
    <span class="head-lvl">${escapeHtml(lvl)}</span>
    <span class="head-text">${escapeHtml(h.text || '(empty)')}</span>
    ${note}
    <code class="head-sel">${escapeHtml(h.selector)}</code>
    <span class="head-actions">
      ${h.should ? `<span class="head-suggest">outline implies H${h.should}</span>` : ''}
      <select class="head-level" aria-label="Level for ${escapeHtml(h.text || 'this heading')}">${choices}</select>
      <button class="btn-outline btn-xs head-change" data-i="${i}">Change it</button>
    </span>
  </div>`;
}

let headingRows = [];

document.getElementById('headingReview')?.addEventListener('click', async () => {
  const status = document.getElementById('headingStatus');
  const list = document.getElementById('headingList');
  list.innerHTML = '';
  showNotice(status, '', 'info', 1);

  const got = await readHeadingOutline();
  if (!got || !got.rows.length) {
    list.innerHTML = '<div class="map-mode-hint">No headings on this page at all — which is its own finding, and the scan reports it.</div>';
    return;
  }
  headingRows = got.rows;
  const broken = got.rows.filter((h) => h.problem).length;
  list.innerHTML =
    (got.noH1 ? '<div class="head-note">This page has no H1. That is a fact about the outline rather than about any one heading below.</div>' : '') +
    `<div class="head-note">${got.rows.length} heading${got.rows.length === 1 ? '' : 's'}, ` +
    `${broken || 'none'} with something to look at. Leaving a row alone changes nothing.</div>` +
    got.rows.map(headingRowHtml).join('');
});

document.getElementById('headingList')?.addEventListener('click', async (e) => {
  const btn = e.target.closest('.head-change');
  if (!btn) return;
  const status = document.getElementById('headingStatus');
  if (isReadonly()) {
    showNotice(status, 'Licence expired — new work is paused.', 'error', 6000);
    return;
  }
  const row = btn.closest('.head-row');
  const h = headingRows[Number(btn.dataset.i)];
  const level = Number(row.querySelector('.head-level').value) || 2;
  if (!h) return;
  if (h.level === level) {
    showNotice(status, 'That is the level it already has — nothing to change.', 'info', 5000);
    return;
  }
  try {
    const tpl = buildTemplate('heading', h.selector, {}, { level });
    await saveMappingEntry(tpl, { refreshUi: false });
    await loadMappingsList();
    refreshExportInfo();
    showNotice(status,
      `"${h.text || h.selector}" is mapped as H${level}. The rest are untouched.`, 'success', 8000);
  } catch (err) {
    showNotice(status, 'Could not save it: ' + err.message, 'error', 9000);
  }
});

let cardShapes = [];

document.getElementById('descFind')?.addEventListener('click', async () => {
  const found = document.getElementById('descFound');
  const status = document.getElementById('descStatus');
  showNotice(status, '', 'info', 1);
  found.innerHTML = '';

  const tab = await getTab();
  if (!isInjectable(tab)) { found.textContent = 'Cannot read this page.'; return; }
  let shapes = null;
  try {
    await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['selector-intel.js'] });
    shapes = await inPage(tab.id, () => {
      const S = window.__u1SelectorIntel;
      return S && S.cardDescriptions ? S.cardDescriptions() : null;
    });
  } catch { shapes = null; }

  cardShapes = shapes || [];
  if (!cardShapes.length) {
    found.innerHTML = 'Nothing on this page repeats a link that says the same thing beside its own heading. ' +
      'A single vague link is a rename by hand, not a pattern — this looks for the repeated kind.';
    return;
  }
  found.innerHTML = cardShapes.map((c, i) => `
    <div class="desc-row">
      <div><strong>${c.count}</strong> links that all say “${escapeHtml(c.says)}”</div>
      <div>each beside <code>${escapeHtml(c.heading)}</code></div>
      <div class="head-suggest">e.g. “${escapeHtml(c.says)} about ${escapeHtml(c.example)}”</div>
      <button class="btn-primary btn-xs desc-add" data-i="${i}">Name them after their headings</button>
    </div>`).join('');
});

document.getElementById('descFound')?.addEventListener('click', async (e) => {
  const btn = e.target.closest('.desc-add');
  if (!btn) return;
  const status = document.getElementById('descStatus');
  if (isReadonly()) {
    showNotice(status, 'Licence expired — new work is paused.', 'error', 6000);
    return;
  }
  const c = cardShapes[Number(btn.dataset.i)];
  if (!c) return;
  try {
    // The mapping that already existed for this and had no way of being found:
    // the link's own text, then "about", then the heading in its card.
    const tpl = buildTemplate('aria-label', c.target, {},
      { middleText: 'about', headingSelector: c.heading });
    await saveMappingEntry(tpl, { refreshUi: false });
    // Everything, not only the one just made. U1 decorates once per page load,
    // so a mapping made earlier may never have met what has re-rendered since —
    // which is the same reason the sweep applies the whole set, and there is a
    // check that forbids narrowing it.
    await applyAllMappings({ silent: true });
    await loadMappingsList();
    refreshExportInfo();
    showNotice(status,
      `Done. Those ${c.count} links now read “${c.says} about …” with each card's own heading.`,
      'success', 9000);
  } catch (err) {
    showNotice(status, 'Could not save it: ' + err.message, 'error', 9000);
  }
});

document.getElementById('filterFind')?.addEventListener('click', async () => {
  const found = document.getElementById('filterFound');
  const add = document.getElementById('filterAdd');
  const status = document.getElementById('filterStatus');
  showNotice(status, '', 'info', 1);
  filterShape = await offerFilterResults();
  if (!filterShape) {
    add.style.display = 'none';
    found.innerHTML = 'Nothing on this page looks like one — no text field with a list of ' +
      'three or more alike results beside it. If you know where it is, the fields below take a selector.';
    return;
  }
  // Shown before it is applied, because the noun is the one thing only you know
  // and it is what a person actually hears.
  found.innerHTML =
    `<div><strong>${escapeHtml(String(filterShape.count))} results</strong> ` +
    `filtered by <code>${escapeHtml(filterShape.field)}</code></div>` +
    `<div>list <code>${escapeHtml(filterShape.results)}</code> · ` +
    `each one <code>${escapeHtml(filterShape.item)}</code></div>` +
    (filterShape.labelled ? '' : '<div>⚠ the field has no label of its own — give it one too</div>') +
    `<div class="sub-sel-row" style="margin-top:8px">
       <div class="key">a result is a…</div>
       <input type="text" id="filterNoun" value="result" spellcheck="false">
     </div>
     <div class="map-mode-hint">Used in the announcement: “2 branches”, “No branches match”.</div>`;
  add.style.display = '';
});

document.getElementById('filterAdd')?.addEventListener('click', async () => {
  const status = document.getElementById('filterStatus');
  if (!filterShape) return;
  if (isReadonly()) {
    showNotice(status, 'Licence expired — new work is paused.', 'error', 6000);
    return;
  }
  const noun = (document.getElementById('filterNoun')?.value || 'result').trim() || 'result';
  try {
    await saveMappingEntry({
      type: null, custom: 'staticFix', primary: 'filter-results',
      config: { field: filterShape.field, results: filterShape.results, item: filterShape.item, noun },
      needsWork: true,
    }, { refreshUi: false });
    await applyStaticFixesToPage();
    await loadMappingsList();
    refreshExportInfo();
    showNotice(status,
      `Done. Typing in that field now announces how many ${noun}s are showing, and the ` +
      `field is tied to the list it controls.`, 'success', 9000);
  } catch (err) {
    showNotice(status, 'Could not save it: ' + err.message, 'error', 9000);
  }
});

// "This must not be reachable." Both halves, always — see the statics region.
document.getElementById('excludeAdd')?.addEventListener('click', async () => {
  const input = document.getElementById('excludeSel');
  const status = document.getElementById('excludeStatus');
  const sel = (input?.value || '').trim();
  if (!sel) { showNotice(status, 'Type a selector first.', 'warn', 4000); return; }
  if (isReadonly()) {
    showNotice(status, 'Licence expired — new work is paused.', 'error', 6000);
    return;
  }
  const tab = await getTab();
  if (!isInjectable(tab)) { showNotice(status, 'Cannot reach this page.', 'error', 4000); return; }
  // Refuse a selector that matches nothing, here, rather than saving a rule
  // that can only ever do nothing.
  const n = await inPage(tab.id, (x) => {
    try { return document.querySelectorAll(x).length; } catch (e) { return -1; }
  }, [sel]);
  if (n === -1) { showNotice(status, 'That is not valid CSS.', 'error', 6000); return; }
  if (!n) { showNotice(status, 'Nothing on this page matches that selector.', 'error', 6000); return; }

  try {
    await saveMappingEntry(
      { type: null, custom: 'staticFix', primary: 'exclude', config: { selector: sel }, needsWork: true },
      { refreshUi: false });
    await applyStaticFixesToPage();
    await loadMappingsList();
    refreshExportInfo();
    showNotice(status,
      `${n} element${n === 1 ? '' : 's'} taken out of the tab order and out of the screen reader. ` +
      `The scan will stop reporting anything inside it.`, 'success', 8000);
  } catch (err) {
    showNotice(status, 'Could not save it: ' + err.message, 'error', 8000);
  }
});

document.getElementById('excludeTest')?.addEventListener('click', async () => {
  const sel = (document.getElementById('excludeSel')?.value || '').trim();
  if (!sel) return;
  const tab = await getTab();
  if (!isInjectable(tab)) return;
  await inPage(tab.id, (x) => window.__u1SelectorIntel.highlightSelector(x), [sel]).catch(() => {});
});

// Which page this scan is running on, and which of the three engines have
// finished — asked for directly: a scan that just says "Scanning…" gives no
// way to tell a slow page from a stuck one, or to know it moved on to the
// engine that takes real time (axe injects and runs in the page).
const SCAN_STEP_LABEL = { u1: 'Structure, names and labels', axe: 'Colour contrast and ARIA' };
function scanProgressHtml(tab, steps) {
  const title = (tab && (tab.title || tab.url)) || '';
  const rows = ['u1', 'axe'].map((k) => {
    const s = steps[k] || 'pending'; // 'pending' | 'running' | 'done' | 'skipped'
    const icon = s === 'done' ? '✅' : s === 'running' ? '⏳' : s === 'skipped' ? '⚠️' : '⬜';
    return `<div class="scan-progress-step scan-progress-${s}">${icon} ${SCAN_STEP_LABEL[k]}</div>`;
  }).join('');
  return `<div class="scan-progress-page" title="${escapeHtml((tab && tab.url) || '')}">📄 ${escapeHtml(title || 'this page')}</div>` +
         `<div class="scan-progress-steps">${rows}</div>`;
}

// ── Scan history: every page scanned before, kept and scored ────────────────
//
// A heuristic, not a certified conformance score: weighted deductions from
// 100 by severity, floored at 0. Meant to say "roughly how rough is this
// page" at a glance across a list of pages — for the actual findings, open
// the scan; the weights are not a WCAG scoring standard and don't claim to be.
// Scored by QUESTION, not by count. Sixty-five findings used to sum to a flat
// 0% on every real page — a number that cannot move is not a score. Each
// checklist question is worth one point; a question with findings loses the
// weight of its worst one (Critical the whole point, High most of it, Medium
// half, Low a quarter), a little more for many findings. Notes and rows already
// resolved count nothing. Two pages with the same faults now differ by how
// many of the twenty questions they fail, which is what a person means by
// "how rough is it".
const SCAN_Q_WEIGHT = { Critical: 1, High: 0.8, Medium: 0.5, Low: 0.25 };
function computeScanScore(results) {
  const live = (results || []).filter(r => r && !r.note && !r.resolved && !isIgnored(r));
  const byQ = new Map();
  for (const r of live) {
    const concept = conceptOfRule(r.ruleId);
    const q = SCAN_CHECKS.find(c => c.rules.includes(concept) || c.rules.includes(r.ruleId));
    const id = q ? q.id : 'other';
    if (!byQ.has(id)) byQ.set(id, []);
    byQ.get(id).push(r);
  }
  const total = SCAN_CHECKS.length;
  let lost = 0;
  for (const rows of byQ.values()) {
    const worst = Math.max(...rows.map(r => SCAN_Q_WEIGHT[r.severity] ?? 0.5));
    lost += Math.min(1, worst * (1 + Math.min(0.5, Math.log10(rows.length) * 0.25)));
  }
  return Math.max(0, Math.round(100 * (1 - lost / total)));
}

// Local-only (setLocalOnly, not the site-synced set() — see store.js's
// SITE_PREFIXES): this is a per-machine convenience record of what you saw
// last time, not shared work a colleague needs, so it does not compete with
// mapping storage for the server's per-request size limit.
function scanHistoryKey() { return 'scanHistory_' + currentHostname; }

async function saveScanToHistory(tab, results, enginesRan, inventory) {
  if (!tab || !tab.url) return;
  const key = scanHistoryKey();
  const stored = (await U1Store.get([key]))[key] || [];
  const url = tab.url.split('#')[0];
  const entry = {
    url, title: tab.title || url, at: Date.now(),
    score: computeScanScore(results),
    count: results.length,
    crit: results.filter(r => r.severity === 'Critical').length,
    high: results.filter(r => r.severity === 'High').length,
    results, enginesRan: enginesRan || [],
    inventory: inventory || null,
  };
  // One entry per URL — re-scanning a page replaces its old record rather
  // than piling up duplicates of the same page.
  const next = [entry, ...stored.filter(e => e && e.url !== url)].slice(0, 30);
  await U1Store.setLocalOnly({ [key]: next });
  renderScanHistory();
}

function scanScoreClass(score) {
  return score >= 90 ? 'good' : score >= 60 ? 'mid' : 'bad';
}

async function renderScanHistory() {
  const box = document.getElementById('scanHistoryList');
  if (!box) return;
  const key = scanHistoryKey();
  const list = (await U1Store.get([key]))[key] || [];
  if (!list.length) { box.innerHTML = ''; box.style.display = 'none'; return; }
  box.style.display = '';
  box.innerHTML =
    `<div class="scan-history-title">Scanned before<span class="dot">.</span></div>` +
    list.map((e, i) => `
      <button type="button" class="scan-history-row" data-reopen="${i}" title="${escapeHtml(e.url)}">
        <span class="scan-history-score scan-history-score-${scanScoreClass(e.score)}">${e.score}%</span>
        <span class="scan-history-text">
          <span class="scan-history-page">${escapeHtml(e.title || e.url)}</span>
          <span class="scan-history-sub">${e.count} issue${e.count === 1 ? '' : 's'}${e.crit ? ` · ${e.crit} critical` : ''}${e.high ? ` · ${e.high} high` : ''} · ${new Date(e.at).toLocaleDateString()}</span>
        </span>
      </button>`).join('');
  box.querySelectorAll('[data-reopen]').forEach((b) => {
    b.addEventListener('click', () => reopenScanHistory(list[parseInt(b.dataset.reopen, 10)]));
  });
}

function reopenScanHistory(entry) {
  if (!entry) return;
  scanResults = entry.results || [];
  scanEnginesRan = entry.enginesRan || [];
  scanInventory = entry.inventory || null;
  scanActiveCat = '*'; scanActiveSev = '*';
  showOnlyScan('static');
  const crit = scanResults.filter(r => r.severity === 'Critical').length;
  const high = scanResults.filter(r => r.severity === 'High').length;
  document.getElementById('scanCount').textContent =
    scanResults.length ? `${entry.score}% · ${scanResults.length} issues${crit ? ` · ${crit} critical` : ''}${high ? ` · ${high} high` : ''} (saved ${new Date(entry.at).toLocaleString()})` : '';
  Promise.all([loadAltOk(), loadIgnored(), loadScanMappingStatus()]).then(() => renderScanResults()).catch(() => {});
  document.getElementById('scanClearBtn').style.display = scanResults.length ? '' : 'none';
  document.getElementById('scanReportRow').style.display = scanResults.length ? 'flex' : 'none';
  renderScanFilters();
  renderScanResults();
}

document.getElementById('scanBtn')?.addEventListener('click', async () => {
  const status = document.getElementById('scanStatus');
  const btn = document.getElementById('scanBtn');
  const progress = document.getElementById('scanProgress');
  const tab = await getTab();
  const steps = { u1: 'running', axe: 'pending' };
  if (progress) { progress.style.display = ''; progress.innerHTML = scanProgressHtml(tab, steps); }
  btn.textContent = 'Scanning…';
  showNotice(status, 'Analyzing the page for accessibility faults…', 'info', 0);
  const res = await scanPageStatic();
  if (res.err) {
    btn.textContent = '🔎 Scan this page';
    if (progress) progress.style.display = 'none';
    showNotice(status, res.err, 'error', 4000);
    return;
  }
  steps.u1 = 'done'; steps.axe = 'running';
  if (progress) progress.innerHTML = scanProgressHtml(tab, steps);

  btn.textContent = 'Checking colour contrast and ARIA…';
  const ext = tab ? await runScanEngines(tab.id) : { findings: [], ran: [] };
  btn.textContent = '🔎 Scan this page';
  steps.axe = (ext.ran || []).includes('axe') ? 'done' : 'skipped';
  if (progress) progress.innerHTML = scanProgressHtml(tab, steps);

  // Enrich each raw finding with its catalog rule (title/why/fix/severity/wcag/category).
  await loadAltOk();
  await loadIgnored();
  await loadScanMappingStatus();
  const ours = dropApprovedAlts(enrichOurFindings(res.results));
  // Every engine finding is shown in OUR words: the catalog entry it translates
  // to (AXE_RULES), under the same question, with the same severity scale.
  // What the engine wrote is kept underneath for the record.
  const theirs = [];
  for (const f of (ext.findings || [])) {
    const c = axeCatalog(f.ruleId);
    if (c === null) continue; // deliberately skipped (AXE_SKIP)
    theirs.push({
      engine: f.engine, ruleId: c ? c.ruleId : f.ruleId, selector: f.selector, idx: f.idx || 0, target: f.target || '',
      text: f.text || '', tag: f.tag || '', detail: c ? '' : f.detail, engineDetail: f.detail, engineSaid: f.fix, href: f.href || '', data: f.data || null,
      issue: c ? c.title : f.issue, why: c ? c.why : f.why, fix: c ? c.fix : f.fix,
      severity: c ? c.severity : f.severity, wcag: c ? (c.wcag || f.wcag) : f.wcag,
      cat: c ? c.category : 'Other', note: !!(c && c.note), helpUrl: f.helpUrl,
    });
  }
  // Ours first, so that where an engine agrees with a rule we wrote, the wording
  // the client reads is the one written for them.
  scanResults = mergeScanFindings([...ours, ...theirs])
    .sort((a, b) => (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9));
  scanEnginesRan = ext.ran || [];
  scanInventory = res.inventory || null;
  scanActiveCat = '*'; scanActiveSev = '*';
  saveScanToHistory(tab, scanResults, scanEnginesRan, scanInventory).catch(() => {});
  status.style.display = 'none';
  document.getElementById('scanClearBtn').style.display = scanResults.length ? '' : 'none';
  // One scan on screen at a time.
  //
  // These answer two unrelated questions — "what is wrong with this page" and
  // "do the mappings I built still work" — and they were shown together, so a
  // page scan left the previous run's mapping results sitting under it as if
  // they were part of the same answer. The results are not thrown away; the
  // section reappears the moment its own scan is run again.
  showOnlyScan('static');
  const crit = scanResults.filter(r => r.severity === 'Critical').length;
  const high = scanResults.filter(r => r.severity === 'High').length;
  document.getElementById('scanCount').textContent =
    scanResults.length ? `${computeScanScore(scanResults)}% · ${scanResults.length} issues${crit ? ` · ${crit} critical` : ''}${high ? ` · ${high} high` : ''}` : '';
  document.getElementById('scanReportRow').style.display = scanResults.length ? 'flex' : 'none';
  if (!scanResults.length) {
    // Which engines answered, not just the count. "No faults" from one engine
    // and "no faults" from three are different claims, and the difference is
    // invisible unless it is written down.
    showNotice(status, scanEnginesRan.includes('axe')
      ? 'No automatic faults found on this page. 🎉'
      : 'No faults found in structure, names and labels — colour contrast and ARIA could not be checked on this page.', 'success', 5000);
  } else if (!scanEnginesRan.includes('axe')) {
    showNotice(status, 'Colour contrast and the ARIA checks could not run on this page — these results cover structure, names and labels only.', 'warn', 8000);
  }
  renderScanFilters();
  renderScanResults();
});

// Export a report of every flagged static issue, each with a screenshot of the
// element (captured now, one by one) and a plain-language fix.
document.getElementById('scanReportBtn')?.addEventListener('click', async () => {
  const status = document.getElementById('scanReportStatus');
  const btn = document.getElementById('scanReportBtn');
  const issues = scanResults.slice(0, 40); // every scan finding is an issue now; cap capture time
  if (!issues.length) { showNotice(status, 'No issues to report.', 'warn', 3000); return; }

  const items = [];
  for (let i = 0; i < issues.length; i++) {
    const r = issues[i];
    btn.textContent = `Capturing ${i + 1}/${issues.length}…`;
    let screenshot = null;
    if (r.selector) { try { screenshot = await captureElementScreenshot(r.selector); } catch {} }
    // Include the richer catalog fields; report-gen shows issue + fix (severity/wcag/why extra).
    items.push({ cat: r.cat, text: r.text, selector: r.selector, detail: r.detail,
      issue: r.issue, severity: r.severity, wcag: r.wcag, why: r.why, fix: r.fix, screenshot });
  }
  btn.textContent = '📄 Export issues report (with screenshots)';

  const tab = await getTab();
  try {
    const out = await generateStaticIssuesReport(currentHostname, items, tab?.url || '', tab?.title || '');
    showNotice(status, `Report opened with ${out.issues} issue${out.issues !== 1 ? 's' : ''} (also downloaded).`, 'success', 4000);
  } catch (e) {
    showNotice(status, 'Error building report: ' + (e && e.message ? e.message : e), 'error', 4500);
  }
});

document.getElementById('scanClearBtn')?.addEventListener('click', () => {
  scanResults = [];
  document.getElementById('scanResultsSection').style.display = 'none';
  document.getElementById('scanClearBtn').style.display = 'none';
  const progress = document.getElementById('scanProgress');
  if (progress) progress.style.display = 'none';
});

document.getElementById('scanResultsSection')?.addEventListener('click', (e) => {
  const b = e.target.closest('[data-scan-view]');
  if (!b) return;
  scanView = b.dataset.scanView;
  renderScanResults();
});

document.getElementById('scanFilters')?.addEventListener('click', (e) => {
  const sevChip = e.target.closest('[data-scan-sev]');
  const catChip = e.target.closest('[data-scan-cat]');
  if (sevChip) scanActiveSev = sevChip.dataset.scanSev;
  else if (catChip) scanActiveCat = catChip.dataset.scanCat;
  else return;
  renderScanFilters();
  renderScanResults();
});

document.getElementById('scanResults')?.addEventListener('focusin', (e) => {
  const inp = e.target.closest('.scan-name-input');
  if (!inp) return;
  const item = inp.closest('.scan-item');
  const r = item && scanResults[Number(item.dataset.scanIdx)];
  if (!r) return;
  const t = scanTargetOf(r);
  highlightMatch(t.sel, t.idx, true).catch(() => {});
});
document.getElementById('scanResults')?.addEventListener('keydown', (e) => {
  const inp = e.target.closest('.scan-name-input');
  if (!inp) return;
  if (e.key === 'Enter') { e.preventDefault(); inp.parentElement.querySelector('.scan-map')?.click(); }
});
document.getElementById('scanResults')?.addEventListener('click', async (e) => {
  if (e.target.closest('.scan-name-input')) { e.stopPropagation(); return; }
  const ign = e.target.closest('.scan-ignore');
  if (ign) {
    e.stopPropagation();
    const item = ign.closest('.scan-item');
    const r = item && scanResults[Number(item.dataset.scanIdx)];
    if (!r) return;
    await setIgnored(r, !isIgnored(r));
    renderScanFilters(); renderScanResults();
    return;
  }
  const showIgn = e.target.closest('.scan-show-ignored');
  if (showIgn) { e.stopPropagation(); scanShowIgnored = !scanShowIgnored; renderScanResults(); return; }
  const mapAll = e.target.closest('.scan-map-all');
  if (mapAll) { e.stopPropagation(); scanMapAll(mapAll); return; }
  const mapBtn = e.target.closest('.scan-map');
  if (mapBtn) {
    e.stopPropagation();
    const item = mapBtn.closest('.scan-item');
    const r = item && scanResults[Number(item.dataset.scanIdx)];
    if (r) scanMapFinding(r, mapBtn);
    return;
  }
  // Clicking the "Why & how to fix" accordion should just toggle it.
  if (e.target.closest('.scan-why')) return;
  const item = e.target.closest('.scan-item');
  if (!item) return;
  const r = scanResults[Number(item.dataset.scanIdx)];
  if (!r || !r.selector) return;
  // Highlight + scroll THIS element into view — the Nth match of the short
  // selector, not the first one (`a.externalLink` is every external link on
  // the page; the finding was about one of them). If it no longer matches
  // (e.g. it was inside something now removed), say so instead of silence.
  const t = scanTargetOf(r);
  const found = await highlightMatch(t.sel, t.idx, true);
  if (found === false) { showNotice(document.getElementById('scanStatus'), `Couldn't find "${r.text || r.selector}" on the page right now.`, 'warn', 3000); return; }
  setTimeout(() => highlightMatch(t.sel, t.idx, false), 3000);
});

// Hover a picture or a heading in the evidence list, see it on the page —
// the list says `icon_pdf.png → "download arrow"`, and which of the two
// identical icons that is cannot be read off the text.
{
  const host = document.getElementById('scanResults');
  let hoverTimer = null, hoverKey = '';
  const stop = () => {
    clearTimeout(hoverTimer);
    if (!hoverKey) return;
    hoverKey = '';
    highlightMatch('*', 0, false).catch(() => {});
  };
  host?.addEventListener('mouseover', (e) => {
    const li = e.target.closest('[data-hl-sel]');
    if (!li || !li.dataset.hlSel) return;
    const key = li.dataset.hlSel + '#' + li.dataset.hlIdx;
    if (key === hoverKey) return;
    hoverKey = key;
    clearTimeout(hoverTimer);
    hoverTimer = setTimeout(() => highlightMatch(li.dataset.hlSel, Number(li.dataset.hlIdx) || 0, true).catch(() => {}), 150);
  });
  host?.addEventListener('mouseout', (e) => {
    const li = e.target.closest('[data-hl-sel]');
    if (li && !li.contains(e.relatedTarget)) stop();
  });
  host?.addEventListener('mouseleave', stop);
}

// ─────────────────────────────────────────────────────────────────────────────
//  Element scan — the 🧪 test, run over every saved mapping
//
//  Deliberately ON DEMAND ONLY. It moves real focus and synthesises real key
//  presses on the client's page, so it must never be wired into
//  loadMappingsList() or the auto-apply on panel open (search: applyAllMappings
//  ({ silent: true })) — that is exactly where it would look natural and be
//  wrong. The only entry points are #elemScanBtn and #elemScanReportBtn.
//
//  Needs no API key: nothing here touches U1AI.
// ─────────────────────────────────────────────────────────────────────────────

let elemScanResults = [];
let elemScanActiveStatus = '*';
// 'here' shows only the page in front; 'all' every page the run drove. Here
// first: the person is looking at one page and wants to work it, then move on.
let elemScanPageFilter = 'here';
let elemScanRunning = false;
let elemScanAbort = false;

// Ordered worst-first, so the chip row reads the way the work should be done.
const ELEM_STATUS_META = {
  fail:    { label: 'Failed',      chip: 'sev-critical' },
  warn:    { label: 'Warnings',    chip: 'sev-medium' },
  pass:    { label: 'Passed',      chip: 'sev-pass' },
  notapplied: { label: 'Not applied here', chip: 'sev-medium' },
  absent:  { label: 'Not on page', chip: '' },
  skipped: { label: 'Skipped',     chip: '' },
  error:   { label: 'Errors',      chip: 'sev-high' },
};


function renderElemScanFilters() {
  const el = document.getElementById('elemScanFilters');
  if (!el) return;
  const hereUrl = cleanPageUrl(elemScanHereUrl);
  const onHere = (r) => !r.pageUrl || !hereUrl || cleanPageUrl(r.pageUrl) === hereUrl;
  const pool = elemScanPageFilter === 'here' ? elemScanResults.filter(onHere) : elemScanResults;
  const others = elemScanResults.length - elemScanResults.filter(onHere).length;
  const counts = {};
  for (const r of pool) counts[r.status] = (counts[r.status] || 0) + 1;
  const chip = (s, label, n) =>
    `<button class="scan-chip ${s === '*' ? '' : (ELEM_STATUS_META[s]?.chip || '')} ${elemScanActiveStatus === s ? 'active' : ''}" data-elem-status="${escapeHtml(s)}">${escapeHtml(label)} <span class="n">${n}</span></button>`;
  const chips = Object.keys(ELEM_STATUS_META)
    .filter(s => counts[s])
    .map(s => chip(s, ELEM_STATUS_META[s].label, counts[s]))
    .join('');
  const pageRow = others > 0 || elemScanPageFilter === 'all'
    ? `<div class="scan-filter-row scan-page-row">
        <button class="scan-chip ${elemScanPageFilter === 'here' ? 'active' : ''}" data-elem-page="here">This page <span class="n">${elemScanResults.filter(onHere).length}</span></button>
        <button class="scan-chip ${elemScanPageFilter === 'all' ? 'active' : ''}" data-elem-page="all">All pages <span class="n">${elemScanResults.length}</span></button>
       </div>` : '';
  el.innerHTML = pageRow + `<div class="scan-filter-row">${chip('*', 'All', pool.length)}${chips}</div>`;
}
// The page the results are looked at from — the tab's URL when the run ended
// (or was reopened), so "this page" means the one in front, not the one the
// run happened to start on.
let elemScanHereUrl = '';
function elemScanFiltered() {
  const hereUrl = cleanPageUrl(elemScanHereUrl);
  return elemScanResults.filter(r =>
    (elemScanActiveStatus === '*' || r.status === elemScanActiveStatus) &&
    (elemScanPageFilter === 'all' || !r.pageUrl || !hereUrl || cleanPageUrl(r.pageUrl) === hereUrl));
}

/** One mapping's result card — the list, the dialog and the live table share it. */
function elemResultItemHtml(r, open) {
  const gi = elemScanResults.indexOf(r);
  const meta = ELEM_STATUS_META[r.status] || { label: r.status, chip: '' };
  const testable = r.status === 'pass' || r.status === 'warn' || r.status === 'fail';
  return `
    <div class="scan-item elem-result ${meta.chip}" data-elem-idx="${gi}" data-elem-key="${escapeHtml(r.key || '')}">
      <div class="scan-item-main">
        <span class="scan-sev-badge ${meta.chip}">${escapeHtml(meta.label)}</span>
        <span class="scan-issue-title" title="u1.fix.${escapeHtml(r.type)}">${r.fixNo != null ? `Fix #${escapeHtml(String(r.fixNo))} · ` : ''}${escapeHtml(r.label || r.type)}</span>
        ${r.primary ? `<button class="btn-ghost btn-xs scan-hl" title="Show it on the page" aria-label="Show it on the page">🔍</button>` : ''}
        ${testable ? `<span class="pills">${testPillsHtml([...r.staticSteps, ...r.keyboardSteps])}</span>` : ''}
      </div>
      ${r.primary ? `<div class="scan-context elem-sel"><code class="scan-detail">${escapeHtml(r.primary)}</code></div>` : ''}
      ${r.reason ? `<div class="scan-context">${escapeHtml(r.reason)}</div>` : ''}
      ${testable ? `
      <details class="scan-why"${open ? ' open' : ''}>
        <summary>What was tested</summary>
        <div class="test-section-title">🏷️ Accessibility (code) <span class="pills">${testPillsHtml(r.staticSteps)}</span></div>
        <ul class="test-steps">${testStepListHtml(r.staticSteps)}</ul>
        <div class="test-section-title">⌨️ Keyboard navigation <span class="pills">${testPillsHtml(r.keyboardSteps)}</span></div>
        <ul class="test-steps">${testStepListHtml(r.keyboardSteps)}</ul>
      </details>` : ''}
    </div>`;
}

// ── The saved-mappings table, live ────────────────────────────────────────────
//
// Each row's verdict chip moves as its mapping is driven — "testing…" while it
// is, the verdict the moment it is done — so the table is the place to watch
// a run, and, when the run is over, the place to open any one result: the
// chip is a button and opens the result in a dialog.
const ELEM_CHIP = { pass: '✓ pass', warn: '! warn', fail: '✕ fail', error: '? error', notapplied: '– not applied', skipped: '– skipped', absent: '– not on page', testing: '⏳ testing…' };
function elemTableMark(key, status) {
  const row = document.querySelector(`.saved-mappings-row[data-key="${CSS.escape(key)}"]`);
  if (!row) return;
  const cell = row.querySelector('.sm-actions');
  if (!cell) return;
  let chip = cell.querySelector('.sm-test');
  if (!chip) { chip = document.createElement('button'); chip.type = 'button'; cell.prepend(chip); }
  chip.className = `sm-test ${status}`;
  chip.dataset.openResult = key;
  chip.title = status === 'testing' ? 'Being driven right now' : 'Open this result';
  chip.textContent = ELEM_CHIP[status] || status;
  row.classList.toggle('is-testing', status === 'testing');
  if (status === 'testing') { try { row.scrollIntoView({ block: 'nearest' }); } catch {} }
}
async function openElemResultDialog(key) {
  let r = elemScanResults.find(x => x.key === key);
  if (!r) { const run = await loadElemLastRun(); r = run && run.results ? run.results.find(x => x.key === key) : null; }
  document.getElementById('elemResultDialog')?.remove();
  const dlg = document.createElement('div');
  dlg.id = 'elemResultDialog';
  dlg.className = 'elem-modal';
  dlg.innerHTML = `<div class="elem-modal-box" role="dialog" aria-modal="true" aria-label="Mapping test result">
      <button type="button" class="elem-modal-close" aria-label="Close">✕</button>
      ${r ? elemResultItemHtml(r, true) : '<div class="empty-state">No result for this mapping yet — run the test.</div>'}
      ${r && r.pageTitle ? `<div class="scan-context">Tested on: ${escapeHtml(r.pageTitle)}${r.pageUrl ? ` <a href="${escapeHtml(r.pageUrl)}" class="elem-page-link" data-goto="${escapeHtml(r.pageUrl)}">↗</a>` : ''}</div>` : ''}
    </div>`;
  document.body.appendChild(dlg);
  const close = () => dlg.remove();
  dlg.addEventListener('click', (e) => { if (e.target === dlg || e.target.closest('.elem-modal-close')) close(); });
  document.addEventListener('keydown', function esc(e) { if (e.key === 'Escape') { close(); document.removeEventListener('keydown', esc); } });
  dlg.querySelector('.elem-modal-close')?.focus();
}
document.addEventListener('click', (e) => {
  const chip = e.target.closest('#elemScanSaved .sm-test[data-open-result]');
  if (!chip) return;
  e.preventDefault(); e.stopPropagation();
  openElemResultDialog(chip.dataset.openResult);
}, true);

function renderElemScanResults() {
  const wrap = document.getElementById('elemScanResults');
  if (!wrap) return;
  let list = elemScanFiltered();
  // The scan tests what is on THIS page. Mappings that belong to other pages
  // are not results — one line says how many, and the "Not on page" chip
  // lists them for whoever wants to know which.
  let absentNote = '';
  if (elemScanActiveStatus === '*') {
    const absent = list.filter(r => r.status === 'absent');
    if (absent.length) {
      list = list.filter(r => r.status !== 'absent');
      absentNote = `<div class="elem-absent-note">${absent.length} mapping${absent.length === 1 ? ' belongs' : 's belong'} to other pages — not tested here. Open those pages and run the scan there.</div>`;
    }
  }
  if (!list.length) {
    const others = elemScanPageFilter === 'here' ? elemScanResults.filter(r => r.pageUrl && cleanPageUrl(r.pageUrl) !== cleanPageUrl(elemScanHereUrl)).length : 0;
    wrap.innerHTML = absentNote || (others
      ? `<div class="empty-state">Nothing was tested on this page. ${others} result${others === 1 ? '' : 's'} on other pages — switch to “All pages” above.</div>`
      : '<div class="empty-state">Nothing matches this filter.</div>');
    return;
  }
  const item = (r) => elemResultItemHtml(r);
  // Skipped rows say the same sentence each — "custom mapping, nothing to
  // drive", "legacy, re-add it". One folded line at the end holds them all;
  // the "Skipped" chip above still lists them on their own.
  let skippedNote = '';
  if (elemScanActiveStatus === '*') {
    const sk = list.filter(r => r.status === 'skipped');
    if (sk.length) {
      list = list.filter(r => r.status !== 'skipped');
      skippedNote = `<details class="elem-skipped"><summary>${sk.length} not tested — custom or legacy mappings the keyboard test cannot drive</summary>${sk.map(item).join('')}</details>`;
    }
  }
  if (!list.length && skippedNote) { wrap.innerHTML = absentNote + skippedNote; return; }
  // One accordion per page the run drove — the page's title as the heading,
  // its address one click away, the mappings tested there inside. A run that
  // stayed on one page is one flat list, as before.
  const pages = new Map();
  for (const r of list) {
    const k = r.pageUrl ? cleanPageUrl(r.pageUrl) : '';
    if (!pages.has(k)) pages.set(k, { url: r.pageUrl || '', title: r.pageTitle || '', rows: [] });
    pages.get(k).rows.push(r);
  }
  if (pages.size <= 1) { wrap.innerHTML = absentNote + list.map(item).join('') + skippedNote; return; }
  const pathOf = (u) => { try { const x = new URL(u); return (x.pathname + x.search) || '/'; } catch { return u; } };
  wrap.innerHTML = absentNote + [...pages.values()].map((pg, i) => {
    const failed = pg.rows.filter(r => r.status === 'fail').length;
    const warned = pg.rows.filter(r => r.status === 'warn').length;
    const passed = pg.rows.filter(r => r.status === 'pass').length;
    return `
    <details class="elem-page${failed ? ' has-fail' : ''}" ${i === 0 || failed ? 'open' : ''}>
      <summary>
        <span class="elem-page-title">${escapeHtml(pg.title || pathOf(pg.url) || 'this page')}</span>
        <span class="pills">${passed ? `<span class="pill pass">${passed}✓</span>` : ''}${failed ? `<span class="pill fail">${failed}✕</span>` : ''}${warned ? `<span class="pill warn">${warned}⚠</span>` : ''}</span>
        ${pg.url ? `<a class="elem-page-link" href="${escapeHtml(pg.url)}" data-goto="${escapeHtml(pg.url)}" title="${escapeHtml(pg.url)}">↗ ${escapeHtml(pathOf(pg.url).slice(0, 40))}${pathOf(pg.url).length > 40 ? '…' : ''}</a>` : ''}
      </summary>
      ${pg.rows.map(item).join('')}
    </details>`;
  }).join('') + skippedNote;
}

// The engine streams a step the moment it happens. A run of eleven mappings is
// two minutes of the page driving itself; without this the panel just sits.
function elemScanLiveStep(msg) {
  const box = document.getElementById('elemScanProgress');
  if (!box) return;
  if (msg.type === 'u1-test-start') {
    const ul = box.querySelector('#elemScanLiveSteps');
    if (ul) ul.innerHTML = '';
  } else if (msg.type === 'u1-test-step' && msg.step) {
    const ul = box.querySelector('#elemScanLiveSteps');
    if (ul) { ul.insertAdjacentHTML('beforeend', testStepRowHtml(msg.step)); ul.lastElementChild?.scrollIntoView({ block: 'nearest' }); }
  }
}

function elemScanProgressHtml(n, total, m) {
  return `
    <div class="test-head">
      <strong>Testing ${n} of ${total}</strong>
      <code>${escapeHtml(m.primary || m.firstArg || '')}</code>
      <span class="test-live-tag">${escapeHtml(m.type)}</span>
    </div>
    <ul class="test-steps" id="elemScanLiveSteps"></ul>`;
}

/**
 * @param {string} [onlyKey] mappingKey of a single mapping to test. Given, the
 *   run is that one mapping — this is what the 🧪 button in the Mappings drawer
 *   hands over, so the per-mapping test and the all-of-them test produce the
 *   same report in the same place instead of two different kinds of answer in
 *   two different tabs.
 */
// Send a tab back to `url` and wait until it is really there — `complete`, AND
// on that URL. A fixed sleep is too short on a slow site and wasted on a fast
// one, so it is polled, and capped, because a page that never comes back must
// not hold a run forever. Returns whether it made it.
async function returnTabTo(tabId, url) {
  try { await chrome.tabs.update(tabId, { url }); } catch { return false; }
  const want = cleanPageUrl(url);
  for (let i = 0; i < 60; i++) {
    await new Promise((r) => setTimeout(r, 250));
    const t = await chrome.tabs.get(tabId).catch(() => null);
    if (t && t.status === 'complete' && cleanPageUrl(t.url) === want) return true;
  }
  return false;
}

/**
 * The page LEFT mid-run. Get back to `url`, then wait until the page is
 * really ready to be tested again — not just loaded, but with U1 and the
 * mappings re-applied — before the next mapping is driven.
 *
 * Three steps, gentlest first:
 *   1. history back — the same as the person pressing Back, no reload of
 *      the page's state beyond what the site does itself;
 *   2. wait for the person — "come back to the page and the test carries
 *      on"; a long, live countdown, and Stop still works;
 *   3. a hard re-navigation as the last resort, as before.
 * Whichever brought it back, the run then waits for the patch and the
 * library to be present on the page again, because testing a mapping half
 * a second after `complete` — before auto-apply has run — fails it for the
 * wrong reason.
 */
async function awaitReturn(tabId, url, status) {
  const want = cleanPageUrl(url);
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const there = async () => {
    const t = await chrome.tabs.get(tabId).catch(() => null);
    return !!(t && t.status === 'complete' && cleanPageUrl(t.url) === want);
  };
  // By itself: Back in the history, and if that did not land within a few
  // seconds, a plain navigation to the page — no waiting on the person. (It
  // used to hold for three minutes asking them to come back; a run that
  // stops to ask is a run nobody finishes.)
  let back = false;
  try { await chrome.tabs.goBack(tabId); } catch {}
  for (let i = 0; i < 16 && !back && !elemScanAbort; i++) { await sleep(250); back = await there(); }
  if (!back && !elemScanAbort) {
    showNotice(status, `The page moved to somewhere else — bringing it back to ${want}…`, 'warn', 0);
    back = await returnTabTo(tabId, url);
  }
  if (!back) return false;
  // Ready to test: the patch and the library are on the page again.
  for (let i = 0; i < 32; i++) {
    const ok = await inPage(tabId, () => !!(window.__u1Patch && (window.u1 || window.U1 || window.user1st))).catch(() => false);
    if (ok) break;
    await sleep(250);
  }
  await sleep(700);
  return true;
}

/** Navigate the tab to `url` and wait until it is loaded AND the patch + library are on it. */
async function gotoPageReady(tabId, url) {
  const want = cleanPageUrl(url);
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  try { await chrome.tabs.update(tabId, { url }); } catch { return false; }
  let there = false;
  for (let i = 0; i < 120 && !there; i++) {
    await sleep(250);
    const t = await chrome.tabs.get(tabId).catch(() => null);
    there = !!(t && t.status === 'complete' && cleanPageUrl(t.url) === want);
    if (elemScanAbort) return false;
  }
  if (!there) return false;
  for (let i = 0; i < 32; i++) {
    const ok = await inPage(tabId, () => !!(window.__u1Patch && (window.u1 || window.U1 || window.user1st))).catch(() => false);
    if (ok) break;
    await sleep(250);
  }
  await sleep(700);
  return true;
}

// ── What the last dynamic scan said about each mapping ──────────────────────
//
// Kept locally (private prefix: never synced, never exported), keyed by the
// mapping key, so the Mappings drawer and the saved-mappings table can say
// "passed" / "failed" on the row itself without the Scan tab open.
const elemTestStoreKey = (host) => (U1Store.PRIVATE_PREFIX || '__') + 'elemTest_' + (host || currentHostname);
async function loadElemTested() {
  try {
    const k = elemTestStoreKey();
    const v = (await U1Store.get([k]))[k];
    return new Map(Object.entries(v && typeof v === 'object' ? v : {}));
  } catch { return new Map(); }
}
// The whole last run (steps and all), so the Dynamic pane reopens on it and
// a drawer row's verdict can be clicked through to the result it came from.
const elemLastRunKey = (host) => (U1Store.PRIVATE_PREFIX || '__') + 'elemLastRun_' + (host || currentHostname);
async function loadElemLastRun() {
  try { const k = elemLastRunKey(); const v = (await U1Store.get([k]))[k]; return v && Array.isArray(v.results) ? v : null; }
  catch { return null; }
}
async function rememberElemLastRun(results) {
  try {
    const slim = (results || []).map(r => ({ ...r, screenshot: undefined, inspect: undefined }));
    await U1Store.setLocalOnly({ [elemLastRunKey()]: { at: Date.now(), results: slim } });
  } catch {}
}
/** From a mapping row to the result the last dynamic scan gave it. */
async function openElemResultFor(key) {
  document.querySelector('.tab-btn[data-tab="scan"]')?.click();
  if (!elemScanResults.length) {
    const run = await loadElemLastRun();
    if (run && run.results) { elemScanResults = run.results; elemScanActiveStatus = '*'; }
  }
  { const t = await getTab().catch(() => null); elemScanHereUrl = (t && t.url) || ''; }
  if (!elemScanResults.some(r => r.key === key)) elemScanActiveStatus = '*';
  // The row may be on another page; show all pages so it can be found.
  const hit = elemScanResults.find(r => r.key === key);
  elemScanPageFilter = (hit && hit.pageUrl && cleanPageUrl(hit.pageUrl) !== cleanPageUrl(elemScanHereUrl)) ? 'all' : 'here';
  showOnlyScan('mappings');
  document.getElementById('elemScanCount').textContent = elemRunCountText(elemScanResults);
  renderElemScanFilters(); renderElemScanResults();
  document.getElementById('elemScanClearBtn').style.display = elemScanResults.length ? '' : 'none';
  document.getElementById('elemScanReportRow').style.display = elemScanResults.length ? '' : 'none';
  const row = document.querySelector(`#elemScanResults .scan-item[data-elem-key="${CSS.escape(key)}"]`);
  if (!row) return;
  const group = row.closest('details'); if (group) group.open = true;
  row.scrollIntoView({ block: 'center', behavior: 'smooth' });
  row.classList.add('located');
  setTimeout(() => row.classList.remove('located'), 2600);
}

async function rememberElemTested(results) {
  try {
    const have = await loadElemTested();
    const at = Date.now();
    for (const r of results || []) {
      if (!r || !r.key || !['pass', 'warn', 'fail', 'error'].includes(r.status)) continue;
      have.set(r.key, { status: r.status, at, fail: (r.counts && r.counts.fail) || 0, warn: (r.counts && r.counts.warn) || 0 });
    }
    const obj = {};
    for (const [k, v] of [...have.entries()].slice(-800)) obj[k] = v;
    await U1Store.setLocalOnly({ [elemTestStoreKey()]: obj });
  } catch {}
}

async function runElementScan(onlyKey, opts) {
  // onlyHere: the page in front and nothing else — no travelling. The default
  // "Test this page" button; "Test all pages" is the one that walks the site.
  const onlyHere = !!(opts && opts.onlyHere);
  const status = document.getElementById('elemScanStatus');
  const btn = document.getElementById('elemScanBtn');
  const hereBtn = document.getElementById('elemScanHereBtn');
  const stopBtn = document.getElementById('elemScanStopBtn');
  const progress = document.getElementById('elemScanProgress');
  const tab = await getTab();
  if (!isInjectable(tab)) { showNotice(status, 'Cannot run on this page.', 'error', 4000); return; }

  const key = storageKey('mappings', currentHostname);
  let all = (await U1Store.get([key]))[key] || [];
  if (onlyKey) {
    all = all.filter(m => typeof m === 'object' && mappingKey(m) === onlyKey);
    if (!all.length) {
      showNotice(status, 'That mapping is no longer saved for this site.', 'error', 5000);
      return;
    }
  }
  if (!all.length) {
    showNotice(status, 'No saved mappings for this site yet — add some in the Picker tab.', 'info', 5000);
    return;
  }

  // A custom aria-label mapping has no widget behaviour to drive, and a legacy
  // string entry has no type at all. Report them rather than pretending.
  const results = [];
  const candidates = [];
  for (const m of all) {
    // Grouped by page below (renderElemScanResults): every row needs a real
    // page name, or the group falls back to a placeholder title. These are
    // reported without ever being driven, so they carry the page they were
    // captured on if there is one, and this page otherwise — never blank.
    const ownPage = (typeof m === 'object' && m.pageUrl) ? { pageUrl: m.pageUrl, pageTitle: m.pageTitle || '' }
      : { pageUrl: tab.url, pageTitle: tab.title || '' };
    if (typeof m !== 'object' || !m.type) {
      results.push({ type: 'legacy', primary: typeof m === 'string' ? m : (m && (m.primary || m.firstArg)) || '(no selector saved)', status: 'skipped', ...ownPage,
        reason: 'Legacy mapping — re-add it to test it.', staticSteps: [], keyboardSteps: [] });
    } else if (m.custom) {
      results.push({ ...pickMappingFields(m), status: 'skipped', ...ownPage,
        reason: 'Custom mapping — nothing for the keyboard test to drive.', staticSteps: [], keyboardSteps: [] });
    } else {
      candidates.push(m);
    }
  }

  // One probe for the whole list. Without this, a site with thirty mappings
  // spends minutes driving elements that are not on the page being looked at.
  //
  // present alone marks anything not VISIBLE RIGHT NOW as absent — which
  // wrongly skipped every dialog/dropdown mapping whose widget only exists in
  // the DOM while open, even standing on the exact page it belongs to. Same
  // rule as everywhere else this question is asked: mappingOnPage also
  // accepts "captured on this exact URL" (see its own comment for why).
  const present = await selectorsPresentOnPage(candidates.map(m => m.primary || m.firstArg || ''));
  const hereUrl = cleanPageUrl(tab && tab.url);
  const toTest = [];
  // "Test everything": a mapping that is not on this page but was captured
  // on a known page is tested THERE — the run visits each such page in turn
  // and comes back. Only the all-mappings run travels; the 🧪 on one row
  // tests it where you stand.
  const elsewhere = new Map(); // cleanPageUrl → { url, title, list }
  for (const m of candidates) {
    if (mappingOnPage(m, present, hereUrl)) { toTest.push(m); continue; }
    const pu = (m.pageUrl && sameSiteUrl(m.pageUrl)) ? cleanPageUrl(m.pageUrl) : '';
    if (!onlyKey && !onlyHere && pu && pu !== hereUrl) {
      if (!elsewhere.has(pu)) elsewhere.set(pu, { url: m.pageUrl, title: m.pageTitle || '', list: [] });
      elsewhere.get(pu).list.push(m);
      continue;
    }
    // A this-page run does not carry the other pages' mappings as rows at all —
    // they are not "absent", they were simply not asked about.
    if (onlyHere && pu && pu !== hereUrl) continue;
    results.push({ ...pickMappingFields(m), status: 'absent', pageUrl: m.pageUrl || tab.url, pageTitle: m.pageTitle || tab.title || '',
      reason: 'Not on this page right now — open the page or the dialog it belongs to, then run this again.',
      staticSteps: [], keyboardSteps: [] });
  }

  elemScanRunning = true;
  elemScanAbort = false;
  btn.disabled = true;
  if (hereBtn) hereBtn.disabled = true;
  stopBtn.style.display = '';
  showOnlyScan('mappings');
  document.getElementById('elemScanReportRow').style.display = 'none';
  progress.style.display = (toTest.length || elsewhere.size) ? 'block' : 'none';
  // A run starting must not sit ALONGSIDE the previous one's finished summary
  // and result list — "37 tested · 4 failing (saved …)" above a brand new
  // "Testing 1 of 40" reads as two runs at once. Cleared here, before the
  // first mapping is driven; the real numbers return when this run ends.
  {
    const cnt = document.getElementById('elemScanCount');
    if (cnt) cnt.textContent = 'Running…';
    const resBox = document.getElementById('elemScanResults');
    if (resBox) resBox.innerHTML = '';
    const filt = document.getElementById('elemScanFilters');
    if (filt) filt.innerHTML = '';
    document.getElementById('elemScanClearBtn').style.display = 'none';
  }

  const pagesTotal = 1 + elsewhere.size;
  let pageNo = 1;
  let travelled = false;
  const grandTotal = toTest.length + [...elsewhere.values()].reduce((n, p) => n + p.list.length, 0);
  let done = 0;
  try {
   // One page's batch. `pageUrl` is where these belong; a navigation away
   // from it mid-batch is put back before the next mapping.
   const runBatch = async (batch, pageUrl, pageTitle) => {
    const urlBefore = cleanPageUrl(pageUrl);
    // Applied BEFORE they are tested — but only the ones that need it. A page
    // loaded before the mappings were saved, or with auto-apply off, has
    // undecorated widgets, and testing those reported a working mapping as
    // five keyboard failures. Re-applying EVERY mapping on EVERY run was the
    // over-correction: most of them are already live (auto-apply put them
    // there), so re-running all twenty took as long as testing them and did
    // nothing to eighteen of them. One cheap read decides which — the same
    // "does it carry U1's marks" check the drawer already uses to show ✓/saved.
    const nonCustom = batch.filter(m => !m.custom);
    if (nonCustom.length && isInjectable(tab)) {
      let needApply = nonCustom;
      try {
        const [chk] = await chrome.scripting.executeScript({
          target: { tabId: tab.id }, world: 'MAIN',
          // ANY copy of the selector's matches, or the trigger, wearing a mark
          // counts. querySelector's first match was the hidden mobile copy on
          // the very pages that have two, and a listbox decorates its trigger
          // long before its list — both read "not applied" and were re-applied
          // every run, for nothing.
          func: (items) => items.map(([sel, trig]) => {
            const marked = (el) => !!el && (Array.from(el.attributes).some(a => /^(role|tabindex)$|^aria-|^u1st-/.test(a.name)) || !!el.querySelector('[role],[aria-haspopup],[aria-expanded],[u1st-avoid-change-detection]'));
            let els = []; try { els = Array.from(document.querySelectorAll(sel)); } catch (e) {}
            if (!els.length) return true; // not found — let applyMappingsBatch report that properly
            if (els.some(marked)) return false;
            let trigs = []; try { trigs = trig ? Array.from(document.querySelectorAll(trig)) : []; } catch (e) {}
            return !trigs.some(marked);
          }),
          args: [nonCustom.map(m => [m.primary || m.firstArg || '', ((m.config || {}).selectors || {}).trigger || ''])],
        });
        const need = (chk && chk.result) || nonCustom.map(() => true);
        needApply = nonCustom.filter((_, i) => need[i]);
      } catch { /* couldn't tell — apply all, the safe direction */ }
      if (needApply.length) {
        showNotice(status, `Applying ${needApply.length} of ${nonCustom.length} mapping${nonCustom.length === 1 ? '' : 's'} not yet on this page…`, 'warn', 0);
        try {
          await applyMappingsBatch(needApply.map(m => ({ type: m.type, primary: m.primary, firstArg: m.firstArg, config: m.config, overwriteRole: m.overwriteRole })));
        } catch {}
        await new Promise(r => setTimeout(r, 900));
      }
    }
    for (let i = 0; i < batch.length; i++) {
      if (elemScanAbort) break;
      const m = batch[i];
      done++;
      progress.innerHTML = (pagesTotal > 1 ? `<div class="test-head"><strong>Page ${pageNo} of ${pagesTotal}</strong> <span class="test-live-tag">${escapeHtml(pageTitle || cleanPageUrl(pageUrl))}</span></div>` : '') + elemScanProgressHtml(done, grandTotal, m);
      showNotice(status, `Testing ${done} of ${grandTotal}${pagesTotal > 1 ? ` (page ${pageNo} of ${pagesTotal})` : ''} — watch the page.`, 'warn', 0);

      elemTableMark(mappingKey(m), 'testing');
      const t0 = Date.now();
      let res = null;
      let errMsg = '';
      try {
        // A widget that never settles must not hold the whole run. The engine's
        // own waits are per-assertion; this is the ceiling for the mapping.
        res = await Promise.race([
          callTestEngine('runTest', [m.type, m.primary || m.firstArg || '',
            (m.config && typeof m.config === 'object') ? m.config : { selectors: {} }], tab),
          new Promise(r => setTimeout(() => r({ __timeout: true }), 15000)),
        ]);
      } catch (e) {
        errMsg = e?.message || String(e);
      }

      if (res && res.__timeout) {
        results.push({ ...pickMappingFields(m), status: 'error', reason: 'Timed out after 15 seconds.',
          staticSteps: [], keyboardSteps: [], ms: Date.now() - t0 });
      } else if (!res || !res.static) {
        results.push({ ...pickMappingFields(m), status: 'error',
          reason: (res && res.__err) ? `Could not run the test: ${res.__err}.` : (errMsg || 'Could not run the test — the page may have changed while testing.'),
          staticSteps: [], keyboardSteps: [], ms: Date.now() - t0 });
      } else {
        const staticSteps = res.static.steps || [];
        const keyboardSteps = (res.keyboard && res.keyboard.steps) || [];
        const all2 = [...staticSteps, ...keyboardSteps];
        const fail = all2.filter(s => s.status === 'fail').length;
        const warn = all2.filter(s => s.status === 'warn').length;
        const closed = !!(res.keyboard && res.keyboard.closed);
        results.push({
          ...pickMappingFields(m),
          status: closed ? 'skipped' : res.notApplied ? 'notapplied' : fail ? 'fail' : warn ? 'warn' : 'pass',
          reason: closed ? 'Open this dialog on the page, then test it — it has no trigger the test can press, so it can only be checked while open.'
            : res.notApplied ? (res.notApplied === 'missing' ? 'Nothing matches its selector on this page right now.' : 'The engine has not decorated it on this page — the roles are missing. Not a keyboard failure; the fix did not take here.') : '',
          staticSteps, keyboardSteps, inspect: res.inspect,
          counts: { pass: all2.length - fail - warn, fail, warn },
          ms: Date.now() - t0,
        });
      }

      // Pressed, and the page LEFT — put it back and WAIT for it before the next
      // mapping, or everything after this one is tested against the wrong page.
      // Reported on the mapping that did it: a component that navigates the
      // site when driven is itself a finding, not just an inconvenience.
      // Stamp the page this was tested on — the results group by it.
      { const last = results[results.length - 1]; if (last && !last.pageUrl) { last.pageUrl = pageUrl; last.pageTitle = pageTitle; } }
      // And the table row moves with it, now, so the run can be watched there.
      { const last = results[results.length - 1]; if (last) elemTableMark(mappingKey(m), last.status); }

      const nowTab = await chrome.tabs.get(tab.id).catch(() => null);
      const urlNow = cleanPageUrl(nowTab && nowTab.url);
      if (urlBefore && urlNow && urlNow !== urlBefore) {
        const last = results[results.length - 1];
        const note = `Driving this mapping navigated the page to ${urlNow} — it was put back before the next one.`;
        if (last) last.reason = last.reason ? `${last.reason} ${note}` : note;
        showNotice(status, `The page went to ${urlNow} — going back before continuing.`, 'warn', 0);
        const back = await awaitReturn(tab.id, pageUrl, status);
        if (!back) {
          // Could not get back within the cap. Going on would measure every
          // remaining mapping against a page they were never on; say so for
          // each rather than let them show as tested.
          for (const rest of batch.slice(i + 1)) {
            results.push({ ...pickMappingFields(rest), status: 'error', pageUrl, pageTitle,
              reason: `Not tested — the page had navigated to ${urlNow} and could not be brought back to ${urlBefore}.`,
              staticSteps: [], keyboardSteps: [] });
          }
          break;
        }
      }

      // Leave the page as we found it before the next mapping. The dialog branch
      // closes what it opens, but menu/listbox/combobox can leave a popup open —
      // and an open menu swallows the next mapping's key presses.
      await callTestEngine('removeHud', [], tab).catch(() => {});
      await inPage(tab.id, () => {
        const el = document.activeElement;
        if (el) {
          el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
          if (typeof el.blur === 'function') el.blur();
        }
      }).catch(() => {});
      await new Promise(r => setTimeout(r, 200));
    }
   };

   await runBatch(toTest, tab.url, tab.title || '');

   // The other pages, one at a time.
   for (const pg of elsewhere.values()) {
     if (elemScanAbort) break;
     pageNo++;
     travelled = true;
     showNotice(status, `Opening ${pg.title || cleanPageUrl(pg.url)} to test ${pg.list.length} mapping${pg.list.length === 1 ? '' : 's'} that belong${pg.list.length === 1 ? 's' : ''} there…`, 'warn', 0);
     progress.innerHTML = `<div class="test-head"><strong>Page ${pageNo} of ${pagesTotal}</strong> <span class="test-live-tag">${escapeHtml(pg.title || cleanPageUrl(pg.url))}</span></div><ul class="test-steps"><li>Opening the page…</li></ul>`;
     const ready = await gotoPageReady(tab.id, pg.url);
     if (!ready) {
       for (const m of pg.list) results.push({ ...pickMappingFields(m), status: 'error', pageUrl: pg.url, pageTitle: pg.title,
         reason: `Not tested — ${cleanPageUrl(pg.url)} did not finish loading.`, staticSteps: [], keyboardSteps: [] });
       continue;
     }
     // What is really there, now that we are on it.
     const there = await selectorsPresentOnPage(pg.list.map(m => m.primary || m.firstArg || ''));
     const here2 = cleanPageUrl(pg.url);
     const batch = [];
     for (const m of pg.list) {
       if (mappingOnPage(m, there, here2)) batch.push(m);
       else results.push({ ...pickMappingFields(m), status: 'absent', pageUrl: pg.url, pageTitle: pg.title,
         reason: 'Not found on the page it was captured on — the page changed, or the element only exists in a state the scan cannot reach.', staticSteps: [], keyboardSteps: [] });
     }
     await runBatch(batch, pg.url, pg.title || '');
   }
   if (travelled) {
     showNotice(status, `Coming back to ${cleanPageUrl(tab.url)}…`, 'warn', 0);
     await gotoPageReady(tab.id, tab.url);
   }
  } finally {
    elemScanRunning = false;
    elemScanAbort = false;
    btn.disabled = false;
    if (hereBtn) hereBtn.disabled = false;
    stopBtn.style.display = 'none';
    stopBtn.disabled = false;
    stopBtn.textContent = '■ Stop';
    progress.style.display = 'none';
    progress.innerHTML = '';
    await callTestEngine('removeHud', [], tab).catch(() => {});
  }

  elemScanResults = results;
  elemScanActiveStatus = '*';
  elemScanPageFilter = 'here';
  elemScanHereUrl = tab.url || '';
  rememberElemTested(results).then(() => { loadMappingsList().catch(() => {}); }).catch(() => {});
  rememberElemLastRun(results).catch(() => {});
  const tested = results.filter(r => ['pass', 'warn', 'fail'].includes(r.status)).length;
  const failed = results.filter(r => r.status === 'fail').length;
  document.getElementById('elemScanCount').textContent = elemRunCountText(results);
  renderElemScanFilters();
  renderElemScanResults();
  document.getElementById('elemScanClearBtn').style.display = '';
  document.getElementById('elemScanReportRow').style.display = results.length ? '' : 'none';
  showNotice(status, tested
    ? `Tested ${tested} mapping${tested === 1 ? '' : 's'}. ${failed} need${failed === 1 ? 's' : ''} work.`
    : 'Nothing could be tested on this page — see the list below for why.',
    failed ? 'warn' : 'success', 6000);

  // The hold is over and the results are painted; the front tab decides what
  // the panel shows next. Done AFTER the rendering above, or the hand-back's
  // own redraw would be painted over with the old site's results.
  const front = await getTab().catch(() => null);
  if (front) await onTabChanged(front);
}

// The fields the element scan carries forward from a saved mapping.
function pickMappingFields(m) {
  return {
    key: mappingKey(m), fixNo: m.fixNo, id: m.id, type: m.type,
    primary: m.primary || m.firstArg || '', label: m.type,
    screenshot: m.screenshot || null,
  };
}

document.getElementById('elemScanHereBtn')?.addEventListener('click', () => {
  runElementScan(null, { onlyHere: true }).catch(err => {
    elemScanRunning = false;
    showNotice(document.getElementById('elemScanStatus'), 'Failed: ' + err.message, 'error', 6000);
  });
});
document.getElementById('elemScanBtn')?.addEventListener('click', () => {
  runElementScan().catch(err => {
    elemScanRunning = false;
    showNotice(document.getElementById('elemScanStatus'), 'Failed: ' + err.message, 'error', 6000);
  });
});

document.getElementById('elemScanStopBtn')?.addEventListener('click', () => {
  elemScanAbort = true;
  const b = document.getElementById('elemScanStopBtn');
  b.disabled = true;
  b.textContent = 'Stopping…';
});

document.getElementById('elemScanClearBtn')?.addEventListener('click', () => {
  elemScanResults = [];
  document.getElementById('elemScanSection').style.display = 'none';
  document.getElementById('elemScanClearBtn').style.display = 'none';
});

document.getElementById('elemScanFilters')?.addEventListener('click', (e) => {
  const page = e.target.closest('[data-elem-page]');
  if (page) { elemScanPageFilter = page.dataset.elemPage; elemScanActiveStatus = '*'; renderElemScanFilters(); renderElemScanResults(); return; }
  const chip = e.target.closest('[data-elem-status]');
  if (!chip) return;
  elemScanActiveStatus = chip.dataset.elemStatus;
  renderElemScanFilters();
  renderElemScanResults();
});

document.getElementById('elemScanResults')?.addEventListener('click', async (e) => {
  // The page heading's link: go there in THIS tab, so the panel stays on the site.
  const goto = e.target.closest('.elem-page-link');
  if (goto) {
    e.preventDefault(); e.stopPropagation();
    const t = await getTab().catch(() => null);
    if (t) chrome.tabs.update(t.id, { url: goto.dataset.goto }).catch(() => {});
    return;
  }
  if (e.target.closest('.scan-why')) return;
  const item = e.target.closest('.scan-item');
  if (!item) return;
  const r = elemScanResults[Number(item.dataset.elemIdx)];
  if (!r || !r.primary) return;
  const found = await highlightMatch(r.primary, 0, true);
  if (found === false) {
    showNotice(document.getElementById('elemScanStatus'), `Couldn't find "${r.primary}" on the page right now.`, 'warn', 3000);
    return;
  }
  setTimeout(() => highlightMatch(r.primary, 0, false), 3000);
});

document.getElementById('elemScanReportBtn')?.addEventListener('click', async () => {
  const status = document.getElementById('elemScanReportStatus');
  const btn = document.getElementById('elemScanReportBtn');
  btn.disabled = true;
  const original = btn.textContent;
  btn.textContent = 'Building…';
  try {
    const tab = await getTab();
    await generateElementScanReport(currentHostname, elemScanResults, tab?.url || '', tab?.title || '');
    showNotice(status, 'Report opened in a new tab.', 'success', 4000);
  } catch (err) {
    showNotice(status, 'Could not build the report: ' + err.message, 'error', 6000);
  } finally {
    btn.disabled = false;
    btn.textContent = original;
  }
});

document.getElementById('copyTemplateBtn').addEventListener('click', () => {
  const text = $templatePreview.textContent;
  navigator.clipboard.writeText(text).then(() => {
    const btn = document.getElementById('copyTemplateBtn');
    btn.textContent = 'Copied!';
    setTimeout(() => { btn.textContent = 'Copy'; }, 1500);
  });
});

// U1-dependent types that have a DOM-only twin in the same dropdown. Read when
// an apply dies on a missing library, so the error can name the way forward
// instead of only naming the problem. Labels must match panel.html's <option>.
const U1_FREE_ALTERNATIVE = {
  tabs: 'tab strip (custom — full pattern, no U1)',
  grid: 'keyboard grid (custom — arrow nav, no U1)',
  datepicker: 'keyboard grid (custom — arrow nav, no U1)',
  button: 'make keyboard-clickable (custom — all matches)',
  link: 'make keyboard-clickable (custom — all matches)',
};

document.getElementById('applyTemplateBtn').addEventListener('click', async () => {
  if (!currentTemplate) return;
  const status = document.getElementById('applyStatus');
  // Measured, for the same reason Apply All is: applyOne answers ok for any
  // u1.fix call that does not throw, and a fix that lands on nothing does not
  // throw. The template is not saved yet, so it goes to the batch directly.
  if (!currentTemplate.custom) {
    // The same repair as the save path, so Apply cannot look different from
    // what a saved mapping would do.
    const narrowedNow = await narrowContained(currentTemplate);
    if (narrowedNow.length) {
      $templatePreview.textContent = currentTemplate.code;
      showNarrowed(status, narrowedNow);
    }
    const res = await applyMappingsBatch([{
      type: currentTemplate.type, primary: currentTemplate.primary,
      firstArg: currentTemplate.firstArg, config: currentTemplate.config,
      overwriteRole: currentTemplate.overwriteRole,
    }]);
    const v = describeApply(res, currentTemplate);
    if (res.u1Missing) {
      const alt0 = U1_FREE_ALTERNATIVE[currentTemplate.type];
      showNotice(status, 'U1 is not loaded on this page — inject it in Setup first' +
        (alt0 ? `, or pick "${alt0}" in the type list, which runs without U1.` : '.'), 'error', 7000);
      return;
    }
    showNotice(status, v.msg, v.ok ? 'success' : 'error', v.ok ? 4000 : 20000);
    if (v.roleClash && await askRoleClash(v.roleClash)) {
      await applyRoleOverwrite(v.roleClash.sel, v.roleClash.role, status);
    }
    return;
  }
  const result = await applyOne(currentTemplate.type, currentTemplate.firstArg || currentTemplate.primary, currentTemplate.config, currentTemplate.custom, currentTemplate);
  if (result.ok) {
    showNotice(status, 'Applied on page.', 'success');
  } else if (result.u1Missing) {
    // Naming the alternative matters here. The export emits window.u1?.fix.*,
    // so on a page without U1 that code is a silent no-op and the only symptom
    // is "nothing happened" — with no error anywhere to explain it. Say which
    // dropdown entry does work on this page.
    const alt = U1_FREE_ALTERNATIVE[currentTemplate.type];
    showNotice(status, 'U1 is not loaded on this page — inject it in Setup first' +
      (alt ? `, or pick "${alt}" in the type list, which runs without U1.` : '.'),
      'error', 7000);
  } else {
    showNotice(status, 'Error: ' + result.err, 'error', 4500);
  }
});

// Take back exactly what an apply added. Uses the receipt recorded at apply
// time, so only the attributes U1 wrote are removed — the site's own role,
// tabindex and aria-* are left alone, which is why this cannot be done by
// pattern-matching after the fact.
async function revertApplied(receipt) {
  const tab = await getTab();
  if (!isInjectable(tab) || !receipt || !receipt.length) return 0;
  try {
    const res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: (list) => {
        let n = 0;
        for (const { token, added } of list) {
          const el = document.querySelector(`[data-u1-revert="${token}"]`);
          if (!el) continue;
          for (const attr of added) { el.removeAttribute(attr); n++; }
          el.removeAttribute('data-u1-revert');
        }
        return n;
      },
      args: [receipt],
    });
    return (res && res[0] && res[0].result) || 0;
  } catch { return 0; }
}

// A role the site wrote blocks the fix, and the answer is a decision — so it is
// asked as one, in the middle of the screen.
//
// It was a small button appended to the status line at the bottom of the panel,
// where it went unread: the apply had just reported success-shaped text, the
// eye had already moved on, and the one thing standing between the mapping and
// working was a link below the fold. Same question as the save-time clash, so
// it uses the same dialog rather than inventing a second look for it.
function askRoleClash(clash) {
  const dlg = document.getElementById('roleClashDialog');
  if (!dlg || !clash) return Promise.resolve(false);

  document.getElementById('roleClashBody').innerHTML =
    `<code>${escapeHtml(clash.sel)}</code> carries <code>role="${escapeHtml(clash.role)}"</code> ` +
    `in the site's own HTML — we did not put it there. U1 will not write ` +
    `<code>role="${escapeHtml(clash.willWrite)}"</code> over it, so this fix cannot land while it is there.`;

  // "Map it as <role>" belongs to the save-time question, where the type can
  // still be changed before anything exists. Here the mapping is already built
  // and applied; the choice is replace it or leave it.
  const switchBtn = document.getElementById('roleClashSwitch');
  switchBtn.style.display = 'none';
  const over = document.getElementById('roleClashOverwrite');
  const cancel = document.getElementById('roleClashCancel');
  over.textContent = `Replace role="${clash.role}"`;
  cancel.textContent = 'Leave it';

  return new Promise((resolve) => {
    const done = (answer) => {
      dlg.close();
      over.textContent = 'Overwrite it';
      cancel.textContent = 'Cancel';
      switchBtn.style.display = '';
      over.removeEventListener('click', onOver);
      cancel.removeEventListener('click', onCancel);
      resolve(answer);
    };
    const onOver = () => done(true);
    const onCancel = () => done(false);
    over.addEventListener('click', onOver);
    cancel.addEventListener('click', onCancel);
    dlg.showModal();
  });
}

// Work on what is already found, without waiting for the rest of the run.
//
// The components discovered in completed sections existed and were unreachable:
// the list only turned into the components view when the whole run ended. On a
// twenty-six section page that means the first thing found is unusable for
// eight minutes, and if you stop early it was never clear that stopping is what
// releases it.
//
// Stopping IS the release — the run's tail already moves to the components view
// — so this presses Stop for you and waits, rather than inventing a second path
// into the same place.
document.addEventListener('click', async (e) => {
  const btn = e.target.closest('[data-build-found]');
  if (!btn) return;
  e.preventDefault();
  e.stopPropagation();          // it lives inside a <summary>; do not toggle the drawer

  if (aiSweep.running) {
    btn.disabled = true;
    btn.textContent = 'Finishing this section…';
    aiSweep.abort = true;
    // Holding for fixes is a wait on a person, not on work — nothing is going
    // to end it but this. Left alone it span out the full sixty seconds below
    // and then reported the run as still going.
    if (sweepPause.resolve) sweepPause.resolve({ stopped: true });
    // The current section is paid for either way, so it is allowed to land.
    for (let i = 0; i < 400 && aiSweep.running; i++) {
      await new Promise((r) => setTimeout(r, 150));
    }
    return;                     // the run's own tail moves to the components view
  }

  const total = aiSweep.stops.reduce((a, x) => a + ((x.found || []).filter(f => !f.done).length), 0);
  if (!total) return;
  aiSweep.phase = 'components';
  renderSweepPicks();
});

// Back to the sections list, to carry on searching the ones never reached.
document.addEventListener('click', (e) => {
  if (!e.target.closest('[data-back-to-sections]')) return;
  aiSweep.phase = 'screens';
  renderSweepScreens();
});

/** Throwing away the survey — always asked, because it is never nothing. */
function confirmSweepClear() {
  const dlg = document.getElementById('sweepClearDialog');
  if (!dlg) return Promise.resolve(true);
  const stops = aiSweep.stops || [];
  const searched = stops.filter((s) => s.scanned).length;
  document.getElementById('sweepClearBody').textContent =
    `${stops.length} section${stops.length === 1 ? '' : 's'} and their pictures go, for everyone on this project. ` +
    (searched
      ? `${searched} of them ${searched === 1 ? 'has' : 'have'} already been searched, and searching them again costs the same as it did the first time. `
      : 'Walking the page again is free, but it takes a few minutes. ') +
    'Components you have already mapped are not affected.';

  return new Promise((resolve) => {
    const go = document.getElementById('sweepClearGo');
    const cancel = document.getElementById('sweepClearCancel');
    const done = (answer) => {
      dlg.close();
      go.removeEventListener('click', onGo);
      cancel.removeEventListener('click', onCancel);
      resolve(answer);
    };
    const onGo = () => done(true);
    const onCancel = () => done(false);
    go.addEventListener('click', onGo);
    cancel.addEventListener('click', onCancel);
    dlg.showModal();
  });
}

/**
 * The cost of a sweep run, stated before it is spent.
 */
async function confirmSweepCost(sections, rereading, elements, calls) {
  const dlg = document.getElementById('sweepCostDialog');
  const each = sweepAvgCall();
  if (!dlg) return true;
  // A section bigger than one batch is asked about in more than one call. The
  // dialog that spends the money says how many, or the first busy page comes in
  // at twice what was agreed to.
  if (calls == null) calls = sections;

  document.getElementById('sweepCostBody').innerHTML =
    escapeHtml(`Searching ${sections} section${sections === 1 ? '' : 's'} for components — that is ${calls} call${calls === 1 ? '' : 's'} to Claude` +
      (calls > sections ? ` (the busy sections take more than one)` : '') + `, ` +
      `about $${each.toFixed(2)} each, ~$${(calls * each).toFixed(2)} in total, ` +
      // The dialog quotes the same number the box above it does, from the same
      // function. Two numbers for one press, differing because one was written
      // later than the other, is how an estimate stops being read at all.
      `and roughly ${mins(sweepSecsFor(elements))}.`) +
    // A ▶ next to a completed screen is one press away from paying twice for
    // the same section. The button is still there — deliberately re-reading
    // one is a real thing to want — but it is not something to do without
    // being told which of the two this is.
    (rereading
      ? `<br><br><strong>Screen ${rereading} has already been searched and paid for.</strong> ` +
        `Reading it again is a second call, and replaces what it found.`
      : '');

  return new Promise((resolve) => {
    const go = document.getElementById('sweepCostGo');
    const cancel = document.getElementById('sweepCostCancel');
    const done = (answer) => {
      dlg.close();
      go.removeEventListener('click', onGo);
      cancel.removeEventListener('click', onCancel);
      resolve(answer);
    };
    const onGo = () => done(true);
    const onCancel = () => done(false);
    go.addEventListener('click', onGo);
    cancel.addEventListener('click', onCancel);
    dlg.showModal();
  });
}

// A one-click way to act on that, since the fix is always the same.
function offerReload(status) {
  if (!status) return;
  if (status.querySelector('[data-reload-tab]')) return;
  status.insertAdjacentHTML('beforeend',
    ' <button class="btn-outline btn-xs" data-reload-tab>↻ Reload the page</button>');
}

document.addEventListener('click', async (e) => {
  if (!e.target.closest('[data-reload-tab]')) return;
  const tab = await getTab();
  if (tab) chrome.tabs.reload(tab.id);
});

// "Replace the site's role and apply."
//
// The decision was previously only reachable at save time, so a mapping already
// on the list had no way to make it: Apply ran, U1 met the author's role, and
// nothing happened — with no way forward except deleting the mapping and
// building it again. The answer is recorded on the mapping so every later apply
// and the exported file make the same choice.
//
// Removing the role is enough on its own. U1 will not look at an element twice
// in a page load, so re-running the fix here would be theatre — but the patch's
// own corrector fills in role="listbox" and role="option" the moment the
// author's role is gone, which is what actually makes the component work.
async function applyRoleOverwrite(sel, was, status) {
  const key = storageKey('mappings', currentHostname);
  const stored = await U1Store.get([key]);
  const list = stored[key] || [];
  const idx = list.findIndex(m => m && typeof m === 'object' && m.primary === sel);
  if (idx < 0) {
    // Not saved yet — the clash was reported by the picker's own Apply. Record
    // the answer on the template so it travels into the mapping when saved.
    if (currentTemplate && currentTemplate.primary === sel) {
      currentTemplate.overwriteRole = was;
      currentTemplate.code = mappingToCode(currentTemplate);
      const res = await applyMappingsBatch([{
        type: currentTemplate.type, primary: currentTemplate.primary,
        firstArg: currentTemplate.firstArg, config: currentTemplate.config,
        overwriteRole: was,
      }]);
      const v = describeApply(res, currentTemplate);
      showNotice(status, `Removed role="${was}" from ${sel}. ` + v.msg +
        ' Save the mapping to keep this answer — the exported file will do the same.',
        v.ok ? 'success' : 'error', 14000);
      return;
    }
    showNotice(status, 'That mapping is no longer on the list.', 'error', 6000);
    return;
  }
  list[idx] = { ...list[idx], overwriteRole: was, code: mappingToCode({ ...list[idx], overwriteRole: was }) };
  await U1Store.set({ [key]: list });

  const r = await applyOne(list[idx].type, list[idx].firstArg || list[idx].primary,
                           list[idx].config, list[idx].custom, list[idx]);
  await loadMappingsList();
  showNotice(status,
    r.ok ? `Removed role="${was}" from ${sel} and re-applied. The exported file now does the same, so the client gets this too.`
         : `Removed role="${was}" from ${sel}, but the fix reported: ${r.err || 'no result'}`,
    r.ok ? 'success' : 'error', 12000);
}

// Which saved mappings target the same DOM as `primary`?
//
// mappingKey is type::primary, so a listbox on `button.main-nav__trigger` and a
// menu on `#mainNav` are different keys and both survive — then Apply All hands
// U1 two components claiming the same elements, and the second undoes the
// first. That is invisible in a flat list of mappings, so ask the page.
async function overlappingMappings(primary, list) {
  const tab = await getTab();
  if (!isInjectable(tab)) return [];
  const others = (list || [])
    .map((m, i) => ({ i, key: mappingKey(m), type: m.type, sel: m.firstArg || m.primary }))
    .filter(o => o.sel && o.sel !== primary);
  if (!others.length) return [];
  try {
    const res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: (mine, list2) => {
        const q = (s) => { try { return Array.from(document.querySelectorAll(s)); } catch { return []; } };
        const a = q(mine);
        if (!a.length) return [];
        return list2.filter(o => q(o.sel).some(el =>
          a.some(x => x === el || x.contains(el) || el.contains(x))));
      },
      args: [primary, others],
    });
    return (res && res[0] && res[0].result) || [];
  } catch { return []; }
}

// Persist one built template as a mapping for the current host, replacing an
// existing entry with the same key (or the one being edited). Shared by the
// manual "Add to Mapping" button and the AI mapping cards, so a mapping made
// either way is byte-for-byte the same record.
// `refreshUi:false` suppresses the list + export re-render. Saving one mapping
// should repaint; saving twelve in a row should repaint once at the end, not
// twelve times — each loadMappingsList() runs an executeScript against the page.
async function saveMappingEntry(template, { editingKey = null, refreshUi = true } = {}) {
  // Whose dialog is this INSIDE? Stamped here — the one save path — by real
  // DOM containment, so a mapping born from any route (manual add with a
  // scoped container, the AI card, the interior scan) nests under its dialog
  // in the drawer without each route knowing about nesting.
  if (!template.parent && template.primary && template.type !== 'dialog') {
    try {
      const mkey = storageKey('mappings', currentHostname);
      const dlgs = ((await U1Store.get([mkey]))[mkey] || [])
        .filter((m) => m && m.type === 'dialog' && m.primary).map((m) => m.primary);
      if (dlgs.length) {
        const tb = await getTab();
        if (isInjectable(tb)) {
          const parent = await inPage(tb.id, (sel, ds) => {
            let el = null;
            try { el = document.querySelector(sel); } catch { return ''; }
            if (!el) return '';
            for (const d of ds) {
              try {
                const host = document.querySelector(d);
                if (host && host !== el && host.contains(el)) return d;
              } catch (e) {}
            }
            return '';
          }, [template.primary, dlgs]);
          if (parent) template.parent = parent;
        }
      }
    } catch {}
  }
  // The site may already have said what this element is, and overruling an
  // author's role is a decision for a person.
  //
  // This lives HERE, not in the button handlers, because there are three ways
  // to create a mapping — the manual Add, the AI card's "Approve & apply", and
  // the bulk save — and only the first one asked. An AI-approved mapping went
  // straight past the question and was only discovered later, after an apply
  // that reported success-shaped text. One save path, one place to ask.
  if (!(await confirmRoleOverwrite(template))) return { cancelled: true };

  // ── A required selector may not be missing ────────────────────────────────
  //
  // validateMapping existed and was called from exactly one place: the manual
  // builder's form. Every other route — the AI card, the bulk save, the sweep's
  // own confirm — went straight past it, so a mapping could be stored and
  // exported with a required field empty and nothing ever said so.
  //
  // That is how this shipped to a client:
  //
  //   fix.tabs("#dealTab-week", { selectors: { tab: ".tab-bar__btn",
  //                                            tabList: "#dealTab-week" } })
  //
  // tabPanel is required and absent, and tabList is a single BUTTON. u1 has
  // nothing to work with, decorates nothing, and reports nothing — the strip
  // stays exactly as it was while the drawer says it is mapped.
  //
  // Here, for the same reason the role question is here: one save path, one
  // place to refuse.
  // ── A selector the ENGINE cannot use ──────────────────────────────────────
  //
  // U1 resolves selectors through jQuery, and a pseudo-class is refused there
  // SILENTLY — the fix simply never applies, and nothing anywhere says so. So
  // a mapping built on one looks finished in the drawer, ships in the export,
  // and decorates nothing on the client's site, forever.
  //
  // isU1ValidSelector has existed all along and this path never called it: the
  // AI route checked (checkAiSelector), the manual builder did not. Reported
  // from tamam.co.il, where
  //   .elementor-widget-text-editor>.elementor-widget-container>p:last-of-type
  // saved cleanly and did nothing. Checked here because this is the one save
  // path, which is where the required-field refusal already lives.
  if (template && template.type) {
    const sels = (template.config && template.config.selectors) || {};

    // Rename before refusing.
    //
    // The refusal below is correct and stays. What was wrong was that it was
    // the FIRST thing tried on a selector that resolves perfectly well in the
    // browser and points at exactly the right element — two dialogs on a live
    // site were refused over `#state-select-modal h2`, with the advice "give
    // the element a class", addressed to a person, about a heading the tool was
    // looking straight at.
    //
    // repairForU1 resolves it and names the same element again with the
    // builder every other selector here comes from, which cannot emit an
    // invalid name. It refuses to answer unless the new name points at exactly
    // the same elements, so nothing is silently widened. Whatever it cannot
    // repair falls through to the refusal unchanged.
    const invalid = [];
    if (template.primary && !isU1ValidSelector(template.primary)) invalid.push(['', template.primary]);
    for (const [k, v] of Object.entries(sels)) {
      if (typeof v === 'string' && v.trim() && !isU1ValidSelector(v)) invalid.push([k, v]);
    }
    const repairs = [];
    if (invalid.length) {
      const tab = await getTab();
      if (isInjectable(tab)) {
        let fixed = null;
        try {
          fixed = await inPage(tab.id, (list) => list.map(([k, v]) => {
            try { return [k, v, window.__u1SelectorIntel.repairForU1(v) || '']; }
            catch (e) { return [k, v, '']; }
          }), [invalid]);
        } catch (e) { fixed = null; }
        for (const [k, was, now] of fixed || []) {
          if (!now || !isU1ValidSelector(now)) continue;
          if (k) setDeep(template.config.selectors, k, now);
          else template.primary = now;
          repairs.push({ field: k || template.type, was, now });
        }
      }
      if (repairs.length) template.code = mappingToCode(template);
    }

    const bad = [];
    if (template.primary && !isU1ValidSelector(template.primary)) {
      bad.push(template.primary);
    }
    for (const [k, v] of Object.entries(sels)) {
      if (typeof v === 'string' && v.trim() && !isU1ValidSelector(v) && !bad.includes(v)) {
        bad.push(`${k}: ${v}`);
      }
    }
    if (bad.length) {
      throw new Error(
        `U1 cannot use ${bad.length === 1 ? 'this selector' : 'these selectors'} — it resolves them ` +
        `through jQuery, which refuses a pseudo-class (:last-of-type, :nth-child, :hover) and a ` +
        `descendant space, and it refuses them SILENTLY. Saved like this the fix would never run and ` +
        `nothing would say why. ${bad.join(' · ')}. Use > + ~ , between compound selectors, and give ` +
        `the element a class if it has nothing else to point at.`);
    }
  }

  // aria-label is a custom script, so the u1.fix guard below skips it — and
  // its required half lives on the config root, not in selectors. Refused
  // here for the same reason as the rest: saved without a heading it writes
  // "Read more about" and calls that a name.
  if (template && template.custom === 'focusOrder') {
    const n = String((template.config && template.config.order) || '').split(';').map((x) => x.trim()).filter(Boolean).length;
    if (n < 2) {
      throw new Error('A focus-order mapping needs at least two selectors in "Tab order", separated by semicolons — one element has no order to be in.');
    }
  }
  if (template && template.custom === 'ariaLabel') {
    const h = template.config && template.config.headingSelector;
    if (!h || !String(h).trim()) {
      throw new Error(
        'An aria-label mapping needs the heading whose text finishes the name — that is the whole ' +
        'point of it. Without one the button keeps saying "Read more". Point "Heading whose text is ' +
        'added at the end" at the card\'s heading.');
    }
  }

  if (template && template.type && !template.custom) {
    const sc = COMPONENT_SCHEMAS[template.type];
    if (sc) {
      const pKey = primaryKeyOf(sc);
      const missing = (sc.req || []).filter((r) => {
        const v = (r === pKey) ? template.primary
          : ((template.config && template.config.selectors) || {})[r];
        return !v || !String(v).trim();
      });
      if (missing.length) {
        throw new Error(
          `A ${template.type} needs ${missing.join(' and ')} and ${missing.length === 1 ? 'it is' : 'they are'} ` +
          `empty. Saved like this it would decorate nothing and say nothing — fill ` +
          `${missing.length === 1 ? 'it' : 'them'} in, or map this as something else.`);
      }
    }
  }

  // ── A listbox trigger nobody can reach ────────────────────────────────────
  //
  // The trigger is what U1 waits for, decorates as the button, and hangs the
  // open/close keys on. Every count check passes on a hidden one: it IS in the
  // DOM. It is just unreachable — the original <select> that a dropdown
  // plugin (msDropDown on molinahealthcare.com) parks in a zero-height
  // overflow:hidden holder next to the widget it painted instead. Mapped that
  // way the list is marked handled and nothing on the page opens it.
  //
  // Repaired first, refused second: the list's own wrapper is asked what its
  // trigger is (listboxShape, walking up a few levels), and only a shape that
  // names THIS list with a reachable trigger is accepted. What cannot be
  // repaired is refused here, in the one save path, like the other refusals.
  if (template.type === 'listbox' && template.firstArg && template.firstArg !== template.primary) {
    const usable = await triggersUsableOnPage([template.firstArg]);
    if (usable && usable[template.firstArg] === false) {
      const tb = await getTab();
      let fixedTrigger = '';
      if (isInjectable(tb)) {
        try {
          fixedTrigger = await inPage(tb.id, (listSel) => {
            const S = window.__u1SelectorIntel;
            let el = null;
            try { el = document.querySelector(listSel); } catch (e) { return ''; }
            if (!el) return '';
            const same = (sel) => { try { return document.querySelector(sel) === el; } catch (e) { return false; } };
            let node = el.parentElement;
            for (let hops = 0; node && node !== document.body && hops < 4; hops++, node = node.parentElement) {
              let sh = null;
              try { sh = S.listboxShape(S.robustSelector(node)); } catch (e) { sh = null; }
              if (!sh || !sh.trigger || !same(sh.listbox)) continue;
              const t = document.querySelector(sh.trigger);
              const r = t && t.getBoundingClientRect();
              if (r && r.width > 0 && r.height > 0 && !el.contains(t)) return sh.trigger;
            }
            return '';
          }, [template.primary]);
        } catch { fixedTrigger = ''; }
      }
      if (fixedTrigger && isU1ValidSelector(fixedTrigger)) {
        const was = template.firstArg;
        template.firstArg = fixedTrigger;
        template.config = template.config || {};
        template.config.selectors = template.config.selectors || {};
        template.config.selectors.trigger = fixedTrigger;
        template.code = mappingToCode(template);
        template.note = (template.note ? template.note + ' ' : '') +
          `Trigger ${was} is not reachable on the page (hidden or clipped away); replaced with ${fixedTrigger}.`;
      } else {
        throw new Error(
          `The trigger ${template.firstArg} is in the DOM but nobody can reach it — it is hidden, or ` +
          `sits in a zero-size clipped holder (a dropdown plugin's original <select>, typically). ` +
          `U1 would mark ${template.primary} handled and nothing on the page would open it. ` +
          `Point "trigger" at the element a person actually presses.`);
      }
    }
  }

  // A selector wider than the container it belongs to is repaired here, before
  // anything is stored — so the mapping, its code, and the exported client file
  // all carry the narrowed form. Every route saves through this function, which
  // is why it is the place.
  const narrowed = await narrowContained(template);

  const key = storageKey('mappings', currentHostname);
  const stored = await U1Store.get([key]);
  const list = stored[key] || [];
  const newKey = mappingKey(template);
  let existingIdx = editingKey ? list.findIndex(m => mappingKey(m) === editingKey) : -1;
  if (existingIdx < 0) existingIdx = list.findIndex(m => mappingKey(m) === newKey);

  // Same container, different trigger: that is the same mapping, not a second
  // one (see containerKey). The one with the reachable trigger stays; when the
  // stored one is that mapping, nothing is overwritten and the caller is told
  // which trigger won.
  let merged = null;
  if (existingIdx < 0) {
    const ck = containerKey(template);
    const twinIdx = ck ? list.findIndex(m => containerKey(m) === ck) : -1;
    if (twinIdx >= 0) {
      const twin = list[twinIdx];
      const usable = await triggersUsableOnPage(
        Array.from(new Set([twin.firstArg || twin.primary, template.firstArg || template.primary])));
      const winner = pickContainerSurvivor(
        [twin, { ...template, capturedAt: Date.now() }], usable);
      merged = {
        kept: winner === twin ? (twin.firstArg || twin.primary) : (template.firstArg || template.primary),
        dropped: winner === twin ? (template.firstArg || template.primary) : (twin.firstArg || twin.primary),
        usable: usable || {},
      };
      if (winner === twin) {
        if (refreshUi) { loadMappingsList(); refreshExportInfo(); }
        return { updated: true, narrowed, merged };
      }
      existingIdx = twinIdx;
    }
  }

  const tab = await getTab();
  const screenshot = await captureElementScreenshot(template.primary, template.firstArg, { reveal: true });
  const prev = existingIdx >= 0 ? list[existingIdx] : null;
  const entry = {
    type: template.type,
    primary: template.primary,
    firstArg: template.firstArg,
    custom: template.custom || null,
    config: template.config,
    code: template.code,
    // The answer to "the site already wrote a role here". Kept on the record,
    // not on the moment: apply, re-apply and export all have to make the same
    // choice, and a decision that lives only in a dialog cannot be repeated.
    overwriteRole: template.overwriteRole || (prev && prev.overwriteRole) || null,
    // What this mapping is about, in words — a heading's text and why its
    // level changed, an auto-answered role clash. Shown on the drawer row.
    note: template.note || (prev && prev.note) || null,
    // The dialog this was found INSIDE (the interior scan stamps it), so the
    // drawer nests the row under that dialog's own.
    parent: template.parent || (prev && prev.parent) || null,
    // Keep the previous screenshot if a fresh capture wasn't possible.
    screenshot: screenshot || (prev && prev.screenshot) || null,
    // Only a page of THIS site can be where a mapping of this site was made.
    pageUrl: (tab && sameSiteUrl(tab.url)) ? tab.url : ((prev && sameSiteUrl(prev.pageUrl)) ? prev.pageUrl : ''),
    pageTitle: (tab && sameSiteUrl(tab.url)) ? (tab.title || '') : ((prev && sameSiteUrl(prev.pageUrl)) ? (prev.pageTitle || '') : ''),
    capturedAt: Date.now(),
    // Stable chronological "Fix #N" shown in the UI, the exported script and the
    // close-out report. Assigned once and kept across edits so the number a
    // client sees in the report always points at the same fix.
    fixNo: (prev && prev.fixNo) || nextFixNo(list),
    // Durable id kept across edits (see genMappingId) — the key the monitor
    // reports as `id=…` when this mapping's selector breaks on a live site.
    id: (prev && prev.id) || genMappingId(),
  };
  if (existingIdx >= 0) list[existingIdx] = entry;
  else list.push(entry);
  await U1Store.set({ [key]: list });
  // What was reviewed was the OLD row. A rewrite — by hand, by the AI, by a
  // trigger merge — is a new thing to look at.
  if (existingIdx >= 0) { try { await setReviewed([reviewIdOf(entry)], false); } catch {} }

  if (refreshUi) {
    loadMappingsList();
    refreshExportInfo();
  }
  return { updated: existingIdx >= 0, narrowed, merged };
}

document.getElementById('addMappingBtn').addEventListener('click', async () => {
  const status = document.getElementById('applyStatus');
  // Always rebuild from the current form so an edited-but-not-regenerated form
  // still saves (previously this silently returned when currentTemplate was stale).
  const fresh = buildTemplateFromForm();
  if (fresh) currentTemplate = fresh;
  if (!currentTemplate) {
    showNotice(status, 'Enter a CSS selector and pick a component type first.', 'error', 3500);
    return;
  }
  const btn = document.getElementById('addMappingBtn');
  btn.textContent = 'Capturing…';
  let updated, cancelled, narrowed, merged;
  try {
    ({ updated, cancelled, narrowed, merged } = await saveMappingEntry(currentTemplate, { editingKey: editingMappingKey }));
    if (cancelled) { btn.textContent = 'Add to Mapping'; return; }
  } catch (e) {
    // A failed write used to travel up as an unhandled rejection: the button
    // sat on "Capturing…" and the mapping was simply never saved.
    btn.textContent = 'Add to Mapping';
    showNotice(status, e.message, 'error', 12000);
    return;
  }
  const wasEditing = editingMappingKey != null || updated;
  editingMappingKey = null;
  const saved = currentTemplate;

  // Saving IS the intent — the page should reflect it without a second
  // click. Before this, Update wrote the entry and did nothing else: the page
  // kept running the old config, and the form stayed open showing the same
  // values, so "I ticked the box and pressed Update" looked like nothing
  // happened. The fix is applied live here (best-effort, exactly as Apply
  // would), and the builder closes, because the mapping list below is now
  // the record of what was done.
  let applyMsg = '';
  try {
    if (saved.custom) {
      const r = await applyOne(saved.type, saved.firstArg || saved.primary, saved.config, saved.custom, saved);
      applyMsg = r.ok ? ' and applied on page' : (r.u1Missing ? '' : ` — apply failed: ${r.err}`);
    } else {
      const res = await applyMappingsBatch([{
        type: saved.type, primary: saved.primary, firstArg: saved.firstArg,
        config: saved.config, overwriteRole: saved.overwriteRole,
      }]);
      const v = describeApply(res, saved);
      applyMsg = res.u1Missing ? ' (U1 is not loaded here — it will apply when the page runs U1)'
               : v.ok ? ' and applied on page' : ` — apply: ${v.msg}`;
    }
  } catch (e) {
    applyMsg = ` — apply failed: ${e.message}`;
  }

  resetPicker();
  // The record of what was just done is the mapping list — so that is what
  // comes on screen, with the notice above it.
  if (typeof setPickerPane === 'function') setPickerPane('mappings');
  const listStatus = document.getElementById('mappingsStatus') || status;
  showNotice(listStatus,
    `${wasEditing ? 'Updated' : 'Added'} ${saved.type} ${saved.primary}${applyMsg}.` +
    ' Reload the page if a fix U1 already ran does not pick up the change.',
    /failed|apply:/.test(applyMsg) ? 'error' : 'success', 7000);
  // Say it. A selector rewritten behind your back is worse than one left wrong,
  // however good the rewrite.
  if (narrowed && narrowed.length) showNarrowed(listStatus, narrowed);
  if (merged) {
    showNotice(listStatus,
      `${saved.type} ${saved.primary} was already mapped with trigger ${merged.dropped === (saved.firstArg || saved.primary) ? merged.kept : merged.dropped}. ` +
      `One container is one mapping (U1 handles it once per page load), so the trigger that is reachable on the page was kept: ${merged.kept}.`,
      'warn', 14000);
  }
});

/** What was narrowed, and why it had to be. */
function showNarrowed(status, narrowed) {
  showNotice(status, narrowed.map((n) =>
    `"${n.field}" matched ${n.total} elements, ${n.outside} of them outside the container — ` +
    `narrowed to ${n.now} so the fix can land.`).join(' '), 'warn', 14000);
}

// Apply every saved mapping for the current host. `silent` suppresses the
// "no mappings" / success notices (used by the auto-run on panel open).
// `only` is a mappingKey: apply that one, through exactly this path.
//
// The drawer's ▶ used to call applyFix directly, and applyFix reports ok for
// any call that does not throw — it measures nothing. So one mapping said
// "Applied on page." while the identical mapping under Apply All was measured,
// diagnosed and told you what was in the way. Two answers to the same question,
// and the reassuring one was the one attached to the single-mapping button.
async function applyAllMappings({ silent = false, only = null, tab = null } = {}) {
  const key = storageKey('mappings', currentHostname);
  const stored = await U1Store.get([key]);
  const all = stored[key] || [];
  const list = only ? all.filter(m => mappingKey(m) === only) : all;
  const status = document.getElementById('applyAllStatus');
  if (list.length === 0) {
    if (!silent) showNotice(status, 'No mappings to apply.', 'error');
    return { applied: 0, failed: 0 };
  }
  // Custom mappings (aria-label) run as scripts; u1.fix ones go through the batch.
  const custom = list.filter(m => m && typeof m === 'object' && m.custom);
  const fixes = list.filter(m => !(m && typeof m === 'object' && m.custom));

  let applied = 0, failed = 0, noEffect = 0, u1Missing = false, err = null, u1State = null;
  let details = [], engineErrs = [], filledIn = [], hidContent = [];
  if (fixes.length) {
    const result = await applyMappingsBatch(fixes, tab || undefined);
    if (result.ok) {
      applied += result.applied;
      failed += result.failed;
      noEffect += result.noEffect || 0;
      details = result.details || [];
      engineErrs = result.errs || [];
      hidContent = result.hidContent || [];
      filledIn = result.filledIn || [];
      for (const d of details) {
        if (d.receipt && d.receipt.length) applyReceipts.set(d.type + '::' + d.sel, d.receipt);
      }
    } else if (result.u1Missing) { u1Missing = true; }
    else { err = result.err; }
  }
  for (const m of custom) {
    const r = await applyOne(m.type, m.firstArg || m.primary, m.config, m.custom, m);
    if (r.ok) applied++; else failed++;
  }

  if (!silent) {
    if (u1Missing && applied === 0) {
      showNotice(status, 'U1 library is not loaded — inject U1 in Setup first.', 'error', 4500);
    } else if (err && applied === 0) {
      showNotice(status, 'Error: ' + err, 'error', 4500);
    } else if (noEffect && !applied) {
      // The case that used to read "Applied N" while the page was untouched.
      const optOut = details.filter(d => d.reason === 'source-opt-out');
      const stale = details.some(d => d.reason === 'already-processed');
      let msg;
      if (optOut.length) {
        msg = `Nothing changed: ${optOut.map(d => d.sel).join(', ')} already carried u1st-avoid-change-detection before the fix ran, which tells U1 to skip that element entirely. Reload the page and press Apply All once — if it says this again on a clean load, the attribute is in the site's own HTML and has to come out there.`;
      } else if (stale) {
        msg = `Nothing changed: U1 had already processed ${noEffect === 1 ? 'this element' : 'these elements'} on this page load. Reload the page, then apply again.`;
      } else if (details.some((d) => d && d.status === 'no-effect' && d.stub)) {
        // The engine was never on this page: the call that "ran without
        // error" was the compat patch's stand-in, which records and does not
        // fix. Same words, opposite diagnosis from the once-per-load Set.
        msg = 'Nothing changed — the U1 engine itself is not on this page: ' +
          details.filter((d) => d.stub).map((d) => 'fix.' + d.type).join(', ') +
          ' answered from the compat patch, which records but does not decorate. ' +
          'Inject U1 in Setup (or turn on auto-inject for this site), reload, and apply again.';
      } else if (list.some((m) => m && typeof m === 'object' &&
                   applyReceipts.has((m.type || '') + '::' + (m.primary || m.firstArg || '')))) {
        // The engine keeps a page-load-wide Set of elements it has fixed
        // (activate()'s fixedComponents) — a second fix.* call on the same
        // element this load is a silent no-op BY DESIGN, whatever changed in
        // the mapping. Verified in the engine source, 2026-09-02; it is the
        // whole story behind 'fix.menu emits zero roles' during
        // map-apply-delete iteration.
        msg = 'Nothing changed — U1 fixes each element ONCE per page load, and this load already fixed ' +
          (noEffect === 1 ? 'this element' : 'these elements') +
          ' (an earlier apply, before the mapping was edited). Reload the page — your mappings re-apply automatically on load.';
      } else {
        msg = 'Nothing changed on the page. u1.fix ran without error but wrote no attributes — usually the domain is not authorised for U1, or the selector is one U1\'s validator rejects.';
      }
      if (engineErrs.length) msg += ' ' + engineErrs.join(' · ');
      showNotice(status, msg, 'error', 12000);
      offerReload(status);
    } else {
      // ── One line per mapping, not one paragraph for all of them ───────────
      //
      // This used to concatenate every finding into a single string: a headline
      // count, then U1's own errors, then the opt-out note, then the
      // half-applied detail, then the role clashes — six sentences about four
      // different mappings, run together with middots. Reported, fairly, as a
      // wall of information. Every one of those sentences is worth keeping;
      // what was wrong is that nothing said WHICH mapping each belonged to.
      //
      // So the same facts are grouped by the mapping they are about, and the
      // headline says only how many landed. Nothing is dropped — the detail is
      // the whole value here, and a person reading this is trying to find out
      // why one specific fix did not work.
      const clashes = details.filter(d => d.roleClash);
      const unblocked = details.filter(d => d.unblocked);

      // What to say about ONE mapping, gathered from wherever it was recorded.
      //
      // Ask describeApply for EVERY line, not only the half-applied ones.
      //
      // It was called only when `fieldsNoEffect` was set, so a mapping that
      // changed nothing at all — the one case where the person has no other
      // way to find out why — printed as a bare "✗ dialog #MedicareAlert"
      // with not one word of explanation, while describeApply had the reason
      // ready ("U1 had already processed this element this page load. Reload
      // the page and press Apply All."). It is the same question for every
      // status; there was never a reason to answer it for one of them.
      const notesFor = (d) => {
        const out = [];
        const m = fixes.find(f => (f.firstArg || f.primary) === d.sel);
        const said = describeApply({ ok: true, applied: 1, details: [d], errs: engineErrs, u1State }, m).msg
          .replace(/^Applied — \d+ elements? changed on the page\.\s*/, '');
        if (said) out.push(said);
        if (d.roleClash && !said.includes('role="' + d.roleClash.role + '"')) {
          out.push(`The site's own HTML gives it role="${d.roleClash.role}". U1 will not write ` +
                   `role="${d.roleClash.willWrite}" over an author's role, so this cannot land ` +
                   `while that attribute is there.`);
        }
        // No separate opt-out sentence. describeApply already ends the `ok`
        // message with it, and pushing a second copy here is what printed the
        // same warning twice in a row on every affected line.
        return out;
      };

      const lines = [];
      for (const d of details) {
        const notes = notesFor(d);
        const broke = d.status && d.status !== 'ok';
        if (!broke && !notes.length) continue;          // it simply worked
        const mark = broke ? '✗' : '!';
        const head = `${mark} ${d.type || 'fix'} ${d.sel}`;
        lines.push(notes.length ? `${head} — ${notes.join(' ')}` : head);
      }
      // U1's own words are the most useful sentence available and must never be
      // dropped. They arrive without a mapping attached, so they get their own
      // lines rather than being appended to somebody else's.
      //
      // Except the ones that DO have a mapping attached. A selector matching
      // nothing is recorded twice — once as a detail, once here — and printed
      // as "✗ dialog .caption-learn-more" immediately followed by "✗ dialog:
      // nothing on the page matches .caption-learn-more". Six unmatched
      // selectors became twelve lines saying six things. The detail line now
      // carries the sentence, so the echo goes.
      const echoed = new Set(details.filter(d => d.status === 'no-match')
                                    .map(d => `${d.type}: nothing on the page matches ${d.sel}`));
      for (const e of engineErrs) if (!echoed.has(e)) lines.push(`✗ ${e}`);

      // A fixer this build of U1 does not have, which the patch supplied. The
      // mapping works — and it works BECAUSE of the patch, which the client's
      // bundle also carries. Worth saying once, not worth an error.
      if (filledIn.length) {
        lines.push(`i This build of U1 has no ${filledIn.map(f => 'u1.fix.' + f).join(', ')} — ` +
                   `u1-patch.js supplied ${filledIn.length === 1 ? 'it' : 'them'}, so the fix works ` +
                   `here and in the export (the patch ships with it). Nothing to do.`);
      }

      const parts = [`Applied ${applied} mapping${applied !== 1 ? 's' : ''}`];
      if (noEffect) parts.push(`${noEffect} changed nothing`);
      if (failed) parts.push(`${failed} failed`);
      // A fix that hid something is never a success, however many others
      // landed — changing the site's appearance is the one thing this product
      // may not do, so it leads the headline and forces the error styling.
      if (hidContent.length) {
        parts.unshift(`${hidContent.length} CHANGED THE PAGE'S APPEARANCE`);
      }

      renderApplyReport(status, parts.join(' · '), lines,
        (hidContent.length || failed || noEffect || clashes.length || unblocked.length) ? 'error' : 'success');

      if (clashes.length && !silent) {
        const c = clashes[0].roleClash;
        if (await askRoleClash(c)) await applyRoleOverwrite(c.sel, c.role, status);
      }
    }
    // Per-mapping detail. console.debug, not warn: these are expected outcomes
    // of a normal run, and at warn level an error collector files each one as a
    // fault report.
    for (const d of details) {
      if (d.status === 'ok' && !d.unblocked) continue;
      console.debug('[U1 Studio] apply:', d.type, d.sel, '→', d.status, d.reason || (d.unblocked ? 'opt-out lifted' : ''));
    }
  }
  return { applied, failed, noEffect, u1Missing, details };
}

// Apply All polls for up to 4s PER mapping, so a site with several can sit
// there for a long time. It had no busy state at all — the button looked idle
// while the panel was working, which reads as nothing having happened.
document.getElementById('applyAllBtn').addEventListener('click', async (e) => {
  const btn = e.currentTarget;
  const label = btn.textContent;
  btn.disabled = true;
  btn.classList.add('is-working');
  btn.textContent = 'Applying…';
  try { await applyAllMappings(); }
  finally {
    btn.disabled = false;
    btn.classList.remove('is-working');
    btn.textContent = label;
  }
});

// ── Same client, different URL ──────────────────────────────────────────────
//
// Everything is filed under the bare hostname, so molina.com and
// member.molina.com are two different sites as far as storage is concerned.
// That is why mappings "disappear": they are filed under a hostname you are
// not currently looking at. Rather than merging hostnames automatically —
// which would fuse unrelated tenants on shared domains like *.railway.app —
// find the likely siblings and offer to move the work.
// A page URL belongs to THIS site: same host, or a related one. A mapping
// saved while another tab was in front recorded a Gemini page as the place it
// was captured — and "Test all pages" then set off to test it there.
function sameSiteUrl(u) {
  try { const h = new URL(u).hostname; return !!h && (h === currentHostname || !!hostRelation(h, currentHostname)); }
  catch { return false; }
}
function hostRelation(a, b) {
  if (!a || !b || a === b) return null;
  // One is a subdomain of the other: member.molina.com ↔ molina.com.
  if (a.endsWith('.' + b) || b.endsWith('.' + a)) return 'subdomain';
  // Or they share a DISTINCTIVE label: molina.com ↔ molina.co.il.
  //
  // Shared hosting domains are not distinctive — two tenants on
  // *.up.railway.app both contain "railway" and are completely unrelated
  // clients, so those labels cannot count as evidence.
  const GENERIC = new Set([
    'com', 'net', 'org', 'co', 'www', 'app', 'dev', 'site', 'online', 'store', 'cloud',
    'railway', 'vercel', 'netlify', 'herokuapp', 'github', 'gitlab', 'pages', 'azurewebsites',
    'amazonaws', 'cloudfront', 'firebaseapp', 'myshopify', 'wixsite', 'squarespace',
    'wordpress', 'webflow', 'onrender', 'surge', 'glitch', 'ngrok', 'localhost', 'local',
    'staging', 'production', 'preview', 'test', 'demo',
  ]);
  const labels = (h) => h.split('.').filter(l => l.length >= 4 && !GENERIC.has(l));
  const shared = labels(a).filter(l => labels(b).includes(l));
  return shared.length ? 'sibling' : null;
}

// Move (or copy) every per-site key from one hostname to another. Used to
// recover work filed under an old URL.
async function moveSiteData(from, to, { copy = false } = {}) {
  const prefixes = U1Store.SITE_PREFIXES || ['mappings', 'config', 'skipLinks', 'autoApply', 'platform', 'manualInject'];
  const fromKeys = prefixes.map(p => storageKey(p, from));
  const src = await U1Store.get(fromKeys);
  const writes = {};
  let moved = 0;
  for (const p of prefixes) {
    const v = src[storageKey(p, from)];
    if (v === undefined) continue;
    // Never clobber work that already exists at the destination: mappings are
    // concatenated (deduped by key), everything else only fills a gap.
    if (p === 'mappings') {
      const destKey = storageKey('mappings', to);
      const dest = (await U1Store.get([destKey]))[destKey] || [];
      const seen = new Set(dest.map(m => mappingKey(m)));
      const add = (v || []).filter(m => !seen.has(mappingKey(m)));
      if (!add.length && !dest.length) continue;
      writes[destKey] = dest.concat(add);
      moved += add.length;
    } else {
      const destKey = storageKey(p, to);
      const dest = (await U1Store.get([destKey]))[destKey];
      if (dest === undefined) writes[destKey] = v;
    }
  }
  if (Object.keys(writes).length) await U1Store.set(writes);
  if (!copy) await U1Store.remove(fromKeys);
  return { moved };
}

// Put the run's "approved" record back to empty. Used when the site has no
// saved mappings left, so the panel cannot claim to have applied any.
function resetApprovedRun() {
  const box = document.getElementById('aiApproved');
  if (box) {
    const list = box.querySelector('#aiApprovedList');
    if (list) list.innerHTML = '';
    const n = box.querySelector('#aiApprovedN');
    if (n) n.textContent = '';
    box.style.display = 'none';
  }
  approvedSeq = 0;
  for (const key of [...agentThreads.keys()]) {
    if (key.startsWith('saved:')) agentThreads.delete(key);
  }
}

// What did applying actually do? One answer, wherever it is asked from.
//
// This lived inside the AI approve handler, so Manual mode never got any of
// it: no per-field report, no explanation of what menubar:false does. Applying
// is applying — the mode you built the mapping in should not change what you
// are told about it.
/**
 * Turns one item's apply result into a sentence.
 *
 * `i` is which item of the batch to describe. This used to be hardcoded to 0,
 * which was invisible while every call passed a one-item array — and would have
 * reported a twelve-mapping batch as twelve copies of the first item's verdict.
 * The per-item `status` is the authority here, not the batch-wide `res.applied`:
 * the in-page loop increments that counter exactly when it pushes status 'ok',
 * so for a single item the two agree, and for a batch only the former is right.
 */
// A role the site wrote blocks the fix outright, and that is true whatever else
// the run reported — so it is appended here, once, rather than in each of the
// callers that show an apply result.
function describeApply(res, m, i = 0) {
  const v = describeApplyResult(res, m, i);
  // A fix the patch declined to call. This is not "no effect" — u1.fix.* never
  // ran at all, so the selectors are innocent and looking at them is wasted
  // time. Say which one and why.
  const skipped = (res.skipped || []).filter((k) => !m || !m.type || k.type === m.type);
  if (skipped.length) {
    v.ok = false;
    v.msg += ` u1.fix.${skipped[0].type} was not run at all: ${skipped[0].why}.` +
      ` Nothing on the page was touched by it — the selectors are not the problem.`;
  }

  const clash = ((res.details || [])[i] || {}).roleClash;
  if (clash) {
    v.ok = false;
    v.msg += ` ${clash.sel} carries role="${clash.role}" in the site's own HTML.` +
      ` U1 will not write role="${clash.willWrite}" over it, so this fix cannot land while it is there.`;
    v.roleClash = clash;
  }
  return v;
}

function describeApplyResult(res, m, i = 0) {
  const d = (res.details || [])[i];
  if (!res.ok) {
    return { ok: false, msg: res.u1Missing
      ? 'U1 is not loaded on this page, so nothing was applied.'
      : 'Applying failed: ' + (res.err || 'unknown') };
  }
  if (d && d.status === 'ok') {
    const v = { ok: true, msg: `Applied — ${d.changed} element${d.changed === 1 ? '' : 's'} changed on the page.` };
    if (d.rebuilt) {
      v.msg += ' Note: this component is built by the site\u2019s own JavaScript after the page loads, so U1 had already finished with the empty container before these elements existed.';
    }
    if (d.fieldsNoEffect && d.fieldsNoEffect.length) {
      v.ok = false;
      // For a menu this is usually not a selector fault. menubar:false is
      // mandatory once there are submenus, and with it off U1 adds tabindex
      // and aria-hidden but no role="menu"/"menuitem" — so the fields look
      // untouched to anyone checking the DOM for roles.
      const menubarFalse = m && m.type === 'menu' && m.config && m.config.menubar === false;
      v.msg += ` But ${d.fieldsNoEffect.map(f => `"${f}"`).join(', ')} changed nothing — U1 decorated the container and left ${d.fieldsNoEffect.length === 1 ? 'that field' : 'those fields'} alone.`;
      // Short, and accurate. With menubar:false U1 DOES give the triggers
      // role="button" and the submenu containers role="menu" — only
      // role="menuitem" is exclusive to menubar:true. The old wording said
      // otherwise and ran to four sentences.
      v.msg += menubarFalse
        ? ` With menubar off, only "triggers" and "submenus" get roles — items stay plain links. Fill those two fields if they are empty.`
        : ` Check the selector, or whether this component supports it.`;
    }
    if (d.unblocked) {
      v.ok = false;
      // Careful about whose attribute this is. U1 stamps the same marker on
      // everything it has handled, and the panel cannot tell the two apart
      // from the DOM alone once U1 has run — so this used to send people to
      // edit markup that did not contain it (molinahealthcare.com serves no
      // u1st-* attribute at all, and got this note on two menus). Say what is
      // measured, and name the one test that settles it.
      v.msg += ` Note: ${d.sel} already carried u1st-avoid-change-detection. It was lifted here so the fix could run. Reload and Apply once: if it comes back on a clean load the attribute is in the site's HTML and must be removed there, or this will not work in production.`;
    }
    return v;
  }
  // Applied, but something about the result looks harmful. Say it loudly and
  // above everything else — but the mapping IS applied, and undoing it on a
  // heuristic would be worse than letting someone who knows the library look.
  if (d && d.harm && d.harm.length) {
    return { ok: false, msg: `Applied — but check this: ${d.harm.join('; ')}. The mapping is still in place; if that is wrong for this component, use Delete to undo it precisely.` };
  }
  if (d && d.status === 'error') {
    return { ok: false, msg: `u1.fix.${d.type} threw: ${(res.errs && res.errs[0]) || 'unknown error'}` };
  }
  if (d && d.status === 'no-match') return { ok: false, msg: `Nothing on the page matches ${d.sel}.` };
  if (d && d.reason === 'source-opt-out') {
    return { ok: false, msg: `${d.sel} already carried u1st-avoid-change-detection before the fix ran — U1 skips such an element. Reload the page and Apply once; if it says this again on a clean load, the attribute is in the site's own HTML and has to be removed there.` };
  }
  if (d && d.reason === 'already-processed') {
    return { ok: false, msg: 'U1 had already processed this element this page load. Reload the page and press Apply All.' };
  }
  // The one we chased all day. Say the whole thing, because no amount of
  // selector work can help and the fix is not in this panel.
  if (d && d.rebuilt) {
    return { ok: false, msg: `Nothing changed — not the selectors. ${d.sel} is built by the site's JavaScript after load, so U1 had already finished with the empty container. It never looks at an element twice in one page load. The site has to render this in the HTML, or call u1.fix.* itself once it has built it.` };
  }
  if (res.u1State && res.u1State.decoratedOnPage === 0) {
    return { ok: false, msg: 'U1 is loaded but has decorated nothing anywhere on this page — it never started up for this domain. No mapping can apply until that is fixed, and the selectors are not the problem.' };
  }
  return { ok: false, msg: 'Nothing changed on the page — u1.fix ran without error and wrote no attributes.' };
}

// ── The agent, as a conversation ────────────────────────────────────────────
// One thread per mapping. Context (markup, config, what measurably happened)
// is gathered once and rides with every turn, so the specialist can just say
// "the mapping doesn't work" and get an answer, the way they would with any
// other agent.
const agentThreads = new Map();   // key → { ctx, history: [{role, text}] }

function renderAgentThread(box, key) {
  const t = agentThreads.get(key);
  if (!t) return;
  box.innerHTML =
    `<div class="ai-chat-head"><span>✨ Ask AI</span>` +
    `<button class="ai-why-close" data-closewhy title="Close">✕</button></div>` +
    `<div class="ai-chat-log">${t.history.map(m =>
      m.role === 'user'
        ? `<div class="ai-msg you">${escapeHtml(m.text)}</div>`
        : `<div class="ai-msg bot">${escapeHtml(m.text)}` +
          ((m.selectors || []).length
            ? `<div class="ai-msg-fix">${m.selectors.map(s =>
                `<code>${escapeHtml(s.key)}: ${escapeHtml(s.value)}</code>`).join('')}` +
              `<button class="btn-outline btn-xs" data-chatfix="${escapeHtml(key)}" data-turn="${t.history.indexOf(m)}">Use these</button></div>`
            : '') + `</div>`
      ).join('')}${t.busy ? '<div class="ai-msg bot thinking"><span></span><span></span><span></span></div>' : ''}</div>` +
    `<div class="ai-ask">` +
    `<input type="text" class="ai-ask-input" data-chatinput="${escapeHtml(key)}" ` +
    `placeholder="${t.history.length ? 'Reply…' : 'What isn\u2019t working?'}"${t.busy ? ' disabled' : ''}>` +
    `<button class="btn-outline btn-sm" data-chatsend="${escapeHtml(key)}"${t.busy ? ' disabled' : ''}>Send</button></div>`;
  const log = box.querySelector('.ai-chat-log');
  if (log) log.scrollTop = log.scrollHeight;
  const inp = box.querySelector('.ai-ask-input');
  if (inp && !t.busy) inp.focus();
}

async function agentSend(key, box, text) {
  const t = agentThreads.get(key);
  if (!t || !text) return;
  t.history.push({ role: 'user', text });
  t.busy = true;
  renderAgentThread(box, key);

  const out = await U1AI.chat({ ...t.ctx, history: t.history });
  aiCost += U1AI.estimateCost(out.usage) || 0;
  t.busy = false;
  t.history.push(out.err
    ? { role: 'assistant', text: out.err }
    : { role: 'assistant', text: out.reply || '', selectors: out.selectors || [] });
  renderAgentThread(box, key);
}

// Gather everything the agent needs to answer without being told it: the
// component's markup, the config in force, and what applying it actually does.
// `overwriteRole` matters here too: the agent is asked why a mapping did not
// work, and to answer that it re-applies it and watches. Re-applying it
// differently from how it really runs would have it diagnose a run that never
// happened.
async function agentContext(type, primary, firstArg, config, overwriteRole) {
  const sel = firstArg || primary;
  const tab = await getTab();
  if (!isInjectable(tab)) return { err: 'Cannot read this page.' };
  const markup = await inPage(tab.id, (s) => window.__u1SelectorIntel.extractComponent(s), [sel]);
  if (!markup || markup.error || markup.notFound) {
    return { err: `Nothing on this page matches ${sel}.` };
  }
  const res = await applyMappingsBatch([{ type, primary, firstArg, config, overwriteRole }]);
  const d = (res.details || [])[0];
  const outcome = !res.ok
    ? (res.u1Missing ? 'window.u1 is not loaded on the page at all.' : 'Applying failed: ' + res.err)
    : d && d.status === 'error' ? `u1.fix.${d.type} threw: ${(res.errs || [])[0] || 'unknown'}`
    : d && d.status === 'no-match' ? `Nothing on the page matches ${d.sel}.`
    : res.applied
      ? `${d.changed} element(s) gained U1 attributes.` +
        (d.fieldsNoEffect && d.fieldsNoEffect.length
          ? ` These fields changed nothing: ${d.fieldsNoEffect.join(', ')}.`
          : ' Every configured field changed something.')
      : `Nothing changed at all. u1.fix ran without throwing and wrote no attributes.${d && d.reason ? ' Reason: ' + d.reason + '.' : ''}`;
  // Hand the agent U1's own state, so a conversation starts from what the
  // library is actually doing rather than from the selectors.
  const state = res.u1State
    ? `\n\nState of the u1 library on this page: ${JSON.stringify(res.u1State)}.` +
      (res.u1State.decoratedOnPage === 0
        ? ' It has decorated NOTHING anywhere on this page, so it never started up for this domain — that is not a selector problem.'
        : '')
    : '';
  return { u1Type: type, containerSel: sel, config, markup, outcome: outcome + state };
}

document.addEventListener('click', (e) => {
  const send = e.target.closest('[data-chatsend]');
  if (!send) return;
  const key = send.dataset.chatsend;
  const box = send.closest('.ai-why');
  const inp = box.querySelector('.ai-ask-input');
  const text = (inp?.value || '').trim();
  if (text) agentSend(key, box, text);
});

document.addEventListener('keydown', (e) => {
  if (e.key !== 'Enter') return;
  const inp = e.target.closest('[data-chatinput]');
  if (!inp) return;
  e.preventDefault();
  const text = inp.value.trim();
  if (text) agentSend(inp.dataset.chatinput, inp.closest('.ai-why'), text);
});

// Close the agent's answer. It also lives inside the mapping's body, so
// collapsing the mapping puts it away.
document.addEventListener('click', (e) => {
  const x = e.target.closest('[data-closewhy]');
  if (!x) return;
  const box = x.closest('.ai-why');
  if (box) box.style.display = 'none';
});

// "Use these" — write the agent's proposed selectors where they belong: into
// the saved mapping if the thread is about one, otherwise into the card's form.
document.addEventListener('click', async (e) => {
  const btn = e.target.closest('[data-chatfix]');
  if (!btn) return;
  const key = btn.dataset.chatfix;
  const t = agentThreads.get(key);
  const turn = t && t.history[Number(btn.dataset.turn)];
  if (!turn || !turn.selectors) return;

  if (key.startsWith('card:')) {
    const idx = Number(key.slice(5));
    const form = document.getElementById('aiMapForm' + idx);
    if (!form) return;
    for (const s of turn.selectors) {
      const inp = s.key === 'primary'
        ? form.querySelector('input[data-field="__primary"]')
        : form.querySelector(`input[data-field="${CSS.escape(s.key)}"]`);
      if (inp) inp.value = s.value;
    }
    await refreshAiCard(idx);
    btn.textContent = 'Applied ✓';
    btn.disabled = true;
    return;
  }

  const mkey = storageKey('mappings', currentHostname);
  const list = (await U1Store.get([mkey]))[mkey] || [];
  const m = list[t.savedIdx];
  if (!m) return;
  for (const s of turn.selectors) {
    if (s.key === 'primary') m.primary = s.value;
    else {
      m.config = m.config || {};
      m.config.selectors = m.config.selectors || {};
      m.config.selectors[s.key] = s.value;
    }
  }
  const rebuilt = buildTemplate(m.type, m.primary, m.config.selectors || {}, m.config);
  if (rebuilt) Object.assign(m, { code: rebuilt.code, firstArg: rebuilt.firstArg, config: rebuilt.config });
  await U1Store.set({ [mkey]: list });
  t.ctx.config = m.config;
  await loadMappingsList();
  refreshExportInfo();
  showNotice(document.getElementById('applyAllStatus'),
    'Mapping updated. Apply it to see the difference.', 'success', 5000);
});

// Recovering work filed under another hostname for the same client.// Recovering work filed under another hostname for the same client.
document.getElementById('mappingsList')?.addEventListener('click', async (e) => {
  const move = e.target.closest('[data-adopt]');
  const copy = e.target.closest('[data-adopt-copy]');
  if (!move && !copy) return;
  const from = (move || copy).dataset.adopt || (move || copy).dataset.adoptCopy;
  const btn = move || copy;
  btn.disabled = true;
  btn.textContent = 'Working…';
  const { moved } = await moveSiteData(from, currentHostname, { copy: !!copy });
  await loadMappingsList();
  refreshExportInfo();
  showNotice(document.getElementById('applyAllStatus'),
    `${copy ? 'Copied' : 'Moved'} ${moved} mapping${moved === 1 ? '' : 's'} from ${from} to ${currentHostname}.`,
    'success', 6000);
});

// The keyboard engines live in grid-nav.js. For DEPLOYMENT we inline their
// source so the produced snippet runs on the live site with no extension.
//
// grid-nav.js holds three INDEPENDENT engines (grid/datepicker, make-clickable,
// tab strip) marked off by //#region u1-engine:<kind>. Inlining the whole file
// shipped all three to every client — roughly 26KB where a site using one of
// them needs 5–14KB. `kinds` narrows it to what the mappings actually call.
async function getGridEngineSource(kinds) {
  try {
    const res = await fetch(chrome.runtime.getURL('grid-nav.js'));
    const src = await res.text();
    const wanted = new Set(kinds && kinds.length ? kinds : ['grid', 'clickable', 'tabs', 'linklist']);

    const picked = [];
    const re = /\/\/#region u1-engine:([a-z]+)\r?\n([\s\S]*?)\r?\n\/\/#endregion/g;
    let m;
    while ((m = re.exec(src))) if (wanted.has(m[1])) picked.push(m[2]);

    // If the markers are ever lost to a bad edit, fall back to the whole file:
    // a deliverable that is larger than it needs to be still works, one missing
    // its engine does not.
    return stripComments(picked.length ? `'use strict';\n${picked.join('\n\n')}` : src);
  } catch { return ''; }
}

// The U1 patch corrects defects in the library itself (see u1-patch.js). It is
// sliced the same way the engine is, so a site that maps tabs and a menu ships
// those two corrections rather than all fifteen.
//
// `core` is always included: it carries the per-match wrapper for u1.fix.*, the
// observer the other regions register with, and the skip-link fix, which has no
// mapping type of its own to key off.
async function getPatchSource(types) {
  try {
    const res = await fetch(chrome.runtime.getURL('u1-patch.js'));
    const src = await res.text();

    // `focus` too: the focus-ring corrections are not tied to any component —
    // a logo link is on every page whether or not anything is mapped.
    const wanted = new Set(['core', 'focus']);
    (types || []).forEach((t) => wanted.add(t));
    // The popup a combobox opens IS a listbox, and the corrections for the open
    // list live with the role rather than with one of its two callers. Without
    // this a combobox ships without them.
    if (wanted.has('combobox')) wanted.add('listbox');

    const picked = [];
    const re = /\/\/#region u1-patch:([a-z]+)\r?\n([\s\S]*?)\r?\n\/\/#endregion/g;
    let m;
    while ((m = re.exec(src))) if (wanted.has(m[1])) picked.push(m[2]);

    // Only `core` matched means there is nothing type-specific to correct —
    // still worth shipping, because the wrapper and the skip-link fix apply to
    // every site. Nothing matched at all means the markers are gone; ship the
    // whole file rather than silently dropping the corrections.
    if (!picked.length) return stripComments(src);
    return stripComments(`'use strict';\n${picked.join('\n\n')}`);
  } catch { return ''; }
}

// Remove ALL comments from the engine before it ships. The delivered script
// should read as ordinary accessibility code — internal notes about how the
// authoring tool works have no place in a client deliverable. Doing it by
// stripping (rather than editing each comment) means future comments can never
// leak either. String/regex literals are respected so code is never corrupted.
function stripComments(src) {
  let out = '', i = 0;
  const n = src.length;
  let inS = null;      // ' " ` when inside a string
  while (i < n) {
    const c = src[i], c2 = src[i + 1];
    if (inS) {
      out += c;
      if (c === '\\') { out += (src[i + 1] || ''); i += 2; continue; }
      if (c === inS) inS = null;
      i++; continue;
    }
    if (c === '"' || c === "'" || c === '`') { inS = c; out += c; i++; continue; }
    if (c === '/' && c2 === '/') { while (i < n && src[i] !== '\n') i++; continue; }
    if (c === '/' && c2 === '*') { i += 2; while (i < n && !(src[i] === '*' && src[i + 1] === '/')) i++; i += 2; continue; }
    out += c; i++;
  }
  // Collapse the blank lines the stripped comments leave behind.
  return out.split('\n').filter((l, idx, a) => l.trim() !== '' || (a[idx - 1] || '').trim() !== '').join('\n').trim();
}

// For the QA monitoring hook: the ONE selector field per type that is reliably
// present on a normal (unopened) page load. For widgets whose main element only
// exists once opened (dialog/datepicker/combobox), the durable anchor is the
// trigger — checking the popup container itself would false-report as broken on
// every static monitor visit. Mirrors u1-runtime.js's MAIN_FIELD_BY_TYPE.
const QA_MAIN_FIELD = {
  dialog: 'trigger', datepicker: 'trigger', 'keyboard-grid': 'trigger',
  combobox: 'textbox', tooltip: 'trigger',
};

// Build the single {id,type,field,selector,page} the monitor should validate for
// a mapping: its reliable anchor selector plus the page path it was created on.
function qaCheckFor(m) {
  if (!m || typeof m !== 'object' || !m.id) return null;
  const schema = COMPONENT_SCHEMAS[m.type];
  const pKey = schema ? primaryKeyOf(schema) : null;
  const mainField = QA_MAIN_FIELD[m.type] || pKey || 'primary';
  let selector = '';
  if (mainField !== pKey && m.config && typeof m.config[mainField] === 'string') selector = m.config[mainField].trim();
  if (!selector) selector = (m.primary || m.firstArg || '').trim(); // fall back to the primary
  if (!selector) return null;
  let page = '';
  try { page = new URL(m.pageUrl).pathname.replace(/\/+$/, '') || '/'; } catch (e) { page = ''; }
  return { id: m.id, type: m.type || 'mapping', field: mainField, selector, page };
}

// Builds the full, self-contained script the implementer pastes into the site
// (after the U1 library tag). Everything here must run WITHOUT the extension.
async function buildDeployableCode(list, hostname) {
  const fixes = [], customs = [], grids = [], clickables = [], tabStrips = [],
        linkLists = [], crumbs = [], statics = [], hides = [], orders = [];
  // Every emitted block is preceded by its "Fix #N" header so the script can be
  // read against the close-out report line by line.
  const header = (m) => {
    // Lead each block with the durable id (the key the monitor reports on breakage).
    // Coerce to the id charset so a malformed/hostile id (e.g. an imported "*/…")
    // can't break out of the /* */ comment and inject code into the client bundle.
    const safeId = m && m.id ? String(m.id).replace(/[^A-Za-z0-9_-]/g, '') : '';
    const label = safeId || 'Fix';
    // type/primary/firstArg can carry attacker-chosen page text (an aria-label
    // or data-testid picked up while mapping a hostile element) — must not be
    // able to close this block comment early. See commentSafe().
    const what = [m && m.type, m && (m.primary || m.firstArg)].filter(Boolean).map(commentSafe).join('  ');
    return `/* ---- ${label} — ${what} ---- */`;
  };
  const sorted = list.slice().sort((a, b) => {
    const an = (a && a.fixNo) || 1e9, bn = (b && b.fixNo) || 1e9;
    return an - bn;
  });
  for (const m of sorted) {
    if (typeof m === 'string') { fixes.push(m); continue; }
    if (!m || typeof m !== 'object') continue;
    if (m.custom === 'keyboardGrid') grids.push(m);
    else if (m.custom === 'keyboardClickable') clickables.push(m);
    // Engine-carrying too: each call is nothing without its region.
    else if (m.custom === 'hideElement') hides.push(m);
    else if (m.custom === 'focusOrder') orders.push(m);
    // Must sit in an engine-carrying bucket, not with the plain customs: its
    // call is meaningless without the engine source shipped alongside it.
    else if (m.custom === 'keyboardTabs') tabStrips.push(m);
    // Same reason: the call needs its engine region shipped beside it.
    else if (m.custom === 'linkList') linkLists.push(m);
    // Same reason: the breadcrumb call needs its engine shipped beside it.
    else if (m.custom === 'breadcrumb') crumbs.push(m);
    // Declarations, not calls: a static fix switches on a corrector that lives
    // in the patch, so it has to be emitted BEFORE the patch runs.
    else if (m.custom === 'staticFix') { const c = mappingToCode(m); if (c) statics.push(header(m) + '\n' + c); }
    else if (m.custom) { const c = mappingToCode(m); if (c) customs.push(header(m) + '\n' + c); } // regenerated, never stored m.code
    else { const c = mappingToCode(m); if (c) fixes.push(header(m) + '\n' + c); }
  }

  const fileBanner = (label, note) => `/* ============================================================\n` +
    ` * U1 accessibility — ${label}\n` +
    ` * Site: ${hostname}\n` +
    ` * Generated by U1 Studio on ${new Date().toLocaleString()}\n` +
    (note ? ` * ${note}\n` : ``) +
    ` * ============================================================ */`;

  // Three separate files, not one pasted blob: u1-patch.js corrects the
  // library itself, u1-fixes.js is the site-specific mappings, u1-monitoring.js
  // is the (optional, inert-by-default) QA hook. A client's dev drops the
  // files in and links them — nothing to copy out of a Word document.
  const patchParts = [];
  const fixesParts = [];
  const monitoringParts = [];

  // Which static rules were switched on, ahead of everything else in the
  // fixes file. The correctors that read this ship inside the patch, and they
  // run the moment it loads — so this must still be declared before anything
  // else in u1-fixes.js runs, same reasoning as before the split.
  if (statics.length) {
    fixesParts.push(`/* ---- Static corrections — which ones are on ---- */\n` + statics.join('\n\n'));
  }

  // The patch must be in place BEFORE the u1.fix.* calls in u1-fixes.js: part
  // of what it does is wrap those functions so they apply to every match
  // instead of the first, and a wrapper installed afterwards would be too
  // late. That is why the package's install instructions load u1-patch.js
  // before u1-fixes.js, not just why they ship as separate files.
  if (fixes.length || statics.length) {
    const mappedTypes = [...new Set(sorted.filter((m) => m && m.type && !m.custom).map((m) => m.type))];
    // The statics region carries every corrector the table above can switch on.
    if (statics.length) mappedTypes.push('statics');
    const patch = await getPatchSource(mappedTypes);
    if (patch) {
      patchParts.push(
        fileBanner('U1 runtime extensions (u1-patch.js)',
          'Load this BEFORE u1-fixes.js — it extends window.u1.fix.* first.') + '\n\n' +
        `/* Extends window.u1.fix.* for the components mapped in u1-fixes.js,\n` +
        ` * covering what the current U1 infrastructure does not reach yet:\n` +
        ` * application to every match rather than one, additional keyboard\n` +
        ` * keys, additional ARIA state, and fixers this build does not carry.\n` +
        ` * Each extension checks the current state first, so it stands down on\n` +
        ` * its own once U1 itself covers the same ground. */\n` +
        `(function () {\n${patch}\n})();`
      );
    }
    // Wrapped in a named function and called, rather than run inline, so the
    // resize hook further down can run exactly the same calls again. See there
    // for why that is needed at all.
    if (fixes.length) {
      fixesParts.push(`/* ---- Component mappings ---- */\n` +
        `function __u1ApplyMappings() {\n` + fixes.join('\n\n') + `\n}\n__u1ApplyMappings();`);
    }
  }
  if (customs.length) {
    fixesParts.push(`/* ---- Accessible names ---- */\n` +
      `function __u1ApplyNames() {\n` + customs.join('\n\n') + `\n}\n__u1ApplyNames();`);
  }
  if (grids.length || clickables.length || tabStrips.length || linkLists.length || crumbs.length || hides.length || orders.length) {
    // Only the engines these mappings actually call.
    const kinds = [];
    if (grids.length) kinds.push('grid');
    if (clickables.length) kinds.push('clickable');
    if (hides.length) kinds.push('hide');
    if (orders.length) kinds.push('focusorder');
    if (tabStrips.length) kinds.push('tabs');
    if (linkLists.length) kinds.push('linklist');
    if (crumbs.length) kinds.push('breadcrumb');
    // A hosted engine turns ~26KB of pasted code into one <script src> line,
    // and lets an engine fix reach every client without anyone re-pasting it.
    // Empty field → inline, exactly as before, so a client who will not load a
    // third-party script still gets something that works.
    const engine = await getGridEngineSource(kinds);
    const calls = grids.map(g =>
      header(g) + `\nwindow.__u1InstallGridFromMapping(${JSON.stringify(g.primary)}, ${JSON.stringify(g.config, null, 2)});`
    ).concat(clickables.map(c =>
      header(c) + `\nwindow.__u1MakeClickable(${JSON.stringify({ selector: c.primary, role: (c.config && c.config.role) || 'button', label: (c.config && c.config.label) || '', activates: (c.config && c.config.activates) || '' }, null, 2)});`
    )).concat(tabStrips.map(t =>
      header(t) + `\nwindow.__u1InstallTabsFromMapping(${JSON.stringify(t.primary)}, ${JSON.stringify(t.config, null, 2)});`
    )).concat(linkLists.map(l =>
      header(l) + `\nwindow.__u1FixLinkListFromMapping(${JSON.stringify(l.primary)}, ${JSON.stringify(l.config, null, 2)});`
    )).concat(crumbs.map(b =>
      header(b) + `\nwindow.__u1InstallBreadcrumbFromMapping(${JSON.stringify(b.primary)}, ${JSON.stringify(b.config, null, 2)});`
    )).concat(hides.map(h =>
      header(h) + `\nwindow.__u1HideFromAll(${JSON.stringify({ selector: h.primary }, null, 2)});`
    )).concat(orders.map(o =>
      header(o) + `\nwindow.__u1FocusOrderFromMapping(${JSON.stringify(o.primary)}, ${JSON.stringify({ order: (o.config && o.config.order) || '' }, null, 2)});`
    )).join('\n\n');
    fixesParts.push(
      `/* ---- Engines (grid / clickable / tab strip / breadcrumb) ----\n` +
      ` * Adds the ARIA roles, names and states each pattern needs, roving\n` +
      ` * tabindex, arrow/Home/End/Enter/Space, a visible focus ring, and\n` +
      ` * re-applies itself on every re-render and each time a widget opens. */\n` +
      (engine ? `(function () {\n${engine}\n})();\n\n${calls}`
              : `/* !! Engine source unavailable — re-copy this script. */\n${calls}`)
    );
  }

  // ── Responsive re-apply ────────────────────────────────────────────────────
  // u1 processes an element ONCE per page load and stamps it; it does not come
  // back. On a responsive site that is a real gap: a page loaded wide has the
  // desktop nav fixed and the hamburger either hidden or not built yet. Resize
  // to a phone width and the site swaps in a menu u1 has never seen — no roles,
  // no aria, no keyboard. The visitor who most needs it gets nothing.
  //
  // Re-calling the same fixes is safe BECAUSE of that stamp: elements already
  // processed are skipped, so this costs nothing on a page that has not changed
  // and decorates whatever the breakpoint just introduced.
  //
  // Only on a real width change — a phone firing resize as the address bar
  // hides must not re-run this on every scroll. Height changes are ignored for
  // the same reason.
  if (fixes.length || customs.length) {
    const reapply = [fixes.length ? '__u1ApplyMappings' : null,
                     customs.length ? '__u1ApplyNames' : null].filter(Boolean);
    fixesParts.push(
      `/* ---- Responsive re-apply ----\n` +
      ` * u1 decorates an element once per page load. A responsive site swaps its\n` +
      ` * navigation at a breakpoint, and the menu that appears was never seen by\n` +
      ` * u1 — so it arrives with no roles, no aria and no keyboard support.\n` +
      ` * This re-runs the same calls after a real WIDTH change. Elements u1 has\n` +
      ` * already processed are skipped by the library itself, so nothing is done\n` +
      ` * twice. */\n` +
      `(function () {\n` +
      `  var lastWidth = window.innerWidth;\n` +
      `  var t = null;\n` +
      `  window.addEventListener('resize', function () {\n` +
      `    if (window.innerWidth === lastWidth) return;   // height only — ignore\n` +
      `    lastWidth = window.innerWidth;\n` +
      `    clearTimeout(t);\n` +
      `    t = setTimeout(function () {\n` +
      `      try { ${reapply.map(f => f + '();').join(' ')} } catch (e) {}\n` +
      `    }, 250);\n` +
      `  });\n` +
      `})();`
    );
  }
  if (fixesParts.length) {
    fixesParts.unshift(fileBanner('component fixes (u1-fixes.js)', 'Load this AFTER u1-patch.js.'));
  }

  // ── Monitoring hook — inert unless the page is loaded with ?u1qa=1 ─────────
  // Lets the external daily monitor detect a mapping whose selector no longer
  // resolves. On such a page it logs ONE greppable console.error per broken
  // mapping, carrying the durable id, the type, the exact field that broke, the
  // selector and the page — the monitor parses these lines straight into its
  // dashboard. Completely silent for real visitors (no ?u1qa=1 → returns early).
  const checks = [];
  for (const m of sorted) { const c = qaCheckFor(m); if (c) checks.push(c); }
  if (checks.length) {
    monitoringParts.push(
      fileBanner('monitoring hook (u1-monitoring.js)', 'Inert unless the page loads with ?u1qa=1 — safe to load anywhere.') + '\n\n' +
      `(function () {\n` +
      `  try {\n` +
      `    if (new URLSearchParams(location.search).get('u1qa') !== '1') return;\n` +
      `    var CHECKS = ${JSON.stringify(checks)};\n` +
      `    var here = (location.pathname || '/').replace(/\\/+$/, '') || '/';\n` +
      `    function run() {\n` +
      `      CHECKS.forEach(function (c) {\n` +
      `        try {\n` +
      `          if (c.page && c.page !== here) return; // page-specific mapping — only validate on its own page\n` +
      `          var ok = false; try { ok = !!document.querySelector(c.selector); } catch (e) { ok = false; }\n` +
      `          if (!ok) console.error('U1-VALIDATION-ERROR | domain=' + location.hostname + ' | type=' + c.type + ' | id=' + c.id + ' | field=' + c.field + ' | selector=' + c.selector + ' | page=' + location.pathname);\n` +
      `        } catch (e) {}\n` +
      `      });\n` +
      `    }\n` +
      `    if (document.readyState === 'complete') setTimeout(run, 800);\n` +
      `    else window.addEventListener('load', function () { setTimeout(run, 800); });\n` +
      `  } catch (e) {}\n` +
      `})();`
    );
  }

  return {
    patch: patchParts.join('\n\n'),
    fixes: fixesParts.join('\n\n'),
    monitoring: monitoringParts.join('\n\n'),
  };
}

document.getElementById('copyAllBtn').addEventListener('click', async () => {
  const key = storageKey('mappings', currentHostname);
  const stored = await U1Store.get([key]);
  const list = stored[key] || [];
  if (!list.length) return;
  const btn = document.getElementById('copyAllBtn');
  btn.textContent = 'Building…';
  const built = await buildDeployableCode(list, currentHostname);
  const text = [built.patch, built.fixes, built.monitoring].filter(Boolean).join('\n\n');
  await navigator.clipboard.writeText(text);
  btn.textContent = 'Copied!';
  setTimeout(() => { btn.textContent = 'Copy All'; }, 1500);
});

// ── Test a mapping (Dimension A static checks; Dimension B added in runTest) ──
async function runMappingTest(m, btn) {
  // Test the MAIN element (m.primary — e.g. the dialog), not firstArg (the trigger).
  const primary = m.primary || m.firstArg || '';
  const type = m.type;
  const config = (m.config && typeof m.config === 'object') ? m.config : { selectors: {} };
  const status = document.getElementById('applyAllStatus');
  if (btn) { btn.disabled = true; btn.textContent = '…'; }
  showNotice(status, 'Running test — watch the page for the keyboard navigation…', 'warn', 0);
  const res = await callTestEngine('runTest', [type, primary, config]);
  if (btn) { btn.disabled = false; btn.textContent = '🧪'; }
  status.style.display = 'none';
  if (!res || !res.static) {
    showNotice(status, 'Could not run the test on this page — is the element present?', 'error', 4000);
    return;
  }
  renderTestResults(m, res);
}

// ── Live keyboard-test streaming ────────────────────────────────────────────
// test-engine.js posts u1-test-start / u1-test-step as it drives the page. Show
// each step the moment it happens (the final tally still replaces this when
// runTest resolves via renderTestResults).
function testStepRowHtml(step) {
  const st = step.status;
  const icon = st === 'pass' ? '✓' : st === 'fail' ? '✗' : '⚠';
  return `<li class="test-step ${st}"><span class="ti">${icon}</span>` +
    `<span class="tl">${escapeHtml(step.label || '')}</span>` +
    `${step.message ? `<div class="tm">${escapeHtml(step.message)}</div>` : ''}</li>`;
}
chrome.runtime.onMessage.addListener((msg) => {
  if (!msg || typeof msg !== 'object') return;
  if (msg.type === 'u1-locate') { jumpToMapping(msg); return; }
  if (msg.type === 'u1-locate-off') { setLocateButton(false); return; }
  // During an element scan the specialist is looking at the Scan tab, and
  // #testResults lives in Picker where they cannot see it. Send the live steps
  // where they are actually watching.
  if (elemScanRunning) { elemScanLiveStep(msg); return; }
  const box = document.getElementById('testResults');
  if (!box) return;
  if (msg.type === 'u1-test-start') {
    box.style.display = 'block';
    box.innerHTML =
      `<div class="test-head"><strong>Test</strong> <code>${escapeHtml(msg.primary || '')}</code>` +
      `<span class="test-live-tag">running…</span></div>` +
      `<div class="test-section-title">⌨️ Keyboard navigation</div>` +
      `<ul class="test-steps" id="testLiveSteps"></ul>`;
    box.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  } else if (msg.type === 'u1-test-step' && msg.step) {
    const ul = document.getElementById('testLiveSteps');
    if (ul) { ul.insertAdjacentHTML('beforeend', testStepRowHtml(msg.step)); ul.lastElementChild?.scrollIntoView({ block: 'nearest' }); }
  }
});

function codeSection(inspect) {
  if (!inspect || inspect.notFound) return '';
  const tags = (inspect.tags || []).map(t =>
    `<div class="test-code-tag"><span class="test-code-label">${escapeHtml(t.label)}</span><code>${escapeHtml(t.tag)}</code></div>`).join('');
  const html = inspect.outerHTML ? `<pre class="test-code-html">${escapeHtml(inspect.outerHTML)}</pre>` : '';
  return `
    <button class="test-code-toggle" id="testCodeToggle">▸ Applied code (what actually landed)</button>
    <div id="testCodePre" class="test-code-pre" style="display:none">
      ${tags}
      ${html}
    </div>`;
}

// Shared by the single-mapping panel and the element scan, so the two views of
// the same test can never drift apart.
function testStepListHtml(steps) {
  const icon = (s) => s === 'pass' ? '✓' : s === 'fail' ? '✗' : '⚠';
  return (steps || []).map(s => {
    const isIssue = s.status === 'fail' || s.status === 'warn';
    const why = s.why || s.message || '';
    // For a pass we just show the (optional) short message; for a warn/fail we
    // put the explanation behind a collapsible "Why?" accordion.
    const detail = isIssue && why
      ? `<details class="test-why"><summary>Why ${s.status === 'fail' ? 'this failed' : 'this warns'}?</summary><div class="tm">${escapeHtml(why)}</div></details>`
      : (s.message ? `<div class="tm">${escapeHtml(s.message)}</div>` : '');
    return `
    <li class="test-step ${s.status}">
      <span class="ti">${icon(s.status)}</span>
      <span class="tl">${escapeHtml(s.label)}${s.wcag ? ` <span class="wcag-chip">WCAG ${escapeHtml(s.wcag)}</span>` : ''}</span>
      ${detail}
    </li>`;
  }).join('');
}

// Pass / fail / warn tally for a step list, in the shared pill style.
function testPillsHtml(steps) {
  const list = steps || [];
  const f = list.filter(s => s.status === 'fail').length;
  const w = list.filter(s => s.status === 'warn').length;
  const p = list.length - f - w;
  return `<span class="pill pass">${p}✓</span><span class="pill fail${f ? '' : ' zero'}">${f}✗</span><span class="pill warn${w ? '' : ' zero'}">${w}⚠</span>`;
}

function renderTestResults(m, res) {
  const box = document.getElementById('testResults');
  if (!box) return;
  const stepRows = testStepListHtml;
  const staticSteps = (res.static && res.static.steps) || [];
  const kbSteps = (res.keyboard && res.keyboard.steps) || [];
  const pills = testPillsHtml;
  box.style.display = 'block';
  box.innerHTML = `
    <div class="test-head">
      <strong>Test</strong>
      <code>${escapeHtml(m.primary || m.firstArg || '')}</code>
      <button class="btn-ghost btn-xs" id="testEdit" title="Fix this element — open it in the editor">✎ Edit</button>
      <button class="btn-ghost btn-xs" id="testClose" title="Close">✕</button>
    </div>
    <div class="test-section-title">🏷️ Accessibility (code) <span class="pills">${pills(staticSteps)}</span></div>
    <ul class="test-steps">${stepRows(staticSteps)}</ul>
    <div class="test-section-title">⌨️ Keyboard navigation <span class="pills">${pills(kbSteps)}</span></div>
    <ul class="test-steps">${stepRows(kbSteps)}</ul>
    ${codeSection(res.inspect)}`;
  const codeToggle = document.getElementById('testCodeToggle');
  if (codeToggle) codeToggle.addEventListener('click', () => {
    const pre = document.getElementById('testCodePre');
    if (!pre) return;
    const open = pre.style.display !== 'none';
    pre.style.display = open ? 'none' : 'block';
    codeToggle.textContent = (open ? '▸' : '▾') + ' Applied code (what actually landed)';
  });
  const ed = document.getElementById('testEdit');
  if (ed) ed.addEventListener('click', () => {
    callTestEngine('removeHud', []);
    box.style.display = 'none'; box.innerHTML = '';
    if (typeof m === 'object') loadMappingIntoForm(m); // jump straight to edit mode for this element
  });
  const c = document.getElementById('testClose');
  if (c) c.addEventListener('click', () => {
    box.style.display = 'none'; box.innerHTML = '';
    callTestEngine('removeHud', []); // clear the on-page HUD too
  });
  box.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
}

// Full-image viewer dialog (for the element screenshot in a mapping row).
function openImageDialog(src) {
  document.getElementById('imgDialogOverlay')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'imgDialogOverlay';
  overlay.className = 'img-dialog-overlay';
  overlay.innerHTML = `
    <div class="img-dialog" role="dialog" aria-label="Element image">
      <button class="img-dialog-close" title="Close">✕</button>
      <img src="${safeImg(src)}" alt="Element image">
    </div>`;
  const close = () => overlay.remove();
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
  overlay.querySelector('.img-dialog-close').addEventListener('click', close);
  document.addEventListener('keydown', function esc(e) { if (e.key === 'Escape') { close(); document.removeEventListener('keydown', esc); } });
  document.body.appendChild(overlay);
}

/**
 * The Scan tab's list of what "every mapping" covers, by name.
 *
 * The card offered to test them all without ever naming one, so the only way to
 * find out what a press would cover was to press it. Each row can also be run on
 * its own — one option, the same run, restricted to that mapping.
 */
async function renderElemScanSaved(list) {
  const box = document.getElementById('elemScanSaved');
  if (!box) return;
  const real = list.filter(m => m && typeof m === 'object' && m.type);
  const testAllBtn = document.getElementById('elemScanBtn');
  if (testAllBtn) testAllBtn.textContent = real.length ? `Test all pages (${real.length})` : 'Test all pages';
  if (!real.length) { box.innerHTML = ''; box.style.display = 'none'; return; }
  box.style.display = '';
  const testedAll = await loadElemTested();
  // Verdicts from the LAST run only. The per-key store keeps every mapping's
  // most recent verdict for ever, so a ✕ from a run three engine fixes ago sat
  // on the row as if it were today's. Anything older than the last run is
  // shown dimmed as "earlier" and counted as untested on the page's scoreboard.
  const lastRun = await loadElemLastRun();
  const freshSince = lastRun ? lastRun.at - 120000 : 0;
  const testedMap = new Map([...testedAll.entries()].map(([k, v]) => [k, { ...v, stale: !!(v && v.at && v.at < freshSince) }]));
  // Named exactly as the Mappings drawer names them — the same id badge, the
  // same type pill, the same selector, in the same order. A mapping you are
  // looking for here is one you already recognise from down there, and
  // inventing a second way to write it down ("u1.fix.heading" three times over)
  // made a list of distinct things look like one thing repeated.
  const rowsHtml = real.map(m => {
    const mk = mappingKey(m);
    const sel = m.primary || m.firstArg || '';
    return `
    <tr class="saved-mappings-row" data-key="${escapeHtml(mk)}">
      <td class="sm-id">${m.id ? `<span class="mh-id" title="${escapeHtml(sel)}">${escapeHtml(m.id)}</span>` : `<span class="mh-id" title="${escapeHtml(sel)}">—</span>`}</td>
      <td><span class="mh-type">${escapeHtml(m.type)}</span></td>
      <td class="sm-status" data-status-for="${escapeHtml(mk)}"><span class="sm-status-dot checking"></span><span class="mh-sel">${escapeHtml(sel)}</span></td>
      <td class="sm-actions">
        ${(() => { const tv = testedMap.get(mk); return tv ? `<button type="button" class="sm-test ${escapeHtml(tv.status)}${tv.stale ? ' stale' : ''}" data-open-result="${escapeHtml(mk)}" title="${tv.stale ? 'From an EARLIER run' : 'Last run'}: ${escapeHtml(tv.status)} · ${new Date(tv.at).toLocaleString()} — click for the result">${escapeHtml(ELEM_CHIP[tv.status] || tv.status)}${tv.stale ? ' (earlier)' : ''}</button>` : `<span class="sm-test untested" title="Not tested yet">– untested</span>`; })()}
        <button class="btn-ghost btn-xs" data-testone="${escapeHtml(mk)}" title="Run the keyboard test on this one">🧪</button>
        <button class="btn-ghost btn-xs" data-editone="${escapeHtml(mk)}" title="Edit this mapping">✎</button>
        <button class="btn-ghost btn-xs" data-delone="${escapeHtml(mk)}" title="Remove">✕</button>
      </td>
    </tr>`;
  }).join('');
  // One accordion per page, this page first and open — the same shape the
  // results and the drawer use, so "which page is this on" is answered by
  // where the row sits, not by reading a URL.
  const tabNow = await getTab().catch(() => null);
  const hereUrl = cleanPageUrl(tabNow && tabNow.url);
  const perRow = real.map(m => {
    const mk = mappingKey(m);
    const start = rowsHtml.indexOf(`data-key="${escapeHtml(mk)}"`);
    if (start === -1) return { m, html: '' };
    const trStart = rowsHtml.lastIndexOf('<tr ', start);
    const trEnd = rowsHtml.indexOf('</tr>', start) + 5;
    return { m, html: rowsHtml.slice(trStart, trEnd) };
  });
  const groups = new Map();
  for (const { m, html } of perRow) {
    const k = (m.pageUrl && sameSiteUrl(m.pageUrl)) ? cleanPageUrl(m.pageUrl) : '__unknown';
    if (!groups.has(k)) groups.set(k, { k, url: m.pageUrl || '', title: m.pageTitle || '', rows: [], keys: [] });
    groups.get(k).rows.push(html);
    groups.get(k).keys.push(mappingKey(m));
  }
  // The page's own scoreboard, on its heading: how many mappings, how many of
  // them were ever tested, and how those came out.
  const pagePills = (g) => {
    const st = g.keys.map(k => { const v = testedMap.get(k); return v && !v.stale ? v.status : null; }).filter(Boolean);
    const n = (x) => st.filter(v => v === x).length;
    const tested = st.filter(v => ['pass', 'warn', 'fail'].includes(v)).length;
    return `<span class="pills sm-page-pills" title="${g.keys.length} mappings · ${tested} tested">` +
      `<span class="pill">${g.keys.length} mapped</span>` +
      (tested ? `<span class="pill">${tested} tested</span>` : `<span class="pill">untested</span>`) +
      (n('pass') ? `<span class="pill pass" title="passed">✓ ${n('pass')}</span>` : '') +
      (n('fail') ? `<span class="pill fail" title="failed">✕ ${n('fail')}</span>` : '') +
      (n('warn') ? `<span class="pill warn" title="warnings">⚠ ${n('warn')}</span>` : '') +
      (n('error') ? `<span class="pill fail" title="could not run">? ${n('error')}</span>` : '') +
      (n('notapplied') ? `<span class="pill warn" title="not applied on that page">${n('notapplied')} not applied</span>` : '') +
      `</span>`;
  };
  const pathOf = (u) => { try { const x = new URL(u); return (x.pathname + x.search) || '/'; } catch { return u; } };
  const order = [...groups.values()].sort((a, b) => {
    const rank = (g) => g.k === hereUrl ? 0 : g.k === '__unknown' ? 2 : 1;
    return rank(a) - rank(b) || (a.title || a.url).localeCompare(b.title || b.url);
  });
  const table = (rows) => `<div class="sm-scroll"><table class="saved-mappings-table"><thead><tr><th>ID</th><th>Type</th><th>Selector</th><th></th></tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
  box.innerHTML = order.length <= 1
    ? table(order.length ? order[0].rows : [])
    : order.map((g) => {
        const isHere = g.k === hereUrl;
        const name = g.k === '__unknown' ? 'Older mappings — no page recorded; tested on whichever page has them' : (g.title || pathOf(g.url));
        return `<details class="mapping-page elem-page${isHere ? ' is-here' : ''}"${isHere ? ' open' : ''}>
          <summary><span class="elem-page-title">${escapeHtml(name)}${isHere ? ' <span class="sc-ev-note">— this page</span>' : ''}</span>${pagePills(g)}${g.url && !isHere ? `<a class="elem-page-link" href="${escapeHtml(g.url)}" data-goto="${escapeHtml(g.url)}" title="${escapeHtml(g.url)}">↗ ${escapeHtml(pathOf(g.url).slice(0, 32))}</a>` : ''}</summary>
          ${table(g.rows)}
        </details>`;
      }).join('');
  box.querySelectorAll('.elem-page-link').forEach(a => a.addEventListener('click', async (e) => {
    e.preventDefault(); e.stopPropagation();
    const t = await getTab().catch(() => null);
    if (t) chrome.tabs.update(t.id, { url: a.dataset.goto }).catch(() => {});
  }));

  box.querySelectorAll('[data-testone]').forEach(b => {
    b.addEventListener('click', () => runElementScan(b.dataset.testone));
  });
  box.querySelectorAll('[data-editone]').forEach(b => {
    b.addEventListener('click', () => {
      const m = real.find(m2 => mappingKey(m2) === b.dataset.editone);
      if (!m) return;
      document.querySelector('.tab-btn[data-tab="picker"]')?.click();
      setPickerPane('scan');
      loadMappingIntoForm(m);
    });
  });
  box.querySelectorAll('[data-delone]').forEach(b => {
    b.addEventListener('click', () => deleteSavedMapping(b.dataset.delone));
  });

  // Hover a row, see the element outlined on the page — the same affordance
  // the Mappings drawer has, for the same reason: a selector string tells you
  // nothing about WHICH thing on screen it is. Same debounce, same fallback:
  // when the primary is a widget that's hidden while closed (a listbox's list,
  // a dialog's box), it has no box to outline, so the trigger (firstArg) is
  // lit instead. Marks are cleared on leaving the row or the table.
  let hoverTimer = null;
  let hoverSel = '';
  const stopHover = () => {
    clearTimeout(hoverTimer);
    hoverSel = '';
    getTab().then((t) => {
      if (t && isInjectable(t)) inPage(t.id, () => window.__u1SelectorIntel.clearMarks());
    }).catch(() => {});
  };
  box.querySelectorAll('.saved-mappings-row').forEach(row => {
    row.addEventListener('mouseenter', () => {
      const m = real.find(m2 => mappingKey(m2) === row.dataset.key);
      const sel = m ? (m.primary || m.firstArg || '') : '';
      if (!sel || sel === hoverSel) return;
      const alt = (m && m.firstArg && m.firstArg !== sel) ? m.firstArg : '';
      hoverSel = sel;
      clearTimeout(hoverTimer);
      hoverTimer = setTimeout(async () => {
        try {
          const tab = await getTab();
          if (!tab || !isInjectable(tab)) return;
          await inPage(tab.id, (s, a) => {
            const S = window.__u1SelectorIntel;
            const shown = (x) => {
              try {
                const el = document.querySelector(x);
                if (!el) return false;
                const r = el.getBoundingClientRect();
                return r.width > 0 && r.height > 0;
              } catch { return false; }
            };
            if (!shown(s) && a && shown(a)) return S.highlightSelector(a);
            return S.highlightSelector(s);
          }, [sel, alt]);
        } catch { /* the page went away or turned restricted mid-hover */ }
      }, 180);
    });
    row.addEventListener('mouseleave', stopHover);
  });
  box.addEventListener('mouseleave', stopHover);

  // Whether each one matches something actually on the current page — real,
  // measured status (the same check the Mappings drawer's "On this page"
  // filter uses), not a fabricated "tested" flag nothing here tracks between
  // sessions. Shown as a coloured dot on the selector itself (which stays on
  // screen throughout) rather than replacing it with a word — the selector
  // is what you came to this column to read.
  try {
    const present = await selectorsPresentOnPage(real.map(m => m.primary || m.firstArg || ''));
    const tab = await getTab();
    const hereUrl = cleanPageUrl(tab && tab.url);
    real.forEach(m => {
      const cell = box.querySelector(`[data-status-for="${CSS.escape(mappingKey(m))}"]`);
      const dot = cell && cell.querySelector('.sm-status-dot');
      if (!dot) return;
      // Same rule the Mappings drawer's "On this page" filter uses — visible
      // right now, OR captured on this exact URL (a closed dialog/dropdown
      // matches nothing while shut, but still belongs here). Checking
      // selectorsPresentOnPage alone marked every such widget "elsewhere"
      // while standing on the very page it's on.
      // present === null means "couldn't check at all" (not injectable) — kept
      // as its own "unknown" state here rather than defaulting to true the
      // way mappingOnPage does for the drawer's filter (where the lenient
      // default is "don't hide it"); a status DOT defaulting to green when it
      // has no idea would be a worse lie than an honest "can't check".
      const on = present === null ? null : mappingOnPage(m, present, hereUrl);
      dot.className = 'sm-status-dot ' + (on == null ? 'unknown' : on ? 'on' : 'off');
      dot.title = on == null ? "Can't check right now" : on ? 'On this page' : 'Not matching anything on this page right now';
      // Not here, but captured on a page we know — offer to go there rather
      // than leaving "elsewhere" unanswered. Same navigation the Setup tab's
      // "adopt from another site" flow uses.
      if (on === false && m.pageUrl && cell && !cell.querySelector('.sm-goto')) {
        const go = document.createElement('button');
        go.type = 'button';
        go.className = 'sm-goto';
        go.title = 'Open ' + m.pageUrl;
        go.textContent = '↗ go there';
        go.addEventListener('click', async (e) => {
          e.stopPropagation();
          const t = await getTab();
          if (t) await chrome.tabs.update(t.id, { url: m.pageUrl });
        });
        cell.appendChild(go);
      }
    });
  } catch {}
}

/**
 * The U1 fixes the SITE itself is already running.
 *
 * A site we are engaged on has often had U1 on it for months, wired by
 * somebody else — tamam.co.il arrives with several menus already deployed.
 * Until now those were invisible to the panel: you could see their EFFECT in
 * the DOM (u1_menu_link, u1st-* ids) but not what had been asked for, so the
 * only way to work with them was to guess the original call and retype it.
 *
 * u1-patch.js records every u1.fix.* the page runs, with the selector and the
 * props the site passed. background.js injects that patch at document_start in
 * the MAIN world, BEFORE the site's own U1 runs, so the record is what the
 * site actually asked for rather than a reconstruction of it.
 *
 * Returns [] when the page was loaded before the patch was armed — the record
 * is only as good as its timing, and an empty list is the honest answer to
 * "I cannot know", not a claim that the site has no fixes.
 */
async function findExistingFixes() {
  const tab = await getTab();
  if (!isInjectable(tab)) return [];
  try {
    const res = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      world: 'MAIN',
      func: () => {
        const p = window.__u1Patch;
        return (p && Array.isArray(p.calls)) ? p.calls : [];
      },
    });
    return (res && res[0] && res[0].result) || [];
  } catch { return []; }
}

/**
 * One recorded call, as the mapping the builder would have produced.
 *
 * The recorded shape is the fixer's own — { selectors: {...}, ...options } —
 * and buildTemplate wants the two halves separately, so they are split here
 * rather than in every caller. A type this build has no schema for is dropped:
 * the library has fixers we do not model, and a mapping we cannot rebuild is
 * one we cannot export, edit or verify.
 */
/**
 * Is this selector the LIBRARY talking to itself?
 *
 * U1 bootstraps by scanning the page for its own markers: on load it calls
 * fix.checkbox('[u1-checkbox]'), fix.radio('[u1-radio]'), fix.tabs('[u1-tabs]')
 * and so on for every type, plus things like '.u1_Datepicker_trigger'. Those
 * are the library's scaffolding, not a deployment anybody wrote, and adopting
 * them fills the list with one empty mapping per component type — which is
 * exactly what happened the first time this ran: 21 adopted, every one of them
 * scaffolding.
 *
 * Told apart by the selector alone, and safely: a site's own deployment points
 * at the SITE's markup (.elementor-nav-menu, .modal). Pointing a fix at a
 * marker the library itself adds would be circular, so a primary built only
 * from u1-owned tokens is never a real one.
 *
 * Only the PRIMARY is judged. A field may legitimately name a u1 class — a
 * menu's items really can be `.u1_menu_link` once the library has run.
 */
function isU1InternalSelector(sel) {
  const v = String(sel || '').trim();
  if (!v) return false;
  // Every simple token in it belongs to U1: [u1-*], [data-u1-*], .u1_*,
  // .u1st-*, #u1st-*.
  //
  // The data- form is not a nicety. The current library's bootstrap table
  // spells every entry as BOTH — U1_SELECTOR.BUTTON is
  // '[u1-button],[data-u1-button]' — and a predicate that only knew the bare
  // attribute judged that pair "not internal" on the strength of its second
  // half. So the whole table came through as real mappings: BUTTON, LINK,
  // TOOLTIP, LOADING, DIALOG, HEADING, one per component type, decorating
  // nothing, saved to the server and pulled down by everyone on the site.
  const tokens = v.match(/#[\w-]+|\.[\w-]+|\[[^\]]+\]|[a-z][\w-]*/gi) || [];
  if (!tokens.length) return false;
  return tokens.every((t) => /^\[\s*(data-)?u1(st)?[-_]/i.test(t) || /^[.#]u1(st)?[-_]/i.test(t));
}

function mappingFromRecordedCall(call) {
  if (!call || !call.type || !call.selector) return null;
  // The library scanning for its own markers, not a deployment to adopt.
  if (isU1InternalSelector(call.selector)) return null;
  const schema = COMPONENT_SCHEMAS[call.type];
  if (!schema) return null;
  const props = call.props || {};
  const pKey = primaryKeyOf(schema);
  const fields = {};
  const sels = props.selectors || {};
  for (const k of Object.keys(sels)) {
    if (k === pKey) continue;                 // the primary is the first argument
    if (typeof sels[k] === 'string') fields[k] = sels[k];
  }
  const roots = {};
  for (const k of Object.keys(props)) {
    if (k === 'selectors') continue;
    if (Object.prototype.hasOwnProperty.call(schema.rootFields || {}, k)) roots[k] = props[k];
  }
  try { return buildTemplate(call.type, call.selector, fields, roots); } catch { return null; }
}

/**
 * Offer the site's own fixes, and say plainly whose they are.
 *
 * Adopting one makes it a mapping like any other — editable, exportable,
 * monitored. That is what makes it useful and also what makes it worth being
 * explicit about: the exported file will then call a fix the site is ALREADY
 * calling, and two calls on the same elements fight (the panel warns about
 * exactly this elsewhere). So the offer says so, and the intended use is that
 * the adopted mappings REPLACE the old deployment rather than sit beside it.
 */
/**
 * Offers of the site's own fixes that have been turned down on this site.
 *
 * Kept as mapping keys, per site, and shared — see SITE_PREFIXES in store.js
 * for why this is not the `dismissed` list.
 */
async function declinedFixKeys() {
  try {
    const key = storageKey('declined', currentHostname);
    const v = (await U1Store.get([key]))[key];
    return new Set(Array.isArray(v) ? v.filter((k) => typeof k === 'string') : []);
  } catch { return new Set(); }
}

/**
 * Remember that these offers were turned down.
 *
 * Written through U1Store.set, never setLocalOnly: that is what carries it to
 * the server, which is the whole point — a refusal that lived on one machine
 * would be re-offered to every colleague on the site.
 */
async function rememberDeclinedFixes(keys) {
  const add = (keys || []).filter(Boolean);
  if (!add.length) return 0;
  try {
    const key = storageKey('declined', currentHostname);
    const have = await declinedFixKeys();
    const before = have.size;
    for (const k of add) have.add(k);
    if (have.size === before) return 0;
    // Bounded like the dismissed list, and for the same reason: it rides in
    // every settings push.
    await U1Store.set({ [key]: [...have].slice(-500) });
    return have.size - before;
  } catch { return 0; }
}

/**
 * Fixes THIS machine has run against the live page, by mapping key. Local and
 * private on purpose (the "__" prefix keeps it out of backups and off the
 * server): its one job is to recognise this browser's own leftovers. A page
 * keeps running whatever U1 wrote until it is reloaded, so a mapping applied
 * here and then deleted here used to masquerade as "a fix the site runs" —
 * and the delete path answered that by DECLINING it, permanently and for the
 * whole team. Every experiment of map-apply-delete grew the set-aside pile by
 * one. Now a leftover is recognised for what it is and simply not offered;
 * nothing is declined on anyone's behalf, and a page reload clears the
 * leftover itself.
 */
// ─────────────────────────────────────────────────────────────────────────────
//  "I went over this one" — the reviewer's own tick on a mapping
//
//  After an AI run the list is full of rows nobody has looked at. The tick is
//  a reading aid for that pass: which ones are checked, which still need a
//  look. It is about the person, not the mapping, so it lives OUTSIDE the
//  mapping record — a private-prefixed key (see store.js: stripped from
//  backups, refused on import, never synced), keyed by the mapping's durable
//  id. Nothing in the export, the report or the server ever sees it.
// ─────────────────────────────────────────────────────────────────────────────
const reviewedStoreKey = (host) => (U1Store.PRIVATE_PREFIX || '__') + 'reviewed_' + (host || currentHostname);
const reviewIdOf = (m) => (m && typeof m === 'object' && m.id) ? m.id : mappingKey(m);

async function loadReviewed() {
  try {
    const k = reviewedStoreKey();
    const v = (await U1Store.get([k]))[k];
    return new Set(Array.isArray(v) ? v.filter((x) => typeof x === 'string') : []);
  } catch { return new Set(); }
}

async function setReviewed(ids, on) {
  const have = await loadReviewed();
  for (const id of ids || []) { if (!id) continue; if (on) have.add(id); else have.delete(id); }
  try { await U1Store.setLocalOnly({ [reviewedStoreKey()]: [...have] }); } catch {}
  return have;
}

async function selfAppliedKeys() {
  try {
    const key = '__selfApplied_' + currentHostname;
    const v = (await U1Store.get([key]))[key];
    return new Set(Array.isArray(v) ? v.filter((k) => typeof k === 'string') : []);
  } catch { return new Set(); }
}

async function rememberSelfApplied(keys) {
  const add = (keys || []).filter(Boolean);
  if (!add.length) return;
  try {
    const key = '__selfApplied_' + currentHostname;
    const have = await selfAppliedKeys();
    const before = have.size;
    for (const k of add) have.add(k);
    if (have.size === before) return;
    await U1Store.setLocalOnly({ [key]: [...have].slice(-800) });
  } catch {}
}

/**
 * Deleting is the opposite of declining, and used to be recorded as the same
 * thing. "Every time I delete I expect it deleted from EVERYWHERE" — so a
 * delete also lifts any standing decline of the same fix, or the mapping
 * comes back undeletable-in-spirit: gone from the list, alive on the page,
 * and refused a fresh offer forever.
 */
async function forgetDeclinedFixes(keys) {
  const drop = new Set((keys || []).filter(Boolean));
  if (!drop.size) return;
  try {
    const key = storageKey('declined', currentHostname);
    const have = await declinedFixKeys();
    const next = [...have].filter((k) => !drop.has(k));
    if (next.length !== have.size) await U1Store.set({ [key]: next });
  } catch {}
}

async function renderExistingFixes() {
  // Owner decision (2026-09-02): this offer does not exist. The panel used to
  // read the site's own deployed u1.fix.* calls off the live page and offer
  // to adopt or set them aside — and however the answer was remembered (by
  // key, wholesale, surviving wipes or not), the box kept finding a reason to
  // come back: the recording is timing-dependent, deletes wipe the slate, and
  // every variant re-opened a question that had been answered. "I don't want
  // this set-aside at all — every delete starts fresh." So: nothing is ever
  // offered, nothing is remembered about it, and the box stays empty. The
  // recorder itself stays — u1-patch's call log still powers other reads.
  const box = document.getElementById('importExisting');
  if (box) { box.style.display = 'none'; box.innerHTML = ''; }
}

// "+ Add a mapping inside this dialog" — the dialog row's own way into the
// scoped scan. Fills the container box with the dialog's selector and hands
// over to the Automatic route; the save path stamps parent by containment,
// so whatever gets built there files under this row on its own.
document.addEventListener('click', (e) => {
  const btn = e.target.closest('.mapping-add-inside');
  if (!btn) return;
  const scope = btn.dataset.scope || '';
  setMapMode('auto');
  const input = document.getElementById('aiScopeInput');
  if (input) { input.value = scope; input.dispatchEvent(new Event('input')); }
  input?.scrollIntoView({ block: 'center', behavior: 'smooth' });
  input?.focus();
  showNotice(document.getElementById('aiStatus'),
    `Scoped to ${scope}. Open the dialog on the page, then Scan it (or ⏱ Scan in 5s for one that only exists while open) — ` +
    `what gets built files under this dialog's row.`, 'info', 12000);
});

/**
 * Delete one saved mapping by its stable key — the one place this happens, so
 * the Mappings drawer's delete button and the Scan tab's saved-mappings table
 * both go through the exact same bookkeeping (self-applied/declined records,
 * reverting what U1 already wrote to the live page) rather than two
 * implementations that can drift apart.
 *
 * Re-reads storage rather than trusting an in-memory list, so it is safe to
 * call from a render pass that isn't the one holding the current array.
 */
async function deleteSavedMapping(mk) {
  const key = storageKey('mappings', currentHostname);
  const list = (await U1Store.get([key]))[key] || [];
  const i = list.findIndex(m => m && typeof m === 'object' && mappingKey(m) === mk);
  if (i === -1) return;
  const gone = list[i];
  list.splice(i, 1);
  await U1Store.set({ [key]: list });
  try { await setReviewed([reviewIdOf(gone)], false); } catch {}

  // Deleted means deleted EVERYWHERE — including from the standing declines.
  // The page still runs what U1 already wrote, and that leftover used to be
  // answered by DECLINING the fix (permanently, for the whole team), so every
  // map-apply-delete experiment grew the set-aside pile by one. Now the
  // leftover is remembered locally as OURS — recognised and simply not
  // offered — and the loop the old decline was written against ("deleted 83,
  // offered 83 back") stays closed without anybody's refusal being forged.
  await rememberSelfApplied([mappingKey(gone)]);
  await forgetDeclinedFixes([mappingKey(gone)]);

  loadMappingsList();
  refreshExportInfo();

  // Deleting the mapping deletes the INSTRUCTION. It does not undo what U1
  // already wrote into the live DOM — roles, aria-*, tabindex, plus key
  // handlers that cannot be detached from outside. A reload is the only clean
  // way back.
  //
  // Said unconditionally rather than detected: U1's roles are
  // indistinguishable from the site's own, so any detector here is either
  // silent when it matters or crying wolf. This is always true anyway.
  const status = document.getElementById('applyAllStatus') || document.getElementById('applyStatus');
  const receipt = applyReceipts.get(gone.type + '::' + (gone.firstArg || gone.primary));
  const undone = await revertApplied(receipt);
  applyReceipts.delete(gone.type + '::' + (gone.firstArg || gone.primary));
  if (undone) {
    showNotice(status, `Removed — and ${undone} attribute${undone === 1 ? '' : 's'} U1 had written were taken back off the page.`, 'success', 6000);
  } else {
    showNotice(status,
      'Removed from the list. Anything U1 already wrote to the page in an earlier session is still there — reload to clear it.',
      'error', 10000);
    offerReload(status);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
//  🎯 Find on page — from the element to its row
//
//  The list says `.landing-module>div>a`; the page shows a "Learn more". Going
//  from the second to the first meant reading selectors off thirty rows. So:
//  arm, click the thing on the page, and its row opens here — or the panel
//  says there is no mapping for it, which is an answer too.
//
//  The match is made IN the page, by element: the nearest mapped ancestor
//  (or the element itself), else the smallest mapped thing inside what was
//  clicked (a card holding a mapped link). Selector strings never compare.
// ─────────────────────────────────────────────────────────────────────────────
let locateArmed = false;

function setLocateButton(on) {
  locateArmed = on;
  const b = document.getElementById('locateMappingBtn');
  if (!b) return;
  b.classList.toggle('on', on);
  b.textContent = on ? '■ Click an element on the page… (Esc to stop)' : '🎯 Find on page';
}

async function armLocateOnPage() {
  const tab = await getTab();
  if (!isInjectable(tab)) {
    showNotice(document.getElementById('mappingsStatus'), 'Cannot run on this page.', 'error', 4000);
    return;
  }
  const key = storageKey('mappings', currentHostname);
  const list = (await U1Store.get([key]))[key] || [];
  const owned = [];
  list.forEach((m) => {
    if (!m || typeof m !== 'object' || !m.type) return;
    for (const sel of new Set([m.primary, m.firstArg].filter(Boolean))) owned.push({ key: mappingKey(m), type: m.type, sel });
  });
  await inPage(tab.id, (owned, on) => {
    const W = window;
    if (W.__u1Locate) { W.__u1Locate.off(); W.__u1Locate = null; }
    if (!on) return;
    const q = (s) => { try { return Array.from(document.querySelectorAll(s)); } catch { return []; } };
    const own = owned.map(o => ({ ...o, els: q(o.sel) })).filter(o => o.els.length);
    const S = W.__u1SelectorIntel;
    const box = document.createElement('div');
    box.setAttribute('data-u1-locate', '');
    box.style.cssText = 'position:fixed;pointer-events:none;z-index:2147483646;border:2px solid #6c4cf1;background:rgba(108,76,241,.12);border-radius:3px;transition:all .06s;display:none';
    document.documentElement.appendChild(box);
    const prevCursor = document.documentElement.style.cursor;
    document.documentElement.style.cursor = 'crosshair';
    const direct = (el) => {
      // Nearest mapped ancestor-or-self.
      for (let n = el; n && n !== document.documentElement; n = n.parentElement) {
        const o = own.find(o => o.els.includes(n));
        if (o) return o;
      }
      // Else the smallest mapped thing inside.
      let best = null, bestArea = Infinity;
      for (const o of own) for (const e of o.els) {
        if (!el.contains(e)) continue;
        const r = e.getBoundingClientRect(), a = r.width * r.height;
        if (a < bestArea) { best = o; bestArea = a; }
      }
      return best;
    };
    // What the clicked thing OPENS. A hamburger button is not inside the menu
    // and the menu is not inside it — the button toggles #navbarCollapse and
    // the mapped <ul> lives there. The markup says so (aria-controls,
    // Bootstrap's data-target / data-bs-target, an in-page href), so follow it.
    const opens = (el) => {
      for (let n = el, hops = 0; n && n !== document.documentElement && hops < 3; n = n.parentElement, hops++) {
        const ref = n.getAttribute('aria-controls') || n.getAttribute('data-bs-target') ||
                    n.getAttribute('data-target') || ((n.getAttribute('href') || '').startsWith('#') ? n.getAttribute('href') : '');
        if (!ref) continue;
        const id = ref.replace(/^#/, '').split(/\s+/)[0];
        const t = id && document.getElementById(id);
        if (t && t !== n && !t.contains(n)) return t;
      }
      return null;
    };
    const hitFor = (el) => {
      const d = direct(el);
      if (d) return d;
      const t = opens(el);
      if (!t) return null;
      const o = direct(t);
      return o ? Object.assign({}, o, { via: 'opens', viaSel: '#' + t.id }) : null;
    };
    const move = (e) => {
      const el = document.elementFromPoint(e.clientX, e.clientY);
      if (!el || el === box) { box.style.display = 'none'; return; }
      const hit = hitFor(el);
      const target = hit ? (hit.els.find(x => x === el || x.contains(el) || el.contains(x)) || el) : el;
      const r = target.getBoundingClientRect();
      box.style.display = 'block';
      box.style.left = r.left + 'px'; box.style.top = r.top + 'px';
      box.style.width = r.width + 'px'; box.style.height = r.height + 'px';
      box.style.borderColor = hit ? '#22c55e' : '#d97706';
      box.style.background = hit ? 'rgba(34,197,94,.12)' : 'rgba(217,119,6,.10)';
    };
    const click = (e) => {
      e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation();
      const el = document.elementFromPoint(e.clientX, e.clientY);
      if (!el) return;
      const hit = hitFor(el);
      let sel = '';
      try { sel = S && S.robustSelector ? (S.robustSelector(el) || '') : ''; } catch {}
      chrome.runtime.sendMessage({
        type: 'u1-locate', key: hit ? hit.key : '', mtype: hit ? hit.type : '', msel: hit ? hit.sel : '',
        via: hit && hit.via ? hit.via : '', viaSel: hit && hit.viaSel ? hit.viaSel : '',
        sel, tag: el.tagName.toLowerCase(), text: (el.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 40),
      });
    };
    const keyd = (e) => { if (e.key === 'Escape') { e.preventDefault(); off(); chrome.runtime.sendMessage({ type: 'u1-locate-off' }); } };
    const off = () => {
      document.removeEventListener('mousemove', move, true);
      document.removeEventListener('click', click, true);
      document.removeEventListener('mousedown', swallow, true);
      document.removeEventListener('mouseup', swallow, true);
      document.removeEventListener('keydown', keyd, true);
      document.documentElement.style.cursor = prevCursor;
      box.remove();
      W.__u1Locate = null;
    };
    const swallow = (e) => { e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation(); };
    document.addEventListener('mousemove', move, true);
    document.addEventListener('click', click, true);
    document.addEventListener('mousedown', swallow, true);
    document.addEventListener('mouseup', swallow, true);
    document.addEventListener('keydown', keyd, true);
    W.__u1Locate = { off };
  }, [owned, !locateArmed]);
  setLocateButton(!locateArmed);
}

document.getElementById('locateMappingBtn')?.addEventListener('click', () => { armLocateOnPage().catch(() => {}); });

/** A page click came back: open that row, or say there is none. */
async function jumpToMapping(msg) {
  const status = document.getElementById('mappingsStatus');
  const what = `<${msg.tag}>${msg.text ? ` “${msg.text}”` : ''}${msg.sel ? ` (${msg.sel})` : ''}`;
  if (typeof setPickerPane === 'function') setPickerPane('mappings');
  if (!msg.key) {
    showNotice(status, `No mapping for ${what}. Still armed — click something else, or Esc to stop.`, 'warn', 6000);
    return;
  }
  const key = storageKey('mappings', currentHostname);
  const list = (await U1Store.get([key]))[key] || [];
  const idx = list.findIndex(m => mappingKey(m) === msg.key);
  if (idx < 0) { showNotice(status, `That mapping is no longer in the list.`, 'error', 5000); return; }
  const container = document.getElementById('mappingsList');
  let row = container && container.querySelector(`.mapping-item[data-idx="${idx}"]`);
  if (!row) {
    // Hidden by the filter (another page, or already reviewed): widen to All.
    setMappingsFilter('all');
    await loadMappingsList();
    row = container && container.querySelector(`.mapping-item[data-idx="${idx}"]`);
  }
  if (!row) return;
  // A row nested inside a dialog's row is only reachable once its parent opens.
  const parentRow = row.parentElement && row.parentElement.closest('.mapping-item');
  for (const r of [parentRow, row]) {
    if (!r) continue;
    const head = r.querySelector(':scope > .mapping-head');
    if (head && head.getAttribute('aria-expanded') !== 'true') head.click();
  }
  container.querySelectorAll('.mapping-item.located').forEach(r => r.classList.remove('located'));
  row.classList.add('located');
  row.scrollIntoView({ block: 'center', behavior: 'smooth' });
  setTimeout(() => row.classList.remove('located'), 2600);
  showNotice(status, msg.via === 'opens'
    ? `${what} is not mapped itself — it opens ${msg.viaSel}, and the mapping in there is ${msg.mtype} ${msg.msel}. ` +
      `The toggle is a native <button> with aria-expanded and aria-controls, so it needs no mapping of its own.`
    : `${msg.mtype} ${msg.msel} — that is the mapping for ${what}.`, 'success', 9000);
}

async function loadMappingsList() {
  const key = storageKey('mappings', currentHostname);
  const stored = await U1Store.get([key]);
  const list = stored[key] || [];
  // A mapping filed under another site's page (the tab in front at save time
  // was somewhere else) is corrected here: the page is forgotten, the mapping
  // kept. Silent, and said in the console — the record was wrong, not the work.
  {
    const wrong = list.filter(m => m && typeof m === 'object' && m.pageUrl && !sameSiteUrl(m.pageUrl));
    if (wrong.length) {
      wrong.forEach(m => { console.info('[U1 Studio] mapping', m.id || m.primary, 'was recorded on', m.pageUrl, '— not this site; page forgotten'); m.pageUrl = ''; m.pageTitle = ''; });
      try { await U1Store.set({ [key]: list }); } catch {}
    }
  }
  // Two mappings on one container are one mapping (containerKey). Healed here,
  // before either list renders, so what was stored before the save path
  // refused it does not keep blocking the good one on every Apply All.
  try {
    const collapsed = await collapseContainerDuplicates(list, key);
    if (collapsed.length) {
      const el = document.getElementById('mappingsStatus');
      if (el) showNotice(el, describeCollapse(collapsed), 'warn', 20000);
    }
  } catch {}
  renderElemScanSaved(list);
  const container = document.getElementById('mappingsList');
  const applyAllRow = document.getElementById('applyAllRow');
  const toolbar = document.getElementById('mappingsToolbar');

  if (list.length === 0) {
    // "The mappings disappeared" is almost always this: the work is filed
    // under another hostname for the same client. Say so here, where the
    // absence is noticed, instead of leaving an empty list to be believed.
    container.innerHTML = '<div class="empty-state">No mappings yet.</div>';
    if (applyAllRow) applyAllRow.style.display = 'none';
    // An empty list is exactly where "the site already runs six of these"
    // matters most, so the offer is made here too.
    renderExistingFixes();
    if (toolbar) toolbar.style.display = 'none';
    // Nothing is saved, so "approved and applied" is describing mappings that
    // no longer exist. Clear it, and drop the agent threads that were about
    // them — a conversation about a deleted mapping has nothing to be about.
    resetApprovedRun();
    try {
      const sites = (await U1Store.listSites()).filter(h => h !== currentHostname);
      const others = await U1Store.get(sites.map(h => storageKey('mappings', h)));
      const kin = sites
        .map(h => ({ h, n: (others[storageKey('mappings', h)] || []).length, rel: hostRelation(currentHostname, h) }))
        .filter(r => r.n > 0 && r.rel)
        .sort((a, b) => b.n - a.n);
      if (kin.length) {
        container.innerHTML =
          `<div class="advisor-note warn"><strong>Nothing is saved for ${escapeHtml(currentHostname)}</strong> — ` +
          `but the same client looks to be saved under another address. Storage is keyed by hostname, so a different URL for the same site is a different file.` +
          `<ul>${kin.map(r =>
            `<li><code>${escapeHtml(r.h)}</code> — ${r.n} mapping${r.n === 1 ? '' : 's'} ` +
            `<button class="btn-primary btn-xs" data-adopt="${escapeHtml(r.h)}">Move here</button> ` +
            `<button class="btn-outline btn-xs" data-adopt-copy="${escapeHtml(r.h)}">Copy here</button></li>`).join('')}</ul>` +
          `<div class="ai-comp-why">Move re-files that site's work under ${escapeHtml(currentHostname)} and leaves nothing behind. Copy keeps both.</div></div>`;
      }
    } catch {}
    return;
  }
  if (toolbar) toolbar.style.display = 'flex';

  // Backfill / repair Fix # — chronological by capture time so the numbers match
  // the order the work was actually done. Collision-safe: a mapping keeps its own
  // number only if it's unique; missing OR duplicate numbers are reassigned the
  // next free integer. This heals data where an old (unnumbered) mapping and a
  // freshly added one both ended up as #1.
  {
    const ordered = list.filter(m => m && typeof m === 'object')
      .slice().sort((a, b) => (a.capturedAt || 0) - (b.capturedAt || 0));
    const used = new Set();
    let n = 0, changed = false;
    const nextFree = () => { do { n++; } while (used.has(n)); return n; };
    ordered.forEach(m => {
      let no = Number(m.fixNo);
      if (!no || used.has(no)) { no = nextFree(); }
      if (no !== m.fixNo) { m.fixNo = no; changed = true; }
      used.add(no);
      // Backfill the durable monitor id onto any mapping saved before ids existed.
      if (!m.id) { m.id = genMappingId(); changed = true; }
    });
    if (changed) await U1Store.set({ [key]: list });
  }

  // "On this page": a mapping belongs to this page if its selector matches RIGHT
  // NOW, or if it was captured on this URL. The second test matters because
  // dialogs/datepickers only exist in the DOM while open — without it they
  // wrongly vanished from the list even though they belong to this page.
  const primaries = list.map(m => (m && typeof m === 'object') ? (m.primary || m.firstArg || '') : '').filter(Boolean);
  const present = await selectorsPresentOnPage(primaries);
  const tab = await getTab();
  const hereUrl = cleanPageUrl(tab && tab.url);
  const onPage = (m) => mappingOnPage(m, present, hereUrl);
  const testedMap = await loadElemTested();
  const onPageCount = list.filter(onPage).length;
  // Show how many mappings each tab holds, so it's obvious when something is hidden.
  const onPageBtn = document.getElementById('filterOnPage');
  const allBtn    = document.getElementById('filterAll');
  if (onPageBtn) onPageBtn.textContent = `On this page (${onPageCount})`;
  if (allBtn)    allBtn.textContent    = `All (${list.length})`;

  // The reviewer's ticks. Pruned to what still exists, so a deleted or
  // collapsed row does not keep counting as reviewed.
  const reviewed = await loadReviewed();
  const liveIds = new Set(list.map(reviewIdOf));
  const isReviewed = (m) => reviewed.has(reviewIdOf(m));
  const reviewedN = list.filter(isReviewed).length;
  const toReviewN = list.length - reviewedN;
  {
    const stale = [...reviewed].filter((id) => !liveIds.has(id));
    if (stale.length) setReviewed(stale, false);
    const btn = document.getElementById('filterToReview');
    if (btn) btn.textContent = `To review (${toReviewN})`;
    const cnt = document.getElementById('reviewCount');
    if (cnt) {
      cnt.textContent = toReviewN === 0
        ? `✓ All ${list.length} reviewed`
        : `Reviewed ${reviewedN} of ${list.length} · ${toReviewN} to review`;
      cnt.classList.toggle('done', toReviewN === 0);
      cnt.title = 'Your own pass over the list. Kept in this extension only — never in the export, the report or on the server.';
    }
  }
  // The count on the Mappings pane's tab, so the drawer says how full it is
  // from the other pane.
  const paneN = document.getElementById('pickerMappingsCount');
  if (paneN) paneN.textContent = list.length ? String(list.length) : '';

  const itemHtml = (m, idx, childrenHtml, childCount) => {
    const code = mappingToCode(m);
    const legacy = typeof m === 'string';
    const shot = m && typeof m === 'object' ? safeImg(m.screenshot) : '';
    const hasShot = !!shot;
    const isStatic = m && typeof m === 'object' && m.custom === 'staticFix';
    const type = isStatic ? 'static fix' : (m && typeof m === 'object' && m.type) ? m.type : 'mapping';
    // A static fix is a rule, not an element: the row says what the rule does,
    // in the scan's own words, instead of "window.__u1Statics[...] = {}".
    const staticRule = isStatic ? (SCAN_RULES[m.primary] || {}) : null;
    const primary = isStatic
      ? (staticRule.title || ({ contrast: 'Text too faint — darker shade on the flagged elements', exclude: 'Not reachable at all' })[m.primary] || m.primary)
      : (m && typeof m === 'object') ? (m.primary || m.firstArg || '') : String(m).slice(0, 40);
    // A menu's focus-opens-submenu switch is behaviour you cannot see in the
    // selector line, and the code below is folded — so the header says it,
    // on or off, for every menu. Read from the saved config, which is what
    // the page actually runs.
    const focusOpen = type === 'menu' && m && m.config
      ? (m.config.focusOpensSubmenu === true || m.config.focusOpensSubmenu === 'true')
      : null;
    // A <button>, not a <span> — but NOT a real <button> element: this sits
    // inside .mapping-head, which IS a <button>, and a <button> nested inside
    // another <button> is invalid HTML. The browser "fixes" that by closing
    // the outer button early, which would silently break the accordion
    // toggle for everything rendered after this chip. role="button" gives it
    // the same semantics and keyboard behaviour without the nesting problem —
    // the same shape .mh-thumb already uses for its own click-to-view.
    // The reviewer's tick. Same nested-role="button" shape as the focus-open
    // chip, for the same reason (a <button> may not hold a <button>).
    const rv = !legacy && isReviewed(m);
    const reviewChip = legacy ? '' :
      `<span class="mh-flag mh-flag-toggle mh-review ${rv ? 'on' : 'off'}" data-review="${idx}" role="button" tabindex="0" aria-pressed="${rv ? 'true' : 'false'}" title="${rv
          ? 'Reviewed — you went over this one. Click to clear.'
          : 'Not reviewed yet. Click once you have gone over it. Kept in this extension only.'}">${rv ? '✓ reviewed' : '○ review'}</span>`;
    // Where it was captured, one click away. The same navigation the Scan
    // table's "go there" makes — in THIS tab, so the panel stays on the site.
    // Dim when you are already there, so the eye is not sent nowhere.
    const pageUrl = (m && typeof m === 'object' && m.pageUrl) ? m.pageUrl : '';
    const here = pageUrl && cleanPageUrl(pageUrl) === hereUrl;
    const pathOf = (u) => { try { const x = new URL(u); return x.pathname + x.search || '/'; } catch { return u; } };
    const gotoChip = pageUrl
      ? `<span class="mh-flag mh-goto${here ? ' here' : ''}" data-goto="${escapeHtml(pageUrl)}" role="${here ? 'note' : 'button'}" tabindex="${here ? '-1' : '0'}" title="${escapeHtml(here
            ? 'Captured on this page: ' + pageUrl
            : 'Open the page this was captured on: ' + (m.pageTitle ? m.pageTitle + ' — ' : '') + pageUrl)}">↗ ${escapeHtml(here ? 'this page' : pathOf(pageUrl).slice(0, 28) + (pathOf(pageUrl).length > 28 ? '…' : ''))}</span>`
      : '';
    const focusChip = type === 'menu'
      ? `<span class="mh-flag mh-flag-toggle ${focusOpen ? 'on' : 'off'}" data-toggle-focusopen="${idx}" role="button" tabindex="0" aria-pressed="${focusOpen ? 'true' : 'false'}" title="${focusOpen
            ? 'Focus opens submenu: ON — Tab/focus on a trigger opens its submenu, Enter/Space does what click does. Click to turn off.'
            : 'Focus opens submenu: off. Click to turn on — Tab/focus on a trigger will open its submenu the way hover does.'}">⌨ focus-open ${focusOpen ? 'ON' : 'off'}</span>`
      : '';
    // A listbox's "only Enter picks" switch — the same kind of behaviour you
    // cannot read off the selector line.
    const enterSel = type === 'listbox' && m && m.config
      ? (m.config.enterSelects === true || m.config.enterSelects === 'true') : null;
    const enterChip = type === 'listbox'
      ? `<span class="mh-flag mh-flag-toggle ${enterSel ? 'on' : 'off'}" data-toggle-cfg="enterSelects" data-toggle-idx="${idx}" role="button" tabindex="0" aria-pressed="${enterSel ? 'true' : 'false'}" title="${enterSel
            ? 'Enter selects: ON — arrows only move the highlight, focus stays on the list, Enter/Space picks. Click to turn off.'
            : 'Enter selects: off. Click to turn on when an option acts as soon as it is focused (arrowing navigates the page).'}">↵ enter-selects ${enterSel ? 'ON' : 'off'}</span>`
      : '';
    // The last dynamic-scan verdict for this mapping, so the drawer says what
    // passed without opening the Scan tab.
    const tv = testedMap.get(mappingKey(m));
    const testChip = tv && ['pass', 'warn', 'fail', 'error'].includes(tv.status)
      ? `<span class="mh-flag mh-flag-toggle mh-test ${tv.status}" data-open-result="${escapeHtml(mappingKey(m))}" role="button" tabindex="0" title="Open this result in the Dynamic scan · ${new Date(tv.at).toLocaleString()}: ${tv.status}${tv.fail ? ` · ${tv.fail} failing step${tv.fail === 1 ? '' : 's'}` : ''}${tv.warn ? ` · ${tv.warn} warning${tv.warn === 1 ? '' : 's'}` : ''}">${tv.status === 'pass' ? '✓ passed' : tv.status === 'warn' ? '! warnings' : tv.status === 'fail' ? '✕ failed' : '? error'}</span>`
      : '';
    // Collapsed accordion: the header carries only what tells rows apart —
    // type, the full selector, and the EXCEPTIONS: a test that did not pass,
    // a switch that is not at its default, a row still to review, mappings
    // nested inside. Everything that is the same on every row (a green
    // "reviewed" on 42 of 45, "enter-selects off", the stable id, the page
    // path on the page you are on, the thumbnail) moved into the body,
    // where it is one click away and no longer costs the eye anything.
    // `reviewed` and `passed` stay two things: one is a person's tick, the
    // other the dynamic scan's verdict, and neither stands in for the other.
    const idChip = m && m.id ? `<span class="mh-id" title="Stable id — how the daily monitor reports this mapping if its selector breaks">${escapeHtml(m.id)}</span>` : '';
    const thumbHtml = hasShot ? `<span class="mh-thumb" data-idx="${idx}" title="Click to view full image">
            <img class="mh-img" src="${shot}" alt="Element preview">
            <img class="mh-preview" src="${shot}" alt="">
          </span>` : '';
    const noteHtml = m && m.note ? `<span class="mh-note" title="${escapeHtml(m.note)}">${escapeHtml(m.note)}</span>` : '';
    const headTest = tv && tv.status !== 'pass' ? testChip : '';
    const headFocus = focusOpen ? focusChip : '';
    const headEnter = enterSel ? enterChip : '';
    const headReview = rv ? '' : reviewChip;
    const headGoto = here ? '' : gotoChip;
    return `
      <div class="mapping-item${legacy ? ' legacy' : ''}${rv ? ' reviewed' : ''}" data-idx="${idx}">
        <button class="mapping-head" aria-expanded="false" data-idx="${idx}">
          <span class="mh-caret">▸</span>
          <span class="mh-type">${escapeHtml(type)}</span>
          <span class="mh-sel">${escapeHtml(primary)}</span>
          ${headTest}${headFocus}${headEnter}${headReview}
          ${childCount ? `<span class="mh-kids" title="Mappings for elements inside this dialog — open the row to see them">▸ ${childCount} inside</span>` : ''}
          ${headGoto}
        </button>
        <div class="mapping-body" style="display:none">
          <div class="mapping-meta">
            ${headReview ? '' : reviewChip}${headTest ? '' : testChip}${headFocus ? '' : focusChip}${headEnter ? '' : enterChip}${idChip}${headGoto ? '' : gotoChip}${thumbHtml}
          </div>
          ${noteHtml ? `<div class="mapping-meta-note">${noteHtml}</div>` : ''}
          ${childrenHtml ? `<div class="mapping-children">${childrenHtml}</div>` : ''}
          ${type === 'dialog' && primary ? `<button type="button" class="btn-outline btn-xs mapping-add-inside" data-scope="${escapeHtml(primary)}"
              title="Open it on the page, then scan just this dialog — whatever is built nests under this row">+ Add a mapping inside this dialog</button>` : ''}
          ${isStatic ? `<div class="map-mode-hint static-fix-what"><strong>What it does:</strong> ${escapeHtml((STATIC_FIXABLE[m.primary] || {}).does || (m.primary === 'contrast' ? `Sets a darker text colour on ${((m.config || {}).rules || []).reduce((n, r) => n + ((r.selectors || []).length), 0)} elements the scan found too faint, as one stylesheet rule.` : m.primary === 'exclude' ? `Takes ${escapeHtml((m.config || {}).selector || '')} out of the tab order and out of the screen reader.` : 'A rule applied to every matching element on every page.'))} Applies on every page of the site, now and in the export — it is a rule, not one element.</div>` : ''}
          <details class="mapping-code"><summary>Code</summary><pre>${escapeHtml(code)}</pre></details>
          <div class="mapping-actions">
            <button class="apply-btn" data-idx="${idx}" title="${legacy ? 'Legacy string — cannot auto-apply, please re-add' : 'Apply on page'}"${legacy ? ' disabled' : ''}><span class="ai">▶</span><span class="al">${legacy ? 'Re-add' : 'Apply'}</span></button>
            <button class="test-btn" data-idx="${idx}" title="Test accessibility + keyboard navigation"${legacy ? ' disabled' : ''}><span class="ai">🧪</span><span class="al">Test</span></button>
            <button class="edit-btn" data-idx="${idx}" title="Edit this mapping"${legacy ? ' disabled' : ''}><span class="ai">✎</span><span class="al">Edit</span></button>
            <button class="ask-btn" data-idx="${idx}" title="Ask AI about this mapping — why it isn't working, or change it in your own words"${legacy ? ' disabled' : ''}><span class="ai">✨</span><span class="al">Ask AI</span></button>
            <button class="shot-btn" data-idx="${idx}" title="Capture/refresh screenshot (open the element's page first)"${legacy ? ' disabled' : ''}><span class="ai">📷</span><span class="al">Screenshot</span></button>
            <button class="img-btn" data-idx="${idx}" title="Upload your own image"${legacy ? ' disabled' : ''}><span class="ai">🖼️</span><span class="al">Image</span></button>
            <button class="del-btn" data-idx="${idx}" title="Remove this mapping"><span class="ai">✕</span><span class="al">Remove</span></button>
          </div>
        </div>
      </div>
    `;
  };

  // Flat list (domain/page grouping lives only in the close-out report now).
  // Display in Fix # order so the list reads 1,2,3… — the storage/insertion order
  // can differ from the chronological numbering, which made numbers look shuffled.
  // idx stays the original storage index so the row buttons still target the right one.
  const entries = [];
  list.forEach((m, idx) => {
    const show = mappingsFilter === 'all' ? true
               : mappingsFilter === 'review' ? !isReviewed(m)
               : onPage(m);
    if (show) entries.push({ m, idx });
  });
  // What needs a hand first: a failing or warning test, then a row nobody has
  // reviewed, then the Fix # order the list has always read in. A failed
  // listbox at the bottom of 18 green rows is the one that got missed.
  const urgency = (m) => {
    const tv = testedMap.get(mappingKey(m));
    const st = tv && tv.status;
    return st === 'fail' || st === 'error' ? 0 : st === 'warn' ? 1 : (!isReviewed(m) ? 2 : 3);
  };
  entries.sort((a, b) => (urgency(a.m) - urgency(b.m)) || (((a.m && a.m.fixNo) || 1e9) - ((b.m && b.m.fixNo) || 1e9)));

  // A mapping born INSIDE a dialog files under that dialog's row — the row
  // opens like an accordion and its interior mappings sit in it. Two ways in:
  // the interior scan stamps `parent` at creation, and a selector that
  // extends the dialog's own (the finishing pass's headings inside a modal)
  // counts as inside even without the stamp.
  const dialogs = entries.filter((e) => e.m && typeof e.m === 'object' && e.m.type === 'dialog' && e.m.primary);
  const childOf = (e) => {
    if (!e.m || typeof e.m !== 'object') return null;
    for (const d of dialogs) {
      if (e === d) continue;
      if (e.m.parent && e.m.parent === d.m.primary) return d;
      if (e.m.primary && e.m.primary.indexOf(d.m.primary + '>') === 0) return d;
    }
    return null;
  };
  const kids = new Map();
  const top = [];
  for (const e of entries) {
    const d = childOf(e);
    if (d) {
      if (!kids.has(d)) kids.set(d, []);
      kids.get(d).push(e);
    } else top.push(e);
  }

  if (entries.length === 0) {
    container.innerHTML = mappingsFilter === 'review'
      ? '<div class="empty-state">✓ Nothing left to review — every mapping carries your tick.</div>'
      : '<div class="empty-state">No mappings match an element on this page. Switch to “All” to see the rest.</div>';
    if (applyAllRow) applyAllRow.style.display = 'flex';
    return;
  }

  const rowOf = (e) => {
    const ch = kids.get(e) || [];
    return itemHtml(e.m, e.idx,
      ch.length ? ch.map((c) => itemHtml(c.m, c.idx)).join('') : '', ch.length);
  };
  // "All": one accordion per page the work was done on — this page first and
  // open, the rest by title, folded. Site-wide rules (static fixes) sit in
  // their own group at the top. The other two filters are one page anyway.
  if (mappingsFilter === 'all') {
    const groups = new Map();
    for (const e of top) {
      const m = e.m || {};
      const k = m.custom === 'staticFix' ? '__site' : ((m.pageUrl && sameSiteUrl(m.pageUrl)) ? cleanPageUrl(m.pageUrl) : '__unknown');
      if (!groups.has(k)) groups.set(k, { k, url: m.pageUrl || '', title: m.pageTitle || '', rows: [] });
      groups.get(k).rows.push(e);
    }
    const order = [...groups.values()].sort((a, b) => {
      const rank = (g) => g.k === '__site' ? 0 : g.k === hereUrl ? 1 : g.k === '__unknown' ? 3 : 2;
      return rank(a) - rank(b) || (a.title || a.url).localeCompare(b.title || b.url);
    });
    const pathOf = (u) => { try { const x = new URL(u); return (x.pathname + x.search) || '/'; } catch { return u; } };
    container.innerHTML = order.map((g) => {
      const isHere = g.k === hereUrl;
      const name = g.k === '__site' ? 'Whole site — rules' : g.k === '__unknown' ? 'Older mappings — no page recorded' : (g.title || pathOf(g.url));
      return `<details class="mapping-page${isHere ? ' is-here' : ''}"${isHere || g.k === '__site' ? ' open' : ''}>
        <summary><span class="elem-page-title">${escapeHtml(name)}</span><span class="mh-kids">${g.rows.length}</span>${g.url && g.k !== '__site' ? `<span class="mh-flag mh-goto${isHere ? ' here' : ''}" data-goto="${escapeHtml(g.url)}" role="${isHere ? 'note' : 'button'}" tabindex="${isHere ? '-1' : '0'}" title="${escapeHtml(g.url)}">↗ ${escapeHtml(isHere ? 'this page' : pathOf(g.url).slice(0, 32))}</span>` : ''}</summary>
        ${g.rows.map(rowOf).join('')}
      </details>`;
    }).join('');
  } else {
    container.innerHTML = top.map(rowOf).join('');
  }

  if (applyAllRow) applyAllRow.style.display = 'flex';
  // Whatever the site is running that this list does not have. Not awaited —
  // it reaches into the page, and the list must not wait on that to paint.
  renderExistingFixes();

  // Accordion: each mapping collapsed by default; click the header to toggle.
  // ── Hover a mapping, see it on the page ───────────────────────────────────
  //
  // A row says `.signin-dropdown`. Which thing on the screen that IS cannot be
  // read off the string, and the alternative is opening devtools and pasting it
  // into a querySelector — for a question asked dozens of times an hour.
  //
  // Debounced, because running the mouse down a list of forty must not fire
  // forty scrolls; and every match is outlined, not just the first, so a
  // selector that has quietly widened to catch fourteen elements shows it here
  // rather than in production.
  let hoverTimer = null;
  let hoverSel = '';
  const stopHover = () => {
    clearTimeout(hoverTimer);
    hoverSel = '';
    getTab().then((t) => {
      if (t && isInjectable(t)) inPage(t.id, () => window.__u1SelectorIntel.clearMarks());
    }).catch(() => {});
  };

  container.querySelectorAll('.mapping-head').forEach(head => {
    head.addEventListener('mouseenter', () => {
      const m = list[parseInt(head.dataset.idx, 10)];
      const sel = m && typeof m === 'object' ? (m.primary || m.firstArg || '') : '';
      if (!sel || sel === hoverSel) return;
      // A listbox's or dialog's primary is the thing that APPEARS — hidden
      // right now, so highlighting it draws nothing while its trigger sits
      // plainly on screen. When the primary has no box, light the firstArg
      // (the trigger) instead, and say so on the row.
      const alt = (m && typeof m === 'object' && m.firstArg && m.firstArg !== sel) ? m.firstArg : '';
      hoverSel = sel;
      clearTimeout(hoverTimer);
      hoverTimer = setTimeout(async () => {
        try {
        const tab = await getTab();
        if (!tab || !isInjectable(tab)) return;
        const res = await inPage(tab.id, (s, a) => {
          const S = window.__u1SelectorIntel;
          const shown = (x) => {
            try {
              const el = document.querySelector(x);
              if (!el) return false;
              const r = el.getBoundingClientRect();
              return r.width > 0 && r.height > 0;
            } catch { return false; }
          };
          if (!shown(s) && a && shown(a)) return { n: S.highlightSelector(a), fell: true };
          return { n: S.highlightSelector(s), fell: false };
        }, [sel, alt]);
        const n = res && res.n;
        // Only report the empty case, and only on the row itself: a mapping
        // that matches nothing on the page in front of you is usually just a
        // mapping for another page, not a fault.
        head.title = res && res.fell ? `${sel} is closed right now — its trigger ${alt} is highlighted instead`
                   : n === 0 ? `${sel} matches nothing on this page right now`
                   : n === -1 ? `${sel} is not a valid selector`
                   : n > 1 ? `${sel} matches ${n} elements` : '';
        } catch { /* the page went away or turned restricted mid-hover — nothing to show */ }
      }, 180);
    });
    head.addEventListener('mouseleave', stopHover);
  });
  container.addEventListener('mouseleave', stopHover);

  container.querySelectorAll('.mapping-head').forEach(head => {
    head.addEventListener('click', () => {
      const body = head.parentElement.querySelector('.mapping-body');
      const open = head.getAttribute('aria-expanded') === 'true';
      head.setAttribute('aria-expanded', String(!open));
      const caret = head.querySelector('.mh-caret');
      if (caret) caret.textContent = open ? '▸' : '▾';
      // Use '' (not 'block') so the stylesheet's display:grid layout applies —
      // an inline display:block would override it and stack the buttons below.
      if (body) body.style.display = open ? 'none' : '';
    });
  });

  // Clicking the header thumbnail opens the full image (doesn't toggle the row).
  container.querySelectorAll('.mh-thumb').forEach(thumb => {
    thumb.addEventListener('click', (e) => {
      e.stopPropagation();
      const img = thumb.querySelector('.mh-img');
      if (img) openImageDialog(img.src);
    });
  });

  // The "focus-open" chip in a menu's header: click (or Enter/Space) flips
  // focusOpensSubmenu on that mapping directly, without opening the row to
  // find the checkbox in the edit form. Saves, re-applies on the page so the
  // behaviour actually changes rather than just the label, and redraws so the
  // chip reflects what is now really saved.
  // The reviewer's tick: stored, then the row and the counter redraw. No
  // apply — it changes nothing on the page, by design.
  container.querySelectorAll('.mh-review').forEach(chip => {
    const toggle = async (e) => {
      e.stopPropagation();
      const m = list[parseInt(chip.dataset.review, 10)];
      if (!m) return;
      chip.setAttribute('aria-disabled', 'true');
      await setReviewed([reviewIdOf(m)], !isReviewed(m));
      loadMappingsList();
    };
    chip.addEventListener('click', toggle);
    chip.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(e); }
    });
  });

  // ↗ page: go where the mapping was captured, in this tab.
  container.querySelectorAll('.mh-goto:not(.here)').forEach(chip => {
    const go = async (e) => {
      e.stopPropagation();
      const url = chip.dataset.goto;
      if (!url) return;
      const t = await getTab();
      if (t) await chrome.tabs.update(t.id, { url });
    };
    chip.addEventListener('click', go);
    chip.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(e); } });
  });

  container.querySelectorAll('.mh-test[data-open-result]').forEach(chip => {
    const go = (e) => { e.stopPropagation(); openElemResultFor(chip.dataset.openResult); };
    chip.addEventListener('click', go);
    chip.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(e); } });
  });

  container.querySelectorAll('.mh-flag-toggle[data-toggle-cfg]').forEach(chip => {
    const toggle = async (e) => {
      e.stopPropagation();
      const idx = parseInt(chip.dataset.toggleIdx, 10);
      const k = chip.dataset.toggleCfg;
      const m = list[idx];
      if (!m || typeof m !== 'object' || !k) return;
      chip.setAttribute('aria-disabled', 'true');
      m.config = m.config || {};
      m.config[k] = !(m.config[k] === true || m.config[k] === 'true');
      await U1Store.set({ [key]: list });
      try {
        await applyMappingsBatch([{ type: m.type, primary: m.primary, firstArg: m.firstArg, config: m.config, overwriteRole: m.overwriteRole }]);
      } catch {}
      loadMappingsList();
    };
    chip.addEventListener('click', toggle);
    chip.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(e); }
    });
  });

  container.querySelectorAll('.mh-flag-toggle[data-toggle-focusopen]').forEach(chip => {
    const toggle = async (e) => {
      e.stopPropagation();
      const idx = parseInt(chip.dataset.toggleFocusopen, 10);
      const m = list[idx];
      if (!m || typeof m !== 'object') return;
      chip.setAttribute('aria-disabled', 'true');
      m.config = m.config || {};
      m.config.focusOpensSubmenu = !(m.config.focusOpensSubmenu === true || m.config.focusOpensSubmenu === 'true');
      await U1Store.set({ [key]: list });
      try {
        await applyMappingsBatch([{ type: m.type, primary: m.primary, firstArg: m.firstArg, config: m.config, overwriteRole: m.overwriteRole }]);
      } catch {}
      loadMappingsList();
    };
    chip.addEventListener('click', toggle);
    chip.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(e); }
    });
  });

  // The agent, on a mapping that is already saved — which is where you find out
  // it is not doing what you wanted. It re-reads the component's markup from
  // the page, measures what the mapping actually does, and answers about THIS
  // mapping: why it is not working, or a change you ask for in words.
  // The agent on a saved mapping — a conversation about THIS mapping, which is
  // where you notice one is not doing what you wanted.
  container.querySelectorAll('.ask-btn:not([disabled])').forEach(btn => {
    btn.addEventListener('click', async () => {
      const idx = parseInt(btn.dataset.idx, 10);
      const m = list[idx];
      if (!m || !m.type) return;
      const item = btn.closest('.mapping-item');
      const body = item.querySelector('.mapping-body');
      let box = item.querySelector('.ai-why');
      if (!box) {
        box = document.createElement('div');
        box.className = 'ai-why';
        (body || item).appendChild(box);
      }
      if (body && body.style.display === 'none') {
        body.style.display = '';
        item.querySelector('.mapping-head')?.setAttribute('aria-expanded', 'true');
      }
      box.style.display = 'block';

      const key = 'saved:' + (m.id || idx);
      if (!agentThreads.has(key)) {
        box.innerHTML = '<div class="ai-busy"><div class="ai-busy-bar"><span></span></div>' +
          '<div class="ai-busy-sub">Reading this component and measuring what the mapping does.</div></div>';
        const ctx = await agentContext(m.type, m.primary, m.firstArg, m.config, m.overwriteRole);
        if (ctx.err) { box.innerHTML = `<div class="ai-sel-bad">${escapeHtml(ctx.err)}</div>`; return; }
        agentThreads.set(key, { ctx, history: [], savedIdx: idx });
      }
      renderAgentThread(box, key);
    });
  });

  container.querySelectorAll('.del-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const i = parseInt(btn.dataset.idx, 10);
      const m = list[i];
      if (m && typeof m === 'object') deleteSavedMapping(mappingKey(m));
    });
  });

  container.querySelectorAll('.test-btn:not([disabled])').forEach(btn => {
    btn.addEventListener('click', async () => {
      const i = parseInt(btn.dataset.idx, 10);
      const m = list[i];
      if (!m || typeof m !== 'object') return;
      // The test's home is the Scan tab — that is where its report is built,
      // filtered and exported. Running it from here used to print a different,
      // smaller answer in the Picker tab, so the same button gave two kinds of
      // result depending on which list you pressed it from. It moves you, and a
      // control that moves you says so before it does it.
      const name = m.primary || m.firstArg || m.type;
      const ok = confirm(
        `Test "${name}"?\n\n` +
        `This moves you to the Scan tab, where the result is shown with the ` +
        `rest of the mapping tests and can be exported. The page will be driven ` +
        `by the keyboard while it runs.`);
      if (!ok) return;
      document.querySelector('.tab-btn[data-tab="scan"]')?.click();
      await runElementScan(mappingKey(m));
    });
  });

  container.querySelectorAll('.edit-btn:not([disabled])').forEach(btn => {
    btn.addEventListener('click', () => {
      const i = parseInt(btn.dataset.idx, 10);
      const m = list[i];
      if (m && typeof m === 'object') loadMappingIntoForm(m);
    });
  });

  container.querySelectorAll('.img-btn:not([disabled])').forEach(btn => {
    btn.addEventListener('click', () => {
      const i = parseInt(btn.dataset.idx, 10);
      const m = list[i];
      if (!m || typeof m === 'string') return;
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = 'image/*';
      input.addEventListener('change', () => {
        const file = input.files && input.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = async () => {
          const scaled = await downscaleImage(reader.result, 900);
          m.screenshot = scaled || reader.result;
          m.capturedAt = Date.now();
          await U1Store.set({ [key]: list });
          loadMappingsList();
          showNotice(document.getElementById('applyAllStatus'), 'Image added to mapping.', 'success', 2000);
        };
        reader.readAsDataURL(file);
      });
      input.click();
    });
  });

  container.querySelectorAll('.shot-btn:not([disabled])').forEach(btn => {
    btn.addEventListener('click', async () => {
      const i = parseInt(btn.dataset.idx, 10);
      const m = list[i];
      if (!m || typeof m === 'string') return;
      const status = document.getElementById('applyAllStatus');
      const original = btn.textContent;
      btn.textContent = '…';
      const shot = await captureElementScreenshot(m.primary, m.firstArg, { reveal: true });
      btn.textContent = original;
      if (!shot) {
        showNotice(status, 'Could not capture — open the page with this element first.', 'error', 4000);
        return;
      }
      const tab = await getTab();
      m.screenshot = shot;
      m.pageUrl = tab?.url || m.pageUrl || '';
      m.pageTitle = tab?.title || m.pageTitle || '';
      m.capturedAt = Date.now();
      await U1Store.set({ [key]: list });
      loadMappingsList();
      showNotice(status, 'Screenshot captured.', 'success', 2000);
    });
  });

  container.querySelectorAll('.apply-btn:not([disabled])').forEach(btn => {
    btn.addEventListener('click', async () => {
      const i = parseInt(btn.dataset.idx, 10);
      const m = list[i];
      if (!m || typeof m === 'string') return;
      // Through applyAllMappings, scoped to this one. It measures the DOM, says
      // which fields moved and which did not, and names a role standing in the
      // way — none of which the direct call did.
      btn.disabled = true;
      try { await applyAllMappings({ only: mappingKey(m) }); }
      finally { btn.disabled = false; }
    });
  });
}

// ─────────────────────────────────────────────────────────────────────────────
//  TAB 4 — EXPORT
// ─────────────────────────────────────────────────────────────────────────────

// Export's four destinations as a grid of tiles instead of four cards
// stacked one after another — pick one, do that thing, ← Back to the grid.
const EXPORT_VIEWS = { package: 'exportViewPackage', finish: 'exportViewFinish', closeout: 'exportViewCloseout', backup: 'exportViewBackup' };
function setExportView(name) {
  const grid = document.getElementById('exportGrid');
  const target = EXPORT_VIEWS[name] || null;
  if (grid) grid.hidden = !!target;
  Object.values(EXPORT_VIEWS).forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.hidden = id !== target;
  });
}
document.getElementById('exportGrid')?.addEventListener('click', (e) => {
  const tile = e.target.closest('[data-exportview]');
  if (tile) setExportView(tile.dataset.exportview);
});
document.querySelectorAll('.export-view [data-exportback]').forEach((b) => {
  b.addEventListener('click', () => setExportView(null));
});

async function refreshExportInfo() {
  const mKey   = storageKey('mappings', currentHostname);
  const platKey = storageKey('platform', currentHostname);
  const stored = await U1Store.get([mKey, platKey]);
  const count  = (stored[mKey] || []).length;
  document.getElementById('exportMappingsCount').textContent =
    `${count} mapping${count !== 1 ? 's' : ''}`;

  const sel = document.getElementById('platformSelect');
  const detectedLabel = document.getElementById('platformDetected');
  // Prefer a saved override; otherwise auto-detect the platform.
  if (stored[platKey]) {
    sel.value = stored[platKey];
    if (detectedLabel) detectedLabel.textContent = '';
  } else {
    const tab = await getTab();
    const detected = await detectSiteType(tab);
    sel.value = detected;
    if (detectedLabel) detectedLabel.textContent = ` — detected: ${detected}`;
  }

  // The backup picker lists every site with saved work, not just this one, so
  // it has to be rebuilt here rather than once at start-up: a site joins the
  // list the moment its first mapping is saved.
  await refreshBackupSites();
}

// Persist a manual platform override per site.
document.getElementById('platformSelect').addEventListener('change', async (e) => {
  await U1Store.set({ [storageKey('platform', currentHostname)]: e.target.value });
  const detectedLabel = document.getElementById('platformDetected');
  if (detectedLabel) detectedLabel.textContent = ' — manual';
});

document.getElementById('exportBtn').addEventListener('click', async () => {
  // This goes to the client. Reading a global key here put another client's
  // bundle URLs into the handover document.
  const lk = storageKey('u1Links', currentHostname);
  const ik = storageKey('manualInject', currentHostname);
  const linkRec = await U1Store.get([lk, ik]);
  const { cssLink = '', jsLink = '' } = linkRec[lk] || linkRec[ik] || {};
  const skipKey = storageKey('skipLinks', currentHostname);
  const cfgKey  = storageKey('config', currentHostname);
  const mKey    = storageKey('mappings', currentHostname);
  const stored = await U1Store.get([skipKey, cfgKey, mKey]);
  const skipLinks = stored[skipKey] || [];
  const config    = stored[cfgKey]  || buildConfigObject(skipLinks);
  // The package must contain code that ACTUALLY RUNS on the live site with no
  // extension — u1.fix calls + custom JS + the inlined keyboard-grid engine —
  // split into the three files a client's dev drops in and links, rather than
  // one blob buried inside the Word document's own text.
  const built = await buildDeployableCode(stored[mKey] || [], currentHostname);

  const statusEl = document.getElementById('exportStatus');

  if (!cssLink || !jsLink) {
    statusEl.className = 'notice error';
    statusEl.textContent = 'Warning: CSS/JS links are empty. Fill them in the Setup tab first.';
    flashMessage(statusEl, 4500);
    return;
  }

  const platform = document.getElementById('platformSelect').value || 'wordpress';
  try {
    generateAndDownloadPackage(currentHostname, cssLink, jsLink, built, skipLinks, config, platform);
    statusEl.className = 'notice success';
    statusEl.textContent = `Package generated (${platform}) and downloaded.`;
    flashMessage(statusEl, 3000);
  } catch (err) {
    statusEl.className = 'notice error';
    statusEl.textContent = 'Error: ' + err.message;
    flashMessage(statusEl, 4500);
  }
});

// The firewall sheet on its own. It needs no CSS/JS links and no mappings —
// it is one request to one person, and gating it behind a complete package
// would be gating it behind work that has nothing to do with it.
document.getElementById('exportMonitoringBtn')?.addEventListener('click', async () => {
  const statusEl = document.getElementById('exportStatus');
  try {
    // The hook's own source, so the document is self-contained: it is very
    // often forwarded on its own, weeks after the .zip was sent and lost.
    let src = '';
    try {
      const mKey = storageKey('mappings', currentHostname);
      const stored = await U1Store.get([mKey]);
      src = (await buildDeployableCode(stored[mKey] || [], currentHostname)).monitoring || '';
    } catch {}
    const platform = document.getElementById('platformSelect')?.value || 'wordpress';
    generateAndDownloadMonitoringGuide(currentHostname, src, platform);
    showNotice(statusEl, src
      ? 'Monitoring guide downloaded — how to install the hook, the hook itself, and the ' +
        'three firewall addresses, in one document.'
      : 'Firewall allowlist downloaded. There are no mappings on this site yet, so the ' +
        'monitoring hook is not in it — re-export once there are.',
      'success', 9000);
  } catch (err) {
    showNotice(statusEl, 'Error: ' + err.message, 'error', 5000);
  }
});

// ── Finish project ───────────────────────────────────────────────────────────
//
// One bundle at the end of a project: everything Export package produces, plus
// the close-out report as a real PDF, named for the client — then the Drive
// folder opens so it can be dropped into their folder.
//
// The PDF is made by Chrome itself (Page.printToPDF over CDP, in the service
// worker) rather than by the print dialog. The dialog is right when a person
// is reading the report and wants a copy; it cannot produce a FILE to put in a
// zip, because it needs somebody standing at it choosing a destination.
//
// Nothing to fill in. The CRM holds the Google identity and owns the parent
// folder, creates the site's folder under it and returns its URL — so there is
// no folder for the specialist to choose, paste or keep in step. A field for
// it was there briefly and was exactly wrong: it made a step look manual that
// the server had already decided, and a pasted parent from the client would
// let any signed-in panel write anywhere that identity can reach.
// btoa needs a binary string. Built in chunks because
// String.fromCharCode(...bytes) on a multi-megabyte docx exceeds the argument
// limit and throws RangeError — which would have failed only on the big files,
// i.e. exactly the real ones.
/** Bytes as something a person reads at a glance, for the handover listing. */
function fileSize(n) {
  if (!(n > 0)) return '';
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${Math.round(n / 1024)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

function bytesToBase64(data) {
  const bytes = typeof data === 'string' ? new TextEncoder().encode(data) : data;
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  }
  return btoa(bin);
}


/**
 * Render the close-out report and print it to PDF, with no dialog.
 * Returns the PDF bytes, or null when there is nothing to report on.
 */
async function closeOutPdfBytes(hostname) {
  const allStorage = await U1Store.get(null);
  const pages = reportCollectPages(allStorage, hostname);
  if (!pages.length) return null;

  // Cleared BEFORE the tab opens: a flag left over from the last handover
  // would be read as "this one is ready" and print an empty page.
  await U1Store.setLocalOnly({ __closeOutReportHtml: reportBuildHtml(pages) });
  await U1Store.remove('__closeOutReportReady');
  const tab = await chrome.tabs.create({ url: chrome.runtime.getURL('report.html'), active: false });
  try {
    // report-view.js writes the document AFTER load, so "complete" on the tab
    // is not the same thing as "the report is on the page".
    await waitForReportRendered();
    const res = await chrome.runtime.sendMessage({ action: 'printTabToPdf', tabId: tab.id });
    if (!res || !res.ok) throw new Error(res && res.error ? res.error : 'print failed');
    // atob gives one char per byte; Uint8Array.from turns that into the real
    // bytes. The zip writer wants bytes, not a string.
    const bin = atob(res.data);
    return Uint8Array.from(bin, (c) => c.charCodeAt(0));
  } finally {
    try { await chrome.tabs.remove(tab.id); } catch {}
  }
}

/**
 * Wait for report-view.js to say the document is on the page.
 *
 * This polled the tab with chrome.scripting.executeScript, looking for the
 * report's root element. The scripting API does not inject into an extension's
 * own pages, so the poll saw nothing, ran its whole budget out, and reported
 * "the report did not finish rendering" about a report that had rendered
 * perfectly — every single time. The page sets a storage flag instead.
 */
async function waitForReportRendered(budgetMs = 15000) {
  const deadline = Date.now() + budgetMs;
  while (Date.now() < deadline) {
    const { __closeOutReportReady } = await U1Store.get('__closeOutReportReady');
    if (__closeOutReportReady) return true;
    await new Promise((r) => setTimeout(r, 100));
  }
  throw new Error('the report did not finish rendering');
}

document.getElementById('finishProjectBtn')?.addEventListener('click', async () => {
  const btn = document.getElementById('finishProjectBtn');
  const status = document.getElementById('finishStatus');
  const label = btn.textContent;
  btn.disabled = true;

  try {
    const cssLink = document.getElementById('cssLink').value.trim();
    const jsLink  = document.getElementById('jsLink').value.trim();
    if (!cssLink || !jsLink) throw new Error('Fill in the CSS/JS links in Setup first.');

    const mKey = storageKey('mappings', currentHostname);
    const cKey = storageKey('config', currentHostname);
    const sKey = storageKey('skipLinks', currentHostname);
    const stored = await U1Store.get([mKey, cKey, sKey]);
    const platform = document.getElementById('platformSelect').value || 'wordpress';

    btn.textContent = 'Building code…';
    const built = await buildDeployableCode(stored[mKey] || [], currentHostname);

    btn.textContent = 'Rendering PDF…';
    // A failed PDF must not cost the whole handover: the code files are the
    // part the client cannot proceed without, and the report can be exported
    // by hand from the Close-out section.
    let pdf = null, pdfErr = null;
    try { pdf = await closeOutPdfBytes(currentHostname); }
    catch (e) { pdfErr = String((e && e.message) || e); }

    btn.textContent = 'Packing…';
    const args = [currentHostname, cssLink, jsLink, built,
                  stored[sKey] || [], stored[cKey], platform, pdf];
    const files = buildHandoverFiles(...args);
    // Both forms go into the folder, on purpose.
    //
    // Loose files are what makes a handover folder readable: the client opens
    // the guide and the close-out report in Drive without downloading
    // anything. But taking the code away means clicking every file in turn —
    // and Chrome names the second copy of one "u1-patch (1).js", so a folder
    // fetched twice is a folder nobody can tell apart afterwards. The zip is
    // the whole handover in one click, beside the files it contains.
    const zip = buildHandoverZip(...args);
    files.push({ name: zip.name, mime: 'application/zip', data: zip.bytes });

    const lines = [];
    if (pdf) lines.push('Close-out report included as a PDF.');
    else if (pdfErr) lines.push(`No PDF — ${pdfErr}. Everything else was still produced.`);
    else lines.push('No PDF — this site has no mappings to report on yet.');

    // Upload if there is somebody to upload as. The CRM holds the Google
    // identity and decides the parent folder; all this sends is the files.
    let uploaded = null, uploadErr = null;
    if (await U1Auth.isLoggedIn()) {
      btn.textContent = 'Uploading to Drive…';
      try {
        uploaded = await U1Sync.uploadHandover(currentHostname,
          files.map((f) => ({ name: f.name, mime: f.mime, b64: bytesToBase64(f.data) })));
      } catch (e) {
        uploadErr = String((e && e.message) || e);
      }
    } else {
      uploadErr = 'not signed in';
    }

    if (uploaded && uploaded.folderUrl) {
      // Show the folder and what is IN it, not a count of what we sent.
      //
      // "7 files uploaded" is a claim about our own intent; it reads the same
      // whether Drive kept them or not, and it says nothing about what was
      // already in the folder from an earlier run or added by hand. Finishing a
      // project is the moment somebody wants to look at the folder and check —
      // so the check is the result.
      const files = uploaded.contents;
      if (files && files.length) {
        lines.length = 0;                       // the listing IS the report
        for (const f of files) lines.push(`${f.name}${f.size ? `  (${fileSize(f.size)})` : ''}`);
      } else {
        // The read-back failed, so this is what we SENT — said plainly, because
        // the two are not the same claim.
        lines.unshift(`Could not read the folder back. Sent: ${uploaded.uploaded.map(u => u.name).join(', ')}.`);
      }
      await chrome.tabs.create({ url: uploaded.folderUrl });
      renderApplyReport(
        status,
        `${uploaded.folderName || currentHostname} on Drive — ${files ? `${files.length} file${files.length === 1 ? '' : 's'}` : 'uploaded'}`,
        lines, 'success');
    } else {
      // Never leave the specialist with nothing. The bundle is produced and
      // downloaded whatever the server did, and the reason is stated rather
      // than swallowed.
      const { bytes, name } = zip;
      const url = URL.createObjectURL(new Blob([bytes], { type: 'application/zip' }));
      const a = document.createElement('a');
      a.href = url; a.download = name;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 30000);

      lines.unshift(`Not uploaded (${uploadErr}) — ${name} downloaded instead.`);
      renderApplyReport(status, 'Handover ready (local)', lines, 'error');
    }
  } catch (e) {
    showNotice(status, String((e && e.message) || e), 'error', 8000);
  } finally {
    btn.disabled = false;
    btn.textContent = label;
  }
});

document.getElementById('closeOutBtn').addEventListener('click', async () => {
  const status = document.getElementById('closeOutStatus');
  showNotice(status, 'Building report…', 'warn', 0);
  try {
    const res = await generateCloseOutReport(currentHostname);
    if (res.fixes === 0) {
      showNotice(status, `No mappings saved for ${currentHostname} yet — add some in the Templates tab first.`, 'error', 4500);
    } else {
      showNotice(status, `Report generated — ${res.fixes} fix(es) across ${res.pages} page(s).`, 'success', 4000);
    }
  } catch (err) {
    showNotice(status, 'Error: ' + err.message, 'error', 4500);
  }
});

// ── Backup / transfer (Export & Import) ─────────────────────────────────────

/**
 * Fill the "Project to export" picker with every site that has saved work.
 *
 * The site in front of you is preselected when it has any, because that is the
 * one being exported nine times out of ten — but the list is deliberately not
 * limited to it. A finished project is often handed over from a tab that is no
 * longer on the client's site.
 */
async function refreshBackupSites() {
  const sel = document.getElementById('exportSiteSelect');
  if (!sel) return;
  const previous = sel.value;
  let sites = [];
  try {
    sites = await U1Store.listSites();
  } catch { /* an unreadable store is reported by the buttons, not the picker */ }

  sel.innerHTML = '';
  if (!sites.length) {
    const opt = document.createElement('option');
    opt.value = '';
    opt.textContent = 'No saved work yet';
    sel.appendChild(opt);
    sel.disabled = true;
    document.getElementById('exportSiteBtn').disabled = true;
    return;
  }
  for (const host of sites) {
    const opt = document.createElement('option');
    opt.value = host;
    opt.textContent = host;
    sel.appendChild(opt);
  }
  sel.disabled = false;
  document.getElementById('exportSiteBtn').disabled = false;
  // Keep an explicit choice across a refresh; otherwise fall back to this site.
  if (previous && sites.includes(previous)) sel.value = previous;
  else if (sites.includes(currentHostname)) sel.value = currentHostname;
}

document.getElementById('exportSiteBtn').addEventListener('click', async () => {
  const status = document.getElementById('backupStatus');
  const host = document.getElementById('exportSiteSelect').value || currentHostname;
  if (!host) {
    showNotice(status, 'Pick a project to export first.', 'error', 4000);
    return;
  }
  try {
    // Per-site, and per-site only: the store filters by hostname and drops the
    // private ("__") keys and the global ones alike, so neither the signed-in
    // session nor another client's bundle URLs can ride inside this file.
    const data = await U1Store.getExportableForSite(host);
    if (!Object.keys(data).length) {
      showNotice(status, `Nothing saved for ${host} yet.`, 'error', 4500);
      return;
    }
    // Same envelope as the all-sites backup, so the existing importer takes it
    // with no changes — it merges, so restoring one project leaves the other
    // sites on the receiving machine untouched. `site` is a label for whoever
    // finds the file later; the importer keys off the data, not off it.
    const payload = {
      __u1helper: true,
      version: 1,
      site: host,
      exportedAt: new Date().toISOString(),
      data,
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `u1-helper-backup-${host.replace(/[^A-Za-z0-9.-]/g, '-')}-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 30000);
    const count = (data[storageKey('mappings', host)] || []).length;
    showNotice(status, `Exported ${host} — ${count} mapping${count !== 1 ? 's' : ''}.`, 'success', 3500);
  } catch (err) {
    showNotice(status, 'Export failed: ' + err.message, 'error', 4500);
  }
});

document.getElementById('exportDataBtn').addEventListener('click', async () => {
  const status = document.getElementById('backupStatus');
  try {
    // The store decides what may leave the machine. It drops every private
    // ("__") key — the close-out render cache, and the signed-in session, which
    // holds a refresh token. A backup file gets emailed and carried between
    // machines, so a credential must never be able to ride along inside one.
    // sanitizeImport() rejects the same prefix on the way back in.
    const all = await U1Store.getExportable();
    const payload = {
      __u1helper: true,
      version: 1,
      exportedAt: new Date().toISOString(),
      data: all,
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `u1-helper-backup-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 30000);
    const sites = Object.keys(all).filter(k => k.startsWith('mappings_')).length;
    showNotice(status, `Exported all data (${sites} site${sites !== 1 ? 's' : ''}).`, 'success', 3500);
  } catch (err) {
    showNotice(status, 'Export failed: ' + err.message, 'error', 4500);
  }
});

document.getElementById('importDataBtn').addEventListener('click', () => {
  const status = document.getElementById('backupStatus');
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'application/json,.json';
  input.addEventListener('change', () => {
    const file = input.files && input.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const parsed = JSON.parse(String(reader.result));
        const raw = (parsed && parsed.data && typeof parsed.data === 'object') ? parsed.data : parsed;
        if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
          throw new Error('Not a valid U1 Studio backup file.');
        }
        // SECURITY: never trust an imported backup — it can silently arm script
        // injection into any site (manualInject_*.jsLink) or store HTML/code that
        // is later rendered or handed to a client. Allow-list keys and schema-check
        // every value; drop anything unrecognised.
        const { data, dropped } = sanitizeImport(raw);
        if (!Object.keys(data).length) throw new Error('Nothing valid to import (all entries were rejected).');
        // Merge into storage (imported keys overwrite matching ones, others kept).
        await U1Store.set(data);
        // Refresh the whole UI for the current tab.
        await loadConfigForm();
        await refreshConfigSkipList();
        updateConfigPreview();
        await loadMappingsList();
        await refreshExportInfo();
        const tab = await getTab();
        if (tab) await refreshSetupTab(tab);
        const siteNames = Object.keys(data)
          .filter(k => k.startsWith('mappings_'))
          .map(k => k.slice('mappings_'.length));
        const sites = siteNames.length;
        // The silent way an import "does not work": the backup's work is
        // filed under a different hostname — member.molina.com against
        // molina.com, or a pre-www-stripping key — and the panel, filtered
        // to the site in front, honestly shows "No mappings yet" right
        // beside a notice that just said the import succeeded. Name the
        // hostnames, and say out loud when none of them is this one.
        const hereToo = siteNames.includes(currentHostname);
        // Every site goes up, not only the one in front of you. U1Store.set's
        // sync hook is scoped to the current hostname — right for a save, wrong
        // for an import, where nine sites out of ten would have landed on this
        // machine alone and the button would have been telling the truth about
        // half of what it did.
        const up = await pushImportedSites(data, status);
        showNotice(status,
          `Imported ${sites} site${sites !== 1 ? 's' : ''}` +
          (sites ? ` (${siteNames.join(', ')})` : '') + '.' +
          (sites && !hereToo
            ? ` None of them is ${currentHostname}, the site in front of you — its list will still say "no mappings". ` +
              `If this is the same client under another address, the Mappings drawer offers to move the work across.`
            : '') +
          (up.sent ? ` ${up.sent} uploaded to the server.` : '') +
          (up.blocked.length ? ` Not uploaded — you are not assigned to ${up.blocked.join(', ')}; ` +
            `that work is on this machine only.` : '') +
          (dropped ? ` (${dropped} unsafe/unknown entr${dropped !== 1 ? 'ies' : 'y'} skipped.)` : ''),
          (up.blocked.length || (sites && !hereToo)) ? 'error' : 'success',
          (up.blocked.length || (sites && !hereToo)) ? 15000 : 6000);
      } catch (err) {
        showNotice(status, 'Import failed: ' + err.message, 'error', 5000);
      }
    };
    reader.readAsText(file);
  });
  input.click();
});

// ─────────────────────────────────────────────────────────────────────────────
//  Navigation listeners — re-detect U1 whenever the active tab changes
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
//  Working on a site whose policy blocks U1
//
//  A site can tell browsers "only run scripts from my own domain". U1 lives on
//  another domain, so it never loads and there is nothing to map. This lifts
//  that restriction FOR THIS BROWSER ONLY, so the specialist can do the work.
//
//  It fixes nothing for the site's visitors, and it is not a substitute for the
//  real remedies (host U1 on the site's own domain, or have the site allow ours)
//  — the notice above the toggle says so, and this comment exists so nobody
//  later mistakes it for one.
//
//  Deliberately session rules, not dynamic ones: session rules die with the
//  browser, so a forgotten toggle cannot outlive the day's work. It is also
//  cleared when leaving the site and when the panel closes.
// ─────────────────────────────────────────────────────────────────────────────

// DNR rule ids must be positive integers and unique among session rules. One
// per host, so toggling the same site twice replaces rather than stacks.
//
// Was a hash of the hostname reduced mod 900000 — two different hostnames can
// hash to the same id, and when they do, toggling the bypass OFF for one site
// silently removes it (or the reverse: toggling it ON for one silently drops
// the CSP of an unrelated site sharing the id, with no way to notice). An
// in-memory table can't collide: each host gets the next free id, once, for
// as long as this panel session lives — which is exactly as long as a session
// DNR rule can live anyway.
const cspRuleIds = new Map();
let cspRuleIdNext = 10000;
function cspRuleIdFor(host) {
  if (!cspRuleIds.has(host)) cspRuleIds.set(host, cspRuleIdNext++);
  return cspRuleIds.get(host);
}

async function cspBypassActive(host) {
  if (!host || host === 'unknown') return false;
  try {
    const rules = await chrome.declarativeNetRequest.getSessionRules();
    return rules.some(r => r.id === cspRuleIdFor(host));
  } catch { return false; }
}

// Returns { ok } or { err } — the caller shows the real reason rather than a
// checkbox that silently does nothing.
async function setCspBypass(host, on) {
  const id = cspRuleIdFor(host);
  try {
    await chrome.declarativeNetRequest.updateSessionRules({
      removeRuleIds: [id],
      addRules: on ? [{
        id,
        priority: 2,
        action: {
          type: 'modifyHeaders',
          responseHeaders: [
            { header: 'content-security-policy', operation: 'remove' },
            { header: 'content-security-policy-report-only', operation: 'remove' },
          ],
        },
        // main_frame and sub_frame only: the policy that blocks U1 is the one
        // delivered with the document. Stripping it from every asset request
        // would be a wider hole for no extra benefit.
        condition: { urlFilter: `||${host}`, resourceTypes: ['main_frame', 'sub_frame'] },
      }] : [],
    });
    return { ok: true };
  } catch (e) {
    return { err: e?.message || String(e) };
  }
}

// Take every one of ours back down. Called when the panel closes.
async function clearAllCspBypasses() {
  try {
    const rules = await chrome.declarativeNetRequest.getSessionRules();
    const ours = rules.filter(r => r.id >= 10000 && r.id < 910000).map(r => r.id);
    if (ours.length) await chrome.declarativeNetRequest.updateSessionRules({ removeRuleIds: ours });
  } catch {}
}

document.getElementById('cspBypassToggle')?.addEventListener('change', async (e) => {
  const on = e.target.checked;
  const status = document.getElementById('cspBypassStatus');
  const host = currentHostname;
  const res = await setCspBypass(host, on);
  if (res.err) {
    e.target.checked = !on;
    showNotice(status,
      `Could not change it: ${res.err}. If this says permissions, the extension needs ` +
      `"declarativeNetRequestWithHostAccess" adding to its manifest.`, 'error', 12000);
    return;
  }
  if (!on) { showNotice(status, `Restriction restored for ${host}.`, 'info', 4000); return; }
  // Turning the bypass on IS the instruction "make U1 load here" — so arm the
  // persistent injection now, from the links already in the form. Without
  // this the reload below came back with CSP gone and nothing injected, and
  // the specialist had to press Inject a second time — or, worse, had never
  // been able to persist it at all, because a blocked injection never reaches
  // the line that saves manualInject.
  const SAFE = (v) => typeof v === 'string' && /^https?:\/\//i.test(v.trim());
  const cssLink = (document.getElementById('cssLink')?.value || '').trim();
  const jsLink = (document.getElementById('jsLink')?.value || '').trim();
  if (SAFE(cssLink) && SAFE(jsLink)) {
    await U1Store.set({ [`manualInject_${host}`]: { cssLink, jsLink } });
  }
  // The policy arrives with the page, so removing the header only counts from
  // the next load. Saying "on" without saying that reads as broken.
  showNotice(status, `Off for ${host} in this browser. Reloading the page so it takes effect…`, 'success', 6000);
  try {
    const tab = await getTab();
    if (tab?.id) await chrome.tabs.reload(tab.id);
  } catch {}
});

// Leaving the site puts it back — the toggle is for the page in front of you,
// not a standing exemption for a client's domain.
async function releaseCspBypassFor(host) {
  if (!host || host === 'unknown') return;
  if (await cspBypassActive(host)) await setCspBypass(host, false);
}

window.addEventListener('pagehide', () => { clearAllCspBypasses(); });

// Backstop for the CSP-bypass safety net in background.js: a long-lived port
// that stays connected exactly as long as this panel does. Its onDisconnect
// firing is how the service worker notices the panel is gone even when
// `pagehide` above did not run (a crash, a forced close) — see the comment on
// chrome.runtime.onConnect in background.js for why that matters here.
try { chrome.runtime.connect({ name: 'panelKeepAlive' }); } catch {}

/**
 * Say why the panel is showing a site that is not the tab in front.
 *
 * Without this the hold is invisible and reads as the panel being stuck: you
 * are looking at one site and the mappings list names another. One line, in
 * the place a tab change would otherwise have redrawn.
 */
// Where the panel should go once the run has finished letting go of it. Set
// only by pressing the button in the hold notice — the panel never decides on
// its own that you have moved on.
let sweepLeaveFor = null;

function noteSweepHoldsPanel(tab) {
  const host = document.getElementById('sweepHoldsPanel');
  if (!host) return;
  const here = tab && isInjectable(tab) ? getHostname(tab) : '';
  // Looking at the scan's own tab is the ordinary case and needs no notice.
  if (!here || here === currentHostname) { host.style.display = 'none'; return; }
  host.style.display = '';
  if (sweepLeaveFor) {
    host.textContent = `Finishing this section, then moving to ${sweepLeaveFor}. ` +
      `Everything read so far is saved.`;
    return;
  }
  // Holding the panel is right for "I glanced at another tab" and wrong for "I
  // have moved on to a different site" — and from inside the panel those two
  // are the same event. It cannot be told apart by watching, so it is asked.
  //
  // The hold has no time limit: a twenty-screen run is twenty minutes, and for
  // twenty minutes the mappings list, the config form and the export tab would
  // all be about a site you are no longer on, with no way out but waiting or
  // pressing Stop and knowing that is what Stop was for. This is the way out,
  // named after where it goes.
  // A single-element scan is ONE model call — ten to thirty seconds, not
  // twenty minutes — so it gets the same hold and no escape hatch: the way
  // out is to wait for it, and offering "ends the scan" for something about
  // to finish on its own would throw away a call already paid for. The
  // leave button also drives aiSweep.abort, which this route does not read.
  if (aiScanHold && !aiSweep.running) {
    host.textContent =
      `Scanning ${currentHostname} — the panel stays with it until the answer lands. ` +
      `Nothing here is about ${here} yet.`;
    return;
  }
  // A bulk build or an element scan: same hold, but the leave button below
  // drives aiSweep.abort, which these runs do not read — offering it would be
  // a button that does nothing. Their own Stop button is the way out.
  if ((aiBulk.running || elemScanRunning) && !aiSweep.running) {
    host.textContent =
      `Working on ${currentHostname} — the panel stays with the run until it finishes. ` +
      `Nothing here is about ${here} yet. The run's own ■ Stop is the way out.`;
    return;
  }
  host.innerHTML =
    `Still scanning <strong>${escapeHtml(currentHostname)}</strong> — this panel stays with ` +
    `the scan until it finishes. Nothing here is about ${escapeHtml(here)}.` +
    `<button class="btn-outline btn-xs" data-leave-scan="${escapeHtml(here)}">` +
    `Work on ${escapeHtml(here)} instead — ends the scan</button>`;
}

function clearSweepHoldsPanel() {
  const host = document.getElementById('sweepHoldsPanel');
  if (host) { host.style.display = 'none'; host.innerHTML = ''; }
}

// "I have actually moved on." The scan finishes the section it is on — that
// call is paid for either way, and abandoning it mid-flight would waste it —
// and the panel follows once it lets go.
document.addEventListener('click', async (e) => {
  const btn = e.target.closest('[data-leave-scan]');
  if (!btn) return;
  sweepLeaveFor = btn.dataset.leaveScan;
  aiSweep.abort = true;
  const stop = document.getElementById('sweepStopBtn');
  if (stop) { stop.disabled = true; stop.textContent = 'Stopping after this section…'; }
  noteSweepHoldsPanel(await getTab());
});

/**
 * Follow a switch that was asked for while the run held the panel.
 *
 * Called from the end of a run's finally, after aiSweep.running is false, so
 * the hold no longer applies and onTabChanged does its ordinary work.
 */
async function followPendingSiteSwitch() {
  if (!sweepLeaveFor) return;
  sweepLeaveFor = null;
  clearSweepHoldsPanel();
  // The survey on screen belongs to the site being left. sweepIsPinnedAndAlive
  // would keep it — right for a glance at another tab, wrong here, where the
  // answer to "am I still working on that site" was an explicit no. It is saved
  // and comes back on its own when that site is opened again.
  resetAiWorkspace();
  const t = await getTab();
  if (t) await onTabChanged(t);
}

async function onTabChanged(tab) {
  // Moving to a non-web tab used to leave currentHostname pointing at the site
  // you were last on, with nothing on screen saying so — save now and it lands
  // on the previous site.
  // ── A running scan owns the panel ────────────────────────────────────────
  //
  // The background camera made "start a scan and carry on working" possible;
  // this is what made it not work anyway. Reported as: started a single-screen
  // scan, switched tabs, and it reset — it had not really scanned.
  //
  // Everything below re-points the panel at whatever tab is IN FRONT. The
  // single most damaging line is the quietest one: currentHostname is
  // reassigned, and sweepStoreKey() defaults to currentHostname — so from that
  // moment every save of the RUNNING scan was written under the other site's
  // key and pushed to the other site on the server. Then the cascade below
  // pulled that other site's own survey down over the top of it. Come back and
  // the scan is gone, and its sections are unread, because that is genuinely
  // what is now stored under this site's name.
  //
  // A scan is pinned to one tab. Which tab you happen to be LOOKING at is not
  // information about it, so it is not allowed to change anything about it —
  // not the site the panel is filed under, not the licence check, not the
  // mappings list, and not the survey on screen. The panel stays on the run
  // until the run ends, and says which site it is still showing.
  if (aiSweep.running && await sweepIsPinnedAndAlive()) {
    noteSweepHoldsPanel(tab);
    return;
  }
  // The same rule for a single-element scan. It is one model call rather than
  // a run of them, but everything below would still re-point the panel and
  // clear the workspace the answer is about to land in.
  if (aiScanHold) {
    const alive = await chrome.tabs.get(aiScanHold.tabId).catch(() => null);
    if (alive) { noteSweepHoldsPanel(tab); return; }
    aiScanHold = null;
  }
  // And for a bulk build. It is the same shape of run as a sweep — a loop of
  // model calls writing cards into the workspace — and re-pointing the panel
  // mid-loop parked that workspace WHILE prepareOne was still appending to
  // it: cards landed in an emptied list at indexes the DOM no longer agreed
  // with, currentHostname moved, and the approve that followed would have
  // filed the whole batch under whichever site happened to be in front.
  if (aiBulk.running && await bulkTab()) {
    noteSweepHoldsPanel(tab);
    return;
  }
  // An element scan drives the pinned page mapping by mapping; everything
  // below would re-point the panel and file its results under the front
  // site's name. The flag always clears in the scan's own finally.
  if (elemScanRunning) {
    noteSweepHoldsPanel(tab);
    return;
  }
  clearSweepHoldsPanel();

  if (!tab || !isInjectable(tab)) { borrowedHost = true; renderHostWarning(); return; }
  borrowedHost = false;
  renderHostWarning();
  const newHostname = getHostname(tab);
  // Session-only detection must not follow you to the next site.
  if (newHostname !== currentHostname) detectedSkipLinks = [];
  const hostnameChanged = newHostname !== currentHostname;
  const previousHostname = currentHostname;

  currentHostname = newHostname;
  document.querySelectorAll('#mappingsHostname, #exportHostname, #closeOutHostname').forEach(el => {
    el.textContent = currentHostname;
  });

  // Assignment is per site, so moving to a different host has to be re-checked
  // — otherwise one assigned site would unlock every tab in the window.
  if (hostnameChanged && !(await enforceLicence(currentHostname))) return;

  if (hostnameChanged) {
    // Scan results are selectors from the site you just left; ON SCREEN over
    // another site they invite approving one client's components into another
    // client's file — so the view comes down. But the STATE stays: throwing
    // away a survey or a half-approved batch because you glanced at another
    // tab is the worse of the two failures, and every write path already
    // refuses to save across sites. Coming back to the workspace's own site
    // puts it back where it stood.
    // Park now — the cascade below (pull, restoreSweep, the config form) has
    // to run against EMPTY live slots or the new site's own stored survey
    // cannot restore over them. Unparking happens at the END of this block,
    // once nothing is left that would paint over the restored view.
    if (!(await sweepIsPinnedAndAlive()) && aiWorkspaceHost && aiWorkspaceHost !== newHostname) {
      parkAiWorkspace();
    }
    // And put the site you just left back the way you found it — but only
    // when you have actually LEFT it. A glance at another tab is not leaving:
    // the whole point of the pinned-run work is that switching tabs changes
    // nothing about the site being worked on, and dropping the CSP bypass on
    // every glance is how "the links refuse to load" came back each time the
    // specialist looked at the CRM. While a tab with that site is still open
    // in the browser, the bypass stays; closing its last tab, the explicit
    // toggle, or closing the panel still put the protection back.
    let stillOpen = false;
    try {
      const allTabs = await chrome.tabs.query({});
      stillOpen = allTabs.some((t) => {
        try { return getHostname(t) === previousHostname; } catch { return false; }
      });
    } catch {}
    if (!stillOpen) await releaseCspBypassFor(previousHostname);
    const t = document.getElementById('cspBypassToggle');
    if (t) t.checked = false;
    const row = document.getElementById('cspBypassRow');
    if (row) row.style.display = 'none';
    const cs = document.getElementById('cspBypassStatus');
    if (cs) cs.style.display = 'none';
    await loadConfigForm();
    await refreshConfigSkipList();
    updateConfigPreview();
    U1Sync.forget();          // one site's versions must not vouch for another's
    const pulled = await pullSiteFromServer();
    await loadMappingsList();
    await refreshExportInfo();
    reportSyncState(pulled);
    // The workspace was just cleared for the new site — so this is the new
    // site's own last survey coming back, not the previous one following you.
    if (!pulled.ok || !pulled.sweep) await restoreSweep();
    // LAST. Coming back to the site whose workspace is parked puts it back on
    // screen — and it has to happen after everything above, because
    // restoreSweep and the panel repaints each set a stage of their own and
    // would paint straight over a view restored before them. That is what
    // made "I changed tab and it did not come back" survive the first fix.
    unparkAiWorkspaceFor(newHostname);
  }

  // Same host, different page: the mappings list has "is it on THIS page"
  // baked into it — the drawer's On-this-page count and the Scan tab's
  // saved-mappings status dots are both computed at render time from what
  // the current page holds. loadMappingsList() only ran in the
  // hostnameChanged branch above, so walking to another page of the same
  // site (including via a mapping's own "go there" link) left both showing
  // the PREVIOUS page's answer — a dot stayed red on the very page the
  // widget lives on. Not awaited, same as renderExistingFixes below: one
  // storage read and one presence probe, and nothing else here waits on it.
  if (!hostnameChanged) loadMappingsList();

  // Run detection immediately and again after a short delay to catch async U1 init
  await refreshSetupTab(tab);
  setTimeout(async () => {
    const freshTab = await getTab();
    if (freshTab && freshTab.id === tab.id) await refreshSetupTab(freshTab);
  }, 1800);

  // What the site runs, re-read on EVERY page — including one on the same
  // host, which is the case that matters and the one that was missed.
  //
  // loadMappingsList() lives inside the hostnameChanged branch above, so
  // walking from one page of a site to the next never re-checked. A U1
  // deployment is per PAGE, not per site: tamam.co.il's home page runs a menu,
  // and its Aviation Catering page runs a form, a menu and a carousel. Walking
  // the site is exactly how the full picture is collected, so it has to be the
  // moment this looks again.
  //
  // Not awaited, and cheap: one scripting call that returns nothing when the
  // page ran no fixes. It only draws the offer — nothing is adopted without
  // the button being pressed.
  //
  // Delayed once, because the library's own fixes run as the page settles: at
  // `complete` the recording is often a fraction behind, and an offer that
  // appears empty and fills in a second later reads as the tool missing things.
  renderExistingFixes();
  setTimeout(async () => {
    const freshTab = await getTab();
    if (freshTab && freshTab.id === tab.id) renderExistingFixes();
  }, 2000);
}

// Full page navigation (including regular links and form submissions)
chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
  if (changeInfo.status !== 'complete') return;
  const activeTab = await getTab();
  if (!activeTab || activeTab.id !== tabId) return;
  await onTabChanged(tab);
});

// User switches to a different tab
chrome.tabs.onActivated.addListener(async ({ tabId }) => {
  const tab = await chrome.tabs.get(tabId).catch(() => null);
  if (tab) await onTabChanged(tab);
});

// ─────────────────────────────────────────────────────────────────────────────
//  LICENCE GATE
//
//  Decides whether the tool may be used on the current site, and in what mode.
//  Nothing here ever touches stored mappings — a worker who is signed out,
//  unassigned or expired keeps every byte of their work on this machine.
// ─────────────────────────────────────────────────────────────────────────────

// Controls that create or persist NEW work. Read, report and export controls are
// deliberately absent: an expired licence must still be able to hand over
// finished work and take a backup out.
const READONLY_DISABLED_IDS = [
  'addMappingBtn',      // add a mapping
  'applyTemplateBtn',   // apply a generated fix as a new mapping
  'addSkipLinkBtn',     // add a skip link
  'saveSkipBtn',        // persist skip links
  'importDataBtn',      // overwrite local data from a backup
  // AI mode creates and persists mappings too, and it also spends money on the
  // specialist's API key — both are exactly what an expired licence pauses.
  'aiDiscoverBtn',      // start a paid review
];

// The per-card Approve buttons are built at runtime, so an id list cannot reach
// them — the handler checks this instead.
const isReadonly = () => licenceState.accessLevel === 'readonly';

let licenceState = { accessLevel: 'full', stale: false };

function showGateScreen(id) {
  const gate = document.getElementById('gate');
  gate.style.display = 'flex';
  ['gateLogin', 'gateBlocked', 'gateOffline'].forEach(s => {
    document.getElementById(s).style.display = s === id ? 'block' : 'none';
  });
}

function hideGate() {
  document.getElementById('gate').style.display = 'none';
}

function applyLicenceMode(state) {
  licenceState = state;

  const readonly = state.accessLevel === 'readonly';
  document.getElementById('readonlyBanner').style.display = readonly ? 'block' : 'none';
  document.getElementById('offlineBanner').style.display = state.stale ? 'block' : 'none';

  READONLY_DISABLED_IDS.forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.toggle('u1-readonly-off', readonly);
    el.disabled = readonly;
    if (readonly) el.title = 'Licence expired — existing work stays available to view and export.';
  });
}

async function showAccountRow() {
  const client = await U1Auth.getStoredClient();
  const el = document.getElementById('accountEmail');
  if (!el) return;
  const email = client?.email || '';
  el.textContent = email;
  // The header truncates long addresses to fit beside the wordmark, so the full
  // value has to stay recoverable on hover.
  if (email) el.title = email; else el.removeAttribute('title');
}

/**
 * Returns true when the tool may boot. When it returns false the gate is
 * already on screen and the caller must stop.
 */
async function enforceLicence(hostname) {
  const result = await U1Auth.checkSiteAccess(hostname);

  if (result.allowed) {
    hideGate();
    applyLicenceMode(result);
    await showAccountRow();
    return true;
  }

  if (result.reason === 'not_logged_in') {
    showGateScreen('gateLogin');
    return false;
  }
  if (result.reason === 'offline') {
    showGateScreen('gateOffline');
    return false;
  }
  if (result.reason === 'no_site') {
    // Opened on a browser page rather than a real site — nothing to check yet.
    hideGate();
    return true;
  }

  document.getElementById('gateBlockedHost').textContent = hostname;
  document.getElementById('gateRequestWrap').style.display = 'block';
  document.getElementById('gateRequestDone').style.display = 'none';
  showGateScreen('gateBlocked');
  return false;
}

document.getElementById('gateLoginForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const btn = document.getElementById('gateLoginBtn');
  const err = document.getElementById('gateLoginError');
  err.style.display = 'none';
  btn.disabled = true;
  btn.textContent = 'Signing in…';

  try {
    await U1Auth.login(
      document.getElementById('gateEmail').value.trim(),
      document.getElementById('gatePassword').value,
    );
    document.getElementById('gatePassword').value = '';
    await init(); // re-runs the gate, now with credentials
  } catch (e2) {
    err.textContent = e2.message;
    err.style.display = 'block';
  } finally {
    btn.disabled = false;
    btn.textContent = 'Sign in';
  }
});

document.getElementById('gateRequestBtn').addEventListener('click', async () => {
  const btn = document.getElementById('gateRequestBtn');
  const err = document.getElementById('gateBlockedError');
  err.style.display = 'none';
  btn.disabled = true;
  btn.textContent = 'Sending…';

  try {
    await U1Auth.requestAccess(currentHostname, document.getElementById('gateRequestNote').value.trim());
    document.getElementById('gateRequestWrap').style.display = 'none';
    document.getElementById('gateRequestDone').style.display = 'block';
  } catch (e) {
    err.textContent = e.offline
      ? 'Could not reach the server. Try again when you are back online.'
      : 'Could not send the request. Try again.';
    err.style.display = 'block';
  } finally {
    btn.disabled = false;
    btn.textContent = 'Request access';
  }
});

document.getElementById('gateRetryBtn').addEventListener('click', () => init());

// Signing out clears credentials only. Local mappings are the worker's work and
// are never removed — that promise is the whole reason this is a two-line
// handler and not a "clean up" routine.
async function signOut() {
  await U1Auth.logout();
  await init();
}

// Ten seconds, counted down, cancellable. Sign out is one click from every tab
// and sits right beside the email address, so it gets pressed by accident — and
// the cost is re-authenticating from the middle of a piece of work.
let signOutTimer = null;
function stopSignOutCountdown() {
  if (signOutTimer) { clearInterval(signOutTimer); signOutTimer = null; }
  document.getElementById('signOutDialog')?.close();
}
function askSignOut() {
  const dlg = document.getElementById('signOutDialog');
  const out = document.getElementById('signOutCountdown');
  // No <dialog> support: do what was asked rather than trapping them signed in.
  if (!dlg || typeof dlg.showModal !== 'function') { signOut(); return; }
  let left = 10;
  const tick = () => {
    out.textContent = `Signing out in ${left} second${left === 1 ? '' : 's'}.`;
    if (left-- <= 0) { stopSignOutCountdown(); signOut(); }
  };
  tick();
  signOutTimer = setInterval(tick, 1000);
  if (!dlg.open) dlg.showModal();
  document.getElementById('signOutCancelBtn')?.focus();
}
document.getElementById('signOutCancelBtn')?.addEventListener('click', stopSignOutCountdown);
document.getElementById('signOutNowBtn')?.addEventListener('click', () => {
  stopSignOutCountdown();
  signOut();
});
// Escape closes a <dialog> natively. The interval has to die with it, or the
// countdown runs on and signs out from behind a dialog nobody can see.
document.getElementById('signOutDialog')?.addEventListener('close', () => {
  if (signOutTimer) { clearInterval(signOutTimer); signOutTimer = null; }
});

document.getElementById('gateSignOutBlocked').addEventListener('click', askSignOut);
document.getElementById('signOutBtn').addEventListener('click', askSignOut);

// The session closes after a spell of inactivity, and the server only learns
// the worker is still here when the panel calls it. Mapping fixes on one page
// makes no calls at all, so without this a session could lapse while someone is
// visibly working. U1Auth.touch() throttles itself, so this is cheap.
['click', 'keydown'].forEach((evt) => {
  document.addEventListener(evt, () => { U1Auth.touch().catch(() => {}); }, { passive: true });
});

// ─────────────────────────────────────────────────────────────────────────────
//  Boot
// ─────────────────────────────────────────────────────────────────────────────

init();
